void traverse_dom(int **states, int num_states, struct FSA *fsa, int last_state) {
    int *new_states = malloc((num_states + 1) * sizeof(int));
    if (new_states == NULL) return NULL;

    new_states[0] = last_state;
    for (int i = 0; i < num_states; ++i) {
        if (match_selector(fsstates[i])) {
            new_states[i + 1] = fsa->transitions[fsstates[i]].next;
        } else {
            new_states[i + 1] = -1;
        }
    }

    if (new_states[last_state] != -1) {
        traverse_dom(new_states, last_state + 1, fsa, new_states[last_state]);
    }

    states->next = new_states;
}

