using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class StoredProcedureExecutor
{
    private readonly Dictionary<string, List<InputParameter>> _procedureCache = new();

    public async Task<List<MyCustomObject>> ExecuteStoredProcedureAsync(SqlConnection connection, List<InputParameter> inputParameters, string storedProcedureName)
    {
        if (!inputParameters.Any())
            throw new ArgumentException("At least one input parameter is required");

        var cacheKey = $"{storedProcedureName}:{string.Join(",", inputParameters.Select(ip => ip.Name + ":" + ip.Value))}";
        if (_procedureCache.TryGetValue(cacheKey, out var cachedInputParameters) && cachedInputParameters.SequenceEqual(inputParameters))
            return (List<MyCustomObject>)_procedureCache[cacheKey];

        _procedureCache.Add(cacheKey, new List<InputParameter>(inputParameters));

        using var command = new SqlCommand(storedProcedureName, connection);
        command.CommandType = System.Data.CommandType.StoredProcedure;

        foreach (var inputParameter in inputParameters)
        {
            command.Parameters.AddWithValue(inputParameter.Name, inputParameter.Value);
        }

        using var reader = await command.ExecuteReaderAsync();
        List<MyCustomObject> result = new();

        while (await reader.ReadAsync())
        {
            var obj = new MyCustomObject();
            for (var i = 0; i < reader.FieldCount; i++)
            {
                switch (reader.GetFieldType(i).Name)
                {
                    case "Int32":
                        obj.Property1 = reader.GetInt32(i);
                        break;
                    case "String":
                        obj.Property2 = reader.GetString(i);
                        break;
                    // Add more property mapping based on the actual data types in your custom objects
                    default:
                        throw new ArgumentException($"Unsupported data type {reader.GetFieldType(i).Name}");
                }
            }

            result.Add(obj);
        }

        await reader.CloseAsync();

        return result;
    }
}

public class InputParameter
{
    public string Name { get; set; }
    public object Value { get; set; }
}

public class MyCustomObject
{
    public int Property1 { get; set; }
    public string Property2 { get; set; }
}
