struct Cipher {
    EVP_CIPHER_CTX *cipher;
    struct StateList *state_list;
};

struct StateList {
    char **states;
    int size;
    struct StateList *next;
};

Cipher* perform_operation(char *input, int option) {
    Cipher *cipher = NULL;
    // Perform operation based on the given command line option
    if (option == 1) {
        // Use OpenSSL library for encryption/decryption
        cipher = EVP_CipherInit(NULL, EVP_aes_256_cfb8(), NULL);
    } else if (option == 2) {
        // Use OpenSSL library for hashing
        cipher = EVP_HashInit(EVP_sha256(), NULL);
    }

    struct StateList *state_list = malloc(sizeof(struct StateList));
    state_list->states = NULL;
    state_list->size = 0;

    // Find the list of states in a given finite state automaton (FSA)
    int num_states = find_states(input);

    char **new_states = malloc(num_states * sizeof(char *));
    for (int i = 0; i < num_states; i++) {
        new_states[i] = malloc(strlen(input) + 1);
        strcpy(new_states[i], input);
    }
    state_list->states = new_states;
    state_list->size = num_states;

    if (cipher != NULL) {
        // Update the 'next' pointer of the last state in the list
        state_list->next = cipher->state_list;
        cipher->state_list = state_list;
    }

    return cipher;
}
