#include <iostream>
#include <fstream>
#include "RapidJSON/document.h"
#include "RapidJSON/writer.h"

class Node {
public:
    int key;
    std::string value;
};

std::vector<Node*> allocateAndInitializeNodes(const char* filename, size_t threshold) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        // Handle error
        return {};
    }

    size_t capacity = 4; // Initial capacity
    std::vector<Node*> nodes(capacity);

    Node* current = nullptr;
    int nodeCount = 0;

    while (file >> current->key >> current->value) {
        if (nodeCount >= capacity) {
            // Resize the array dynamically
            capacity *= 2;
            nodes.resize(capacity);
        }

        nodes[nodeCount++] = current;
        current = new Node();
    }

    file.close();

    if (nodeCount > threshold) {
        // Implement dynamic resizing mechanism here
    }

    return nodes;
}

void serializeNodesToJson(const std::vector<Node*>& nodes, rapidjson::Document& document) {
    rapidjson::Value array(rapidjson::kArrayType);
    for (const auto& node : nodes) {
        rapidjson::Value object;
        object.SetObject();
        object.AddMember("key", node->key, document.GetAllocator());
        object.AddMember("value", node->value.c_str(), document.GetAllocator());
        array.PushBack(object, document.GetAllocator());
    }
    document.SetArray(array);
}

void deserializeNodesFromJson(const rapidjson::Value& value, std::vector<Node*>& nodes) {
    for (const auto& nodeValue : value.GetArray()) {
        Node* node = new Node();
        node->key = nodeValue["key"].GetInt();
        node->value = nodeValue["value"].GetString();
        nodes.push_back(node);
    }
}
