import java.io.*;
import java.net.*;
import java.util.*;

public class GameCharacter {

    private Socket socket;
    private DataInputStream in;
    private DataOutputStream out;
    private boolean isConnected = false;
    private boolean isAttackCooldown = true;
    private Random random = new Random();
    private int attackType;

    public void establishConnection() throws IOException {
        try {
            socket = new Socket("remoteAddress", 12345);
            in = new DataInputStream(socket.getInputStream());
            out = new DataOutputStream(socket.getOutputStream());
            isConnected = true;
            setStateChangeListener();
        } catch (UnknownHostException e) {
            System.out.println("Unknown host");
        } catch (IOException e) {
            System.out.println("Connection failed");
        }
    }

    public void closeConnection() throws IOException {
        if (isConnected) {
            in.close();
            out.close();
            socket.close();
            isConnected = false;
        }
    }

    private void setStateChangeListener() {
        Thread thread = new Thread(() -> {
            try {
                while (isConnected) {
                    int state = in.readInt();
                    switch (state) {
                        case 0:
                            if (!isAttackCooldown) {
                                isAttackCooldown = true;
                                attackType = random.nextInt(2);
                                System.out.println("Selected attack: " + attackType);
                            }
                            break;
                        case 1:
                            if (isAttackCooldown) {
                                isAttackCooldown = false;
                            }
                            Thread.sleep(9000); // 9 seconds cooldown
                            break;
                    }
                }
            } catch (IOException e) {
                System.out.println("Connection closed");
            } catch (InterruptedException e) {
                System.out.println("Thread interrupted");
            }
        });
        thread.start();
    }

    public void selectAttack() throws IOException {
        if (!isAttackCooldown) {
            out.writeInt(0); // send attack selection request
        }
    }
