using UnityEngine;

public class CustomRandomGenerator
{
    private Random _random;
    private bool _isSeeded = false;
    private int? _seed;

    public CustomRandomGenerator(int? seed = null)
    {
        _seed = seed;
        if (_seed != null)
        {
            _isSeeded = true;
            UnityEngine.Random.Seed(_seed.Value);
        }
    }

    public float CustomRange(float min, float max, bool isExclusive, bool seeded = false, int? customSeed = null)
    {
        if (min > max && !isExclusive)
            throw new InvalidOperationException("Invalid range");

        if (isExclusive)
        {
            return min + UnityEngine.Random.Range(0f, max - min);
        }
        else
        {
            return min + UnityEngine.Random.Range(0f, max - min + 1f);
        }
    }

    public int CustomRange(int min, int max, bool isExclusive, bool seeded = false, int? customSeed = null)
    {
        if (min > max && !isExclusive)
            throw new InvalidOperationException("Invalid range");

        if (isExclusive)
        {
            return UnityEngine.Random.Range(min + 1, max);
        }
        else
        {
            return min + UnityEngine.Random.Range(0, max - min + 1);
        }
    }

    public override string ToString()
    {
        return $"Random Generator: {(_isSeeded ? "Seeded" : "Unseeded")}, Seed: {_seed}";
    }
}
