import os
import logging
from collections import defaultdict

logging.basicConfig(level=logging.INFO)

class FileProcessor:
    def __init__(self, directory_path, exclude_patterns):
        self.directory_path = directory_path
        self.exclude_patterns = [p for p in (pattern.strip() for pattern in exclude_patterns.split(',')) if p]
        self.file_stats = defaultdict(lambda: {'lines': 0, 'words': 0, 'chars': 0})

    def process_files(self):
        for root, dirs, files in os.walk(self.directory_path):
            for file in files:
                file_path = os.path.join(root, file)
                if any(pattern in file_path or pattern in os.path.splitext(file)[1] for pattern in self.exclude_patterns):
                    continue
                try:
                    with open(file_path, 'r') as f:
                        content = f.read()
                        self.file_stats[os.path.splitext(file)[1].lower()].update({'lines': content.count('\n') + 1,
                                                                                       'words': len(content.split()),
                                                                                       'chars': len(content)})
                except (FileNotFoundError, PermissionError):
                    logging.error(f"Failed to read file {file_path}. Skipping...")
                except Exception as e:
                    logging.error(f"An error occurred while processing file {file_path}: {str(e)}")

    def summarize_stats(self):
        for file_type, stats in self.file_stats.items():
            print(f"File type: {file_type}")
            print(f"Lines: {stats['lines']}")
            print(f"Words: {stats['words']}")
            print(f"Characters: {stats['chars']}")
            print()

    def export_stats(self):
        with open('file_stats.csv', 'w') as f:
            f.write("File Type, Lines, Words, Characters\n")
            for file_type, stats in self.file_stats.items():
                f.write(f"{file_type},{stats['lines']},{stats['words']},{stats['chars']}\n")

def main(directory_path='.', exclude_patterns=''):
    processor = FileProcessor(directory_path, exclude_patterns)
    processor.process_files()
    processor.summarize_stats()
    processor.export_stats()

if __name__ == '__main__':
    main()

