import os
import importlib.util
import json
from typing import Dict, List

class ProtocolLoader:
    def __init__(self, protocol_dir: str):
        self.protocol_dir = protocol_dir
        self.cache = {}

    def load_protocol(self, name: str) -> Dict:
        if name not in self.cache:
            try:
                spec = importlib.util.spec_from_file_location(name, f"{self.protocol_dir}/{name}.py")
                implementation_class = spec.loader.exec_module()
                with open(f"{self.protocol_dir}/{name}_config.json") as config_file:
                    config = json.load(config_file)
                protocol_info = {
                    "name": name,
                    "implementation_class": implementation_class,
                    "description": config.get("description", ""),
                    "supported_features": config.get("features", [])
                }
                self.cache[name] = protocol_info
            except FileNotFoundError:
                raise ValueError(f"Protocol '{name}' not found")
            except ImportError as e:
                raise ImportError(f"Error loading protocol '{name}': {e}")
        return self.cache.get(name)
