```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>

#define MAX_HOSTNAME_LENGTH 256
#define MAX_DNS_SERVERS 10
#define DNS_QUERY_TIMEOUT 5000 // in milliseconds

typedef struct {
    char hostname[MAX_HOSTNAME_LENGTH];
    char ip_address[INET6_ADDRSTRLEN];
} IpAddress;

typedef enum {
    DNS_RESOLUTION_SUCCESS,
    DNS_RESOLUTION_FAILURE,
    DNS_RESOLUTION_TIMEOUT,
} DnsResolutionStatus;

DnsResolutionStatus dns_resolve(const char* hostname, u_char** ip_addresses, int* ip_addresses_count) {
    // Initialize the list of DNS servers and their priority
    static const char* dns_servers[] = {"8.8.8.8", "1.1.1.1"};
    static int dns_servers_priority[] = {2, 1};
    int num_dns_servers = sizeof(dns_servers) / sizeof(dns_servers[0]);

    // Initialize the DNS query cache
    static const IpAddress* ip_address_cache = NULL;
    int cache_size = 0;

    for(int i = 0; i < num_dns_servers; i++) {
        // Perform DNS query with the current server
        struct sockaddr_in server_addr;
        inet_pton(AF_INET, dns_servers[i], &server_addr.sin_addr);
        server_addr.sin_family = AF_INET;

        int sock = socket(AF_INET, SOCK_DGRAM, 0);
        if(sock < 0) {
            return DNS_RESOLUTION_FAILURE;
        }

        setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &socklen_t(1), sizeof(socklen_t));

        struct timeval timeout;
        timeout.tv_sec = 0;
        timeout.tv_usec = DNS_QUERY_TIMEOUT;
        setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout));

        char query_buffer[256];
        sprintf(query_buffer, "%s IN A", hostname);
        sendto(sock, query_buffer, strlen(query_buffer), 0, (struct sockaddr*)&server_addr, sizeof(server_addr));

        int bytes_received = recvfrom(sock, query_buffer, 256, 0, NULL, NULL);

        if(bytes_received < 0) {
            return DNS_RESOLUTION_FAILURE;
        }

        close(sock);

        // Process the received IP address
        char* ip_address_str = query_buffer + strlen(query_buffer) - bytes_received;
        *ip_addresses_count += 1;
        *ip_addresses = realloc(*ip_addresses, (*ip_addresses_count) * sizeof(IpAddress));
        strcpy((*ip_addresses)[*ip_addresses_count-1].hostname, hostname);
        strcpy((*ip_addresses)[*ip_addresses_count-1].ip_address, ip_address_str);

        // Log the DNS query attempt and its outcome
        printf("Resolved %s to %s\n", hostname, ip_address_str);
    }

    return DNS_RESOLUTION_SUCCESS;
}

int main() {
    char hostname[] = "example.com";
    u_char* ip_addresses = NULL;
    int ip_addresses_count = 0;

    DnsResolutionStatus status = dns_resolve(hostname, &ip_addresses, &ip_addresses_count);

    if(status == DNS_RESOLUTION_SUCCESS) {
        for(int i = 0; i < ip_addresses_count; i++) {
            printf("Resolved %s to %s\n", hostname, ip_addresses[i].hostname);
        }
    } else {
        printf("DNS resolution failed with status code %d\n", status);
    }

    free(ip_addresses);
    return 0;
}
