<?php

function generateRandomString($length, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
    if (!$length) return '';
    $chars = str_split($charset);
    shuffle($chars);
    return implode('', array_slice($chars, 0, $length));
}

function hashPassword($password, $algo = 'bcrypt', $saltLength = 16) {
    if (!in_array($algo, ['bcrypt', 'argon2id'])) throw new Exception("Invalid algorithm");
    if (!$password) return '';

    // Generate salt
    $salt = generateRandomString($saltLength);

    // Hash password with salt
    $hashedPassword = password_hash("$password$salt", $algo);

    // Store salt along with hashed password
    $storedHashedPassword = "$hashedPassword|$salt";

    return $storedHashedPassword;
}

function verifyPassword($inputPassword, $storedHashedPassword) {
    list($hashedPassword, $salt) = explode('|', $storedHashedPassword);
    if (!$inputPassword || !$storedHashedPassword) return false;

    // Verify password
    if (!password_verify("$inputPassword$salt", $hashedPassword)) return false;

    return true;
}

// Session management
session_start();

function storeToken($token, $expiration = 3600) {
    $_SESSION['token'] = $token;
    $_SESSION['expiration'] = time() + $expiration;
}

function getToken() {
    if (!isset($_SESSION['token'])) throw new Exception("No token found");

    // Check token expiration
    if (time() > $_SESSION['expiration']) {
        session_destroy();
        throw new Exception("Token expired");
    }

    return $_SESSION['token'];
}

function storePassword($password, $expiration = 3600) {
    $hashedPassword = hashPassword($password);
    $_SESSION['password'] = $hashedPassword;
    $_SESSION['expiration'] = time() + $expiration;
}

function getPassword() {
    if (!isset($_SESSION['password'])) throw new Exception("No password found");

    // Check password expiration
    if (time() > $_SESSION['expiration']) {
        session_destroy();
        throw new Exception("Password expired");
    }

    return $_SESSION['password'];
}

// Example usage
