const fs = require('fs');
const path = require('path');
const { EventEmitter } = require('events');

class FileLoader extends EventEmitter {
  constructor() {
    super();
    this.filesToLoad = [];
    this.loadQueue = [];
    this.loadedFiles = {};
    this.errorHandler = (error) => {
      console.error(`Error loading file: ${error.message}`);
      process.exit(1);
    };
  }

  addFile(file) {
    this.filesToLoad.push(file);
  }

  loadFiles() {
    if (!this.loadQueue.length && !this.filesToLoad.length) return;
    const loadNext = () => {
      if (this.loadQueue.length === 0) {
        if (this.filesToLoad.length > 0) {
          this.loadNextFile();
        } else {
          this.emit('filesLoaded');
        }
      }
    };
    const file = this.loadQueue.shift();
    fs.readFile(file, 'utf8', (err, code) => {
      if (err) {
        this.errorHandler(err);
      } else {
        try {
          eval(code); // execute the loaded JavaScript
          this.loadedFiles[file] = true;
        } catch (error) {
          this.errorHandler(error);
        }
      }
      loadNext();
    });
  }

  loadNextFile() {
    const file = this.filesToLoad.shift();
    if (!file) return;
    this.loadQueue.push(file);
    this.emit('fileLoaded', file);
  }

  checkCircularDependencies(file) {
    if (this.loadedFiles[file]) return false; // already loaded, no circular dependency
    for (const loadedFile of Object.keys(this.loadedFiles)) {
      const loadedFileRelative = path.relative(path.dirname(file), loadedFile);
      if (!loadedFileRelative || !loadedFile.includes(loadedFileRelative)) continue;
      this.errorHandler(new Error(`Circular dependency detected: ${file} -> ${loadedFile}`));
    }
  }

  loadAllFiles() {
    this.filesToLoad.forEach((file) => {
      this.addFile(file);
    });
    this.loadFiles();
  }
}

module.exports = FileLoader;
