```csharp
using System;
using System.Threading;

public enum RangeType { Closed, Open, HalfOpen }

public delegate void SeedCallback(int seed)

public class AdvancedRandomGenerator : IAdvancedRandomGenerator
{
    private Random _random;
    private readonly object _syncLock = new object();
    private int? _seed;
    private bool _isSeeded;

    public AdvancedRandomGenerator()
    {
        _random = new Random();
        _seed = null;
        _isSeeded = false;
    }

    public float CustomRange(float min, float max, RangeType rangeType, bool seeded, int? seed, SeedCallback? callback)
    {
        if (!ValidateInput(min, max))
            throw new ArgumentException("Invalid range. Min must be less than or equal to Max.");

        if (seeded && _isSeeded && _seed == seed)
            return GenerateRandomFloat(min, max, rangeType);

        if (seeded)
        {
            _seed = seed;
            _random.Seed((int)seed);
            _isSeeded = true;

            if (callback != null)
                callback.Invoke((int)seed);
        }
        else
        {
            _seed = null;
            _isSeeded = false;
        }

        return GenerateRandomFloat(min, max, rangeType);
    }

    public int CustomRange(int min, int max, RangeType rangeType, bool seeded, int? seed, SeedCallback? callback)
    {
        if (!ValidateInput(min, max))
            throw new ArgumentException("Invalid range. Min must be less than or equal to Max.");

        if (seeded && _isSeeded && _seed == seed)
            return GenerateRandomInt(min, max, rangeType);

        if (seeded)
        {
            _seed = seed;
            _random.Seed((int)seed);
            _isSeeded = true;

            if (callback != null)
                callback.Invoke((int)seed);
        }
        else
        {
            _seed = null;
            _isSeeded = false;
        }

        return GenerateRandomInt(min, max, rangeType);
    }

    private float GenerateRandomFloat(float min, float max, RangeType rangeType)
    {
        if (rangeType == RangeType.Closed)
            return _random.NextDouble() * (max - min) + min;

        if (rangeType == RangeType.Open)
            return (float)_random.NextDouble() * (max - min) + min;

        if (rangeType == RangeType.HalfOpen)
            return (float)_random.NextDouble() * (max - min) + min;
    }

    private int GenerateRandomInt(int min, int max, RangeType rangeType)
    {
        if (rangeType == RangeType.Closed)
            return _random.Next(min, max + 1);

        if (rangeType == RangeType.Open)
            return _random.Next(min, max);

        if (rangeType == RangeType.HalfOpen)
            return _random.Next(min, max);
    }

    private bool ValidateInput(float min, float max)
    {
        return min <= max;
    }
}

public interface IAdvancedRandomGenerator
{
    int CustomRange(int min, int max, RangeType rangeType, bool seeded, int? seed, SeedCallback? callback);
    float CustomRange(float min, float max, RangeType rangeType, bool seeded, int? seed, SeedCallback? callback);
}
