    if not s3.get_bucket_notification_configuration(Bucket='your-bucket-name')['Notifications']:
        s3.put_bucket_notification_configuration(
            Bucket='your-bucket-name',
            NotificationConfiguration={
                'TopicConfigurations': [
                    {
                        'TopicArn': 'arn:aws:sns:REGION:ACCOUNT_ID:your-topic-name',
                        'Filter': {'S3Event': ['ObjectCreated:*']}
                    }
                ]
            }
        )

    try:
        response = s3.get_object(Bucket='your-bucket-name', Key=file_name + extension)

        if not response['Body'].read():
            response = requests.get(url, stream=True)

            if 200 <= response.status_code < 300:
                Image.open(BytesIO(response.content)).save(file_name + '.jpg')

                s3.put_object(Body=response.content, Bucket='your-bucket-name', Key=file_name + extension)

                return 'https://your-bucket-name.s3.amazonaws.com/' + file_name + extension
            else:
                raise Exception('Failed to get the image from the URL.')
        else:
            last_modified = datetime.strptime(response['LastModified'].strftime('%Y-%m-%d %H:%M:%S'), '%Y-%m-%d %H:%M:%S')

            if (datetime.now() - timedelta(hours=24)).replace(tzinfo=None) < last_modified.replace(tzinfo=None):
                return 'https://your-bucket-name.s3.amazonaws.com/' + file_name + extension
    except Exception as e:
        print(f"An error occurred: {str(e)}")
