void insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& insertion, int count = 1, Database* db = nullptr) {
    auto it = list.begin();
    bool found = false;
    while (it != list.end()) {
        if (*it == target) {
            found = true;
            break;
        }
        ++it;
    }

    if (!found) {
        list.insert_after(list.cend(), insertion);
    } else {
        for (int i = 0; i < count; ++i) {
            it = list.find(target);
            if (it == list.end()) break;
            list.insert_after(it, insertion);
            ++it;
        }
    }

    if (db != nullptr) {
        std::string timestamp = "timestamp";
        db->logOperation(timestamp, "inserted after first occurrence");
    }
}
