const SCRIPT_CACHE = {};

function fetchScripts(scripts, endpoint) {
  const promises = scripts.map((script) => {
    if (!script.code || !script.type) {
      throw new Error('Script is missing essential properties');
    }
    return fetch(`${endpoint}/${script.type}`)
      .then((response) => response.text())
      .catch((error) => console.error('Error fetching script:', error))
      .finally(() => {
        setTimeout(() => {
          const cacheKey = `${script.type}#${script.code}`;
          SCRIPT_CACHE[cacheKey] = script;
        }, 100);
      });
  });

  return Promise.all(promises);
}

function renderScripts(scripts) {
  const html = [];

  scripts.forEach((script) => {
    if (!SCRIPT_CACHE[`${script.type}#${script.code}`]) {
      return null;
    }
    const cachedScript = SCRIPT_CACHE[`${script.type}#${script.code}`];
    html.push(`<script id="${cachedScript.type}" key="${cachedScript.code}">
      ${cachedScript.code}
    </script>`);
  });

  return html.join('');
}

function loadScripts(footerScripts) {
  const promises = footerScripts.map((script) => {
    if (!script.code || !script.type) {
      throw new Error('Script is missing essential properties');
    }
    return new Promise((resolve, reject) => {
      const scriptTag = document.createElement('script');
      scriptTag.id = `${script.type}`;
      scriptTag.innerHTML = script.code;
      document.body.appendChild(scriptTag);
      resolve();
    });
  });

  return Promise.all(promises)
    .then(() => console.log('Scripts loaded'))
    .catch((error) => console.error('Error loading scripts:', error));
}

function renderFooter(footerScripts, endpoint) {
  const html = renderScripts(footerScripts);

  if (!html) {
    return '<p>Loading...</p>';
  }

  document.body.innerHTML += `<div id="footer">${html}</div>`;

  loadScripts(footerScripts)
    .then(() => console.log('Footer rendered'))
    .catch((error) => console.error('Error rendering footer:', error));

  return html;
}

function handleScriptFetchError(error) {
  console.error('Error fetching script:', error);
  // Show error message or loading indicator here
}
