function updateClinicStatus(int $clinicId, string $newStatus) {
    // Initialize rate limiting variables
    $maxUpdatesPerSecond = 10;
    $lastUpdateTimestamp = time();

    while (true) {
        if (time() - $lastUpdateTimestamp >= 1) {
            $lastUpdateTimestamp = time();
        }

        // Validate clinic ID
        if (!validateClinicId($clinicId)) {
            return ['error' => 'Invalid clinic ID'];
        }

        try {
            // Start transaction
            $db = new PDO('mysql:host=localhost;dbname=clinics', 'user', 'password');
            $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
            $db->beginTransaction();

            // Update clinic status
            $query = "UPDATE clinics SET status = :newStatus, last_modified_ip = $_SERVER['REMOTE_ADDR'], last_modified_date = NOW() WHERE id = :clinicId";
            $stmt = $db->prepare($query);
            $stmt->bindParam(':newStatus', $newStatus);
            $stmt->bindParam(':clinicId', $clinicId);
            $stmt->execute();

            // Commit transaction
            $db->commit();
        } catch (PDOException $e) {
            // Rollback and log error
            $db->rollBack();
            $logService = new LoggingService();
            $logService->logError($e, 'updateClinicStatus');
            return ['error' => 'Failed to update clinic status'];
        }

        // Log success
        $logService = new LoggingService();
        $logService->logSuccess('Updated clinic status');

        return ['message' => 'Clinic status updated successfully', 'numUpdated' => 1];
    }
}

