void insertReplacementString(std::forward_list<std::string>& list, const std::string& target, const std::string& replacement) {
    auto it = list.begin();
    bool found = false;

    // Find the target string in the list
    while (it != list.end() && !found) {
        if (*it == target) {
            found = true;
        } else {
            ++it;
        }
    }

    // If not found, insert at the end of the list
    if (!found) {
        list.insert_after(it, replacement);
    } else {
        // Found! Insert the replacement string immediately after the target
        list.insert_after(it++, replacement);
    }

    // Log the insertion operation to the database
    try {
        DatabaseLogger::getInstance()->logInsertion(list, target, replacement);
    } catch (const std::exception& e) {
        // Handle error: failed database operation
        throw std::runtime_error("Failed to log insertion operation: " + std::string(e.what()));
    }

    // Clean up resources (e.g., close database connection)
    DatabaseLogger::getInstance()->cleanUp();
}
