using System;
using System.Data.SqlClient;
using System.Collections.Generic;

public static class DatabaseHelper
{
    public static void ExecuteDynamicSqlQuery(SqlConnection connection, string commandTemplate, Dictionary<string, object> parameters)
    {
        using (var cmd = new SqlCommand(commandTemplate, connection))
        {
            foreach (var parameter in parameters)
            {
                var dbType = GetDbType(parameter.Value);
                cmd.Parameters.AddWithValue("@" + parameter.Key, parameter.Value);
                cmd.Parameters[@"@" + parameter.Key].DbType = dbType;
            }

            try
            {
                using (var transaction = connection.BeginTransaction())
                {
                    cmd.ExecuteNonQuery();
                    transaction.Commit();
                }
            }
            catch (Exception ex)
            {
                transaction.Rollback();
                // Log the error here
                Console.WriteLine("Error executing query: " + ex.Message);
            }
        }
    }

    private static SqlDbType GetDbType(object value)
    {
        if (value == null) return SqlDbType.Bit;
        if (value is DateTime || value is DateTime?) return SqlDbType.DateTime2;
        if (value is string) return SqlDbType.NVarChar;
        if (value is byte[]) return SqlDbType.VarBinary;
        // Add more data type mappings as needed
        throw new ArgumentException("Unsupported data type", nameof(value));
    }
}
