const scriptCache = {};
let activeScripts = [];

function fetchScript(script) {
  return new Promise((resolve, reject) => {
    if (scriptCache[script.key]) {
      resolve(scriptCache[script.key]);
    } else {
      const xhr = new XMLHttpRequest();
      xhr.open('GET', script.src);
      xhr.onload = () => {
        if (xhr.status === 200) {
          scriptCache[script.key] = xhr.responseText;
          resolve(xhr.responseText);
        } else {
          reject(new Error(`Failed to load script ${script.src}`));
        }
      };
      xhr.onerror = () => {
        reject(new Error('Network error'));
      };
      xhr.ontimeout = () => {
        reject(new Error('Timeout'));
      };
      xhr.send();
    }
  });
}

function renderScripts(scripts) {
  const footerHTML = `<footer id="script-footer">
  <div class="loader" style="display: none;">
    <img src="loading-spinner.gif" alt="Loading...">
  </div>
  <ul id="script-list"></ul>
</footer>`;

  document.body.innerHTML += footerHTML;

  function renderScript(script) {
    return new Promise((resolve, reject) => {
      fetchScript(script).then((scriptCode) => {
        const scriptTag = document.createElement('script');
        scriptTag.src = `data:text/javascript;charset=utf-8,${encodeURIComponent(scriptCode)}`;
        scriptTag.onload = () => resolve();
        scriptTag.onerror = () => reject(new Error(`Failed to load script ${script.src}`));
        scriptTag.async = true;
        document.getElementById('script-list').appendChild(scriptTag);
      });
    });
  }

  activeScripts.forEach((script) => renderScript(script));

  scripts.forEach((script) => {
    if (!activeScripts.includes(script)) {
      return;
    }
    const scriptElement = document.createElement('script');
    scriptElement.innerHTML = script.code;
    scriptElement.type = script.type;
    document.getElementById('script-list').appendChild(scriptElement);
  });
}

function updateFooter() {
  activeScripts.forEach((script) => {
    const scriptElement = document.getElementById(`script-${script.key}`);
    if (scriptElement) {
      scriptElement.parentNode.removeChild(scriptElement);
    }
  });

  activeScripts = [];
}

setInterval(() => {
  updateFooter();
}, 10000);

function loadMoreScripts() {
  fetch('https://api.example.com/scripts')
    .then((response) => response.json())
    .then((scripts) => {
      scripts.forEach((script) => {
        if (!scriptCache[script.key]) {
          activeScripts.push(script);
          renderScript(script).catch((error) => console.error(error));
        }
      });
    })
    .catch((error) => console.error(error));

  return Promise.all(activeScripts.map((script) => fetchScript(script)));
}
