```csharp
using System;

public class RandomValueGenerator
{
    private double minValue;
    private double maxValue;
    private string distributionType;

    public RandomValueGenerator(double minValue, double maxValue, string distributionType)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
        this.distributionType = distributionType;
    }

    public double GetRandomFloat()
    {
        switch (distributionType)
        {
            case "uniform":
                return UnityEngine.Random.Range(minValue, maxValue);
            case "normal":
                return NormalDistribution(minValue, maxValue);
            default:
                throw new ArgumentException("Unsupported distribution type");
        }
    }

    public int GetRandomInt()
    {
        switch (distributionType)
        {
            case "uniform":
                return (int)UnityEngine.Random.Range(minValue, maxValue);
            case "normal":
                return (int)NormalDistribution(minValue, maxValue);
            default:
                throw new ArgumentException("Unsupported distribution type");
        }
    }

    public double GetRandomFloatWithinQuantile(double quantile)
    {
        if (quantile < 0 || quantile > 1)
            throw new ArgumentException("Quantile must be between 0 and 1");

        return GetRandomFloat() * (maxValue - minValue) + minValue;
    }

    public int GetRandomIntWithinStandardDeviation(double standardDeviation)
    {
        if (standardDeviation < 0)
            throw new ArgumentException("Standard deviation cannot be negative");

        double mean = (minValue + maxValue) / 2;

        return (int)(NormalDistribution(mean, standardDeviation));
    }

    private double NormalDistribution(double mean, double stdDev)
    {
        System.Random rand = new System.Random();
        double u1 = 0.0;
        double u2 = 0.0;

        do
        {
            u1 = rand.NextDouble();
            u2 = rand.NextDouble();
        }
        while (u2 > Math.Exp(-12.0 * (Math.Log(u1) - Math.Log(1.0) + stdDev)));

        return mean + stdDev * (double)Math.Sqrt(-2.0 * Math.Log(u1));
    }

    public override string ToString()
    {
        return $"RandomValueGenerator (Min: {minValue}, Max: {maxValue}, Distribution: {distributionType})";
    }
}
