using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Memory;
using System;
using System.Threading.Tasks;

namespace MyWebApp.Services
{
    public class UpdateHtmlContentService
    {
        private readonly IMemoryCache _cache;
        private readonly IAzureBlobStorageService _blobStorageService;

        public UpdateHtmlContentService(IMemoryCache cache, IAzureBlobStorageService blobStorageService)
        {
            _cache = cache;
            _blobStorageService = blobStorageService;
        }

        [HttpPost]
        public async Task<IActionResult> UpdateHtmlContent([FromBody]UpdateHtmlContentRequest request)
        {
            if (!await IsValidRequest(request))
                return BadRequest("Invalid input");

            try
            {
                // Check if the content is already cached
                if (_cache.TryGetValue(request.PageSectionId, out string cachedHtmlContent))
                {
                    // Update the cached HTML content
                    _cache.Set(request.PageSectionId, request.HtmlContent);
                }
                else
                {
                    // Fetch the HTML content from storage service
                    string htmlContent = await _blobStorageService.GetHtmlContent(request.PageSectionId);

                    // Check if the content is available
                    if (string.IsNullOrEmpty(htmlContent))
                        return NotFound("HTML content not found");

                    // Update the cache with the latest HTML content
                    _cache.Set(request.PageSectionId, request.HtmlContent);
                }

                // Return a success response
                return Ok();
            }
            catch (Exception ex)
            {
                // Log the error and return an internal server error
                await LogError(ex);
                return StatusCode(500, "Internal Server Error");
            }
        }

        private async Task<bool> IsValidRequest(UpdateHtmlContentRequest request)
        {
            // Validate page section ID and element ID formats
            if (!Guid.TryParse(request.PageSectionId, out _))
                return false;

            if (!Guid.TryParse(request.ElementId, out _))
                return false;

            // Check if the HTML content is valid
            if (string.IsNullOrEmpty(request.HtmlContent))
                return false;

            return true;
        }

        private async Task LogError(Exception ex)
        {
            // Implement logging mechanism here
        }
    }

    public class UpdateHtmlContentRequest
    {
        public Guid PageSectionId { get; set; }
        public Guid ElementId { get; set; }
        public string HtmlContent { get; set; }
    }
}
