import java.io.IOException;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.Random;

public class GameCharacter {
    private Selector selector;
    private SocketChannel channel;
    private Random rand = new Random();
    private int cooldown = 0; // Initialize with 0 for the first attack

    public void connectToServer() throws IOException {
        selector = Selector.open();
        channel = SocketChannel.open();
        channel.configureBlocking(false);
        channel.register(selector, SelectionKey.OP_CONNECT);
        // Handle connection state and timeouts
        while (true) {
            selector.select(500); // Wait for 0.5 seconds
            for (SelectionKey key : selector.selectedKeys()) {
                if (key.isConnectable()) {
                    channel.connect(new InetSocketAddress("remote_server_ip", "port"));
                    // Log connection event
                    System.out.println("Connected to the server.");
                    break;
                }
            }
        }
    }

    public void useAttack() throws IOException {
        if (cooldown > 0) {
            System.out.println("Cooldown not expired yet. Waiting for " + cooldown + " more seconds.");
            return; // Attack cannot be used during cooldown
        }
        int attackType = rand.nextInt(2); // Randomly select attack type
        String attackName;
        int attackPower;

        if (attackType == 0) {
            attackName = "Lightning Strike";
            attackPower = 10;
        } else {
            attackName = "Fireball";
            attackPower = 50;
        }
        System.out.println("Selected attack: " + attackName + ", Power Level: " + attackPower);
        // Log attack event
        System.out.println("Attacking with a " + attackName + "!");

        cooldown = 3; // Initialize cooldown for 3 seconds
    }

    public void updateCooldown() throws IOException {
        if (cooldown > 0) {
            cooldown--;
            System.out.println("Cooldown remaining: " + cooldown);
        } else {
            System.out.println("Attack ready!");
        }
    }

    public static void main(String[] args) throws IOException {
        GameCharacter gc = new GameCharacter();
        gc.connectToServer();
        while (true) {
            gc.useAttack();
            try {
                Thread.sleep(1000); // Wait for 1 second
                gc.updateCooldown();
            } catch (InterruptedException e) {
                System.out.println("Interrupted while waiting.");
                return;
            }
        }
    }
}
