```csharp
using System;
using System.Collections.Generic;
using System.Threading;

public delegate bool ConfigUpdateCallback(Dictionary<string, object> configUpdates);

public class DynamicRandomNumberGenerator
{
    private Random _random;
    private Dictionary<string, object> _config;
    private readonly object _lock = new object();

    public DynamicRandomNumberGenerator()
    {
        _random = new Random();
        _config = new Dictionary<string, object>();
    }

    public int GenerateRandomInt(int min, int max, RangeType rangeType, bool seeded = false)
    {
        if (!ValidateRange(min, max, rangeType))
            throw new ArgumentException("Invalid range or range type");

        int result;
        lock (_lock)
        {
            _random.Next(min, max);
            if (seeded)
                _random = new Random();
            else
                Thread.Sleep(1); // Simulate a delay for non-seeded generation

            switch (rangeType)
            {
                case RangeType.Closed:
                    result = _random.Next(min, max + 1);
                    break;
                case RangeType.Open:
                    result = _random.Next(min, max);
                    break;
                case RangeType.HalfOpen:
                    if (_random.Next(2) == 0)
                        result = _random.Next(min, max);
                    else
                        result = min - 1;
                    break;
                default:
                    throw new ArgumentException("Invalid range type");
            }
        }
        return result;
    }

    public double GenerateRandomDouble(double min, double max, RangeType rangeType, bool seeded = false)
    {
        if (!ValidateRange(min, max, rangeType))
            throw new ArgumentException("Invalid range or range type");

        double result;
        lock (_lock)
        {
            _random.NextDouble();
            if (seeded)
                _random = new Random();
            else
                Thread.Sleep(1); // Simulate a delay for non-seeded generation

            switch (rangeType)
            {
                case RangeType.Closed:
                    result = min + (_random.NextDouble() * (max - min));
                    break;
                case RangeType.Open:
                    result = min + (_random.NextDouble() * (max - min));
                    break;
                case RangeType.HalfOpen:
                    if (_random.Next(2) == 0)
                        result = min + (_random.NextDouble() * (max - min));
                    else
                        result = max - 1e-6; // Prevent half-open range from being exceeded
                    break;
                default:
                    throw new ArgumentException("Invalid range type");
            }
        }
        return result;
    }

    public void UpdateConfig(ConfigUpdateCallback callback, Dictionary<string, object> configUpdates)
    {
        lock (_lock)
        {
            if (!callback(configUpdates))
                throw new Exception("Configuration update failed");

            _config = configUpdates;
        }
    }

    private bool ValidateRange(int min, int max, RangeType rangeType)
    {
        if (min >= max || (rangeType != RangeType.HalfOpen && min > max))
            return false;

        return true;
    }
}

public enum RangeType
{
    Closed,
    Open,
    HalfOpen
}
