#include <thread>
#include <mutex>
#include <random>

class AttackController {
private:
    std::mutex mtx;
    int attackCooldown[2] = {9, 15};
    int currentCooldown[2];
    std::random_device rd;
    std::mt19937 gen;

public:
    AttackController() : gen(rd()) {
        for (int i = 0; i < 2; i++) {
            currentCooldown[i] = attackCooldown[i];
        }
    }

    void selectAttack() {
        // Simulate network latency
        if (!std::this_thread::hardware_concurrency()) {
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
        }

        std::lock_guard<std::mutex> lock(mtx);
        for (int i = 0; i < 2; i++) {
            if (currentCooldown[i] > 0) {
                currentCooldown[i]--;
                return;
            }
        }

        // Generate random number
        int randomNum = gen() % 2;

        std::cout << "Selected attack: " << randomNum + 1 << std::endl;

        // Reset cooldown for selected attack
        currentCooldown[randomNum] = attackCooldown[randomNum];
    }
};
