use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process;
use std::sync::mpsc;
use std::thread;

const MAX_RETRIES: usize = 5;
const RETRY_DELAY_MSEC: u64 = 1000; // 1 second

struct Env {
    path: String,
}

impl Env {
    fn new() -> Self {
        let p = env::var("MY_DIR").ok().map_or_else(|| "no-dir".to_string(), |p| p);
        Env { path: p }
    }

    fn set(&mut self, p: &str) {
        *self = Env { path: p.to_string() };
        env::set_var("MY_DIR", p);
    }
}

fn create_dir(dir_name: &str, parent_dir: &PathBuf, retries: usize) -> Result<(), String> {
    let mut dir_path = parent_dir.join(dir_name);

    if dir_path.exists() {
        // Append timestamp to directory name
        dir_path.set_file_name(&format!("{}-{}", dir_path.file_name().unwrap(), Utc::now()));
    }

    for _ in 0..retries {
        match fs::create_dir_all(&dir_path) {
            Ok(_) => return Ok(()),
            Err(e) if e.kind() == io::ErrorKind::WouldBlock
                || e.kind() == io::ErrorKind::InputMismatch =>
            // Retry with a delay
            thread::sleep(std::time::Duration::from_millis(RETRY_DELAY_MSEC));
        }
    }

    Err(format!("Failed to create directory: {}", dir_path.display()))
}

fn cleanup(dir_name: &str, max_age_days: u64) -> Result<(), String> {
    let dir_path = Path::new(dir_name);

    // Clean up directories older than the specified age
    for entry in fs::read_dir(dir_path)? {
        let entry = entry?;
        if let Some(path) = entry.path().to_str().map(PathBuf::from) {
            if path.exists() && (Utc::now().signed_duration_since(chrono::DateTime::parse_from_rfc3339(&path.file_name().unwrap()).unwrap()).num_seconds() >= max_age_days * 24 * 60 * 60) {
                fs::remove_dir_all(path)?;
            }
        }
    }

    Ok(())
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        println!("Usage: {} [directory-name] [parent-directory-path]", &args[0]);
        process::exit(1);
    }

    let dir_name = &args[1];
    let parent_dir_path = PathBuf::from(&args.get(2).unwrap_or(""));
    if !parent_dir_path.exists() {
        fs::create_dir_all(parent_dir_path.clone()).expect("Failed to create parent directory");
    }

    let env = Env::new();
    match create_dir(dir_name, &parent_dir_path, MAX_RETRIES) {
        Ok(_) => println!("Directory created: {}", dir_path.display()),
        Err(err) => eprintln!("Error creating directory: {}", err),
    };

    // Set environment variable
    env.set(&dir_path.display().to_string());

    match cleanup(dir_name, 7) {
        Ok(_) => println!("Cleaned up directories older than 7 days"),
        Err(err) => eprintln!("Error cleaning up directories: {}", err),
    };
}
