using Microsoft.AspNetCore.Identity;
using System;

namespace IdentityValidation
{
    public class Startup
    {
        public void ConfigureServices(IServiceCollection services)
        {
            services.AddIdentity<User, Role>()
                .AddErrorDescriber<CustomErrorDescriber>()
                .AddDefaultTokenProviders()
                .WithUsernameRequirements(new CustomUsernameRequirement())
                .WithPasswordRequirements(new CustomPasswordRequirement());
            services.ConfigureApplicationCookie(options =>
            {
                options.LoginPath = "/Account/LogIn";
                options.AccessDeniedPath = "/Account/AccessDenied";
            });
        }
    }

    public class CustomErrorDescriber : IdentityErrorDescriber
    {
        public override IdentityError DuplicateUsernameError()
        {
            return new IdentityError(code: "DuplicateUsername", description: "The username is already taken.");
        }
    }

    public class CustomUsernameRequirement : IUserNameNormalizer, IPasswordValidator<User>
    {
        public async Task<IdentityResult> ValidateAsync(User user)
        {
            if (user.UserName.Length < 3)
                return IdentityResult.Failed(new IdentityError(code: "UsernameTooShort", description: "The username must be at least 3 characters long."));
            if (!user.UserName.Contains(" "))
                return IdentityResult.Success;
            return IdentityResult.Failed(new IdentityError(code: "UsernameContainsSpace", description: "The username cannot contain spaces."));
        }
    }

    public class CustomPasswordRequirement : IPasswordValidator<User>
    {
        public async Task<IdentityResult> ValidateAsync(User user)
        {
            if (user.Password.Length < 8)
                return IdentityResult.Failed(new IdentityError(code: "PasswordTooShort", description: "The password must be at least 8 characters long."));
            if (!user.Password.Contains(" "))
                return IdentityResult.Success;
            return IdentityResult.Failed(new IdentityError(code: "PasswordContainsSpace", description: "The password cannot contain spaces."));
        }
    }
}
