use std::env;
use std::fs;
use std::path::{Path, PathBuf};

pub fn create_directory(name: &str) -> String {
    let path = match env::var("DIRECTORY") {
        Ok(path) => Path::new(&path),
        Err(_) => {
            let dir_path = Path::new(name);
            if !dir_path.exists() {
                fs::create_dir_all(dir_path).expect("Failed to create directory");
            }
            dir_path
        }
    };
    env::set_var("DIRECTORY", path.to_str().unwrap()).expect("Failed to set environment variable");
    format!("{}", path.display())
}
