function generateSecureRandomString($length, $characterSet) {
    if (!isset($length) || !is_int($length) || $length <= 0) {
        throw new Exception("Length must be a positive integer");
    }

    if (!isset($characterSet) || !is_string($characterSet)) {
        throw new Exception("Character set must be a string");
    }

    $possibleChars = str_split($characterSet);
    $randomString = '';
    for ($i = 0; i < $length; $i++) {
        $randomString .= $possibleChars[rand(0, count($possibleChars) - 1)];
    }

    return $randomString;
}

function hashPassword($password, $algorithm = 'bcrypt', $saltLength = 16) {
    if (!isset($password) || !is_string($password)) {
        throw new Exception("Password must be a string");
    }

    if (!in_array($algorithm, ['bcrypt', 'argon2id'])) {
        throw new Exception("Invalid algorithm. Supported algorithms are bcrypt and argon2id");
    }

    $salt = generateSecureRandomString($saltLength, 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz1234567890');

    switch ($algorithm) {
        case 'bcrypt':
            return crypt($password, '$2y$' . $salt);
        case 'argon2id':
            return password_hash($password, PASSWORD_ARGON2ID, ['memory_cost' => 2048]);
    }
}

