```csharp
using System;
using System.Collections.Generic;
using System.Data.Common;
using System.Linq;
using System.Threading;

namespace DatabaseConnectionManager
{
    public sealed class DatabaseConnectionManager : IDisposable
    {
        private readonly Dictionary<string, ConnectionPool> _connectionPools = new();
        private readonly object _lock = new object();

        public void InitializeFromConfiguration()
        {
            // Implement the configuration loading logic here
        }

        public void ConfigurePooling(int minSize, int maxSize, int idleTimeout)
        {
            // Implement the connection pooling configuration logic here
        }

        public IDbConnection GetConnection(string provider, string connectionString)
        {
            if (string.IsNullOrEmpty(connectionString))
                throw new ArgumentException("Connection string is required", nameof(connectionString));

            lock (_lock)
            {
                if (!_connectionPools.TryGetValue(provider, out var pool))
                {
                    pool = new ConnectionPool(minSize: 1, maxSize: maxSize, idleTimeout: TimeSpan.FromMinutes(idleTimeout));
                    _connectionPools[provider] = pool;
                }

                return pool.GetConnection(connectionString);
            }
        }

        public void ReleaseConnection(IDbConnection connection)
        {
            lock (_lock)
            {
                var provider = connection.GetType().Name.Split('.')[0];
                if (_connectionPools.TryGetValue(provider, out var pool))
                {
                    pool.ReleaseConnection(connection);
                }
            }
        }

        public override string ToString()
        {
            lock (_lock)
            {
                return $"Database Connection Manager (Pool size: {_connectionPools.Values.Sum(p => p.Size)}, Active connections: {_connectionPools.Values.Sum(p => p.ActiveConnections)})"
                      + Environment.NewLine
                      + string.Join(Environment.NewLine, _connectionPools.Select(p => $"{p.Key} - Size: {p.Value.Size}, Idle timeout: {p.Value.IdleTimeout}"));
            }
        }

        public PerformanceMetrics GetPerformanceMetrics()
        {
            lock (_lock)
            {
                var metrics = new PerformanceMetrics();
                foreach (var pool in _connectionPools.Values)
                {
                    metrics.ConnectionRequestLatency += pool.RequestLatency;
                    metrics.PoolSize += pool.Size;
                    metrics.IdleConnections += pool.IdleConnections;
                }
                return metrics;
            }
        }

        public void Dispose()
        {
            lock (_lock)
            {
                foreach (var pool in _connectionPools.Values)
                {
                    pool.Dispose();
                }
                _connectionPools.Clear();
            }
        }
    }

    public sealed class ConnectionPool : IDisposable
    {
        public int Size { get; private set; }
        public int ActiveConnections { get; private set; }
        public TimeSpan IdleTimeout { get; private set; }
        public Queue<IDbConnection> Connections { get; } = new();

        public IDbConnection GetConnection(string connectionString)
        {
            if (Connections.Count == 0 || DateTime.Now - Connections.Peek().StateChange >= IdleTimeout)
            {
                var connection = CreateConnection(connectionString);
                Connections.Enqueue(connection);
                return connection;
            }

            return Connections.Dequeue();
        }

        public void ReleaseConnection(IDbConnection connection)
        {
            lock (_lock)
            {
                connection.StateChange = DateTime.Now;
                Connections.Enqueue(connection);
            }
        }

        public void Configure(int minSize, int maxSize, TimeSpan idleTimeout)
        {
            // Implement the configuration logic here
        }

        public void Dispose()
        {
            while (Connections.Count > 0)
            {
                Connections.Dequeue().Dispose();
            }
        }
    }

    public sealed class PerformanceMetrics
    {
        public double ConnectionRequestLatency { get; set; }
        public int PoolSize { get; set; }
        public int IdleConnections { get; set; }
    }
}
