using System;
using System.IO;
using Microsoft.Web.Administration;

public class WebsiteAdder
{
    public TaskResult AddAndStartWebsite(string directoryPath, string siteName)
    {
        // Verify the presence of a web.config file
        if (!File.Exists(Path.Combine(directoryPath, "web.config")))
        {
            LogError("Web.config file is missing in the specified directory.");
            return new TaskResult { Status = TaskStatus.Failed };
        }

        try
        {
            // Create an instance of the WebAdministration class
            using (var iisManager = new Server())
            {
                // Get a reference to the default website collection
                var sites = iisManager.Sites;

                // Add the new site with the specified name and directory path
                sites.Add(siteName, directoryPath);

                // Start the newly added site
                sites[siteName].Start();

                LogInfo("Website successfully added and started.");
                return new TaskResult { Status = TaskStatus.Successful };
            }
        }
        catch (Exception ex)
        {
            LogError("An error occurred while adding and starting the website: " + ex.Message);
            return new TaskResult { Status = TaskStatus.Failed };
        }
    }

    // Helper methods for logging
    private void LogInfo(string message) => Console.WriteLine($"[INFO] {message}");
    private void LogError(string message) => Console.WriteLine($"[ERROR] {message}");
}

public class TaskResult
{
    public TaskStatus Status { get; set; }
}

public enum TaskStatus
{
    Successful,
    Failed
}
