using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public static class FileEncryptionService
{
    public static byte[] EncryptFile(string filePath, string encryptionKey, string salt)
    {
        using (AesGcm aes = new AesGcm(encryptionKey, salt))
        {
            using (FileStream fileStream = File.OpenRead(filePath))
            {
                byte[] encryptedBytes;
                using (MemoryStream memoryStream = new MemoryStream())
                {
                    using (CryptoStream cryptoStream = aes.CreateEncryptorStream(memoryStream))
                    {
                        fileStream.CopyTo(cryptoStream);
                        cryptoStream.FlushFinalBlock();
                        encryptedBytes = memoryStream.ToArray();
                    }
                }
                return encryptedBytes;
            }
        }
    }

    public static byte[] DecryptFile(string filePath, string encryptionKey, string salt)
    {
        using (AesGcm aes = new AesGcm(encryptionKey, salt))
        {
            using (FileStream fileStream = File.OpenRead(filePath))
            {
                byte[] decryptedBytes;
                using (MemoryStream memoryStream = new MemoryStream())
                {
                    using (CryptoStream cryptoStream = aes.CreateDecryptorStream(memoryStream))
                    {
                        fileStream.CopyTo(cryptoStream);
                        cryptoStream.FlushFinalBlock();
                        decryptedBytes = memoryStream.ToArray();
                    }
                }
                return decryptedBytes;
            }
        }
    }

    public class AesGcm
    {
        private readonly string _encryptionKey;
        private readonly string _salt;

        public AesGcm(string encryptionKey, string salt)
        {
            _encryptionKey = encryptionKey;
            _salt = salt;
        }

        public Stream CreateEncryptorStream(Stream stream)
        {
            using (Aes aes = Aes.Create())
            {
                aes.Key = Convert.FromBase64String(_encryptionKey);
                aes.IV = Convert.FromBase64String(_salt);

                ICryptoTransform encryptor = aes.CreateEncryptor();
                CryptoStream cryptoStream = new CryptoStream(stream, encryptor, CryptoStreamMode.Write);

                return cryptoStream;
            }
        }

        public Stream CreateDecryptorStream(Stream stream)
        {
            using (Aes aes = Aes.Create())
            {
                aes.Key = Convert.FromBase64String(_encryptionKey);
