#include <ctime>
#include <cstdlib>
#include <cstdio>

const int MAX_FILENAME_LENGTH = 255;

char* generateNewFileName(const char* filePath) {
    time_t rawtime;
    struct tm *info;
    char timestamp[20];

    // Create the timestamp
    rawtime = time(NULL);
    info = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", info);

    // Calculate the random alphanumeric string
    static const char alphanum[] =
        "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    int randomLength = 8;
    char* randomStr = new char[randomLength + 1];
    for (int i = 0; i < randomLength; i++) {
        randomStr[i] = alphanum[(rand() % (sizeof(alphanum) - 1))];
    }
    randomStr[randomLength] = '\0';

    // Combine the timestamp and random string
    char* fileName = new char[MAX_FILENAME_LENGTH + 1];
    sprintf(fileName, "%s_%s", timestamp, randomStr);

    return fileName;
}
