class OctreeNode {
public:
    std::shared_ptr<OctreeNode> children[8];
    bool isLeaf;
    void* data;

    // ...
};

std::unique_ptr<OctreeNode> initializeOctree(int depth, int capacity) {
    if (depth < 0 || capacity <= 0) {
        throw std::runtime_error("Invalid input");
    }

    auto root = std::make_unique<OctreeNode>();
    root->isLeaf = false;

    for (int i = 0; i < 8; ++i) {
        root->children[i] = nullptr;
    }

    if (depth > 1) {
        initializeOctree(depth - 1, capacity / 2);
    } else {
        // Initialize leaf nodes
        for (int i = 0; i < capacity; ++i) {
            root->children[i] = std::make_unique<OctreeNode>();
            root->children[i]->isLeaf = true;
            root->children[i]->data = nullptr;
        }
    }

    return root;
}
