    {
        try
        {
            using (Aes aes = Aes.Create())
            {
                byte[] keyBytes;
                byte[] ivBytes;

                if (!LoadKeyAndIV(out keyBytes, out ivBytes))
                {
                    throw new Exception("Failed to load encryption key and IV.");
                }

                aes.Key = keyBytes;
                aes.IV = ivBytes;

                ICryptoTransform decryptor = aes.CreateDecryptor();

                using (MemoryStream ms = new MemoryStream(Convert.FromBase64String(base64EncodedMessage)))
                {
                    using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                    {
                        byte[] decryptedBytes = new byte[ms.Length];
                        int bytesRead = cs.Read(decryptedBytes, 0, decryptedBytes.Length);
                        return Encoding.UTF8.GetString(decryptedBytes, 0, bytesRead);
                    }
                }
            }
        }
        catch (CryptographicException ex)
        {
            // Log decryption error
            Console.WriteLine($"Decryption failed: {ex.Message}");
            return null;
        }
    }

    private static bool LoadKeyAndIV(out byte[] keyBytes, out byte[] ivBytes)
    {
        try
        {
            using (FileStream fileStream = File.OpenRead(_keyFile))
            {
                keyBytes = new byte[fileStream.Length];
                fileStream.Read(keyBytes, 0, keyBytes.Length);
            }

            using (FileStream fileStream = File.OpenRead(_ivFile))
            {
                ivBytes = new byte[fileStream.Length];
                fileStream.Read(ivBytes, 0, ivBytes.Length);
            }
            return true;
        }
        catch
        {
            keyBytes = null;
            ivBytes = null;
            return false;
        }
    }

