import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.Random;
import java.util.logging.Handler;
import java.util.logging.Logger;

public class GameCharacter {
    private static final Logger logger = Logger.getLogger(GameCharacter.class.getName());
    private static final Random random = new Random();
    private SocketChannel channel;
    private boolean isAttacking = false;
    private long attackCooldownTime = 0;

    public void establishConnection() throws IOException {
        Selector selector = Selector.open();
        channel = SocketChannel.open();
        channel.configureBlocking(false);
        channel.register(selector, SelectionKey.OP_CONNECT, null);
        InetSocketAddress address = new InetSocketAddress("remote.address");
        channel.connect(address);
        while (!channel.isConnectionPending()) {
            selector.select();
        }
    }

    public void handleConnectionStateChanges() throws IOException {
        while (true) {
            if (channel.isConnectionPending()) {
                // Handle connection establishment
                logger.info("Connected to the remote address");
            } else if (channel.isConnected() && !isAttacking) {
                // Select a random attack and start cooldown
                int attackType = random.nextInt(2);
                System.out.println("Selected attack: " + attackType);
                isAttacking = true;
                attackCooldownTime = System.currentTimeMillis() + 9000; // 9 seconds in milliseconds
            } else if (channel.isConnected() && isAttacking) {
                // Check for cooldown expiration
                if (System.currentTimeMillis() >= attackCooldownTime) {
                    isAttacking = false;
                }
            } else if (!channel.isConnected()) {
                // Handle disconnection or failure
                logger.warning("Connection failed");
            }
        }
    }

    public void closeConnection() throws IOException {
        channel.close();
        channel = null;
    }
}
