#include <curl/curl.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    CURL *c;
    int total_bytes_downloaded;
} DownloadThread;

struct {
    pthread_t *threads;
    size_t num_threads;
} thread_pool;

int download_url(const char *url, const char *output_file_path, int max_concurrent_downloads) {
    int rc = 0;
    CURL *curl_handle;
    CURLcode res;
    FILE *fp = NULL;
    size_t total_bytes_downloaded = 0;
    pthread_t *threads = NULL;
    int num_threads = 0;
    int thread_ids[16];

    // Initialize libcurl
    curl_global_init(CURL_GLOBAL_DEFAULT);

    // Allocate memory for the thread pool
    if ((thread_pool.threads = (pthread_t *)malloc(max_concurrent_downloads * sizeof(pthread_t))) == NULL) {
        rc = -1;
        goto cleanup;
    }
    thread_pool.num_threads = max_concurrent_downloads;

    // Initialize the download threads
    for (int i = 0; i < max_concurrent_downloads; i++) {
        DownloadThread *thread = (DownloadThread *)malloc(sizeof(DownloadThread));
        if (thread == NULL) {
            rc = -1;
            goto cleanup;
        }
        thread->c = curl_easy_init();
        if (thread->c == NULL) {
            rc = -1;
            free(thread);
            continue;
        }
        pthread_create(&thread_pool.threads[i], NULL, download_thread_func, thread);
    }

    // Perform the downloads
    for (int i = 0; i < max_concurrent_downloads; i++) {
        pthread_join(thread_pool.threads[i], &thread_ids[num_threads]);
        num_threads++;
    }

    // Clean up
cleanup:
    if (fp != NULL) fclose(fp);
    if (curl_handle != NULL) curl_easy_cleanup(curl_handle);
    for (int i = 0; i < max_concurrent_downloads; i++) {
        free(thread_pool.threads[i]);
    }
    free(thread_pool.threads);
    free(threads);
    return rc;
}

void *download_thread_func(void *data) {
    DownloadThread *thread = data;

    // Perform the download
    res = curl_easy_perform(thread->c, NULL);

    if (res != CURLE_OK) {
        // Handle error
    }

    // Close the connection
    curl_easy_cleanup(thread->c);

    return NULL;
}
