const fs = require('fs');
const path = require('path');
const Module = Module || (Module = {});
const require = require('module').create(require.main);

class DynamicLoader {
  constructor(context, config) {
    this.context = context;
    this.config = config;
    this.loadedModules = {};
    this.circularDependencies = [];
    this.concurrentLoadCount = 0;
    this.concurrentLoadMax = 5; // default value
  }

  async loadModule(moduleName) {
    if (this.loadedModules[moduleName]) return this.loadedModules[moduleName];

    try {
      const modulePath = path.join(this.config.moduleDir, `${moduleName}.js`);
      if (!fs.existsSync(modulePath)) throw new Error(`Module ${moduleName} not found`);

      await new Promise((resolve, reject) => {
        this.concurrentLoadCount++;
        fs.readFile(modulePath, 'utf8', (err, content) => {
          if (err) reject(err);
          else resolve(content);
        });
      });

      const module = Module.create(moduleName, content);
      Object.defineProperty(this.context, moduleName, { get: () => module.exports });
      this.loadedModules[moduleName] = module;

      return this.context[moduleName];
    } catch (error) {
      console.error(`Error loading module ${moduleName}: ${error}`);
      throw error;
    } finally {
      if (--this.concurrentLoadCount === 0) {
        // All concurrent loads have finished
      }
    }
  }

  async executeModules() {
    for await (const moduleName of this.config.moduleOrder) {
      try {
        const module = await this.loadModule(moduleName);
        console.log(`Loaded and executed module ${moduleName}`);
      } catch (error) {
        console.error(`Error executing module ${moduleName}: ${error}`);
      }
    }
  }

  async checkCircularDependencies() {
    for (const moduleName of Object.keys(this.loadedModules)) {
      const dependencies = require(moduleName).dependencies;
      if (dependencies && dependencies.length > 0) {
        for (const dependency of dependencies) {
          if (!this.loadedModules[dependency]) this.circularDependencies.push({ module: moduleName, dependency });
        }
      }
    }

    if (this.circularDependencies.length > 0) {
      console.error('Circular dependencies detected:');
      for (const circularDependency of this.circularDependencies) {
        console.error(`Module ${circularDependency.module} depends on non-loaded module ${circularDependency.dependency}`);
      }
      throw new Error('Circular dependencies detected');
    }
  }

  async run() {
    await this.executeModules();
    await this.checkCircularDependencies();
  }
}

const context = {};
const config = require('./config.json');

const loader = new DynamicLoader(context, config);
loader.concurrentLoadMax = process.argv.includes('--concurrent-load-max') ? parseInt(process.argv[process.argv.indexOf('--concurrent-load-max') + 1], 10) : this.concurrentLoadMax;

loader.run();
