#include <forward_list>
#include <string>
#include <iostream>

void insertReplacement(std::forward_list<std::string>& list,
                        const std::string& target,
                        const std::string& replacement,
                        bool caseInsensitive = false) {
    auto it = list.cbegin();

    if (!target.empty() && !replacement.empty()) {
        for (; it != list.cend(); ++it) {
            if (caseInsensitive ? (*it).compare(target, 0, target.length(), std::nullopt) : (*it) == target) {
                list.insert_after(it++, replacement);
                break;
            }
        }

        if (it == list.cend()) {
            list.insert_after(list.cend(), replacement);
        }
    } else {
        // Handle error: invalid input parameters
        std::cout << "Error: Invalid input parameters." << std::endl;
    }
}
