#include <semaphore.h>
#include <stdio.h>

// Function prototypes
sem_t* create_semaphore();
void init_semaphore(sem_t *sem, int value);
int wait_semaphore(sem_t *sem);
void post_semaphore(sem_t *sem);

// Structure to hold semaphore properties and error handling information
typedef struct {
    sem_t *sem;
    int initialized;
    int max_value;
} Semaphore;

Semaphore* create_semaphore(int max_value) {
    Semaphore *semaphore = (Semaphore*)malloc(sizeof(Semaphore));
    semaphore->initialized = 0;
    semaphore->max_value = max_value;
    semaphores->sem = sem_open("/my_semaphore", O_CREAT | O_EXCL, S_IRUSR | S_IWUSR, max_value);
    return semaphore;
}

void init_semaphore(sem_t *sem, int value) {
    if (!sem_initialized()) {
        sem_init(sem, 1, value);
        semaphores->initialized = 1;
    }
}

int wait_semaphore(sem_t *sem) {
    return sem_wait(sem);
}

void post_semaphore(sem_t *sem) {
    return sem_post(sem);
}
