typedef struct {
    char* filename;
    FILE* file;
} LogFile;

void* process_file(void* arg) {
    LogFile* log = (LogFile*)arg;
    int num_fields = 0;
    double sum = 0.0;

    while (fgets(log->filename, sizeof(char), log->file)) {
        char* token = strtok(log->filename, " ");
        while (token) {
            if (strspn(token, ".0123456789-") == strlen(token)) {
                num_fields++;
                sum += atof(token);
            }
            token = strtok(NULL, " ");
        }
    }

    fclose(log->file);
    free(log);

    return &sum;
}

void print_average(double* averages) {
    int i;
    for (i = 0; i < 2; i++) {
        printf("Average of fields %d and %d: %.2f\n", i, i+1, *averages++);
    }
}

int main(int argc, char** argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <log_dir> <endpoint> <verbosity>\n", argv[0]);
        return 1;
    }

    const char* log_dir = argv[1];
    const char* endpoint = argv[2];

    int verbosity = atoi(argv[3]);

    pthread_t threads[1000];

    DIR* dir = opendir(LOG_DIR);
    if (!dir) {
        perror("opendir");
        return 1;
    }

    struct dirent* ent;
    while ((ent = readdir(dir))) {
        LogFile* log = (LogFile*)malloc(sizeof(LogFile));
        log->filename = strdup(ent->d_name);

        int fd = open(log_dir, O_RDONLY);
        if (-1 == fd) {
            perror("open");
            free(log->filename);
            free(log);
            continue;
        }

        log->file = fdopen(fd, "r");

        pthread_create(&threads[ent->d_namlen], NULL, process_file, (void*)log);

        closedir(dir);
    }

    for (int i = 0; i < ent->d_namlen; i++) {
        void* result;
        pthread_join(threads[i], &result);
        double sum = *(double*)result;
        printf("Total average: %.2f\n", sum / num_fields);

        free(result);
    }

    return 0;
}
