from PIL import Image

class ProfilePictureDAO:
    def __init__(self, cache_expiration_time=3600):
        self.cache = {}
        self.cache_expiration_time = cache_expiration_time

    def get_profile_picture(self, user_id):
        if user_id in self.cache and time.time() - self.cache[user_id]['timestamp'] < self.cache_expiration_time:
            return self.cache[user_id]['profile_picture']
        else:
            # Call external API to retrieve profile picture from cloud storage
            profile_picture = retrieve_from_cloud_storage(user_id)
            if profile_picture:
                self.cache[user_id] = {'timestamp': time.time(), 'profile_picture': profile_picture}
            return profile_picture

    def update_profile_picture(self, user_id, image_file):
        if not (os.path.isfile(image_file) and image_file.endswith(('.jpg', '.jpeg', '.png'))):
            raise ValueError("Invalid image file")

        # Resize the image to optimize storage
        img = Image.open(image_file)
        new_size = (100, 100)
        img.thumbnail(new_size)
        resized_image_path = f"{uuid.uuid4().hex}.thumbnail.jpg"
        img.save(resized_image_path)

        try:
            # Call external API to update profile picture in cloud storage
            update_in_cloud_storage(user_id, resized_image_path)
        except Exception as e:
            print(f"Error updating profile picture: {e}")

    def delete_profile_picture(self, user_id):
        if user_id in self.cache:
            del self.cache[user_id]
        try:
            # Call external API to delete profile picture from cloud storage
            delete_from_cloud_storage(user_id)
        except Exception as e:
            print(f"Error deleting profile picture: {e}")
