**JavaScript Function: Dynamic Footer Rendering**
```javascript
function renderFooterScripts(scripts) {
  const footer = document.createElement('div');
  footer.className = 'footer';

  function fetchScript(script) {
    return new Promise((resolve, reject) => {
      if (!script.code || !script.type) {
        console.error('Invalid script:', script);
        resolve('');
      }

      const xhr = new XMLHttpRequest();
      xhr.open('GET', `https://api.example.com/${script.type}.js`);
      xhr.onload = () => {
        if (xhr.status === 200) {
          script.code = xhr.responseText;
          resolve(script.code);
        } else {
          reject(new Error(`Failed to fetch script: ${xhr.statusText}`));
        }
      };
      xhr.onerror = () => reject(new Error('Network error'));
      xhr.onTimeout = () => reject(new Error('Timeout'));

      xhr.send();
    });
  }

  function renderScript(script) {
    const scriptTag = document.createElement('script');
    scriptTag.src = 'data:text/javascript;charset=UTF-8,' + encodeURIComponent(script.code);
    scriptTag.type = script.type;
    scriptTag.key = `script-${script.name}`;
    footer.appendChild(scriptTag);

    return scriptTag;
  }

  function cacheScripts(scripts) {
    const cachedScripts = {};

    scripts.forEach((script) => {
      cachedScripts[script.name] = script.code;
    });

    return cachedScripts;
  }

  function loadScripts(scripts) {
    return Promise.all(scripts.map(fetchScript));
  }

  function renderScripts(scripts) {
    return Promise.all(scripts.map(renderScript));
  }

  function removeUnusedScripts() {
    const scriptTags = footer.querySelectorAll('script');

    scriptTags.forEach((scriptTag) => {
      if (!cachedScripts[scriptTag.key]) {
        footer.removeChild(scriptTag);
      }
    });
  }

  let cachedScripts;

  async function renderFooter() {
    try {
      cachedScripts = cacheScripts(scripts);
      const fetchedScripts = await loadScripts(scripts);
      const renderedScripts = await renderScripts(fetchedScripts);

      footer.innerHTML = '';
      footer.appendChild(...renderedScripts);

      removeUnusedScripts();
    } catch (error) {
      console.error('Error rendering footer:', error);
    }
  }

  renderFooter();

  return footer;
}
