using System;
using System.Data.SqlClient;

public class DbCommandExecutor
{
    public IDataReader ExecuteReader(string command, List<string> parameters, SqlConnection connection)
    {
        using (SqlCommand sqlCmd = new SqlCommand(command, connection))
        {
            for (int i = 0; i < parameters.Count; i++)
            {
                sqlCmd.Parameters.AddWithValue($"@p{i}", parameters[i]);
            }

            using (SqlDataReader reader = sqlCmd.ExecuteReader())
            {
                return reader;
            }
        }
    }
}
