using System.Threading;

public class DataLoader
{
    public static MyCustomData LoadData(string filePath)
    {
        MyCustomData data = null;

        try
        {
            using (FileStream fs = File.Open(filePath, FileMode.Open))
            {
                BinaryFormatter formatter = new BinaryFormatter();
                lock (_lockObject) // thread-safe locking for concurrent access
                {
                    data = (MyCustomData)formatter.Deserialize(fs);
                }
            }

            // Verify data integrity against checksum file
            string checksumFilePath = filePath + ".chk";
            if (!File.Exists(checksumFilePath))
            {
                Console.WriteLine("Checksum file not found. Loading data anyway.");
            }
            else
            {
                using (FileStream csFs = File.Open(checksumFilePath, FileMode.Open))
                {
                    long checksum = BinaryFormatter.Deserialize(csFs);
                    if (data.Checksum != checksum)
                    {
                        throw new Exception("Data corruption detected! Cannot load corrupted data.");
                    }
                }
            }

            return data;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading data: {ex.Message}");
            throw; // rethrow the exception for proper error handling
        }
    }

    private static object _lockObject = new object();
}
