Here is a C program that reads data from multiple log files stored in a directory and processes them concurrently to calculate the average of the last two numerical fields in each line:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_LOG_FILES 1000
#define MAX_FILE_SIZE (1 << 30) // 1GB

// Struct to represent a log file
typedef struct {
    char path[256];
    int fd;
    size_t fileSize;
} File;

// Function to read and process a single log file
void* processFile(void* arg) {
    File* file = (File*)arg;
    FILE* fp = fopen(file->path, "r");

    if (!fp) {
        perror("fopen");
        return NULL;
    }

    char line[1024];
    int lineNumber = 0;
    double sum = 0.0;

    while (fgets(line, sizeof(line), fp)) {
        char* token = strtok(line, " ");

        if (!token) continue;

        int fieldCount = 0;
        while (token && *token != '\0') {
            if (!strspn(token, "0123456789.-")) break; // Skip non-numeric fields

            ++fieldCount;

            if (fieldCount == 3 || fieldCount == 4) { // Process the last two numerical fields
                double num1 = atof(token);
                double num2 = atof(strtok(NULL, " ") ? : "");

                sum += num1 + num2;
            }

            token = strtok(NULL, " ");
        }

        ++lineNumber;
    }

    fclose(fp);

    if (file->fd > 0) close(file->fd);

    printf("Processed file: %s\nAverage: %.4f\n", file->path, sum / lineNumber);

    return NULL;
}

// Function to read and process all log files concurrently
void processLogFiles(const char* directoryPath, const char* loggingServiceEndpoint) {
    DIR* dir = opendir(directoryPath);
    struct dirent* entry;

    if (!dir) {
        perror("opendir");
        return;
    }

    File files[MAX_LOG_FILES];
    int fileCount = 0;

    while ((entry = readdir(dir))) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        File* file = &files[fileCount++];

        sprintf(file->path, "%s/%s", directoryPath, entry->d_name);
        file->fd = open(file->path, O_RDONLY);

        if (file->fd < 0) {
            perror("open");
            continue;
        }

        struct stat sb;
        fstat(file->fd, &sb);
        file->fileSize = sb.st_size;
    }

    closedir(dir);

    pthread_t threads[fileCount];

    for (int i = 0; i < fileCount; ++i) {
        pthread_create(&threads[i], NULL, processFile, &files[i]);
    }

    for (int i = 0; i < fileCount; ++i) {
        pthread_join(threads[i], NULL);
    }
}

// Function to handle the external logging service
void logToService(const char* message) {
    // TO DO: Implement API call to the external logging service
}

// Main function
int main(int argc, char** argv) {
    const char* directoryPath = "path_to_log_files";
    const char* loggingServiceEndpoint = "endpoint_of_logging_service";

    // Parse command-line options and configuration files

    processLogFiles(directoryPath, loggingServiceEndpoint);

    return 0;
}
