#include <forward_list>
#include <string>
#include <functional>

bool insertAfter(std::forward_list<std::string>& lst, const std::string& target, const std::string& value, std::function<bool(const std::string&, const std::string&)> compFunc) {
    auto it = lst.begin();
    bool found = false;

    for (auto i = 0; !found && i < lst.size(); ++i) {
        if (compFunc(lst.cront[i], target)) {
            lst.insert_after(it, value);
            found = true;
        }
        else
            ++it;
    }

    if (!found)
        lst.append(value);

    return found;
}
