import re
import json
import requests

def extract_book_titles(text):
    fiction_title_pattern = r'\b(fictional|novel)\b'
    non_fiction_title_pattern = r'\b(non-fiction|textbook)\b'
    poetry_title_pattern = r'\b(poem|verse)\b'
    book_title_pattern = r'\b(.*?)(?: by|,|&| )?(author|writer|publisher|company|series|volume)\b'

    titles = {}
    for title_pattern in [fiction_title_pattern, non_fiction_title_pattern, poetry_title_pattern]:
        matches = re.findall(title_pattern, text.lower())
        for match in matches:
            if match not in titles:
                titles[match] = 0
            titles[match] += 1

    min_occurrences = int(input("Enter the minimum occurrences of a book title to query the API: "))

    filtered_titles = {k: v for k, v in titles.items() if v >= min_occurrences}

    api_response = {}
    for title, count in filtered_titles.items():
        response = requests.get(f"https://book-api.com/search/{title}")
        try:
            data = json.loads(response.text)
            if data['results']:
                api_response[title] = {'count': count, 'data': data['results'][0]}
        except (json.JSONDecodeError, KeyError):
            continue

    return api_response
