import java.io.File;
import java.security.MessageDigest;
import java.util.HashMap;
import java.util.Map;

public class MD5HashCalculator {
    private static Map<String, String> cachedHashes = new HashMap<>();

    public String calculateMD5(String filePath) throws Exception {
        try {
            File file = new File(filePath);
            if (!file.exists()) {
                return null; // or throw exception
            }

            MessageDigest md = MessageDigest.getInstance("MD5");
            java.io.FileInputStream fis = new java.io.FileInputStream(file);
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
            fis.close();

            byte[] digest = md.digest();
            StringBuilder hexString = new StringBuilder();
            for (int i = 0; i < digest.length; i++) {
                String hex = Integer.toHexString(0xff & digest[i]);
                if (hex.length() == 1) {
                    hexString.append('0');
                }
                hexString.append(hex);
            }

            String hash = hexString.toString();

            // cache the result
            cachedHashes.put(filePath, hash);

            return hash;
        } catch (Exception e) {
            // handle exception gracefully
            return null; // or throw exception
        }
    }

    public boolean isFileChanged(String filePath, String expectedHash) throws Exception {
        try {
            String actualHash = calculateMD5(filePath);
            if (actualHash == null || !actualHash.equals(expectedHash)) {
                return true;
            } else {
                return false;
            }
        } catch (Exception e) {
            // handle exception gracefully
            return true; // or throw exception
        }
    }
}
