use std::time::{Instant, Duration};
use std::process::exit;
use rustc_driver::{CatchResult, catch_with_exit_code};
use early_error::{EarlyError, EarlyErrorKind};
use serde_json;

struct CompilationMetric {
    exit_code: i32,
    compilation_time: Duration,
    resident_set_size_before: u64,
    resident_set_size_after: u64,
}

fn compile_files(file_paths: Vec<String>) -> Result<Vec<CompilationMetric>, EarlyError> {
    let mut results = vec![];

    for file_path in file_paths {
        let start_time = Instant::now();
        let start ResidentSetSize = get_resident_set_size();

        match catch_with_exit_code(&file_path, |compiler| {
            // Install custom logging hook using SyncLazy
            compiler.install_logging_hook(|log| log.set_level(log::Level::Debug));

            // Compile the file and handle any errors that occur during compilation
            match compiler.compile_file(&file_path) {
                Ok(_) => Ok(CatchResult::Success),
                Err(err) => catch_with_exit_code(err, |compiler| {
                    // Report any compilation errors using early_error
                    let err = EarlyError::new(EarlyErrorKind::Compilation, &err);
                    exit(1); // Exit with error code 1
                }),
            }
        }) {
            Ok(CatchResult::Success) => {}
            Err(err) => return Err(err),
        }

        let end_time = Instant::now();
        let compilation_time = end_time.duration_since(start_time).unwrap_or_default();
        let resident_set_size_after = get_resident_set_size();

        results.push(CompilationMetric {
            exit_code: 0, // Replace with actual exit code
            compilation_time,
            resident_set_size_before: start ResidentSetSize,
            resident_set_size_after,
        });
    }

    Ok(results)
}

fn get_resident_set_size() -> u64 {
    use winapi::mmmap;
    let mut size = mmmap::get_process_memory_info().pagefile_usage;
    // Implement OS-specific logic to retrieve the process's resident set size
    size
}
