```csharp
using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Linq;
using System.Threading.Tasks;

public class StoredProcExecutor
{
    private readonly Dictionary<string, object> _cache = new Dictionary<string, object>();

    public async Task<List<MyCustomObject>> ExecuteStoredProcedureAsync(SqlConnection connection, List<SqlParameter> inputParams, string storedProcedureName)
    {
        var cacheKey = $"{connection.Database}-{string.Join(",", inputParams.Select(x => x.ParameterName + "=" + x.Value))}-{storedProcedureName}";
        if (_cache.ContainsKey(cacheKey))
            return _cache[cacheKey].Cast<MyCustomObject>().ToList();

        using (var command = new SqlCommand(storedProcedureName, connection))
        {
            command.CommandType = CommandType.StoredProcedure;
            inputParams.ForEach(x => command.Parameters.Add(x));
            var result = await Task.Run(() =>
            {
                var adapter = new SqlDataAdapter(command);
                var dt = new DataTable();
                adapter.Fill(dt);
                return dt.Rows.Cast<DataRow>().Select(row => MyCustomObject.FromDataRow(row)).ToList();
            });
            _cache[cacheKey] = result;
        }
        return result;
    }
}

public class MyCustomObject
{
    public int Id { get; set; }
    public string Name { get; set; }

    public static List<MyCustomObject> FromDataRow(DataRow row)
    {
        var list = new List<MyCustomObject>();
        foreach (DataColumn column in row.Table.Columns)
        {
            switch (column.ColumnName)
            {
                case "Id":
                    list.Add(new MyCustomObject { Id = int.Parse(row[column].ToString()) });
                    break;
                case "Name":
                    list.Last().Name = row[column].ToString();
                    break;
            }
        }
        return list;
    }
}

function copyBytes(chunks, numBytes) {
  const buffer = Buffer.allocUnsafe(numBytes);
  let offset = 0;

  for (const chunk of chunks) {
    chunk.copy(chunk.offset(), 0, Math.min(numBytes - offset, chunk.length), buffer, offset);

    offset += Math.min(numBytes - offset, chunk.length);
  }

  return buffer;
}
