<?php

function updateClinicStatus($clinicId) {
    // Validate clinic ID
    if (!is_numeric($clinicId)) {
        return ['error' => 'Invalid clinic ID', 'count' => 0];
    }

    // Start transaction
    $db = new PDO('mysql:host=localhost;dbname=clinics', 'root', '');
    $db->beginTransaction();

    try {
        // Update clinic status
        $query = "UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE id = ?";
        $stmt = $db->prepare($query);
        $stmt->execute(['new_status', $_SERVER['REMOTE_ADDR'], date('Y-m-d H:i:s'), $clinicId]);

        // Fetch and cache last modified information
        $lastModifiedInfo = fetchLastModifiedInfo($clinicId);

        // Commit transaction
        $db->commit();

        // Log update
        logUpdate($clinicId, 'success', $lastModifiedInfo['last_modified_ip'], $lastModifiedInfo['last_modified_date']);

        return ['message' => 'Clinic status updated successfully', 'count' => 1];
    } catch (Exception $e) {
        // Rollback transaction and log error
        $db->rollBack();
        logError($clinicId, $e);

        return ['error' => $e->getMessage(), 'count' => 0];
    }
}

function fetchLastModifiedInfo($clinicId) {
    // Fetch last modified information from external API
    $apiUrl = 'https://api.lastmodified.com/clinics/' . $clinicId;
