using System.Linq;
using System.Threading.Tasks;

public class DatabaseHelper
{
    private readonly ILogger _logger;
    private readonly Dictionary<string, object> _cache = new Dictionary<string, object>();

    public async Task<List<MyCustomObject>> ExecuteStoredProcedureAsync(SqlConnection connection, List<SqlParameter> parameters, string procedureName)
    {
        // Validate input parameters
        foreach (var param in parameters)
        {
            if (param.Value == null && param.SqlDbType != SqlDbType.Int)
                throw new ArgumentException("Non-nullable parameters must have a default value.");
        }

        // Generate cache key based on procedure name and parameter values
        var cacheKey = $"{procedureName}:{string.Join(",", parameters.Select(p => p.Value.ToString()))}";

        // Check if cached result exists
        if (_cache.TryGetValue(cacheKey, out object cachedResult))
            return (List<MyCustomObject>)cachedResult;

        try
        {
            using (var command = new SqlCommand(procedureName, connection))
            {
                command.CommandType = System.Data.CommandType.StoredProcedure;
                foreach (var param in parameters)
                    command.Parameters.Add(param);

                _logger.LogInformation($"Executing stored procedure: {procedureName}");

                // Execute the stored procedure asynchronously and read results
                using (var reader = await command.ExecuteReaderAsync())
                {
                    var result = new List<MyCustomObject>();

                    while (await reader.ReadAsync())
                    {
                        var obj = new MyCustomObject();
                        foreach (var column in reader.Columns)
                            if (!reader.IsDBNull(reader.GetOrdinal(column.ToString())))
                                obj.GetType().GetProperty(column.ToString()).SetValue(obj, reader[column]);
                        result.Add(obj);
                    }

                    return result;
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Failed to execute stored procedure: {procedureName}");
            throw;
        }
        finally
        {
            // Update cache expiration policy based on input parameters
            _cache.ExpireItem(cacheKey, TimeSpan.FromDays(1)); // Expire in 1 day
        }
    }
}

public class MyCustomObject
{
    public int Id { get; set; }
    public string Name { get; set; }
    // ...
}
