    private Random random = new Random();
    private SocketChannel socketChannel;
    private Logger logger = Logger.getLogger(GameCharacter.class.getName());
    private boolean isAttackReady = false;

    public void establishConnectionAndHandleStateChanges() {
        try {
            socketChannel = new SocketChannel();
            socketChannel.connect(new InetSocketAddress("remote.address"));
            socketChannel.configureBlocking(false);
            socketChannel.setOption(StandardSocketOptions.SO_REUSEADDR, true);

            while (true) {
                if (!isAttackReady && canUseAttack()) {
                    useRandomAttack();
                    isAttackReady = false;
                }

                // Handle connection state changes
                ConnectionState state = get ConnectionState(socketChannel);
                switch (state) {
                    case ESTABLISHED:
                        handleEstablishedConnection();
                        break;
                    case CLOSED:
                        handleClose();
                        return;
                    default:
                        break;
                }
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error connecting to remote address", e);
        }
    }

    private void useRandomAttack() {
        int attackType = random.nextInt(2); // 0 or 1
