#include <openssl/aes.h>
#include <openssl/rsa.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

typedef enum {
    AES_256_CBC,
    RSA_OAEP
} CipherType;

typedef struct {
    CipherType type;
    char* key;
    int blockSize;
} CipherConfig;

Cipher* encrypt_file(const char* filePath, const char* outputFile, CipherConfig cipherConfig) {
    // Initialize OpenSSL library
    SSL_library_init();

    // Read file in chunks to avoid loading entire file into memory
    FILE* file = fopen(filePath, "rb");
    if (!file) {
        // Log error and return
        // ...
    }
    fseek(file, 0L, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    // Initialize cipher object
    Cipher* cipher = EVP_CIPHER_CTX_new();
    if (!cipher) {
        // Log error and return
        // ...
    }

    // Set cipher parameters
    switch (cipherConfig.type) {
        case AES_256_CBC:
            EVP_EncryptInit_ex(cipher, EVP_aes_256_cbc(), NULL);
            break;
        case RSA_OAEP:
            EVP_EncryptInit_ex(cipher, EVP_rsa_oaep(), NULL);
            break;
        default:
            // Log error and return
            // ...
    }

    // Initialize buffer for reading file in chunks
    unsigned char* buffer = (unsigned char*)malloc(cipherConfig.blockSize * sizeof(unsigned char));
    if (!buffer) {
        // Log error and return
        // ...
    }
    size_t bytesRead;
    while ((bytesRead = fread(buffer, 1, cipherConfig.blockSize, file)) > 0) {
        // Encrypt buffer contents
        unsigned char* encryptedBuffer = (unsigned char*)malloc(bytesRead * sizeof(unsigned char));
        EVP_EncryptUpdate(cipher, encryptedBuffer, &bytesRead, buffer, bytesRead);
        // Process progress callback function
        // ...
    }

    // Finalize encryption
    EVP_EncryptFinal_ex(cipher, NULL, NULL);

    // Close file and cipher object
    fclose(file);
    EVP_CIPHER_CTX_free(cipher);

    return cipher;
}
