```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

namespace FileHasher
{
    public class FileHasher
    {
        private readonly ILogger _logger;

        public FileHasher(ILogger logger)
        {
            _logger = logger;
        }

        public async Task<string> ComputeHashAsync(string filePath, bool computeInChunks = false, int chunkSize = 4096)
        {
            using (var fileStream = new FileStream(filePath, FileMode.Open))
            {
                try
                {
                    var hashAlgorithm = SHA256.Create();
                    var hashValue = await ComputeHashAsync(fileStream, hashAlgorithm, computeInChunks, chunkSize);
                    return Convert.ToBase64String(hashValue);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error computing file hash");
                    throw;
                }
            }
        }

        private async Task<byte[]> ComputeHashAsync(Stream stream, SHA256 sha256, bool computeInChunks, int chunkSize)
        {
            if (computeInChunks)
            {
                using (var memoryStream = new MemoryStream())
                {
                    byte[] buffer = new byte[chunkSize];
                    int bytesRead;
                    while ((readBytes := stream.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        await Task.Yield();
                        memoryStream.Write(buffer, 0, readBytes);
                    }
                    return sha256.ComputeHash(memoryStream.ToArray());
                }
            }
            else
            {
                byte[] buffer = new byte[1024 * 64];
                int bytesRead;
                using (var hash = sha256)
                {
                    while ((readBytes := stream.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        await Task.Yield();
                        hash.TransformBlock(buffer, 0, readBytes);
                    }
                }
                return hash.HashValue;
            }
        }
    }
}
