#include <filesystem>
#include <string>
#include <forward_list>
#include <iostream>

std::string insertAndReadFile(const std::filesystem::path& directoryPath,
                              const std::string& targetString,
                              const std::string& replacementString,
                              std::forward_list<std::string>& fileList) {
    std::string fileContent;

    try {
        // Read the file synchronously from the specified directory
        fileContent = fs::read_file(directoryPath).data();

        // Find the first occurrence of the target string in the forward list
        auto it = std::find_if(fileList.begin(), fileList.end(),
                                 [&targetString](const std::string& str) {
                                     return 0 <= str.find(targetString);
                                 });

        if (it != fileList.end()) {
            // Insert the replacement string after the first occurrence of the target string
            fileList.insert(it, replacementString);
        } else {
            // If the target string is not found, insert the replacement string at the end of the list
            fileList.push_back(replacementString);
        }

        return fileContent;
    } catch (const std::exception& e) {
        // Handle exceptions and log errors for debugging and auditing purposes
        std::cerr << "Error: " << e.what() << std::endl;
        return "";
    }
}

// Example usage:
int main() {
    std::forward_list<std::string> fileList = {"hello", "world"};
    std::string fileContent = insertAndReadFile("/path/to/file.txt", "world", "cpp", fileList);
    // Process the file content
    return 0;
}
