const { Buffer } = require('buffer');

function mergeChunks(chunks, byteCount) {
  const buffer = Buffer.alloc(0);
  let bytesRead = 0;

  for (const chunk of chunks) {
    if (!Buffer.isBuffer(chunk)) throw new Error('Invalid data type');

    const chunkBytes = chunk.length;
    if (byteReads + chunkBytes > byteCount) throw new Error('Requested byte count exceeds available data');

    buffer = Buffer.concat([buffer, chunk.slice(0, byteCount - bytesRead)]);
    bytesRead += Math.min(chunkBytes, byteCount - bytesRead);

    if (bytesRead >= byteCount) break;
  }

  return buffer.slice(0, byteCount);
}
