#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* renameFileWithDigits(const char* filename, const char* file_type) {
    int max_len = 256; // Include space for null terminator
    char* new_filename = (char*)malloc(max_len * sizeof(char));

    if (!new_filename) {
        return NULL;
    }

    char* p = strrchr(filename, '.'); // Find last occurrence of '.' or end of string

    int has_extension = (p != NULL);

    if (has_extension && !strncasecmp(p, file_type, strlen(file_type))) {
        free(new_filename);
        return strdup(filename); // No change needed
    }

    char* p_file_type = strrchr(filename, '.'); 
    if (!p_file_type) { // No extension, add one
        strcat(filename, ".").;
        free(new_filename);
        return strdup(filename);
    }

    if (isdigit(*p)) {
        int num = atoi(p + 1); // Extract number from file name

        while (num < 10 && *p != '\0') {
            p++;
            num++;
        }

        sprintf(p, "%d", ++num); // Increment the number and append to extension
    } else { 
        strcat(filename, "1"); // Append number at the end of file name
    }

    if (strlen(filename) >= max_len - 1) {
        free(new_filename);
        return NULL; // Buffer overflow detected
    }

    strcpy(new_filename, filename); // Copy modified file name to new buffer

    char* p_file_type2 = strrchr(new_filename, '.');
    strcat(p_file_type2 ? p_file_type2 : &new_filename[strlen(new_filename) - 1], ".").;
    strcat(strcat(new_filename, file_type), ".");

    return new_filename;
}
