import json
import asyncio
from typing import Dict, Any

class JSONParser:
    def __init__(self):
        self.registry: Dict[str, Any] = {}
        self.circular_dependencies = set()

    async def load_json_files(self, file_paths: list) -> None:
        tasks = []
        for file_path in file_paths:
            task = asyncio.create_task(self.load_file(file_path))
            tasks.append(task)
        await asyncio.gather(*tasks)

    async def load_file(self, file_path: str) -> None:
        try:
            with open(file_path, 'r') as f:
                data = json.load(f)
                for obj in data:
                    if 'id' not in obj:
                        raise ValueError(f"Invalid JSON object in {file_path}")
                    factory = self.get_factory(obj['id'])
                    if factory is None:
                        continue
                    await self.execute_factory(factory, file_path, obj)
        except (FileNotFoundError, json.JSONDecodeError) as e:
            print(f"Failed to load file {file_path}: {str(e)}")
        except Exception as e:
            print(f"An error occurred while executing the factory for file {file_path}: {str(e)}")

    def get_factory(self, id: str) -> Any:
        return self.registry.get(id)

    async def execute_factory(self, factory: Any, file_path: str, obj: dict) -> None:
        if id in self.circular_dependencies:
            print(f"Circular dependency detected for file {file_path} with ID {id}")
            return
        try:
            instance = await factory()
            if hasattr(instance, 'load'):
                await self.load_file(obj['file'])
            else:
                print(f"Instance {instance.__class__.__name__} loaded successfully from {file_path}")
        except Exception as e:
            print(f"An error occurred while executing the factory for file {file_path}: {str(e)}")
        finally:
            if hasattr(instance, 'unload'):
                await instance.unload()

    def add_factory(self, id: str, factory: Any) -> None:
        self.registry[id] = factory

    async def create_instance(self, id: str) -> Any:
        return await self.get_factory(id)()
