    private DynamicResourcePool pool;

    public void initializeResourcePool(int minConnections, int maxConnections, int connectionTimeout,
            boolean seeded, Integer seed, ConnectionConfigCallback callback) {
        if (minConnections <= 0 || maxConnections < minConnections) {
            throw new IllegalArgumentException("Invalid number of connections");
        }
        if (connectionTimeout <= 0) {
            throw new IllegalArgumentException("Connection timeout must be positive");
        }

        config = new ResourcePoolConfig();
        config.minConnections = minConnections;
        config.maxConnections = maxConnections;
        config.connectionTimeout = connectionTimeout;

        if (seeded && seed != null) {
            isSeedSet = true;
            // implementation details omitted for brevity
        } else {
            isSeedSet = false;
        }

        if (callback != null) {
            ConnectionConfig initialConfig = new ConnectionConfig();
            config.callbackConfig = callback.onConfigure(initialConfig);
        }

        pool = new DynamicResourcePool();

        // initialization logic omitted for brevity
    }

    public Connection getConnection() {
        return pool.take();
    }

    public void returnConnection(Connection conn) {
        try {
            pool.put(conn);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
