class DynamicRandomStringGenerator {
    private $characterSet;
    private $seed;
    private $configUpdateCallback;

    public function __construct($characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', $seed = null) {
        $this->characterSet = $characterSet;
        if ($seed !== null) {
            srand($seed);
        }
    }

    public function GenerateCustomRandomString(int $length, int $seed = null): string {
        if ($length < 1) {
            throw new Exception('Length must be greater than zero');
        }

        if (isset($seed)) {
            srand($seed);
        } else {
            srand(time());
        }

        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $this->characterSet[rand(0, strlen($this->characterSet) - 1)];
        }

        return $randomString;
    }

    public function HashPassword(string $password): string {
        return hash('sha256', $password);
    }

    public function SetConfigUpdateCallback(?callable $callback): void {
        $this->configUpdateCallback = $callback;
    }

    public function UpdateConfiguration(array $settings): bool {
        if (isset($this->configUpdateCallback)) {
            return call_user_func($this->configUpdateCallback, $settings);
        }
        return true;
    }
}
