from flask import Flask, request, jsonify
from flask_login import LoginManager, login_user, logout_user, current_user
from flask_security import Security, SQLAlchemyUserDatastore, SecuredLoginManager
from flask_sqlalchemy import SQLAlchemy
from flask_bcrypt import Bcrypt
from flask_oauthlib.provider import OAuth2Provider
import hashlib

app = Flask(__name__)
app.config['SECRET_KEY'] = 'mysecretkey'
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///users.db'
app.config['SECURITY_PASSWORD_SALT'] = hashlib.sha256(b'salt').hexdigest()
app.config['SECURITY_TOKEN_SALT'] = hashlib.sha256(b'token').hexdigest()

db = SQLAlchemy(app)
bcrypt = Bcrypt(app)

# Define the User and Role models
class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    email = db.Column(db.String(120), unique=True)
    phone_number = db.Column(db.String(20))
    password = db.Column(db.String(128))
    role_id = db.Column(db.Integer, db.ForeignKey('role.id'))

class Role(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(64), unique=True)

# Define the User data store
user_datastore = SQLAlchemyUserDatastore(db, User, Role)

# Configure Flask-Security
security = Security(app, user_datastore)
login_manager = SecuredLoginManager(app)
oauth2_provider = OAuth2Provider(app)

@login_manager.user_loader
def load_user(user_id):
    return user_datastore.get_user(user_id)

@oauth2_provider.clientgetter
def get_client(client_id):
    return User.query.filter_by(email=client_id).first()

@oauth2_provider.token_verification_handler
def verify_token(token, request):
    # Verify the token with the external OAuth provider
    pass

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        email = request.form['email']
        password = request.form['password']
        user = User.query.filter_by(email=email).first()
        if user and bcrypt.check_password_hash(user.password, password):
            login_user(user)
            return jsonify({'success': True})
    return jsonify({'success': False})

@app.route('/logout', methods=['GET'])
def logout():
    logout_user()
    return jsonify({'success': True})

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        email = request.form['email']
        phone_number = request.form['phone_number']
        password = request.form['password']
        user = User(email=email, phone_number=phone_number)
        user.password = bcrypt.generate_password_hash(password).decode('utf-8')
        db.session.add(user)
        db.session.commit()
        return jsonify({'success': True})
    return jsonify({'success': False})

@app.route('/roles', methods=['GET'])
def get_roles():
    roles = Role.query.all()
    return jsonify([role.name for role in roles])

@app.route('/role/<int:role_id>', methods=['GET'])
def get_role(role_id):
    role = Role.query.get(role_id)
    if role:
        return jsonify({'name': role.name})
    return jsonify({'success': False})

if __name__ == '__main__':
    app.run(debug=True)

