#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <rand.h>

typedef struct {
    long offset;
    int key;
    double value;
} record;

record** initArrays(const char* filename, int* numRecords) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        printf("Error opening file\n");
        return NULL;
    }

    int numOffsets, numRows;
    fscanf(file, "%d %d", &numOffsets, &numRows);

    record** records = (record**)malloc(numRecords * sizeof(record*));
    for (int i = 0; i < numRecords; i++) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            printf("Memory allocation failed\n");
            return NULL;
        }
    }

    long* offsets = (long*)malloc(numOffsets * sizeof(long));
    int* keys = (int*)malloc(numRows * sizeof(int));

    for (int i = 0; i < numOffsets; i++) {
        fscanf(file, "%ld", &offsets[i]);
    }
    for (int i = 0; i < numRows; i++) {
        fscanf(file, "%d", &keys[i]);
    }

    fclose(file);

    *numRecords = numOffsets;

    // Initialize record values
    for (int i = 0; i < *numRecords; i++) {
        records[i]->offset = offsets[i];
        records[i]->key = keys[i];
        records[i]->value = ((double)rand()) / RAND_MAX;
    }

    free(offsets);
    free(keys);

    return records;
}

void freeArrays(record** records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        free(records[i]);
    }
    free(records);
}
