function copyBytes(chunks, byteCount) {
    const buffer = Buffer.alloc(0);

    for (const chunk of chunks) {
        if (chunk.length < 1 || chunk.length > byteCount) {
            throw new Error("Invalid chunk size");
        }

        const bytesRead = Math.min(chunk.length, byteCount);
        buffer.write(chunk.slice(0, bytesRead), 0, bytesRead);

        if (byteReads >= byteCount) {
            break;
        }
    }

    return buffer;
}

