bool generateAndHash(std::forward_list<std::string>& list,
                     const std::string& characterSet,
                     const std::string& password,
                     size_t length, 
                     const std::string& target, 
                     std::function<bool(const std::string&, const std::string&)> comp = std::equal_to<std::string>()) {
    // Generate a random string of the specified length using the given character set
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, characterSet.size() - 1);
    std::string randomString(length, ' ');
    for (auto& c : randomString) {
        c = characterSet[dis(gen)];
    }

    // Hash the provided password using a default hash function
    const auto hashedPassword = std::hash<std::string>{}(password);

    // Find the first occurrence of the target string in the list
    auto it = std::find_if(list.begin(), list.end(), [comp, &target](const std::string& s) {
        return comp(s, target);
    });

    // Insert the generated random string into the forward list after the first occurrence of the target string
    if (it != list.end()) {
        list.insert_after(it, randomString);
    } else {
        list.insert_after(list.end(), randomString);
    }

    // Return a boolean indicating whether the insertion and hashing were successful
    return true;
}
