#include <iostream>
#include <vector>
#include <mutex>

struct OctreeNode {
    int sizeLimit;
    bool isLeafNode;
    std::vector<OctreeNode*> children;
    std::vector<int> dataPoints;

    OctreeNode(int sizeLimit, bool isLeafNode = false)
        : sizeLimit(sizeLimit), isLeafNode(isLeafNode) {}
};

class Octree {
private:
    OctreeNode* root;
    std::mutex mutex;

public:
    Octree(int sizeLimit) {
        if (sizeLimit <= 0) {
            throw std::runtime_error("Invalid size limit");
        }

        root = new OctreeNode(sizeLimit);
    }

    ~Octree() {
        destroy(root);
    }

    void insert(int x, int y, int z, int dataPoint) {
        if (!root->insert(x, y, z, dataPoint)) {
            std::cerr << "Error: Node exceeded size limit" << std::endl;
        }
    }

private:
    void destroy(OctreeNode* node) {
        if (node == nullptr) return;

        for (auto child : node->children) {
            destroy(child);
        }

        delete node;
    }
};

int main() {
    // Example usage
    Octree octree(10);

    octree.insert(1, 2, 3, 42);
    octree.insert(4, 5, 6, 21);

    return 0;
}
