use std::env;
use std::fs::{self, DirBuilder};
use std::path::Path;
use std::process::exit;
use std::thread;
use std::time::{Duration, Instant};

fn create_or_use_dir() -> Result<String, std::io::Error> {
    let my_dir_path = env::var("MY_DIR_PATH");
    if let Ok(path) = &my_dir_path {
        if fs::read_dir(path.clone()).is_ok() {
            return Ok(path.clone());
        }
    }

    let new_dir_path = "/tmp/my_dir";
    if let Err(err) = DirBuilder::new()
        .recursive(true)
        .create(&Path::new(new_dir_path))?
    {
        eprintln!("Failed to create directory: {}", err);
        exit(1);
    }

    Ok(new_dir_path.to_string())
}

fn set_env_var(path: &str) -> Result<(), std::io::Error> {
    env::set_var("MY_DIR_PATH", path)?;
    println!("Set MY_DIR_PATH environment variable to '{}'", path);
    Ok(())
}

fn cleanup_dir() {
    loop {
        let my_dir_path = env::var("MY_DIR_PATH").unwrap_or_default();
        if my_dir_path.is_empty() || !fs::read_dir(&Path::new(&my_dir_path)).is_ok() {
            break;
        }
        thread::sleep(Duration::from_secs(600)); // sleep for 10 minutes
    }
}

fn main() {
    let path = create_or_use_dir().unwrap_or_default();
    set_env_var(&path).unwrap();

    let now = Instant::now();
    thread::spawn(move || {
        loop {
            cleanup_dir();
            if now.elapsed().as_secs() > 600 * 10 { // check every 10 minutes
                break;
            }
            thread::sleep(Duration::from_secs(300)); // sleep for 5 minutes between checks
        }
    });
}
