<?php

function generateSecureRandomString(int $length, string $characterSet): string {
    return bin2hex(random_bytes($length));
}

function hashPassword(string $password, string $hashAlgorithm): array {
    if (!in_array($hashAlgorithm, ['bcrypt', 'argon2id'])) {
        throw new Exception('Invalid hash algorithm');
    }

    $salt = random_bytes(16);
    $hashedPassword = password_hash($password . $salt, $hashAlgorithm);

    return [$hashedPassword, $salt];
}

function storeTokenAndHashedPassword(string $token, string $hashedPassword, array $nodeInfo): void {
    // Store the token and hashed password in a NoSQL database
    $database->insert('tokens', [
        'token' => $token,
        'hashed_password' => $hashedPassword,
        'node_info' => json_encode($nodeInfo)
    ]);
}

function retrieveTokenAndHashedPassword(string $token): array {
    // Retrieve the token and hashed password from a NoSQL database
    $result = $database->get('tokens', ['token' => $token]);

    if (!$result) {
        throw new Exception('Token not found');
    }

    return [$result['hashed_password'], json_decode($result['node_info'], true)];
}

function distributeTokenGenerationAndHashing(array $input): array {
    // Initialize a distributed lock to ensure concurrent access is handled safely
    $distributedLock = new DistributedLock();

    if (!$distributedLock->acquire()) {
        throw new Exception('Failed to acquire distributed lock');
    }

    try {
        $token = generateSecureRandomString($input['length'], $input['characterSet']);
        list($hashedPassword, $salt) = hashPassword($input['password'], $input['hashAlgorithm']);
        storeTokenAndHashedPassword($token, $hashedPassword, $input);
    } catch (Exception $e) {
        // Handle and log any errors that occur during token generation or hashing
        error_log('Error: ' . $e->getMessage());
        throw $e;
    } finally {
        $distributedLock->release();
    }

    return [$token, $hashedPassword];
}

// Example usage:
$input = [
    'length' => 32,
    'characterSet' => 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789',
    'password' => 'mysecretpassword',
    'hashAlgorithm' => 'bcrypt'
];

try {
    list($token, $hashedPassword) = distributeTokenGenerationAndHashing($input);
    echo "Generated token: $token\n";
    echo "Hashed password: $hashedPassword\n";
} catch (Exception $e) {
    error_log('Error: ' . $e->getMessage());
}

