```csharp
using UnityEngine;

public class ValueGenerator : MonoBehaviour
{
    public int min;
    public int max;
    public float? lowerBoundFloat = null;
    public float? upperBoundFloat = null;

    private void CheckRange()
    {
        if (min > max)
        {
            throw new ArgumentException("Minimum value must be less than or equal to maximum value.");
        }
    }

    public ValueGenerator(int min, int max)
    {
        this.min = min;
        this.max = max;
        CheckRange();
    }

    public ValueGenerator(int min, int max, bool constrainFloat) : this(min, max)
    {
        if (constrainFloat)
        {
            lowerBoundFloat = 0f;
            upperBoundFloat = 1f;
        }
    }

    public float GenerateFloat()
    {
        return UnityEngine.Random.value * (upperBoundFloat ?? (max - min)) + (lowerBoundFloat ?? min);
    }

    public int GenerateInt()
    {
        return UnityEngine.Random.Range(min, max + 1);
    }

    public int[] GenerateIntArray(int size)
    {
        CheckRange();
        var array = new int[size];
        for (int i = 0; i < size; i++)
        {
            array[i] = GenerateInt();
        }
        return array;
    }

    public float[] GenerateFloatArray(int size)
    {
        CheckRange();
        var array = new float[size];
        for (int i = 0; i < size; i++)
        {
            array[i] = GenerateFloat();
        }
        return array;
    }

    public override string ToString()
    {
        if (lowerBoundFloat.HasValue && upperBoundFloat.HasValue)
        {
            return $"Range: {min} to {max}, Constrained to [{lowerBoundFloat.Value}, {upperBoundFloat.Value})";
        }
        else
        {
            return $"Range: {min} to {max}";
        }
    }
}
