    {
        private readonly ConcurrentDictionary<string, DbConnection> _connectionsPool = new();
        private readonly Random _random = new();
        private int _connectionPoolSize;
        private bool _initialized;
        private string _seed;

        public void InitializeFromConfiguration()
        {
            // Load configuration from external system (e.g., Azure App Configuration or AWS SSM)
            // ...
            _seed = _random.Next().ToString();
            _initialized = true;
        }

        public IDbConnection GetConnection(string provider, string connectionString)
        {
            if (!_initialized) throw new InvalidOperationException("Database connection manager not initialized");

            if (_connectionsPool.ContainsKey(provider))
            {
                var connection = _connectionsPool.GetOrAdd(provider, CreateConnection);
                return connection;
            }

            return CreateConnection(provider, connectionString);
        }

        public void ReleaseConnection(IDbConnection connection)
        {
            if (!_initialized) throw new InvalidOperationException("Database connection manager not initialized");

            if (connection.State == ConnectionState.Open)
            {
                // Close the connection and release it to the pool
                connection.Close();
            }
            else
            {
                _connectionsPool.TryAdd(connection.GetType().Name, connection);
            }
        }

        public override string ToString()
        {
            return $"DynamicDatabaseConnectionManager: Pool size {_connectionPoolSize}, Active connections {_connectionsPool.Count}";
