#include <semaphore.h>
#include <stdio.h>

// Function prototype
int find_largest(int* arr, int size);

int main() {
    // Initialize semaphore
    sem_t *sem;
    if (sem_init(sem, 0, 1) == -1) {
        perror("sem_init");
        return -1;
    }

    // Read integers from standard input and store them in an array
    int n;
    scanf("%d", &n);
    int arr[n];
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    // Find the largest integer in the array using the semaphore
    sem_wait(sem); // Acquire the semaphore
    int max = find_largest(arr, n);
    printf("Largest integer: %d\n", max);
    sem_post(sem); // Release the semaphore

    // Destroy the semaphore
    if (sem_destroy(sem) == -1) {
        perror("sem_destroy");
        return -1;
    }

    return 0;
}

int find_largest(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}
