using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Runtime.Serialization.Formatters.Binary;

public class ProductMerger
{
    private readonly ILogger _logger;
    private readonly InventoryManagementApiClient _inventoryApi;

    public ProductMerger(ILogger logger, InventoryManagementApiClient inventoryApi)
    {
        _logger = logger;
        _inventoryApi = inventoryApi;
    }

    public async Task<MergedProductCollection> MergeProductsAsync(string[] filePaths)
    {
        var mergedProducts = new MergedProductCollection();
        var productLocks = new Dictionary<string, object>();

        await Task.WhenAll(filePaths.Select(async filePath =>
        {
            try
            {
                using (var fileStream = File.OpenRead(filePath))
                {
                    var binaryFormatter = new BinaryFormatter();
                    var products = (List<Product>)binaryFormatter.Deserialize(fileStream);

                    lock (productLocks.GetOrAdd(filePath, () => new object()))
                    {
                        foreach (var product in products)
                        {
                            mergedProducts.AddProduct(product);
                        }
                    }

                    _logger.LogInformation($"Loaded {products.Count} products from file '{filePath}'");
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error loading products from file '{filePath}'");
            }
        }));

        await _inventoryApi.UploadMergedProductsAsync(mergedProducts);

        return mergedProducts;
    }

    public class MergedProductCollection
    {
        private readonly List<Product> _products = new List<Product>();

        public void AddProduct(Product product)
        {
            _products.Add(product);
        }

        public List<Product> GetProducts()
        {
            return _products;
        }
    }
}

public interface ILogger
{
    void LogInformation(string message);
    void LogError(Exception ex, string message);
}

