const fs = require('fs');
const { PassThrough } = require('stream');

function mergeDataChunks(dataChunks, byteCount) {
  if (!dataChunks || dataChunks.length === 0) throw new Error('No data chunks provided');

  const mergedStream = new PassThrough({ encoding: 'utf8' });
  let totalBytesCopied = 0;

  async function processChunk(chunk) {
    try {
      const chunkSize = Buffer.byteLength(chunk);
      if (chunkSize !== byteCount) throw new Error('Chunk size does not match expected byte count');

      await new Promise((resolve, reject) => {
        mergedStream.write(chunk, error => {
          if (error) reject(error);
          else resolve();
        });
      });

      totalBytesCopied += chunkSize;
    } catch (error) {
      console.error('Error processing chunk:', error);
    }
  }

  dataChunks.forEach(processChunk);

  return new Promise((resolve, reject) => {
    mergedStream.on('end', () => {
      if (totalBytesCopied !== byteCount) throw new Error('Total bytes copied do not match expected count');

      resolve();
    });

    mergedStream.on('error', error => {
      console.error('Error merging data chunks:', error);
      reject(error);
    });
  });
}

async function logOperation(metadata) {
  try {
    await fs.promises.appendFile('operation_log.txt', JSON.stringify(metadata, null, 2));
  } catch (error) {
    console.error('Error logging operation:', error);
  }
}

function handleSimultaneousAccesses(concurrentOperationsLimit) {
  let concurrentOperations = 0;

  function acquireLock() {
    return new Promise((resolve, reject) => {
      if (concurrentOperations >= concurrentOperationsLimit) {
        setTimeout(() => resolve(acquireLock()), 100);
      } else {
        concurrentOperations++;
        resolve();
      }
    });
  }

  async function releaseLock() {
    await new Promise((resolve, reject) => {
      concurrentOperations--;
      if (concurrentOperations < 0) throw new Error('Invalid state');

      resolve();
    });
  }

  return { acquireLock, releaseLock };
}

const stream1 = fs.createReadStream('stream1.txt');
const stream2 = fs.createReadStream('stream2.txt');

// Simulate data chunks from multiple network streams
const dataChunks = [stream1.read(), stream2.read()];

// Merge and log the operation
mergeDataChunks(dataChunks, 1024).then(() => {
  const metadata = {
    sourceStreamID: 'stream1',
    byteRangeCopied: [0, 1024],
  };
  logOperation(metadata);
});

const concurrencyControl = handleSimultaneousAccesses(5);

// Simulate concurrent access
(async () => {
  for (let i = 0; i < 10; i++) {
    await concurrencyControl.acquireLock();
    try {
      // Perform operation that requires simultaneous access
      console.log('Concurrent operation performed');
    } finally {
      await concurrencyControl.releaseLock();
    }
  }
})();
