#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char str[100];
    double val;
} SubNode;

typedef struct {
    int value;
    SubNode* head;
    int size;
} Node;

Node* create_node(int value, int subnode_size) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->value = value;
    node->head = NULL;
    node->size = 0;

    for (int i = 0; i < subnode_size; i++) {
        SubNode* new_subnode = (SubNode*)malloc(sizeof(SubNode));
        if (!new_subnode) return NULL;

        new_subnode->str[0] = '\0';
        new_subnode->val = (double)rand() / RAND_MAX;
        char random_str[100];
        srand(time(NULL));
        for (int j = 0; j < 50; j++) {
            random_str[j] = (char)(rand() % ('z' - 'a' + 1)) + 'a';
        }
        random_str[50] = '\0';
        strcpy(new_subnode->str, random_str);

        if (!node->head) node->head = new_subnode;
        else {
            SubNode* current = node->head;
            for (int k = 0; current && k < node->size - 1; k++) {
                current = current->next;
            }
            new_subnode->next = current ? current : NULL;
            current->next = new_subnode;
        }

        node->size++;
    }

    return node;
}

void free_node(Node* node) {
    if (!node) return;

    SubNode* current = node->head;
    while (current) {
        SubNode* next = current->next;
        free(current);
        current = next;
    }
    free(node);
}

int main() {
    int array_size = 5;
    Node** nodes = (Node**)malloc(array_size * sizeof(Node*));
    if (!nodes) return -1;

    for (int i = 0; i < array_size; i++) {
        int value = rand() % 100;
        int subnode_size = 3;
        Node* node = create_node(value, subnode_size);
        nodes[i] = node;
    }

    // Use your nodes here...

    for (int i = 0; i < array_size; i++) {
        free_node(nodes[i]);
    }
    free(nodes);

    return 0;
}
