namespace SecureRandom {
    class SessionIDGenerator {
    public:
        static std::string generate() {
            if (!initialized_) {
                initialize();
            }
            std::uniform_int_distribution<int> distribution(0, 1);
            int bit = distribution(gen_);
            return ((bit << 31) ^ sessionID_) + base64_;
        }

        static void checkForDuplicate(const std::string& sessionID) {
            if (database_.count(sessionID) > 0) {
                regenerate();
            }
        }

    private:
        static std::mt19937_64 gen_;
        static std::chrono::time_point<std::chrono::system_clock> initializationTime_;
        static std::random_device randomDevice;
        static std::string base64_ = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

        static void initialize() {
            if (initialized_) return;

            // Securely seed the random number generator with current time and additional entropy
            auto entropy = randomDevice();
            gen_.seed(std::chrono::system_clock::now().time_since_epoch().count());
            gen_.seed(entropy);

            initialized_ = true;
        }

        static void regenerate() {
            while (true) {
                std::string sessionID = generate();
                if (!database_.count(sessionID)) {
                    return;
                }
            }
        }

    private:
        static bool initialized_;
        static std::unordered_map<std::string, int> database_;
        static std::mt19937_64& getGenerator() { return gen_; }
    };

    // Static member variables
    std::random_device SecureRandom::SessionIDGenerator::randomDevice;
    std::chrono::time_point<std::chrono::system_clock> SecureRandom::SessionIDGenerator::initializationTime_;
    bool SecureRandom::SessionIDGenerator::initialized_ = false;

    std::mt19937_64& SecureRandom::SessionIDGenerator::gen_ = SecureRandom::SessionIDGenerator::getGenerator();
