        await AuthenticateAndObtainToken();

        // Check if the file exists and is valid
        if (!File.Exists(filePath))
        {
            return new UploadResult(false, "File not found");
        }

        try
        {
            // Read the file in chunks to optimize memory usage
            byte[] buffer = new byte[4096];
            using (FileStream stream = File.OpenRead(filePath))
            {
                using (Aes aes = Aes.Create())
                {
                    aes.Key = encryptionKey;
                    aes.IV = iv;

                    int bytesRead;
                    using (MemoryStream ms = new MemoryStream())
                    {
                        do
                        {
                            bytesRead = stream.Read(buffer, 0, buffer.Length);
                            ms.Write(buffer, 0, bytesRead);
                        } while (bytesRead == buffer.Length);

                        // Upload the file in chunks to the cloud storage provider
                        await UploadFileChunkedAsync(ms.ToArray(), aes);
