            client = future.args[0]
            test_result = future.result()
            results[test_case_name] = test_result

    logger.info("API endpoint tests completed.")
    logger.info(f"Test summary for {app_name}:")
    for test_case, result in results.items():
        if isinstance(result, tuple):
