using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Serilog;

public class StringHasher
{
    private readonly ILogger _logger;
    private readonly HashAlgorithm _hashAlgorithm;
    private readonly Settings _settings;

    public StringHasher(Settings settings)
    {
        _settings = settings;
        _logger = new LoggerConfiguration()
            .WriteTo(_settings.LogFilePath, restrictedToMinimumLevel: LogEventLevel.Warning)
            .CreateLogger();
        _hashAlgorithm = _settings.HashAlgorithm == HashAlgorithm.MD5
            ? MD5.Create()
            : SHA256.Create();
    }

    public string HashSingleString(string input)
    {
        if (string.IsNullOrEmpty(input))
        {
            throw new ArgumentException("Input string cannot be null or empty.");
        }

        using var hash = _hashAlgorithm;
        var hashBytes = hash.ComputeHash(Encoding.UTF8.GetBytes(input));
        return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
    }

    public Dictionary<string, string> HashStringArray(string[] inputs)
    {
        if (inputs == null || inputs.Length == 0)
        {
            throw new ArgumentException("Input array cannot be null or empty.");
        }

        var hashResults = new Dictionary<string, string>();

        Parallel.ForEach(inputs, input =>
        {
            try
            {
                var hash = HashSingleString(input);
                lock (hashResults)
                {
                    hashResults.Add(input, hash);
                }
            }
            catch (Exception ex)
            {
                _logger.Error(ex, "Error hashing string: {Input}", input);
            }
        });

        return hashResults;
    }

    public void ValidateHashes(string[] inputs, Dictionary<string, string> knownHashes)
    {
        if (inputs == null || inputs.Length == 0)
        {
            throw new ArgumentException("Input array cannot be null or empty.");
        }

        if (knownHashes == null || knownHashes.Count == 0)
        {
            throw new ArgumentException("Known hashes dictionary cannot be null or empty.");
        }

        var errors = new List<string>();

        foreach (var input in inputs)
        {
            if (!knownHashes.ContainsKey(input))
            {
                errors.Add($"Unknown hash for string: {input}");
            }
            else
            {
                try
                {
                    var generatedHash = HashSingleString(input);
                    if (generatedHash != knownHashes[input])
                    {
                        errors.Add($"Hash mismatch for string: {input}. Expected: {knownHashes[input]}, Actual: {generatedHash}");
                    }
                }
                catch (Exception ex)
                {
                    _logger.Error(ex, "Error validating hash for string: {Input}", input);
                    errors.Add($"Error validating hash for string: {input}");
                }
            }
        }

        if (errors.Count > 0)
        {
            throw new Exception(string.Join("\n", errors));
        }
    }
}

public enum HashAlgorithm
{
    MD5,
    SHA256
}

public class Settings
{
    public string LogFilePath { get; set; }
    public HashAlgorithm HashAlgorithm { get; set; }
}
