task:
Write a C function named `loadResourceBundle` that loads a resource bundle from a file into a dynamically allocated structure. The function should support loading multiple types of resources (e.g., images, text files, audio files) and return a list of all item types along with their counts. Each resource type should be represented by an enum value. The function should take a path to the resource file as input and return a pointer to the allocated structure or an error code if necessary. 

The resource file is in a custom binary format where each resource entry is preceded by a 4-byte identifier indicating the type of resource and a 4-byte size. The function must read the file and correctly parse these entries, allocating memory for each resource and storing the counts of each type. 

Ensure the function handles large files efficiently, manages memory properly to avoid leaks, and supports concurrent access to the loaded resources by multiple threads. Implement thread-safe data structures and consider using locks or atomic operations when accessing the resource counts. 

Include comprehensive error handling for file I/O operations, invalid file formats, and insufficient memory. The function should gracefully handle partial reads and provide meaningful error messages. 

Provide a mechanism to free the allocated memory and ensure all resources are properly released. The function should also validate the resource file before parsing, ensuring it adheres to a predefined schema. 

The function signature should look like this:

```c
enum ResourceType { IMAGE, TEXT, AUDIO, NUM_TYPES };
typedef struct ResourceItem {
    enum ResourceType type;
    void* data;
} ResourceItem;

typedef struct ResourceBundle {
    ResourceItem* items;
    size_t itemCount[NUM_TYPES];
    size_t totalItemCount;
    pthread_mutex_t mutex; // For thread safety
} ResourceBundle;

ResourceBundle* loadResourceBundle(const char* filePath);
void freeResourceBundle(ResourceBundle* bundle);
```

response:
Here is the code block for the `loadResourceBundle` function:
```
ResourceBundle* loadResourceBundle(const char* filePath) {
    ResourceBundle* bundle = NULL;
    FILE* file = fopen(filePath, "rb");
    if (file == NULL) {
        return NULL; // Error opening file
    }

    enum ResourceType types[NUM_TYPES];
    size_t typeCounts[NUM_TYPES] = {0};
    pthread_mutex_init(&bundle->mutex, NULL);

    // Read and validate the resource bundle header
    fseek(file, 0, SEEK_END);
    size_t fileSize = ftell(file);
    rewind(file);
    if (fileSize < sizeof(enum ResourceType) * NUM_TYPES + sizeof(size_t)) {
        fclose(file);
        return NULL; // Invalid file format
    }

    fread(&bundle->totalItemCount, sizeof(size_t), 1, file);
    for (size_t i = 0; i < bundle->totalItemCount; ++i) {
        enum ResourceType type;
        size_t dataSize;
        fread(&type, sizeof(enum ResourceType), 1, file);
        fread(&dataSize, sizeof(size_t), 1, file);

        if (type >= NUM_TYPES) {
            fclose(file);
            freeResourceBundle(bundle);
            return NULL; // Invalid resource type
        }

        void* data = malloc(dataSize);
        if (data == NULL) {
            fclose(file);
            freeResourceBundle(bundle);
            return NULL; // Memory allocation error
        }

        fread(data, 1, dataSize, file);

        ResourceItem* item = malloc(sizeof(ResourceItem));
        if (item == NULL) {
            fclose(file);
            freeResourceBundle(bundle);
            return NULL; // Memory allocation error
        }
        item->type = type;
        item->data = data;

        bundle->items = realloc(bundle->items, sizeof(ResourceItem*) * ++bundle->totalItemCount);
        if (bundle->items == NULL) {
            fclose(file);
            freeResourceBundle(bundle);
            return NULL; // Memory allocation error
        }
        bundle->items[bundle->totalItemCount - 1] = item;

        typeCounts[type]++;
    }

    fclose(file);

    return bundle;
}
