import requests
import json
from functools import wraps
from time import sleep
from unittest.mock import patch

def rate_limited(max_retries=3):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for i in range(max_retries + 1):
                try:
                    return func(*args, **kwargs)
                except requests.exceptions.RequestException as e:
                    if i < max_retries - 1:
                        sleep(1)  # wait before retrying
                    else:
                        raise
        return wrapper
    return decorator

def cached(ttl=3600):  # 1 hour TTL
    def decorator(func):
        cache = {}
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = str(args) + str(kwargs)
            if key in cache and cache[key]['timestamp'] > time.time() - ttl:
                return cache[key]['result']
            result = func(*args, **kwargs)
            cache[key] = {'result': result, 'timestamp': time.time()}
            return result
        return wrapper
    return decorator

def fetch_weather(city):
    @rate_limited()
    def get_weather():
        url = f"https://api.openweathermap.org/data/2.5/weather?q={city}&units=metric"
        response = requests.get(url)
        response.raise_for_status()
        return json.loads(response.text)

    return get_weather()

def average_weather_data(weather_data):
    avg_temp = sum(city['main']['temp'] for city in weather_data) / len(weather_data)
    avg_humidity = sum(city['main']['humidity'] for city in weather_data) / len(weather_data)
    avg_wind_speed = sum(city['wind']['speed'] for city in weather_data) / len(weather_data)
    return {'average_temperature': avg_temp, 'average_humidity': avg_humidity, 'average_wind_speed': avg_wind_speed}

@patch('requests.get', side_effect=Exception('Failed to fetch weather data'))
def test_fetch_weather(mock_get):
    get_weather = fetch_weather('New York')
    get_weather()

if __name__ == '__main__':
    cities = ['New York', 'London', 'Paris']
    start_time = time.time()
    end_time = start_time + 60 * 30  # 30 minutes
    weather_data = []
    while time.time() < end_time:
        for city in cities:
            get_weather = fetch_weather(city)
            response = get_weather()
            weather_data.append(response)
            sleep(1)  # wait before querying next city

    average_results = average_weather_data(weather_data)
    print("Average Temperature:", average_results['average_temperature'])
    print("Average Humidity:", average_results['average_humidity'])
    print("Average Wind Speed:", average_results['average_wind_speed'])
