Here is the C program that reads and parses log entries in a streaming fashion:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 1024

struct LogEntry {
    char *line;
    int num_fields;
};

void* process_log_entry(void* arg) {
    struct LogEntry* entry = (struct LogEntry*)arg;

    // Calculate average of last two numeric fields
    double sum = 0.0;
    for(int i = entry->num_fields - 2; i < entry->num_fields; i++) {
        sum += atof(strchr(entry->line, ',') + strlen(","));
    }
    double avg = sum / (entry->num_fields - 2);

    // Append average to the end of the line
    char* new_line = malloc(MAX_LINE_LENGTH * sizeof(char));
    sprintf(new_line, "%s,%.2f", entry->line, avg);

    printf("%s\n", new_line);

    free(entry->line);
    free(new_line);

    return NULL;
}

int main() {
    FILE* log_file = fopen("log.txt", "r");
    if(log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        return 1;
    }

    pthread_t thread;
    while(1) {
        char line[MAX_LINE_LENGTH];
        fgets(line, MAX_LINE_LENGTH, log_file);

        struct LogEntry entry = {0};
        entry.line = strdup(line);
        entry.num_fields = 0;
        char* token = strtok(line, ",");
        while(token != NULL) {
            if(atof(token) == (double)atol(token)) {
                entry.num_fields++;
            }
            token = strtok(NULL, ",");
        }

        pthread_create(&thread, NULL, process_log_entry, &entry);
        pthread_join(thread, NULL);
    }

    fclose(log_file);
    return 0;
}
