using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class UpdateElementService
{
    private readonly ICacheService _cacheService;
    private readonly IMessageQueueService _messageQueueService;
    private readonly RateLimiter _rateLimiter;

    public UpdateElementService(ICacheService cacheService, IMessageQueueService messageQueueService, RateLimiter rateLimiter)
    {
        _cacheService = cacheService;
        _messageQueueService = messageQueueService;
        _rateLimiter = rateLimiter;
    }

    public async Task<IActionResult> UpdateElement(string sectionId, string elementId, string htmlContent)
    {
        if (!ValidateInput(sectionId, elementId, htmlContent))
        {
            return new BadRequestResult();
        }

        await _rateLimiter.WaitAndAcquire();

        try
        {
            await _cacheService.UpdateElementHtmlContent(sectionId, elementId, htmlContent);
            await _messageQueueService.EnqueueRefreshMessage();
            return new OkResult();
        }
        catch (Exception ex)
        {
            // Log the error and return an error response
            _logger.LogError(ex, "Error updating element");
            return new StatusCodeResult(500);
        }
    }

    private bool ValidateInput(string sectionId, string elementId, string htmlContent)
    {
        if (!Guid.TryParse(sectionId, out var _))
        {
            return false;
        }

        if (!Guid.TryParse(elementId, out var _))
        {
            return false;
        }

        try
        {
            new HtmlDocument(htmlContent);
        }
        catch (Exception ex)
        {
            // Log the error and return an error response
            _logger.LogError(ex, "Invalid HTML content");
            return false;
        }

        return true;
    }
}
