using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;

public class WebsiteAdder
{
    public async Task AddWebsite(string directoryPath, string siteName, int basePort)
    {
        // Validate inputs
        if (!Directory.Exists(directoryPath))
            throw new DirectoryNotFoundException($"The directory '{directoryPath}' was not found.");
        if (!IsValidSiteName(siteName))
            throw new ArgumentException("Invalid site name. It should not contain special characters.", nameof(siteName));

        // Check for web.config file existence
        if (File.Exists(Path.Combine(directoryPath, "web.config")))
        {
            try
            {
                using var process = Process.Start(new ProcessStartInfo("start", $"{directoryPath}/{siteName}.exe"))
                {
                    RedirectStandardOutput = true,
                    RedirectStandardError = true
                };

                // Wait for the process to finish or timeout
                await Task.Run(() =>
                {
                    int timeout = 30; // in seconds
                    while (process.WaitForExit(timeout * 1000))
                    {
                        if (!process.HasExited)
                            throw new OperationTimeoutException("Failed to start website within the allotted time.");
                    }
                });

                process.Dispose();
            }
            catch (Exception ex)
            {
                // Log any errors that occur during the process of adding or starting the site
                Console.WriteLine($"Error: {ex.Message}");
            }
        }
        else
        {
            try
            {
                // Integrate with external configuration management system to retrieve default settings for web server
                var config = await GetDefaultConfig();
                // Use retrieved config

                // Add website using retrieved config
                using var process = Process.Start(new ProcessStartInfo("start", $"{directoryPath}/{siteName}.exe"))
                {
                    RedirectStandardOutput = true,
                    RedirectStandardError = true
                };

                // Wait for the process to finish or timeout
                await Task.Run(() =>
                {
                    int timeout = 30; // in seconds
                    while (process.WaitForExit(timeout * 1000))
                    {
                        if (!process.HasExited)
                            throw new OperationTimeoutException("Failed to start website within the allotted time.");
                    }
                });

                process.Dispose();
            }
            catch (Exception ex)
            {
                // Log any errors that occur during the process of adding or starting the site
                Console.WriteLine($"Error: {ex.Message}");
            }
        }

        // Health check mechanism
        try
        {
            await Task.Delay(1000); // wait for 1 second
            using var process = Process.Start(new ProcessStartInfo("tasklist", "/fi \"imagename eq {siteName}.exe\""))
            {
                RedirectStandardOutput = true,
                RedirectStandardError = true
            };

            string output = await ReadProcessOutput(process);
            if (output == null || !output.Contains(siteName))
                throw new Exception($"Website '{siteName}' did not start properly.");
        }
        catch (Exception ex)
        {
            // Log any errors that occur during the health check mechanism
            Console.WriteLine($"Error: {ex.Message}");
        }

        // Clean up any resources used after the operation completes, even if an error occurs
        GC.Collect();
    }

    private async Task<string> ReadProcessOutput(Process process)
    {
        using var reader = new StreamReader(process.StandardOutput.BaseStream);
        return await reader.ReadToEndAsync();
    }
}
