```java
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.ReentrantLock;

public class DynamicResourcePoolManager {

    public interface ConnectionConfigCallback {
        ConnectionConfig apply(ConnectionConfig config);
    }

    private static final int DEFAULT_MIN_POOL_SIZE = 1;
    private static final int DEFAULT_MAX_POOL_SIZE = 10;
    private static final long DEFAULT_TIMEOUT_MILLIS = 30000L;

    private volatile AtomicInteger minPoolSize = new AtomicInteger(DEFAULT_MIN_POOL_SIZE);
    private volatile AtomicInteger maxPoolSize = new AtomicInteger(DEFAULT_MAX_POOL_SIZE);
    private volatile Long connectionTimeout = DEFAULT_TIMEOUT_MILLIS;
    private final ReentrantLock lock = new ReentrantLock();
    private final Random random = new Random();

    public void initializeResourcePool(int minConnections, int maxConnections, long timeout) {
        if (minConnections < 1 || maxConnections < 1) {
            throw new IllegalArgumentException("Minimum and maximum number of connections must be greater than zero");
        }
        if (timeout <= 0) {
            throw new IllegalArgumentException("Connection timeout must be positive");
        }

        lock.lock();
        try {
            minPoolSize.set(minConnections);
            maxPoolSize.set(maxConnections);
            connectionTimeout = timeout;
        } finally {
            lock.unlock();
        }
    }

    public void initializeResourcePool(int minConnections, int maxConnections) {
        initializeResourcePool(minConnections, maxConnections, DEFAULT_TIMEOUT_MILLIS);
    }

    public ConnectionConfig configureConnectionPool(ConnectionConfigCallback callback) {
        ConnectionConfig config = new ConnectionConfig(minPoolSize.get(), maxPoolSize.get(), connectionTimeout);
        return callback.apply(config);
    }
}
