using System.Threading.Tasks;
using Newtonsoft.Json;
using System.Security.Cryptography;

namespace AESDecryption
{
    public class Program
    {
        private static readonly HttpClient client = new HttpClient();
        private static readonly string apiKey = "YOUR_API_KEY";
        private static readonly string apiEndpoint = "https://api.your-encryption-service.com/keys";

        public static async Task Main(string[] args)
        {
            await LoadConfigAsync("config.xml");
            foreach (var ciphertext in ReadCiphertextsFromFile("ciphertexts.txt"))
            {
                var keyAndIv = await GetKeyAndIvAsync();
                var plaintext = DecryptCiphertext(ciphertext, keyAndIv.Key, keyAndIv.IV);
                Console.WriteLine($"Decrypted: {plaintext}");
            }
        }

        private static async Task LoadConfigAsync(string configFile)
        {
            var config = JsonConvert.DeserializeObject<Config>(File.ReadAllText(configFile));
            // Initialize game parameters based on the loaded configuration
            Console.WriteLine("Game parameters initialized.");
        }

        private static async Task<(string Key, string IV)> GetKeyAndIvAsync()
        {
            client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue(apiKey);
            try
            {
                var response = await client.GetAsync(apiEndpoint);
                if (response.IsSuccessStatusCode)
                {
                    var responseBody = await response.Content.ReadAsStringAsync();
                    var keyAndIvResponse = JsonConvert.DeserializeObject<KeyAndIvResponse>(responseBody);
                    return (keyAndIvResponse.Key, keyAndIvResponse.IV);
                }
                else
                {
                    Console.WriteLine("Failed to retrieve encryption key and IV. Please check your API credentials.");
                    throw new Exception("Failed to retrieve encryption key and IV.");
                }
            }
            catch (HttpRequestException ex)
            {
                Console.WriteLine("Error communicating with the API: " + ex.Message);
                throw;
            }
        }

        private static string DecryptCiphertext(string ciphertext, string key, string iv)
        {
            var aes = Aes.Create();
            aes.Key = Convert.FromBase64String(key);
            aes.IV = Convert.FromBase64String(iv);
            using (var memoryStream = new MemoryStream(Convert.FromBase64String(ciphertext)))
            {
                using (var cryptoStream = new CryptoStream(memoryStream, aes.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    var buffer = new byte[1024];
                    int bytesRead;
                    StringBuilder plaintext = new StringBuilder();
                    while ((bytesRead = cryptoStream.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        plaintext.Append(Encoding.UTF8.GetString(buffer, 0, bytesRead));
                    }
                    return plaintext.ToString();
                }
            }
        }

        private static string[] ReadCiphertextsFromFile(string filename)
        {
            try
            {
                return File.ReadAllLines(filename);
            }
            catch (IOException ex)
            {
                Console.WriteLine("Failed to read ciphertexts from file: " + ex.Message);
                throw;
            }
        }
    }

    public class Config
    {
        public int TileSize { get; set; }
        public int WorldWidth { get; set; }
        public int WorldHeight { get; set; }
        public double CameraSpeed { get; set; }
    }

    public class KeyAndIvResponse
    {
        public string Key { get; set; }
        public string IV { get; set; }
    }
