```javascript
function renderFooter(scripts) {
  const cache = {};
  const cacheExpirationTime = 30000; // 30 seconds
  let currentScriptLoading = 0;
  let pendingScripts = [];

  function fetchScript(script) {
    return new Promise((resolve, reject) => {
      if (cache[script.key]) {
        resolve(cache[script.key]);
      } else {
        const scriptTag = document.createElement('script');
        scriptTag.type = 'text/javascript';
        scriptTag.innerHTML = script.code;
        scriptTag.src = script.src;
        scriptTag.async = true;

        fetchScriptLoading++;

        fetch(script.src)
          .then(response => response.text())
          .then(html => {
            scriptTag.innerHTML = html;
            resolve(html);
          })
          .catch(error => {
            reject(error);
          })
          .finally(() => {
            fetchScriptLoading--;
          });
      }
    });
  }

  function renderScripts() {
    return scripts.map((script) => {
      if (script.key in cache) {
        const cachedScript = cache[script.key];
        return cachedScript;
      } else {
        pendingScripts.push(script);
        return '';
      }
    }).join('');
  }

  function updateFooter() {
    document.getElementById('footer').innerHTML = renderScripts();
  }

  function manageCache() {
    setTimeout(() => {
      Object.keys(cache).forEach((key) => {
        if (Date.now() - cache[key].timestamp > cacheExpirationTime) {
          delete cache[key];
        }
      });
      updateFooter();
    }, cacheExpirationTime);
  }

  let fetchScriptLoading = 0;

  scripts.forEach((script) => {
    if (!('code' in script || 'src' in script)) {
      console.error('Invalid script object:', script);
      return;
    }

    fetchScript(script)
      .then((html) => {
        cache[script.key] = { html, timestamp: Date.now() };
        updateFooter();
      })
      .catch((error) => {
        console.error('Error fetching script:', error);
      });
  });

  manageCache();

  return renderScripts();
}

// Example usage
const scripts = [
  { key: 'script1', code: 'console.log("Hello!");' },
  { key: 'script2', src: 'https://example.com/script2.js' },
  { key: 'script3', code: 'console.log("Goodbye!");' },
];

document.getElementById('footer').innerHTML = renderFooter(scripts);
