Here is a Node.js application that dynamically loads and executes multiple JavaScript modules in a specified order:

```javascript
const { readFileSync } = require('fs');
const { resolve } = require('path');
const { load } = require('@loaderjs/loader');

const config = JSON.parse(readFileSync(resolve(__dirname, 'config.json'), 'utf8'));

async function loadModules() {
  const loader = new load({
    paths: [resolve(__dirname, 'modules')],
  });

  let modules = [];
  for (let i = 0; i < config.length; i++) {
    try {
      const module = await loader.load(config[i]);
      modules.push(module);
    } catch (error) {
      console.error(`Error loading module ${config[i]}: ${error}`);
    }
  }

  return Promise.all(modules.map((module, index) => {
    if (index === config.length - 1) {
      // execute the last module
      return module();
    }
    return new Promise((resolve, reject) => {
      module().then(() => resolve()).catch((error) => {
        console.error(`Error executing module ${config[i]}: ${error}`);
        reject(error);
      });
    });
  }));
}

loadModules();

