Here is a C function that parses a TIFF image file:

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    int extraSamples;
} TiffInfo;

TiffInfo parseTIFF(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        return (TiffInfo){-1, -1, -1}; // error
    }

    // Read the TIFF header
    unsigned short int tiffHeader[2];
    fread(tiffHeader, 2, 1, file);

    TiffInfo info;
    if (tiffHeader[0] == 0x002A) {
        info.bitsPerSample = 8;
    } else if (tiffHeader[0] == 0x100C || tiffHeader[0] == 0x1010) {
        info.bitsPerSample = 16;
    } else if (tiffHeader[0] == 0x1012 || tiffHeader[0] == 0x1016) {
        info.bitsPerSample = 32;
    } else if (tiffHeader[0] == 0x103A) {
        info.bitsPerSample = 64;
    } else {
        fclose(file);
        return (TiffInfo){-1, -1, -1}; // error
    }

    fread(&info.samplesPerPixel, sizeof(info.samplesPerPixel), 1, file);

    int extraSamples = 0;
    while (fread(&extraSamples, sizeof(extraSamples), 1, file)) {
        if (extraSamples > 0) {
            info.extraSamples += extraSamples;
        } else {
            break; // end of extra samples
        }
    }

    fclose(file);

    return info;
}

int main() {
    TiffInfo info = parseTIFF("example.tiff");
    if (info.bitsPerSample == -1) {
        printf("Error parsing TIFF file: %s\n", "Invalid or corrupted file");
    } else {
        printf("Bits per sample: %d, Samples per pixel: %d, Extra samples: %d\n",
               info.bitsPerSample, info.samplesPerPixel, info.extraSamples);
    }
    return 0;
}
