import os
import tempfile
import time
import platform

def create_directory(directory_name, parent_directory=None):
    if parent_directory:
        full_path = os.path.join(parent_directory, directory_name)
    else:
        full_path = directory_name

    while True:
        try:
            os.makedirs(full_path)
            break
        except FileExistsError:
            pass
        except OSError as e:
            if platform.system() == 'Windows' and (e.winerror == 2 or e.winerror == 5):
                time.sleep(1)
            elif e.errno == 28:  # ENOSPC - no space left on device
                time.sleep(1)
            else:
                raise

    if parent_directory:
        full_path = os.path.dirname(full_path)

    os.environ['NEW_DIR'] = full_path

    temp_dir = tempfile.TemporaryDirectory()
    try:
        yield
    finally:
        for filename in os.listdir(temp_dir.name):
            file_path = os.path.join(temp_dir.name, filename)
            if not os.path.isdir(file_path):
                os.remove(file_path)
        temp_dir.cleanup()

if __name__ == "__main__":
    with create_directory('my_new_dir', 'path_to_parent_dir') as _:
        print(os.environ['NEW_DIR'])
