from flask import Flask, request, jsonify
from flask_caching import Cache
from flask_limiter import Limiter
from flask_limiter.util import get_remote_address
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config["SQLALCHEMY_DATABASE_URI"] = "sqlite:///database.db"
db = SQLAlchemy(app)

limiter = Limiter(
    app,
    key_func=get_remote_address,
    default_limits=["200 per hour", "50 per minute"]
)

cache = Cache(app, config={"CACHE_TYPE": "SimpleCache"})

# Resource model
class Resource(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    data = db.Column(db.String)
    version = db.Column(db.Integer, default=1)
    timestamp = db.Column(db.DateTime, default=db.func.current_timestamp())

@app.route('/resources/<int:resource_id>', methods=['PUT'])
@limiter.limit("10 per minute")
def update_resource(resource_id):
    resource = Resource.query.get_or_404(resource_id)
    if request.is_json:
        data = request.get_json()
        if resource.version != 1 or (data and "version" in data and data["version"] == 1):
            return jsonify({"error": "Precondition failed"}), 412
        resource.data = data.get("data", "")
        resource.version += 1
        db.session.commit()
        return jsonify({"message": f"Resource {resource_id} updated successfully."})

@app.route('/resources/<int:resource_id>', methods=['DELETE'])
@limiter.limit("5 per minute")
def delete_resource(resource_id):
    resource = Resource.query.get_or_404(resource_id)
    if request.is_json:
        data = request.get_json()
        if "version" in data and data["version"] == resource.version:
            db.session.delete(resource)
            db.session.commit()
            return jsonify({"message": f"Resource {resource_id} deleted successfully."})
        else:
            return jsonify({"error": "Conflict"}), 409
    return jsonify({"error": "Invalid request"}), 400

if __name__ == "__main__":
    app.run(debug=True)

