#include <openssl/aes.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function prototypes
void* encrypt_file(const char* filepath, const char* cipher_name, int chunk_size, void (*progress)(int), const char* output_filepath);
void progress_callback(int percent);

int main() {
    // Example usage:
    const char* filepath = "path/to/file.txt";
    const char* cipher_name = "AES-256-CBC";
    int chunk_size = 4096;
    void (*progress)(int) = &progress_callback;
    const char* output_filepath = "encrypted_file.txt";

    encrypt_file(filepath, cipher_name, chunk_size, progress, output_filepath);

    return 0;
}

void* encrypt_file(const char* filepath, const char* cipher_name, int chunk_size, void (*progress)(int), const char* output_filepath) {
    // Validate input file path and command line options
    if (!filepath || !cipher_name) {
        printf("Error: Invalid input.\n");
        return NULL;
    }

    // Initialize OpenSSL library
    OpenSSL_add_all_algorithms();
    RAND_load_file("randomseed", 1024);

    // Load the specified cipher
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    int mode = EVP_MODE_CBC; // or EVP_MODE_GCM, etc.
    if (!EVP_CipherInit_ex(ctx, cipher_name, NULL, NULL, mode)) {
        printf("Error: Unable to initialize cipher.\n");
        return NULL;
    }

    // Open the input file
    FILE* in_file = fopen(filepath, "rb");
    if (!in_file) {
        printf("Error: Unable to open input file.\n");
        return NULL;
    }

    // Create a buffer for reading and encryption
    unsigned char* buffer = malloc(chunk_size);
    size_t buffer_size = chunk_size;

    // Read the file in chunks and encrypt
    FILE* out_file = fopen(output_filepath, "wb");
    if (!out_file) {
        printf("Error: Unable to open output file.\n");
        return NULL;
    }

    int processed_bytes = 0;
    while (1) {
        size_t read_size = fread(buffer, 1, buffer_size, in_file);
        if (read_size == 0) break;

        // Encrypt the chunk
        unsigned char* encrypted = malloc(read_size);
        int encrypted_len = EVP_EncryptUpdate(ctx, encrypted, &encrypted_len, buffer, read_size);

        // Write the encrypted chunk to the output file
        fwrite(encrypted, 1, encrypted_len, out_file);

        // Update progress callback
        processed_bytes += read_size + encrypted_len;
        (*progress)(100 * (processed_bytes / (double)file_size));

        free(buffer);
        buffer = malloc(chunk_size);
    }

    fclose(in_file);
    fclose(out_file);
    EVP_CIPHER_CTX_free(ctx);
    free(buffer);

    return NULL;
}

void progress_callback(int percent) {
    printf("Encrypted %d%% of file.\n", percent);
}
