using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using Microsoft.Extensions.Logging;

public class BinaryDataLoader
{
    private readonly ILogger _logger;
    private readonly Func<string, Stream> _streamProvider;

    public BinaryDataLoader(ILogger<BinaryDataLoader> logger, Func<string, Stream> streamProvider)
    {
        _logger = logger;
        _streamProvider = streamProvider;
    }

    public T LoadAndDeserialize<T>(string filename) where T : class
    {
        try
        {
            using var stream = _streamProvider(filename);
            if (stream == null || !stream.CanRead)
                throw new InvalidOperationException("Cannot read from file");

            BinaryFormatter formatter = new();
            T data = (T)formatter.Deserialize(stream);

            return data;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error loading and deserializing binary data");
            throw;
        }
    }
}
