using Service;

public class UpdateElementContent
{
    private readonly IEncryptionService _encryptionService;
    private readonly IRateLimiter _rateLimiter;
    private readonly ILogger _logger;
    private readonly HashSet<string> _allowedTags;
    private readonly Dictionary<string, HashSet<string>> _allowedAttributes;

    public UpdateElementContent(IEncryptionService encryptionService, IRateLimiter rateLimiter, ILogger logger)
    {
        _encryptionService = encryptionService;
        _rateLimiter = rateLimiter;
        _logger = logger;
        _allowedTags = new HashSet<string> { "p", "span", "div", "img" };
        _allowedAttributes = new Dictionary<string, HashSet<string>>
        {
            {"p", new HashSet<string> { "style", "class" }},
            {"span", new HashSet<string> { "style", "class" }},
            {"div", new HashSet<string> { "style", "class" }},
            {"img", new HashSet<string> { "src", "alt", "width", "height" }}
        };
    }

    [HttpPost]
    public ActionResult UpdatePageSection(string sectionId, string elementId, string htmlContent)
    {
        if (!_rateLimiter.AllowRequest())
        {
            return HttpUnauthorizedResult("Rate limit exceeded. Please try again later.");
        }

        try
        {
            // Decrypt HTML content using Triple DES encryption with the given key and IV
            byte[] encryptedBytes = Convert.FromBase64String(htmlContent);
            byte[] decryptedBytes = _encryptionService.Decrypt(encryptedBytes, "your_key", "your_iv");

            // Validate decrypted HTML content against the whitelist of allowed tags and attributes
            if (!ValidateHtml(decryptedBytes))
            {
                return HttpNotFoundResult("Invalid HTML content. Please ensure it only contains allowed tags and attributes.");
            }

            // Update element's HTML content in the database
            DatabaseService.UpdateElementContent(sectionId, elementId, decryptedBytes);

            // Log update with timestamp for auditing purposes
            _logger.LogInformation($"Updated element '{elementId}' in section '{sectionId}' at {DateTime.Now}.");

            return Ok("Update successful.");
        }
        catch (Exception ex)
        {
            // Handle errors gracefully and provide meaningful error messages
            _logger.LogError(ex, $"Error updating element '{elementId}' in section '{sectionId}'.");
            return HttpNotFoundResult("An unexpected error occurred. Please try again later.");
        }
    }

    private bool ValidateHtml(byte[] htmlBytes)
    {
        string htmlContent = Encoding.UTF8.GetString(htmlBytes);
        HtmlAgilityPack.HtmlDocument doc = new HtmlAgilityPack.HtmlDocument();
        doc.LoadHtml(htmlContent);

        foreach (var node in doc.DocumentNode.Descendants())
        {
            if (!_allowedTags.Contains(node.Name) || !IsValidAttributes(node))
            {
                return false;
            }
        }

        return true;
    }

    private bool IsValidAttributes(HtmlAgilityPack.HtmlNode node)
    {
        foreach (var attribute in node.Attributes)
        {
            string attributeName = attribute.Name.ToLower();
            if (!_allowedAttributes.ContainsKey(node.Name) || !_allowedAttributes[node.Name].Contains(attributeName))
            {
                return false;
            }
        }

        return true;
    }
}
