#include <condition_variable>

class OctreeNode {
public:
    OctreeNode(int capacity, int depth) : capacity(capacity), depth(depth), data_(nullptr) {}

    ~OctreeNode() {
        if (data_) delete[] data_;
        for (int i = 0; i < 8; ++i) {
            children_[i] = nullptr;
        }
    }

    void split() {
        int newCapacity = capacity * 2 / 3;
        int newNodeSize = sizeof(int) * (newCapacity + 7) / 8 * 8;
        int* newData = new int[newNodeSize];
        for (int i = 0; i < capacity; ++i) {
            newData[i] = data_[i];
        }
        data_ = nullptr;

        children_.resize(8);
        for (int i = 0; i < 8; ++i) {
            children_[i] = new OctreeNode(newCapacity, depth + 1);
        }

        delete[] data_;
    }

    void insert(int point, int value) {
        if (!data_) {
            data_ = new int[capacity];
            for (int i = 0; i < capacity; ++i) {
                data_[i] = -1;
            }
        }

        int index = findIndex(point);
        if (index != -1 && data_[index] == -1) {
            data_[index] = value;
        } else if (depth > 0) {
            for (int i = 0; i < 8; ++i) {
                if (!children_[i]->insert(point, value)) {
                    split();
                    return children_[i]->insert(point, value);
                }
            }
        }
    }

    int findIndex(int point) {
        // Implement your own spatial partitioning algorithm here
        // For simplicity, assume the point is stored in a simple array
        if (point <= capacity / 2) {
            return 0;
        } else {
            return 1;
        }
    }

private:
    int capacity;
    int depth;
    std::unique_ptr<int[]> data_;
    std::vector<std::unique_ptr<OctreeNode>> children_;
};

class Octree {
public:
    Octree(int capacity, int maxDepth) : root_(new OctreeNode(capacity, 0)), maxDepth(maxDepth) {}

    ~Octree() {
        if (root_) delete root_;
    }

    void insert(int point, int value) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (!root_->insert(point, value)) {
            throw std::runtime_error("Error inserting data");
        }
    }

private:
    std::unique_ptr<OctreeNode> root_;
    std::mutex mutex_;
};

int main() {
    Octree octree(1024, 6);
    // Insert data points into the octree
    return 0;
}
