#include <vector>
#include <stdexcept>

double findLargestAverage(const std::string& filename) {
    std::ifstream file(filename);

    if (!file.is_open()) {
        throw std::runtime_error("Failed to open the file");
    }

    int max = INT_MIN;
    double sum = 0.0;

    while (file >> max) {
        sum += max;
    }

    file.close();

    return {max, sum / static_cast<double>(max)};
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <filename>\n";
        return 1;
    }

    try {
        auto result = findLargestAverage(argv[1]);
        std::cout << "The largest integer is: " << result.first << "\n";
        std::cout << "The average of all integers in the file is: " << result.second << "\n";
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
        return 1;
    }

    return 0;
}
