void create_semaphore(int value) {
    sem_t* semaphore = (sem_t*)malloc(sizeof(sem_t));
    if (sem_init(semaphore, 1, value) == -1) {
        perror("sem_init");
        free(semaphore);
        exit(EXIT_FAILURE);
    }
}

int sem_wait(sem_t* semaphore, int timeout) {
    struct timespec ts;
    ts.tv_sec = timeout / 1000;
    ts.tv_nsec = (timeout % 1000) * 1000000;

    if (sem_timedwait(semaphore, &ts) == -1) {
        perror("sem_wait");
        return -1;
    }

    return 0;
}

int sem_post(sem_t* semaphore) {
    if (sem_post(semaphore) == -1) {
        perror("sem_post");
        return -1;
    }

    return 0;
}

int sem_getvalue(sem_t* semaphore, int* value) {
    if (sem_getvalue(semaphore, value) == -1) {
        perror("sem_getvalue");
        return -1;
    }

    return 0;
}

void destroy_semaphore(sem_t* semaphore) {
    sem_destroy(semaphore);
    free(semaphore);
}
