using System;
using System.Collections.Generic;
using System.Linq;

public class DataPointGenerator
{
    private double _minValue;
    private double _maxValue;
    private readonly Random _random = new Random();

    public DataPointGenerator(double minValue, double maxValue)
    {
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public double GetRandomFloat()
    {
        return _random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public int GetRandomInt()
    {
        return _random.Next((int)_minValue, (int)_maxValue);
    }

    public List<int> GenerateDataPoints(int count)
    {
        return Enumerable.Range(0, count).Select(_ => GetRandomInt()).ToList();
    }

    public override string ToString()
    {
        return $"Range: [{_minValue}, {_maxValue}]";
    }

    private void ValidateRange()
    {
        if (_minValue > _maxValue)
            throw new ArgumentException("Minimum value must be less than or equal to the maximum value.");
    }
}

public static class HtmlExtensions
{
    public static IEnumerable<HtmlElement> SelectMatchingElements(HtmlElement node, string selector, Func<HtmlElement, bool> predicate)
    {
        var elements = new List<HtmlElement>();
        var stack = new Stack<HtmlElement>();
        stack.Push(node);

        while (stack.Any())
        {
            node = stack.Pop();
            if (node.NodeType == HtmlNodeType.Element && predicate((HtmlElement)node))
                elements.Add((HtmlElement)node);
            foreach (var child in node.ChildNodes)
            {
                if (child.NodeType == HtmlNodeType.Element)
                    stack.Push(child);
            }
        }

        return elements;
    }
}

public enum HtmlNodeType
{
    Element,
    Attribute,
    Text,
    Comment,
    Document
}

public class HtmlElement : IComparable<HtmlElement>
{
