#include <iostream>
#include <fstream>
#include <string>
#include "rapidjson/document.h"
#include "rapidjson/filewriter.h"
#include "rapidjson/filereader.h"

class Node {
public:
    int key;
    std::string value;

    Node(int k, const std::string& v) : key(k), value(v) {}
};

class NodeArray {
private:
    Node** nodes;
    int size;
    int capacity;
    int resizeThreshold;
    int writeCount;
    std::ofstream logFile;

public:
    NodeArray() : size(0), capacity(2), resizeThreshold(5), writeCount(0) {}

    ~NodeArray() {
        for (int i = 0; i < size; ++i)
            delete nodes[i];
        delete[] nodes;
    }

    void initialize(const std::string& filename) {
        try {
            std::ifstream file(filename);
            if (!file.is_open())
                throw std::runtime_error("File not found");

            rapidjson::Document doc, *document = &doc;
            file >> *document;

            for (int i = 0; i < document->Size(); ++i) {
                Node* node = new Node(document[i]["key"].GetInt(), document[i]["value"].GetString());
                if (nodes == nullptr)
                    nodes = new Node*[2];
                else if (size >= capacity) {
                    capacity *= 2;
                    Node** newNodeArray = new Node*[capacity];
                    for (int j = 0; j < size; ++j)
                        newNodeArray[j] = nodes[j];
                    delete[] nodes;
                    nodes = newNodeArray;
                }
                nodes[size++] = node;
            }

        } catch (const std::exception& e) {
            std::cerr << "Error initializing: " << e.what() << '\n';
        }
    }

    void serialize(const std::string& filename) const {
        try {
            rapidjson::FileWriter<rapidjson::FileWriteMode> writer(filename);
            writer.SetIndent("", 2);

            for (int i = 0; i < size; ++i)
                writer.StartObject().AddMember("key", nodes[i]->key, writer.ValueType::kString).AddMember("value", nodes[i]->value.c_str(), writer.ValueType::kString).Finish();

        } catch (const std::exception& e) {
            std::cerr << "Error serializing: " << e.what() << '\n';
        }
    }

    void deserialize(const std::string& filename) {
        try {
            rapidjson::FileReader reader(filename);
            if (!reader.IsOpen())
                throw std::runtime_error("File not found");

            rapidjson::Document doc, *document = &doc;
            reader >> *document;

            for (int i = 0; i < document->Size(); ++i) {
                Node* node = new Node(document[i]["key"].GetInt(), document[i]["value"].GetString());
                if (nodes == nullptr)
                    nodes = new Node*[2];
                else if (size >= capacity) {
                    capacity *= 2;
                    Node** newNodeArray = new Node*[capacity];
                    for (int j = 0; j < size; ++j)
                        newNodeArray[j] = nodes[j];
                    delete[] nodes;
                    nodes = newNodeArray;
                }
                nodes[size++] = node;
            }

        } catch (const std::exception& e) {
            std::cerr << "Error deserializing: " << e.what() << '\n';
        }
    }

    void addNode(int key, const std::string& value) {
        Node* newNode = new Node(key, value);
        if (nodes == nullptr)
            nodes = new Node*[2];
        else if (size >= capacity) {
            capacity *= 2;
            Node** newNodeArray = new Node*[capacity];
            for (int j = 0; j < size; ++j)
                newNodeArray[j] = nodes[j];
            delete[] nodes;
            nodes = newNodeArray;
        }
        nodes[size++] = newNode;

        writeCount++;
    }

    void removeNode(int key) {
        for (int i = 0; i < size; ++i) {
            if (nodes[i]->key == key) {
                delete nodes[i];
                std::swap(nodes[i], nodes[--size]);
                break;
            }
        }

        writeCount++;
    }

    void updateNode(int key, const std::string& value) {
        for (int i = 0; i < size; ++i) {
            if (nodes[i]->key == key) {
                delete nodes[i];
                nodes[i] = new Node(key, value);
                break;
            }
        }

        writeCount++;
    }

    void logOperation(const std::string& operation) {
        logFile << operation << '\n';
        logFile.flush();
    }
};

int main() {
    NodeArray nodeArray;

    nodeArray.initialize("nodes.json");
    nodeArray.serialize("nodes.json");

    while (true) {
        std::cout << "1. Add node\n2. Remove node\n3. Update node\n4. View nodes\n5. Exit\n";
        int choice;
        std::cin >> choice;

        switch (choice) {
            case 1: {
                int key;
                std::string value;
                std::cout << "Enter key and value: ";
                std::cin >> key >> value;
                nodeArray.addNode(key, value);
                break;
            }
            case 2: {
                int key;
                std::cout << "Enter key to remove: ";
                std::cin >> key;
                nodeArray.removeNode(key);
                break;
            }
            case 3: {
                int key;
                std::string value;
                std::cout << "Enter key and new value: ";
                std::cin >> key >> value;
                nodeArray.updateNode(key, value);
                break;
            }
            case 4:
                for (int i = 0; i < nodeArray.size; ++i)
                    std::cout << nodes[i]->key << ": " << nodes[i]->value.c_str() << '\n';
                break;
            case 5: {
                // Write database and log files
                // Close the application
                return 0;
            }
        }
    }

    return 0;
}
