import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

import org.apache.commons.io.IOUtils;
import org.json.JSONArray;
import org.json.JSONObject;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.http.HttpMethod;
import org.springframework.http.client.HttpComponentsClientHttpRequestFactory;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

@SpringBootApplication
@RestController
public class PokemonService {

    @Value("${pokemon.api.url}")
    private String pokemonApiUrl;

    @Value("${pokemon.config.file.path}")
    private String configFilePath;

    private ExecutorService executorService = Executors.newFixedThreadPool(10);

    public static void main(String[] args) {
        SpringApplication.run(PokemonService.class, args);
    }

    @GetMapping("/pokemons")
    public String generateReport() throws IOException {

        List<Pokemon> pokemons = new ArrayList<>();

        // Fetch Pokemon details from API
        JSONArray response = executeApiCall(pokemonApiUrl);

        for (int i = 0; i < response.length(); i++) {
            JSONObject pokemonJson = response.getJSONObject(i);
            Pokemon pokemon = new Pokemon(pokemonJson.getString("name"), pokemonJson.getString("type"));

            // Fetch weaknesses for the Pokémon
            JSONArray weaknessesResponse = executeApiCall(pokemonApiUrl + "/weaknesses/" + pokemon.getType());
            if (weaknessesResponse.length() > 0) {
                JSONObject weaknessesJson = weaknessesResponse.getJSONObject(0);
                pokemon.setWeaknesses(getWeaknesses(weaknessesJson));
            } else {
                // Handle case where Pokémon type does not have defined weaknesses
                pokemon.setWeaknesses(new ArrayList<>());
            }

            pokemons.add(pokemon);
        }

        // Generate HTML report
        StringBuilder report = new StringBuilder("<html><body>");
        for (Pokemon pokemon : pokemons) {
            report.append("<h2>").append(pokemon.getName()).append("</h2>");
            report.append("<ul>");
            for (String weakness : pokemon.getWeaknesses()) {
                report.append("<li>").append(weakness).append("</li>");
            }
            report.append("</ul>");
        }
        report.append("</body></html>");

        return report.toString();
    }

    private JSONArray executeApiCall(String url) throws IOException {

        HttpComponentsClientHttpRequestFactory client = new HttpComponentsClientHttpRequestFactory();
        org.springframework.http.HttpRequest request = org.springframework.http.HttpMethod.GET.buildRequest(url, null);
        org.springframework.http.client.ClientHttpResponse response = client.execute(request);

        return new JSONArray(IOUtils.toString(response.getBody(), "UTF-8"));
    }

    private List<String> getWeaknesses(JSONObject weaknessesJson) {
        List<String> weaknesses = new ArrayList<>();
        int typeIndex = weaknessesJson.names().indexOf("type");
        if (typeIndex != -1) {
            String type = weaknessesJson.getString(typeIndex);
            switch (type) {
                case "grass":
                    weaknesses.add("poison");
                    weaknesses.add("fire");
                    break;
                // Add more cases for other types
                default:
                    // Handle unknown type
                    weaknesses.add("unknown");
            }
        } else {
            // Handle malformed response
            weaknesses.add("error");
        }
        return weaknesses;
    }

    @Bean
    public ExecutorService executorService() {
        return this.executorService;
    }
}

class Pokemon {
    private String name;
    private String type;
    private List<String> weaknesses;

    public Pokemon(String name, String type) {
        this.name = name;
        this.type = type;
    }

    public String getName() {
        return name;
    }

    public String getType() {
        return type;
    }

    public List<String> getWeaknesses() {
        return weaknesses;
    }

    public void setWeaknesses(List<String> weaknesses) {
        this.weaknesses = weaknesses;
    }
}
