<?php
class ClinicManager {
    private $registry = [];
    private $logger;
    private $rateLimit = 5; // updates per minute
    private $lastUpdateTime;

    public function __construct(LoggerInterface $logger) {
        $this->logger = $logger;
        $this->lastUpdateTime = time();
    }

    public function updateClinicStatus(int $clinicId, string $status): bool {
        if (!$this->validateClinicId($clinicId)) {
            return false;
        }

        if (!is_in_range($this->lastUpdateTime, $this->rateLimit * 60)) { // rate limiting
            sleep(1); // wait for a second before proceeding with the update
            return false;
        }

        try {
            $db = Db::getInstance();
            $transaction = $db->beginTransaction();

            try {
                $query = "UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE id = ?";
                $result = $db->prepare($query);
                $result->execute([$status, $_SERVER['REMOTE_ADDR'], date('Y-m-d H:i:s'), $clinicId]);

                $transaction->commit();
            } catch (Exception $e) {
                $transaction->rollBack();
                $this->logger->error("Error updating clinic status: " . $e->getMessage());
                return false;
            }
        } finally {
            $this->lastUpdateTime = time(); // update last updated timestamp
        }

        return true;
    }

    public function convertToJSON(Clinic $clinic): string {
        return json_encode($clinic);
    }

    public function createFromJSON(string $json): Clinic {
        $data = json_decode($json, true);

        if (!isset($data['id'])) {
            throw new \Exception("Invalid JSON: missing clinic ID");
        }

        // get the factory function based on the clinic ID
        $factoryFunction = $this->registry[$data['id']];

        if (!$factoryFunction) {
            throw new \Exception("Unknown clinic type: " . $data['id']);
        }

        return $factoryFunction($data);
    }

    public function addFactoryFunction(int $clinicId, callable $factoryFunction): void {
        $this->registry[$clinicId] = $factoryFunction;
    }
}

class Db {
    private static $instance;

    public static function getInstance(): self {
        if (!self::$instance) {
            self::$instance = new self();
        }

        return self::$instance;
    }

    // implement database connection and query methods
}

interface LoggerInterface {
    public function error(string $message): void;
}
