struct ProcessedData {
    int largest;
    long long sum;
    size_t count;

    ProcessedData() : largest(-INT_MAX), sum(0LL), count(0) {}

    void merge(const ProcessedData& other) {
        if (other.largest > largest)
            largest = other.largest;
        sum += other.sum;
        count += other.count;
    }
};

std::mutex mutex;
std::condition_variable cv;

void processFile(int fileId, const std::string& filename) {
    std::ifstream file(filename);
    if (!file) {
        std::cerr << "Error opening file: " << filename << std::endl;
        return;
    }

    int maxInt = INT_MIN;
    long long sum = 0LL;
    size_t count = 0;

    int val;
    while (file >> val) {
        if (val < -1000000 || val > 1000000) {
            std::cerr << "Invalid integer in file " << filename << ": " << val << std::endl;
            continue;
        }

        if (val > maxInt)
            maxInt = val;

        sum += val;
        count++;

        // Report progress
        std::unique_lock<std::mutex> lock(mutex);
        cv.notify_all();
    }

    file.close();

    // Merge data into global queue
    {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this]() { return !queue_.empty(); });
        ProcessedData&.globalData = queue_.top();
        globalData.merge(ProcessedData{maxInt, sum, count});
        queue_.pop();
    }
}

int main(int argc, char* argv[]) {
    int fileId = 0;
    std::vector<std::string> files;

    for (int i = 1; i < argc; ++i) {
        files.emplace_back(argv[i]);
    }

    std::queue<ProcessedData> queue;

    // Start processing files in separate threads
    std::thread threads[std::thread::hardware_concurrency()];
    for (size_t i = 0; i < threads.size(); ++i) {
        threads[i] = std::thread(processFile, fileId++, files[i]);
    }

    // Wait for all threads to finish
    for (auto& thread : threads)
        thread.join();

    ProcessedData largestData;
    while (!queue.empty()) {
        largestData.merge(queue.front());
        queue.pop();
    }

    // Print results
    std::cout << "Largest integer: " << largestData.largest << std::endl;
    std::cout << "Average: " << (double)largestData.sum / largestData.count << std::endl;

    return 0;
}
