function refreshDialogFields(resourceId, fieldsToRefresh) {
  // Identify Fields
  const dialogFields = angular.element('#dialog').scope().$ctrl.fields;
  const fieldsToUpdate = [];
  for (let field in dialogFields) {
    if (fieldsToRefresh.includes(field)) {
      fieldsToUpdate.push(field);
    }
  }

  // External Dependency Handling
  let promises = [];
  for (let field of fieldsToUpdate) {
    promises.push(getUpdatedData(resourceId, field));
  }

  $q.all(promises).then((responses) => {
    // Performance Optimization
    const updates = {};
    for (let i in responses) {
      updates[fieldsToUpdate[i]] = responses[i].data;
    }
    angular.element('#dialog').scope().$ctrl.refreshFields(updates);
  }).catch((error) => {
    // Error Management
    if (error.status === 404) {
      alert('Error: Field not found');
    } else if (error.status === 500) {
      alert('Error: Internal Server Error');
    } else {
      console.error(error);
    }
  });
}

function getUpdatedData(resourceId, field) {
