#include <pthread.h>

#define MAX_TOKEN_CACHE 1000
#define LRU_THRESHOLD 90 // in percentage

typedef struct {
    CURL *handle;
    bool disable_cert_validation;
} RequestBuilder;

bool validate_oauth_token(const char* json) {
    json_t *root = json_loadb(json, strlen(json), JSON_NONE);
    if (!root || json_object_get(root, "access_token") == NULL ||
        json_object_get(root, "expires_in") == NULL ||
        json_object_get(root, "token_type") == NULL) {
        return false;
    }

    int expires_in = json_integer_value(json_object_get(root, "expires_in"));
    if (expires_in <= 0 || strcmp(json_string_value(json_object_get(root, "token_type")), "Bearer") != 0) {
        return false;
    }

    // Verify refresh_token if present
    json_t *refresh_token = json_object_get(root, "refresh_token");
    if (refresh_token && !json_is_null(refresh_token)) {
        // TODO: handle refresh_token logic
    }

    json_decref(root);
    return true;
}

RequestBuilder* construct_request_builder(const char* url, bool disable_cert_validation) {
    CURL *handle = curl_easy_init();
    if (!handle) {
        return NULL;
    }
    RequestBuilder* rb = malloc(sizeof(RequestBuilder));
    rb->handle = handle;
    rb->disable_cert_validation = disable_cert_validation;
    return rb;
}

// Token cache management
pthread_mutex_t token_cache_lock = PTHREAD_MUTEX_INITIALIZER;
struct lru_node {
    char* key;
    time_t timestamp;
    struct lru_node* prev;
    struct lru_node* next;
};

static void lru_insert(struct lru_node** head, struct lru_node** tail, char* key) {
    struct lru_node* new_node = malloc(sizeof(struct lru_node));
    new_node->key = key;
    new_node->timestamp = time(NULL);

    if (*head == NULL || *tail == NULL) {
        *head = new_node;
        *tail = new_node;
    } else {
        new_node->prev = *tail;
        (*tail)->next = new_node;
        *tail = new_node;
    }
}

static void lru_remove(struct lru_node** head, struct lru_node* node) {
    if (node == NULL || head == NULL || tail == NULL) return;

    if (node->prev != NULL)
        node->prev->next = node->next;
    else
        *head = node->next;

    if (node->next != NULL)
        node->next->prev = node->prev;
    else
        *tail = node->prev;

    free(node);
}

bool cache_token(char* token, CURL* handle) {
    pthread_mutex_lock(&token_cache_lock);

    struct lru_node* head = NULL;
    struct lru_node* tail = NULL;

    // Check if the token is already in the cache
    struct lru_node* node = head;
    while (node != NULL && node->key != token) {
        node = node->next;
    }

    if (node != NULL) {
        pthread_mutex_unlock(&token_cache_lock);
        return true; // Token is already cached, no need to add it
    }

    lru_insert(&head, &tail, token);

    // Check the cache size and evict least recently used entries if necessary
    if (lru_threshold > 0 && lru_threshold < 100) {
        struct lru_node* node = head;
        for (int i = 0; i < lru_threshold; i++) {
            if (node != NULL)
                lru_remove(&head, node);
            node = node->next;
        }
    }

    pthread_mutex_unlock(&token_cache_lock);
    return true;
}

void free_request_builder(RequestBuilder* rb) {
    curl_easy_cleanup(rb->handle);
    free(rb);
}
