    public class FileChunkProcessor
    {
        private readonly IEncryptionService _encryptionService;
        private readonly ILoggingService _loggingService;
        private readonly int _chunkSize;
        private readonly int _bufferSize;
        private readonly int _connectionTimeout;
        private readonly bool _useParallelProcessing;

        public FileChunkProcessor(IEncryptionService encryptionService, ILoggingService loggingService, int chunkSize, int bufferSize, int connectionTimeout, bool useParallelProcessing)
        {
            _encryptionService = encryptionService;
            _loggingService = loggingService;
            _chunkSize = chunkSize;
            _bufferSize = bufferSize;
            _connectionTimeout = connectionTimeout;
            _useParallelProcessing = useParallelProcessing;
        }

        public async Task ProcessFileAsync(string filePath, string serverUrl)
        {
            using (var fileStream = new FileStream(filePath, FileMode.Open))
            {
                var buffer = new byte[_bufferSize];
                var encryptionKey = _encryptionService.GetEncryptionKey();

                while (!fileStream.EndOfStream)
                {
                    var readBytes = await ReadFileChunkAsync(fileStream, buffer);
                    var encryptedBuffer = _encryptionService.Encrypt(readBytes, encryptionKey);

                    using (var client = new TcpClient())
                    {
                        client.Connect(serverUrl, 443); // Establish connection to remote server
                        client.ReceiveTimeout = _connectionTimeout;

                        using (var stream = client.GetStream())
                        {
                            await stream.WriteAsync(encryptedBuffer);
                        }
                    }

                    if (_useParallelProcessing)
                    {
                        await Task.Run(() => ProcessFileChunkAsync(readBytes, encryptedBuffer));
                    }
                }
            }
        }

        private async Task<int> ReadFileChunkAsync(FileStream fileStream, byte[] buffer)
        {
            var bytesRead = 0;
            while (readBytes < _chunkSize && !fileStream.EndOfStream)
            {
                await fileStream.ReadAsync(buffer, bytesRead, Math.Min(_chunkSize - bytesRead, buffer.Length));
                bytesRead += buffer.Length;
            }
            return bytesRead;
        }

        private void ProcessFileChunkAsync(byte[] readBytes, byte[] encryptedBuffer)
        {
            // Implement processing logic here
        }
    }
}
