import requests
import json
from flask import Flask, request, jsonify
from flask_caching import Cache
from datetime import datetime, timedelta
from unittest.mock import patch

app = Flask(__name__)
cache = Cache(app, config={'CACHE_TYPE': 'SimpleCache'})

weather_api_key = "your_openweathermap_api_key"
secondary_weather_api_key = "your_secondary_weather_api_key"

def fetch_weather(city, api_key):
    url = f"http://api.openweathermap.org/data/2.5/weather?q={city}&appid={api_key}"
    response = requests.get(url)
    if response.status_code == 200:
        return json.loads(response.text)

@app.route('/weather', methods=['GET'])
def get_weather():
    cities = request.args.get('cities')
    start_date = request.args.get('start_date')
    end_date = request.args.get('end_date')

    weather_data = {}
    for city in cities.split(','):
        if not (city, start_date) in cache:
            response = fetch_weather(city, weather_api_key)
            if response:
                cache.set((city, start_date), response, timeout=3600)
            else:
                return jsonify({'error': 'Failed to retrieve weather data'}), 400
        else:
            response = cache.get((city, start_date))

        weather_data[city] = {
            'temperature': response['main']['temp'],
            'humidity': response['main']['humidity'],
            'wind_speed': response['wind']['speed']
        }

    return jsonify({'weather_data': weather_data})

@app.route('/uv_index', methods=['GET'])
def get_uv_index():
    cities = request.args.get('cities')
    start_date = request.args.get('start_date')
    end_date = request.args.get('end_date')

    uv_index_data = {}
    for city in cities.split(','):
        response = fetch_weather(city, weather_api_key)
        if response:
            uv_index_data[city] = {
                'uv_index': response['wind']['uv_index']
            }
        else:
            return jsonify({'error': 'Failed to retrieve UV index'}), 400

    return jsonify({'uv_index_data': uv_index_data})

@app.route('/api_usage_policy', methods=['GET'])
def get_api_usage_policy():
    return jsonify({'policy': 'Please do not exceed 500 requests per day.'})

if __name__ == '__main__':
    app.run(debug=True)
