public class PageUpdater
{
    private readonly IPageService _pageService;
    private readonly ICachedInvalidateService _cacheInvalidator;

    public PageUpdater(IPageService pageService, ICachedInvalidateService cacheInvalidator)
    {
        _pageService = pageService;
        _cacheInvalidator = cacheInvalidator;
    }

    public async Task<string> UpdateElementAsync(string sectionId, string elementId, string htmlContent)
    {
        if (string.IsNullOrEmpty(sectionId) || string.IsNullOrEmpty(elementId))
            return "Error: Invalid IDs";

        try
        {
            // Validate HTML content
            var htmlDoc = new HtmlDocument();
            htmlDoc.LoadHtml(htmlContent);
            if (!htmlDoc.Validate())
                return "Error: Malformed HTML";

            await _pageService.UpdateElementAsync(sectionId, elementId, htmlContent);

            // Notify cache invalidation service to clear the affected page section's cache
            await _cacheInvalidator.InvalidateCacheAsync(sectionId);

            return "Update successful. Please refresh the page.";
        }
        catch (Exception ex)
        {
            // Log or handle exceptions as needed
            return $"Error: {ex.Message}";
        }
    }
}
