#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

int load_resource_bundle(const char *file_path) {
    // Open file in read mode
    FILE *file = fopen(file_path, "r");
    if (file == NULL) {
        printf("Error: Failed to open file '%s'\n", file_path);
        return -1;
    }

    // Initialize JSON parser
    json_object *json_obj = json_object_from_file(file_path);
    if (json_obj == NULL) {
        printf("Error: Failed to parse JSON file '%s'\n", file_path);
        fclose(file);
        return -2;
    }

    // Get number of items in the bundle
    int num_items = json_object_get_array_size(json_obj);

    // Dynamically allocate memory for the bundle and its items
    void *bundle_data = malloc(num_items * sizeof(void *));
    if (bundle_data == NULL) {
        printf("Error: Failed to allocate memory for bundle\n");
        json_object_put(json_obj);
        fclose(file);
        return -3;
    }

    // Initialize item pointers
    void **item_ptrs = (void **)malloc(num_items * sizeof(void *));
    if (item_ptrs == NULL) {
        printf("Error: Failed to allocate memory for item pointers\n");
        free(bundle_data);
        json_object_put(json_obj);
        fclose(file);
        return -4;
    }

    // Load items from JSON file
    int i;
    for (i = 0; i < num_items; i++) {
        json_object *item_json_obj = json_object_object_get(json_obj, "item%d" % i);
        if (item_json_obj == NULL) {
            printf("Error: Failed to load item '%d'\n", i);
            break;
        }

        // Check item type and load accordingly
        const char *key = json_object_get_string(item_json_obj, "key");
        if (!strcmp(key, "string")) {
            // Load string item
            char *item_str = (char *)malloc(strlen(json_object_get_string(item_json_obj, "value")) + 1);
            strcpy(item_str, json_object_get_string(item_json_obj, "value"));
            item_ptrs[i] = item_str;
        } else if (!strcmp(key, "integer")) {
            // Load integer item
            int *item_int = (int *)malloc(sizeof(int));
            *item_int = json_object_get_int(item_json_obj, "value");
            item_ptrs[i] = item_int;
        } else if (!strcmp(key, "float")) {
            // Load floating-point number item
            double *item_float = (double *)malloc(sizeof(double));
            *item_float = json_object_get_double(item_json_obj, "value");
            item_ptrs[i] = item_float;
        } else {
            printf("Error: Unknown item type '%s'\n", key);
            break;
        }
    }

    // Clean up and return number of items
    if (i < num_items) {
        free(bundle_data);
        json_object_put(json_obj);
        fclose(file);
        for (int j = 0; j < i; j++) {
            switch (item_ptrs[j]) {
                case char *:
                    free((char *)item_ptrs[j]);
                    break;
                case int *:
                    free((int *)item_ptrs[j]);
                    break;
                case double *:
                    free((double *)item_ptrs[j]);
                    break;
                default:
                    printf("Error: Unknown item type '%s'\n", key);
            }
        }
        for (int j = 0; j < i; j++) {
            free(item_ptrs[j]);
        }
        free(item_ptrs);
    } else {
        json_object_put(json_obj);
        fclose(file);
    }

    return num_items;
}
