import os
import threading
import time
from ctypes import CDLL, c_char_p, c_int

class Mutex:
    def __init__(self):
        self.locked = False

    def acquire(self):
        while self.locked:
            pass
        self.locked = True

    def release(self):
        self.locked = False


def create_directory(directory_name, parent_dir=None, max_attempts=3):
    mutex = Mutex()
    for _ in range(max_attempts):
        try:
            with mutex:
                if parent_dir is None:
                    os.makedirs(directory_name)
                else:
                    os.makedirs(os.path.join(parent_dir, directory_name))
                return
        except (FileExistsError, PermissionError, OSError) as e:
            time.sleep(1)

    print(f"Failed to create directory {directory_name} after {max_attempts} attempts")


def filter_transactions(transactions):
    # Load the C function
    lib = CDLL('./transaction_filter.so')
    lib.filter_transactions.argtypes = [c_char_p, c_int]
    lib.filter_transactions.restype = c_int

    max_weighted_sum = 0
    max_transaction_id = None

    for transaction in transactions:
        weighted_sum = lib.filter_transactions(transaction.encode('utf-8'), len(transactions))
        if weighted_sum > max_weighted_sum:
            max_weighted_sum = weighted_sum
            max_transaction_id = transaction

    return max_weighted_sum, max_transaction_id


def cleanup():
    # Clean up any temporary files or directories
    pass

