public class StoredProcedureExecutor
{
    private readonly IMemoryCache _cache;
    private readonly ILogger _logger;

    public StoredProcedureExecutor(IMemoryCache cache, ILogger logger)
    {
        _cache = cache;
        _logger = logger;
    }

    public async Task<List<MyObject>> ExecuteStoredProcedureAsync(SqlConnection connection, List<SqlParameter> parameters, string procedureName)
    {
        // Validate input parameters against predefined schema
        var validatedParameters = ValidateInputParameters(parameters);

        // Check if the cached result is available for the given input parameters
        if (_cache.TryGetValue(procedureName + "_" + string.Join("_", parameters.Select(p => p.Value)), out var cachedResult))
        {
            return (List<MyObject>)cachedResult;
        }

        try
        {
            using (var command = new SqlCommand(procedureName, connection))
            {
                command.CommandType = CommandType.StoredProcedure;

                foreach (var parameter in parameters)
                {
                    command.Parameters.Add(parameter);
                }

                // Execute the stored procedure asynchronously and retrieve the result set
                var result = await Task.Run(() =>
                {
                    connection.Open();
                    using (var reader = command.ExecuteReader())
                    {
                        var results = new List<MyObject>();

                        while (reader.Read())
                        {
                            results.Add(new MyObject
                            {
                                Property1 = reader["Property1"].ToString(),
                                Property2 = int.Parse(reader["Property2"].ToString()),
                                // ... other properties ...
                            });
                        }

                        return results;
                    }
                });

                _cache.Set(procedureName + "_" + string.Join("_", parameters.Select(p => p.Value)), result);
            }
        }
        catch (SqlException ex) when (ex.Number == 121)
        {
            // Handle database connection timeout
            _logger.LogError(ex, "Database connection timed out");
            return null;
        }
        catch (SqlException ex) when (ex.Number >= 50000 && ex.Number <= 50999)
        {
            // Handle invalid parameters
            _logger.LogError(ex, "Invalid input parameters");
            return null;
        }
        catch (Exception ex)
        {
            // Handle failed stored procedure execution
            _logger.LogError(ex, "Failed to execute the stored procedure");
            return null;
        }

        // Log successful execution of the stored procedure
        _logger.LogInformation("Successfully executed the stored procedure");

        return result;
    }

    private List<SqlParameter> ValidateInputParameters(List<SqlParameter> parameters)
    {
