            IntPtr stateList = malloc((numStates + 1) * sizeof(int));

            if (stateList == IntPtr.Zero)
                return NULL;

            for (int i = 0; i <= lastState; i++)
            {
                ((int*)stateList)[i] = *(int*)(states + i * sizeof(int));
            }

            // Update the 'next' pointer of the last state in the list to point to the newly created state list
            ((int*)stateList)[lastState] = (int)stateList;

            return stateList;
