            // ...

            _aesGcmCipher.Init(metadata.Nonce, metadata.Tag, metadata.Iv);
            return _aesGcmCipher.Decrypt(fileStream, ciphertext);
        }
    }

    public class AesGcmCipher
    {
        private readonly Aes aes;
        private readonly GCMBlockCipher gcm;

        public AesGcmCipher()
        {
            aes = Aes.Create();
            gcm = new GCMBlockCipher(aes);
        }

        public byte[] Encrypt(Stream stream, byte[] nonce)
        {
            using (var memoryStream = new MemoryStream())
            {
                var ct = new MemoryStream();
                var iv = new MemoryStream();

                using (var cryptoStream = new CryptoStream(memoryStream, aes.CreateEncryptor(), true))
                {
                    int bytesRead;
                    byte[] buffer = new byte[0x10000];
                    while ((bytesRead = stream.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        cryptoStream.Write(buffer, 0, bytesRead);
                    }
                }

                ct.Position = 0;
                var tag = GetTag();
                ct.Write(tag, 0, tag.Length);
                return CombineStreams(ct.ToArray(), nonce, iv.ToArray());
            }
        }

        public byte[] Decrypt(Stream stream, byte[] ciphertext)
        {
            using (var memoryStream = new MemoryStream(ciphertext))
            {
                int bytesRead;
                byte[] buffer = new byte[0x10000];
                var decryptedData = new MemoryStream();
                while ((bytesRead = memoryStream.Read(buffer, 0, buffer.Length)) > 0)
                {
                    var cryptoStream = new CryptoStream(decryptedData, aes.CreateDecryptor(), true);
                    cryptoStream.Write(buffer, 0, bytesRead);
                }

                return decryptedData.ToArray();
            }
        }

        private byte[] GetTag()
        {
            // Calculate the tag
            // ...
            return tag;
        }

        private byte[] CombineStreams(byte[] ct, byte[] nonce, byte[] iv)
        {
            using (var memoryStream = new MemoryStream())
            {
                memoryStream.Write(nonce, 0, nonce.Length);
                memoryStream.Write(iv, 0, iv.Length);
                memoryStream.Write(ct, 0, ct.Length);
                return memoryStream.ToArray();
            }
        }

        public byte[] GetNonce()
        {
            // Generate a new nonce
            // ...
            return nonce;
        }

        public void Init(byte[] nonce, byte[] tag, byte[] iv)
        {
            gcm.Init(new AESEncryptionParameters(aes.Key, iv), nonce, tag);
        }
    }
}

public class EncryptionMetadata
{
    public byte[] Nonce { get; set; }
    public byte[] Tag { get; set; }
    public byte[] Iv { get; set; }
}
