from flask import Flask, request, jsonify
from flask_login import LoginManager, login_user, logout_user, current_user
from flask_principal import Principal, Permission, RoleNeed
from werkzeug.utils import secure_filename

app = Flask(__name__)
app.config.from_object('config')

login_manager = LoginManager()
login_manager.init_app(app)

principal = Principal(app)

class User:
    def __init__(self, id):
        self.id = id

@login_manager.user_loader
def load_user(user_id):
    return User(user_id)

@app.route('/login', methods=['POST'])
def login():
    if request.is_json:
        data = request.get_json()
        username = data.get('username')
        password = data.get('password')

        # Validate credentials against external identity provider using OAuth2 or similar protocol
        # For demonstration purposes, assume a simple username/password validation
        if username == 'admin' and password == 'password':
            user = User(1)
            login_user(user)

            return jsonify({'message': 'Login successful'})

    return jsonify({'error': 'Invalid credentials'}), 401

@app.route('/logout', methods=['POST'])
def logout():
    logout_user()
    return jsonify({'message': 'Logout successful'})

@app.route('/profile', methods=['GET', 'PUT'])
@principal.permission_required('user')
def profile():
    if request.method == 'PUT':
        # Validate and update user profile picture
        file = request.files['image']
        filename = secure_filename(file.filename)

        if file.size > 1024 * 1024:  # 1MB limit
            return jsonify({'error': 'File size exceeds limit'}), 400

        # Store profile picture in cloud storage service (e.g., AWS S3, Google Cloud Storage)
        try:
            s3 = boto3.client('s3', aws_access_key_id='YOUR_ACCESS_KEY',
                                     aws_secret_access_key='YOUR_SECRET_KEY')
            s3.put_object(Body=file.read(), Bucket='your-bucket-name', Key=filename)

            # Update user profile picture in database
            current_user.profile_picture = filename

            return jsonify({'message': 'Profile picture updated'})
        except Exception as e:
            app.logger.error('Error updating profile picture: %s' % str(e))
            return jsonify({'error': 'Failed to update profile picture'}), 500

    # Return user profile information
    return jsonify({'username': current_user.username, 'profile_picture': current_user.profile_picture})

if __name__ == '__main__':
    app.run(debug=True)
