use std::path::{Path, PathBuf};
use std::fs::{create_dir_all, remove_dir_all};
use std::io::{Read, Write};
use std::env;
use std::process;
use std::thread::sleep;
use std::time::Duration;

mod plugins {
    pub trait PreDirHook {}
    pub trait PostDirHook {}

    pub mod jenkins {
        pub struct JenkinsPreDir {}
        pub struct JenkinsPostDir {}
    }
}

struct DirManager {
    work_dir: PathBuf,
    cleanup_interval: u64,
}

impl DirManager {
    fn new() -> Self {
        let mut work_dir = match env::var("WORK_DIR").ok() {
            Some(dir) => Path::new(&dir).to_path_buf(),
            None => create_temp_dir("/tmp"),
        };

        if !work_dir.exists() || !work_dir.is_dir() {
            panic!("Invalid WORK_DIR: {}", &work_dir.display());
        }

        let cleanup_interval = match env::var("CLEANUP_INTERVAL").ok() {
            Some(interval) => interval.parse::<u64>().unwrap_or(3600),
            None => 3600,
        };

        DirManager { work_dir, cleanup_interval }
    }

    fn run_plugins(&self, action: &str) -> Result<(), Box<dyn std::error::Error>> {
        match action {
            "pre" => plugins::jenkins::JenkinsPreDir {}.run(),
            "post" => plugins::jenkins::JenkinsPostDir {}.run(),
            _ => Ok(()),
        }
    }

    fn manage_dir(&self) -> Result<(), Box<dyn std::error::Error>> {
        if let Err(err) = self.run_plugins("pre") {
            log_error!("Pre-directory hook failed: {}", err);
        }

        // Perform directory management operations here

        if let Err(err) = self.run_plugins("post") {
            log_error!("Post-directory hook failed: {}", err);
        }

        Ok(())
    }

    fn cleanup_dir(&self) {
        sleep(Duration::from_secs(self.cleanup_interval));
        remove_dir_all(&self.work_dir).unwrap_or_else(|err| {
            log_error!("Failed to clean up directory: {}", err);
        });
    }
}

fn create_temp_dir(base: &str) -> PathBuf {
    let mut dir = Path::new(base);
    let temp_name = format!("pipeline-{}", uuid::Uuid::new_v4().to_string());
    let path = dir.join(temp_name);

    create_dir_all(&path).unwrap_or_else(|err| {
        log_error!("Failed to create temporary directory: {}", err);
        process::exit(1);
    });

    path
}

fn log_error(msg: &str) {
    eprintln!("{}", msg);
}
