public class CustomUserValidator : UserValidator<CustomUser>
{
    public override async Task<IdentityResult> ValidateAsync(string userName)
    {
        // implement custom validation logic here
        return await base.ValidateAsync(userName);
    }
}

public class CustomUserLockoutData
{
    public DateTime? LockoutEnd { get; set; }
    public int MaxFailedAccessAttempts { get; set; }
    public DateTime? LockoutUntil { get; set; }

    public void Update(int failedAccessAttempts, DateTime? lockoutUntil)
    {
        if (lockoutUntil != null && lockoutUntil < DateTime.Now.AddSeconds(60))
        {
            // adjust lockout policy based on recent login attempts
            MaxFailedAccessAttempts = Math.Min(MaxFailedAccessAttempts + 1, 5);
            LockoutEnd = DateTime.Now.AddSeconds(Math.Max(0, (int)(60 / MaxFailedAccessAttempts) * 1000));
        }
    }
}

public class CustomUser : IdentityUser<int>
{
