using System;
using System.IO;
using System.Linq;
using System.Threading;

namespace LargeIntegerProcessor
{
    class Program
    {
        static void Main(string[] args)
        {
            if (args.Length < 1)
            {
                Console.WriteLine("Please provide the file paths as command-line parameters.");
                return;
            }

            string[] filePaths = args.Select(arg => Path.GetFullPath(arg)).ToArray();

            try
            {
                int largestInteger = int.MinValue;
                long total = 0;

                foreach (string filePath in filePaths)
                {
                    if (!File.Exists(filePath))
                    {
                        Console.WriteLine($"File '{filePath}' not found.");
                        continue;
                    }

                    try
                    {
                        string[] lines = File.ReadAllLines(filePath);

                        foreach (string line in lines)
                        {
                            int integer;

                            if (int.TryParse(line, out integer))
                            {
                                total += integer;

                                if (integer > largestInteger)
                                {
                                    largestInteger = integer;
                                }
                            }
                            else
                            {
                                Console.WriteLine($"Invalid integer '{line}' in file '{filePath}'.");
                            }
                        }
                    }
                    catch (IOException ex)
                    {
                        Console.WriteLine($"Error reading file '{filePath}': {ex.Message}");
                    }
                }

                Console.WriteLine($"Largest integer: {largestInteger}");
                Console.WriteLine($"Average integer: {(double)total / filePaths.Length}");
            }
            catch (Exception ex)
            {
                Console.WriteLine("An error occurred: " + ex.Message);
            }
        }
    }
}
