import json
import asyncio
from typing import Dict, Any
from collections import defaultdict

class JsonSerializable:
    @classmethod
    def from_json(cls, data: str) -> 'JsonSerializable':
        return cls(**json.loads(data))

    def to_json(self) -> str:
        return json.dumps(self.__dict__)

class RegisteredClass(type):
    registry = {}

    def __new__(cls, name, bases, dct):
        new_cls = super().__new__(cls, name, bases, dct)
        RegisteredClass.registry[name] = new_cls
        return new_cls

def factory_loader(directory: str) -> Dict[str, type]:
    factories = {}
    for file in [file for file in directory.iterdir() if file.is_file() and file.name.endswith('.json')]:
        try:
            with open(file, 'r') as f:
                data = json.load(f)
                factories[file.stem] = RegisteredClass(data['class_name'], (), {})
        except Exception as e:
            print(f"Failed to load {file.name}: {e}")
    return factories

async def parallel_loader(directory: str) -> Dict[str, type]:
    loop = asyncio.get_running_loop()
    tasks = [loop.run_in_executor(None, lambda: factory_loader(directory)) for _ in range(5)]
    results = await asyncio.gather(*tasks)
    merged_results = {}
    for result in results:
        merged_results.update(result)
    return merged_results

def dependency_graph(node_set: set) -> Dict[str, list]:
    graph = defaultdict(list)
    for node in node_set:
        try:
            with open(f"{node}.json", 'r') as f:
                data = json.load(f)
                depends_on = data.get('depends_on', [])
                if depends_on:
                    graph[node].extend(depends_on)
        except FileNotFoundError:
            pass
        except Exception as e:
            print(f"Failed to load {node}: {e}")
    return dict(graph)

def main():
    directory = "path/to/json/files"
    factories = asyncio.run(parallel_loader(directory))
    node_set = set(factories.keys())
    graph = dependency_graph(node_set)
    for node, dependencies in graph.items():
        if dependencies:
            print(f"Node {node} depends on: {[str(dep) for dep in dependencies]}")

if __name__ == "__main__":
    main()
```

