import os
import tempfile
import threading
import time
from typing import Dict

class DirectoryManager:
    def __init__(self):
        self.lock = threading.Lock()
        self.temp_dir_root = tempfile.gettempdir()

    def create_directory(self, dir_path: str) -> None:
        with self.lock:
            while True:
                try:
                    os.makedirs(dir_path)
                    break
                except FileExistsError:
                    continue
                except IsADirectoryError:
                    raise
                except OSError as e:
                    if e.errno == errno.ENOSPC:
                        time.sleep(1)  # Wait and retry on disk full condition
                    elif e.errno == errno.EPERM:
                        time.sleep(1)  # Wait and retry on permission issue
                    else:
                        raise

    def create_temp_directory(self, prefix: str = None) -> str:
        temp_dir_path = tempfile.mkdtemp(dir=self.temp_dir_root, prefix=prefix)
        return temp_dir_path

    def set_environment_variable(self, name: str, value: str) -> None:
        os.environ[name] = value

    def get_environment_variable(self, name: str) -> str:
        return os.getenv(name)

class DirectoryManagerThreadSafe(DirectoryManager):
    def __init__(self):
        super().__init__()
        self.lock = threading.Lock()

    def create_directory(self, dir_path: str) -> None:
        with self.lock:
            while True:
                try:
                    os.makedirs(dir_path)
                    break
                except FileExistsError:
                    continue
                except IsADirectoryError:
                    raise
                except OSError as e:
                    if e.errno == errno.ENOSPC:
                        time.sleep(1)  # Wait and retry on disk full condition
                    elif e.errno == errno.EPERM:
                        time.sleep(1)  # Wait and retry on permission issue
                    else:
                        raise

    def create_temp_directory(self, prefix: str = None) -> str:
        with self.lock:
            temp_dir_path = tempfile.mkdtemp(dir=self.temp_dir_root, prefix=prefix)
            return temp_dir_path

class DirectoryManagerWrapper(DirectoryManagerThreadSafe):
    def __init__(self):
        super().__init__()
        self.logger = logging.getLogger(__name__)

    def create_directory(self, dir_path: str) -> None:
        try:
            super().create_directory(dir_path)
        except Exception as e:
            self.logger.error(f"Error creating directory {dir_path}: {str(e)}")

    def create_temp_directory(self, prefix: str = None) -> str:
        try:
            temp_dir_path = super().create_temp_directory(prefix=prefix)
        except Exception as e:
            self.logger.error(f"Error creating temporary directory with prefix {prefix}: {str(e)}")
        return temp_dir_path

    def set_environment_variable(self, name: str, value: str) -> None:
        try:
            super().set_environment_variable(name, value)
        except Exception as e:
            self.logger.error(f"Error setting environment variable {name} to {value}: {str(e)}")

    def get_environment_variable(self, name: str) -> str:
        try:
            return super().get_environment_variable(name)
        except Exception as e:
            self.logger.error(f"Error getting environment variable {name}: {str(e)}")
