```rust
use tokio::sync::{RwLock};
use tokio_postgres::NoTls;
use tokio_postgres::connect;

struct DatabaseConnectionManager {
    connections: RwLock<Vec<tokio_postgres::Client>>,
    config: RwLock<Option<tokio_postgres::Config>>,
}

impl DatabaseConnectionManager {
    async fn new() -> Self {
        let mut connections = RwLock::new(Vec::new());
        let config = RwLock::new(None);
        DatabaseConnectionManager { connections, config }
    }

    async fn get_connection(&self, provider: String, connection_string: String) -> Result<tokio_postgres::Client, Box<dyn std::error::Error>> {
        match &*self.config.read().await {
            Some(c) => {
                let db = connect(format!("{} {}", provider, connection_string), NoTls).await?;
                self.connections.write().await.push(db);
                Ok(self.connections.read().await.last().cloning().unwrap())
            }
            None => Err("No configuration set".to_string().into())
        }
    }

    async fn release_connection(&self, conn: &tokio_postgres::Client) {
        match self.connections.write().await.iter().position(|c| c.as_ref() == conn) {
            Some(index) => self.connections.write().await.remove(index),
            None => {}
        }
    }

    async fn to_string(&self) -> String {
        format!("Connection Manager: {}", self.config.read().await.unwrap())
    }

    async fn initialize_from_configuration(&mut self, provider: String, connection_string: String) {
        *self.config.write().await = Some(tokio_postgres::Config::new(format!("{} {}", provider, connection_string)).no_tls());
    }

    async fn configure_pooling(&mut self, min_size: i32, max_size: i32, idle_timeout: i32) {
        let mut conn_config = self.config.read().await.unwrap();
        conn_config.min_connections(min_size).max_connections(max_size).idle_timeout(std::time::Duration::from_millis(idle_timeout as u64));
    }

    async fn get_performance_metrics(&self) -> String {
        format!("Connections: {:?}", self.connections.read().await.len())
    }
}

async fn main() {
    let mut manager = DatabaseConnectionManager::new().await;
    // Use the manager
    if std::env::args().count() > 1 {
        match &*manager.config.read().await {
            Some(c) => println!("{}", c),
            None => println!("No configuration set")
        }
    } else {
        manager.initialize_from_configuration("provider", "connection_string").await;
        manager.configure_pooling(1, 10, 10000).await;
        let conn = manager.get_connection("provider", "connection_string").await.unwrap();
        // Use the connection
        manager.release_connection(&conn).await;
    }
}

#[tokio::main]
async fn main() {
    DatabaseConnectionManager::new().await.main().await;
}
