```php
function generateRandomSalt($length = 16) {
    $randomBytes = random_bytes($length);
    return bin2hex($randomBytes);
}

function hashPassword($password, $salt, $algorithm = 'argon2i') {
    return password_hash($password . $salt, $algorithm);
}

function verifyPassword($hashedPassword, $plainTextPassword, $salt) {
    $verified = password_verify($plainTextPassword . $salt, $hashedPassword);
    if (!$verified) {
        throw new Exception('Invalid password');
    }
    return true;
}

function authenticateUser($username, $password) {
    // Make API call to external authentication service
    $response = json_decode(file_get_contents('https://api.example.com/user/' . $username), true);

    if ($response['status'] !== 'success') {
        throw new Exception('User not found');
    }

    $userSalt = generateRandomSalt();
    $hashedPassword = hashPassword($password, $userSalt);
    return array('salt' => $userSalt, 'hashed_password' => $hashedPassword);
}

function changePassword($username, $oldPassword, $newPassword) {
    try {
        $userDetails = authenticateUser($username, $oldPassword);
        $hashedOldPassword = hashPassword($oldPassword, $userDetails['salt']);
        if ($hashedOldPassword !== $userDetails['hashed_password']) {
            throw new Exception('Invalid old password');
        }
        $newSalt = generateRandomSalt();
        $hashedNewPassword = hashPassword($newPassword, $newSalt);
        // Update user details in database with the new salt and hashed password
        return array('salt' => $newSalt, 'hashed_password' => $hashedNewPassword);
    } catch (Exception $e) {
        throw $e;
    }
}

function regenerateHash($username, $newPassword) {
    try {
        $userDetails = authenticateUser($username, $newPassword);
        return array('salt' => $userDetails['salt'], 'hashed_password' => hashPassword($newPassword, $userDetails['salt']));
    } catch (Exception $e) {
        throw $e;
    }
}
