```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

public class DatabaseExecutor
{
    private readonly Dictionary<string, SqlCommand> _cachedCommands = new();
    private readonly int _maxCachedCommands = 1000;
    private readonly ILogger _logger;

    public DatabaseExecutor(ILogger logger)
    {
        _logger = logger;
    }

    public IDataReader ExecuteParameterizedQuery(SqlConnection connection, string commandText, List<object> parameters, bool returnAsObjects = false)
    {
        if (connection == null) throw new ArgumentNullException(nameof(connection));
        if (string.IsNullOrEmpty(commandText)) throw new ArgumentNullException(nameof(commandText));

        if (!returnAsObjects && _cachedCommands.TryGetValue(commandText, out SqlCommand cachedCommand))
            return ExecuteReader(cachedCommand);

        var command = new SqlCommand(commandText, connection);
        foreach (var parameter in parameters)
        {
            switch (parameter)
            {
                case int value:
                    command.Parameters.AddWithValue($"@{commandText}_{value}", value);
                    break;
                case string value:
                    command.Parameters.AddWithValue($"@{commandText}_{value}", value);
                    break;
                case DateTime value:
                    command.Parameters.AddWithValue($"@{commandText}_{value}", value);
                    break;
            }
        }

        if (!returnAsObjects)
        {
            try
            {
                using (var reader = command.ExecuteReader())
                {
                    return reader;
                }
            }
            catch (SqlException ex)
            {
                _logger.LogError(ex, "Error executing parameterized query");
                throw;
            }
        }
        else
        {
            try
            {
                var results = new List<object>();
                using (var reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        results.Add(reader);
                    }
                }
                return results;
            }
            catch (SqlException ex)
            {
                _logger.LogError(ex, "Error executing parameterized query");
                throw;
            }
        }
    }

    private IDataReader ExecuteReader(SqlCommand command)
    {
        try
        {
            using (var reader = command.ExecuteReader())
            {
                return reader;
            }
        }
        catch (SqlException ex)
        {
            _logger.LogError(ex, "Error executing cached parameterized query");
            throw;
        }
    }

    public void CacheCommands(int maxCachedCommands)
    {
        _maxCachedCommands = maxCachedCommands;
    }
}
