import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class FileUploadProcessor {
    public void processFileUploads(BlockingQueue<ultipartFile> uploadQueue, int maxConcurrency) {
        // Create a thread pool executor with the specified maximum concurrency
        ThreadPoolExecutor executor = new ThreadPoolExecutor(
                maxConcurrency,
                maxConcurrency,
                0L,
                TimeUnit.MILLISECONDS,
                new LinkedBlockingQueue<Runnable>()
        );

        // Process files from the queue asynchronously using the thread pool
        uploadQueue.drainTo(executor);

        // Shutdown the thread pool to prevent leakage of resources
        executor.shutdown();

        try {
            while (!executor.isTerminated()) {
                Thread.sleep(100);
            }
        } catch (InterruptedException e) {
            // Handle interruption
            Thread.currentThread().interrupt();
        }

        // Log any remaining tasks in the queue
        if (uploadQueue.size() > 0) {
            System.out.println("Remaining files to process: " + uploadQueue.size());
        }
    }
}
