#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct SubNode {
    char* str;
    double val;
} SubNode;

typedef struct Node {
    int value;
    SubNode* subnodes;
    size_t subnode_count;
} Node;

void init_node_array(Node** nodes, size_t size) {
    *nodes = (Node*)malloc(size * sizeof(Node));
}

void free_node_array(Node* nodes, size_t size) {
    for (size_t i = 0; i < size; i++) {
        if (nodes[i].subnodes != NULL) {
            SubNode* subnode = nodes[i].subnodes;
            while (subnode != NULL) {
                SubNode* next = subnode->next;
                free(subnode);
                subnode = next;
            }
        }
    }
    free(nodes);
}

void init_subnode_list(SubNode** subnodes, size_t capacity) {
    *subnodes = (SubNode*)malloc((capacity + 1) * sizeof(SubNode));
    (*subnodes)[0].next = NULL;
}

void add_subnode(SubNode** subnodes, char* str, double val) {
    SubNode* new_subnode = (SubNode*)malloc(sizeof(SubNode));
    new_subnode->str = str;
    new_subnode->val = val;
    if (*subnodes == NULL || (*subnodes)->next == NULL) {
        *subnodes = new_subnode;
    } else {
        SubNode* current = *subnodes;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_subnode;
    }
}

int main() {
    srand(time(NULL));

    size_t node_count = 10; // Change this to your desired node count
    size_t subnode_capacity = 5; // Change this to your desired subnode capacity

    Node* nodes = NULL;
    init_node_array(&nodes, node_count);

    for (size_t i = 0; i < node_count; i++) {
        int value = rand() % 100; // Random integer within range [0, 99]
        nodes[i].value = value;

        SubNode* subnodes = NULL;
        init_subnode_list(&subnodes, subnode_capacity);

        for (size_t j = 0; j < subnode_capacity; j++) {
            char* str = (char*)malloc(10); // Random string of length [5, 9]
            int len = rand() % 4 + 5;
            for (int k = 0; k < len; k++) {
                str[k] = 'a' + rand() % 26;
            }
            str[len] = '\0';

            double val = (double)rand() / RAND_MAX; // Random double value
            add_subnode(&subnodes, str, val);

            if (j < subnode_capacity - 1) {
                free(str);
            }
        }

        nodes[i].subnode_count = subnode_capacity;
        nodes[i].subnodes = subnodes;
    }

    // Use the serialized data here...

    free_node_array(nodes, node_count);

    return 0;
}
