class AttackTracker {
public:
    AttackTracker() : attack1_used(0), attack2_used(0) {}

    void select_attack();

private:
    int attack1_used;
    int attack2_used;

    std::mutex lock;
};

void AttackTracker::select_attack() {
    static bool is_attack1_available = true;
    static auto start_time = std::chrono::high_resolution_clock::now();

    if (attack1_used >= 100) {
        std::cout << "Warning: Attack 1 usage limit reached. Cannot use again until end of session." << std::endl;
        is_attack1_available = false;
    }
    else if (attack2_used >= 100) {
        std::cout << "Warning: Attack 2 usage limit reached. Cannot use again until end of session." << std::endl;
        is_attack1_available = true; // Ensure attack 1 remains available
    }

    int selected_attack = is_attack1_available ? 1 : 2;

    if (std::chrono::high_resolution_clock::now().time_since_epoch().count() - start_time.count() < 9e9 / 9000) { // 9 seconds in milliseconds
        std::cout << "Cooldown period not over yet. Waiting..." << std::endl;
        return;
    }

    if (selected_attack == 1) {
        attack1_used++;
    }
    else {
        attack2_used++;
    }

    start_time = std::chrono::high_resolution_clock::now();

    std::cout << "Selected attack: " << selected_attack << std::endl;

    // Release the lock to allow other threads to access the shared data
    lock.unlock();
}
