function getMatchingElements(rootElement: HTMLElement, selector: string, filterFn: (element: ElementMetadata) => boolean): Promise<HTMLElement[]> {
    return new Promise((resolve, reject) => {
        const results = [];
        const traverse = (element: HTMLElement) => {
            if (!element || !element.matches(selector)) return;
            let metadata: ElementMetadata | undefined;
            try {
                metadata = { id: element.id, class: element.className, description: fetchDescription(element) };
            } catch (error) {
                reject(error);
                return;
            }
            if (filterFn(metadata)) results.push(element);
            const children = Array.from(element.children);
            for (const child of children) traverse(child);
        };
        traverse(rootElement);
        resolve(results.map((element) => element as HTMLElement));
    });

    async function fetchDescription(element: HTMLElement): Promise<string> {
        if (!element.id) return 'Unknown';
        try {
            const response = await fetch(`https://api.example.com/element-descriptions/${element.id}`);
            if (!response.ok) throw new Error('Failed to retrieve description');
            return (await response.text()).trim();
        } catch (error) {
            console.error(error);
            return 'Error retrieving description';
        }
    }
