using System;
using System.Security.Cryptography;
using System.Text;
using BCryptNet = BCrypt.Net.BCrypt;

namespace PasswordHashing
{
    public class SecurePasswordHasher
    {
        private readonly string _saltPrefix;

        public SecurePasswordHasher(string saltPrefix)
        {
            _saltPrefix = saltPrefix;
        }

        public string HashPassword(string plainTextPassword, HashAlgorithm algorithm)
        {
            using var random = new RNGCryptoServiceProvider();
            byte[] salt = GenerateSalt(random);
            return algorithm switch
            {
                HashAlgorithm.SHA256 => HashWithSHA256(plainTextPassword, salt),
                HashAlgorithm.BCrypt => HashWithBCrypt(plainTextPassword, salt),
                _ => throw new ArgumentException("Invalid hashing algorithm", nameof(algorithm)),
            };
        }

        public bool VerifyHashedPassword(string hashedPassword, string plainTextPassword, HashAlgorithm algorithm)
        {
            return algorithm switch
            {
                HashAlgorithm.SHA256 => VerifyWithSHA256(hashedPassword, plainTextPassword),
                HashAlgorithm.BCrypt => VerifyWithBCrypt(hashedPassword, plainTextPassword),
                _ => throw new ArgumentException("Invalid hashing algorithm", nameof(algorithm)),
            };
        }

        public void StoreHashedPassword(string hashedPassword, string userId)
        {
            // Database storage implementation
        }

        public string RetrieveHashedPassword(string userId)
        {
            // Database retrieval implementation
            return null;
        }

        private byte[] GenerateSalt(RNGCryptoServiceProvider random)
        {
            var salt = new byte[16];
            random.GetBytes(salt);
            return salt;
        }

        private string HashWithSHA256(string plainTextPassword, byte[] salt)
        {
            using var sha256 = SHA256.Create();
            byte[] hashBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes($"{plainTextPassword}{_saltPrefix}{Convert.ToBase64String(salt)}"));
            return Convert.ToBase64String(hashBytes);
        }

        private string HashWithBCrypt(string plainTextPassword, byte[] salt)
        {
            return BCryptNet.HashPassword(plainTextPassword, _saltPrefix + Convert.ToBase64String(salt));
        }

        private bool VerifyWithSHA256(string hashedPassword, string plainTextPassword)
        {
            using var sha256 = SHA256.Create();
            byte[] hashBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes($"{plainTextPassword}{_saltPrefix}"));
            return Convert.ToBase64String(hashBytes) == hashedPassword;
        }

        private bool VerifyWithBCrypt(string hashedPassword, string plainTextPassword)
        {
            return BCryptNet.Verify(plainTextPassword, hashedPassword);
        }
    }

    public enum HashAlgorithm
    {
        SHA256,
        BCrypt
    }
}
