```java
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.locks.ReentrantLock;

public class DistributedCache {
    private Map<String, CacheNode> cacheNodes = new HashMap<>();
    private int totalCapacity;
    private int availableResources;
    private ReentrantLock lock = new ReentrantLock();

    public void initializeCache(int numNodes, int capacityPerNode) {
        this.totalCapacity = numNodes * capacityPerNode;
        this.availableResources = totalCapacity;

        for (int i = 0; i < numNodes; i++) {
            CacheNode node = new CacheNode(capacityPerNode);
            cacheNodes.put("node-" + i, node);
        }
    }

    public void put(String key, String value, int ttl) {
        if (!isValidInput(key, value, ttl)) {
            return;
        }

        lock.lock();
        try {
            // Find the least-loaded cache node
            CacheNode targetNode = findLeastLoadedNode();

            // Store the data in the selected node
            targetNode.put(key, value);

            // Update TTL and schedule expiration if necessary
            targetNode.scheduleExpiration(ttl);
        } finally {
            lock.unlock();
        }
    }

    public String get(String key) {
        if (!isValidInput(key)) {
            return null;
        }

        lock.lock();
        try {
            // Find the cache node with the requested data
            CacheNode node = findNodeWithKey(key);

            if (node == null) {
                return null; // Data not found
            }

            // Return the cached value
            return node.get(key);
        } finally {
            lock.unlock();
        }
    }

    public void remove(String key) {
        if (!isValidInput(key)) {
            return;
        }

        lock.lock();
        try {
            // Find the cache node with the requested data
            CacheNode node = findNodeWithKey(key);

            if (node != null) {
                // Remove the entry from the node
                node.remove(key);
            }
        } finally {
            lock.unlock();
        }
    }

    public void resizeCache(int newSize, int capacityPerNode) {
        if (newSize <= 0 || capacityPerNode <= 0) {
            return; // Invalid input
        }

        lock.lock();
        try {
            // Calculate the new total capacity
            this.totalCapacity = newSize * capacityPerNode;

            // Resize cache nodes and rebalance data
            resizeNodes(newSize, capacityPerNode);
        } finally {
            lock.unlock();
        }
    }

    private CacheNode findLeastLoadedNode() {
        // Implement a load-balancing algorithm to find the least-loaded node
    }

    private CacheNode findNodeWithKey(String key) {
        // Iterate through cache nodes and find the one with the requested data
    }

    private boolean isValidInput(String key, String value, int ttl) {
        // Validate input data (key, value, TTL)
        return true; // Default: valid input
    }

    private boolean isValidInput(String key) {
        // Validate input key
        return true; // Default: valid input
    }
}

class CacheNode {
    private Map<String, String> cache;
    private int capacity;
    private int usedCapacity;
    private ReentrantLock lock = new ReentrantLock();

    public CacheNode(int capacity) {
        this.capacity = capacity;
        this.usedCapacity = 0;
        this.cache = new HashMap<>();
    }

    public void put(String key, String value) {
        // Store the data in the cache
        if (!isValidInput(key, value)) {
            return; // Invalid input
        }

        lock.lock();
        try {
            // Check for available space before storing
            if (usedCapacity + 1 > capacity * 0.85) { // 15% utilization threshold
                // Handle cache overflow (e.g., evict expired entries or resize)
            }

            // Store the data
            cache.put(key, value);
            usedCapacity++;
        } finally {
            lock.unlock();
        }
    }

    public String get(String key) {
        if (!isValidInput(key)) {
            return null; // Invalid input
        }

        lock.lock();
        try {
            // Retrieve the cached value
            return cache.get(key);
        } finally {
            lock.unlock();
        }
    }

    public void remove(String key) {
        if (!isValidInput(key)) {
            return; // Invalid input
        }

        lock.lock();
        try {
            // Remove the entry from the cache
            cache.remove(key);
            usedCapacity--;
        } finally {
            lock.unlock();
        }
    }

    private boolean isValidInput(String key, String value) {
        // Validate input data (key, value)
        return true; // Default: valid input
    }

    private boolean isValidInput(String key) {
        // Validate input key
        return true; // Default: valid input
    }
}
