class PasswordManager {
    private $caching = [];
    private $saltDatabase = [];

    public function generateRandomString($length, $charset) {
        $randomString = '';
        while (strlen($randomString) < $length) {
            if (rand(0, 1)) {
                $randomChar = rand(48, 122); // numeric and special characters
            } else {
                $randomChar = rand(65, 90); // uppercase letters
            }
            $randomString .= chr($randomChar);
        }
        return $randomString;
    }

    public function hashPassword($password, $salt) {
        if (!preg_match('/^[a-zA-Z0-9/+]{43}$/', $salt)) {
            throw new Exception('Invalid salt');
        }
        return password_hash($password, PASSWORD_BCRYPT, ['cost' => 12]);
    }

    public function verifyPassword($hashedPassword, $password, $salt) {
        if (!preg_match('/^[a-zA-Z0-9/+]{43}$/', $salt)) {
            throw new Exception('Invalid salt');
        }
        return password_verify($password, $hashedPassword);
    }

    public function retrieveSalt($username) {
        if (isset($this->caching[$username])) {
            return base64_decode($this->caching[$username]);
        } elseif (array_key_exists($username, $this->saltDatabase)) {
            return base64_encode($this->saltDatabase[$username]);
        }
        throw new SaltNotFoundException('Salt not found for user');
    }

    public function saveHashedPassword($username, $hashedPassword, $salt) {
        try {
            // simulate database connection
            if (!isset($this->caching[$username])) {
                $this->caching[$username] = base64_encode($salt);
            }
            $this->saltDatabase[$username] = $salt;
            return true;
        } catch (Exception $e) {
            echo "Error: " . $e->getMessage();
            return false;
        }
    }
}
