    class SecureRandom {
    public:
        static std::mt19937_64& getInstance() {
            static std::mt19937_64 rng;
            return rng;
        }

        void seed() {
            // Seed the random number generator with current time, system entropy, and WebSocket protocol
            uint32_t seed = std::chrono::high_resolution_clock::now().time_since_epoch().count();
            auto& rng = getInstance();
            std::seed_seq seedSequence({
                (uint32_t)std::chrono::system_clock::now().time_since_epoch().count(),
                (uint32_t)getSystemEntropy(),
                (uint32_t)WebSocketProtocol::getInstance()->getRandomBytes(8)
            });
            rng.seed(seedSequence);
        }

        std::string generateSessionID() {
            // Generate a random session ID
            auto& rng = getInstance();
            char buffer[22];
            for(int i = 0; i < 22; ++i) {
                buffer[i] = (char)(rng() % 256);
            }
            return base64Encode(buffer, 22);
        }

    private:
        static uint32_t getSystemEntropy() {
            // Get system entropy from /dev/urandom on Unix-like systems
            #ifdef _WIN32
                // Windows does not have a direct equivalent to /dev/urandom, so we will use a different method.
                std::random_device rd;
                return (uint32_t)rd();
            #else
                FILE* file = fopen("/dev/urandom", "rb");
                if (!file) {
                    // Handle error
                }
                fseek(file, 0, SEEK_SET);
                uint32_t entropy = fread(buffer, 4, 1, file);
