from logging import getLogger, DEBUG

logger = getLogger()

@lru_cache(maxsize=None)
def fetch_widgets():
    try:
        response = requests.get('https://api.example.com/widgets')
        response.raise_for_status()
        return response.json()
    except Exception as e:
        logger.error(f"Error fetching widgets: {e}")
        return []

def render_widget(widget):
    if not widget['title'] or not widget['content']:
        return ''

    if 'type' in widget and widget['type'] == 'list':
        return f"<ul>{''.join([f"<li>{item}</li>" for item in widget['content']])}</ul>"
    elif 'type' in widget and widget['type'] == 'paragraph':
        return f"<p>{widget['content']}</p>"
    else:
        return f"<div key={widget['key']}>{widget['content']}</div>"

def render_sidebar(widgets):
    html = ''
    for widget in widgets:
        html += render_widget(widget)
    return html

def main():
    widgets = fetch_widgets()
    sidebar_html = render_sidebar(widgets)

    # Add loading spinner or progress indicator here
    print(sidebar_html)

if __name__ == '__main__':
    main()

