using System;
using System.IO;
using System.Threading.Tasks;

public interface IDeserializationStrategy
{
    void Deserialize(Stream stream);
}

public class BinaryDeserializer
{
    private readonly IDeserializationStrategy _strategy;
    private readonly ILogger _logger;
    private readonly ConcurrentQueue<DeserializationTask> _tasks = new ConcurrentQueue<ConcurrentBag<DeserializationTask>>();

    public BinaryDeserializer(IDeserializationStrategy strategy, ILogger logger)
    {
        _strategy = strategy;
        _logger = logger;
    }

    public async Task LoadAndDeserializeAsync(string filePath, int maxConcurrency)
    {
        try
        {
            using (var stream = File.OpenRead(filePath))
            {
                for (int i = 0; i < maxConcurrency; i++)
                {
                    var task = new DeserializationTask(stream);
                    _tasks.Enqueue(task);
                    await Task.Run(() => _strategy.Deserialize(task.Stream));
                }

                while (_tasks.TryDequeue(out ConcurrentBag<DeserializationTask> tasks))
                {
                    foreach (var task in tasks)
                    {
                        try
                        {
                            await Task.Run(() => _strategy.Deserialize(task.Stream));
                        }
                        catch (Exception ex)
                        {
                            _logger.LogError(ex, "Error deserializing data");
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error loading and deserializing binary file");
        }
    }

    public void ConfigureCaching(bool enabled, CacheProvider provider)
    {
