```javascript
interface ElementMetadata {
    id: string;
    class: string;
    descriptions: Promise<Map<string, string>>;
    images: Promise<Map<string, string>>;
}

class ApiClientFactory {
    createApiClient(url: string): Promise<ApiClient> {
        return new Promise((resolve) => {
            const apiClient = new APIClient(url);
            resolve(apiClient);
        });
    }
}

interface ApiClient {
    fetchDescriptions(elements: HTMLElement[]): Promise<Map<string, string>>;
    fetchImages(elements: HTMLElement[]): Promise<Map<string, string>>;
}

class Queue {
    private queue: any[];
    private maxConcurrency: number;

    constructor(maxConcurrency: number) {
        this.queue = [];
        this.maxConcurrency = maxConcurrency;
    }

    add(item: any) {
        this.queue.push(item);
    }

    async start() {
        while (this.queue.length > 0) {
            const items = this.queue.splice(0, this.maxConcurrency);

            for (const item of items) {
                await item;
            }
        }
    }
}

async function fetchAndFilterElements(rootElement: HTMLElement, selector: string, filterFn: (element: ElementMetadata) => boolean, apiClientFactory: ApiClientFactory): Promise<HTMLElement[]> {
    const result = [];
    const queue = new Queue(5);

    function traverse(node: Node) {
        for (let i = 0; i < node.childNodes.length; i++) {
            traverse(node.childNodes[i]);
        }

        if (node.nodeType === Node.ELEMENT_NODE && node.nodeName.toLowerCase() === selector) {
            const metadata: ElementMetadata = {
                id: node.getAttribute('id'),
                class: node.className,
                descriptions: apiClientFactory.createApiClient('descriptions-api').fetchDescriptions([node]),
                images: apiClientFactory.createApiClient('images-api').fetchImages([node]),
            };

            queue.add(metadata.descriptions);
            queue.add(metadata.images);

            if (filterFn(metadata)) {
                result.push(node);
            }
        }
    }

    traverse(rootElement);

    await queue.start();

    return result;
}
