async function runModuleTests(moduleLabel, testSuite, loggingLevel) {
  try {
    // Dynamically load the module using import()
    const module = await import(moduleLabel);

    // Initialize blueslip mocking library before running each test
    const { mock } = await import('blueslip');

    for (const [testIndex, { label, testFunction }] of testSuite.entries()) {
      try {
        // Reset and clean up the blueslip library to its initial state
        await mock.reset();

        // Run the test with a new isolated environment
        await testFunction(label, module);

        // Log success message for passed tests
        console.log(`Test ${label} of ${moduleLabel} passed`);
      } catch (error) {
        // Log error message and detailed failure information
        console.error(`Test ${label} of ${moduleLabel} failed: ${error.message}`);
      }
    }

  } catch (error) {
    // Log error message for overall module test execution
    console.error(`Module ${moduleLabel} testing failed: ${error.message}`);
  }
}
