#include <forward_list>
#include <fstream>
#include <iostream>

void insert_after_position(std::forward_list<std::string>& list, const std::string& target,
                             const std::string& str, int position = -1) {
    auto it = list.begin();
    for (auto pos = 0; pos <= position && it != list.end(); ++pos, ++it) {
        if (*it == target) {
            list.insert_after(it, str);
            return;
        }
    }

    // Target string not found, insert at the end
    list.insert_after(list.end(), str);
}
