        static void Main(string[] args)
        {
            if (args.Length < 1)
            {
                Console.WriteLine("Please provide file paths as command-line arguments.");
                return;
            }

            RandomNumberGenerator rng = new RandomNumberGenerator();

            int largestInteger = int.MinValue;
            long totalSum = 0;

            foreach (string filePath in args)
            {
                if (!File.Exists(filePath))
                {
                    Console.WriteLine($"Error: File '{filePath}' not found.");
                    continue;
                }

                try
                {
                    string[] lines = File.ReadAllLines(filePath);

                    foreach (string line in lines)
                    {
                        int integer;

                        if (int.TryParse(line, out integer))
                        {
                            largestInteger = Math.Max(largestInteger, integer);
                            totalSum += integer;
                        }
                        else
                        {
                            Console.WriteLine($"Error parsing '{filePath}': {line}");
                        }
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error reading '{filePath}': {ex.Message}");
                }
            }

            if (args.Length > 0)
            {
                int average = totalSum / args.Length;
                Console.WriteLine($"Largest integer: {largestInteger}");
                Console.WriteLine($"Average: {average}");
            }
        }
    }
}
