<?php
class SecureSessionManager {
    private $mongoClient;
    private $tokenLength;

    public function __construct($mongoClient) {
        $this->mongoClient = $mongoClient;
        $this->tokenLength = 64; // default token length, can be customized
    }

    public function generateToken() {
        return bin2hex(random_bytes($this->tokenLength));
    }

    public function startSession($userId) {
        $sessionToken = $this->generateToken();
        $this->mongoClient->collection("sessions")->insertOne(['user_id' => $userId, 'token' => $sessionToken]);
        return $sessionToken;
    }

    public function validateSession($token) {
        $cursor = $this->mongoClient->collection("sessions")->find(['token' => $token]);
        $result = $cursor->limit(1)->next();
        if ($result && $result['user_id']) {
            return $result['user_id'];
        } else {
            return null;
        }
    }

    public function endSession($token) {
        $this->mongoClient->collection("sessions")->deleteOne(['token' => $token]);
    }
}

