function readDynamicFiles(filePath, callback) {
    try {
        const fs = require('fs');
        const path = require('path');

        if (!filePath) {
            throw new Error('File path is required.');
        }

        filePath = path.normalize(filePath);

        fs.readFile(filePath, (err, data) => {
            if (err) {
                callback(err);
            } else {
                callback(null, data.toString());
            }
        });
    } catch (error) {
        callback(error);
    }
}
