from kubernetes import client
import os
import subprocess
import time
import threading

def create_namespace(k8s_client, namespace_name, parent_namespace=None):
    def try_create_namespace():
        try:
            if not parent_namespace:
                return k8s_client.create_namespace(client.V1Namespace(namespace_name))
            else:
                return k8s_client.create_namespace(client.V1Namespace(namespace_name), parent_namespace)
        except Exception as e:
            print(f"Error creating namespace: {str(e)}")
            time.sleep(5)  # retry after 5 seconds
            try_create_namespace()

    if not os.path.exists("namespace_lock"):
        with open("namespace_lock", "w") as f:
            pass

    def lock_and_create_namespace():
        with open("namespace_lock", "r+"):  # acquire the lock
            try_create_namespace()
            os.remove("namespace_lock")  # release the lock

    threading.Thread(target=lock_and_create_namespace).start()

def analyze_pod_resources(k8s_client, pod_name):
    def get_pod_resources():
        return k8s_client.read_namespaced_pod(pod_name)

    def calculate_average_usage(metrics):
        total_cpu = 0
        total_memory = 0
        for metric in metrics:
            total_cpu += metric.cpu_usage
            total_memory += metric.memory_usage
        average_cpu = total_cpu / len(metrics)
        average_memory = total_memory / len(metrics)
        return {
            "cpu": average_cpu,
            "memory": average_memory,
        }

    def get_pod_restart_count():
        pod = k8s_client.read_namespaced_pod(pod_name)
        return pod.status.container_statuses[0].restart_count

    def monitor_pod_resources(k8s_client, pod_name):
        metrics = []
        for _ in range(10):  # collect metrics over a time window of 10 seconds
            metric = get_pod_resources()
            metrics.append(metric)
            time.sleep(1)

        average_metrics = calculate_average_usage(metrics)
        restart_count = get_pod_restart_count()

        return {
            "pod": pod_name,
            "cpu": average_metrics["cpu"],
            "memory": average_metrics["memory"],
            "restarts": restart_count,
        }

    c_function = subprocess.run(["/path/to/c/function", pod_name], capture_output=True)
    result = monitor_pod_resources(k8s_client, pod_name)

    return {
        "pod_with_highest_consumption": max(result, key=lambda x: (x["cpu"] + x["memory"]) / 2),
        "average_metrics": result,
    }

def main():
    k8s_config.load_kubeconfig()
    namespace = create_namespace(k8s_client, "my-namespace")
    results = analyze_pod_resources(k8s_client, "my-pod")

if __name__ == "__main__":
    main()
