import re
from bs4 import BeautifulSoup
from functools import lru_cache
from logging import getLogger, basicConfig

basicConfig(level='DEBUG')

logger = getLogger(__name__)

MAX_CACHE_SIZE = 500

cache = {}

def extract_and_cache_elements(html_doc: str, tag: str, attribute: str, value: str) -> list:
    if not isinstance(html_doc, str):
        raise ValueError("HTML document must be a string")

    try:
        soup = BeautifulSoup(html_doc, 'html.parser')
    except Exception as e:
        logger.error(f"Failed to parse HTML: {e}")
        return []

    key = f"{tag}:{attribute}:{value}"
    if key in cache:
        logger.debug(f"Cache hit for {key}")
        return cache[key]

    result = []
    if attribute:
        if ',' in attribute:
            attributes = [attr.strip() for attr in attribute.split(',')]
            for elem in soup.find_all(tag, **{attribute: value}):
                if any(attr in elem.get(attribute) for attr in attributes):
                    result.append(elem)
        else:
            result = [elem for elem in soup.find_all(tag, {attribute: value})]

    else:
        result = [elem for elem in soup.find_all(tag)]

    cache[key] = result[:MAX_CACHE_SIZE]
    logger.debug(f"Cache size after storing {key}: {len(cache)}")

    return result
