function renderFooterScripts(scripts) {
    const cache = {};
    let loadedCount = 0;

    // Function to fetch scripts from API endpoint
    async function loadScript(script) {
        if (script.code && script.type) {
            if (!cache[script.code]) {
                try {
                    const response = await fetch('/api/scripts', { method: 'POST', body: JSON.stringify({ code: script.code }) });
                    if (response.ok) {
                        const data = await response.json();
                        cache[script.code] = data;
                    } else {
                        console.error('Failed to load script:', script.code);
                    }
                } catch (error) {
                    console.error('Error loading script:', script.code, error);
                }
            }
        }
    }

    // Function to render scripts
    function renderScripts() {
        const scriptElements = [];
        for (const script of scripts) {
            if (!script.code || !script.type) {
                continue;
            }
            loadScript(script).then(() => {
                loadedCount++;
                if (loadedCount === scripts.length) {
                    // Render all scripts
                    const footer = document.getElementById('footer');
                    for (const code in cache) {
                        const scriptElement = document.createElement('script');
                        scriptElement.src = `/api/scripts/${code}`;
                        scriptElement.type = script.type;
                        footer.appendChild(scriptElement);
                    }
                }
            });
        }
    }

    // Render scripts and handle errors
    renderScripts();

    return `
      <footer id="footer">
        <!-- Scripts will be rendered here -->
      </footer>
    `;
}
