const require = require('blueslip');
const { parallelizeTests } = require('parallel-tests');
const { logLevel } = require('logging');

async function runModuleTests(moduleName) {
  const module = await require(moduleName);

  const testRunner = async (testFunction) => {
    try {
      await testFunction();
    } catch (error) {
      console.error(`Test ${moduleName} failed: ${error}`);
    }
  };

  for (const test of module.tests) {
    await blueslip.reset();
    await testRunner(test);
    await blueslip.cleanup();
    logLevel.info(`Module ${moduleName} tested: ${test.name}`);
  }
}

async function runModules(modules, concurrency = 1) {
  const parallelTestRunners = [];

  for (const moduleName of modules) {
    const module = require(moduleName);

    for (const test of module.tests) {
      await blueslip.reset();
      try {
        await test();
      } catch (error) {
        console.error(`Test ${moduleName} failed: ${error}`);
      }
      await blueslip.cleanup();
      logLevel.info(`Module ${moduleName} tested: ${test.name}`);
    }
  }
}

async function runTests(modules, concurrency = 1) {
  const parallelTestRunners = [];

  for (const moduleName of modules) {
    await require(moduleName);

    for (let i = 0; i < concurrency; i++) {
      parallelTestRunners.push(runModuleTests(moduleName));
    }

    await Promise.all(parallelTestRunners.map((promise) => promise.then(() => console.log(`Module ${moduleName} tested.`))));
  }
}

