import yaml
import kubernetes as k8s
from packaging import version

class DeploymentManager:
    def __init__(self, config_file):
        self.config = yaml.safe_load(config_file)
        self.k8s_client = k8s.client.V1Api(k8s.client.ApiClient(configuration=k8s.client.Configuration()))
        self.dependency_graph = {}
        self.deployed_applications = set()
        self.concurrent_deployments = 5

    def load_config(self):
        for app in self.config['applications']:
            if 'depends_on' in app:
                self.dependency_graph[app['name']] = app['depends_on']
            else:
                self.dependency_graph[app['name']] = []

    def is_prereq_met(self, app_name):
        return all(self.has_deployed_app(prereq) for prereq in self.dependency_graph[app_name])

    def has_deployed_app(self, app_name):
        return app_name in self.deployed_applications

    def deploy_app(self, app_config):
        try:
            image = k8s.client.V1PodTemplateSpec(image=app_config['image'])
            deployment = k8s.create_namespaced_deployment(app_config['name'], spec=image)
            self.k8s_client.patch_namespaced_deployment_status(app_config['name'], "default", deployment.metadata.uid, {"status": {"availableReplicas": 1}})
        except Exception as e:
            print(f"Error deploying {app_config['name']}: {str(e)}")
            return False
        else:
            self.deployed_applications.add(app_config['name'])
            print(f"Deployed {app_config['name']} successfully!")
            return True

    def scale_app(self, app_name, replicas):
        try:
            deployment = k8s.get_namespaced_deployment_status(app_name, "default")
            deployment.spec.replicas = replicas
            self.k8s_client.patch_namespaced_deployment_status(app_name, "default", deployment.metadata.uid, {"status": {"availableReplicas": replicas}})
        except Exception as e:
            print(f"Error scaling {app_name}: {str(e)}")

    def check_app_health(self):
        try:
            for app in self.config['applications']:
                if not self.has_deployed_app(app['name']):
                    continue
                deployment = k8s.get_namespaced_deployment_status(app['name'], "default")
                if deployment.status.availableReplicas != int(app['replicas']):
                    print(f"{app['name']} scaling to {int(app['replicas'])} replicas...")
                    self.scale_app(app['name'], int(app['replicas']))
        except Exception as e:
            print(f"Error checking app health: {str(e)}")

    def manage_concurrency(self):
        while len(self.deployed_applications) > 0 and len(self.k8s_client.list_namespaced_deployment("default", label_selector="app").items) >= self.concurrent_deployments:
            time.sleep(1)

def main():
    config_file = open('config.yaml', 'r')
    deployment_manager = DeploymentManager(config_file)
    deployment_manager.load_config()
    for app in deployment_manager.config['applications']:
        if not deployment_manager.is_prereq_met(app['name']):
            continue
        deployment_manager.deploy_app(app)
        deployment_manager.manage_concurrency()
    deployment_manager.check_app_health()

if __name__ == "__main__":
    main()
```

