namespace beast = boost::beast;
namespace http = beast::http;

void sendGetRequest(int port) {
    beast::io_context ioc;

    auto const endpoint = beast::ip::make_endpoint_v4("localhost", port);
    beast::tcp_stream stream(ioc);

    beast::ssl_set stream_ ssl(stream, boost::asio::use_certificate_file("path_to_your_crt.pem", boost::asio::file_mode::read));
    beast::get_lowest_layer(stream).set_option(beast::socket_base::linger{});
    beast::ssl_set stream_.set_option(beast::socket_base::keep_alive(true));

    beast::http::request<beast::http::string_body> req;
    req.version(11);
    req.target("/");
    req.method(http::verb::get);

    beast::flat_buffer buffer;

    beast::http::response<beast::http::string_body> res;

    stream.async_connect(endpoint, [&req, &res](boost::system::error_code ec) {
        if (!ec)
            beast::ssl_set(stream).async_handshake(beast::ssl_set::handshake_type::client, req.version(), buffer.assigned_buffer_size(), [](boost::system::error_code ec) {
                if (!ec) {
                    // Send the request
                    beast::http::write(stream_.next_layer().next_layer(), req);

                    // Read the response
                    beast::flat_buffer buffer_;
                    beast::http::read(stream_.next_layer().next_layer(), buffer_, res);

                    // Verify the response against expected values
                }
            });
    });

    int numRequests = 0;
    int proxySessions = 0;
    int internalErrors = 0;

    std::cout << "Number of requests: " << numRequests << "\n";
    std::cout << "Proxy sessions: " << proxySessions << "\n";
    std::cout << "Internal errors: " << internalErrors << "\n";

}

