#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <memory>

class OctreeNode {
public:
    enum class NodeState { EMPTY, FULL, LEAF };

    OctreeNode(NodeState state) : state(state) {}
    virtual ~OctreeNode() {}

    NodeState getState() const { return state; }

protected:
    NodeState state;
};

class LeafNode : public OctreeNode {
public:
    std::vector<std::pair<float, float, float>> dataPoints;

    LeafNode() : OctreeNode(NodeState::LEAF) {}
};

class InternalNode : public OctreeNode {
public:
    bool isSplit = false;
    std::unique_ptr<OctreeNode> children[8];

    InternalNode() : OctreeNode(NodeState::EMPTY) {}

    ~InternalNode() {
        if (isSplit) {
            for (auto& child : children) {
                delete child.get();
            }
        }
    }

    void split() {
        isSplit = true;
        for (int i = 0; i < 8; ++i) {
            children[i] = std::make_unique<InternalNode>();
        }
    }
};

class Octree {
public:
    static const int MAX_DEPTH = 16;

    Octree(int initialCapacity, int threadCount)
        : root(new InternalNode()), depth(0), capacity(initialCapacity), threads(threadCount) {}

    ~Octree() {
        destroyTree(root.get());
    }

    void insert(std::pair<float, float, float> point) {
        auto node = &root;
        for (int i = 0; i < MAX_DEPTH; ++i) {
            if (!node->isSplit || node->getState() == NodeState::EMPTY) {
                break;
            }
            int index = calculateIndex(point);
            node = &(*node)->children[index].get();
            depth = i + 1;
        }
        if (node->getState() == NodeState::LEAF) {
            static std::mutex mutex;
            auto lock = std::unique_lock<std::mutex>(mutex, std::deferred);
            node->dataPoints.push_back(point);
        } else if (node->isSplit) {
            node->split();
        }
    }

    bool query(std::pair<float, float, float> point) {
        auto node = &root;
        for (int i = 0; i < MAX_DEPTH; ++i) {
            int index = calculateIndex(point);
            if (!node->children[index]) {
                return false;
            }
            node = &(*node)->children[index].get();
        }
        return std::any_of(node->dataPoints.begin(), node->dataPoints.end(),
                            [&point](const auto& point) { return (point.first - 1.0f <= point.second &&
                                                                                      point.second + 1.0f >= point.third); });
    }

private:
    static int calculateIndex(const std::pair<float, float, float>& point) {
        // Calculate the octree index based on the 3D spatial coordinates
    }

    void destroyTree(OctreeNode* node) {
        if (!node) return;
        if (auto leaf = dynamic_cast<LeafNode*>(node)) {
            for (const auto& point : leaf->dataPoints) {
                // Clean up data points as needed
            }
        } else if (auto internal = dynamic_cast<InternalNode*>(node)) {
            for (int i = 0; i < 8; ++i) {
                destroyTree(internal->children[i].get());
            }
        }
    }

    int depth;
    std::unique_ptr<OctreeNode> root;
    int capacity;
    int threads;
};

