import logging
from functools import wraps
from datetime import datetime

class ConfigLoader:
    def __init__(self):
        self.cache = {}
        self.params_store = None
        self.gsm = None
        self.config_version = 1.0

    @wraps(get_config)
    def get_config(self, env):
        key = f"config/{env}"
        if key not in self.cache:
            value = None
            try:
                if os.environ.get("AWS_REGION"):
                    self.params_store = boto3.client("ssm", region_name=os.environ["AWS_REGION"])
                    value = self.params_store.get_parameter(Name=key, WithDecryption=True)["Parameter"]["Value"]
                elif os.environ.get("GOOGLE_APPLICATION_CREDENTIALS"):
                    self.gsm = gcloud.secretmanager.SecretManagerClient()
                    response = self.gsm.access_secret_version(request={"name": f"projects/your-project/secrets/{key}/versions/latest"})
                    value = response.payload.data.decode("utf-8")
            except Exception as e:
                logging.error(f"Error loading config for {env}: {str(e)}")
                value = None
            self.cache[key] = value
        return self.cache.get(key)

    def load_config(self):
        envs = ["dev", "test", "prod"]
        for env in envs:
            if not (config := self.get_config(env)):
                raise Exception(f"Environment-specific config {env} not found")
            logging.info(f"Loaded environment-specific config for {env}")

    @wraps(validate_config)
    def validate_config(self, config):
        # Implement your custom validation logic here
        pass

    @wraps(test_config)
    def test_config(self, config):
        # Implement your custom testing logic here
        pass

    def apply_config(self):
        try:
            self.load_config()
            if not (config := self.get_config("prod")):  # Assume production environment is the target
                raise Exception("No production configuration found")
            validated = self.validate_config(config)
            tested = self.test_config(validated)
            logging.info("Config applied successfully!")
        except Exception as e:
            logging.error(f"Error applying config: {str(e)}")

    def check_version(self):
        current_version = self.get_config("version")
        if not (previous_version := self.cache.get("config/prev-version")) or current_version != previous_version:
            self.config_version += 1
            self.set_config("version", str(self.config_version))
            logging.info(f"Config version updated to {self.config_version}")

    def set_config(self, key, value):
        if os.environ.get("AWS_REGION"):
            self.params_store.put_parameter(Name=key, Value=value, Type="String", Overwrite=True)
        elif os.environ.get("GOOGLE_APPLICATION_CREDENTIALS"):
            response = self.gsm.create_secret_version(request={"name": f"projects/your-project/secrets/{key}/versions/latest"})
            value_bytes = value.encode("utf-8")
            self.gsm.update_secret(request={"name": f"projects/your-project/secrets/{key}/versions/latest", "payload": {"data": value_bytes}})

    def cache_config(self):
        try:
            for key, value in self.cache.items():
                self.set_config(key, value)
        except Exception as e:
            logging.error(f"Error caching config: {str(e)}")

    def notify_ci_cd(self):
        if not (config := self.get_config("prod")):
            raise Exception("No production configuration found")
        # Implement your custom CI/CD notification logic here
        pass

# Example usage:

loader = ConfigLoader()
loader.apply_config()

try:
    while True:
        time.sleep(10)  # Check for config updates every 10 seconds
        loader.check_version()
except KeyboardInterrupt:
    logging.info("Interrupted. Caching and notifying CI/CD pipeline...")
    loader.cache_config()
    loader.notify_ci_cd()
