#include <pthread.h>

typedef struct Node {
    char* name;
    struct Node* parent;
    struct Node* children;
} Node;

Node* node_new(char* name) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->name = (char*)malloc(strlen(name)+1);
    strcpy(node->name, name);
    node->parent = NULL;
    node->children = NULL;
    return node;
}

void node_free(Node* node) {
    free(node->name);
    free(node);
}

Node** traverse_DOM(Node* root, int depth_limit, void (*callback)(Node*, int), char** css_selectors, pthread_t** threads) {
    Node** matched_nodes = (Node**)malloc((depth_limit+1)*sizeof(Node*));
    for(int i=0; i<=depth_limit; i++) {
        matched_nodes[i] = NULL;
    }

    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);

    int num_threads = 4; // adjust based on system resources
    for(int t=0; t<num_threads; t++) {
        pthread_create(threads+t, &attr, (void*)traverse_DOM_thread, (void*)root);
    }

    pthread_attr_destroy(&attr);

    for(int i=0; i<num_threads; i++) {
        pthread_join(*threads+i, NULL);
    }

    free(matched_nodes);
    return NULL;
}

void traverse_DOM_thread(void* arg) {
