#define SEMAPHORE_ERROR(code) \
    do { \
        if ((code) < 0) { \
            perror("semaphore operation failed"); \
        } \
    } while (0)

int main() {
    // Initialize semaphore manager
    CloudSemaphoreManager* sem_manager = cloud_semaphore_manager_init("cloud-service.com", 8080);

    // Create and initialize the semaphore
    void *sem = cloud_semaphore_create(10); // Initialize with 10 permits

    // Acquire and release the semaphore in a loop
    for (int i = 0; i < 10000; i++) {
        if (cloud_semaphore_acquire(sem) == -1) {
            SEMAPHORE_ERROR(-1);
            break;
        }
        // Access shared resource
        printf("Accessing shared resource...\n");
        sleep(1); // Simulate work
        cloud_semaphore_release(sem);
    }

    // Destroy the semaphore and close socket
    cloud_semaphore_destroy(sem);

    // Clean up semaphore manager
    cloud_semaphore_manager_free(sem_manager);

    return 0;
}

