const { S3Client, Upload } = require('@aws-sdk/client-s3');
const { getAuth } = require('./auth');

async function uploadFileFromUrl(url) {
  const auth = await getAuth();
  if (!auth) return 'Unauthorized';

  try {
    const s3 = new S3Client({ region: 'your-region' });
    const params = { Bucket: 'your-bucket', Key: url.split('/').pop(), Body: '' };

    // Validate file type
    const fileType = await validateFileType(url);
    if (!fileType) return 'Unsupported file type';

    // Split large files into chunks (if needed)
    if (params.Body.size > 500 * 1024 * 1024) {
      params.Body = await splitFileIntoChunks(params.Body, 10);
    }

    const uploader = new Upload({
      client: s3,
      params,
      onProgress: (percentDone) => console.log(`Uploading file... ${percentDone}%`),
      concurrentUploads: 5
    });

    // Resume upload if interrupted
    let attempt = 0;
    while (attempt < 4) {
      try {
        await uploader.upload();
        break;
      } catch (error) {
        if (error.name === 'S3RequestError') {
          console.log('Upload failed, retrying...');
          await new Promise((resolve) => setTimeout(resolve, Math.pow(2, attempt++) * 1000));
        } else throw error;
      }
    }

    // Log completion
    console.log(`File uploaded successfully: ${params.Key}`);

