using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Threading;

public class DynamicSqlExecutor
{
    public static IDbDataReader ExecuteQuery(string connectionString, List<string> values, string commandTemplate)
    {
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            connection.Open();

            List<IDbCommand> commands = values.Select(value => CreateParameterizedCommand(connection, commandTemplate, value)).ToList();
            using (SqlDataReader reader = ExecuteCommands(commands))
            {
                return reader;
            }
        }
    }

    private static IDbCommand CreateParameterizedCommand(SqlConnection connection, string commandTemplate, string value)
    {
        SqlCommand command = new SqlCommand(commandTemplate, connection);
        command.Parameters.AddWithValue("@value", value);

        return command;
    }

    private static SqlDataReader ExecuteCommands(List<IDbCommand> commands)
    {
        using (SqlTransaction transaction = connection.BeginTransaction())
        {
            try
            {
                foreach (IDbCommand command in commands)
                {
                    try
                    {
                        command.ExecuteNonQuery();
                    }
                    catch (SqlException ex) when (ex.Class == 16)
                    {
                        // Retry logic for transient errors
                        int attempt = 0;
                        while (attempt < 3 && ex.LastErrorCode != 0)
                        {
                            Thread.Sleep(500);
                            try
                            {
                                command.ExecuteNonQuery();
                            }
                            catch (SqlException ex2) when (ex2.Class == 16)
                            {
                                if (ex2.LastErrorCode == 0)
                                    break;
                                else
                                    throw;
                            }
                            attempt++;
                        }

                        // Rollback transaction on error
                        transaction.Rollback();
                    }
                }

                // Commit the transaction
                transaction.Commit();
            }
            catch (SqlException ex) when (ex.Class != 16)
            {
                // Log the error
                System.Diagnostics.EventLog.WriteEntry("Error executing SQL query", ex.Message, EventLogEntryType.Error);

                // Rollback the transaction
                transaction.Rollback();

                throw;
            }

            return new SqlDataReader(commands.Last().CommandText);
        }
    }
}
