from bs4 import BeautifulSoup
import re
from functools import lru_cache
from typing import List

class Cache:
    def __init__(self):
        self.cache = {}
        self.size = 500

    @lru_cache(maxsize=self.size)
    def get(self, key):
        return self.cache.get(key)

    def set(self, key, value):
        if len(self.cache) >= self.size:
            self.cache.popitem(last=False)
        self.cache[key] = value

    def clear(self):
        self.cache.clear()

@lru_cache(maxsize=5000)
def extract_and_cache_elements(html_doc: str, tag: str, attribute: str, value: str) -> List[BeautifulSoup]:
    try:
        soup = BeautifulSoup(html_doc, 'html.parser')
        result = []

        if ',' in value:
            values = [v.strip() for v in value.split(',')]
            elements = [soup.find(tag, {attribute: value}) for value in values]
        else:
            element = soup.find(tag, {attribute: value})
            if element is not None:
                result.append(element)

        cache_key = f"{tag}:{attribute}:{value}"
        cache = Cache()

        if len(result) > 0:
            cache.set(cache_key, result)
            print(f"Cache hit for tag='{tag}', attribute='{attribute}', value='{value}'")
        else:
            cached_result = cache.get(cache_key)
            if cached_result is not None:
                result.extend(cached_result)
                print(f"Cache miss for tag='{tag}', attribute='{attribute}', value='{value}'. Using cached result.")
            else:
                print(f"No cached result found for tag='{tag}', attribute='{attribute}', value='{value}'")

        return [BeautifulSoup(str(elem), 'html.parser') for elem in result]

    except Exception as e:
        print(f"An error occurred: {str(e)}")

# Usage example:
html_doc = "<div id='header'><h1>Hello, World!</h1></div><p>This is a paragraph.</p>"
tag = "h1"
attribute = "id"
value = "header"

result = extract_and_cache_elements(html_doc, tag, attribute, value)
