#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <string.h>
#include <time.h>

#define MAX_CMD_LENGTH 1024
#define MAX_ARGC 128
#define TIMEOUT 60 // seconds

void logCommandExecution(pid_t pid, int success) {
    // Implement logging functionality here
}

int executeBackgroundCommand(char *commands[], char **envp, FILE *logFile) {
    int i;
    pid_t childPid;
    int status;
    struct timespec timeout;

    if (!commands || !*commands)
        return 0;

    for (i = 0; commands[i]; i++) {
        // Split the command string into individual commands
        char *command = strtok(commands[i], " &&");
        while (command) {
            // Set up environment variables and timeout
            char **envcopy = (char **)malloc((envp ? strlen(envp) + 1 : 0) * sizeof(char *));
            if (envp)
                envcopy[0] = envp;
            int timeoutSet = 0;

            // Create a child process for the command
            childPid = fork();
            if (!childPid) {
                // Child process

                // Set up signal handling to ensure cleanup on termination
                signal(SIGINT, SIG_DFL);
                signal(SIGTERM, SIG_DFL);

                // Check for timeout and set it if needed
                if (timeoutSet)
                    nanosleep(&timeout, NULL);

                // Execute the command with environment variables
                execve(command, &commands[0], envcopy);
            } else {
                // Parent process

                // Wait for child to finish or timeout
                if (timeoutSet) {
                    struct timespec endtime;
                    clock_gettime(CLOCK_REALTIME, &endtime);
                    endtime.tv_sec += TIMEOUT;
                    endtime.tv_nsec /= 1000000;
                    while ((status = waitpid(childPid, NULL, WNOHANG | WNOWAIT)) > 0) {
                        if (clock_nanosleep(NULL, &endtime, NULL, NULL) < 0)
                            // Command timed out
                            kill(childPid, SIGTERM);
                    }
                } else {
                    status = waitpid(childPid, NULL, 0);
                }

                // Check for command success or failure
                int successCmd = WEXITSTATUS(status);

                if (successCmd || status < 0) {
                    logCommandExecution(childPid, 0); // Log failure or timeout
                    kill(childPid, SIGTERM); // Terminate child process
                    waitpid(childPid, NULL, 0);
                } else {
                    logCommandExecution(childPid, 1); // Log success
                }
            }

            free(envcopy);
            command = strtok(NULL, " &&");
        }
    }

    return i ? 1 : 0;
}
