#include <mutex>
#include <condition_variable>
#include <thread>
#include <map>
#include <queue>

class AdvancedOctreeManager {
public:
    AdvancedOctreeManager(int nodeCapacity, int maxNodes);
    ~AdvancedOctreeManager();

    void seedOctree(const std::vector<std::pair<int, float>> &dataPoints);

    void setNodeCapacity(int capacity) { nodeCapacity = capacity; }

    // Get spatial data point
    std::vector<float> getSpatialDataPoint(std::string sensorId, float x, float y, float z);

private:
    struct OctreeNode {
        int id;
        std::map<int, float> dataPoints;
        bool isSplit;

        OctreeNode* leftChild;
        OctreeNode* rightChild;
    };

    void constructOctree(OctreeNode*& node, const std::vector<std::pair<int, float>> &dataPoints);

    void splitNode(OctreeNode*& node);

    int nodeCapacity;
    int maxNodes;
    std::mutex octreeMutex;
    std::condition_variable cv;

    OctreeNode* root;
};

AdvancedOctreeManager::AdvancedOctreeManager(int nodeCapacity, int maxNodes) : nodeCapacity(nodeCapacity), maxNodes(maxNodes) {
    root = nullptr;
}

AdvancedOctreeManager::~AdvancedOctreeManager() {
    if (root) {
        std::queue<OctreeNode*> queue({&root});
        while (!queue.empty()) {
            OctreeNode* node = queue.front();
            queue.pop();

            if (node->leftChild) {
                queue.push(node->leftChild);
            }

            if (node->rightChild) {
                queue.push(node->rightChild);
            }

            delete node;
        }
    }
}

void AdvancedOctreeManager::seedOctree(const std::vector<std::pair<int, float>> &dataPoints) {
    root = nullptr;

    constructOctree(&root, dataPoints);

    cv.notify_all();
}

std::vector<float> AdvancedOctreeManager::getSpatialDataPoint(std::string sensorId, float x, float y, float z) {
    OctreeNode* node = root;
    while (node && (node->leftChild || node->rightChild)) {
        if (x < node->dataPoints.at(0).second / 2.0f) {
            node = node->leftChild;
        } else if (y > node->dataPoints.at(1).second / 2.0f) {
            node = node->rightChild;
        }
    }

    if (!node || !node->isSplit) {
        return {};
    }

    for (const auto &point : node->dataPoints) {
        if (point.second == x && point.first == sensorId) {
            return {x, y, z};
        }
    }

    return {};
}
