import os
import hashlib
import threading
from queue import Queue
from logging import Logger
import sqlite3

class IntegrityChecker:
    def __init__(self, log_dir, exclude_patterns=None):
        self.log_dir = log_dir
        self.exclude_patterns = exclude_patterns if exclude_patterns else []
        self.sha256_hashes = {}
        self.db_pool = sqlite3.ConnectionPool(minconn=10, maxconn=20)

    def check_file_integrity(self, file_path):
        try:
            with open(file_path, 'rb') as f:
                sha256_hash = hashlib.sha256(f.read()).hexdigest()
                if file_path not in self.sha256_hashes or sha256_hash != self.sha256_hashes[file_path]:
                    print(f"File integrity error: {file_path}")
                    # Report to monitoring system API
                    self.report_integrity_issue(file_path)
                    return False
            return True
        except Exception as e:
            Logger.error("Error processing file {}: {}".format(file_path, str(e)))
            return None

    def check_dir_integrity(self):
        threads = []
        queue = Queue()

        def worker():
            while not queue.empty():
                file_path = queue.get()
                if self.check_file_integrity(file_path):
                    self.sha256_hashes[file_path] = hashlib.sha256(open(file_path, 'rb').read()).hexdigest()
                else:
                    # Delete log files that fail the integrity check
                    os.remove(file_path)

        for file in os.listdir(self.log_dir):
            file_path = os.path.join(self.log_dir, file)
            if not self.exclude_patterns or not any(pattern.match(file) for pattern in self.exclude_patterns):
                queue.put(file_path)
                thread = threading.Thread(target=worker)
                threads.append(thread)
                thread.start()

        for thread in threads:
            thread.join()

    def report_integrity_issue(self, file_path):
        # API call to external monitoring system
        pass

if __name__ == "__main__":
    ic = IntegrityChecker("/path/to/log/directory", exclude_patterns=[r"error.log", r"warning.log"])
    ic.check_dir_integrity()
