import json
import requests

def validate_jwt_token(token_json):
    try:
        token_data = json.loads(token_json)
    except json.JSONDecodeError:
        return False

    required_fields = ['sub', 'exp', 'iat', 'aud']

    for field in required_fields:
        if field not in token_data or not isinstance(token_data[field], str):
            return False

    if not (isinstance(int(token_data['exp']), int) and isinstance(int(token_data['iat']), int)):
        return False

    if not all(isinstance(x, int) for x in [int(token_data['exp']), int(token_data['iat'])]):
        return False

    sub = token_data['sub']

    try:
        user_id = int(sub)
    except ValueError:
        return False

    try:
        user_db_response = requests.get(f'http://user-service.com/users/{user_id}')
        if user_db_response.status_code != 200:
            return False
    except requests.exceptions.RequestException as e:
        print(f"Failed to query user database: {e}")
        return False

    try:
        token_validation_service_response = requests.post('https://token-validation-service.com/validate', json=token_data)

        if token_validation_service_response.status_code == 200:
            return True
        elif token_validation_service_response.status_code == 401:
            print("Token has expired")
            return False
        else:
            print(f"Invalid token: {token_validation_service_response.text}")
            return False

    except requests.exceptions.RequestException as e:
        print(f"Failed to validate token against service: {e}")
        return False

