def validate_token(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        token_json = kwargs.get('token_json')
        if not token_json:
            return False

        try:
            token_data = json.loads(token_json)
        except json.JSONDecodeError as e:
            print(f"Invalid JSON: {e}")
            return False

        if 'sub' not in token_data or 'exp' not in token_data or 'iat' not in token_data or 'aud' not in token_data or 'scope' not in token_data:
            return False

        sub = token_data['sub']
        exp = token_data['exp']
        iat = token_data['iat']
        aud = token_data['aud']
        scope = token_data['scope']

        if isinstance(sub, str) and not cache.get('user_exists', sub):
            # User does not exist in the database
            return False

        if time.time() > exp:
            # Token has expired
            return False

        if iat + (exp - iat) < time.time():
            # Token is invalid (not issued at the expected time)
            return False

        if aud != 'expected_aud':
            # Token audience does not match the expected one
            return False

        if scope == "admin":
            # Additional permissions checks for admin tokens
            pass

        @cache.cached(ttl=60)  # Cache token validation results for 1 minute
        def validate_token_against_service(token_json):
            # Call the external API to validate the token
            # ...
            return True

        if not validate_token_against_service(token_json):
            return False

        return True

    return wrapper

