    public async Task<byte[]> EncryptFileAsync(string filePath, string encryptionKey, string salt)
    {
        using (var fileStream = File.OpenRead(filePath))
        {
            var nonce = GenerateNonce();
            var iv = GenerateIv();
            var cipherText = await EncryptStream(fileStream, nonce, iv, encryptionKey);
            var metadata = new Metadata { Nonce = nonce, Iv = iv, Tag = GenerateTag(cipherText) };

            // Store file encryption metadata in the distributed storage system
            await StoreMetadataAsync(metadata);

            return cipherText;
        }
    }

    public async Task<byte[]> DecryptFileAsync(string filePath, string encryptionKey)
    {
        using (var fileStream = File.OpenRead(filePath))
        {
            var metadata = await RetrieveMetadataAsync(filePath);
            var nonce = metadata.Nonce;
            var iv = metadata.Iv;
            var cipherText = new byte[fileStream.Length - 16]; // adjust for metadata
            await fileStream.ReadAsync(cipherText.AsMemory());

            return DecryptStream(cipherText, nonce, iv, encryptionKey);
        }
    }

    private async Task<byte[]> EncryptStream(Stream stream, byte[] nonce, byte[] iv, string encryptionKey)
    {
        using (var aesGcm = AesGcmEncryptor.CreateAesGcm(nonce, iv, encryptionKey))
        {
            var cipherText = new byte[stream.Length];
            await stream.CopyToAsync(new MemoryStream(cipherText));
            return cipherText;
