    private byte[] DecryptStream(byte[] cipherText, byte[] nonce, byte[] iv, string encryptionKey)
    {
        using (var aesGcm = AesGcmEncryptor.CreateAesGcm(nonce, iv, encryptionKey))
        {
            var plaintext = new byte[cipherText.Length];
            aesGcm.Decrypt(cipherText, plaintext);
