use std::env;
use std::fs::DirBuilder;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::process::Command;

struct FileManagement {
    work_dir: PathBuf,
}

impl FileManagement {
    fn new() -> Self {
        let mut work_dir = env::var("WORK_DIR").ok_or(io::Error::new(
            io::ErrorKind::Other,
            "WORK_DIR environment variable not set",
        ))
        .and_then(|dir| dir.parse::<PathBuf>().map_err(|_| io::Error::new(
            io::ErrorKind::Other,
            "Invalid WORK_DIR value",
        )));

        if work_dir.is_err() {
            let tmp_dir = DirBuilder::new()
                .prefix("ci-pipeline")
                .create_in("/tmp")
                .expect("Failed to create temporary directory");

            work_dir = Some(tmp_dir.join(format!("pipeline-{}", uuid::Uuid::new_v4())));
            work_dir = work_dir.map(|dir| dir.canonicalize());
        }

        FileManagement { work_dir: work_dir.ok_or(io::Error::new(
            io::ErrorKind::Other,
            "Failed to determine working directory",
        ))? }
    }

    fn execute_command(&self, command: &str) -> io::Result<()> {
        Command::new("bash")
            .arg("-c")
            .arg(command)
            .current_dir(&self.work_dir)
            .status()
            .map(|st| if st.success() { Ok(()) } else { Err(io::Error::new(
                io::ErrorKind::Other,
                "Command execution failed",
            ))})
    }

    fn clean_up(&self) -> io::Result<()> {
        self.execute_command("rm -rf pipeline-{}").map_err(|_| io::Error::new(
            io::ErrorKind::Other,
            "Failed to clean up working directory",
        ))
    }
}

fn main() {
    let file_management = FileManagement::new();

    // execute commands in the working directory
    file_management.execute_command("ls").unwrap();
}
