using System;
using System.Data;
using System.Data.SqlClient;

public static class SqlParameterizedCommand
{
    public static IDataReader ExecuteCommand(SqlConnection connection, string commandText, List<object> parameters)
    {
        using (var command = new SqlCommand(commandText, connection))
        {
            foreach (var parameter in parameters)
            {
                var parameterName = "param" + parameters.IndexOf(parameter).ToString();
                command.Parameters.AddWithValue(parameterName, parameter);
            }
            return command.ExecuteReader();
        }
    }
}
