    public class MediaAssetManager
    {
        private readonly ITokenService _tokenService;
        private readonly ICloudStorageProvider _cloudStorageProvider;
        private readonly ConcurrentQueue<UploadRequest> _uploadRequests;

        public MediaAssetManager(ITokenService tokenService, ICloudStorageProvider cloudStorageProvider)
        {
            _tokenService = tokenService;
            _cloudStorageProvider = cloudStorageProvider;
            _uploadRequests = new ConcurrentQueue<UploadRequest>();
        }

        public async Task UploadAsync(UploadRequest request)
        {
            await AuthenticateAndRefreshToken();

            if (request.FilePath != null)
            {
                using var fileStream = File.OpenRead(request.FilePath);
                await UploadFileAsync(fileStream, request.FileName);
            }
            else
            {
                await UploadBytesAsync(request.FileBytes, request.FileName);
            }

            await _cloudStorageProvider.UploadAsync(_uploadRequests.Enqueue);
        }

        private async Task AuthenticateAndRefreshToken()
        {
            var token = await _tokenService.GetAccessToken();
            if (string.IsNullOrEmpty(token))
            {
                throw new InvalidOperationException("No valid access token found");
            }
        }

        private async Task UploadFileAsync(Stream fileStream, string fileName)
        {
            // Implement dynamic chunking algorithm
            var fileChunkSize = CalculateChunkSize(fileStream.Length);
            using var memoryStream = new MemoryStream();

            await fileStream.CopyToAsync(memoryStream);

            var uploadTasks = new List<Task>();

            for (int i = 0; i < (memoryStream.Length / fileChunkSize); i++)
            {
                int start = i * fileChunkSize;
                int end = (i + 1) * fileChunkSize;

                if (end > memoryStream.Length)
                {
                    end = memoryStream.Length;
                }

                memoryStream.Position = start;
                var chunk = new MemoryStream();
                await memoryStream.CopyToAsync(chunk);
                chunk.Position = 0;

                uploadTasks.Add(_cloudStorageProvider.UploadChunkAsync(chunk, fileName, start));
            }

            await Task.WhenAll(uploadTasks);
        }

        private async Task UploadBytesAsync(byte[] fileBytes, string fileName)
        {
            // Implement dynamic chunking algorithm
            var fileChunkSize = CalculateChunkSize(fileBytes.Length);
            using var memoryStream = new MemoryStream(fileBytes);

            var uploadTasks = new List<Task>();

            for (int i = 0; i < (memoryStream.Length / fileChunkSize); i++)
            {
                int start = i * fileChunkSize;
                int end = (i + 1) * fileChunkSize;

                if (end > memoryStream.Length)
                {
                    end = memoryStream.Length;
                }

                memoryStream.Position = start;
                var chunk = new MemoryStream();
                await memoryStream.CopyToAsync(chunk);
                chunk.Position = 0;

                uploadTasks.Add(_cloudStorageProvider.UploadChunkAsync(chunk, fileName, start));
            }

            await Task.WhenAll(uploadTasks);
        }

        private int CalculateChunkSize(long fileSize)
        {
