import java.util.*;
import java.util.concurrent.*;

public class TaskScheduler {
    private static final int MAX_CONCURRENT_TASKS = 5;
    private static final int API_RATE_LIMIT = 10; // in seconds

    private final ExecutorService executor;
    private final Map<String, String> cachedResponses;

    public TaskScheduler() {
        this.executor = Executors.newFixedThreadPool(MAX_CONURRENT_TASKS);
        this.cachedResponses = new HashMap<>();
    }

    public void scheduleTasks(List<TaskDescription> tasks) {
        for (TaskDescription task : tasks) {
            if (!isValidTask(task)) {
                System.out.println("Invalid task description: " + task.toString());
                continue;
            }
            try {
                ScheduleTask(task);
            } catch (Exception e) {
                System.out.println("Error scheduling task: " + task.toString() + " - " + e.getMessage());
            }
        }
    }

    private void ScheduleTask(TaskDescription task) throws Exception {
        String apiResponse = getCachedResponse(task.getDescription());
        if (apiResponse != null) {
            // Task already scheduled, reuse cached response
            return;
        }

        Future<String> future = executor.submit(() -> executeTask(task));
        try {
            String result = future.get(API_RATE_LIMIT, TimeUnit.SECONDS); // wait for API rate limit
            cachedResponses.put(task.getDescription(), result);
        } catch (TimeoutException e) {
            System.out.println("API connection timeout: " + task.toString());
        } catch (InterruptedException | ExecutionException e) {
            System.out.println("Failed to execute task: " + task.toString() + " - " + e.getMessage());
        }
    }

    private String executeTask(TaskDescription task) throws Exception {
