#include <iostream>
#include <memory>
#include <vector>

class OctreeSpatialPartitioner {
public:
    OctreeSpatialPartitioner() : root_(nullptr) {}

    void initialize(int maxDepth, int capacityPerNode) {
        if (maxDepth <= 0 || capacityPerNode <= 0) {
            std::cerr << "Invalid input: maxDepth and capacityPerNode must be greater than zero." << std::endl;
            return;
        }

        root_ = std::make_unique<OctreeNode>(nullptr, maxDepth - 1, capacityPerNode);
    }

