private:
    struct OctreeNode {
        int capacity;
        std::unique_ptr<OctreeNode> topLeft_, topRight_, bottomLeft_, bottomRight_;
        float minX_, maxX_, minY_, maxY_, minZ_, maxZ_;

        OctreeNode(OctreeNode* parent, int depth, int capacityPerNode)
            : capacity(capacityPerNode), parent_(parent) {
            if (depth > 0) {
                topLeft_ = std::make_unique<OctreeNode>(this, depth - 1, capacityPerNode);
                topRight_ = std::make_unique<OctreeNode>(this, depth - 1, capacityPerNode);
                bottomLeft_ = std::make_unique<OctreeNode>(this, depth - 1, capacityPerNode);
                bottomRight_ = std::make_unique<OctreeNode>(this, depth - 1, capacityPerNode);
