// JavaScript code
function FindElementsBySelector(node, selector, callback) {
    const result = [];

    function traverse(node, parent) {
        if (!node) return;

        const className = node.className;
        const id = node.id;

        if (callback(node, className, id)) {
            result.push(node);
        }

        const children = Array.from(node.children);

        for (const child of children) {
            traverse(child, node);
        }
    }

    traverse(node, null);

    return result;
}
