```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

// Define the structure to store scraped data
typedef struct {
    char *url;
    char *content;
} ScrapedData;

// Function to handle a single curl request
static size_t write_callback(void *ptr, size_t size, size_t nmemb, void *data) {
    size_t realsize = size * nmemb;
    ScrapedData *scraped_data = (ScrapedData *) data;
    char *content = realloc(scraped_data->content, scraped_data->content ? scraped_data->content_size + realsize : realsize);
    if (!content) {
        // Handle memory allocation failure
        return 0;
    }
    memcpy(content + scraped_data->content_size, ptr, realsize);
    scraped_data->content = content;
    scraped_data->content_size += realsize;
    return realsize;
}

// Function to handle a list of URLs and scrape their contents
void scrape_urls(char **urls, int num_urls) {
    CURL *curl;
    CURLcode res;
    ScrapedData scraped_data;

    // Initialize the thread pool manager
    pthread_t threads[num_urls];
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setstacksize(&attr, 1024*16);

    for (int i = 0; i < num_urls; i++) {
        CURL *curl_copy = curl_easy_init();
        if(curl_copy) {
            // Set the URL to scrape
            curl_easy_setopt(curl_copy, CURLOPT_URL, urls[i]);
            // Set the write callback function
            curl_easy_setopt(curl_copy, CURLOPT_WRITEFUNCTION, &write_callback);
            curl_easy_setopt(curl_copy, CURLOPT_WRITEDATA, (void *) &scraped_data);

            // Start the curl request in a separate thread
            pthread_create(&threads[i], &attr, (void*)start_curl, curl_copy);
        }
    }

    for (int i = 0; i < num_urls; i++) {
        pthread_join(threads[i], NULL);
    }

    // Process the scraped data and store it in a database
    // ...

    return;
}

// Function to start a curl request in a separate thread
void* start_curl(void *data) {
    CURL *curl = (CURL *) data;
    CURLcode res;

    res = curl_easy_perform(curl);

    if(res != CURLE_OK) {
        // Handle error
        printf("cURL error: %s\n", curl_easy_strerror(res));
    }

    return NULL;
}

int main(int argc, char **argv[]) {
    // Parse command-line options and set the number of concurrent downloads
    int num_concurrent_downloads = 5;

    // Define a list of URLs to scrape
    char *urls[] = {"http://example.com/page1", "http://example.com/page2", ...};

    // Scrape the URLs concurrently
    scrape_urls(urls, sizeof(urls) / sizeof(urls[0]));

    return 0;
}
