<?php

class UserAuthentication {

    private $database;
    private $emailServiceApi;

    public function __construct($database, $emailServiceApi) {
        $this->database = $database;
        $this->emailServiceApi = $emailServiceApi;
    }

    public function authenticateUser($username, $password) {
        if (!isset($this->database[$username])) {
            return "Username not found";
        }
        list($storedHash, $salt) = explode('::', $this->database[$username]['password']);
        if (!password_verify("$salt::" . $password, $storedHash)) {
            return "Invalid password or username not found";
        }
        // Implement rate limiting to prevent brute force attacks
        return true;
    }

    public function changeUserPassword($username, $newPassword) {
        if (!isset($this->database[$username])) {
            throw new UserNotFoundException("Username not found");
        }
        list($storedHash, $salt) = explode('::', $this->database[$username]['password']);
        // Implement locking mechanism to handle race conditions
        try {
            // Generate a new salt
            $newSalt = random_bytes(16);
            // Hash the new password using bcrypt algorithm with cost parameter of 12
            $newHash = password_hash("$newSalt::" . $newPassword, PASSWORD_BCRYPT, array('cost' => 12));
            // Update the user's password in the database
            $this->database[$username]['password'] = "$newHash::" . bin2hex($newSalt);
        } catch (Exception $e) {
            throw new UserNotFoundException("Username not found");
        }
    }

    public function forgotPassword($email) {
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            return "Invalid email address";
        }
        if (!isset($this->database[$email])) {
            return "Email address not found";
        }
        // Generate a unique token
        $token = random_bytes(16);
        // Store the token and expiration time in the database
        $this->database[$email]['forgotToken'] = bin2hex($token);
        $expirationTime = strtotime('+1 hour');
        $this->database[$email]['forgotExpirationTime'] = $expirationTime;
        // Send a password reset email to the user using the email service API
        return true;
    }

    public function resetPasswordUsingToken($token, $newPassword) {
        if (!isset($this->database[$token])) {
            return "Invalid token";
        }
        $email = $token;
        list($storedHash, $salt) = explode('::', $this->database[$email]['password']);
        // Validate the token against the one stored in the database
        if (strtotime($this->database[$email]['forgotExpirationTime']) < time()) {
            return "Token has expired";
        }
        try {
            // Generate a new salt
            $newSalt = random_bytes(16);
            // Hash the new password using bcrypt algorithm with cost parameter of 12
            $newHash = password_hash("$newSalt::" . $newPassword, PASSWORD_BCRYPT, array('cost' => 12));
            // Update the user's password in the database
            $this->database[$email]['password'] = "$newHash::" . bin2hex($newSalt);
        } catch (Exception $e) {
            throw new UserNotFoundException("Username not found");
        }
    }

    public function retrieveSalt($username) {
        if (!isset($this->database[$username])) {
            throw new UserNotFoundException("Username not found");
        }
        return $this->database[$username]['salt'];
    }
}
