const require = new Function('require', 'exports');
const blueslip = require('blueslip');
const { parallel, series } = require('blue-tape');

function runTests(moduleLabel, testSuite) {
  async function runTest(label, testFunction) {
    try {
      await testFunction(label);
    } catch (error) {
      console.error(`Error in ${label}:`, error.stack);
    }
  }

  let startTime;
  let endTime;

  async function runModuleTests() {
    startTime = new Date().getTime();

    for (let i = 0; i < testSuite.length; i++) {
      const label = `Test ${i + 1}`;
      console.log(`Running ${label}...`);

      await blueslip.reset();
      await runTest(label, testSuite[i]);
      await blueslip.reset();
    }

    endTime = new Date().getTime();

    if (endTime - startTime > 1000) {
      console.log(`${moduleLabel} tests took ${(endTime - startTime) / 1000} seconds`);
    }
  }

  async function runModuleTestsParallel() {
    let promises = [];

    for (let i = 0; i < testSuite.length; i++) {
      const label = `Test ${i + 1}`;
      console.log(`Running ${label}...`);

      promises.push(blueslip.reset().then(() => runTest(label, testSuite[i]).catch(error => console.error(`Error in ${label}:`, error.stack)).finally(() => blueslip.reset()));
    }

    await Promise.all(promises);
  }

  async function main() {
    if (process.argv[2]) {
      const loggingLevel = process.argv[2].toLowerCase();
      switch (loggingLevel) {
        case 'debug':
          console.log('Running tests in debug mode');
          break;
        case 'verbose':
          console.log('Running tests in verbose mode');
          break;
        default:
          console.log('Running tests in quiet mode');
      }
    }

    await runModuleTests();
  }

  main().then(() => {
    console.log(`${moduleLabel} tests finished`);
  }).catch(error => {
    console.error(`Error running ${moduleLabel} tests:`, error.stack);
  });
}

