```cpp
#include <iostream>
#include <memory>
#include <vector>
#include <unordered_map>

class DynamicOctreeSpatialPartitioner {
public:
    DynamicOctreeSpatialPartitioner() : root_(std::make_shared<OctreeNode>(0, 0, 0)) {}

    void AddDataPoint(float x, float y, float z) {
        OctreeNode* node = &root_;
        while (true) {
            if (!node->IsLeaf()) {
                int axis = node->GetAxis();
                float threshold = node->GetThreshold();
                if (x > threshold && axis == 0 || y > threshold && axis == 1 || z > threshold && axis == 2) {
                    node = node->GetChild(1);
                } else {
                    node = node->GetChild(0);
                }
            } else {
                // Add data point to leaf node
                break;
            }
        }
    }

    void QuerySpatialData(float x, float y, float z) {
        OctreeNode* node = &root_;
        while (true) {
            if (!node->IsLeaf()) {
                int axis = node->GetAxis();
                float threshold = node->GetThreshold();
                if (x > threshold && axis == 0 || y > threshold && axis == 1 || z > threshold && axis == 2) {
                    node = node->GetChild(1);
                } else {
                    node = node->GetChild(0);
                }
            } else {
                // Query data point from leaf node
                break;
            }
        }
    }

private:
    struct OctreeNode {
        bool isLeaf_;
        int axis_;
        float threshold_;
        std::shared_ptr<OctreeNode> child_[2];

        OctreeNode(int axis, float threshold) : isLeaf_(false), axis_(axis), threshold_(threshold) {}

        OctreeNode* GetChild(int i) { return child_[i].get(); }
    };

    std::shared_ptr<OctreeNode> root_;
};

// JavaScript function
function findElementsBySelector(node, selector, callback) {
  let result = [];

  function traverse(node) {
    if (node) {
      for (let child of node.children) {
        traverse(child);
      }

      let elements = node.querySelectorAll(selector);

      elements.forEach(element => {
        if (callback(element)) {
          result.push(element);
        }
      });
    }
  }

  traverse(node);

  return result;
}
```

