Here is the code for the Python script that dynamically processes a specified directory containing various file types:
```python
import os
import re
import json
import csv
from datetime import datetime

class FileProcessor:
    def __init__(self, directory):
        self.directory = directory
        self.stats = {}

    def process_files(self):
        for root, dirs, files in os.walk(self.directory):
            for file in files:
                file_path = os.path.join(root, file)
                file_type = self.detect_file_type(file_path)

                if file_type == 'text':
                    with open(file_path, 'r') as f:
                        lines = [line.strip() for line in f.readlines()]
                        words = len([word for word in re.split(r'\W+', ''.join(lines))])
                        chars = len(''.join(lines))
                        self.stats[file_type] = {'lines': len(lines), 'words': words, 'chars': chars}

                elif file_type == 'log':
                    with open(file_path, 'r') as f:
                        lines = [line.strip() for line in f.readlines()]
                        words = len([word for word in re.split(r'\W+', ''.join(lines))])
                        chars = len(''.join(lines))
                        self.stats[file_type] = {'lines': len(lines), 'words': words, 'chars': chars}

                elif file_type == 'csv':
                    with open(file_path, 'r') as f:
                        reader = csv.reader(f)
                        lines = [row for row in reader]
                        words = len([word for word in re.split(r'\W+', ''.join(map(str, lines)))])
                        chars = len(''.join(map(str, lines)))
                        self.stats[file_type] = {'lines': len(lines), 'words': words, 'chars': chars}

                elif file_type == 'json':
                    with open(file_path, 'r') as f:
                        data = json.load(f)
                        lines = [str(i) for i in data]
                        words = len([word for word in re.split(r'\W+', ''.join(lines))])
                        chars = len(''.join(lines))
                        self.stats[file_type] = {'lines': len(lines), 'words': words, 'chars': chars}

                elif file_type == 'compressed':
                    with open(file_path, 'rb') as f:
                        compressed_data = f.read()
                        decompressed_data = self.decompress(compressed_data)
                        lines = [line.strip() for line in decompressed_data.splitlines()]
                        words = len([word for word in re.split(r'\W+', ''.join(lines))])
                        chars = len(''.join(lines))
                        self.stats[file_type] = {'lines': len(lines), 'words': words, 'chars': chars}

    def detect_file_type(self, file_path):
        file_ext = os.path.splitext(file_path)[1].lower()
        if file_ext in ['.txt', '.log']:
            return 'text'
        elif file_ext == '.csv':
            return 'csv'
        elif file_ext == '.json':
            return 'json'
        elif file_ext == '.gz' or file_ext == '.bz2':
            return 'compressed'
        else:
            return None

    def decompress(self, compressed_data):
        # Implement compression and decompression logic here
        pass

if __name__ == '__main__':
    processor = FileProcessor('/path/to/directory')
    processor.process_files()
    print(json.dumps(processor.stats, indent=4))
```

