        $storedHash = $this->userDatabase[$username]['hash'];
        $salt = $this->userDatabase[$username]['salt'];

        $rateLimit = &$this->rateLimitCache[$username];
        if (!isset($rateLimit['attempts']) || !isset($rateLimit['lastAttempt'])) {
            $rateLimit = ['attempts' => 0, 'lastAttempt' => time()];
        }
        if ($rateLimit['attempts'] >= 3) {
            if (time() - $rateLimit['lastAttempt'] < 300) {
                throw new RateLimitExceededException("Too many attempts");
            } else {
                $rateLimit = ['attempts' => 0, 'lastAttempt' => time()];
            }
        }

        if (!password_verify($password, $storedHash)) {
            $rateLimit['attempts']++;
            return "Incorrect username and/or password";
        }
        return true;
    }

    public function changeUserPassword($username, $newPassword) {
        $user = &$this->userDatabase[$username];
        if (!isset($user['hash']) || !isset($user['salt'])) {
            throw new UserNotFoundException("Username not found");
        }

        $storedHash = $user['hash'];
        $salt = $user['salt'];

        $newSalt = sodium_base64_encode(random_bytes(16));
        $newHash = password_hash($newPassword, PASSWORD_BCRYPT, ['cost' => 12]);

        do {
            try {
                $this->userDatabase[$username] = ['hash' => $newHash, 'salt' => $newSalt];
                return true;
            } catch (LockedException $e) {
                usleep(100000);
            }
        } while (true);
    }

    public function forgotPassword($email) {
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            throw new InvalidArgumentException("Invalid email format");
        }

        if (!isset($this->userDatabase[$email])) {
            return "Email not found";
        }

        $token = sodium_base64_encode(random_bytes(16));
        do {
            try {
                $this->userDatabase[$email]['forgotToken'] = ['token' => $token, 'expirationTime' => time() + 3600];
                return true;
            } catch (LockedException $e) {
                usleep(100000);
            }
        } while (true);

        mail($email, "Forgot Password", "A password reset email");
    }

    public function resetPasswordUsingToken($token, $newPassword) {
        if (!isset($this->userDatabase[$email]['forgotToken'])) {
            throw new UserNotFoundException("Email not found");
        }
        $storedToken = $this->userDatabase[$email]['forgotToken']['token'];
        $expirationTime = $this->userDatabase[$email]['forgotToken']['expirationTime'];

        if ($storedToken !== $token || time() > $expirationTime) {
            throw new TokenExpiredException("Invalid or expired token");
        }

        if (isset($this->userDatabase[$email]['forgotToken'])) {
            unset($this->userDatabase[$email]['forgotToken']);
        }

        do {
            try {
                $this->userDatabase[$username] = ['hash' => password_hash($newPassword, PASSWORD_BCRYPT, ['cost' => 12]), 'salt' => sodium_base64_encode(random_bytes(16))];
                return true;
            } catch (LockedException $e) {
                usleep(100000);
            }
        } while (true);

        mail($email, "Password Reset", "A password reset email");
    }

    public function retrieveSalt($username) {
        if (!isset($this->userDatabase[$username])) {
            throw new UserNotFoundException("Username not found");
        }
        return $this->userDatabase[$username]['salt'];
    }
}
