    // If there's an error, return NULL

    StateList *state_list = malloc(sizeof(StateList));
    if (!state_list) {
        printf("Error: Insufficient memory.\n");
        return NULL;
    }

    // Initialize the first state of the list
    state_list->next = NULL;

    // Perform cryptographic operation using OpenSSL library
    SSL_CTX *ctx = SSL_CTX_new(TLS_client_method());
    SSL *ssl = SSL_new(ctx);

    // Handle potential errors while performing cryptographic operation
    if (!ssl) {
        printf("Error: Unable to create SSL object.\n");
        SSL_CTX_free(ctx);
        free(state_list);
        return NULL;
    }

    // Cache the computed state list for future reference
    // and ensure efficient handling of large state lists

    // Clean up resources before returning the cipher object
    SSL_free(ssl);
    SSL_CTX_free(ctx);

    return state_list;
}
