```
const { Buffer } = require('buffer');
const db = require('db-connection');

function mergeData(chunks, byteCount) {
  if (!chunks.length || !byteCount) return new Buffer(0);

  const buffer = new Buffer(byteCount);
  let bytesRead = 0;
  let i = 0;

  while (bytesRead < byteCount) {
    const chunk = chunks[i];

    if (!chunk || chunk.length > (byteCount - bytesRead)) {
      throw new Error('Invalid chunk size');
    }

    let start = 0;
    let end = Math.min(chunk.length, byteCount - bytesRead);

    while (start < end) {
      const srcOffset = start;
      const dstOffset = bytesRead + start;
      const length = end - start;

      try {
        buffer.copy(chunk, srcOffset, dstOffset, srcOffset + length);
      } catch (e) {
        // Log error and return empty buffer
        db.logError(e, `MergeData failed to copy chunk ${i}`);
        return new Buffer(0);
      }

      bytesRead += length;
    }

    i++;
  }

  try {
    db.logInfo(`Merged data successfully: ${byteCount} bytes`);
  } catch (e) {
    // Log error and return empty buffer
    db.logError(e, `MergeData failed to log info: ${byteCount} bytes`);
    return new Buffer(0);
  }

  return buffer;
}
