<?php

function updateClinicStatus($clinicId, $newStatus, $lastModifiedIp, $reasonForUpdate) {
    require_once 'DbConfig.php';
    require_once 'Logger.php';

    // Validate clinic ID before proceeding with update
    if (!filter_var($clinicId, FILTER_VALIDATE_INT)) {
        throw new Exception('Invalid clinic ID');
    }

    try {
        // Start transaction to ensure data integrity
        $dbConn = new PDO('mysql:host=' . DB_HOST . ';dbname=' . DB_NAME, DB_USER, DB_PASSWORD);
        $dbConn->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        $dbConn->beginTransaction();

        // Detect and prevent bulk updates from a single source IP within a short time frame
        $lastModifiedIpQuery = "SELECT * FROM clinic_status_updates WHERE last_modified_ip = :ip AND timestamp >= DATE_SUB(NOW(), INTERVAL 1 MINUTE)";
        $bulkUpdateDetectionStmt = $dbConn->prepare($lastModifiedIpQuery);
        $bulkUpdateDetectionStmt->execute([':ip' => $lastModifiedIp]);
        if ($bulkUpdateDetectionStmt->rowCount() > 0) {
            throw new Exception('Bulk update detected from the same IP address within the last minute');
        }

        // Update clinic status in a single transaction
        $updateQuery = "UPDATE clinics SET status = :newStatus, last_modified_ip = :lastModifiedIp, last_modified_timestamp = NOW() WHERE id = :clinicId";
        $updateStmt = $dbConn->prepare($updateQuery);
        $updateStmt->execute([':newStatus' => $newStatus, ':lastModifiedIp' => $lastModifiedIp, ':clinicId' => $clinicId]);

        // Log update details
        $logger = new Logger();
        $logger->logUpdateDetails($clinicId, $newStatus, $reasonForUpdate);

        // Commit transaction
        $dbConn->commit();

    } catch (Exception $e) {
        // Rollback and log the error
        $dbConn->rollBack();
        $logger->logError($e);
        throw $e;
    } finally {
        // Close database connection
        $dbConn = null;
    }
}

