import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.AsynchronousSocketChannel;
import java.nio.channels.CompletionHandler;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.logging.Level;
import java.util.logging.Logger;

public class SecureConnectionPool {
    private static final Logger LOGGER = Logger.getLogger(SecureConnectionPool.class.getName());
    private static final int CONNECTION_POOL_SIZE = 10;
    private static final int TIMEOUT_MILLISECONDS = 10000;
    private static final String FILENAME_EXTENSION = "%d_%s";

    private AsynchronousSocketChannel[] connections;
    private ExecutorService executorService;

    public SecureConnectionPool() {
        this.connections = new AsynchronousSocketChannel[CONNECTION_POOL_SIZE];
        this.executorService = Executors.newFixedThreadPool(CONNECTION_POOL_SIZE);
    }

    public void establishSecureConnection(String hostname, int port) throws IOException, InterruptedException {
        for (int i = 0; i < CONNECTION_POOL_SIZE; i++) {
            final int index = i;
            connections[index] = AsynchronousSocketChannel.open(new InetSocketAddress(hostname, port));
            connections[index].setOption(AsynchronousSocketChannel.Option.SO_KEEPALIVE, true);
            connections[index].setOption(AsynchronousSocketChannel.Option.TCP_NODELAY, true);

            connections[index].connect(new InetSocketAddress(hostname, port), TIMEOUT_MILLISECONDS, new CompletionHandler() {
                @Override
                public void completed(AsynchronousSocketChannel channel, Object attachment) {
                    LOGGER.info("Connection to " + hostname + " established successfully.");
                }

                @Override
                public void failed(Throwable exc, Object attachment) {
                    LOGGER.severe("Failed to establish connection to " + hostname + ": " + exc.getMessage());
                }
            });
        }
    }

    public String modifyFilenameExtension(String filename) {
        StringBuilder modifiedFilename = new StringBuilder();
        for (int i = 0; i < filename.length(); i++) {
            char c = filename.charAt(i);
            if (Character.isDigit(c)) {
                modifiedFilename.append("%d");
            } else {
                modifiedFilename.append(c);
            }
        }
        return String.format(FILENAME_EXTENSION, Integer.parseInt(filename), "txt");
    }

    public static void main(String[] args) throws IOException, InterruptedException {
        SecureConnectionPool connectionPool = new SecureConnectionPool();
        connectionPool.establishSecureConnection("example.com", 443);

        // Modify filename extension
        String originalFilename = "testfile";
        String modifiedFilename = connectionPool.modifyFilenameExtension(originalFilename);
        System.out.println(modifiedFilename);
    }
}
