```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

// Function to fetch latest validation rules from remote configuration server
int fetchValidationRules(json_object *rules) {
    // TO DO: Implement the logic to fetch rules from a remote configuration server
    return 0;
}

// Function to validate OAuth2 access token response
int validateAccessToken(const char *jsonString, json_object **tokenInfo) {
    json_object *tokenObj = json_object_from_string(jsonString);
    if (!tokenObj) {
        printf("Error parsing JSON.\n");
        return -1;
    }

    if (json_object_object_get(tokenObj, "access_token") == NULL) {
        printf("Access token not found.\n");
        json_object_put(tokenObj);
        return -1;
    }

    char *accessToken = json_object_get_string(json_object_object_get(tokenObj, "access_token"));
    if (strlen(accessToken) == 0) {
        printf("Invalid access token.\n");
        json_object_put(tokenObj);
        return -1;
    }

    if (json_object_object_get(tokenObj, "token_type") == NULL) {
        printf("Token type not found.\n");
        json_object_put(tokenObj);
        return -1;
    }

    const char *tokenType = json_object_get_string(json_object_object_get(tokenObj, "token_type"));
    if (strcmp(tokenType, "Bearer") != 0) {
        printf("Invalid token type.\n");
        json_object_put(tokenObj);
        return -1;
    }

    if (json_object_object_get(tokenObj, "expires_in") == NULL) {
        printf("Expires in not found.\n");
        json_object_put(tokenObj);
        return -1;
    }

    int expiresIn = json_object_get_int(json_object_object_get(tokenObj, "expires_in"));
    if (expiresIn <= 0) {
        printf("Invalid expires in value.\n");
        json_object_put(tokenObj);
        return -1;
    }

    if (json_object_object_get(tokenObj, "refresh_token") != NULL) {
        char *refreshToken = json_object_get_string(json_object_object_get(tokenObj, "refresh_token"));
        if (strlen(refreshToken) == 0) {
            printf("Invalid refresh token.\n");
            json_object_put(tokenObj);
            return -1;
        }
    }

    // Fetch latest validation rules from remote configuration server
    fetchValidationRules(tokenObj);

    *tokenInfo = tokenObj;
    return 0;
}
