import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.atomic.AtomicInteger;

public class SecureConnectionPool {

    private final int connectionTimeout;
    private final long idleTimeout;
    private final List<SocketChannel> connections = new CopyOnWriteArrayList<>();
    private final AtomicInteger activeConnections = new AtomicInteger(0);
    private final Selector selector;

    public SecureConnectionPool(int connectionTimeout, long idleTimeout) {
        this.connectionTimeout = connectionTimeout;
        this.idleTimeout = idleTimeout;
        try {
            this.selector = Selector.open();
        } catch (IOException e) {
            throw new RuntimeException("Failed to open selector", e);
        }
    }

    public void start() throws IOException {
        ServerSocketChannel serverSocketChannel = ServerSocketChannel.open();
        serverSocketChannel.configureBlocking(false);
        serverSocketChannel.bind(new InetSocketAddress(0));
        SelectionKey acceptKey = serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);
        new AcceptThread().start();

        // implement health check mechanism here
    }

    private class AcceptThread extends Thread {

        @Override
        public void run() {
            try (ServerSocketChannel serverSocketChannel = SecureConnectionPool.this.serverSocketChannel) {
                while (!interrupted()) {
                    SocketChannel socketChannel = serverSocketChannel.accept();
                    socketChannel.configureBlocking(false);
                    SelectionKey key = socketChannel.register(selector, SelectionKey.OP_READ);
                    connections.add(socketChannel);
                    activeConnections.incrementAndGet();

                    new ReadThread(socketChannel).start();
                }
            } catch (IOException e) {
                throw new RuntimeException("Failed to accept connection", e);
            }
        }
    }

    private class ReadThread extends Thread {

        private final SocketChannel socketChannel;

        public ReadThread(SocketChannel socketChannel) {
            this.socketChannel = socketChannel;
        }

        @Override
        public void run() {
            try (socketChannel) {
                while (!interrupted()) {
                    // handle read operations here
                    if (socketChannel.ready()) {
                        // process incoming data
                    } else {
                        break; // connection idle
                    }
                }
                // implement connection reclamation strategy here
            } catch (IOException e) {
                throw new RuntimeException("Failed to read from connection", e);
            }
        }
    }

    public void close() {
        try {
            connections.forEach(channel -> channel.close());
            selector.wakeup();
        } catch (IOException e) {
            throw new RuntimeException("Failed to close connections", e);
        }
    }
}

