#include <iostream>
#include <fstream>
#include <filesystem>
#include <algorithm>
#include <numeric>
#include <thread>
#include "Logger.h"

int main(int argc, char* argv[]) {
    if (argc != 4) {
        std::cerr << "Usage: " << argv[0] << " <input_dir> <output_file> <log_level>\n";
        return 1;
    }

    std::string inputDir = argv[1];
    std::string outputFile = argv[2];
    int logLevel = atoi(argv[3]);

    Logger logger(logLevel);

    uint64_t totalSum = 0;
    size_t fileCount = 0;

    for (const auto& entry : std::filesystem::directory_iterator(inputDir)) {
        if (!entry.is_directory()) {
            continue;
        }

        std::string filePath = entry.path().filename().string();
        logger.log("Processing file " + filePath);

        int64_t largestInt = -2147483648;
        size_t fileSize = 0;

        try {
            std::ifstream file(entry.path());
            if (!file) {
                logger.log("Error opening file " + filePath);
                continue;
            }

            int64_t sum = 0;
            while (true) {
                int val;
                file >> val;
                if (file.fail()) {
                    break; // End of file
                }
                sum += val;
                largestInt = std::max(largestInt, val);
                fileSize++;
            }

            totalSum += sum;
            fileCount++;
        } catch (...) {
            logger.log("Error processing file " + filePath);
            continue;
        }

        logger.log("File " + filePath + " processed. Largest integer: " + std::to_string(largestInt) + ". File size: " + std::to_string(fileSize));
    }

    if (fileCount == 0) {
        logger.log("No files found in directory.");
    } else {
        int64_t average = totalSum / fileCount;
        logger.log("Average integer: " + std::to_string(average));

        std::ofstream outputFileStream(outputFile);
        if (!outputFileStream) {
            logger.log("Error opening output file");
        } else {
            outputFileStream << "Largest integer: " << largestInt << "\n";
            outputFileStream << "Average integer: " << average;
        }
    }

    return 0;
}
