// External attack database interface (simplified for demonstration purposes)
class AttackDatabase {
public:
    std::vector<std::pair<int, int>> getAttacks();
};

// Function to select an attack with cooldown
void selectAttack(AttackDatabase& db, int characterType) {
    // Load cooldown period from configuration or character type
    auto cooldownPeriod = std::chrono::milliseconds(9000); // Default 9 seconds

    // Initialize random number generator
    static std::random_device rd;
    static std::mt19937 gen(rd());
    static std::uniform_int_distribution<> dis(0, db.getAttacks().size() - 1);

    while (true) {
        // Fetch attack details from database with retries for network latency and failures
        int attempt = 0;
        while (attempt++ < 3) {
            try {
                auto attacks = db.getAttacks();
                if (!attacks.empty()) {
                    // Select an attack based on cooldown period
                    auto now = std::chrono::high_resolution_clock::now();
                    for (const auto& attack : attacks) {
                        if ((now - std::chrono::milliseconds(attack.second)).count() >= cooldownPeriod.count()) {
                            // Log selected attack and reset cooldown timer
                            std::cout << "Selected attack: " << attack.first << std::endl;
                            db.resetCooldownTimer();
                            return;
                        }
                    }
                } else {
                    // Handle database error (e.g., no attacks found)
                    std::cerr << "Error: No attacks available." << std::endl;
                    break;
                }
            } catch (const std::exception& e) {
                // Log and retry for network latency or other errors
                std::cerr << "Error: " << e.what() << std::endl;
                if (attempt < 3) {
                    std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Wait before retrying
                } else {
                    break; // Exit after maximum retries
                }
            }
        }

        // Log and reset cooldown timer after maximum retries or no attacks found
        if (attempt >= 3) {
            std::cout << "No attack selected due to cooldown period." << std::endl;
            db.resetCooldownTimer();
        }
    }
}
