    env_logger::init();
    info!("Starting server...");

    let config = read_config().await?;
    info!("Config loaded: {config:?}");

    HttpServer::new(|| App::new().service(web::resource("/health")
        .route(web::get().to(health_check))))
        .bind("127.0.0.1:8000")?
        .run()
        .await
        .unwrap();
}

async fn health_check() -> HttpResponse {
    let mut response = "Healthy";
    for (name, status) in config.services.iter() {
        if !status {
            response += &format!(", Service '{}': Unhealthy", name);
        }
    }
    HttpResponse::Ok().body(response)
}

async fn read_config() -> Result<String, Box<dyn std::error::Error>> {
    let file = File::open("config.json").await?;
    let mut config_str = String::new();
    file.read_to_string(&mut config_str).await?;
    Ok(config_str)
