function renderFooterScripts(scripts) {
  const cache = {};
  const loadingSpinner = document.getElementById('loading-spinner');

  function fetchScript(script) {
    return fetch('/api/scripts')
      .then(response => response.json())
      .catch(error => console.error('Error fetching script:', error));
  }

  function renderScript(script, index) {
    const scriptElement = document.createElement('script');
    scriptElement.src = script.src || '';
    scriptElement.type = script.type || 'text/javascript';
    scriptElement.textContent = script.code;

    if (!cache[index]) {
      loadingSpinner.style.display = 'block';
    }

    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        if (script.src) {
          fetchScript(script)
            .then(data => {
              scriptElement.textContent = data.script;
              resolve();
            })
            .catch(error => {
              console.error('Error fetching script:', error);
              reject();
            });
        } else {
          resolve();
        }
      }, 1000);
    }).then(() => {
      loadingSpinner.style.display = 'none';
      document.body.appendChild(scriptElement);
    });
  }

  function renderScripts(scripts) {
    return Promise.all(scripts.map((script, index) => renderScript(script, index)))
      .catch(error => console.error('Error rendering scripts:', error));
  }

  async function main() {
    loadingSpinner.style.display = 'block';

    try {
      await renderScripts(scripts);
    } catch (error) {
      console.error('Error rendering footer scripts:', error);
    } finally {
      loadingSpinner.style.display = 'none';
    }
  }

  main();
}
