namespace MersenneTwisterRandomNumberGenerator
{
    public class RandomNumberGenerator
    {
        private static MT19937 _random;

        public RandomNumberGenerator()
        {
            _random = new MT19937();
        }

        ~RandomNumberGenerator()
        {
            Dispose(false);
        }

        public void Dispose(bool disposing)
        {
            if (!disposing) return;
            _random.Dispose();
        }
    }

    class Program
    {
        [STAThread]
        static async Task Main(string[] args)
        {
            RandomNumberGenerator rng = new RandomNumberGenerator();

            try
            {
                foreach (string file in args)
                {
                    if (!File.Exists(file))
                        continue;

                    int maxInt = 0;
                    long sum = 0;
                    int count = 0;

                    using (StreamReader reader = File.OpenText(file))
                    {
                        string line;
                        while ((line = await reader.ReadLineAsync()) != null)
                        {
                            try
                            {
                                int num = int.Parse(line);
                                if (num > maxInt) maxInt = num;
                                sum += num;
                                count++;
                            }
                            catch
                            {
                                continue;
                            }
                        }
                    }

                    Console.WriteLine($"File {file} processed. Max integer: {maxInt}, Average: {(double)sum / count}");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error processing files:");
                Console.WriteLine(ex.Message);
            }
        }
    }
}
