#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>

typedef enum {
    RESOURCE_TYPE_TEXT,
    RESOURCE_TYPE_IMAGE,
    RESOURCE_TYPE_AUDIO,
} resource_type;

typedef struct {
    resource_type type;
    int count;
} resource_info;

resource_info* loadResourceBundle(const char* filePath) {
    // Open the file
    FILE* file = fopen(filePath, "r");
    if (file == NULL) {
        return NULL; // Handle error
    }

    // Initialize the resource bundle
    resource_info* resources = NULL;
    int resourceCount = 0;

    // Parse the file and count the number of resources
    while (fscanf(file, "%s\n", &resourceInfoStr) == 1) {
        resource_type type;
        int count;

        // Determine the resource type based on the filename extension
        if (strchr(resourceInfoStr, '.') && !strcmp(strrchr(resourceInfoStr, '.'), ".txt")) {
            type = RESOURCE_TYPE_TEXT;
        } else if (!strcmp(strrchr(resourceInfoStr, '.'), ".jpg" || .jpeg)) {
            type = RESOURCE_TYPE_IMAGE;
        } else if (strchr(resourceInfoStr, '.') && !strcmp(strrchr(resourceInfoStr, '.'), ".wav" || .mp3)) {
            type = RESOURCE_TYPE_AUDIO;
        } else {
            // Handle unknown resource type
            fclose(file);
            return NULL; // Handle error
        }

        count = atoi(resourceInfoStr);

        if (resources == NULL) {
            resources = (resource_info*)malloc(sizeof(resource_info));
            resourceCount = 1;
        } else {
            resources = realloc(resources, sizeof(resource_info) * (resourceCount + 1));
            resourceCount++;
        }

        resources[resourceCount - 1].type = type;
        resources[resourceCount - 1].count = count;
    }

    // Close the file
    fclose(file);

    return resources;
}

