import json
import os
from threading import Thread
from concurrent.futures import ThreadPoolExecutor

class JSONManager:
    def __init__(self):
        self.registry = {}
        self.instances = []

    def add_factory(self, id, factory):
        self.registry[id] = factory

    def create_instance(self, id):
        if id in self.registry:
            return self.registry[id]()
        else:
            raise ValueError("Factory function not found")

    def deserialize_byte_array(self, byte_array):
        object_file = tempfile.NamedTemporaryFile(mode='wb', delete=False)
        object_file.write(byte_array)
        object_file.close()

        try:
            with open(object_file.name, 'r') as f:
                obj = json.load(f)
        except Exception as e:
            logging.error("Error deserializing byte array: %s", str(e))
            return None

        os.remove(object_file.name)
        return obj

    def hash_password(self, password):
        hashed_password = hashlib.sha256(password.encode()).hexdigest()
        random_string = secrets.token_hex(16)
        return hashed_password, random_string

    def load_files(self, file_paths):
        threads = []
        with ThreadPoolExecutor(max_workers=5) as executor:
            for file_path in file_paths:
                thread = executor.submit(self.load_file, file_path)
                threads.append(thread)

            for thread in threads:
                try:
                    thread.result()
                except Exception as e:
                    logging.error("Error loading file: %s", str(e))

    def load_file(self, file_path):
        with open(file_path, 'r') as f:
            data = json.load(f)
        # Handle circular dependencies here
        self.instances.append(data)

    def insert_in_forward_list(self, forward_list, target_string, insertion_string, position_index=0):
        try:
            if not isinstance(forward_list, list) or not all(isinstance(item, str) for item in forward_list):
                raise ValueError("Invalid forward list")

            index = 0
            while index < len(forward_list):
                if forward_list[index] == target_string:
                    break
                index += 1

            if position_index >= len(forward_list):
                forward_list.append(insertion_string)
            elif index < len(forward_list) and forward_list[index] == target_string:
                forward_list.insert(index + 1, insertion_string)
            else:
                forward_list.append(insertion_string)

        except Exception as e:
            logging.error("Error inserting in forward list: %s", str(e))

    def read_insertions(self, file_path):
        try:
            with open(file_path, 'r') as f:
                insertions = json.load(f)
                for insertion in insertions:
                    self.insert_in_forward_list(insertion['forwardList'], insertion['targetString'], insertion['insertionString'], position_index=insertion.get('positionIndex', 0))
        except Exception as e:
            logging.error("Error reading insertions: %s", str(e))

