int run_command(std::string command) {
    pid_t child_pid = fork();

    if (child_pid == 0) {
        // Child process
        execl("/bin/sh", "sh", "-c", command.c_str(), NULL);
        return 1;
    } else {
        // Parent process
        wait(NULL);
        return 0;
    }
}

int main() {
    std::string command = "echo 'Hello, World!'";
    int status = run_command(command);
