import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;

public class RandomStringGenerator {

    private static final Map<String, List<Character>> CHAR_SETS = new ConcurrentHashMap<>();
    private static final int BUFFER_SIZE = 1024;

    public static String generateRandomString(byte[] data, int length) throws Exception {
        try (ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(data);
             ObjectInputStream objectInputStream = new ObjectInputStream(byteArrayInputStream)) {

            // Deserialize the object
            Object deserializedObject = objectInputStream.readObject();

            // Get the character set for random string generation
            List<Character> charSet = getCharacterSet(deserializedObject.getClass().getName());

            // Generate a random string using the deserialized object and character set
            StringBuilder randomStringBuilder = new StringBuilder();
            Random random = new Random();
            for (int i = 0; i < length; i++) {
                randomStringBuilder.append(charSet.get(random.nextInt(charSet.size())));
            }

            return randomStringBuilder.toString();

        } catch (Exception e) {
            throw new Exception("Error generating random string: " + e.getMessage());
        }
    }

    public static String hashPassword(String password, int iterations) throws Exception {
        try (ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
             MessageDigest messageDigest = MessageDigest.getInstance("SHA-256")) {

            // Hash the password
            byte[] bytes = password.getBytes(StandardCharsets.UTF_8);
            for (int i = 0; i < iterations; i++) {
                bytes = messageDigest.digest(bytes);
            }

            return Base64.getEncoder().encodeToString(bytes);

        } catch (Exception e) {
            throw new Exception("Error hashing password: " + e.getMessage());
        }
    }

    private static List<Character> getCharacterSet(String className) throws Exception {
        // Check if the character set is cached
        if (CHAR_SETS.containsKey(className)) {
            return CHAR_SETS.get(className);
        }

        try (ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(
                loadClassBytesFromExternalDataSource(className))) {

            // Load the character set from the external data source
            Object object = new ObjectInputStream(byteArrayInputStream).readObject();
            List<Character> charSet = (List<Character>) object;

            // Cache the character set
            CHAR_SETS.put(className, charSet);

            return charSet;

        } catch (Exception e) {
            throw new Exception("Error loading character set: " + e.getMessage());
        }
    }

