#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LENGTH 255
#define MAX_DIGITS 4
#define ALLOWED_FILE_TYPES "txt|csv|pdf|png"

typedef struct {
    char *types;
    int def_digits;
} Config;

Config load_config();
void validate_filename(const char *filename);
char *modify_extension(const char *filename, int digits, const char *file_type);
char *add_prefix_suffix(char *filename, const char *prefix, const char *suffix);

int main(int argc, char **argv) {
    // Load configuration
    Config config = load_config();

    // Process files
    for (int i = 1; i < argc; i++) {
        const char *filename = argv[i];
        validate_filename(filename);

        int digits;
        if (config.def_digits > 0) {
            digits = config.def_digits;
        } else {
            // Determine number of digits based on filename
            int num_digits = 0;
            for (int j = strlen(filename) - 1; j >= 0; j--) {
                if (!strchr(ALLOWED_FILE_TYPES, filename[j])) {
                    break;
                }
                num_digits++;
            }
            digits = MIN(num_digits, MAX_DIGITS);
        }

        const char *file_type;
        // Determine file type based on configuration
        for (char *type = strtok(config.types, "|"); type; type = strtok(NULL, "|")) {
            if (strchr(type, filename[strlen(filename) - 1])) {
                file_type = type;
                break;
            }
        }

        char *new_filename = modify_extension(filename, digits, file_type);
        if (new_filename == NULL) {
            printf("Error: New filename exceeds maximum length or contains invalid characters.\n");
            continue;
        }

        // Add prefix/suffix
        char *prefix = NULL, *suffix = NULL;
        for (int j = 1; j < argc - i; j++) {
            const char *arg = argv[j + i];
            if (strcmp(arg, "--prefix") == 0) {
                prefix = argv[j + i + 1];
            } else if (strcmp(arg, "--suffix") == 0) {
                suffix = argv[j + i + 1];
            }
        }

        new_filename = add_prefix_suffix(new_filename, prefix, suffix);

        printf("Modified filename: %s\n", new_filename);
    }

    return 0;
}

Config load_config() {
    // Load configuration from file
    // ...
    Config config;
    config.types = ALLOWED_FILE_TYPES;
    config.def_digits = 1; // Default number of digits
    return config;
}

void validate_filename(const char *filename) {
    if (strlen(filename) > MAX_LENGTH || strchr(filename, '\0') == NULL) {
        printf("Error: Invalid filename.\n");
        exit(EXIT_FAILURE);
    }
}

char *modify_extension(const char *filename, int digits, const char *file_type) {
    // Determine last dot position
    int pos = -1;
    for (int i = strlen(filename) - 1; i >= 0; i--) {
        if (filename[i] == '.') {
            pos = i;
            break;
        }
    }

    if (pos < 0) {
        return NULL; // No extension
    }

    char *new_filename = malloc((strlen(filename) + digits + strlen(file_type) + 1) * sizeof(char));
    if (new_filename == NULL) {
        printf("Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    sprintf(new_filename, "%.*s%d.%s", pos, filename, digits, file_type);

    return new_filename;
}

char *add_prefix_suffix(char *filename, const char *prefix, const char *suffix) {
    // Check for invalid characters
    if (strchr(prefix, '.') || strchr(suffix, '.')) {
        printf("Error: Invalid prefix/suffix.\n");
        exit(EXIT_FAILURE);
    }

    int len = strlen(filename);
    char *new_filename = malloc((len + strlen(prefix) + strlen(suffix) + 1) * sizeof(char));
    if (new_filename == NULL) {
        printf("Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    sprintf(new_filename, "%s%s%s", prefix, filename, suffix);

    return new_filename;
}
