public class DynamicResourcePoolManager {
    private static final int DEFAULT_MIN_CONNECTIONS = 1;
    private static final int DEFAULT_MAX_CONNECTIONS = 10;
    private static final long DEFAULT_TIMEOUT = 30000L; // 30 seconds

    public void initializeResourcePool(int minConnections, int maxConnections, long timeout, ConnectionConfigCallback callback) {
        if (minConnections < 0 || maxConnections < minConnections || timeout <= 0) {
            throw new InvalidInputException("Invalid initialization parameters");
        }

        ConnectionConfig config = new ConnectionConfig();
        // Configure the connection pool based on input parameters and callback
        config.setMinConnections(minConnections);
        config.setMaxConnections(maxConnections);
        config.setTimeout(timeout);

        if (callback != null) {
            config = callback.onConfigure(config);
        }

        // Initialize the resource pool with the configured settings
        // ...
    }

    public void initializeResourcePool(int seed, int minConnections, int maxConnections, long timeout, ConnectionConfigCallback callback) {
        AtomicInteger atomicSeed = new AtomicInteger(seed);
        initializeResourcePool(atomicSeed.getAndIncrement(), minConnections, maxConnections, timeout, callback);
    }

    public interface ConnectionConfigCallback {
        ConnectionConfig onConfigure(ConnectionConfig config);
    }

    public class InvalidInputException extends Exception {
        public InvalidInputException(String message) {
            super(message);
        }
    }
}

public interface ConnectionHealthChecker {
    boolean isHealthy(Connection conn);
}
