import mysql.connector
from psycopg2 import Error, connect as ps_connect
from sqlite3 import connect as sqlite_connect
import graphql

class DatabaseConnector:
    def __init__(self, config):
        self.config = config
        if self.config['type'] == 'mysql':
            self.conn = mysql.connector.connect(**config)
        elif self.config['type'] == 'postgresql':
            self.conn = ps_connect(**config)
        elif self.config['type'] == 'sqlite':
            self.conn = sqlite_connect(**config)

    def execute_query(self, query):
        cursor = self.conn.cursor()
        try:
            cursor.execute(query)
            return cursor.fetchall()
        except Exception as e:
            print(f"Error executing query: {e}")
            return None

    def execute_transaction(self, queries):
        cursor = self.conn.cursor()
        try:
            for query in queries:
                cursor.execute(query)
            self.conn.commit()
            return True
        except Exception as e:
            print(f"Error executing transaction: {e}")
            self.conn.rollback()
            return False

    def close_connection(self):
        if hasattr(self, 'conn'):
            self.conn.close()

class GraphQLResolver:
    def __init__(self, database_connector):
        self.database_connector = database_connector
        self.schema = {
            'profile_update': {'type': 'object', 'properties': {'name': {'type': 'string'}, 'email': {'type': 'string'}}},
            'profile_delete': {'type': 'object'}
        }

    def update_profile(self, parent, info, user_id, data):
        if not self.schema['profile_update'].match(data):
            return {"errors": ["Invalid input"]}

        query = f"UPDATE users SET name='{data['name']}', email='{data['email']}' WHERE id={user_id}"
        result = self.database_connector.execute_query(query)
        return {"updated_profile": result[0]} if result else None

    def delete_profile(self, parent, info, user_id):
        query = f"DELETE FROM users WHERE id={user_id}"
        result = self.database_connector.execute_query(query)
        return {"success": True} if result else None
