#include <forward_list>
#include <shared_ptr>

void insertLogEntry(std::forward_list<std::shared_ptr<LogEntry>>& logList,
                    const std::string& logLevel, const std::string& message,
                    int attempts = 1) {
    bool found = false;
    auto current = logList.begin();
    while (current != logList.end()) {
        if ((*current)->getLogLevel() == logLevel) {
            found = true;
            break;
        }
        ++current;
    }

    if (!found) {
        // Insert at the end of the list
        logList.insert_after(current, std::make_shared<LogEntry>(message));
    } else {
        while (attempts--) {
            try {
                // Send the log entry to the API and process the response
                sendLogToApi(*current);
                break;
            } catch (const NetworkError& e) {
                if (attempts > 0) {
                    // Retry sending the log entry
                    std::this_thread::sleep_for(std::chrono::seconds(1));
                } else {
                    // Log an error and exit
                    logError("Failed to send log entry: " + e.what());
                    return;
                }
            } catch (const RateLimitError& e) {
                if (attempts > 0) {
                    // Wait for the rate limit to reset
                    std::this_thread::sleep_for(std::chrono::minutes(1));
                } else {
                    logError("Rate limit exceeded: " + e.what());
                    return;
                }
            } catch (...) {
                logError("Unknown error occurred");
                return;
            }

            // Insert the new LogEntry after the found one
            logList.insert_after(current, std::make_shared<LogEntry>(message));
        }
    }
}

void sendLogToApi(const LogEntry& entry) {
    // Implementation of the API call goes here
}

void logError(const std::string& message) {
    // Implementation of logging error messages goes here
}
