public class ChatMessageProcessor {

    private final ObjectMapper objectMapper = new ObjectMapper();
    private final Logger logger = LoggerFactory.getLogger(ChatMessageProcessor.class);

    public void processChatMessage(String incomingJson) throws IOException {
        JsonNode jsonNode = objectMapper.readTree(incomingJson);
        validateJson(jsonNode);
        String roomId = jsonNode.get("roomId").textValue();
        String userId = jsonNode.get("userId").textValue();
        String message = jsonNode.get("message").textValue();

        List<String> roomConnections = getRoomConnections(roomId);

        try {
            // Forward the message to multiple chat rooms
            for (String roomConnection : roomConnections) {
                sendMessageToRoom(roomConnection, userId, message);
            }
        } catch (Exception e) {
            logger.error("Error forwarding message to room " + roomId, e);
            // Implement retry mechanism for transient network failures
            retrySendMessage(roomId, userId, message);
        }

        logger.info("Message successfully delivered to room " + roomId);
    }

    private void validateJson(JsonNode jsonNode) throws IOException {
