#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json_util.h>

int loadResourceBundle(const char *filePath) {
    // Load the resource bundle from file
    FILE *file = fopen(filePath, "rb");
    if (!file) return -1;  // Error: File not found or corrupted

    // Read JSON data into memory
    size_t jsonDataSize = ftell(file);
    unsigned char *jsonData = (unsigned char *)malloc(jsonDataSize + 1);
    fread(jsonData, jsonDataSize, 1, file);
    fclose(file);

    json_object *jsonBundle = json_object_from_cstring((char *)jsonData);
    if (!jsonBundle) return -2;  // Error: Corrupted or invalid JSON data

    int itemCount = 0;
    json_object_iter *iter = json_object_iter_begin(jsonBundle);
    while (iter != NULL) {
        itemCount++;
        iter = json_object_iter_next(iter);
    }
    json_object_iter_end(iter);

    free(jsonData);
    json_object_free(jsonBundle);

    return itemCount;
}
