pub struct Compiler {
    cache_dir: PathBuf,
    fetcher: Arc<dyn std::any::Any + Send + Sync>,
    max_concurrency: usize,
}

impl Compiler {
    pub fn new(cache_dir: &Path, max_concurrency: usize) -> Self {
        Self {
            cache_dir: cache_dir.to_path_buf(),
            fetcher: Arc::new(std::thread_rng()),
            max_concurrency,
        }
    }

    pub async fn compile(&self, files: Vec<PathBuf>) -> Result<(), io::Error> {
        let start = Instant::now();

        for file in files {
            if let Err(err) = self.compile_file(file).await {
                logging::log_error(&format!("Failed to compile {}: {}", file.display(), err));
                continue;
            }
            logging::log_warn(&format!("Compiled: {}", file.display()));
        }

        let end = Instant::now();
        logging::log(&format!("Total compilation time: {:.2?}", (end - start).as_secs_f64()));

        Ok(())
    }

    async fn compile_file(&self, file: PathBuf) -> Result<(), io::Error> {
        // fetch crate or package if needed
        // ...

        let mut reader = BufReader::new(File::open(file)?);
        // ... compile the file ...
        Ok(())
    }
}

