using System;
using System.Linq;

public class HighPerformanceRandomValueGenerator
{
    private double minValue { get; set; }
    private double maxValue { get; set; }
    private string distributionType { get; set; }

    public HighPerformanceRandomValueGenerator(double min, double max, string type)
    {
        if (min > max) throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        if (!new[] {"Uniform", "Normal", "Cauchy"}.Contains(type))
            throw new ArgumentException("Unsupported distribution type.");

        minValue = min;
        maxValue = max;
        distributionType = type;
    }

    public double GetRandomFloatValue()
    {
        return distributionType switch
        {
            "Uniform" => RandomGenerator.GetUniform(minValue, maxValue),
            "Normal" => RandomGenerator.GetGaussian(minValue, maxValue),
            _ => RandomGenerator.GetCauchy(minValue, maxValue)
        };
    }

    public int GetRandomIntValue()
    {
        return (int)GetRandomFloatValue();
    }

    public double GetRandomFloatValueWithinQuantileRange(double lowerQuantile, double upperQuantile)
    {
        var randomValue = GetRandomFloatValue();
        return randomValue < (1 - lowerQuantile) * (maxValue - minValue) + minValue
            ? randomValue
            : maxValue;
    }

    public int GetRandomIntValueWithinStandardDeviations(double standardDeviation, double mean)
    {
        var randomValue = GetRandomFloatValue();
        return (int)(randomValue * standardDeviation + mean);
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}], Distribution: {distributionType}";
    }
}

public static class RandomGenerator
{
    // implementation of uniform, normal, and cauchy distributions
}
