typedef struct {
    CURL *easy;
    char *url;
    int retries;
} scrape_request_t;

void *scrape_thread(void *args) {
    scrape_request_t *request = (scrape_request_t *)args;
    CURLcode res;
    printf("Starting thread to scrape URL: %s\n", request->url);

    do {
        res = curl_easy_setopt(request->easy, CURLOPT_URL, request->url);
        if (res != CURLE_OK) {
            fprintf(stderr, "cURL error setting URL: %s\n", curl_error_str(res));
            break;
        }

        CURLcode ret = curl_easy_perform(request->easy, NULL);
        if (ret == CURLE_OK) {
            printf("Scraped data for %s successfully.\n", request->url);
        } else {
            fprintf(stderr, "cURL error: %s\n", curl_error_str(ret));
            if (request->retries > 0) {
                printf("Retrying in 1 second...\n");
                sleep(1);
                request->retries--;
            } else {
                break;
            }
        }
    } while (request->retries > 0);

    return NULL;
}

