import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.util.List;
import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.RecursiveTask;

public class FileProcessor {
    public void processFileBatchWithValidation(String inputDirectory, String outputDirectory, List<Class<? extends Rule>> validationRules) {
        ForkJoinPool pool = new ForkJoinPool();
        List<File> files = listFiles(new File(inputDirectory));

        pool.invoke(new FileValidator(files, validationRules, inputDirectory, outputDirectory));
    }

    private class FileValidator extends RecursiveTask<Void> {
        private List<File> files;
        private List<Class<? extends Rule>> validationRules;
        private String inputDirectory;
        private String outputDirectory;

        public FileValidator(List<File> files, List<Class<?extends Rule>> validationRules, String inputDirectory, String outputDirectory) {
            this.files = files;
            this.validationRules = validationRules;
            this.inputDirectory = inputDirectory;
            this.outputDirectory = outputDirectory;
