#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <signal.h>
#include <sys/types.h>
#include <unistd.h>

#define LOG_LEVEL 2 // 1: error, 2: warning, 3: informational

// Function prototypes
void log_message(int level, const char* message);
void process_file(const char* input_filename, const char* output_filename);

// Logging function
void log_message(int level, const char* message) {
    time_t current_time = time(NULL);
    struct tm *time_info = localtime(&current_time);
    printf("[%04d-%02d-%02d %02d:%02d:%02d] ", 
           time_info->tm_year + 1900, 
           time_info->tm_mon + 1, 
           time_info->tm_mday, 
           time_info->tm_hour, 
           time_info->tm_min, 
           time_info->tm_sec);
    switch (level) {
        case 1:
            fprintf(stderr, "ERROR: %s\n", message);
            break;
        case 2:
            printf("WARNING: %s\n", message);
            break;
        case 3:
            printf("%s\n", message);
            break;
    }
}

// Process a file by reading it line by line and processing each line
void process_file(const char* input_filename, const char* output_filename) {
    FILE *input_file = fopen(input_filename, "r");
    if (input_file == NULL) {
        log_message(1, "Error opening input file");
        return;
    }

    FILE *output_file = fopen(output_filename, "w");
    if (output_file == NULL) {
        log_message(1, "Error opening output file");
        fclose(input_file);
        return;
    }

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), input_file)) {
        // Remove trailing newline
        size_t length = strlen(buffer);
        if (buffer[length - 1] == '\n') {
            buffer[length - 1] = '\0';
        }

        // Skip lines with less than three values
        char *token = strtok(buffer, " ");
        int value_count = 0;
        while (token != NULL) {
            token = strtok(NULL, " ");
            if (token == NULL) break;
            value_count++;
        }
        if (value_count < 3) continue;

        // Compute average of last three values
        float total = 0.0f;
        int count = 0;
        for (int i = value_count - 3; i < value_count; i++) {
            token = strtok(NULL, " ");
            if (token == NULL) break;
            char *endptr;
            float num = strtof(token, &endptr);
            if (*endptr != '\0' || num != num) { // Check for non-numeric values
                log_message(2, "Warning: Non-numeric value found");
                continue;
            }
            total += num;
            count++;
        }

        float average = (count > 0) ? total / count : 0.0f;

        // Write processed data to output file
        fprintf(output_file, "%.2f,%.2f,%.2f\n", 
               total, total - average * count, average);

        free(buffer);
    }

    fclose(input_file);
    fclose(output_file);
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        log_message(1, "Invalid number of arguments");
        return 1;
    }

    process_file(argv[1], argv[2]);

    return 0;
}
