import json
from typing import Dict, Any

class JSONParser:
    registry: Dict[str, callable] = {}

    @classmethod
    def add_factory(cls, factory_id: str, factory_func: callable):
        cls.registry[factory_id] = factory_func

    @classmethod
    def get_factory(cls, factory_id: str) -> callable:
        return cls.registry.get(factory_id)

    @classmethod
    def parse_json(cls, json_str: str) -> Any:
        try:
            data = json.loads(json_str)
            if 'type' in data and data['type'] in cls.registry:
                factory_func = cls.get_factory(data['type'])
                return factory_func(**data.get('args', {}))
            else:
                raise ValueError("Invalid JSON structure")
        except (json.JSONDecodeError, KeyError) as e:
            raise ValueError(f"Failed to parse JSON: {e}")

    @classmethod
    def serialize_json(cls, obj: Any) -> str:
        try:
            factory_id = type(obj).__name__
            if factory_id in cls.registry:
                serialized_obj = {'type': factory_id}
                for key, value in obj.__dict__.items():
                    serialized_obj[key] = value
                return json.dumps(serialized_obj)
            else:
                raise ValueError(f"Unsupported object type: {factory_id}")
        except Exception as e:
            raise ValueError(f"Failed to serialize JSON: {e}")
