        std::mt19937_64 engine(std::time(nullptr));
        std::uniform_int_distribution<> distribution(0, 1);
        std::string sessionId;
        for (int i = 0; i < 22; ++i) {
            int val = distribution(engine);
            if (val % 2 == 0)
                sessionId += (char)(std::rand() % 26 + 'a');
            else
                sessionId += (char)(std::rand() % 10 + '0');
        }
        return base64Encode(sessionId);
    }

private:
    std::string base64Encode(const std::string& input) {
        std::string output;
        for (int i = 0; i < input.length(); ++i) {
            char c = input[i];
            if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')) {
                output.push_back(c);
            } else {
                int val = (int)c;
                while (val > 0) {
                    output.push_back((char)(val % 64 + (val < 26 ? 'a' : (val < 52 ? 'A' : '0'))));
                    val /= 64;
                }
            }
        }
        return output;
    }
};

