function generateUniqueId($length = 32) {
    if ($length < 1 || $length > 256) {
        throw new Exception("Invalid length. Length must be between 1 and 256.");
    }

    $characters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    $randomString = '';

    for ($i = 0; $i < $length; $i++) {
        $randomString .= $characters[rand(0, strlen($characters) - 1)];
    }

    return $randomString;
}

function hashPassword($password) {
    return password_hash($password, PASSWORD_BCRYPT);
}

function registerUser($username, $email, $password) {
    try {
        // Generate unique ID
        $uniqueId = generateUniqueId();

        // Hash password
        $hashedPassword = hashPassword($password);

        // Make API request to authenticate service
        $apiUrl = 'https://example.com/authenticate';
        $headers = array('Authorization' => 'Bearer YOUR_API_KEY');
        $data = array('username' => $username, 'email' => $email, 'hashed_password' => $hashedPassword);

        $ch = curl_init($apiUrl);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_POST, true);
        curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($data));
        foreach ($headers as $header => $value) {
            curl_setopt($ch, CURLOPT_HTTPHEADER, array(array($header, $value)));
        }

        $response = curl_exec($ch);

        if (curl_errno($ch)) {
            throw new Exception('API request failed: ' . curl_error($ch));
        } elseif (stripos($response, 'error') !== false) {
            throw new Exception('Authentication error: ' . $response);
        }

        // If API is unavailable, return an error
    } catch (Exception $e) {
        return array('success' => false, 'message' => $e->getMessage());
    }

    return array('success' => true, 'uniqueId' => $uniqueId);
}
