import re
import requests
from threading import Semaphore
from collections import defaultdict
from settings import REGEX_FICTION, REGEX_NONFICTION, REGEX_POETRY

def extract_book_titles(text):
    titles = defaultdict(int)
    for match in re.finditer(r'\b(' + '|'.join([REGEX_FICTION, REGEX_NONFICTION, REGEX_POETRY]) + r')\b', text.lower()):
        title = match.group(1).strip('.,;:')
        titles[title] += 1
    return dict(titles)

def verify_book_titles(book_titles, rate_limiter):
    verified_titles = {}
    for title, count in book_titles.items():
        if count >= settings.API_REQUEST_THRESHOLD:
            try:
                response = requests.get(f'https://goodreads.com/search?q={title}', headers={'User-Agent': 'Your App'})
                if response.status_code == 200:
                    verified_titles[title] = count
                else:
                    rate_limiter.wait()
                    response = requests.get(f'https://goodreads.com/search?q={title}', headers={'User-Agent': 'Your App'})
                    if response.status_code == 200:
                        verified_titles[title] = count
            except (requests.exceptions.RequestException, ValueError):
                pass
    return verified_titles

def main(text, rate_limiter):
    book_titles = extract_book_titles(text)
    verified_titles = verify_book_titles(book_titles, rate_limiter)
    return verified_titles

if __name__ == '__main__':
    settings = load_settings()  # assumes a settings module
    rate_limiter = Semaphore(settings.API_REQUEST_RATE_LIMIT)
    text = load_text()  # assumes a function to load the text corpus
    result = main(text, rate_limiter)
    print(result)

