import os
import hashlib
import logging
from functools import lru_cache
from typing import Dict, List

@lru_cache(maxsize=None)
def calculate_sha256(file_path: str) -> str:
    with open(file_path, 'rb') as file:
        file_hash = hashlib.sha256()
        while chunk := file.read(4096):
            file_hash.update(chunk)
        return file_hash.hexdigest()

class LogMonitor:
    def __init__(self, log_dir: str, monitoring_system_api: str, exclusion_criteria: List[str]):
        self.log_dir = log_dir
        self.monitoring_system_api = monitoring_system_api
        self.exclusion_criteria = exclusion_criteria
        self.log_files = {}
        self.integrity_cache = {}

    def monitor(self):
        while True:
            for file in os.listdir(self.log_dir):
                if not any(exclusion in file for exclusion in self.exclusion_criteria):
                    if file not in self.log_files:
                        try:
                            self.log_files[file] = calculate_sha256(os.path.join(self.log_dir, file))
                        except Exception as e:
                            logging.error(f"Error processing log file {file}: {str(e)}")
                    elif self.integrity_cache.get(file) != self.log_files[file]:
                        self.integrity_cache.pop(file)
            for file in list(self.log_files.keys()):
                if not any(exclusion in file for exclusion in self.exclusion_criteria):
                    try:
                        file_hash = calculate_sha256(os.path.join(self.log_dir, file))
                        if file_hash != self.log_files[file]:
                            self.integrity_cache[file] = file_hash
                            self.monitoring_system_api.send_alert(f"Log file {file} has been updated")
                    except Exception as e:
                        logging.error(f"Error processing log file {file}: {str(e)}")
            time.sleep(1)

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    log_monitor = LogMonitor("/path/to/log/dir", "monitoring_system_api_url", ["*.old"])
    log_monitor.monitor()
