import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jaxdsv.JsonSchemaValidator;

import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.List;

public class CartUpdateServlet extends HttpServlet {
    private final TokenManagementService tokenManagementService;
    private final ProductService productService;
    private final ObjectMapper mapper = new ObjectMapper();
    private final JsonSchemaValidator validator = new JsonSchemaValidator();

    public CartUpdateServlet(TokenManagementService tokenManagementService, ProductService productService) {
        this.tokenManagementService = tokenManagementService;
        this.productService = productService;
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String userId = request.getParameter("user_id");
        String sessionToken = request.getParameter("session_token");
        String jsonData = request.getReader().lines().collect(Collectors.join());

        if (!tokenManagementService.validateSessionToken(sessionToken, userId)) {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            response.getWriter().print("Invalid session token");
            return;
        }

        ProductCart productCart;

        try {
            productCart = mapper.readValue(jsonData, ProductCart.class);
        } catch (JsonProcessingException e) {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            response.getWriter().print("Failed to deserialize JSON data: " + e.getMessage());
            return;
        }

        if (!validator.isValid(jsonData, CartUpdateSchema.CART_UPDATE_SCHEMA)) {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            response.getWriter().print("Invalid JSON format");
            return;
        }

        try (Transaction tx = productService.beginTransaction()) {
            productService.updateCart(userId, productCart);

            // Send confirmation email
            EmailService.sendEmail(userId, "Cart Updated", "Your cart has been updated successfully");

            tx.commit();
        } catch (Exception e) {
            response.setStatus(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
            response.getWriter().print("Failed to update cart: " + e.getMessage());
            return;
        }

        response.setStatus(HttpServletResponse.SC_OK);
    }
}
