    private final Logger logger = new RemoteLogger();
    private volatile boolean isRunning = false;
    private final HeartbeatTask heartbeatTask;
    private final ConfigUpdater configUpdater;

    public ServiceManager(String[] apiEndpoints) throws IOException {
        this.heartbeatTask = new HeartbeatTask(scheduler);
        this.configUpdater = new ConfigUpdater(apiEndpoints);

        scheduler.scheduleAtFixedRate(heartbeatTask, 0, 10 * 1000, TimeUnit.MILLISECONDS); // every 10 seconds
    }

    public void startService() {
        isRunning = true;
        logger.log("Service started");
        try {
            configUpdater.updateConfig();
        } catch (IOException e) {
            logger.error("Failed to update configuration", e);
        }
    }

    public void stopService() {
        isRunning = false;
        scheduler.shutdown();
        logger.log("Service stopped");
    }

    private class HeartbeatTask implements Runnable {
        @Override
        public void run() {
            if (isRunning) {
                try {
                    configUpdater.sendHeartbeat();
                    logger.info("Sent heartbeat");
                } catch (IOException e) {
                    logger.error("Failed to send heartbeat", e);
                }
            }
        }
    }

