// Node of Octree
struct OctreeNode {
    std::vector<OctreeNode*> children;
    int dataPointCount;
};

class Octree {
public:
    Octree(int sizeLimit) : sizeLimit_(sizeLimit), root_(new OctreeNode()) {}

    ~Octree() {
        clear(root_);
    }

    bool storeDataPoint(float x, float y, float z);

private:
    void clear(OctreeNode* node);

    int sizeLimit_;
    std::unique_ptr<OctreeNode> root_;

    // Helper function to free memory
    void clear(OctreeNode* node) {
        for (auto child : node->children) {
            if (child != nullptr) {
                clear(child);
                delete child;
            }
        }
    }
};

// Store data point into Octree
bool Octree::storeDataPoint(float x, float y, float z) {
    if (root_->dataPointCount >= sizeLimit_) {
        std::cout << "Octree full. Cannot store more points.\n";
        return false;
    }

    // Create a new node for the data point
    OctreeNode* newNode = new OctreeNode();
    root_->children.push_back(newNode);
    newNode->dataPointCount = 1;

    // Insert the data point into the octree
    insert(root_, x, y, z);

    return true;
}

int main() {
    Octree octree(1000); // Initialize an octree with a size limit of 1000

    if (octree.storeDataPoint(1.0f, 2.0f, 3.0f)) {
        std::cout << "Data point stored successfully.\n";
    }

    return 0;
}
