        with ThreadPoolExecutor(max_workers=10) as executor:
            for title, count in titles.items():
                futures = [executor.submit(self.verify_title, title) for _ in range(count)]
                results = [future.result() for future in futures]
                verified_titles.update({title: len(results)})
        return verified_titles

    def verify_title(self, title):
        # API call to Goodreads or LibraryThing
        try:
            response = requests.get(f"https://api.goodreads.com/book/title/{title}")
            if response.status_code == 200:
                return True
        except (requests.exceptions.RequestException, json.JSONDecodeError) as e:
            self.logger.error(f"Error verifying title {title}: {e}")
            return None

