// JavaScript function: FindElementsBySelector
function FindElementsBySelector(node, selector) {
    const result = [];
    (function traverse(node) {
        if (!node) return;
        if (node.classList.contains(selector) || node.id === selector) {
            result.push(node);
        }
        for (const child of node.children) {
            traverse(child);
        }
    })(node);
    return result;
}
