#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* bfs(int* nodes, int n, int** graph, int start, int maxHops) {
    Node* queue = NULL;
    Node* visited = NULL;
    int* distances = (int*)malloc((n+1)*sizeof(int));
    for (int i = 0; i <= n; i++) distances[i] = -1;

    Node* node = (Node*)malloc(sizeof(Node));
    node->data = start;
    node->next = NULL;
    queue = node;

    visited = (Node*)malloc(sizeof(Node));
    visited->data = start;
    visited->next = NULL;

    int hops = 0;
    while (queue) {
        node = queue;
        queue = queue->next;

        for (int i = 0; graph[node->data][i] != -1; i++) {
            if (distances[graph[node->data][i]] == -1) {
                distances[graph[node->data][i]] = hops+1;

                node = (Node*)malloc(sizeof(Node));
                node->data = graph[node->data][i];
                node->next = NULL;

                queue->next = node;
                queue = node;
            }
            else if (distances[graph[node->data][i]] == hops) {
                printf("Cyclic graph detected. Terminating gracefully.\n");
                free(distances);
                for (node = visited; node->next; node = node->next) free(node->next);
                free(visited); free(queue);
                return NULL;
            }
        }

        if (++hops > maxHops) break;
    }

    free(distances);
    for (node = visited; node->next; node = node->next) {
        if (!node->next) {
            node->next = queue;
            break;
        }
    }
    free(visited);

    return queue;
}
