public class GameServer {

    private static final Logger logger = LogManager.getLogger();

    public enum Attack {
        ATTACK1, ATTACK2
    }

    private Attack currentAttack;
    private long cooldownExpirationTime;

    private interface AttackSelectionStrategy {
        Attack selectAttack();
    }

    private AttackSelectionStrategy attackStrategy;

    private AsynchronousChannelGroup channelGroup;
    private ExecutorService executorService;

    public GameServer() {
        this.attackStrategy = new RandomAttackSelector();
        this.channelGroup = AsynchronousChannelGroup.withFixedAvailableProcessors();
        this.executorService = Executors.newCachedThreadPool();
    }

    public void establishConnection(String remoteHost, int remotePort) throws IOException, InterruptedException {
        AsynchronousSocketChannel channel = AsynchronousSocketChannel.open(channelGroup);
        channel.setOption(SocketOptions.SO_REUSEADDR, true);

        channel.connect(new InetSocketAddress(remoteHost, remotePort), new CompletionHandler<Void, AsynchronousSocketChannel>() {

            @Override
            public void completed(Void result, AsynchronousSocketChannel channel) {
                // Handle connection established
            }

            @Override
            public void failed(Throwable exc, AsynchronousSocketChannel channel) {
                // Handle connection failure
            }
        });
    }

    public void handleConnectionStateChange() {
        // Handle state changes
    }

    public void selectAttack() {
        Attack selectedAttack = attackStrategy.selectAttack();

        if (selectedAttack == currentAttack) {
            long timeNow = System.currentTimeMillis();
            if (timeNow < cooldownExpirationTime) {
                // Cooldown not expired yet, print message to console and log event
                logger.info(StructuredSerializedMessage.create()
                        .put("characterId", "Character1")
                        .put("attack", selectedAttack.name())
                        .put("timestamp", timeNow));
            } else {
                currentAttack = selectedAttack;
                cooldownExpirationTime = System.currentTimeMillis() + 1000; // Set new cooldown expiration
                // Print and log the attack selection event
                logger.info(StructuredSerializedMessage.create()
                        .put("characterId", "Character1")
                        .put("attack", selectedAttack.name())
                        .put("timestamp", timeNow));
            }
        } else {
            currentAttack = selectedAttack;
            cooldownExpirationTime = System.currentTimeMillis() + 1000; // Set new cooldown expiration
            // Print and log the attack selection event
            logger.info(StructuredSerializedMessage.create()
                    .put("characterId", "Character1")
                    .put("attack", selectedAttack.name())
                    .put("timestamp", System.currentTimeMillis()));
        }
    }

    public void parseTIFFImage(String filePath) {
        TIFFImageParser parser = new TIFFImageParser();
