import json
from collections import defaultdict

class JSONParser:
    def __init__(self):
        self.registry = {}
        self.forward_list_registry = defaultdict(list)
        self.factories = {}

    def add_factory(self, factory_id, factory_func):
        self.factories[factory_id] = factory_func

    def create_instance(self, json_string):
        return json.loads(json_string)

    def get_forward_list(self, forward_list_id):
        return self.forward_list_registry[forward_list_id]

    def insert_after(self, forward_list, target_str, new_str, position_index=0):
        try:
            index = forward_list.index(target_str, position_index)
            forward_list.insert(index + 1, new_str)
        except ValueError as e:
            print(f"Error: {e}")
            forward_list.append(new_str)

    def deserialize_byte_array(self, byte_array):
        return json.loads(byte_array.decode('utf-8'))

    def generate_random_string(self, password):
        import hashlib
        hashed_password = hashlib.sha256(password.encode()).hexdigest()
        return f"{hashed_password}-random-string"

    async def load_json_files(self, file_paths):
        loaded_files = []
        errors = []

        for file_path in file_paths:
            try:
                with open(file_path, 'r') as file:
                    loaded_files.append((file_path, json.load(file)))
            except Exception as e:
                errors.append(f"Error loading {file_path}: {e}")

        if errors:
            print("Error(s) occurred during JSON file loading:")
            for error in errors:
                print(error)
        else:
            return loaded_files

    def handle_circular_dependencies(self, loaded_files):
        seen = set()
        stack = []

        for file in loaded_files:
            self._check_for_circular_dependencies(file[1], seen, stack)

        if stack:
            raise ValueError("Circular dependency detected")

    def _check_for_circular_dependencies(self, obj, seen, stack):
        if id(obj) in seen:
            return True
        seen.add(id(obj))
        stack.append(obj)
        for key, value in obj.items():
            if isinstance(value, dict):
                if self._check_for_circular_dependencies(value, seen, stack):
                    return True
        stack.pop()
        return False

    def load_and_deserialize(self, file_paths):
        loaded_files = await self.load_json_files(file_paths)

        for file in loaded_files:
            try:
                instance = self.create_instance(json.dumps(file[1]))
                if isinstance(instance, dict):
                    for key, value in instance.items():
                        if isinstance(value, str) and 'factory_id' in value:
                            factory_id = value.split(':')[1]
                            if factory_id not in self.factories:
                                raise ValueError(f"Unknown factory ID: {factory_id}")
                            instance[key] = self.factories[factory_id]()
                print(f"Loaded file {file[0]} with instance {instance}")
            except Exception as e:
                print(f"Error deserializing file {file[0]}: {e}")

        random_string = self.generate_random_string("password")
        print(f"Random string generated: {random_string}")
