Here is the PHP function that generates a secure random string, hashes a given password, and manages session tokens:

```php
<?php

function generateSecureRandomString(int $length, array $chars): ?string {
    if ($length < 1) {
        return null;
    }
    if (!isset($chars[0]) || !is_string($chars[0])) {
        return null;
    }

    $pool = implode('', $chars);
    $secureRandomString = '';
    for ($i = 0; $i < $length; $i++) {
        $secureRandomString .= $pool[random_int(0, strlen($pool) - 1)];
    }

    // Check the strength of the generated random string
    $minEntropy = 128;
    if (strlen($secureRandomString) < $minEntropy) {
        return null;
    }

    return $secureRandomString;
}

function hashPasswordWithSalt(string $password, array $salt, string $hashAlgorithm): ?string {
    if (!isset($salt[0]) || !is_string($salt[0])) {
        return null;
    }
    if (!in_array($hashAlgorithm, ['bcrypt', 'Argon2id'])) {
        return null;
    }

    $hashedPassword = '';
    switch ($hashAlgorithm) {
        case 'bcrypt':
            $hashedPassword = password_hash($password . $salt[0], PASSWORD_BCRYPT);
            break;
        case 'Argon2id':
            $hashedPassword = password_hash($password . $salt[0], PASSWORD_ARGON2ID);
            break;
    }

    return $hashedPassword;
}

function manageSessionTokens(): void {
    // Start session management
    session_start();

    if (!isset($_SESSION['tokens'])) {
        $_SESSION['tokens'] = [];
    }

    while (true) {
        $token = generateSecureRandomString(16, ['a', 'b', 'c']);

        if ($token !== null && !in_array($token, $_SESSION['tokens'])) {
            array_push($_SESSION['tokens'], $token);
            break;
        } else {
            // Token not strong enough or already exists
            continue;
        }
    }

    // Regenerate session tokens periodically
    register_tick_function(function() {
        if (time() % 60 == 0) {
            manageSessionTokens();
        }
    });
}

// Example usage:
manageSessionTokens();

?>
