import asyncio
import json
from aiofiles import open as ao_open

class JSONProcessor:
    def __init__(self):
        self.registry = {}

    def add_factory(self, id: str, factory_func):
        if id in self.registry:
            raise ValueError(f"ID '{id}' already registered.")
        self.registry[id] = factory_func

    async def process_file(self, file_id: str, file_path: str):
        try:
            with ao_open(file_path, 'r') as f:
                file_content = await f.read()
            obj = json.loads(file_content)
            if file_id in self.registry:
                factory_func = self.registry[file_id]
                instance = factory_func(obj)
                print(f"Processed {file_path} - Created instance: {instance}")
            else:
                raise ValueError(f"Factory function not found for ID '{file_id}'")
        except json.JSONDecodeError as e:
            print(f"Failed to parse JSON in file {file_path}: {e}")
        except Exception as e:
            print(f"An error occurred while processing file {file_path}: {e}")

    async def load_files(self, files):
        tasks = []
        for file_id, file_path in files.items():
            task = self.process_file(file_id, file_path)
            tasks.append(task)

        done, pending = await asyncio.wait(tasks, return_exceptions=True)
        for task in done:
            print(f"File processing completed: {task}")
        for task in pending:
            if isinstance(task.exception(), Exception):
                print(f"Error occurred while processing file: {task.exception()}")


# Example usage
async def main():
    processor = JSONProcessor()
    files = {"file1": "path/to/file1.json", "file2": "path/to/file2.json"}
    await processor.load_files(files)

if __name__ == "__main__":
    asyncio.run(main())
