use std::path::{Path, PathBuf};
use std::fs;
use std::time::{SystemTime,Duration};
use log::{info,error};
use slog;
use slog_drain;

struct DirectoryManager {
    parent_directory_path: String,
    timestamp_format: String,
    cleanup_interval: u64,
}

impl DirectoryManager {
    fn new(parent_directory_path: &str, timestamp_format: &str) -> Self {
        DirectoryManager {
            parent_directory_path: parent_directory_path.to_string(),
            timestamp_format: timestamp_format.to_string(),
            cleanup_interval: 60 * 1000, // default cleanup interval in milliseconds
        }
    }

    fn create_directory(&self, name: &str) -> Result<PathBuf, Box<dyn std::error::Error>> {
        let mut dir_path = Path::new(&self.parent_directory_path).to_path_buf();
        dir_path.push(name);

        if !dir_path.exists() {
            fs::create_dir_all(&dir_path)?;
        }

        Ok(dir_path)
    }

    fn generate_unique_name(&self) -> String {
        let timestamp = SystemTime::now().duration_since(SystemTime::UNIX_EPOCH).unwrap();
        format!("{}-{}", self.timestamp_format, timestamp.as_millis())
    }
}

fn main() {
    env_logger::init();

    let mut dir_manager = DirectoryManager::new("/tmp", "%Y-%m-%d_%H-%M-%S");
    let unique_name = dir_manager.generate_unique_name();
    let dir_path = dir_manager.create_directory(&unique_name).unwrap();

    println!("Directory created: {}", dir_path.display());
}
