    private readonly ILogger _logger;
    private readonly ICacheService _cacheService;
    private readonly IMessageQueueService _messageQueueService;
    private readonly IAuditLogger _auditLogger;

    public async Task UpdateElement(string pageSectionId, string elementId, string htmlContent, int? versionId)
    {
        if (string.IsNullOrEmpty(pageSectionId))
            throw new ArgumentException("Page section ID is required", nameof(pageSectionId));

        if (string.IsNullOrEmpty(elementId))
            throw new ArgumentException("Element ID is required", nameof(elementId));

        if (string.IsNullOrEmpty(htmlContent))
            throw new ArgumentException("HTML content is required", nameof(htmlContent));

        try
        {
            _cacheService.UpdateElementHtmlContent(pageSectionId, elementId, htmlContent);

            if (versionId.HasValue)
                if (!_cacheService.ValidateVersion(pageSectionId, elementId, versionId.Value))
                    throw new InvalidOperationException($"Invalid version ID {versionId} for element {elementId}");

            await _messageQueueService.SendMessage("page-refresh");

            _auditLogger.LogUpdateAttempt(pageSectionId, elementId, htmlContent, versionId);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating element");
            throw;
        }
    }
}
