Here is the C code for the distributed semaphore management system:
```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define the structure for a semaphore
typedef struct {
    int value;
    pthread_mutex_t mutex;
} semaphore_t;

// Function to create a new semaphore with initial value 1
semaphore_t* semaphore_create(int initial_value) {
    semaphore_t* sem = (semaphore_t*) malloc(sizeof(semaphore_t));
    sem->value = initial_value;
    pthread_mutex_init(&sem->mutex, NULL);
    return sem;
}

// Function to delete a semaphore
void semaphore_delete(semaphore_t* sem) {
    pthread_mutex_destroy(&sem->mutex);
    free(sem);
}

// Function to acquire a semaphore
int semaphore_acquire(semaphore_t* sem) {
    pthread_mutex_lock(&sem->mutex);
    if (sem->value > 0) {
        --sem->value;
        return 1; // success
    } else {
        return 0; // failed
    }
    pthread_mutex_unlock(&sem->mutex);
}

// Function to release a semaphore
void semaphore_release(semaphore_t* sem) {
    pthread_mutex_lock(&sem->mutex);
    ++sem->value;
    pthread_mutex_unlock(&sem->mutex);
}

// Define the structure for a database connection pool
typedef struct {
    int connections; // number of available connections
    int max_connections; // maximum allowed connections
    semaphore_t* sem; // semaphore to manage connections
} db_pool_t;

// Function to create a new database connection pool with initial connections 1 and max connections 10
db_pool_t* db_pool_create(int initial_connections, int max_connections) {
    db_pool_t* pool = (db_pool_t*) malloc(sizeof(db_pool_t));
    pool->connections = initial_connections;
    pool->max_connections = max_connections;
    pool->sem = semaphore_create(1);
    return pool;
}

// Function to delete a database connection pool
void db_pool_delete(db_pool_t* pool) {
    semaphore_delete(pool->sem);
    free(pool);
}

// Function to acquire a database connection from the pool
int db_pool_acquire_connection(db_pool_t* pool) {
    if (pool->connections > 0) {
        --pool->connections;
        return 1; // success
    } else {
        return 0; // failed
    }
}

// Function to release a database connection back to the pool
void db_pool_release_connection(db_pool_t* pool) {
    ++pool->connections;
}

// Define the API endpoints for managing semaphores and handling database connections
int main() {
    // Example usage: create a semaphore and acquire it
    semaphore_t* sem = semaphore_create(1);
    if (semaphore_acquire(sem)) {
        printf("Semaphore acquired!\n");
    } else {
        printf("Semaphore acquisition failed.\n");
    }
    // ... release the semaphore, delete it, etc.

    return 0;
}
```
