package com.example.fileanalyzer;

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class FileAnalyzer {

    private static final int BUFFER_SIZE = 1024 * 1024; // 1MB buffer size
    private static final String DEFAULT_PARSING_PATTERN = "^(\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}),([A-Z]{3,5})-(\\d+)$";

    public List<String> parseLogData(String logFilepath) throws IOException {
        List<String> parsedData = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(logFilepath), BUFFER_SIZE)) {
            String line;
            while ((line = reader.readLine()) != null) {
                // Use the parsing pattern to extract relevant fields
                Pattern parsingPattern = Pattern.compile(DEFAULT_PARSING_PATTERN);
                Matcher matcher = parsingPattern.matcher(line);
                if (matcher.matches()) {
                    parsedData.add(parseMatchedFields(matcher));
                } else {
                    System.out.println("Malformed log entry: " + line);
                }
            }
        }
        return parsedData;
    }

    private String parseMatchedFields(Matcher matcher) {
        // Extract relevant fields from the matched log entry
        String timestamp = matcher.group(1);
        String errorCode = matcher.group(2);
        int userId = Integer.parseInt(matcher.group(3));
        // Return a formatted string containing the extracted fields
        return String.format("{timestamp: %s, error_code: %s, user_id: %d}", timestamp, errorCode, userId);
    }
}
