#include <iostream>
#include <string>
#include <map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>

using namespace std;

class Semaphore {
public:
    Semaphore(int value = 0) : value_(value), locked_(false) {}

    void acquire() {
        unique_lock<mutex> lock(mutex_);
        while (!locked_ && value_ == 0) {
            cv_.wait(lock);
        }
        if (locked_) {
            --value_;
            if (value_ == 0)
                locked_ = false;
        } else
            --value_;
    }

    void release() {
        unique_lock<mutex> lock(mutex_);
        if (!locked_)
            value_++;
        else
            locked_ = false;
        cv_.notify_all();
    }

private:
    int value_;
    bool locked_;
    mutex mutex_;
    condition_variable cv_;
};

class DistributedSemaphoreService {
public:
