        int retries = 0;
        while (true) {
            try {
                // Call cloud service to acquire the semaphore, with retry mechanism
                // ...
                break;
            } catch (exception& e) {
                if (retries >= maxRetryCount_) {
                    cerr << "Error: Cannot acquire semaphore. Service unavailable." << endl;
                    return;
                }
                this_thread::sleep_for(chrono::milliseconds(min(retries * 100, 500)));
                retries++;
            }
        }
    }

    void releaseSemaphore(string name) {
        int retries = 0;
        while (true) {
            try {
                // Call cloud service to release the semaphore, with retry mechanism
                // ...
                break;
            } catch (exception& e) {
                if (retries >= maxRetryCount_) {
                    cerr << "Error: Cannot release semaphore. Service unavailable." << endl;
                    return;
                }
                this_thread::sleep_for(chrono::milliseconds(min(retries * 100, 500)));
                retries++;
            }
        }
    }

private:
    int retryCount_;
    int maxRetryCount_;
};

int main() {
