const express = require('express');
const app = express();
const axios = require('axios');
const fs = require('fs');

// Configuration file
const config = JSON.parse(fs.readFileSync('config.json', 'utf8'));

// Define constants for weather APIs and cache timeouts
const API_OPENWEATHERMAP = 'https://api.openweathermap.org/data/2.5/weather';
const API_WEATHERAPI = 'https://weatherapi.com/v1/current.json';
const API_ACCUWEATHER = 'https://api.accuweather.com/currentconditions/v1';
const CACHE_TIMEOUT_OPENWEATHERMAP = 300000; // 5 minutes
const CACHE_TIMEOUT_WEATHERAPI = 1800000; // 30 minutes

// Define weather data structure
const WeatherData = {
  temperature: null,
  humidity: null,
  windSpeed: null,
  forecast: []
};

// Function to fetch and aggregate weather data from multiple APIs
async function getWeatherData(location, cache) {
  const apiResponses = await Promise.all([
    axios.get(`${API_OPENWEATHERMAP}?q=${location}&units=metric&appid=${config.openweathermapApiKey}`),
    axios.get(`${API_WEATHERAPI}?q=${location}&key=${config.weatherapiApiKey}`),
    axios.get(`${API_ACCUWEATHER}?q=${location}&details=true&apikey=${config.accuweatherApiKey}`)
  ]);

  // Aggregate data from each API response
  const aggregatedData = {
    temperature: (apiResponses[0].data.main.temp + apiResponses[1].data.current.condition.temp + apiResponses[2].data.current.temperature) / 3,
    humidity: (apiResponses[0].data.main.humidity + apiResponses[1].data.current condiciones.humidity + apiResponses[2].data.current.relativeHumidity) / 3,
    windSpeed: Math.max(apiResponses[0].data.wind.speed, apiResponses[1].data.current.windspeed, apiResponses[2].data.current.windSpeed),
    forecast: [...apiResponses[0].data.weather.forecast, ...apiResponses[1].data.forecast, ...apiResponses[2].data.forecast]
  };

  // Cache the aggregated data
  cache.set(location, JSON.stringify(aggregatedData), CACHE_TIMEOUT_OPENWEATHERMAP);

  return aggregatedData;
}

// Function to generate a JSON report for weather data
function generateReport(weatherData) {
  const report = {
    temperature: weatherData.temperature,
    humidity: weatherData.humidity,
    windSpeed: weatherData.windSpeed,
    forecast: weatherData.forecast.map((forecast, index) => ({
      date: new Date(forecast.datetime * 1000),
      condition: forecast.condition.text
    }))
  };

  return JSON.stringify(report);
}

// Express route to handle GET requests for weather data
app.get('/weather', async (req, res) => {
  const location = req.query.location;
  const cache = require('memory-cache')();

  try {
    // Check if the aggregated data is cached
    const cachedData = cache.get(location);
    if (cachedData) {
      const weatherData = JSON.parse(cachedData);
      return res.send(generateReport(weatherData));
    }

    // Fetch and aggregate weather data from multiple APIs
    const weatherData = await getWeatherData(location, cache);

    // Generate the JSON report
    const report = generateReport(weatherData);

    // Cache the aggregated data
    cache.set(location, report, CACHE_TIMEOUT_OPENWEATHERMAP);

    return res.send(report);
  } catch (error) {
    console.error(error);
    res.status(500).send({ error: 'Failed to retrieve weather data' });
  }
});

// Start the Express server
const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Weather service started on port ${port}`);
});
