import json
import logging
import threading
from typing import Dict, Any

class BaseClass:
    def __init__(self, **kwargs):
        for key, value in kwargs.items():
            setattr(self, key, value)

    @classmethod
    def from_json(cls, json_string: str) -> 'BaseClass':
        return cls(**json.loads(json_string))

class JSONParser:
    registry: Dict[str, Any] = {}

    def __init__(self):
        self.lock = threading.Lock()

    def add_factory_function(self, id: str, factory_func):
        with self.lock:
            self.registry[id] = factory_func

    def create_instance(self, id: str) -> BaseClass:
        if id not in self.registry:
            return None
        with self.lock:
            return self.registry[id]()

    @staticmethod
    def to_json(obj: Any) -> str:
        return json.dumps(obj.__dict__)

    @staticmethod
    def from_json(json_string: str, factory_func):
        obj = BaseClass.from_json(json_string)
        return factory_func()(obj)

class FileUploader:
    def __init__(self):
        self.parser = JSONParser()
        self.lock = threading.Lock()

    def add_factory_function(self, id: str, factory_func):
        self.parser.add_factory_function(id, factory_func)

    def create_instance(self, id: str) -> BaseClass:
        return self.parser.create_instance(id)

    @staticmethod
    def upload_file(file_path: str, parser: JSONParser = None) -> str:
        try:
            with open(file_path, 'r') as file:
                content = file.read()
        except FileNotFoundError:
            logging.error(f"File {file_path} not found")
            return None
        except Exception as e:
            logging.error(f"Error reading file {file_path}: {str(e)}")
            return None

        if parser is None:
            parser = JSONParser()

        try:
            obj = BaseClass.from_json(content)
        except json.JSONDecodeError as e:
            logging.error(f"Invalid JSON in file {file_path}: {str(e)}")
            return None

        return parser.to_json(obj)

    @staticmethod
    def process_file(file_path: str, parser: JSONParser = None) -> BaseClass:
        if parser is None:
            parser = JSONParser()

        try:
            obj = BaseClass.from_json(parser.upload_file(file_path))
        except Exception as e:
            logging.error(f"Error processing file {file_path}: {str(e)}")
            return None

        return obj

    @staticmethod
    def upload_and_process_files(file_paths: list, parser: JSONParser = None) -> Dict[str, BaseClass]:
        results = {}
        thread_pool = []

        for file_path in file_paths:
            t = threading.Thread(target=FileUploader.process_file, args=(file_path, parser))
            thread_pool.append(t)
            t.start()

        for t in thread_pool:
            t.join()
            if t.is_alive():
                logging.error("Thread did not finish")

        return results

    @staticmethod
    def query_upload_status(file_paths: list) -> Dict[str, str]:
        # TO DO: implement status query logic here
        pass

    @staticmethod
    def get_processed_data(file_paths: list) -> Dict[str, Any]:
        # TO DO: implement data retrieval logic here
        pass

def main():
    file_uploader = FileUploader()

    # Example usage:
    factory_func = lambda obj: MySubClass(obj)
    file_uploader.add_factory_function("my_subclass_id", factory_func)

    file_paths = ["file1.json", "file2.json"]
    results = file_uploader.upload_and_process_files(file_paths)
    print(results)

if __name__ == "__main__":
    main()
