async function runTests(label, f, plugins) {
  const log = await import('logging-service');
  const { Parallel } = await import('parallel');
  const { glob } = await import('glob');

  try {
    // Load plugins
    const pluginFiles = await glob(`plugins/*${label}.js`);
    const pluginsObj = await Promise.all(pluginFiles.map((file) => import(file)));

    // Filter plugins to only include those specified in the input array
    const filteredPlugins = plugins.filter((plugin) => pluginsObj.includes(plugin));

    // Run tests in parallel
    await Parallel.run(async () => {
      for (const plugin of filteredPlugins) {
        try {
          // Load and run plugin tests
          const pluginFile = pluginsObj.find((p) => p.name === plugin);
          const testResults = await f(plugin, pluginFile.test);

          // Log test results
          log.info(`Plugin ${plugin} - Tests passed: ${testResults.passed}, Failed: ${testResults.failed}, Duration: ${testResults.duration}ms`);
        } catch (error) {
          // Handle errors
          log.error(`Error running tests for plugin ${plugin}: ${error}`);
        }
      }
    }, { concurrency: 5 });
  } catch (error) {
    // Catch and rethrow any unexpected errors
    throw error;
  }
}
