#include <stdlib.h>
#include <stdio.h>

struct record {
    long offset;
    int key;
};

void* alloc_arrays(size_t size) {
    void* ptr = NULL;

    // Allocate memory for the 'long' array
    ptr = malloc(size * sizeof(long));
    if (!ptr) {
        printf("Failed to allocate memory for 'long' array.\n");
        return NULL;
    }

    // Allocate memory for the 'int' array
    void* key_ptr = malloc(size * sizeof(int));
    if (!key_ptr) {
        free(ptr); // Free previously allocated memory
        printf("Failed to allocate memory for 'int' array.\n");
        return NULL;
    }

    // Allocate memory for the 'record' array
    ptr = realloc(ptr, size * sizeof(struct record)); // Update the 'long' array pointer
    if (!ptr) {
        free(key_ptr); // Free previously allocated memory
        printf("Failed to allocate memory for 'record' array.\n");
        return NULL;
    }

    return ptr;
}

void dealloc_arrays(void* ptr, size_t size) {
    free(ptr);
    ptr = NULL; // Set the pointer to NULL for safety

    return;
}
