import json
import os
from flask_login import LoginManager, UserMixin, login_user
from flask_principal import Principal, Permission, RoleNeed, UserNeed
from werkzeug.security import generate_password_hash, check_password_hash
from werkzeug.utils import secure_filename
from PIL import Image

class JSONParser:
    def __init__(self):
        self.registry = {}

    def add_factory(self, id, factory):
        self.registry[id] = factory

    def get_instance(self, id):
        if id in self.registry:
            return self.registry[id]()
        else:
            return None

class User(UserMixin):
    def __init__(self, id):
        self.id = id
        self.password_hash = generate_password_hash("password")
        self.profile_picture_path = "default.jpg"

    def check_password(self, password):
        return check_password_hash(self.password_hash, password)

class DAO:
    def update_profile_picture(self, user_id, new_picture):
        if not os.path.isfile(new_picture):
            return False
        if not Image.open(new_picture).format in ["jpg", "jpeg"]:
            return False
        if len(new_picture) > 1000000:
            return False

        try:
            with open("updated_profile_picture.jpg", "wb") as file:
                file.write(Image.open(new_picture).convert("RGB").resize((200, 200)).convert("JPEG"))
        except Exception as e:
            print(f"Error updating profile picture: {e}")
            return False

        user = User(user_id)
        user.profile_picture_path = "updated_profile_picture.jpg"
        return True

class App:
    def __init__(self):
        self.parser = JSONParser()
        self.login_manager = LoginManager()
        self.principal = Principal()

        @self.login_manager.user_loader
        def load_user(user_id):
            return User(user_id)

        @self.principal.permission_loader("user_update")
        def user_update_permission():
            return Permission(RoleNeed("admin"), UserNeed(1))

    def load_json_files(self, file_names):
        for file_name in file_names:
            try:
                with open(file_name) as file:
                    data = json.load(file)
                    instance = self.parser.get_instance(data["id"])
                    if instance is not None:
                        print(f"Loaded JSON file: {file_name}")
                    else:
                        print(f"Failed to load JSON file: {file_name}")
            except Exception as e:
                print(f"Error loading JSON file: {e}")

    def run(self):
        self.parser.add_factory("user", User)
        self.parser.add_factory("admin", lambda: Admin())

        file_names = ["users.json", "admins.json"]
        self.load_json_files(file_names)

        login_user(User(1), remember=True)

if __name__ == "__main__":
    app = App()
    app.run()

