import requests
import time
from datetime import datetime, timedelta
import logging
import json
import os

class WeatherAPI:
    def __init__(self, base_url, api_key):
        self.base_url = base_url
        self.api_key = api_key

    def fetch_data(self, city, start_date, end_date):
        url = f"{self.base_url}/data/{city}/{start_date}/{end_date}?api_key={self.api_key}"
        response = requests.get(url)
        if response.status_code == 200:
            return json.loads(response.content.decode('utf-8'))
        else:
            logging.error(f"Failed to fetch data for {city} from {start_date} to {end_date}. Status code: {response.status_code}")
            return None

class WeatherAnalyzer:
    def __init__(self):
        self.cached_data = {}

    def analyze_weather(self, city, start_date, end_date):
        if (city, start_date, end_date) in self.cached_data:
            data = self.cached_data[(city, start_date, end_date)]
        else:
            api_key = os.environ.get("WEATHER_API_KEY")
            base_url = "https://api.openweathermap.org/data/2.5"
            weather_api = WeatherAPI(base_url, api_key)
            data = weather_api.fetch_data(city, start_date, end_date)
            self.cached_data[(city, start_date, end_date)] = data
        if data:
            avg_temp = sum([d["main"]["temp"] for d in data]) / len(data)
            avg_humidity = sum([d["main"]["humidity"] for d in data]) / len(data)
            avg_wind_speed = sum([d["wind"]["speed"] for d in data]) / len(data)
            return {"avg_temp": avg_temp, "avg_humidity": avg_humidity, "avg_wind_speed": avg_wind_speed}

class RateLimiter:
    def __init__(self, max_calls_per_second):
        self.max_calls_per_second = max_calls_per_second
        self.last_call_time = datetime.now()

    def should_wait(self):
        current_time = datetime.now()
        time_diff = (current_time - self.last_call_time).total_seconds()
        if time_diff < 1 / self.max_calls_per_second:
            return True
        else:
            return False

    def wait(self):
        max_time_between_calls = 1 / self.max_calls_per_second
        while datetime.now() - self.last_call_time < timedelta(seconds=max_time_between_calls):
            pass

class WeatherAPIManager:
    def __init__(self, api_keys):
        self.api_keys = api_keys
        self.active_api_key_index = 0

    def get_active_api_key(self):
        return self.api_keys[self.active_api_key_index]

    def increment_active_api_key_index(self):
        self.active_api_key_index += 1
        if self.active_api_key_index >= len(self.api_keys):
            self.active_api_key_index = 0

class Config:
    def __init__(self, file_path):
        self.config = json.load(open(file_path))

def main():
    config_file_path = "config.json"
    api_keys = [os.environ.get(f"WEATHER_API_KEY_{i}") for i in range(3)]
    weather_api_manager = WeatherAPIManager(api_keys)
    rate_limiter = RateLimiter(max_calls_per_second=10)
    weather_analyzer = WeatherAnalyzer()

    # Fetch data and analyze
    for city in ["New York", "London", "Paris"]:
        start_date = datetime.now() - timedelta(days=30)
        end_date = datetime.now()
        while True:
            if rate_limiter.should_wait():
                rate_limiter.wait()
            data = weather_api_manager.get_active_api_key().fetch_data(city, start_date, end_date)
            if data is None:
                weather_api_manager.increment_active_api_key_index()
                continue
            analysis_results = weather_analyzer.analyze_weather(city, start_date, end_date)
            print(f"Weather pattern for {city} from {start_date} to {end_date}:")
            print(analysis_results)
            break

if __name__ == "__main__":
    main()

