public class ImageMetadataExtractor {

    private static final int MAX_THREADS = 10; // configurable limit for parallel processing
    private static final String EXCLUSION_PATTERN = "*.mov|*.avi"; // default exclusion pattern
    private static final int RATE_LIMIT = 5; // rate limiting threshold in seconds

    public void extractMetadata(String directoryPath, boolean excludeMovies) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);

        try (File directory = new File(directoryPath)) {
            if (!directory.isDirectory()) {
                throw new Exception("Invalid directory path");
            }

            List<File> files = new ArrayList<>();
            for (File file : directory.listFiles()) {
                if (file.isFile() && !isExcluded(file.getName(), excludeMovies)) {
                    files.add(file);
                }
            }

            executor.submit(() -> {
                try {
                    for (File file : files) {
                        extractMetadata(file);
                    }
                } catch (Exception e) {
                    logger.error("Error processing image files", e);
                }
            });

            // implement rate limiting and database connection pool
        } finally {
            executor.shutdown();
        }
    }

    private void extractMetadata(File file) throws Exception {
        // perform metadata extraction and validation using the external API
        String metadata = extract(file);

        if (metadata != null) {
            // cache the extracted metadata for future use
            CacheManager.put(file.getAbsolutePath(), metadata);
        } else {
            // report error to the log and optionally delete the file
            logger.error("Failed to extract metadata from " + file.getAbsolutePath());
            if (deleteOnFailure) {
                file.delete();
            }
        }
    }

    private String extract(File file) throws Exception {
        // implement real-time metadata extraction logic using an external API or library
    }

    private boolean isExcluded(String fileName, boolean excludeMovies) {
        return fileName.matches(EXCLUSION_PATTERN);
    }

    private static Logger logger = LoggerFactory.getLogger(ImageMetadataExtractor.class);

    public interface CacheManager {
        void put(String key, String value);
    }
}
