// Define a function to parse TIFF image file
const CFunction = `#include <tiff.h>
#include <stdio.h>

struct tiff_info {
  int bitsPerSample;
  int samplesPerPixel;
  int extraSamples;
};

struct tiff_info parseTIFF(const char *filePath) {
  struct tiff_info info;
  FILE *file = fopen(filePath, "rb");
  if (file == NULL) {
    return (struct tiff_info){-1, -1, -1};
  }

  // Read TIFF header
  uint32_t tiffHeader[2];
  fread(tiffHeader, sizeof(uint32_t), 2, file);

  info.bitsPerSample = tiffHeader[0];
  info.samplesPerPixel = tiffHeader[1];

  // Read extra samples
  uint16_t extraSamples;
  fread(&extraSamples, sizeof(uint16_t), 1, file);

  fclose(file);
  return info;
}`;

// Define a C wrapper function to call the C function from Node.js
const { bindings } = require('bindings')('tiff_parser');

module.exports = {
  loadModules,
  executeModules,
  parseTIFF: bindings.parseTIFF
};
