        private static readonly string _configFile = Environment.GetEnvironmentVariable("CONFIG_FILE_PATH") ?? "config.xml";
        private static ConfigSettings _config;

        public static byte[] DecryptCiphertext(byte[] ciphertext, byte[] encryptionKey, byte[] initializationVector)
        {
            if (ciphertext == null || encryptionKey == null || initializationVector == null)
                throw new ArgumentNullException("One or more arguments are null");

            using (var aes = Aes.Create())
            {
                aes.Key = encryptionKey;
                aes.IV = initializationVector;

                using (var encryptor = aes.CreateDecryptor())
                {
                    return decryptStream(encryptor, ciphertext);
                }
            }
        }

        private static byte[] decryptStream(ICryptoTransform transform, byte[] buffer)
        {
            var ms = new MemoryStream(buffer);
            using (var cs = new CryptoStream(ms, transform, CryptoStreamMode.Read))
            {
                var decryptedBytes = new byte[buffer.Length];
                cs.Read(decryptedBytes, 0, buffer.Length);
                return decryptedBytes;
            }
        }

        public static void LoadConfig()
        {
            try
            {
                using (var reader = XmlSerializer.Create(_configFile, typeof(ConfigSettings)).Read())
                {
                    _config = reader.Deserialize<ConfigSettings>();
                }
            }
            catch (Exception ex)
            {
                // Log error or warning with external logging system
