#include <random>
#include <json/json.h>
#include <thread>
#include <mutex>

namespace RandomUtils {
    class RandomGenerator {
    public:
        RandomGenerator(const Json::Value& config) {
            static std::once_flag seedFlag;
            std::call_once(seedFlag, [&] {
                // Initialize the random number generator
                mt_ = new std::mt19937_64(time(0));
            });
            if (config.isMember("seed")) {
                *mt_ = std::stoi(config["seed"].asString());
            }
        }
        ~RandomGenerator() {
            delete mt_;
        }

        int uniform(int min, int max) {
            return dist_(min, max);
        }

        double uniform(double min, double max) {
            return dist_(min, max);
        }

        double normal(double mean, double std_dev) {
            return norm_dist_(mean, std_dev);
        }

        double exponential(double rate) {
            return exp_dist_(rate);
        }

        int poisson(double lambda) {
            return pois_dist_(lambda);
        }

        double geometric(double p) {
            return geo_dist_(p);
        }

    private:
        std::unique_ptr<std::mt19937_64> mt_;
        std::random_device rd;
        std::mt19937_64 eng(rd());
        std::uniform_real_distribution<double> dist_(0.0, 1.0);

        double norm_dist_(double mean, double std_dev) {
            return mean + (std_dev * (dist_(mean, std_dev)));
        }

        double exp_dist_(double rate) {
            double u = dist_();
            return -log(u) / rate;
        }

        int pois_dist_(double lambda) {
            double t = exp(-lambda);
            int k = 0;
            double p = 1.0;

            for (int i = 0; i < INT_MAX && p > t; ++i, p *= (lambda / (k + 1)), ++k);

            return k;
        }

        double geo_dist_(double p) {
            return -log(1.0 - dist_()) / log(p);
        }
    };
}

