<?php

function updateClinicStatus($clinicId, $newStatus, $ipAddress) {
    // Validate clinic ID
    if (!is_numeric($clinicId)) {
        logError("Invalid clinic ID: $clinicId");
        return [];
    }

    // Start transaction
    $db = dbConnect();
    $db->beginTransaction();

    try {
        // Update clinic status
        $query = "UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE id = ?";
        $stmt = $db->prepare($query);
        $stmt->execute([$newStatus, $ipAddress, date("Y-m-d H:i:s"), $clinicId]);

        // Update log
        $logQuery = "INSERT INTO clinic_logs (clinic_id, status, ip_address, timestamp) VALUES (?, ?, ?, ?)";
        $logStmt = $db->prepare($logQuery);
        $logStmt->execute([$clinicId, $newStatus, $ipAddress, date("Y-m-d H:i:s")]);

        // Commit transaction
        $db->commit();
    } catch (Exception $e) {
        logError("Error updating clinic status: " . $e->getMessage());
        $db->rollBack();
        return [];
    } finally {
        // Close database connection
        $db = null;
    }
}

function dbConnect() {
    // Connect to database
    $dsn = 'mysql:host=localhost;dbname=clinics';
    $username = 'root';
    $password = '';

    try {
        $db = new PDO($dsn, $username, $password);
        $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        return $db;
    } catch (PDOException $e) {
        logError("Database connection failed: " . $e->getMessage());
        return null;
    }
}

