import boto3
from botocore.exceptions import ClientError

def get_function_metadata(function_id):
    cloudformation = boto3.client('cloudformation')
    try:
        response = cloudformation.describe_stack_resources(StackName='serverless-functions', LogicalResourceId=function_id)
        return response['StackResourceSummaries'][0]['LastUpdatedTimestamp']
    except ClientError as e:
        print(f"Failed to retrieve metadata for function {function_id}: {e}")
        return None

def update_function(function_id, request_body, version=None):
    if not version:
        version = 1
    cloudformation = boto3.client('cloudformation')
    try:
        response = cloudformation.update_stack(StackName='serverless-functions', TemplateBody=request_body, Capabilities=['CAPABILITY_IAM'], StackVersion=version)
        return response['StackId']
    except ClientError as e:
        if e.response['ResponseMetadata']['HTTPStatusCode'] == 412:
            raise Exception(f"Precondition Failed: Function {function_id} has been modified. Please check the version number.")
        else:
            print(f"Failed to update function {function_id}: {e}")
            return None

def delete_function(function_id, request_body):
    cloudformation = boto3.client('cloudformation')
    try:
        response = cloudformation.delete_stack(StackName='serverless-functions', StackVersion=1)
        return response['StackId']
    except ClientError as e:
        if e.response['ResponseMetadata']['HTTPStatusCode'] == 412:
            raise Exception(f"Precondition Failed: Function {function_id} has been modified. Please check the version number.")
        else:
            print(f"Failed to delete function {function_id}: {e}")
            return None

def main(event):
    if event['httpMethod'] == 'PUT':
        # Update function
        try:
            metadata = get_function_metadata(event['pathParameters']['functionId'])
            timestamp = int(metadata.get('LastUpdatedTimestamp', 0))
            if 'X-Last-Deployment-Timestamp' in event['headers']:
                last_deployed_timestamp = int(event['headers']['X-Last-Deployment-Timestamp'])
                if timestamp > last_deployed_timestamp:
                    raise Exception("Conflict: Function has been deployed after the specified timestamp.")
            return update_function(event['pathParameters']['functionId'], event['body'], version=event.get('version', 1))
        except Exception as e:
            print(f"Error updating function {event['pathParameters']['functionId']}: {e}")
            return {'statusCode': 400, 'body': str(e)}
    elif event['httpMethod'] == 'DELETE':
        # Delete function
        try:
            metadata = get_function_metadata(event['pathParameters']['functionId'])
            timestamp = int(metadata.get('LastUpdatedTimestamp', 0))
            if 'X-Last-Deployment-Timestamp' in event['headers']:
                last_deployed_timestamp = int(event['headers']['X-Last-Deployment-Timestamp'])
                if timestamp < last_deployed_timestamp:
                    raise Exception("Precondition Failed: Function has been modified since the last deployment.")
            return delete_function(event['pathParameters']['functionId'], event.get('body', '{}'))
        except Exception as e:
            print(f"Error deleting function {event['pathParameters']['functionId']}: {e}")
            return {'statusCode': 400, 'body': str(e)}
    else:
        # Invalid request method
        return {'statusCode': 405, 'body': "Method not allowed."}
