**JavaScript: Buffer Merging Function**
```javascript
const { Buffer } = require('buffer');

function mergeBuffers(chunks, byteCount) {
  const result = Buffer.alloc(0);
  let totalBytes = 0;

  chunks.forEach((chunk) => {
    if (chunk.length === 0) return; // ignore empty chunks

    if (totalBytes + chunk.length > byteCount) {
      throw new Error(`Insufficient data to fulfill the request`);
    }

    result = Buffer.concat([result, chunk]);
    totalBytes += chunk.length;

    if (totalBytes >= byteCount) break;
  });

  if (totalBytes < byteCount) {
    throw new Error(`Not enough data available`);
  }

  return result.slice(0, byteCount);
}

// Example usage:
const chunk1 = Buffer.from([1, 2, 3]);
const chunk2 = Buffer.from([4, 5, 6]);

mergeBuffers([chunk1, chunk2], 6); // returns the first 6 bytes of the merged buffer
