        printf("Usage: %s <input_file> <output_file> <rules> <log_files_dir>\n", argv[0]);
        return 1;
    }

    int input_fd = open(argv[1], O_RDONLY);
    if (input_fd < 0) {
        perror("open");
        return 2;
    }

    int output_fd = open(argv[2], O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);
    if (output_fd < 0) {
        perror("open");
        close(input_fd);
        return 3;
    }

    char rules[RULES_MAX_LENGTH];
    strncpy(rules, argv[3], RULES_MAX_LENGTH - 1);
    rules[RULES_MAX_LENGTH - 1] = '\0';

    DIR* dir = opendir(LOG_FILES_DIR);
    if (dir == NULL) {
        perror("opendir");
        close(input_fd);
        close(output_fd);
        return 4;
    }

    pthread_t threads[10];
    ThreadData td[10];
    int thread_count = 0;

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char file_path[256];
        sprintf(file_path, "%s/%s", LOG_FILES_DIR, entry->d_name);

        td[thread_count].fd = open(file_path, O_RDONLY);
        if (td[thread_count].fd < 0) {
            perror("open");
            closedir(dir);
            close(input_fd);
            close(output_fd);
            return 5;
        }

        td[thread_count].buffer = malloc(BUFFER_SIZE);
        pthread_create(&threads[thread_count], NULL, parse_file, &td[thread_count]);
        thread_count++;
    }

    closedir(dir);

    // Wait for all threads to finish
    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
        close(td[i].fd);
        free(td[i].buffer);
    }

    return 0;
}
