        return jsonify({'message': 'Tenant not found'}), 404

    rbac = tenants[tenant_id]
    user_id = int(request.environ.get('user_id'))
    if not rbac.check_access(user_id, 'admin'):
        return jsonify({'message': 'Access denied'}), 403
    return jsonify({'resources': ['resource-1', 'resource-2']})

