```rust
use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::exit;

struct FileManagementUtility {
    work_dir: PathBuf,
}

impl FileManagementUtility {
    fn new() -> Self {
        let mut env_var = env::var("WORK_DIR").unwrap_or_else(|_| {
            // Create a temporary directory under /tmp
            let temp_dir = dirs::temp_dir().unwrap();
            let dir_name = "ci-pipeline-temp";
            let work_dir = temp_dir.join(dir_name);
            fs::create_dir_all(&work_dir).unwrap();
            env_var = format!("{}{}", "/tmp", &dir_name);
            env::set_var("WORK_DIR", &env_var);
        });

        FileManagementUtility {
            work_dir: PathBuf::from(env_var.clone()),
        }
    }

    fn manage_directory(&self) -> Result<(), Box<dyn std::error::Error>> {
        // Clean up the working directory
        if self.work_dir.exists() {
            fs::remove_dir_all(&self.work_dir)?;
        } else {
            // Create a new temporary directory under /tmp
            let temp_dir = dirs::temp_dir().unwrap();
            let dir_name = "ci-pipeline-temp";
            let work_dir = temp_dir.join(dir_name);
            fs::create_dir_all(&work_dir)?;
            env::set_var("WORK_DIR", &format!("{}{}", "/tmp", &dir_name));
        }

        Ok(())
    }
}

fn main() {
    let file_mgmt_util = FileManagementUtility::new();
    if let Err(err) = file_mgmt_util.manage_directory() {
        eprintln!("Error: {}", err);
        exit(1);
    } else {
        println!("Working directory managed successfully!");
    }
}
