function mergeDataChunks(chunkList, bytesToCopy) {
  const buffer = Buffer.alloc(0);
  let totalCopied = 0;

  for (const chunk of chunkList) {
    if (!Buffer.isBuffer(chunk)) throw new Error('Invalid data type');

    if (chunk.length !== Math.ceil(bytesToCopy / 4) * 4)
      throw new Error('Inconsistent chunk size');

    let chunkCopied = 0;
    for (let i = 0; i < chunk.length && totalCopied < bytesToCopy; i++) {
      const byte = chunk.readUInt8(i);
      buffer.writeUInt8(byte, totalCopied++);
    }

    if (totalCopied >= bytesToCopy) break;
  }

  if (totalCopied !== bytesToCopy)
    throw new Error('Insufficient data available');

  return buffer.slice(0, bytesToCopy);
}

