function collectDataAndSaveToMongo(stream, databaseUrl, collectionName) {
  const MongoClient = require('mongodb').MongoClient;
  const fs = require('fs');
  let streamPaused = false;
  let buffer = [];

  async function handleStream() {
    try {
      const client = await MongoClient.connect(databaseUrl);
      const db = client.db();
      const collection = db.collection(collectionName);

      while (!stream.atEnd()) {
        if (streamPaused) {
          break;
        }

        const chunk = await stream.read();
        buffer.push(chunk);
        if (buffer.length >= 1024 * 1024) { // 1MB chunk
          await saveBufferToMongo(buffer, collection);
          buffer = [];
        }
      }

      if (buffer.length > 0) {
        await saveBufferToMongo(buffer, collection);
      }

      client.close();
    } catch (err) {
      console.error('Error handling stream:', err);
      throw err;
    }
  }

  async function pauseStream() {
    streamPaused = true;
    return new Promise(resolve => setTimeout(() => resolve(), 100));
  }

  async function resumeStream() {
    streamPaused = false;
  }

  async function saveBufferToMongo(buffer, collection) {
    try {
      const documents = buffer.map(chunk => Buffer.from(chunk).toString());
      await collection.insertMany(documents.map(document => ({ data: document })));
    } catch (err) {
      console.error('Error saving buffer to MongoDB:', err);
      throw err;
    }
  }

  return { handleStream, pauseStream, resumeStream };
}
