void runModuleTests(const std::string& moduleLabel, const std::vector<testFunction>& testSuite, const std::string& loggingLevel, int cooldown, ResourceManager& resourceManager) {
    // Initialize the mocking library
    auto mockLibrary = initializeMockingLibrary(resourceManager);

    for (const auto& test : testSuite) {
        // Reset and clean up the mocking library before each test
        resetMockingLibrary(mockLibrary, resourceManager);

        // Run the test with a separate thread to prevent interference between tests
        std::thread testThread([test, &loggingLevel] {
            try {
                test("Test " + moduleLabel, [](const std::string& label, auto attackFunction) {
                    // Simulate the attack mechanism and verify its behavior
                    for (int i = 0; i < 10; ++i) {
                        if (!attackFunction()) {
                            throw std::runtime_error("Attack failed");
                        }
                        if (i % cooldown == 0) {
                            // Print the selected attack number to the console
                            std::cout << "Selected attack: " << i << "\n";
                        }
                    }
                });
            } catch (const std::exception& e) {
                // Log and report the test failure with detailed error messages
                std::cerr << "Test failed: " << e.what() << '\n';
            }
        });

        // Wait for the test thread to finish before moving on to the next test
        testThread.join();
    }

    // Clean up resources after all tests have run
    cleanupResources(mockLibrary, resourceManager);
}
