        var salt = GenerateSalt();
        var passwordWithSalt = $"{salt}{plainTextPassword}";
        var hashedPassword = Convert.ToBase64String(sha256.ComputeHash(Encoding.UTF8.GetBytes(passwordWithSalt)));
        return hashedPassword;
    }

    private string Sha256Verify(string hashedPassword, string plainTextPassword)
