        using var sha256 = SHA256.Create();
        var salt = GetSaltFromHashedPassword(hashedPassword);
        var passwordWithSalt = $"{salt}{plainTextPassword}";
        var computedHash = Convert.ToBase64String(sha256.ComputeHash(Encoding.UTF8.GetBytes(passwordWithSalt)));
        return hashedPassword == computedHash;
    }

    private string BcryptHash(string plainTextPassword)
    {
