#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <pthread.h>

#define MAX_THREADS 10
#define LOG_FILE "logs.txt"
#define CFG_FILE "config.ini"

typedef struct {
    char url[256];
    int expected_size;
    int timeout;
} metadata_t;

void* download_file(void* arg) {
    metadata_t* metadata = (metadata_t*)arg;
    CURL* curl;
    CURLcode res;
    FILE* file;

    // Initialize curl
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        return NULL;
    }

    // Set URL, timeout and expected size from metadata
    curl_easy_setopt(curl, CURLOPT_URL, metadata->url);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, (long)metadata->timeout);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &file);

    // Perform the request and cleanup
    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    }
    curl_easy_cleanup(curl);

    return NULL;
}

int main(int argc, char* argv[]) {
    int num_threads = 1;
    char* output_dir = ".";
    FILE* config_file = fopen(CFG_FILE, "r");
    if (config_file) {
        // Read configuration file
        fclose(config_file);
    }

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 || strcmp(argv[i], "--threads") == 0) {
            num_threads = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-o") == 0 || strcmp(argv[i], "--output") == 0) {
            output_dir = argv[++i];
        }
    }

    // Initialize thread pool
    pthread_t threads[MAX_THREADS];
    int i, rc;
    for (i = 0; i < num_threads; i++) {
        rc = pthread_create(&threads[i], NULL, download_file, (void*)metadata);
        if (rc) {
            fprintf(stderr, "Error creating thread %d: %s\n", i, strerror(rc));
            return -1;
        }
    }

    // Wait for threads to finish
    for (i = 0; i < num_threads; i++) {
        rc = pthread_join(threads[i], NULL);
        if (rc) {
            fprintf(stderr, "Error joining thread %d: %s\n", i, strerror(rc));
            return -1;
        }
    }

    return 0;
}

