```javascript
class ScriptLoader {
  constructor(config) {
    this.config = config;
    this.scripts = [];
    this.loadQueue = [];
    this.errorHandlers = {};
    this.log = console.log.bind(console);
  }

  addScript(script, options = {}) {
    const { src, priority, fallback } = options;
    if (!src) throw new Error('No script source provided');
    this.scripts.push({ src, priority, fallback });
  }

  setLoader(options = {}) {
    const { async, lazy, cache } = options;
    this.async = async;
    this.lazy = lazy;
    this.cache = cache;
  }

  setErrorHandler(scriptName, handler) {
    this.errorHandlers[scriptName] = handler;
  }

  load() {
    if (!this.config.loadOnReady) return;
    const queue = [...this.scripts];
    let loadCount = 0;

    function loadNextScript() {
      if (loadCount >= queue.length) return;

      const script = queue[loadCount++];
      this.loadScript(script.src, script.priority);
    }

    loadNextScript.bind(this);

    while (queue.length > 0) {
      loadNextScript();
    }
  }

  loadScript(src, priority) {
    if (this.cache && this.cache[src]) return;

    const script = document.createElement('script');
    script.src = src;
    script.priority = priority;

    if (!this.async) {
      document.body.appendChild(script);
    } else {
      script.onload = () => {
        this.loadScriptComplete(src, priority);
      };
      script.onerror = (error) => {
        this.loadScriptError(src, error);
      };

      setTimeout(() => {
        document.body.appendChild(script);
      }, 0);
    }
  }

  loadScriptComplete(src, priority) {
    const { fallback } = this.scripts.find((script) => script.src === src);
    if (fallback) {
      // Execute fallback script or default behavior
      console.log('Fallback script executed: ' + fallback);
    }
  }

  loadScriptError(src, error) {
    if (!this.config.errorHandler) return;

    const handler = this.errorHandlers[src];
    if (handler) handler(error);
    else this.config.errorHandler(error);
  }
}
