const fs = require('fs');
const path = require('path');
const mongoose = require('mongoose');
const { promisify } = require('util');

async function collectAndSaveData(stream, databaseUri) {
  const protocolsDir = 'protocols';
  const protocolConfigFile = 'protocol-config.json';

  // Load available protocols
  let protocols = [];
  try {
    fs.readdirSync(protocolsDir).forEach(file => {
      if (file.endsWith('.js')) {
        const protocolName = file.replace('.js', '');
        protocols.push({
          name: protocolName,
          implementation: require(`./${protocolsDir}/${protocolName}`),
          description: 'Description for ' + protocolName,
          supportedFeatures: ['feature1', 'feature2']
        });
      }
    });

    // Load protocol configurations from JSON file
    const config = await promisify(fs.readFile)(path.join(__dirname, '..', protocolConfigFile));
    protocols.forEach((protocol) => {
      try {
        const configData = JSON.parse(config);
        if (configData[protocol.name]) {
          protocol.description = configData[protocol.name].description;
          protocol.supportedFeatures = configData[protocol.name].supportedFeatures;
        }
      } catch (error) {
        console.error('Error parsing protocol configuration: ', error);
      }
    });

    // Establish database connection
    mongoose.connect(databaseUri, { useNewUrlParser: true, useUnifiedTopology: true });
    const db = mongoose.connection;

    // Define schema for data storage
    let dataSchema;
    if (stream instanceof Buffer) {
      dataSchema = new mongoose.Schema({
        data: Buffer,
        protocol: String,
        timestamp: Date
      });
    } else {
      dataSchema = new mongoose.Schema({
        data: stream,
        protocol: String,
        timestamp: Date
      });
    }

    // Create model for data storage
    const DataModel = mongoose.model('Data', dataSchema);

    // Initialize paused state and offset
    let paused = false;
    let offset = 0;

    // Define callback function for handling data processing
    async function processChunk(chunk) {
      try {
        if (paused) {
          offset += chunk.length;
          return;
        }

        const data = new DataModel({
          data: chunk,
          protocol: stream.protocol,
          timestamp: Date.now()
        });
        await data.save();
      } catch (error) {
        console.error('Error processing data chunk: ', error);
      }
    }

    // Define callback function for handling errors during data processing
    async function onError(error) {
      console.error('Error occurred during data processing: ', error);

      if (!paused && error instanceof Error && error.message.includes('ETIMEDOUT')) {
        paused = true;
      } else {
        try {
          await mongoose.disconnect();
        } catch (disconnectError) {
          console.error('Error disconnecting from database: ', disconnectError);
        }
      }
    }

    // Read and process data stream in chunks
    let chunkSize = 1024 * 1024; // 1MB chunks
    let chunk;
    while ((chunk = await promisify(stream.read.bind(stream))(chunkSize)) !== null) {
      processChunk(chunk);

      if (stream.bytesAvailable() < chunkSize && !paused) {
        paused = true;
      }
    }

    // Resume data processing when interrupted
    process.on('resume', () => {
      paused = false;
    });

    // Handle database connection issues and reconnect when necessary
    db.on('disconnected', async () => {
      try {
        await mongoose.connect(databaseUri, { useNewUrlParser: true, useUnifiedTopology: true });
      } catch (reconnectError) {
        console.error('Error reconnecting to database: ', reconnectError);
      }
    });

    // Perform any necessary cleanup or logging before exiting
    process.on('exit', () => {
      try {
        await mongoose.disconnect();
      } catch (disconnectError) {
        console.error('Error disconnecting from database: ', disconnectError);
      }
    });
}

module.exports = collectAndSaveData;
