```c
/**
 * @brief Create a new dynamic list of tasks based on priority and deadline.
 * 
 * @param tasks Pointer to an array of Task structs.
 * @param numTasks Integer representing the number of tasks in the input array.
 * @param minPriority Priority level (inclusive) for task selection.
 * @param deadline Deadline timestamp for task selection.
 * 
 * @return A pointer to a newly created task list meeting the specified priority and deadline criteria. If insufficient memory, returns NULL.
 */
task_list* createTaskList(Task* tasks, int numTasks, int minPriority, long deadline) {
    // Initialize pointers
    task_list* head = NULL;
    task_list* current = NULL;

    for (int i = 0; i < numTasks; i++) {
        if (tasks[i].priority >= minPriority && tasks[i].deadline > deadline) {
            task_list* newTask = (task_list*)malloc(sizeof(task_list));
            if (!newTask) return NULL;
            newTask->task = &tasks[i];
            newTask->next = NULL;

            // Update the last task in the list to point to the newly created task
            if (head == NULL) {
                head = current = newTask;
            } else {
                current->next = newTask;
                current = newTask;
            }
        }
    }

    return head;
}
