// Constants and helper functions
const COMPILATION_TIME_OUT: u64 = 30000; // 30 seconds

fn compile_file(file_path: &Path) -> Result<(String, String), Box<dyn std::error::Error>> {
    let output = Command::new("rustc")
        .arg("-o")
        .arg("example")
        .arg(file_path)
        .output()
        .expect("Failed to execute process");

    if !output.status().success() {
        error!("Compilation failed: {}", file_path.display());
    }

    let contents = String::from_utf8_lossy(&output.stdout);
    Ok((contents.to_string(), output.status().to_string()))
}

