class SessionPool {
public:
    std::unordered_map<std::string, int> sessionCount;
    std::mutex mtx;
    std::condition_variable cv;

    void addSession(const std::string& ip) {
        std::unique_lock<std::mutex> lock(mtx);
        if (!sessionCount.count(ip)) {
            sessionCount[ip] = 0;
        }
        sessionCount[ip]++;
        cv.notify_all();
    }

    int getSessions(const std::string& ip) {
        std::unique_lock<std::mutex> lock(mtx);
        return sessionCount.count(ip) ? sessionCount[ip] : 0;
    }

    void removeSession(const std::string& ip) {
        std::unique_lock<std::mutex> lock(mtx);
        if (sessionCount.count(ip)) {
            sessionCount[ip]--;
            cv.notify_all();
        }
    }

    bool hasAvailableSession(const std::string& ip, int required) {
        std::unique_lock<std::mutex> lock(mtx);
        return sessionCount.count(ip) && sessionCount[ip] >= required;
    }
};

