class ClinicManager {
    private $registry;
    private $loggingService;

    public function __construct() {
        $this->registry = [];
        $this->loggingService = new \Logger();
    }

    public function addFactoryFunction($id, callable $factory) {
        $this->registry[$id] = $factory;
    }

    public function createClinicInstanceFromJson($json) {
        $data = json_decode($json, true);
        if (!isset($data['type'])) {
            throw new \Exception('Invalid clinic data');
        }
        $id = $data['id'];
        $factory = $this->registry[$id];
        return $factory($data);
    }

    public function updateClinicStatus(int $clinicId, string $status) {
        try {
            // Validate clinic ID
            if (!isset($this->registry[$clinicId])) {
                throw new \Exception('Invalid clinic ID');
            }

            // Get the factory function for the given clinic ID
            $factory = $this->registry[$clinicId];

            // Start transaction
            $transactionStarted = false;
            $error = null;

            try {
                // Create a database connection pool and update the status in all databases
                $connections = [];
                foreach (['db1', 'db2'] as $database) {
                    $connection = new \PDO("mysql:host=localhost;dbname=$database", 'username', 'password');
                    $connections[] = $connection;
                    // Update the clinic status in each database
                    $statement = $connection->prepare("UPDATE clinics SET status = :status WHERE id = :id");
                    $statement->execute([':status' => $status, ':id' => $clinicId]);
                }

                // Commit transaction
                $transactionStarted = true;
            } catch (\PDOException $e) {
                $error = $e;
            } finally {
                if (!$transactionStarted) {
                    // Roll back the transaction if an error occurred
                    foreach ($connections as $connection) {
                        $connection->rollBack();
                    }
                }
            }

            // Log any errors or exceptions to a centralized logging service
            if ($error) {
                try {
                    $this->loggingService->logError($error);
                } catch (\Exception $e) {
                    // Log the error in case of another exception
                    $this->loggingService->logError($e);
                }
            }

            return true;
        } catch (\Exception $e) {
            // Log any exceptions to a centralized logging service
            try {
                $this->loggingService->logError($e);
            } catch (\Exception $ee) {
                // Handle the error in case of another exception
                echo "Error occurred: $e";
            }
        }
    }

    public function convertClinicDataToJson(Clinic $clinic) {
        return json_encode([
            'id' => $clinic->getId(),
            'type' => get_class($clinic),
            'data' => $clinic->getJsonData()
        ]);
    }
}
