Here is the code block for the JavaScript function that dynamically renders a footer of a web page using an array of script objects:

```javascript
function renderFooter(scripts, apiEndpoint, cacheExpirationTime) {
  const cache = {};
  const loadingSpinner = document.getElementById('loading-spinner');

  async function fetchScript(script) {
    if (script.src) {
      try {
        const response = await fetch(script.src);
        const scriptText = await response.text();
        script.code = scriptText;
      } catch (error) {
        console.error(`Error fetching script ${script.src}:`, error);
      }
    }
  }

  async function renderScripts(scripts) {
    const renderedScripts = [];

    for (const script of scripts) {
      if (!script.code) {
        await fetchScript(script);
      }

      const scriptTag = document.createElement('script');
      scriptTag.key = `script-${script.type || ''}`;
      scriptTag.innerHTML = script.code;
      renderedScripts.push(scriptTag);
    }

    return renderedScripts.join('');
  }

  async function renderFooterHtml() {
    loadingSpinner.style.display = 'block';
    const footerHtml = await renderScripts(scripts);
    document.getElementById('footer').innerHTML = footerHtml;
    loadingSpinner.style.display = 'none';
  }

  renderFooterHtml();
}
```

