// Script manager module
const scriptManager = {
  // Cache for fetched scripts
  cache: {},

  // Fetch scripts from API endpoint (async)
  async fetchScripts(apiEndpoint) {
    try {
      const response = await fetch(apiEndpoint);
      if (!response.ok) {
        console.error('Failed to fetch scripts:', response.status);
        return [];
      }
      const scripts = await response.json();
      return scripts;
    } catch (error) {
      console.error('Error fetching scripts:', error);
      return [];
    }
  },

  // Manage cache (async)
  async manageCache(scripts, timestamp) {
    this.cache = {};
    for (const script of scripts) {
      if (!script.timestamp || script.timestamp <= timestamp) continue;
      const key = `script:${script.id}`;
      this.cache[key] = script.code;
    }
  },

  // Render script tags from cache or fetch new ones
  renderScripts(scripts, callback) {
    const renderedScripts = [];
    for (const script of scripts) {
      if (!script.type) continue;
      const key = `script:${script.id}`;
      if (this.cache[key]) {
        // Script cached, use cached code
        renderedScripts.push(`<script id="${key}" type="${script.type}">${this.cache[key]}</script>`);
      } else {
        // Fetch new script
        this.fetchScripts(script.src).then((newScript) => {
          const key = `script:${script.id}`;
          this.cache[key] = newScript.code;
          renderedScripts.push(`<script id="${key}" type="${script.type}">${newScript.code}</script>`);
          callback();
        }).catch((error) => {
          console.error('Error fetching script:', error);
        });
      }
    }
    return renderedScripts.join('');
  },
};

// Script rendering function
function renderFooter(scripts, loadingSpinnerHTML = '') {
  if (!scripts.length) return loadingSpinnerHTML;

  const footerHTML = '<footer>';
  for (const script of scripts) {
    // Render script tag with unique key and code
    const renderedScript = scriptManager.renderScripts([script], () => {});
    footerHTML += renderedScript;
  }
  footerHTML += '</footer>';
  return loadingSpinnerHTML + footerHTML;
}

// Example usage:
