using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

public class FileMetadataProcessor
{
    private string _directoryPath;
    private long _minFileSizeThreshold;
    private long _maxFileSizeThreshold;
    private readonly ILogger _logger;

    public FileMetadataProcessor(string directoryPath, long minFileSizeThreshold, long maxFileSizeThreshold, ILogger logger)
    {
        _directoryPath = directoryPath;
        _minFileSizeThreshold = minFileSizeThreshold;
        _maxFileSizeThreshold = maxFileSizeThreshold;
        _logger = logger;
    }

    public IEnumerable<FileMetadata> ProcessFileMetadata(Func<FileInfo, bool> filterCallback, int batchSize = 1000)
    {
        var fileMetadataList = new List<FileMetadata>();

        try
        {
            foreach (string file in Directory.GetFiles(_directoryPath, "*", SearchOption.AllDirectories))
            {
                FileInfo fileInfo = new FileInfo(file);

                if (_minFileSizeThreshold <= fileInfo.Length && fileInfo.Length <= _maxFileSizeThreshold)
                {
                    FileMetadata metadata = new FileMetadata
                    {
                        Path = file,
                        Size = fileInfo.Length / 1024,
                        CreationDate = fileInfo.CreationTime,
                        LastModified = fileInfo.LastAccessTime
                    };

                    if (filterCallback != null && !filterCallback(metadata))
                    {
                        continue;
                    }

                    fileMetadataList.Add(metadata);
                }

                if (fileMetadataList.Count >= batchSize)
                {
                    yield return new FileMetadataCollection(fileMetadataList);
                    fileMetadataList.Clear();
                }
            }

            if (fileMetadataList.Any())
            {
                yield return new FileMetadataCollection(fileMetadataList);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing file metadata");
        }
    }

    public override string ToString()
    {
        return $"Size Range: [{_minFileSizeThreshold}KB, {_maxFileSizeThreshold}KB]";
    }

    public void ValidateFileSizeRange()
    {
        if (_minFileSizeThreshold > _maxFileSizeThreshold)
        {
            throw new ArgumentException("Minimum file size threshold cannot be greater than maximum file size threshold.");
        }
    }
}

public class FileMetadata
{
    public string Path { get; set; }
    public long Size { get; set; }
    public DateTime CreationDate { get; set; }
    public DateTime LastModified { get; set; }
}

public class FileMetadataCollection : IEnumerable<FileMetadata>
{
    private readonly List<FileMetadata> _fileMetadataList;

    public FileMetadataCollection(List<FileMetadata> fileMetadataList)
    {
        _fileMetadataList = fileMetadataList;
    }

    public IEnumerator<FileMetadata> GetEnumerator()
    {
        return _fileMetadataList.GetEnumerator();
    }

    System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator()
    {
        return GetEnumerator();
    }
}

public interface ILogger
{
    void LogError(Exception ex, string message);
}
