    public IDataReader ExecuteQuery(string commandTemplate, List<SqlParameter> parameters)
    {
        using (SqlConnection connection = new SqlConnection("Data Source=<your_data_source>;Initial Catalog=<your_catalog>;User ID=<your_username>;Password=<your_password>;"))
        {
            connection.Open();

            StringBuilder query = new StringBuilder();
            foreach (SqlParameter parameter in parameters)
            {
                query.Append(commandTemplate);
                commandTemplate = parameter.ParameterName + "=@" + parameter.ParameterName;
            }

            using (SqlCommand command = new SqlCommand(query.ToString(), connection))
            {
                foreach (SqlParameter parameter in parameters)
                {
                    command.Parameters.Add(parameter);
                }
                try
                {
                    IDataReader reader = command.ExecuteReader();
                    return reader;
                }
                catch (SqlException ex)
                {
                    // Log the error for future analysis
                    Console.WriteLine("Error: " + ex.Message);

                    if (ex.Number == 3958) // Retry logic for transient errors
                    {
                        try
                        {
                            using (SqlCommand command2 = new SqlCommand(commandTemplate, connection))
                            {
                                foreach (SqlParameter parameter in parameters)
                                {
                                    command2.Parameters.Add(parameter);
                                }
                                IDataReader reader = command2.ExecuteReader();
                                return reader;
                            }
                        }
                        catch (SqlException ex2)
                        {
                            // Log the error for future analysis
