using UnityEngine;

public class ValueGenerator : MonoBehaviour
{
    private float _min;
    private float _max;
    private bool _isWeighted;
    private float[] _probabilityWeights;
    private GaussianDistributionSettings _gaussianDistribution;

    public ValueGenerator(float min, float max)
    {
        if (min > max) throw new Exception("Minimum value must be less than or equal to maximum value.");

        _min = min;
        _max = max;
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.value * (_max - _min) + _min;
    }

    public int GetRandomInt()
    {
        return UnityEngine.Random.Range(_min, _max + 1);
    }

    public int[] GenerateRandomIntArray(int size)
    {
        int[] array = new int[size];
        for (int i = 0; i < size; i++)
        {
            array[i] = GetRandomInt();
        }
        return array;
    }

    public int[] GenerateWeightedRandomIntArray(int size, float[] weights)
    {
        _isWeighted = true;
        _probabilityWeights = weights;
        return GenerateRandomIntArray(size);
    }

    public float[] GenerateRandomFloatArray(int size)
    {
        float[] array = new float[size];
        for (int i = 0; i < size; i++)
        {
            array[i] = GetRandomFloat();
        }
        return array;
    }

    public float[] GenerateWeightedRandomFloatArray(int size, float[] weights)
    {
        _isWeighted = true;
        _probabilityWeights = weights;
        return GenerateRandomFloatArray(size);
    }

    public float[] GenerateGaussianDistributionFloatArray(int size, float mean, float standardDeviation)
    {
        _gaussianDistribution = new GaussianDistributionSettings(mean, standardDeviation);
        float[] array = new float[size];
        for (int i = 0; i < size; i++)
        {
            array[i] = _gaussianDistribution.Sample();
        }
        return array;
    }

    public int[] GenerateRandomArrayWithStepSize(int size, int stepSize)
    {
        int[] array = new int[size];
        float startValue = GetRandomFloat();
        for (int i = 0; i < size; i++)
        {
            array[i] = (int)(startValue + (i * stepSize));
        }
        return array;
    }

    public override string ToString()
    {
        string toString = $"Range: [{_min}, {_max}]";
        if (_isWeighted)
        {
            toString += $", Weighted: {string.Join(", ", _probabilityWeights)}";
        }
        if (_gaussianDistribution != null)
        {
            toString += $", Gaussian Distribution: Mean={_gaussianDistribution.Mean}, Standard Deviation={_gaussianDistribution.StandardDeviation}";
        }
        return toString;
    }

    [System.Serializable]
    public class GaussianDistributionSettings
    {
        public float Mean;
        public float StandardDeviation;

        public GaussianDistributionSettings(float mean, float standardDeviation)
        {
            Mean = mean;
            StandardDeviation = standardDeviation;
        }

        public float Sample()
        {
            return UnityEngine.Random.normal(0f, 1f) * StandardDeviation + Mean;
        }
    }
}
