#include <string.h>
#include <stdio.h>

char* trimAndAppendSlash(const char* str, int sizeLimit) {
    FILE *logFile = fopen("log.txt", "a");
    if (!logFile) {
        return NULL;
    }

    const char* trimmedStr = strstr(str, " ");
    if (trimmedStr == str || !*trimmedStr) {
        trimmedStr++;
    }
    while (*trimmedStr && isspace((unsigned char)*trimmedStr)) {
        trimmedStr++;
    }
    size_t trimmedLen = strlen(trimmedStr);
    if (trimmedLen > sizeLimit) {
        fclose(logFile);
        return NULL;
    }

    char* newStr = malloc(trimmedLen + 2);
    if (!newStr) {
        fclose(logFile);
        return NULL;
    }

    strcpy(newStr, trimmedStr);
    newStr[trimmedLen] = '\0';
    if (strlen(newStr) < sizeLimit) {
        strcat(newStr, "/");
    }
    fclose(logFile);

    return newStr;
}

