from collections import deque
import pickle
import os

class TaskDependencyGraph:
    def __init__(self):
        self.dag = {}
        self.cache = {}

    def add_task(self, task_id, dependencies=None):
        if dependencies is None:
            dependencies = []
        self.dag[task_id] = dependencies

    def traverse_dag(self, start_task, max_depth):
        visited = set()
        stack = deque([(start_task, 0)])
        result = []
        cyclic_deps = set()

        while stack:
            task, depth = stack.pop()
            if depth > max_depth:
                continue
            if task in visited:
                if depth == 1:
                    cyclic_deps.add(task)
                continue
            visited.add(task)

            if task not in self.dag:
                continue

            for neighbor in self.dag[task]:
                if neighbor in cyclic_deps:
                    return None, None
                stack.append((neighbor, depth + 1))

        if len(cyclic_deps) > 0:
            print(f"Cyclic dependencies detected: {cyclic_deps}")
            return None, None

        return list(visited), result

    def get_task_metadata(self, task_id):
        # API call to project management API
        pass

def main():
    graph = TaskDependencyGraph()
    graph.add_task("Task1", ["Task2"])
    graph.add_task("Task2", ["Task3"])
    graph.add_task("Task3", ["Task4"])
    graph.add_task("Task4")

    start_task = "Task1"
    max_depth = 2

    result, _ = graph.traverse_dag(start_task, max_depth)

    if result is None:
        print("No tasks can be executed within the specified depth.")
    else:
        for task in result:
            metadata = graph.get_task_metadata(task)
            print(f"Task: {task}, Description: {metadata['description']}, Duration: {metadata['duration']}, Resources: {metadata['resources']}")

if __name__ == "__main__":
    main()
