import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class FileHasher {
    private static final int MAX_RETRIES = 3; // configurable maximum number of retries
    private static final String API_KEY = "YOUR_API_KEY"; // replace with your API key

    public Map<String, String> computeAndValidateFileHashes(List<File> files) throws HashMismatchException {
        ExecutorService executor = Executors.newFixedThreadPool(files.size());
        Map<String, Future<String>> futures = new HashMap<>();

        for (File file : files) {
            Callable<String> callable = () -> computeAndValidateFileHash(file);
            Future<String> future = executor.submit(callable);
            futures.put(file.getAbsolutePath(), future);
        }

        Map<String, String> results = new HashMap<>();
        for (Map.Entry<String, Future<String>> entry : futures.entrySet()) {
            try {
                String filePath = entry.getKey();
                String hash = entry.getValue().get(); // get the result
                results.put(filePath, hash);
            } catch (InterruptedException | ExecutionException e) {
                throw new HashMismatchException("Failed to compute or validate file hashes", e);
            }
        }

        executor.shutdown();

        return results;
    }

    private String computeAndValidateFileHash(File file) throws IOException {
        try (InputStream inputStream = Files.newInputStream(file.toPath())) {
            MessageDigest md5 = MessageDigest.getInstance("MD5");
            byte[] buffer = new byte[1024];
            int bytesRead;

            while ((bytesRead = inputStream.read(buffer)) != -1) {
                md5.update(buffer, 0, bytesRead);
            }

            String computedHash = bytesToHex(md5.digest());

            // call the API to validate the hash
            try (InputStream apiResponse = sendApiRequest(file.getAbsolutePath(), computedHash)) {
                MessageDigest md5Api = MessageDigest.getInstance("MD5");
                byte[] bufferApi = new byte[1024];
                int bytesReadApi;

                while ((bytesReadApi = apiResponse.read(bufferApi)) != -1) {
                    md5Api.update(bufferApi, 0, bytesReadApi);
                }

                String apiHash = bytesToHex(md5Api.digest());
                if (!computedHash.equals(apiHash)) {
                    throw new HashMismatchException("Computed hash does not match API hash", file.getAbsolutePath(), computedHash, apiHash);
                }
            } catch (IOException e) {
                // handle transient API failures
                int retries = 0;
                while (retries < MAX_RETRIES && !sendApiRequest(file.getAbsolutePath(), computedHash).available() > 0) {
                    try { Thread.sleep(100); } catch (InterruptedException ignored) {}
                    retries++;
                }
                if (retries >= MAX_RETRIES) {
                    throw new HashMismatchException("Failed to validate file hash after " + MAX_RETRIES + " retries", file.getAbsolutePath(), computedHash);
                }
            }

            return computedHash;
        }
    }

    private InputStream sendApiRequest(String filePath, String computedHash) throws IOException {
        // implement your API request logic here
        // for demonstration purposes, assume a simple HTTP GET request
        try (InputStream response = new URL("https://api.example.com/validate-hash?file=" + filePath + "&hash=" + computedHash).openStream()) {
            return response;
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder builder = new StringBuilder();
        for (byte b : bytes) {
            builder.append(String.format("%02x", b));
        }
        return builder.toString();
    }
}
