from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
import os
import boto3

app = Flask(__name__)
app.config["SQLALCHEMY_DATABASE_URI"] = "sqlite:///inventory.db"
db = SQLAlchemy(app)

class Product(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    category = db.Column(db.String(50))
    tags = db.Column(db.String(200))
    image_url = db.Column(db.String(255))

@app.route("/products", methods=["GET"])
def get_products():
    products = Product.query.all()
    return jsonify([product.to_dict() for product in products])

@app.route("/products", methods=["POST"])
def create_product():
    data = request.get_json()
    product = Product(name=data["name"], category=data["category"], tags=data["tags"], image_url=data["image_url"])
    db.session.add(product)
    db.session.commit()
    return jsonify({"id": product.id})

@app.route("/products/<int:product_id>", methods=["GET"])
def get_product(product_id):
    product = Product.query.get(product_id)
    if product is None:
        return jsonify({"error": "Product not found"}), 404
    return jsonify(product.to_dict())

@app.route("/products/<int:product_id>/image", methods=["POST"])
def upload_image(product_id):
    s3 = boto3.client("s3")
    file = request.files["file"]
    product = Product.query.get(product_id)
    if product is None:
        return jsonify({"error": "Product not found"}), 404
    s3.put_object(Body=file.read(), Bucket="your-bucket-name", Key=f"products/{product.id}.jpg")
    product.image_url = f"s3://your-bucket-name/products/{product.id}.jpg"
    db.session.commit()
    return jsonify({"message": "Image uploaded successfully"})

if __name__ == "__main__":
    app.run(debug=True)
