#include <functional>

class Octree {
public:
    using Point = std::tuple<double, double, double>; // x, y, z coordinates

    Octree(int maxDepth) : maxDepth_(maxDepth), root_(nullptr) {}

    ~Octree() { destroy(root_); }

    void insert(const Point& point);

    bool query(const Point& point, std::function<void(const Point&)>& callback);

private:
    struct Node {
        int depth;
        Point bounds[8]; // 2^3 = 8 corners
        bool isLeaf; // leaf node or not

        std::vector<Point> points;

        Node(int depth) : depth(depth), isLeaf(true) {}

        ~Node() {
            if (!isLeaf)
                destroyChildren();
        }

        void destroyChildren() {
            for (int i = 0; i < 8; ++i) {
                if (children_[i]) {
                    delete children_[i];
                    children_[i] = nullptr;
                }
            }
        }
    };

    Node* createNode(int depth);

    void insert(Node*& node, const Point& point);

    bool query(Node* node, const Point& point, std::function<void(const Point&)>& callback);

    void destroy(Node* node);

    int maxDepth_;
    Node* root_;

    std::mutex mtx_; // protects access to the octree
    std::condition_variable cv_; // for thread synchronization

    std::vector<Node*> children_[8];
};

