struct HttpsClient {
    client: hyper::Client<HttpsConnector>,
}

impl HttpsClient {
    async fn new(cert_validation: bool) -> Self {
        let connector = HttpsConnector::new(Some((0.5, 1.5).into())).unwrap();
        let mut client = Client::builder().build::<_, hyper::Body>(connector);
        if cert_validation {
            // add certificate validation logic
        }
        HttpsClient { client }
    }

    async fn get(&self, url: &str) -> Result<hyper::Response, Box<dyn std::error::Error>> {
        let req = Request::get(url).unwrap();
        self.client.request(req).await
    }

    async fn post(&self, url: &str, data: String) -> Result<hyper::Response, Box<dyn std::error::Error>> {
        let mut req = Request::post(url).body(data.as_bytes()).unwrap();
        self.client.request(req).await
    }
}

struct ReqwestClientWrapper {
    client: ReqwestClient,
}

impl ReqwestClientWrapper {
    async fn new() -> Self {
        ReqwestClientWrapper { client: get("https://example.com").await.unwrap().json().await.unwrap() }
    }

    async fn get(&self, url: &str) -> Result<reqwest::blocking::Response, Box<dyn std::error::Error>> {
        self.client.get(url).send().await
    }
}

async fn main() {
    let (task1, task2) = join!(
        HttpsClient::new(true).get("https://example.com").await,
        ReqwestClientWrapper::new().get("https://example.net").await
    );

    match (task1, task2) {
        (Ok(response), Ok(reqwest_response)) => println!("Both requests were successful"),
        (Err(err), _) => println!("Error: {}", err),
        (_, Err(err)) => println!("Error: {}", err),
    }
}

fn main() {
    tokio::runtime::Runtime::new().unwrap().block_on(main());
}
