import os
import tempfile
import threading
import logging
from typing import Dict, List

class DirectoryManager:
    def __init__(self):
        self._directories: Dict[str, int] = {}
        self._lock = threading.Lock()
        self._logger = logging.getLogger(__name__)
        self._config = {"parent_dir": None, "temp_dir": None}

    @property
    def config(self) -> Dict:
        return self._config

    @config.setter
    def config(self, value: Dict):
        self._config = value

    def create_directory(self, name: str) -> str:
        with self._lock:
            if not self._directories.get(name):
                for _ in range(5):  # retry up to 5 times
                    try:
                        os.makedirs(os.path.join(self.config["parent_dir"], name), exist_ok=True)
                        self._directories[name] = 1
                        return os.path.join(self.config["parent_dir"], name)
                    except (OSError, IOError) as e:
                        if e.errno not in [13, 28]:  # permission or no such file or directory
                            raise
                else:
                    raise Exception(f"Failed to create directory '{name}' after 5 retries")
            return self._directories[name]

    def get_directory(self, name: str) -> str:
        with self._lock:
            if self._directories.get(name):
                return self._directories[name]
            return None

    def delete_directory(self, name: str) -> None:
        with self._lock:
            try:
                os.rmdir(self.get_directory(name))
            except OSError as e:
                if e.errno != 2:  # no such file or directory
                    raise

    def get_temp_dir(self) -> str:
        return tempfile.gettempdir()

    def set_parent_dir(self, path: str) -> None:
        self.config["parent_dir"] = path

    def set_temp_dir(self, path: str) -> None:
        self.config["temp_dir"] = path

    @staticmethod
    def _async_create_directory(name: str) -> None:
        import asyncio
        try:
            await asyncio.to_thread(os.makedirs, os.path.join(DirectoryManager().config["parent_dir"], name), exist_ok=True)
        except (OSError, IOError):
            pass

