using System;
using System.IO;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class BinaryDataLoader
{
    private readonly ILogger<BinaryDataLoader> _logger;
    private readonly Func<FileStream, Task<DeserializationResult>> _deserializer;

    public BinaryDataLoader(ILogger<BinaryDataLoader> logger, Func<FileStream, Task<DeserializationResult>> deserializer)
    {
        _logger = logger;
        _deserializer = deserializer;
    }

    public async Task<LoadingResult> LoadAndDeserializeAsync(string filePath)
    {
        try
        {
            using var fileStream = File.OpenRead(filePath);
            return await LoadAndDeserializeAsync(fileStream);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error loading and deserializing binary data");
            throw;
        }
    }

    private async Task<LoadingResult> LoadAndDeserializeAsync(FileStream fileStream)
    {
        try
        {
            var result = await _deserializer(fileStream);
            return new LoadingResult { Data = result.DeserializedData };
        }
        catch (Exception ex) when (ex is SerializationError || ex is VersionMismatch)
        {
            _logger.LogError(ex, "Error deserializing binary data");
            throw;
        }
        catch (Exception ex) when (ex is PartialFileCorruption)
        {
            _logger.LogWarning(ex, "Partial file corruption detected. Skipping this file.");
            return new LoadingResult { HasErrors = true };
        }
    }

    public class LoadingResult
    {
        public object Data { get; set; }
        public bool HasErrors { get; set; }
    }

    public class DeserializationResult
    {
        public object DeserializedData { get; set; }
        public bool IsValid { get; set; }
    }
}
