import os
import tempfile
import time
from functools import wraps
from threading import Lock
from queue import Queue
from multiprocessing import Process, Manager
from cryptography.fernet import Fernet

class DirectoryManager:
    def __init__(self, root_dir):
        self.root_dir = root_dir
        self.config = Manager().dict()
        self.lock = Lock()
        self.temp_dir_queue = Queue()

    def create_directory(self, dir_name):
        while True:
            try:
                path = os.path.join(self.root_dir, dir_name)
                os.makedirs(path, exist_ok=True)
                break
            except Exception as e:
                if isinstance(e, FileNotFoundError) or 'File exists' in str(e):
                    time.sleep(1)
                elif 'Permission denied' in str(e):
                    self.lock.acquire()
                    try:
                        self.create_directory(dir_name)
                    finally:
                        self.lock.release()
                else:
                    raise

    def get_temp_dir(self):
        temp_dir = tempfile.TemporaryDirectory()
        self.temp_dir_queue.put(temp_dir.name)
        return temp_dir

    def acquire_lock(self, node_id):
        return self.config.get(node_id, Lock())

    def get_config(self):
        return self.config.copy()

    def update_config(self, node_id, config_data):
        self.config[node_id] = config_data
        for node in list(self.config.keys()):
            if node != node_id:
                self.acquire_lock(node).acquire()
                try:
                    self.config[node].update(config_data)
                finally:
                    self.acquire_lock(node).release()

    def encrypt_dir_create_request(self, dir_name):
        key = Fernet.generate_key()
        cipher_text = Fernet(key).encrypt(dir_name.encode())
        return key, cipher_text

    def decrypt_dir_create_request(self, key, cipher_text):
        plain_text = Fernet(key).decrypt(cipher_text)
        return plain_text.decode()

    @wraps(create_directory)
    def secure_create_directory(self, node_id, dir_name):
        _, encrypted_dir_name = self.encrypt_dir_create_request(dir_name)
        while True:
            try:
                path = os.path.join(self.root_dir, dir_name)
                os.makedirs(path, exist_ok=True)
                break
            except Exception as e:
                if isinstance(e, FileNotFoundError) or 'File exists' in str(e):
                    time.sleep(1)
                elif 'Permission denied' in str(e):
                    self.acquire_lock(node_id).acquire()
                    try:
                        self.secure_create_directory(node_id, dir_name)
                    finally:
                        self.acquire_lock(node_id).release()
                else:
                    raise

    def start(self):
        processes = []
        for _ in range(5):  # Adjust the number of worker nodes
            process = Process(target=self.worker_process)
            processes.append(process)
            process.start()

    def worker_process(self):
        node_id = os.getpid()
        while True:
            try:
                dir_name = self.temp_dir_queue.get()
                self.secure_create_directory(node_id, dir_name)
                self.temp_dir_queue.task_done()
            except Exception as e:
                if 'File exists' in str(e):
                    time.sleep(1)
                else:
                    raise

    def shutdown(self):
        for process in processes:
            process.terminate()

