import asyncio
import logging
from aiohttp import ClientSession
from jinja2 import Template

class Configurator:
    def __init__(self):
        self.configs = {}
        self.session = ClientSession()

    async def fetch_configs(self, url):
        try:
            async with self.session.get(url) as response:
                data = await response.json()
                return data
        except Exception as e:
            logging.error(f"Error fetching configurations: {e}")
            return []

    def render_config(self, config):
        template = Template('''
            <div>
                {{ label }}:
                {% if element_type == 'input' %}
                    <input type="text" name="{{ name }}" value="{{ value }}">
                {% elif element_type == 'select' %}
                    <select name="{{ name }}">
                        {% for option in options %}
                            <option value="{{ option }}">{{ option }}</option>
                        {% endfor %}
                    </select>
                {% elif element_type == 'textarea' %}
                    <textarea name="{{ name }}">{{ value }}</textarea>
                {% endif %}
            </div>
        ''')
        return template.render(config)

    def update_ui(self, configs):
        html = ''
        for config in configs:
            if not self.configs.get(config['name']):
                self.configs[config['name']] = config
                html += self.render_config(config)
        return html

    async def fetch_and_render_configs(self, url, container):
        try:
            configs = await self.fetch_configs(url)
            if configs:
                html = self.update_ui(configs)
                await container.innerHTML.set_value(html)
        except Exception as e:
            logging.error(f"Error updating UI: {e}")
