const fs = require('fs');
const path = require('path');
const vm = require('vm');

class ModuleLoader {
  constructor(cacheDir = './cache') {
    this.cacheDir = cacheDir;
    this.moduleCache = {};
  }

  async loadModule(moduleName, dependencies = []) {
    if (this.moduleCache[moduleName]) {
      return this.moduleCache[moduleName];
    }

    try {
      const modulePath = path.join(__dirname, `./modules/${moduleName}.js`);
      let moduleCode;
      try {
        moduleCode = await fs.promises.readFile(modulePath, 'utf8');
      } catch (error) {
        console.error(`Error loading module ${moduleName}: ${error.message}`);
        return null;
      }

      if (!dependencies.every((dep) => this.moduleCache[dep])) {
        throw new Error(`Circular dependency detected for module ${moduleName}`);
      }

      const moduleScope = vm.createContext();
      try {
        // Load dependencies
        for (const dep of dependencies) {
          await this.loadModule(dep);
        }
        // Execute module code in the context of the loaded dependencies
        await vm.runInContext(moduleCode, moduleScope);
        this.moduleCache[moduleName] = moduleScope;
      } catch (error) {
        console.error(`Error executing module ${moduleName}: ${error.message}`);
        return null;
      }

      return this.moduleCache[moduleName];
    } catch (error) {
      console.error(`Error loading module ${moduleName}: ${error.message}`);
      return null;
    }
  }

  async loadModulesOrder(dependencies, order = []) {
    for (const moduleName of order) {
      await this.loadModule(moduleName, dependencies);
    }
  }
}

module.exports = ModuleLoader;
