#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int state;
    struct FSA* transition;
} State;

State* find_states(int* states, int num_states, struct FSA* fsa, int last_state) {
    // Initialize the state list
    State* state_list = (State*)malloc(sizeof(State));

    if (!state_list) {
        return NULL;  // Out of memory
    }

    // Perform DFS traversal
    state_list->state = last_state;
    struct FSA* current_fsa = fsa;
    while (current_fsa && current_fsa->state != -1) {
        if (current_fsa->state < num_states && !contains(states, current_fsa->state, num_states)) {
            // Add the state to the list
            State* new_state = (State*)malloc(sizeof(State));

            if (!new_state) {
                free(state_list);
                return NULL;  // Out of memory
            }

            new_state->state = current_fsa->state;
            new_state->transition = current_fsa->transition;
            state_list = add_to_list(state_list, &new_state);  // Update the head of the list

            // Move to the next transition
            current_fsa = current_fsa->transition;
        } else {
            break;  // Reached the end of the FSA or a loop
        }
    }

    return state_list;
}

// Helper function to check if a state is in the list of states
int contains(int* states, int target_state, int num_states) {
    for (int i = 0; i < num_states; i++) {
        if (states[i] == target_state) {
            return 1;  // Found the state
        }
    }
    return 0;  // Not found
}

// Helper function to add a new state to the list and update the head of the list
State* add_to_list(State* head, State** new_state) {
    if (!head) {
        return *new_state;
    }

    (*new_state) = (State*)malloc(sizeof(State));

    if (!(*new_state)) {
        free(head);
        return NULL;  // Out of memory
    }

    (*new_state)->state = head->state;
    (*new_state)->transition = head->transition;
    head = *new_state;

    return head;
}
