import logging
import time
from typing import Dict, List
import requests
import json
import threading

class WeatherData:
    def __init__(self, city: str, temp: float, humidity: int, condition: str):
        self.city = city
        self.temp = temp
        self.humidity = humidity
        self.condition = condition

class Cacher:
    def __init__(self, max_size: int):
        self.max_size = max_size
        self.cache = {}
        self.lock = threading.Lock()

    def get(self, key: str) -> WeatherData:
        with self.lock:
            if key in self.cache:
                data = self.cache[key]
                del self.cache[key]  # Remove to make room for new data
                return data
        return None

    def put(self, key: str, value: WeatherData):
        with self.lock:
            if len(self.cache) >= self.max_size:
                self.cache.popitem(last=False)
            self.cache[key] = value


def fetch_weather_data(api_key: str, city: str, preferred_timezone: str) -> Dict[str, List[WeatherData]]:
    api_url = f"http://api.openweathermap.org/data/2.0/weather"
    headers = {"Authorization": f"Bearer {api_key}"}

    cache = Cacher(max_size=100)

    while True:
        try:
            response = requests.get(api_url, params={"q": city, "units": "metric", "tz": preferred_timezone}, headers=headers)
            response.raise_for_status()
            data = json.loads(response.text)
            weather_data = []

            for forecast in data["list"]:
                weather = WeatherData(city=city, temp=forecast["main"]["temp"], humidity=forecast["main"]["humidity"], condition=forecast["weather"][0]["description"])
                weather_data.append(weather)

            if cache.get(f"{city}{preferred_timezone}"):
                return {city: cache.get(f"{city}{preferred_timezone}")()}
            else:
                return {city: weather_data}
        except requests.exceptions.RequestException as e:
            logging.error(f"Failed to fetch weather data for {city}: {e}")
            time.sleep(60)  # Wait 1 minute before retrying
        except json.JSONDecodeError as e:
            logging.error(f"Failed to parse JSON response for {city}: {e}")
            time.sleep(60)  # Wait 1 minute before retrying


# Example usage:
api_key = "YOUR_OPENWEATHERMAP_API_KEY"
cities = ["New York", "London", "Paris"]
preferred_timezone = "America/New_York"

results = {}
for city in cities:
    results[city] = fetch_weather_data(api_key, city, preferred_timezone)
print(results)
