using System;
using System.Threading;

namespace AdvancedRandomGenerator
{
    public enum RangeType { Closed, Open, HalfOpen }

    public class CustomInterval<T> where T : IComparable
    {
        public T Min { get; set; }
        public T Max { get; set; }

        public bool IsHalfOpen => Max == null;
    }

    public delegate void SeedCallback(int seed);

    public sealed class SeedManager
    {
        private static readonly object _lock = new object();
        private static int _seed;

        public static void SetSeed(int seed)
        {
            lock (_lock)
            {
                _seed = seed;
            }
        }

        public static int GetSeed()
        {
            return Interlocked.Exchange(ref _seed, 0);
        }
    }

    public class AdvancedRandomGenerator
    {
        private Random _random;

        public AdvancedRandomGenerator(int seed = default)
        {
            _random = new Random(seed);
        }

        public double GenerateDouble(CustomInterval<double> range, RangeType type = RangeType.Closed)
        {
            if (range.Min > range.Max && type != RangeType.Open)
                throw new ArgumentException("Invalid range: min must be less than or equal to max for closed and half-open intervals.");

            return _random.NextDouble() * (range.Max - range.Min) + range.Min;
        }

        public int GenerateInt(CustomInterval<int> range, RangeType type = RangeType.Closed)
        {
            if (range.Min > range.Max && type != RangeType.Open)
                throw new ArgumentException("Invalid range: min must be less than or equal to max for closed and half-open intervals.");

            return _random.Next((int)range.Min, (int)(type == RangeType.Open ? range.Min + 1 : range.Max));
        }

        public void RegisterSeedCallback(SeedCallback callback)
        {
            // Implement the logic to register the seed callback
        }
    }
}
