# imports
import logging
from flask import Flask, request, jsonify
from flask_caching import Cache
from flask_limiter import Limiter
from flask_limiter.util import get_remote_address
from datetime import datetime, timedelta
from uuid import uuid4

app = Flask(__name__)
cache = Cache(app)
limiter = Limiter(
    app,
    key_func=get_remote_address,
    default_limits=["200 per hour", "50 per minute"]
)

# session metadata store
sessions = {}

def create_session(user_id):
    # generate unique session token
    session_token = str(uuid4())

    # set expiration timestamp to 30 minutes from now
    expire_at = datetime.now() + timedelta(minutes=30)

    sessions[session_token] = {
        "user_id": user_id,
        "expire_at": expire_at,
        "version": 0
    }

    return session_token

@app.route('/sessions', methods=['POST'])
@limiter.limit("5 per minute")
def create_session_endpoint():
    if not request.is_json:
        return jsonify({"error": "Invalid JSON"}), 400

    user_id = request.get_json()['user_id']
    session_token = create_session(user_id)

    return jsonify({'session_token': session_token}), 201

@app.route('/sessions/<string:session_token>', methods=['PUT'])
@limiter.limit("2 per minute")
def update_session_endpoint(session_token):
    if not request.is_json:
        return jsonify({"error": "Invalid JSON"}), 400

    user_id = sessions.get(session_token, {}).get('user_id')

    if not user_id:
        return jsonify({"error": "Unauthorized"}), 401

    if datetime.now() > sessions[session_token]['expire_at']:
        return jsonify({"error": "Session has expired"}), 401

    # increment session version
    sessions[session_token]['version'] += 1

    return jsonify({'message': 'Session updated'}), 200

@app.route('/sessions/<string:session_token>', methods=['DELETE'])
@limiter.limit("2 per minute")
def delete_session_endpoint(session_token):
    user_id = sessions.get(session_token, {}).get('user_id')

    if not user_id:
        return jsonify({"error": "Unauthorized"}), 401

    if datetime.now() > sessions[session_token]['expire_at']:
        return jsonify({"error": "Session has expired"}), 401

    # check version
    if sessions[session_token]['version'] != request.args.get('version'):
        return jsonify({"error": "Session has been modified"}), 409

    del sessions[session_token]

    return jsonify({'message': 'Session deleted'}), 200

@app.route('/sessions', methods=['GET'])
@limiter.limit("10 per minute")
def get_sessions_endpoint():
    return jsonify({'sessions': list(sessions.keys())}), 200

if __name__ == '__main__':
    app.run(debug=True)
