const fs = require('fs');
const jest = require('@jest/globals');
const child_process = require('child_process');
const os = require('os');

class TestRunner {
  constructor(config) {
    this.config = config;
    this.modules = [];
    this.testSuites = [];
  }

  async loadModules() {
    const modulesDir = this.config.modulesDirectory;
    if (!fs.existsSync(modulesDir)) {
      throw new Error(`Module directory '${modulesDir}' does not exist`);
    }
    try {
      this.modules = await fs.readdirAsync(modulesDir);
    } catch (err) {
      console.error(err);
      process.exit(1);
    }
  }

  async runTests() {
    for (const module of this.modules) {
      if (!this.config.testSuites.includes(module)) continue;
      try {
        const testModule = await require(`./${module}`);
        this.testSuites.push(testModule);
      } catch (err) {
        console.error(err);
        process.exit(1);
      }
    }
  }

  async runTestSuites() {
    const concurrencyLevel = Math.floor(os.cpus().length / 2); // adjust based on your system resources
    const childProcesses = [];
    for (const testSuite of this.testSuites) {
      childProcesses.push(child_process.fork('run-test-suite.js', [JSON.stringify(testSuite)]));
    }
    return Promise.all(childProcesses.map(process => new Promise((resolve, reject) => process.on('exit', resolve).on('error', reject))));
  }

  async logTestResults() {
    // implement logging logic to send test results to a centralized log server
  }

  async handleErrors(err) {
    console.error(err);
    if (!this.config.continueOnFailure) process.exit(1);
  }

  async run(config) {
    this.config = config;
    await this.loadModules();
    await this.runTests();
    await this.runTestSuites();
    await this.logTestResults();
  }
}

module.exports = TestRunner;
