        if (file.exists()) {
            fileInputStream = new FileInputStream(file);
        } else {
            fileInputStream = new FileInputStream(new ByteArrayInputStream((byte[]) filePathOrBytes));
        }

        return processImageFile(fileInputStream, outputFormat);
