#include <vector>
#include <memory>

std::unique_ptr<class KDTree> createKDTree(int dimensionality, int maxDepth, void* libPtr) {
    std::unique_ptr<KDTree> tree = std::make_unique<KDTree>(dimensionality, maxDepth);

    // Initialize the root node
    tree->rootNode = new Node(dimensionality);

    // Initialize auxiliary data structures for point queries
    tree->queryData = std::vector<std::vector<float>>(1 << dimensionality, std::vector<float>(dimensionality));

    return tree;
}

class KDTree {
public:
    int dimensionality;
    int maxDepth;
    Node* rootNode;

    std::vector<std::vector<float>> queryData;
};

class Node {
public:
    int dimensionIndex;
    float thresholdValue;
    Node* leftChild;
    Node* rightChild;

    Node(int dim) : dimensionIndex(dim), leftChild(nullptr), rightChild(nullptr) {}
};
