function refreshDialogFields(resourceId, fields, url) {
  const fieldMap = {};
  const apiCalls = [];

  // Dynamically identify and prepare fields for update
  fields.forEach((field) => {
    fieldMap[field] = {value: '', pending: false};
  });

  // Fetch updated data for each field from APIs
  Object.keys(fieldMap).forEach((field) => {
    const apiCall = fetch(`${url}/${resourceId}/${field}`)
      .then((response) => response.json())
      .catch((error) => {
        console.error(`Error fetching ${field} data: ${error}`);
        return Promise.resolve({value: '', pending: true});
      });

    // Cache API calls to optimize performance
    apiCalls.push(apiCall);
  });

  // Concurrently refresh fields with batched API requests
  Promise.all(apiCalls).then((responses) => {
    responses.forEach((response, index) => {
      const field = Object.keys(fieldMap)[index];
      if (response.pending) {
        fieldMap[field].value = '';
      } else {
        fieldMap[field].value = response.value;
      }

      // Update the dialog fields
      // ... (your logic to update the UI goes here)
    });
  });
}
