#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

// Define the structure for semaphore manager
typedef struct {
    pthread_mutex_t lock;
    sem_t *semaphores; // Array of semaphores
    int num_resources; // Number of resources (e.g., database connections)
    int max_permits_per_resource;
    char *resource_names; // Names of each resource type
} semaphore_manager_t;

// Initialize the semaphore manager
void init_semaphore_manager(semaphore_manager_t *manager, int num_resources) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->semaphores = (sem_t *)malloc(num_resources * sizeof(sem_t));
    for (int i = 0; i < num_resources; i++) {
        sem_init(&manager->semaphores[i], 1, manager->max_permits_per_resource);
    }
    manager->num_resources = num_resources;
}

// Destroy the semaphore manager
void destroy_semaphore_manager(semaphore_manager_t *manager) {
    for (int i = 0; i < manager->num_resources; i++) {
        sem_destroy(&manager->semaphores[i]);
    }
    free(manager->semaphores);
    pthread_mutex_destroy(&manager->lock);
}

// Acquire a permit from the semaphore manager
void acquire_permit(semaphore_manager_t *manager, int resource_index) {
    pthread_mutex_lock(&manager->lock);
    sem_wait(&manager->semaphores[resource_index]);
    pthread_mutex_unlock(&manager->lock);
}

// Release a permit to the semaphore manager
void release_permit(semaphore_manager_t *manager, int resource_index) {
    pthread_mutex_lock(&manager->lock);
    sem_post(&manager->semaphores[resource_index]);
    pthread_mutex_unlock(&manager->lock);
}

int main() {
    // Initialize the semaphore manager for 3 resources (e.g., database connections)
    semaphore_manager_t manager;
    init_semaphore_manager(&manager, 3);

    // Acquire a permit from each resource
    acquire_permit(&manager, 0);
    acquire_permit(&manager, 1);
    acquire_permit(&manager, 2);

    // Release the permits
    release_permit(&manager, 0);
    release_permit(&manager, 1);
    release_permit(&manager, 2);

    // Destroy the semaphore manager
    destroy_semaphore_manager(&manager);

    return 0;
}
