package com.example.sassapplication.service;

import java.sql.Timestamp;
import java.util.UUID;

import javax.validation.Valid;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.cache.annotation.CachePut;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RestController;

import com.example.sassapplication.domain.UserPlan;
import com.example.sassapplication.exception.InvalidUpgradePlanException;
import com.example.sassapplication.exception.ServiceCommunicationFailureException;
import com.example.sassapplication.model.UpgradePlanRequest;
import com.example.sassapplication.service.accountplan.AccountPlanService;
import com.example.sassapplication.service.billing.BillingService;
import com.example.sassapplication.service.notification.NotificationService;
import com.example.sssapplication.util.Logger;

@RestController
public class UserAccountUpgradeController {

    private static final Logger logger = Logger.getLogger(UserAccountUpgradeController.class);

    @Autowired
    private AccountPlanService accountPlanService;

    @Autowired
    private BillingService billingService;

    @Autowired
    private NotificationService notificationService;

    @PutMapping("/api/users/{tenantId}/users/{userId}/upgrade")
    public ResponseEntity<UserPlan> upgradeUserAccount(@RequestHeader("Authorization") String authorization,
            @PathVariable("tenantId") UUID tenantId, @PathVariable("userId") UUID userId,
            @Valid @RequestBody UpgradePlanRequest request) {

        // Validate inputs
        accountPlanService.validateTenantAndUserId(tenantId, userId);

        if (request.getSubscriptionTier() == null || request.getExpirationDate() == null) {
            throw new InvalidUpgradePlanException("Invalid upgrade plan details");
        }

        try {
            // Update user's account plan using service layer
            UserPlan updatedUserPlan = accountPlanService.updateUserPlan(tenantId, userId, request);

            // Notify billing and notification services through service mesh
            billingService.updateBillingInformation(tenantId, userId, request);
            notificationService.sendNotification(tenantId, userId, request);

            return ResponseEntity.status(HttpStatus.OK).body(updatedUserPlan);

        } catch (ServiceCommunicationFailureException e) {
            logger.error("Error communicating with service mesh", e);
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).build();

        } catch (Exception e) {
            logger.error("Error upgrading user account", e);
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).build();
        }
    }
}
