class JSONSerializer {
public:
    std::string serialize(const std::map<std::string, std::any>& data) const {
        boost::property_tree::ptree tree;
        for (const auto& pair : data) {
            tree.put(pair.first.c_str(), pair.second.get());
        }
        std::stringstream stream;
        boost::property_tree::write_json(stream, tree, false);
        return stream.str();
    }

    std::map<std::string, std::any> deserialize(const std::string& json) {
        boost::property_tree::ptree tree;
        std::istringstream stream(json);
        boost::property_tree::read_json(stream, tree, false);

        std::map<std::string, std::any> data;
        for (const auto& pair : tree.get_child("")) {
            if (!pair.second.empty()) {
                data[pair.first] = pair.second.data();
            }
        }

        return data;
    }
};

