import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.AsynchronousChannelGroup;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArraySet;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicInteger;

public class ConnectionPool {
    private static final int DEFAULT_MAX_CONNECTIONS = 100;
    private static final int DEFAULT_HEALTH_CHECK_INTERVAL = 10 * 1000; // 10 seconds
    private static final int MIN_HEALTH_CHECK_INTERVAL = 5000; // 5 seconds
    private static final int MAX_HEALTH_CHECK_INTERVAL = 30 * 1000; // 30 seconds

    private final ConcurrentHashMap<String, AsynchronousSocketChannel> channels;
    private final CopyOnWriteArraySet<String> availableServers;
    private final ExecutorService executor;
    private final AtomicInteger connectionCount;
    private final int maxConnections;
    private final int healthCheckInterval;

    public ConnectionPool(int maxConnections) {
        this(maxConnections, DEFAULT_HEALTH_CHECK_INTERVAL);
    }

    public ConnectionPool(int maxConnections, int healthCheckInterval) {
        if (maxConnections < 1) {
            throw new IllegalArgumentException("Max connections must be greater than zero");
        }
        if (healthCheckInterval < MIN_HEALTH_CHECK_INTERVAL || healthCheckInterval > MAX_HEALTH_CHECK_INTERVAL) {
            throw new IllegalArgumentException("Health check interval out of range");
        }

        this.maxConnections = maxConnections;
        this.healthCheckInterval = healthCheckInterval;
        this.channels = new ConcurrentHashMap<>();
        this.availableServers = new CopyOnWriteArraySet<>();
        this.executor = Executors.newCachedThreadPool();
        this.connectionCount = new AtomicInteger(0);
    }

    public AsynchronousSocketChannel connect(String server) {
        if (!availableServers.contains(server)) {
            throw new RuntimeException("Server not available");
        }
        try {
            AsynchronousSocketChannel channel = AsynchronousChannelGroup.open().openAsynchronousSocketChannel();
            channel.connect(new InetSocketAddress(server), null).get();
            channels.put(server, channel);
            connectionCount.incrementAndGet();
            return channel;
        } catch (IOException | InterruptedException e) {
            throw new RuntimeException(e);
        }
    }

    public void close() {
        executor.shutdown();
        for (AsynchronousSocketChannel channel : channels.values()) {
            try {
                channel.close().get();
            } catch (IOException | InterruptedException e) {
                // Ignore
            }
        }
    }

    public void startHealthCheck() {
        Runnable task = () -> {
            while (true) {
                Thread.sleep(healthCheckInterval);
                for (String server : availableServers) {
                    try {
                        AsynchronousSocketChannel channel = channels.get(server);
                        if (!channel.isOpen()) {
                            // Server is down, remove it from the pool
                            availableServers.remove(server);
                            channels.remove(server);
                            connectionCount.decrementAndGet();
                        }
                    } catch (IOException e) {
                        // Ignore
                    }
                }
            }
        };
        executor.submit(task);
    }

    public static void main(String[] args) {
        ConnectionPool pool = new ConnectionPool(DEFAULT_MAX_CONNECTIONS, DEFAULT_HEALTH_CHECK_INTERVAL);
        // Use the connection pool
    }
}
