using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using StackExchange.Redis;

public class UserProfileFetcher
{
    private readonly IConnectionMultiplexer _redisConnection;
    private readonly HttpClient _httpClient;
    private readonly int _maxRetries;

    public UserProfileFetcher(IConnectionMultiplexer redisConnection, HttpClient httpClient, int maxRetries)
    {
        _redisConnection = redisConnection;
        _httpClient = httpClient;
        _maxRetries = maxRetries;
    }

    public async Task FetchUserProfiles(List<string> userIds, string apiKey, TimeSpan? cacheExpirationTime = null)
    {
        foreach (string userId in userIds)
        {
            ValidateUserId(userId);

            // Check if the user profile is already cached
            string cachedUserProfile = await GetCachedUserProfileAsync(userId);
            if (!string.IsNullOrEmpty(cachedUserProfile))
            {
                Console.WriteLine($"Fetched user profile for {userId} from cache.");
                continue;
            }

            int retries = 0;
            while (retries <= _maxRetries)
            {
                try
                {
                    // Make API request and get the user profile
                    string userProfile = await Get UserProfileFromApiAsync(userId, apiKey);
                    if (!string.IsNullOrEmpty(userProfile))
                    {
                        Console.WriteLine($"Fetched user profile for {userId} from API.");

                        // Cache the user profile
                        await SetCachedUserProfileAsync(userId, userProfile, cacheExpirationTime);

                        return;
                    }
                }
                catch (HttpRequestException ex)
                {
                    // Handle API rate limits and network timeouts
                    if (ex.Message.Contains("429"))
                    {
                        Console.WriteLine($"API rate limit exceeded for {userId}. Retrying in 1 second.");
                        await Task.Delay(1000);
                    }
                    else if (ex.Message.Contains("503") || ex.Message.Contains("504"))
                    {
                        Console.WriteLine($"API endpoint failed for {userId}. Marking as failure and retrying up to {_maxRetries} times.");
                        retries++;
                        continue;
                    }
                    throw; // Rethrow the exception
                }
            }

            // Log the failed attempt
            await LogFailedRequestAsync(userId);
            Console.WriteLine($"Failed to fetch user profile for {userId}. Marked as failure and will not retry.");

            // Dispose of HTTP client resources
            _httpClient.Dispose();
        }
    }

    private async Task<string> GetCachedUserProfileAsync(string userId)
    {
        IDatabase redis = _redisConnection.GetDatabase();
        return await redis.StringGetAsync($"userprofiles:{userId}");
    }

    private async Task SetCachedUserProfileAsync(string userId, string userProfile, TimeSpan? cacheExpirationTime)
    {
        IDatabase redis = _redisConnection.GetDatabase();
        await redis.StringSetAsync($"userprofiles:{userId}", userProfile);
        if (cacheExpirationTime.HasValue)
        {
            await redis.ExpireAsync($"userprofiles:{userId}", cacheExpirationTime.Value);
        }
    }

