            string cachedHtml = await _redisConnection.GetDatabase().StringGetAsync($"html:{pageSectionId}:{elementId}");
            if (string.IsNullOrEmpty(cachedHtml))
                cachedHtml = await GetHtmlContentFromBlobStorage(pageSectionId, elementId);

            // Update HTML content in Redis cache with optimistic concurrency control
            string updatedHtml;
            int retries = 0;
            do
            {
                updatedHtml = await _redisConnection.GetDatabase().StringGetAsync($"html:{pageSectionId}:{elementId}");
                if (string.Compare(updatedHtml, cachedHtml, StringComparison.Ordinal) == 0)
                {
                    // Update HTML content in Redis cache with fine-grained locking mechanism
                    using (IDatabase redisDb = _redisConnection.GetDatabase())
                    {
                        await redisDb.ExecuteAsync("UNLOCK", "html:", pageSectionId);
                        await redisDb.StringSetAsync($"html:{pageSectionId}:{elementId}", htmlContent, TimeSpan.FromHours(1));
                        updatedHtml = await redisDb.StringGetAsync($"html:{pageSectionId}:{elementId}");
                    }
                }
            } while (!string.Compare(updatedHtml, cachedHtml, StringComparison.Ordinal) == 0 && retries++ < 3);

            return new OkResult();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating HTML content");
            if (ex is BusinessException || ex is StorageServiceUnavailableException)
                return new StatusCodeResult(500);
            else
                return new BadRequestResult();
        }
    }

    private async Task<string> GetHtmlContentFromBlobStorage(int pageSectionId, int elementId)
    {
        // Implement logic to fetch HTML content from Azure Blob Storage
    }
}

public class BusinessException : Exception { }

public class StorageServiceUnavailableException : Exception { }
