import json
import logging
from kafka import KafkaConsumer, KafkaProducer
from elasticsearch import Elasticsearch

def process_log_files(config_file):
    with open(config_file, 'r') as f:
        config = yaml.safe_load(f)

    consumer = KafkaConsumer(bootstrap_servers=config['kafka']['servers'],
                              group_id='log_processor',
                              auto_offset_reset='latest')

    producer = KafkaProducer(bootstrap_servers=config['kafka']['servers'])

    es_client = Elasticsearch(hosts=[{'host': config['es']['host'], 'port': config['es']['port']}])

    while True:
        for message in consumer.poll(timeout_ms=1000):
            if message is None:
                continue
            try:
                log_entry = json.loads(message.value)
                apply_filters(log_entry, config['filters'])
                forward_to_es(log_entry, es_client)
            except Exception as e:
                logging.error(f"Error processing log entry: {e}")

def apply_filters(log_entry, filters):
    for filter_name, filter_config in filters.items():
        if filter_name == 'regex':
            if re.search(filter_config['pattern'], log_entry['message']):
                yield log_entry
        elif filter_name == 'threshold':
            if int(log_entry['level']) >= filter_config['threshold']:
                yield log_entry

def forward_to_es(log_entry, es_client):
    es_index = config['es']['index']
    doc_id = f"{log_entry['timestamp']}-{log_entry['source']}"

    try:
        es_client.index(index=es_index, body=log_entry, id=doc_id)
    except Exception as e:
        logging.error(f"Error indexing log entry: {e}")

if __name__ == "__main__":
    import yaml
    process_log_files('config.yaml')
