        int splitIndex = node->getChildren().size() / 2;
        std::vector<std::shared_ptr<octree::Node>> children = node->getChildren();
        auto leftChild = std::make_shared<octree::Node>(children.size());
        auto rightChild = std::make_shared<octree::Node>(children.size());

