import json
import os
from collections import defaultdict
from hashlib import sha256

class JsonSerializable:
    _registry = defaultdict(dict)
    _instances = []

    def __new__(cls, id):
        if id not in cls._registry:
            raise ValueError(f"ID '{id}' is not registered.")
        return super().__new__(cls)

    @classmethod
    def register(cls, id):
        cls._registry[id] = cls

    @classmethod
    def deserialize(cls, data):
        try:
            instance = json.loads(data)
            return cls(**instance)
        except Exception as e:
            raise ValueError(f"Error deserializing: {e}")

    def serialize(self):
        data = self.__dict__
        return json.dumps(data)

class ForwardList:
    def __init__(self):
        self._list = []

    def insert_after(self, target, value, position=-1):
        try:
            index = self._find_index(target, position)
            self._insert(index + 1, value)
        except ValueError as e:
            print(f"Error: {e}")
        finally:
            return self._list

    def _find_index(self, target, position):
        if not isinstance(position, int) or position < -len(self._list):
            raise ValueError("Invalid position index.")
        for i, item in enumerate(self._list):
            if item == target and i == position:
                return i
        raise ValueError(f"Target '{target}' not found at position {position}.")

    def _insert(self, index, value):
        self._list.insert(index, value)

def load_json_files(directory, exclude=None):
    for file in os.listdir(directory):
        if file.endswith(".json"):
            try:
                with open(os.path.join(directory, file), "r") as f:
                    json_data = json.load(f)
                    # handle circular dependencies
                    pass
            except Exception as e:
                print(f"Error loading {file}: {e}")

def deserialize_and_hash(password):
    random_string = os.urandom(16).decode()
    hashed_password = sha256(password.encode()).hexdigest() + random_string
    return random_string, hashed_password

def process_directory(directory):
    file_types = {"text": 0, "log": 1, "CSV": 2, "compressed": 3, "JSON": 4}
    stats = {key: 0 for key in file_types}

    for file in os.listdir(directory):
        if file.endswith(".txt"):
            stats["text"] += len(open(os.path.join(directory, file), "r").read().splitlines())
        elif file.endswith((".log", ".csv", ".json")):
            try:
                with open(os.path.join(directory, file), "r") as f:
                    stats[file_types[os.path.splitext(file)[1][1:]]] += len(f.read().splitlines())
            except Exception as e:
                print(f"Error processing {file}: {e}")
        else:
            continue

    for key, value in stats.items():
        print(f"{key.capitalize()} files: {value} lines")

if __name__ == "__main__":
    load_json_files("/path/to/json/files")
    deserialize_and_hash("your_password")
    process_directory("/path/to/directory")

