#include <stdio.h>
#include <stdlib.h>
#include <inttypes.h>

// Helper function to find the largest integer in an array
int* find_max(int** arr, int len) {
    int* max = (int*)malloc(sizeof(int));
    *max = (*arr)[0];

    for (int i = 1; i < len; i++) {
        if ((*arr)[i] > *max) {
            *max = (*arr)[i];
        }
    }

    free(*arr);
    return max;
}

// Function to read a list of integers from standard input and find the largest
int* read_and_find_max() {
    int num_elements = 0, current_element;
    int** arr = NULL;
    uint64_t total_size = 0;

    // Read numbers until a negative number is encountered
    while (scanf("%d", &current_element) == 1 && current_element >= 0) {
        if ((total_size + sizeof(int)) > 50 * 1024 * 1024) {
            printf("Memory limit exceeded. Truncating the list.\n");
            break;
        }

        // Dynamically allocate memory for the array
        arr = (int**)realloc(arr, (num_elements + 1) * sizeof(int*));
        *arr = (int*)malloc(sizeof(int));
        **arr = current_element;

        total_size += sizeof(int);
        num_elements++;
    }

    if (!arr || !*(--arr)) {
        free(*arr);
        return NULL; // Return empty array
    }

    int* max = find_max(arr, num_elements);
    printf("The largest integer is: %d\n", *max);

    free(*arr);
    return max;
}

int main() {
    read_and_find_max();
    return 0;
}
