using System;
using System.Data.SqlClient;
using System.Collections.Generic;

public static void ExecuteDynamicSqlQuery(
    SqlConnection connection,
    string sqlTemplate,
    Dictionary<string, object> parameters)
{
    // Validate input parameters to prevent SQL injection attacks
    foreach (var parameter in parameters)
    {
        if (!parameter.Key.StartsWith("@"))
            throw new ArgumentException("Invalid parameter name");
    }

    // Generate the dynamic SQL query
    var sb = new StringBuilder();
    sb.Append(sqlTemplate);
    foreach (var parameter in parameters)
    {
        sb.AppendFormat(" {0} @{1}", parameter.Value, parameter.Key);
    }
    var sqlQuery = sb.ToString();

    try
    {
        // Execute the SQL query and retrieve the results
        using (var command = new SqlCommand(sqlQuery, connection))
        {
            foreach (var parameter in parameters)
            {
                command.Parameters.AddWithValue(parameter.Key, parameter.Value);
            }
            var reader = command.ExecuteReader();
            while (reader.Read())
            {
                // Process the result set as needed
            }
        }
    }
    catch (Exception ex)
    {
        // Log any errors that occur during query execution
        Console.WriteLine($"Error executing SQL query: {ex.Message}");
    }
}
