```rust
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use log::{info, error};

const DEFAULT_WORK_DIR: &str = "/tmp/file_processing_dir";
const CLEANUP_THRESHOLD_PERCENT: u32 = 20;

struct WorkDir {
    path: Arc<Mutex<PathBuf>>,
    metadata: Arc<Mutex<(i64, i64)>>,
}

impl WorkDir {
    fn new(prefix: Option<&str>) -> Self {
        let mut work_dir_path = DEFAULT_WORK_DIR.to_string();
        if let Some(prefix) = prefix {
            let mut random = rand::thread_rng();
            let dir_name = format!("{}/{}", prefix, random.gen::<u64>());
            work_dir_path = dir_name;
        }

        WorkDir {
            path: Arc::new(Mutex::new(PathBuf::from(work_dir_path))),
            metadata: Arc::new(Mutex::new((0, 0))),
        }
    }

    fn create(&self) -> std::io::Result<()> {
        fs::create_dir_all(&(*self.path).clone())?;
        (*self.path).lock().set_readwrite(true)?;
        info!("Work directory created at: {}", &*self.path);
        Ok(())
    }

    fn cleanup(&self, threshold_percent: u32) -> std::io::Result<()> {
        let disk_usage = fs::read_dir(&(*self.path).clone()).unwrap()
            .filter_map(|e| e.map_err(|_| ()))
            .count() as f64;

        if disk_usage > (1.0 - threshold_percent / 100.0) * fs::read_dir("/").unwrap().count() as f64 {
            let mut files = fs::read_dir(&(*self.path).clone()).unwrap()
                .filter_map(|e| e.map_err(|_| ()))
                .map(|entry| entry.unwrap().path())
                .filter(|path| path.extension().is_none());
            for file in files {
                if file.metadata().unwrap().modified() < std::time::SystemTime::now().duration_since(std::time::SystemTime::UNIX_EPOCH).unwrap().as_secs() as u64 * 1000 {
                    fs::remove_file(&file)?;
                }
            }
        }

        info!("Work directory cleaned up");
        Ok(())
    }

    fn monitor_disk_usage(&self) -> std::io::Result<()> {
        loop {
            let disk_usage = fs::read_dir("/").unwrap().count() as f64;
            if disk_usage > (1.0 - CLEANUP_THRESHOLD_PERCENT / 100.0) * fs::read_dir("/").unwrap().count() as f64 {
                self.cleanup(CLEANUP_THRESHOLD_PERCENT)?;
            }
            std::thread::sleep(std::time::Duration::from_millis(60000));
        }
    }

    fn record_metadata(&self, db: &mut sqlx::Pool<sqlx::Postgres>) -> Result<(), Box<dyn std::error::Error>> {
        let metadata = (*self.metadata).clone();
        db.execute("INSERT INTO work_dirs (path, created_at, last_cleanup) VALUES ($1, $2, $3)", |r| {
            r.bind(&(*self.path).as_path().display(), &metadata.0);
            r.bind(metadata.0, metadata.1);
            Ok(())
        })?;
        info!("Work directory metadata recorded in the database");
        Ok(())
    }
}

fn main() {
    let db = sqlx::Pool::connect("postgresql://user:password@localhost/database").unwrap();
    let work_dir = WorkDir::new(Some(env!("WORK_DIR_PREFIX")).as_ref());
    if !work_dir.create().is_ok() {
        error!("Failed to create work directory");
    }
    work_dir.record_metadata(&mut db);
    work_dir.monitor_disk_usage();
}
