import os
import time
import logging
from functools import wraps

class FileProcessor:
    def __init__(self, base_dir):
        self.base_dir = base_dir
        self.logger = logging.getLogger(__name__)
        self.retry_attempts = 3
        self.retry_delay = 1.0

    def create_directory(self, dir_path):
        @wraps(create_directory)
        def retry_decorator(func):
            def wrapper(*args, **kwargs):
                for _ in range(self.retry_attempts):
                    try:
                        return func(*args, **kwargs)
                    except OSError as e:
                        if e.errno == errno.EEXIST:  # directory already exists
                            continue
                        else:
                            raise
                self.logger.error(f"Directory creation failed after {self.retry_attempts} attempts")
                time.sleep(self.retry_delay)
                return wrapper

        @retry_decorator
        def create_directory(dir_path):
            if not os.path.exists(os.path.dirname(dir_path)):
                try:
                    os.makedirs(os.path.dirname(dir_path), exist_ok=True)
                except OSError as e:
                    raise
            return

    def process_file(self, file_name):
        dir_path = os.path.join(self.base_dir, os.path.dirname(file_name))
        if not os.path.exists(dir_path):
            self.create_directory(dir_path)

        # process the file here
        pass

    def get_status(self):
        dir_list = os.listdir(self.base_dir)
        status_dict = {}
        for file in dir_list:
            file_path = os.path.join(self.base_dir, file)
            if os.path.isfile(file_path):
                status_dict[file] = "processed"
            elif os.path.isdir(file_path):
                status_dict[file] = "in_progress"
            else:
                status_dict[file] = "failed"

        return status_dict

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    file_processor = FileProcessor("/path/to/base/directory")
    try:
        file_processor.process_file("file_name.txt")
    except Exception as e:
        print(f"Error: {e}")

    status = file_processor.get_status()
    print(status)
