using System;
using System.Net.Http;
using System.Threading.Tasks;

public class PageUpdater
{
    private readonly ICacheService _cacheService;
    private readonly IMessageQueue _messageQueue;

    public PageUpdater(ICacheService cacheService, IMessageQueue messageQueue)
    {
        _cacheService = cacheService;
        _messageQueue = messageQueue;
    }

    public async Task<HttpResponseMessage> UpdatePageSectionAsync(string sectionId, string elementId, string content)
    {
        if (string.IsNullOrEmpty(sectionId))
            throw new ArgumentException("Section ID is required");

        if (string.IsNullOrEmpty(elementId))
            throw new ArgumentException("Element ID is required");

        if (string.IsNullOrEmpty(content))
            throw new ArgumentException("Content is required");

        try
        {
            await _cacheService.UpdateAsync(sectionId, elementId, content);
            await _messageQueue.EnqueueAsync();
            return new HttpResponseMessage { StatusCode = HttpStatusCode.OK };
        }
        catch (Exception ex)
        {
            // Log the failure and return an error response
            return new HttpResponseMessage { StatusCode = HttpStatusCode.InternalServerError, ReasonPhrase = "Update failed" };
