function renderScripts(scripts) {
  let html = '';
  for (const script of scripts) {
    if (!script.code || !script.type) continue;
    html += `<script id="${script.key}" type="${script.type}">${script.innerHTML}</script>`;
  }
  return html;
}

async function loadAndRenderScripts() {
  const spinner = document.getElementById('spinner');
  let renderedScripts = '';
  try {
    const response = await fetch('https://api.example.com/scripts');
    if (!response.ok) throw new Error('Failed to load scripts');

    const scripts = await response.json();
    renderedScripts = renderScripts(scripts);
    spinner.classList.add('hide');
  } catch (error) {
    // Handle network issues, timeouts, and unexpected responses
    spinner.classList.remove('hide');
    setTimeout(() => {
      tryAgain();
    }, 1000);
  }
}

function tryAgain() {
  loadAndRenderScripts();
}
