    private readonly ConcurrentBag<string> _availablePorts = new ConcurrentBag<string>();
    private readonly ILogger _logger;
    private readonly AzureAppConfigurationService _azureConfigService;

    public WebApplicationManager(ILogger logger, AzureAppConfigurationService azureConfigService)
    {
        _logger = logger;
        _azureConfigService = azureConfigSiteNamePattern = @"^[a-zA-Z0-9]+$";

        // Initialize available ports with all possible numbers
        for (int i = 80; i <= 65535; i++)
        {
            _availablePorts.Add(i.ToString());
        }
    }

    public async Task AddWebApplicationAsync(string directoryPath, string siteName)
    {
        if (!await ValidateDirectoryPathAsync(directoryPath))
        {
            throw new Exception("Invalid or inaccessible directory path");
        }

        if (!await ValidateSiteNameAsync(siteName))
        {
            throw new ArgumentException("Invalid site name", nameof(siteName));
        }

        // Get the next available port
        string port = await GetAvailablePortAsync();

        // Configure web application settings from Azure App Configuration
        var configSettings = await _azureConfigService.GetAppSettingAsync("WebApplicationSettings");

        // Create a new web.config file and integrate with external configuration management service
        using (var webConfigFile = File.Create(directoryPath + "\\web.config"))
        {
            using (var writer = XmlWriter.Create(webConfigFile, new XmlWriterSettings { Indent = true }))
            {
                writer.WriteStartDocument();
                writer.WriteStartElement("configuration");
                writer.WriteStartElement("system.webServer");

                // Add site name and port to web.config
                writer.WriteElementString("siteName", siteName);
                writer.WriteElementString("port", port);

                // ... add other configuration settings ...
                writer.WriteEndElement(); // system.webServer
                writer.WriteEndElement(); // configuration
                writer.WriteEndDocument();
            }
        }

        // Start the web application process
        using (var process = new Process())
        {
            process.StartInfo.FileName = "dotnet";
            process.StartInfo.Arguments = $"run --port {port} --siteName {siteName}";
            process.Start();

            // Monitor and manage the lifecycle of spawned processes
            await Task.Run(() =>
            {
                while (process.HasExited == false)
                {
                    Thread.Sleep(1000);
                }
            });
        }

        // Schedule health checks for the new web application
        _logger.LogInformation("Web application '{siteName}' started on port {port}", siteName, port);

        // ... implement health check mechanism ...
    }

    private async Task<string> GetAvailablePortAsync()
    {
        while (true)
        {
            string port = _availablePorts.Take(1).FirstOrDefault();
            if (!string.IsNullOrEmpty(port))
            {
                return port;
            }
            await Task.Delay(100);
        }
    }
}
