// Cargo.toml dependencies:
[dependencies]
env_logger = "0.9.0"
log = "0.4.14"
walkdir = "2.3.1"

use env_logger::EnvLogger;
use log::{info, warn};
use std::path::{Path, PathBuf};
use walkdir::WalkDir;

// File management utility
struct FileManager {
    work_dir: Option<PathBuf>,
    plugins: Vec<Box<dyn Fn() + Send>>,
}

impl FileManager {
    fn new() -> Self {
        let mut file_manager = FileManager {
            work_dir: None,
            plugins: vec!(),
        };

        if let Some(work_dir) = std::env::var("WORK_DIR").ok().and_then(|s| s.parse::<PathBuf>().ok()) {
            if work_dir.exists() && work_dir.is_dir() {
                file_manager.work_dir = Some(work_dir);
            } else {
                warn!("Invalid or non-existent WORK_DIR: {}", work_dir.display());
            }
        }

        // Create a new temporary directory under /tmp with a unique name
        if file_manager.work_dir.is_none() {
            let temp_dir = tempfile::tempdir().unwrap();
            file_manager.work_dir = Some(temp_dir.path().to_path_buf());
        }

        file_manager
    }

    fn run(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        // Run pipeline execution, ensuring accessibility during runtime
        for plugin in &self.plugins {
            (plugin)();
        }

        // Clean up the working directory after pipeline completion
        if let Some(work_dir) = &self.work_dir {
            fs::remove_dir_all(work_dir)?;
        }

        Ok(())
    }
}

// Plugin system integration
trait Plugin {
    fn run(&mut self);
}

impl Plugin for Box<dyn Fn() + Send> {
    fn run(&mut self) {
        (self)();
    }
}

