use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::thread;
use std::time::{Duration, Instant};

struct DirectoryManager {
    dir_path: String,
    cleanup_policy: Box<dyn Fn()>,
}

impl DirectoryManager {
    fn new(custom_prefix: &str) -> Self {
        let my_dir_path = env::var("MY_DIR_PATH").unwrap_or_else(|_| {
            fs::create_dir_all("/tmp/my_dir").unwrap();
            "/tmp/my_dir".to_string()
        });
        let dir_path = format!("{}/{}", custom_prefix, "my_dir");
        DirectoryManager { 
            dir_path,
            cleanup_policy: Box::new(|| {}),
        }
    }

    fn start_cleanup(&self) {
        thread::spawn(move || loop {
            self.cleanup_policy();
            thread::sleep(Duration::from_secs(60 * 10)); // clean up every 10 minutes
        });
    }

    fn monitor_disk_usage(&self) {
        let disk_usage = fs::read_dir(self.dir_path.clone())
            .unwrap()
            .count() as f64;
        if disk_usage > 0.8 {
            self.start_cleanup();
        }
    }
}

fn main() {
    let mut directory_manager = DirectoryManager::new("my_app");
    directory_manager.monitor_disk_usage();
}
