public class PaymentProcessor {
    private static final AtomicInteger PAYMENT_ATTEMPTS = new AtomicInteger(0);
    private static final int MAX_PAYMENT_RETRIES = 3;
    private static final int REFUND_MAX_ATTEMPTS = 5;
    private static final double MAX_REFUND_AMOUNT = 100.0;

    public void processPayment(String paymentMethod, double amount, String orderId) {
        if (!validatePaymentMethod(paymentMethod)) {
            logError("Invalid payment method: " + paymentMethod);
            return;
        }
        if (amount < 1 || amount > 1000) {
            logError("Invalid payment amount: " + amount);
            return;
        }
