using XPathParserAndValidator;

public class XPathParserAndValidator
{
    private readonly ILRUCache<string, XmlDocument> _cache = new LRUCache<string, XmlDocument>();
    private readonly ILogger _logger;

    public XPathParserAndValidator(ILogger logger)
    {
        _logger = logger;
    }

    public void ValidateAndParse(string xmlString, string xpathQuery, string schemaPath)
    {
        // User input validation for XPath query
        var syntaxTree = new SyntaxTree(xpathQuery);

        // Parse XML using XPath and optimize for large files through streaming
        var xslCompiledTransform = new XslCompiledTransform();
        var streamReader = new StreamReader(schemaPath);
        var schemaDocument = XslSchemaManager.Current.Compile(xslCompiledTransform, streamReader.ReadToEnd());
        streamReader.Close();

        try
        {
            // Fetch XML from external API and validate against provided schema
            var xmlDocument = _cache.GetOrAdd(xmlString, () =>
            {
                var response = MakeApiCall(xmlString);
                if (response.IsSuccessStatusCode)
                {
                    return ParseXml(response.Content);
                }
                throw new Exception("Failed to fetch XML");
            });

            // XPath parsing and validation against provided schema
            var node = xslCompiledTransform.Transform(xmlDocument, null);

            // Check for first element that matches given name
            var result = node.SelectSingleNode(xpathQuery);
            if (result == null)
                throw new Exception("No match found");

            if (node.SelectNodes(xpathQuery).Count() > 1)
                throw new Exception("Multiple matches found");
        }
        catch (Exception ex) when (_logger.LogError(ex))
        {
            // Log detailed information about each operation
            _logger.LogInformation($"XPath query: {xpathQuery}, XML string: {xmlString}, Schema path: {schemaPath}");
            _logger.LogInformation($"Cache hits/misses: {_cache.HitCount}/{_cache.MissCount}");
            _logger.LogInformation($"Schema validation result: {(schemaDocument.Validate(xmlDocument) ? "Valid" : "Invalid")}");
        }
    }

