}

public class LRUCache<TKey, TValue>
{
    private readonly Dictionary<TKey, TValue> _cache;
    private readonly LinkedList<TKey> _lruList;

    public LRUCache()
    {
        _cache = new Dictionary<TKey, TValue>();
        _lruList = new LinkedList<TKey>();
    }

    public TValue GetOrAdd(TKey key, Func<TValue> valueFactory)
    {
        if (_cache.TryGetValue(key, out var cachedValue))
            return cachedValue;

        var newValue = valueFactory();
        _cache[key] = newValue;
        _lruList.AddFirst(key);

        if (_cache.Count > 20) // Implement LRU strategy to remove the least recently used entry
        {
            var oldestEntry = _lruList.Last();
            _lruList.Remove(oldestEntry);
            _cache.Remove(oldestEntry);
        }

        return newValue;
    }

    public int HitCount { get; set; }
    public int MissCount { get; set; }
}

