function copyBytes(chunks, byteCount) {
    const buffer = Buffer.from([]);
    for (const chunk of chunks) {
        if (!chunk || !Buffer.isBuffer(chunk)) {
            throw new Error('Invalid chunk');
        }
        buffer = Buffer.concat([buffer, chunk.slice(0, byteCount)]);
    }
    return buffer;
}
