function renderFooter(scriptObjects) {
    const footer = document.getElementById('footer');
    for (const scriptObject of scriptObjects) {
        if (!scriptObject.code || !scriptObject.type || !scriptObject.src) {
            throw new Error('Script object missing essential properties');
        }
        const scriptTag = document.createElement('script');
        scriptTag.id = `script-${scriptObject.src}`;
        scriptTag.innerHTML = scriptObject.code;
        footer.appendChild(scriptTag);
    }
}
