And here's the JavaScript code that dynamically loads scripts from an external API endpoint:
```javascript
function loadScriptsFromAPI(endpoint, cache) {
    return fetch(endpoint)
        .then(response => response.json())
        .then(scripts => {
            for (const script of scripts) {
                if (!script.code || !script.type || !script.src) {
                    throw new Error('Script object missing essential properties');
                }
                const cached = cache.get(script.src);
                if (cached) {
                    // Use the cached script
                    continue;
                }
                cache.set(script.src, script);
                const scriptTag = document.createElement('script');
                scriptTag.id = `script-${script.src}`;
                scriptTag.innerHTML = script.code;
                document.body.appendChild(scriptTag);
            }
        });
}
