# Define a function to manage resources efficiently
def manage_resources():
    try:
        v1 = client.V1Api()
        nodes = v1.list_node().items
        for node in nodes:
            if node.status.available_pods > 0:
                print(f"Node {node.metadata.name} has available pods: {node.status.available_pods}")
    except kubernetes.client.ApiException as e:
