namespace ServiceController
{
    class Program
    {
        static void Main(string[] args)
        {
            try
            {
                // Load configuration settings from XML file
                XDocument configXml = XDocument.Load("config.xml");
                int tileSize = int.Parse(configXml.Root.Element("Tile").Attribute("Size").Value);
                int worldWidth = int.Parse(configXml.Root.Element("World").Attribute("Width").Value);
                int worldHeight = int.Parse(configXml.Root.Element("World").Attribute("Height").Value);
                int cameraSpeed = int.Parse(configXml.Root.Element("Camera").Attribute("Speed").Value);

                // Start service with random delay
                Random rand = new Random();
                while (true)
                {
                    System.Threading.Thread.Sleep(rand.Next(1000, 5000));
                    ServiceController.Start("MyService");
                    System.Threading.Thread.Sleep(cameraSpeed * 1000);
                    ServiceController.Stop("MyService");

                    // Send message to messaging system when service is stopped
                    WebRequest request = WebRequest.CreateHttp("https://messaging-system.com/messages");
                    request.Method = "POST";
                    request.ContentType = "text/xml";
                    request.ContentLength = Encoding.UTF8.GetBytes($"<?xml version=\"1.0\" encoding=\"UTF-8\"?><message>MyService has been stopped!</message>").Length;
                    Stream stream = request.GetRequestStream();
                    byte[] buffer = Encoding.UTF8.GetBytes($"<?xml version=\"1.0\" encoding=\"UTF-8\"?><message>MyService has been stopped!</message>");
                    stream.Write(buffer, 0, buffer.Length);
                }
            }
            catch (FileNotFoundException)
            {
                Console.WriteLine("Config file not found!");
            }
            catch (XmlException)
            {
                Console.WriteLine("Invalid XML configuration!");
            }
            catch (WebException ex)
            {
                Console.WriteLine($"Error sending message: {ex.Message}");
            }
        }
    }
}
