#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <ifaddrs.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>

#define DNS_SERVERS_MAX 5
#define MAX_HOSTNAME_LENGTH 256
#define DNS_RECORD_TYPES_MAX 10

typedef enum {
    DNS_QUERY_SUCCESS,
    DNS_QUERY_FAILURE,
    DNS_QUERY_TIMEOUT,
} dns_query_status;

typedef struct {
    char* hostname;
    u_char* ip_addresses;
    int num_ip_addresses;
} dns_resolution_result;

int main() {
    // Initialize configuration
    int dns_server_count = 3;
    char** dns_servers = malloc(dns_server_count * sizeof(char*));
    for (int i = 0; i < dns_server_count; i++) {
        dns_servers[i] = malloc(strlen("8.8.8.8") + 1);
        strcpy(dns_servers[i], "8.8.8.8");
    }

    // Perform DNS resolution
    u_char* ip_addresses;
    int num_ip_addresses;

    for (int i = 0; i < dns_server_count; i++) {
        // Perform query
        struct hostent* host = gethostbyname(dns_servers[i]);
        if (!host) {
            continue;
        }

        // Validate IP addresses
        ip_addresses = malloc(host->h_addrtype * sizeof(u_char));
        num_ip_addresses = 0;

        for (struct in_addr* in_addr = (struct in_addr*)host->h_addr; in_addr < (struct in_addr*)host->h_addr + host->h_length; in_addr++) {
            if (inet_ntop(AF_INET, in_addr, NULL, 0) == NULL) {
                continue;
            }
            ip_addresses[num_ip_addresses++] = *in_addr;
        }

        // Log query outcome
        printf("DNS resolution for %s at server %s: %d IP addresses resolved\n", dns_servers[i], inet_ntop(AF_INET, in_addr, NULL, 0), num_ip_addresses);
    }

    // Clean up resources
    free(ip_addresses);
    for (int i = 0; i < dns_server_count; i++) {
        free(dns_servers[i]);
    }
    free(dns_servers);

    return 0;
}

