import org.apache.commons.lang3.StringUtils;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;
import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.ArrayList;
import java.util.List;

public class WebSocketConfigParser {

    public static WebSocketConfig parseWebSocketConfig(String url) throws IOException {
        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(url))
                .GET()
                .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

        Document doc = Jsoup.parse(response.body());
        WebSocketConfig config = new WebSocketConfig();

        // Extract configuration settings
        Element rootElement = doc.documentElement();
        NodeList childNodes = rootElement.getChildNodes();
        for (int i = 0; i < childNodes.getLength(); i++) {
            Element childNode = (Element) childNodes.item(i);
            if ("serverPort".equals(childNode.getTagName())) {
                config.setServerPort(Integer.parseInt(childNode.getText()));
            } else if ("allowedOrigins".equals(childNode.getTagName())) {
                NodeList originsList = childNode.getChildNodes();
                List<String> allowedOrigins = new ArrayList<>();
                for (int j = 0; j < originsList.getLength(); j++) {
                    Element origin = (Element) originsList.item(j);
                    allowedOrigins.add(origin.getText());
                }
                config.setAllowedOrigins(allowedOrigins);
            } else if ("maxConnections".equals(childNode.getTagName())) {
                config.setMaxConnections(Integer.parseInt(childNode.getText()));
            } else if ("timeout".equals(childNode.getTagName())) {
                config.setTimeout(Integer.parseInt(childNode.getText()));
            } else if ("cipherSuites".equals(childNode.getTagName())) {
                NodeList cipherSuitesList = childNode.getChildNodes();
                List<String> cipherSuites = new ArrayList<>();
                for (int j = 0; j < cipherSuitesList.getLength(); j++) {
                    Element cipherSuite = (Element) cipherSuitesList.item(j);
                    cipherSuites.add(cipherSuite.getText());
                }
                config.setCipherSuites(cipherSuites);
            } else if ("sslCertPath".equals(childNode.getTagName())) {
                config.setSslCertPath(childNode.getText());
            } else if ("sslKeyPath".equals(childNode.getTagName())) {
                config.setSslKeyPath(childNode.getText());
            } else if ("heartbeatInterval".equals(childNode.getTagName())) {
                config.setHeartbeatInterval(Integer.parseInt(childNode.getText()));
            }
        }

        return config;
    }
}
