```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    int extraSamples;
} TiffInfo;

TiffInfo* parseTIFF(const char* filePath) {
    FILE* file = fopen(filePath, "rb");
    if (!file) {
        return NULL; // Error opening file
    }

    TiffInfo* info = (TiffInfo*)malloc(sizeof(TiffInfo));

    // Read bits per sample and samples per pixel
    int headerSize;
    fread(&headerSize, sizeof(int), 1, file);
    fread(&info->bitsPerSample, sizeof(int), 1, file);
    fread(&info->samplesPerPixel, sizeof(int), 1, file);

    if (info->bitsPerSample < 1 || info->bitsPerSample > 16) {
        fclose(file);
        free(info);
        return NULL; // Error: unsupported bits per sample
    }

    // Check for extra samples
    int numSamples;
    fread(&numSamples, sizeof(int), 1, file);
    if (numSamples != info->samplesPerPixel) {
        info->extraSamples = numSamples - info->samplesPerPixel;
    } else {
        info->extraSamples = 0;
    }

    fclose(file);

    return info;
}
