**node.js module loader**
```javascript
const fs = require('fs');
const path = require('path');
const modules = {};

function loadModule(moduleName, context) {
    if (modules[moduleName]) {
        return modules[moduleName];
    }

    try {
        const modulePath = path.join(__dirname, '..', `/${moduleName}.js`);
        const module = require(modulePath)(context);
        modules[moduleName] = module;
        return module;
    } catch (err) {
        console.error(`Error loading module ${moduleName}: ${err}`);
        return null;
    }
}

function loadModules(config, context) {
    if (!config || config.length === 0) {
        return [];
    }

    const modulesList = [];

    for (const moduleName of config) {
        try {
            const module = loadModule(moduleName, context);
            if (!module) {
                throw new Error(`Failed to load module ${moduleName}`);
            }
            modulesList.push(module);
        } catch (err) {
            console.error(`Error loading module ${moduleName}: ${err}`);
        }
    }

    return modulesList;
}
