function reduce(arr, initialValue, callback) {
  let accumulator = initialValue;

  for (const num of arr) {
    try {
      accumulator = callback(accumulator, num);
    } catch (err) {
      console.error(`Error during reduction: ${err}`);
      return null;
    }
  }

  return accumulator;
}

// Example usage
const numbers = [1, 2, 3, 4, 5];
const initialValue = 0;

try {
  const result = reduce(numbers, initialValue, (acc, current) => acc + current);
  console.log(`Final reduced value: ${result}`);
} catch (err) {
  console.error(`Error during reduction: ${err}`);
}
