import os
from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from werkzeug.utils import secure_filename
import requests
import json
from concurrent.futures import ThreadPoolExecutor

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///uploads.db'
db = SQLAlchemy(app)

class File(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    uploaded_at = db.Column(db.DateTime, default=db.func.current_timestamp())
    processed_at = db.Column(db.DateTime)
    status = db.Column(db.String(20), nullable=False, default='pending')

@app.route('/upload', methods=['POST'])
def upload_file():
    if request.method == 'POST':
        file = request.files['file']
        filename = secure_filename(file.filename)
        file.save(os.path.join('uploads', filename))
        file_id = File(name=filename).id
        db.session.commit()
        return jsonify({'id': file_id, 'status': 'pending'})

@app.route('/process', methods=['POST'])
def process_file():
    if request.method == 'POST':
        file_id = int(request.form['file_id'])
        file = File.query.get(file_id)
        if file.status != 'processed':
            # Asynchronous processing
            with ThreadPoolExecutor() as executor:
                future = executor.submit(process_file_async, file_id)
                return jsonify({'id': file_id, 'status': 'processing'})
        else:
            return jsonify({'id': file_id, 'status': 'processed'})

@app.route('/status', methods=['GET'])
def get_status():
    if request.method == 'GET':
        file_id = int(request.args.get('file_id'))
        file = File.query.get(file_id)
        if file:
            return jsonify({'id': file_id, 'status': file.status})
        else:
            return jsonify({'error': 'File not found'})

@app.route('/processed', methods=['GET'])
def get_processed():
    if request.method == 'GET':
        files = File.query.filter_by(status='processed').all()
        results = []
        for file in files:
            result = {'id': file.id, 'name': file.name, 'processed_at': file.processed_at}
            results.append(result)
        return jsonify(results)

def process_file_async(file_id):
    # External API call to validate and process the file
    file = File.query.get(file_id)
    if file.status != 'processed':
        try:
            response = requests.post('https://api-validation.com/validate', json={'file': file.name})
            if response.status_code == 200:
                file.processed_at = datetime.now()
                file.status = 'processed'
                db.session.commit()
        except Exception as e:
            file.status = 'error'
            file.error_message = str(e)
            db.session.commit()
    return

if __name__ == '__main__':
    app.run(debug=True)

