import os
import logging
import time
from logging.handlers import RotatingFileHandler
from retrying import retry
from configparser import ConfigParser
from collections import defaultdict

def init_logging_config(env_vars, config_service):
    log_dir = env_vars.get('LOG_DIR', '/var/log')
    max_bytes = int(env_vars.get('MAX_BYTES', 10*1024*1024))
    backup_count = int(env_vars.get('BACKUP_COUNT', 5))
    max_age_days = int(env_vars.get('MAX_AGE_DAYS', 30))

    logger = logging.getLogger()
    logger.setLevel(logging.INFO)

    formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')

    if not os.path.exists(log_dir):
        @retry(wait_exponential_multiplier=1000, stop_max_attempt_number=5)
        def create_log_dir():
            try:
                os.makedirs(log_dir)
            except OSError as e:
                raise

        create_log_dir()

    rotating_handler = RotatingFileHandler(os.path.join(log_dir, 'app.log'), 
                                            maxBytes=max_bytes, backupCount=backup_count)
    rotating_handler.setFormatter(formatter)

    logger.addHandler(rotating_handler)

    # External logging aggregation service
    aggregator = AggregatorService('https://example.com/aggregator')

    def rotate_and_send_logs():
        for _, handler in logger.handlers.items():
            if isinstance(handler, RotatingFileHandler):
                handler.doRollover()
                aggregator.send_logs(os.path.join(log_dir, 'app.log'))

    @retry(wait_exponential_multiplier=1000, stop_max_attempt_number=5)
    def clean_up_logs():
        try:
            for f in os.listdir(log_dir):
                file_path = os.path.join(log_dir, f)
                if not os.path.getsize(file_path) > 0 and time.time() - os.path.getctime(file_path) > max_age_days*24*60*60:
                    os.remove(file_path)
        except OSError as e:
            raise

    def configure_logging_levels():
        levels = {'DEBUG': logging.DEBUG, 'INFO': logging.INFO, 'WARNING': logging.WARNING, 
                  'ERROR': logging.ERROR, 'CRITICAL': logging.CRITICAL}
        for level, value in env_vars.items():
            if level.upper() in levels:
                logger.setLevel(levels[level.upper()])

    def configure_logging_formats():
        formats = {'JSON': logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s'),
                   'TEXT': logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')}
        for format_name, value in env_vars.items():
            if format_name.upper() in formats:
                logger.formatter = formats[format_name.upper()]

    def distribute_tasks():
        from multiprocessing import Process
        processes = []
        for instance_id in range(1, int(env_vars.get('NUM_INSTANCES', 1))+1):
            process = Process(target=rotate_and_send_logs)
            processes.append(process)
            process.start()
        for p in processes:
            p.join()

    configure_logging_levels()
    configure_logging_formats()
    distribute_tasks()
