    public void processFileBatchWithValidationAndMetadata(String inputDirectory, String outputDirectory, List<Rule> validationRules, MetadataExtractionService metadataService) throws Exception {
        // Dynamically load and instantiate validation rule classes
        List<Rule> loadedRules = new ArrayList<>();
        for (Rule rule : validationRules) {
            loadedRules.add(rule.getClass().newInstance());
        }

        // Create a thread pool to manage concurrency
        ExecutorService executor = Executors.newFixedThreadPool(10);

        // Process files in parallel
        File[] files = new File(inputDirectory).listFiles();
        for (File file : files) {
            try {
                // Validate and extract metadata for each file
                RuleExecutor ruleExecutor = new RuleExecutor(file, loadedRules, metadataService);
                executor.submit(ruleExecutor);
            } catch (IOException e) {
                System.out.println("Error processing file: " + file.getName());
            }
        }

        // Shutdown the thread pool
        executor.shutdown();
    }

    private class RuleExecutor implements Runnable {
        private File file;
        private List<Rule> rules;
        private MetadataExtractionService metadataService;

        public RuleExecutor(File file, List<Rule> rules, MetadataExtractionService metadataService) {
            this.file = file;
            this.rules = rules;
            this.metadataService = metadataService;
        }

        @Override
        public void run() {
            try {
                // Validate the file against all loaded rules
                for (Rule rule : rules) {
                    if (!rule.validate(file)) {
                        System.out.println("File " + file.getName() + " failed validation with rule: " + rule.getClass().getSimpleName());
                        return;
                    }
                }

                // Extract metadata from the file and store it alongside the validated file
                Map<String, String> metadata = metadataService.extractMetadata(file);
                File outputfile = new File(outputDirectory, file.getName());
                Files.write(Files.readAllBytes(Paths.get(file.getAbsolutePath())), Paths.get(outputfile.getAbsolutePath()));
                metadata.forEach((key, value) -> {
                    try (FileWriter writer = new FileWriter(new File(outputDirectory, key + ".txt"))) {
                        writer.write(value);
                    } catch (IOException e) {
                        System.out.println("Error writing metadata to file: " + outputfile.getName());
                    }
                });

                // Log the end of each validation and metadata extraction process
                System.out.println("File " + file.getName() + " processed successfully");
            } catch (Exception e) {
                // Handle exceptions gracefully, logging detailed error messages
                System.out.println("Error processing file: " + file.getName());
                e.printStackTrace();
            }
        }
    }
}
