        if service_name in self.services:
            self.configured_service = self.services[service_name]
        else:
            print(f"Service {service_name} not found. Falling back to {self.default_service}.")
            self.configured_service = self.services[self.default_service]

    def upload_file(self, file_path):
        if self.configured_service['service'] == 's3':
            s3 = get_session().client('s3')
            bucket_name = 'your-bucket-name'
            s3.upload_file(file_path, bucket_name)
        elif self.configured_service['service'] == 'storage':
            gcs_client = gcs.Client()
            bucket = gcs_client.bucket('your-bucket-name')
            blob = bucket.blob(file_path.split('/')[-1])
            blob.upload_from_string(open(file_path, 'rb').read())
        elif self.configured_service['service'] == 'blob':
            blob_service_client = BlobServiceClient.from_connection_string(
                f"DefaultEndpointsProtocol=https;AccountName={self.configured_service['account_name']};AccountKey=your-account-key;"
            )
            container_client = blob_service_client.get_container_client('your-container-name')
            blob_client = container_client.get_blob_client(file_path.split('/')[-1])
            with open(file_path, 'rb') as f:
                blob_client.upload_blob(f.read(), overwrite=True)

    def download_file(self, file_path):
        if self.configured_service['service'] == 's3':
            s3 = get_session().client('s3')
            bucket_name = 'your-bucket-name'
            response = s3.get_object(Bucket=bucket_name, Key=file_path)
            with open(file_path, 'wb') as f:
                f.write(response['Body'].read())
        elif self.configured_service['service'] == 'storage':
            gcs_client = gcs.Client()
            bucket = gcs_client.bucket('your-bucket-name')
            blob = bucket.blob(file_path.split('/')[-1])
            with open(file_path, 'wb') as f:
                f.write(blob.download_as_string().encode())
        elif self.configured_service['service'] == 'blob':
            blob_service_client = BlobServiceClient.from_connection_string(
                f"DefaultEndpointsProtocol=https;AccountName={self.configured_service['account_name']};AccountKey=your-account-key;"
            )
            container_client = blob_service_client.get_container_client('your-container-name')
            blob_client = container_client.get_blob_client(file_path.split('/')[-1])
            with open(file_path, 'wb') as f:
                f.write(blob_client.download_blob().read())

    def start_upload_thread(self):
        for file in files_to_upload:
            thread = threading.Thread(target=self.upload_file, args=(file,))
            thread.start()

    def start_download_thread(self):
        for file in files_to_download:
            thread = threading.Thread(target=self.download_file, args=(file,))
            thread.start()

    def collect_metrics(self):
        if self.configured_service['service'] == 's3':
            s3 = get_session().client('s3')
            bucket_name = 'your-bucket-name'
            latency = s3.get_object(Bucket=bucket_name, Key='latency.txt')['Latency']
            speed = s3.get_object(Bucket=bucket_name, Key='speed.txt')['Speed']
        elif self.configured_service['service'] == 'storage':
