            blob = bucket.blob('speed.txt')
            speed = float(blob.download_as_string().decode())
        elif self.configured_service['service'] == 'blob':
            blob_service_client = BlobServiceClient.from_connection_string(
                f"DefaultEndpointsProtocol=https;AccountName={self.configured_service['account_name']};AccountKey=your-account-key;"
            )
            container_client = blob_service_client.get_container_client('your-container-name')
            blob_client = container_client.get_blob_client('latency.txt')
            latency = float(blob_client.download_blob().read().decode())
            blob_client = container_client.get_blob_client('speed.txt')
            speed = float(blob_client.download_blob().read().decode())
        self.metrics['latency'].append(latency)
        self.metrics['speeds'].append(speed)

    def monitor_queue_sizes(self):
        if self.configured_service['service'] == 's3':
            s3 = get_session().client('s3')
            bucket_name = 'your-bucket-name'
            queue_size = len(s3.list_objects(Bucket=bucket_name))
        elif self.configured_service['service'] == 'storage':
            gcs_client = gcs.Client()
            bucket = gcs_client.bucket('your-bucket-name')
            queue_size = len(list(bucket.list_blobs()))
        elif self.configured_service['service'] == 'blob':
            blob_service_client = BlobServiceClient.from_connection_string(
                f"DefaultEndpointsProtocol=https;AccountName={self.configured_service['account_name']};AccountKey=your-account-key;"
            )
            container_client = blob_service_client.get_container_client('your-container-name')
            queue_size = len(list(container_client.list_blobs()))
        self.queue_sizes.append(queue_size)

    def report_metrics(self):
        print(f"Latency: {sum(self.metrics['latency']) / len(self.metrics['latency'])}")
        print(f"Speeds: {sum(self.metrics['speeds']) / len(self.metrics['speeds'])}")
        print(f"Queue sizes: {self.queue_sizes}")

    def recover_from_errors(self):
        if self.error_counts['transient']:
            time.sleep(1)
        elif self.error_counts['permanent']:
            print("Permanent error. Aborting operations.")
