```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using UnityEngine;

public interface IRandomDistribution
{
    float Generate(float min, float max);
}

public abstract class RandomDistribution : IRandomDistribution
{
    public abstract float Generate(float min, float max);
}

public class UniformDistribution : RandomDistribution
{
    public override float Generate(float min, float max)
    {
        return UnityEngine.Random.Range(min, max);
    }
}

public class GaussianDistribution : RandomDistribution
{
    private const float Mean = 0f;
    private const float StandardDeviation = 1f;

    public override float Generate(float min, float max)
    {
        float value = (float)Normal.Next();
        return Mathf.Min(Mathf.Max(value * StandardDeviation + Mean, min), max);
    }
}

public class CustomRandomGenerator
{
    private readonly IRandomDistribution _distribution;
    private readonly UnityEngine.Random _random;
    private readonly object _lock = new object();

    public CustomRandomGenerator(int seed)
    {
        _random = new UnityEngine.Random(seed);
        _distribution = new UniformDistribution();
    }

    public float Generate(float min, float max, RangeType rangeType)
    {
        lock (_lock)
        {
            if (min > max && rangeType == RangeType.Closed)
                throw new ArgumentException("Min value cannot be greater than Max value for a closed range.");

            return _distribution.Generate(min, max);
        }
    }

    public enum RangeType
    {
        Open,
        Closed,
        HalfOpen
    }

    public class CustomRange
    {
        public float Min { get; set; }
        public float Max { get; set; }
        public RangeType Type { get; set; }
    }

    public void SetSeed(int seed)
    {
        _random.Seed = seed;
    }
}

public class Normal : IRandomGenerator
{
    private readonly RandomNumberGenerator _generator;

    public Normal()
    {
        _generator = RandomNumberGenerator.Create();
    }

    public static Random.Next()
    {
        return (float)_generator.NextDouble();
    }
}
