        for feedback in feedbacks:
            if not hasattr(feedback, 'user_id') or not hasattr(feedback, 'rating'):
                # Handle missing properties
                feedback.user_id = 0  # Default user ID
                feedback.rating = 3  # Default rating

            if not feedback.feedback_text.strip():
                raise ValueError('Feedback text cannot be empty')

            if not (1 <= feedback.rating <= 5):
                raise ValueError('Rating must be between 1 and 5')

            try:
                await db_conn.execute("INSERT INTO feedbacks SET user_id = ?, feedback_text = ?, rating = ?", 
                                        (feedback.user_id, feedback.feedback_text, feedback.rating))

                if feedback.rating < 3:
                    # Send notification to admin team
                    await send_notification(feedback)

            except Exception as e:
                # Handle database connection errors and retry logic
                while True:
                    try:
                        await db_conn.execute("INSERT INTO feedbacks SET user_id = ?, feedback_text = ?, rating = ?", 
                                            (feedback.user_id, feedback.feedback_text, feedback.rating))
                        break
                    except Exception as e:
