#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define BUFFER_SIZE 1024
#define MAX_FIELDS 10
#define AVG_WINDOW 3

typedef struct {
    char timestamp[20];
    char server_id[20];
    char event_type[20];
    int num_fields[MAX_FIELDS];
} log_entry;

log_entry *current_entry;
int current_position = 0;
pthread_mutex_t buffer_lock;
pthread_cond_t entry_available;
int entries_processed = 0;

void* process_log_entry(void* arg) {
    log_entry *entry = (log_entry*)arg;
    int sum = 0, avg;

    // Calculate average of last three numeric fields
    for(int i=AVG_WINDOW-1; i>=0; i--) {
        sum += entry->num_fields[i];
    }
    avg = sum / AVG_WINDOW;

    // Append average to the end of the line
    char output[ BUFFER_SIZE ];
    strcpy(output, "%s,%s,%s,", entry->timestamp, entry->server_id, entry->event_type);
    for(int i=0; i<MAX_FIELDS; i++) {
        sprintf(output + strlen(output), "%d", entry->num_fields[i]);
    }
    sprintf(output + strlen(output), ",%d", avg);

    // Print processed log entry
    printf("%s\n", output);

    return NULL;
}

void* read_log_file(void* arg) {
    FILE *file = (FILE*)arg;
    char buffer[BUFFER_SIZE];

    while(fgets(buffer, BUFFER_SIZE, file)) {
        pthread_mutex_lock(&buffer_lock);
        log_entry *new_entry = (log_entry*)malloc(sizeof(log_entry));
        sscanf(buffer, "%s %s %s", new_entry->timestamp, new_entry->server_id, new_entry->event_type);

        int field_count = 0;
        char *token = strtok(buffer, ",\n");
        while(token && field_count < MAX_FIELDS) {
            int value = atoi(token);
            new_entry->num_fields[field_count] = value;
            token = strtok(NULL, ",\n");
            field_count++;
        }

        current_entry = new_entry;
        current_position = strlen(buffer);
        pthread_cond_signal(&entry_available);
        pthread_mutex_unlock(&buffer_lock);
    }

    return NULL;
}

void* process_log_entries(void* arg) {
    while(1) {
        pthread_mutex_lock(&buffer_lock);
        pthread_cond_wait(&entry_available, &buffer_lock);

        if(current_entry == NULL)
            break;

        // Process the log entry
        void *entry = current_entry;
        process_log_entry(entry);

        free(current_entry);
        current_entry = NULL;
        pthread_mutex_unlock(&buffer_lock);
    }

    return NULL;
}

int main() {
    FILE *file = fopen("log.txt", "r");
    if(file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    pthread_t reader_thread, processor_thread;

    pthread_create(&reader_thread, NULL, read_log_file, (void*)file);
    pthread_create(&processor_thread, NULL, process_log_entries, NULL);

    pthread_join(reader_thread, NULL);
    pthread_join(processor_thread, NULL);

    return 0;
}
