```javascript
function FindElementsByTagName(node, selector) {
    const result = [];

    (function traverse(node, callback) {
        if (!node) return;

        node.classList.forEach((className) => {
            if (callback(className)) result.push(node);
        });

        for (let child of node.children) {
            traverse(child, callback);
        }
    })(node, (className) => className.includes(selector));

    return result;
}

