import json
import asyncio
from typing import List, Dict, Any

class JSONObject:
    def __init__(self):
        self.registry = {}

    async def load_json_files(self, file_names: List[str]) -> None:
        await asyncio.gather(*[self.load_file(name) for name in file_names])

    async def load_file(self, file_name: str) -> None:
        try:
            with open(file_name) as f:
                json_data = json.load(f)
                self.registry[file_name] = json_data
        except Exception as e:
            print(f"Error loading {file_name}: {str(e)}")

    def get_json_object(self, file_name: str) -> Dict[Any, Any]:
        return self.registry.get(file_name)

    async def deserialize_byte_array(self, byte_array: bytes) -> Dict[str, Any]:
        try:
            json_data = json.loads(byte_array.decode("utf-8"))
            random_string = f"random_{json_data['id']}"
            hashed_password = json_data["password"]
            return {"random_string": random_string, "hashed_password": hashed_password}
        except Exception as e:
            print(f"Error deserializing byte array: {str(e)}")
            return {}

    def manipulate_forward_list(self, forward_list: List[str], target_str: str, new_str: str, position: int = -1) -> None:
        try:
            if not forward_list or position < 0:
                raise ValueError("Invalid input")
            index = forward_list.index(target_str)
            if position == -1 or position > len(forward_list):
                forward_list.insert(index + 1, new_str)
            else:
                forward_list.insert(position, new_str)
        except ValueError as e:
            print(f"Error manipulating list: {str(e)}")

    def read_string_pairs(self, file_name: str) -> List[List[str]]:
        try:
            with open(file_name) as f:
                pairs = [line.strip().split("=") for line in f.readlines()]
                return [[pair[0], pair[1]] for pair in pairs]
        except Exception as e:
            print(f"Error reading string pairs: {str(e)}")

    async def run(self, file_names: List[str]) -> None:
        await self.load_json_files(file_names)
        try:
            json_data = self.get_json_object("main.json")
            random_string = f"random_{json_data['id']}"
            hashed_password = json_data["password"]
            print(f"Random string: {random_string}, Hashed password: {hashed_password}")
        except Exception as e:
            print(f"Error running program: {str(e)}")

if __name__ == "__main__":
    asyncio.run(JSONObject().run(["file1.json", "file2.json", "file3.json"]))
