function renderScripts(scripts, cache) {
  const footerHTML = '';

  for (const script of scripts) {
    const { key, code, async = false, defer = false, src, type } = script;
    let attributes = '';
    if (async) attributes += ' async';
    if (defer) attributes += ' defer';

    if (src) {
      if (!cache[src]) {
        try {
          const response = await fetch(src);
          const data = await response.json();
          cache[src] = { ...data };
        } catch (error) {
          console.error('Error fetching script:', error);
          continue;
        }
      }

      const cachedScript = cache[src];
      if (cachedScript) {
        code = cachedScript.code;
      } else {
        continue;
      }
    }

    footerHTML += `<script ${attributes} key="${key}" >${code}</script>`;
  }

  return footerHTML;
}
