import os
import glob
import logging
import csv
import zipfile
from collections import defaultdict
import json

logging.basicConfig(filename='statistic_logger.log', level=logging.INFO)

class StatisticsProcessor:
    def __init__(self, directory, exclusions=None):
        self.directory = directory
        self.exclusions = exclusions if exclusions else []

    def process_directory(self):
        file_types = defaultdict(lambda: {'lines': 0, 'words': 0, 'chars': 0})
        for file_path in glob.iglob(os.path.join(self.directory, '*')):
            if os.path.isfile(file_path):
                file_name, file_ext = os.path.splitext(file_path)
                if any(exclusion in file_name or exclusion in file_ext for exclusion in self.exclusions):
                    continue
                try:
                    with open(file_path, 'r') as file:
                        content = file.read()
                        lines, words, chars = len(content.splitlines()), len(content.split()), len(content)
                        file_types[file_ext[1:]].update({'lines': lines, 'words': words, 'chars': chars})
                except (FileNotFoundError, PermissionError):
                    logging.error(f"Failed to read {file_path}. Skipping.")
        return file_types

    def process_csv_files(self, file_types):
        for file_type, stats in file_types.items():
            if file_type == '.csv':
                with open(os.path.join(self.directory, f'statistics_{file_type[:-4]}.csv'), 'w', newline='') as output_file:
                    writer = csv.writer(output_file)
                    writer.writerow(['Lines', 'Words', 'Chars'])
                    for line in stats.values():
                        writer.writerow(list(line.values()))
                logging.info(f"Statistics written to {output_file.name}")

    def process_json_files(self, file_types):
        for file_type, stats in file_types.items():
            if file_type == '.json':
                with open(os.path.join(self.directory, f'statistics_{file_type[:-4]}.json'), 'w') as output_file:
                    json.dump(stats, output_file)
                logging.info(f"Statistics written to {output_file.name}")

    def compress_data_to_zip(self):
        zip_file_name = os.path.join(self.directory, 'statistics.zip')
        with zipfile.ZipFile(zip_file_name, 'w', zipfile.ZIP_DEFLATED) as zip_file:
            for file_type, stats in self.process_directory().items():
                if file_type == '.csv':
                    output_file_path = os.path.join(self.directory, f'statistics_{file_type[:-4]}.csv')
                    zip_file.write(output_file_path)
                elif file_type == '.json':
                    output_file_path = os.path.join(self.directory, f'statistics_{file_type[:-4]}.json')
                    zip_file.write(output_file_path)

    def start_processing(self):
        if not os.path.isdir(self.directory):
            logging.error(f"Invalid directory path: {self.directory}")
            return
        file_types = self.process_directory()
        self.process_csv_files(file_types)
        self.process_json_files(file_types)
        self.compress_data_to_zip()

if __name__ == '__main__':
    processor = StatisticsProcessor('/path/to/directory', exclusions=['*.log'])
    processor.start_processing()

