import re
import datetime
import signal
import functools

class LogAnalyzer:
    def __init__(self):
        self.config = {}
        self.cached_entries = {}

    def read_config(self, filename):
        with open(filename, 'r') as f:
            self.config = eval(f.read())

    def parse_line(self, line):
        timestamp, service_name, log_message = line.strip().split(',')
        return datetime.datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S'), service_name, log_message

    def analyze_log_message(self, log_message):
        failure_keywords = self.config.get('failure_keywords', [])
        for keyword in failure_keywords:
            if re.search(r'\b' + keyword + r'\b', log_message.lower()):
                return True
        return False

    @functools.lru_cache(maxsize=None)
    def get_previous_entry(self, timestamp):
        previous_entry = self.cached_entries.get(timestamp, None)
        if previous_entry:
            return previous_entry
        else:
            return None

    def calculate_latency(self, current_timestamp, previous_timestamp):
        latency = (current_timestamp - previous_timestamp).total_seconds() * 1000
        return latency

    def write_result(self, result):
        with open('output.log', 'a') as f:
            f.write(','.join(map(str, result)) + '\n')

    def analyze_log_file(self, filename):
        with open(filename, 'r') as f:
            for line in f:
                current_timestamp, service_name, log_message = self.parse_line(line)
                if self.analyze_log_message(log_message):
                    previous_entry = self.get_previous_entry(current_timestamp)
                    if previous_entry:
                        latency = self.calculate_latency(current_timestamp, previous_entry[0])
                        result = [service_name, log_message, previous_entry[1], latency, current_timestamp]
                        self.write_result(result)

    def signal_handler(self, signum, frame):
        print('Interrupted by signal', signum)
        self.save_state()
        raise SystemExit

    def save_state(self):
        with open('state.pkl', 'wb') as f:
            pickle.dump((self.cached_entries, self.config), f)

    def restore_state(self):
        try:
            with open('state.pkl', 'rb') as f:
                self.cached_entries, self.config = pickle.load(f)
        except FileNotFoundError:
            pass

    def run(self):
        self.read_config('config.txt')
        self.restore_state()
        signal.signal(signal.SIGINT, functools.partial(self.signal_handler))
        for filename in ['log_file1.log', 'log_file2.log']:
            self.analyze_log_file(filename)

if __name__ == '__main__':
    analyzer = LogAnalyzer()
    try:
        analyzer.run()
    except SystemExit:
        pass
