import re
import logging
import os
import csv
import concurrent.futures
from typing import List, Tuple

class LogProcessor:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.db_client = None
        self.stats = {
            "txt": {"lines": 0, "words": 0, "chars": 0},
            "log": {"lines": 0, "words": 0, "chars": 0},
            "csv": {"lines": 0, "words": 0, "chars": 0}
        }
        self.exclusions = []

    def process_log_file(self, file_path: str) -> None:
        if not os.path.exists(file_path):
            return

        with open(file_path, 'r') as file:
            for line in file:
                entry = line.strip()
                if not entry or re.match(r"^\s*$", entry):
                    continue

                try:
                    fields = [field.strip() for field in entry.split(",")]
                    numeric_fields = [float(field) for field in fields[-2:]]

                    avg = sum(numeric_fields) / len(numeric_fields)
                    new_entry = f"{entry},{avg:.2f}"

                    self.process_new_entry(new_entry)

                except ValueError:
                    self.logger.warning(f"Corrupted log entry: {entry}")

    def process_new_entry(self, entry: str) -> None:
        if not self.db_client:
            self.logger.error("Database connection failed")
            return

        try:
            self.db_client.write(entry)
        except Exception as e:
            self.logger.error(f"Error writing to database: {e}")
            self.db_client = None  # failover mechanism

    def compile_stats(self, directory_path: str) -> None:
        for root, dirs, files in os.walk(directory_path):
            for file in files:
                file_path = os.path.join(root, file)
                file_type = file.split(".")[-1]

                if file_type in self.stats:
                    with open(file_path, 'r') as f:
                        lines = 0
                        words = 0
                        chars = 0

                        for line in f:
                            lines += 1
                            words += len(line.strip().split())
                            chars += len(line)

                        self.stats[file_type]["lines"] += lines
                        self.stats[file_type]["words"] += words
                        self.stats[file_type]["chars"] += chars

    def get_stats(self) -> Tuple[dict]:
        return tuple({k: v for k, v in stats.items()} for stats in [self.stats.values()])

    def export_stats(self, output_path: str) -> None:
        with open(output_path, 'w') as file:
            writer = csv.writer(file)
            writer.writerow(["File Type", "Lines", "Words", "Chars"])
            writer.writerows(zip(*[({f"txt: {v['lines']}"}, {f"txt: {v['words']}"}), ({f"txt: {v['chars']}"})) + ([({f"log: {v['lines']}"}), {f"log: {v['words']}"}], ({f"log: {v['chars']}"})]) + (...)
