```javascript
function getElementListBySelector(rootElement, selector, ...filterCriteria) {
  const result = [];
  (function traverse(node) {
    if (!node) return;
    if (node.nodeType === Node.ELEMENT_NODE && matchesSelector(node, selector)) {
      let matches = true;
      for (const criterion of filterCriteria) {
        if (!matchesAttribute(criterion.name, criterion.value, node)) {
          matches = false;
          break;
        }
      }
      if (matches) result.push(...Array.from(node.children).map(traverse));
    } else if (node.nodeType === Node.TEXT_NODE || node.nodeType === Node.COMMENT_NODE) {
      // Text and comment nodes can be safely ignored
    } else if (node.nodeType === Node.DOCUMENT_FRAGMENT_NODE) {
      traverse(node.firstChild);
    }
  })(rootElement);

  return result;
}

function matchesSelector(element, selector) {
  const matches = document.querySelectorAll(selector);
  for (const match of matches) {
    if (match.contains(element)) return true;
  }
  return false;
}

function matchesAttribute(attributeName, attributeValue, element) {
  if (!element.hasAttribute(attributeName)) return false;
  return element.getAttribute(attributeName).toLowerCase() === attributeValue.toLowerCase();
}
