using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class PasswordService
{
    private readonly HttpClient _httpClient;
    private readonly string _apiEndpoint;
    private readonly string _apiKey;

    public PasswordService(string apiEndpoint, string apiKey)
    {
        _httpClient = new HttpClient { Timeout = TimeSpan.FromMinutes(1) };
        _apiEndpoint = apiEndpoint;
        _apiKey = apiKey;
    }

    public async Task<string> HashAndStorePasswordAsync(string password)
    {
        using (var md5 = MD5.Create())
        {
            var hashBytes = md5.ComputeHash(Encoding.UTF8.GetBytes(password));
            var hashString = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();

            try
            {
                using (var request = new HttpRequestMessage(HttpMethod.Post, _apiEndpoint))
                {
                    request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", _apiKey);
                    request.Content = new StringContent(hashString, Encoding.UTF8, "text/plain");

                    var response = await _httpClient.SendAsync(request);

                    if (!response.IsSuccessStatusCode)
                    {
                        throw new Exception($"Failed to store hash: {response.StatusCode}");
                    }
                }

                return hashString;
            }
            catch (Exception ex)
            {
                // Log error and handle accordingly
                Console.WriteLine(ex.Message);
                throw;
            }
        }
    }

    public async Task<bool> VerifyPasswordAsync(string storedHash, string providedPassword)
    {
        using (var md5 = MD5.Create())
        {
            var hashBytes = md5.ComputeHash(Encoding.UTF8.GetBytes(providedPassword));
            var providedHashString = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();

            try
            {
                using (var request = new HttpRequestMessage(HttpMethod.Get, _apiEndpoint))
                {
                    request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", _apiKey);
                    request.Query.Add("hash", storedHash);

                    var response = await _httpClient.SendAsync(request);

                    if (!response.IsSuccessStatusCode)
                    {
                        throw new Exception($"Failed to verify hash: {response.StatusCode}");
                    }

                    var responseBody = await response.Content.ReadAsStringAsync();
                    return responseBody.Contains(providedHashString);
                }
            }
            catch (Exception ex)
            {
                // Log error and handle accordingly
                Console.WriteLine(ex.Message);
                return false;
            }
        }
    }
}

public class AuthenticationHeaderValue : HttpRequestHeader
{
    public string Value { get; set; }

    public override string ToString()
    {
        return $"Bearer {Value}";
    }
}
