import os
import fcntl
import time
import threading
import logging

class DistributedFileSystem:
    def __init__(self, root_directory):
        self.root_directory = root_directory
        self.locks = {}
        self.config = {}

    def create_directory(self, directory_path):
        while True:
            try:
                os.mkdir(directory_path)
                return
            except OSError as e:
                if e.errno == errno.EEXIST:
                    # Directory already exists, retry
                    continue
                elif e.errno in (errno.ENOENT, errno.EACCES):
                    # Parent directory does not exist or permission issue, retry
                    continue
                else:
                    # Unexpected error, log and raise
                    logging.error(f"Error creating directory {directory_path}: {e}")
                    raise

    def delete_directory(self, directory_path):
        while True:
            try:
                os.rmdir(directory_path)
                return
            except OSError as e:
                if e.errno == errno.ENOENT:
                    # Directory does not exist, return
                    return
                else:
                    # Unexpected error, log and raise
                    logging.error(f"Error deleting directory {directory_path}: {e}")
                    raise

    def list_directory(self, directory_path):
        try:
            contents = os.listdir(directory_path)
            return contents
        except OSError as e:
            logging.error(f"Error listing directory {directory_path}: {e}")
            return []

    def create_file(self, file_path):
        while True:
            try:
                with open(file_path, 'w') as f:
                    pass
                return
            except IOError as e:
                if e.errno in (errno.EEXIST, errno.ENOENT):
                    # File already exists or does not exist, retry
                    continue
                else:
                    # Unexpected error, log and raise
                    logging.error(f"Error creating file {file_path}: {e}")
                    raise

    def read_file(self, file_path):
        try:
            with open(file_path, 'r') as f:
                content = f.read()
                return content
        except IOError as e:
            logging.error(f"Error reading file {file_path}: {e}")
            return None

    def update_file(self, file_path, content):
        while True:
            try:
                with open(file_path, 'w') as f:
                    f.write(content)
                return
            except IOError as e:
                if e.errno in (errno.EEXIST, errno.ENOENT):
                    # File already exists or does not exist, retry
                    continue
                else:
                    # Unexpected error, log and raise
                    logging.error(f"Error updating file {file_path}: {e}")
                    raise

    def delete_file(self, file_path):
        while True:
            try:
                os.remove(file_path)
                return
            except OSError as e:
                if e.errno == errno.ENOENT:
                    # File does not exist, return
                    return
                else:
                    # Unexpected error, log and raise
                    logging.error(f"Error deleting file {file_path}: {e}")
                    raise

    def get_config(self):
        return self.config

    def set_config(self, key, value):
        self.config[key] = value

    def get_lock(self, directory_path):
        if directory_path not in self.locks:
            self.locks[directory_path] = fcntl.flock(open(directory_path, 'a'), fcntl.LOCK_EX)
        return self.locks[directory_path]

    def release_lock(self, directory_path):
        if directory_path in self.locks:
            fcntl.flock(self.locks[directory_path], fcntl.LOCK_UN)
            del self.locks[directory_path]
