import time
from functools import wraps
from cachetools import TTLCache
from requests.exceptions import RequestException

# Define rate limiting functions for individual transactions and batch processing
def rate_limit_individual(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        if "X-Request-Source" not in kwargs:
            kwargs["X-Request-Source"] = "unknown"
        start_time = time.time()
        result = func(*args, **kwargs)
        end_time = time.time()
        elapsed_time = end_time - start_time
        if elapsed_time < 1.0 / 5:  # Limit to 5 requests per second
            time.sleep(max(0, 1 / 5 - elapsed_time))
        return result
    return wrapper

def rate_limit_batch(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start_time = time.time()
        result = func(*args, **kwargs)
        end_time = time.time()
        elapsed_time = end_time - start_time
        if elapsed_time < 10:  # Limit to 100 transactions in 10 seconds for batch processing
            time.sleep(max(0, 10 - elapsed_time))
        return result
    return wrapper

