const { spawn } = require('child_process');
const fs = require('fs');
const db = require('./db.js'); // assuming a separate file for database operations
const logFile = 'shell_command_log.txt';

async function executeShellCommand(command, pattern) {
  try {
    const childProcess = spawn('bash', ['-c', command]);
    let output = '';
    childProcess.stdout.on('data', (data) => {
      output += data.toString();
    });
    childProcess.stderr.on('data', (data) => {
      console.error(data.toString());
    });
    childProcess.on('close', () => {
      const filteredOutput = output.split('\n').filter((line) => line.includes(pattern)).join('\n');
      await db.insertData(filteredOutput); // assuming a method to insert data into the database
      fs.appendFile(logFile, `Command executed: ${command}\n`, (err) => {
        if (err) console.error(err);
      });
    });
  } catch (error) {
    console.error(error);
    fs.appendFile(logFile, `Error executing command: ${error.stack}\n`, (err) => {
      if (err) console.error(err);
    });
  }
}
