    private readonly int _batchSize;
    private readonly Func<FileInfo, ProcessedMetadata> _metadataProcessor;

    public DynamicFileMetadataAnalyzer(string directoryPath, int minimumFileSizeThreshold, int maximumFileSizeThreshold, int batchSize, Func<FileInfo, ProcessedMetadata> metadataProcessor)
    {
        _directoryInfo = new DirectoryInfo(directoryPath);
        _minimumFileSizeThreshold = minimumFileSizeThreshold;
        _maximumFileSizeThreshold = maximumFileSizeThreshold;
        _batchSize = batchSize;
        _metadataProcessor = metadataProcessor;
    }

    public IEnumerable<ProcessedMetadata> Analyze()
    {
        if (!_directoryInfo.Exists)
            throw new DirectoryNotFoundException("The specified directory does not exist.");

        ValidateFileSizeRange();

        var processedMetadatas = Enumerable.Empty<ProcessedMetadata>();

        using (var fileReader = _directoryInfo.EnumerateFiles())
        {
            while (fileReader.MoveNext())
            {
                var fileInfo = fileReader.Current;
                if (ValidateFile(fileInfo))
                {
                    var metadata = GetFileInfoMetadata(fileInfo);
                    processedMetadatas = processedMetadatas.Concat(GetProcessedMetadata(metadata));
                }
            }
        }

        return processedMetadatas;
    }

    private void ValidateFileSizeRange()
    {
        if (_minimumFileSizeThreshold > _maximumFileSizeThreshold)
            throw new ArgumentException("Minimum file size threshold must be less than or equal to the maximum threshold.");
    }

    private bool ValidateFile(FileInfo fileInfo)
    {
        try
        {
            return fileInfo.Exists;
        }
        catch (UnauthorizedAccessException ex)
        {
            // Log error and skip file
            Console.WriteLine($"Error accessing file: {ex.Message}");
            return false;
        }
        catch (Exception ex)
        {
            // Log error and skip file
            Console.WriteLine($"Error processing file: {ex.Message}");
            return false;
        }
    }

    private ProcessedMetadata GetFileInfoMetadata(FileInfo fileInfo)
    {
        var metadata = new ProcessedMetadata()
        {
            FileName = fileInfo.Name,
            Size = fileInfo.Length,
            CreationDate = fileInfo.CreationTime,
            LastModified = fileInfo.LastWriteTime
        };
        return _metadataProcessor(fileInfo, metadata);
    }
}

public class ProcessedMetadata
{
    public string FileName { get; set; }
    public int Size { get; set; }
    public DateTime CreationDate { get; set; }
    public DateTime LastModified { get; set; }
}
