import functools
import cachingutils

conversion_factors = {
    "Celsius": {"Fahrenheit": 9/5 + 32, "Kelvin": 1},
    "Fahrenheit": {"Celsius": (5/9) * (temper-32), "Kelvin": (5/9) * (temper-32) + 273.15},
    "Kelvin": {"Celsius": temper - 273.15, "Fahrenheit": (9/5) * (temper - 273.15) + 32}
}

@functools.lru_cache(maxsize=None)
def convert_temperature(source_scale: str, source_value: float, target_scale: str):
    if source_scale == target_scale:
        return source_value
    factor = conversion_factors[source_scale][target_scale]
    return round(source_value * factor, 2)

def batch_convert_temperatures(scales: dict, values: list):
    results = []
    for value in values:
        result = {}
        for scale, temper in scales.items():
            try:
                result[scale] = convert_temperature(scale, value[0], temper)
            except Exception as e:
                print(f"Error converting {value[0]} from {scale} to {temper}: {str(e)}")
        results.append(result)
    return results

# Example usage:
scales = {"Celsius": "Fahrenheit", "Fahrenheit": "Kelvin"}
values = [(0, 100), (32, -20)]
results = batch_convert_temperatures(scales, values)
