function dynamicDOMQuery(rootElement, selector, ...filterCriteria) {
  const results = [];
  const apiRetryCount = 3;
  let metadataApiFailureCount = 0;

  function traverse(node, selector, filterCriteria) {
    if (!node) return;

    const elementsMatchingSelector = node.querySelectorAll(selector);
    elementsMatchingSelector.forEach((element) => {
      const matchesFilter = filterCriteria.every((filter) => {
        for (const [attributeName, attributeValue] of Object.entries(filter)) {
          if (!element.hasAttribute(attributeName) || element.getAttribute(attributeName) !== attributeValue) return false;
        }
        return true;
      });

      if (matchesFilter) {
        results.push(element);
        metadataApiFailureCount = 0; // Reset after successful traversal
      }

      traverse(...elementsMatchingSelector, selector, filterCriteria);
    });
  }

  try {
    traverse(rootElement, selector, filterCriteria);
  } catch (error) {
    console.error('Error during DOM query:', error);

    if (error.name === 'TypeError' && /Cannot read property of null/.test(error.message)) {
      // Handle invalid selectors
      return [];
    }
  }

  async function fetchMetadata() {
    try {
      const response = await fetch('https://metadata-api.com/get', { method: 'GET' });
      const data = await response.json();

      if (!data) throw new Error('API returned no data');

      return data;
    } catch (error) {
      if (error.name === 'FetchError') {
        // API failure, retry with exponential backoff
        setTimeout(() => fetchMetadata(), Math.pow(2, metadataApiFailureCount++) * 100);
      } else {
        throw error;
      }
    }
  }

  const metadata = await fetchMetadata();

  if (metadataApiFailureCount >= apiRetryCount) {
    // Fallback strategy after maximum API retries
    return results;
  }

  // Integrate metadata with query results
  // ...

  return results;
}
