const fs = require('fs');
const path = require('path');
const chalk = require('chalk');
const { watch } = require('chokidar');

let modules = {};

async function loadModules(directory) {
  const moduleFiles = await Promise.all(
    fs.readdirSync(directory).map((file) => {
      return fs.stat(path.join(directory, file)).then((stat) => {
        if (stat.isDirectory()) {
          return loadModules(path.join(directory, file));
        } else if (file.endsWith('.js')) {
          return importModule(path.join(directory, file));
        }
      });
    })
  );

  return moduleFiles.flat();
}

async function importModule(modulePath) {
  try {
    const module = await import(modulePath);
    modules[module.default.name] = module;
  } catch (error) {
    console.error(chalk.red(`Error loading module: ${modulePath}`));
    process.exit(1);
  }
}

function executeModules() {
  Object.keys(modules).forEach((moduleName) => {
    try {
      modules[moduleName].default();
    } catch (error) {
      console.error(chalk.red(`Error executing module: ${moduleName}`));
    }
  });
}

async function watchDirectory(directory) {
  const watcher = watch(directory);
  watcher.on('change', async (path, event) => {
    if (event === 'update') {
      try {
        await importModule(path);
        executeModules();
        console.log(chalk.green(`Module updated: ${path}`));
      } catch (error) {
        console.error(chalk.red(`Error updating module: ${path}`));
      }
    } else if (event === 'delete') {
      delete modules[path];
      executeModules();
      console.log(chalk.yellow(`Module deleted: ${path}`));
    }
  });
}

async function main() {
  const directory = './modules'; // Specify the directory path
  await loadModules(directory);
  watchDirectory(directory);
  setInterval(executeModules, 1000); // Execute modules every second
}

main();
