using System;
using System.Threading;

namespace AdvancedRandomGenerator
{
    public enum RangeType { Closed, Open, HalfOpen }

    public class CustomInterval
    {
        public double Min { get; set; }
        public double Max { get; set; }
        public RangeType Type { get; set; }

        public CustomInterval(double min, double max, RangeType type)
        {
            Min = min;
            Max = max;
            Type = type;
        }
    }

    public class SeedManager
    {
        private readonly ThreadLocal<int> _seed;

        public SeedManager()
        {
            _seed = new ThreadLocal<int>(() => UnityEngine.Random.Range(0, 100000));
        }

        public void ReSeed(int threshold)
        {
            if (_seed.Value > threshold)
                _seed.Value = UnityEngine.Random.Range(0, 100000);
        }

        public int GetSeed()
        {
            return _seed.Value;
        }
    }

    public class AdvancedRandomGenerator
    {
        private readonly SeedManager _seedManager;

        public AdvancedRandomGenerator()
        {
            _seedManager = new SeedManager();
        }

        public void CustomRange(double min, double max, RangeType type)
        {
            if (min > max) throw new ArgumentException("Invalid range: min must be less than or equal to max.");
            if (type == RangeType.Open && min >= max) throw new ArgumentException("Invalid range for open interval: min must be less than max.");

            var random = new System.Random(_seedManager.GetSeed());
            double value;

            switch (type)
            {
                case RangeType.Closed:
                    value = random.NextDouble() * (max - min) + min;
                    break;
                case RangeType.Open:
                    value = random.NextDouble() * (max - min) + min;
                    if (value == max) value += 1e-6; // avoid exact equality
                    break;
                case RangeType.HalfOpen:
                    value = random.NextDouble() * (max - min) + min;
                    if (value >= max) value = max - 1e-6; // avoid exact equality
                    break;
                default:
                    throw new ArgumentException("Invalid range type.");
            }

            Console.WriteLine($"Generated value: {value}");
        }
    }
}
