    private static final int RETRY_COUNT = 3;
    private static final int BACKOFF_MILLIS = 5000;

    public void downloadImageResources(String[] imageUrls) throws IOException, InterruptedException {
        // Create a thread-safe cache
        BlockingQueue<Image> cache = new LinkedBlockingQueue<>();

        // Set up the HTTP client with retry mechanism and backoff
        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
                .timeout(Duration.ofMillis(5000))
                .build();

        for (String imageUrl : imageUrls) {
            Image image;
            try {
                // Validate the URL
                URI url = URI.create(imageUrl);
                if (!isValidImageUrl(url)) {
                    continue;
                }

                // Download and cache the image
                image = downloadImage(client, request, url);
                cache.put(image);
            } catch (IOException e) {
                // Log error and retry
                logError(imageUrl, e);
                if (retryCount < RETRY_COUNT) {
                    try {
                        Thread.sleep(BACKOFF_MILLIS);
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                    }
                } else {
                    continue;
                }
            } finally {
                // Clean up the cache
                if (cache.size() > MAX_CACHE_SIZE) {
                    cache.take();
