    public class DatabaseConnectionManager
    {
        private readonly Dictionary<string, object> _connectionPools = new();
        private readonly object _lock = new();
        private int _seedValue;
        private string _configSource;

        public void InitializeFromConfiguration(string configSource)
        {
            _configSource = configSource;
        }

        public void Seed(int seedValue)
        {
            _seedValue = seedValue;
        }

        public DbConnection GetConnection(string provider, string connectionString)
        {
            lock (_lock)
            {
                if (!_connectionPools.TryGetValue(provider, out object pool))
                {
                    pool = new List<DbConnection>();
                    _connectionPools[provider] = pool;
                }
                var connectionPool = (List<DbConnection>)pool;
                DbConnection connection;
                if (!connectionPool.Any())
                {
                    // Establish a new connection
                    connection = CreateConnection(provider, connectionString);
                    connectionPool.Add(connection);
                }
                else
                {
                    // Return an existing connection from the pool
                    connection = connectionPool[0];
                    connectionPool.RemoveAt(0);
                }
                return connection;
            }
        }

        public void ReleaseConnection(IDbConnection connection)
        {
            lock (_lock)
            {
                string provider = connection.GetType().Name.Replace("Db", "");
                if (_connectionPools.TryGetValue(provider, out object pool))
                {
                    (List<DbConnection>)pool.Add(connection);
                }
            }
        }

        public override string ToString()
        {
            // Display the current state of the connection manager
            return $"Pool size: {_connectionPools.Count}, Active connections: {GetActiveConnections()}";
        }

        private DbConnection CreateConnection(string provider, string connectionString)
        {
            // Implement your provider-specific connection creation logic here
            // For example:
            // using Npgsql;
            // return new NpgsqlConnection(connectionString);
            throw new NotImplementedException();
        }

        private int GetActiveConnections()
        {
            // Count the number of active connections in each pool
            int count = 0;
            foreach (var pool in _connectionPools.Values)
            {
                foreach (var connection in pool.OfType<DbConnection>())
                {
                    if (!connection.State.HasFlag(ConnectionState.Closed))
                    {
                        count++;
                    }
                }
            }
            return count;
        }
    }
}
