typedef struct SubNode {
    char* str;
    double value;
    struct SubNode** nestedList;
} SubNode;

typedef struct Node {
    int value;
    SubNode* list;
} Node;

void freeMemory(Node* nodeArray, int size) {
    for (int i = 0; i < size; i++) {
        if (nodeArray[i].list != NULL) {
            for (int j = 0; nodeArray[i].list[j] != NULL; j++) {
                free(nodeArray[i].list[j]->str);
                free(nodeArray[i].list[j]->nestedList);
                free((void*) nodeArray[i].list);
            }
        }
    }
}

Node* createNodeArray(int size) {
    Node* nodeArray = (Node*)malloc(size * sizeof(Node));
    if (nodeArray == NULL)
        return NULL;

    for (int i = 0; i < size; i++) {
        nodeArray[i].value = rand() % 100;
        SubNode** list = (SubNode**)malloc(sizeof(SubNode*) * 5);
        for (int j = 0; j < 5; j++) {
            SubNode* subNode = (SubNode*)malloc(sizeof(SubNode));
            char* str = (char*)malloc((rand() % 100) + 1);
            strcpy(str, "RandomString");
            subNode->str = str;
            subNode->value = (double)rand() / RAND_MAX;
            double nestedValue = (double)rand() / RAND_MAX;
            float nestedFloat = (float)rand() / RAND_MAX;

            char** nestedStrArray = (char**)malloc(sizeof(char*) * 10);
            for (int k = 0; k < 10; k++) {
                char* nestedStr = (char*)malloc((rand() % 100) + 1);
                strcpy(nestedStr, "NestedRandomString");
                nestedStrArray[k] = nestedStr;
            }
            subNode->nestedList = (SubNode**)malloc(sizeof(SubNode*) * 10);
            for (int k = 0; k < 10; k++) {
                SubNode* nestedSubNode = (SubNode*)malloc(sizeof(SubNode));
                nestedSubNode->str = nestedStrArray[k];
                nestedSubNode->value = nestedValue;
                nestedSubNode->nestedList = NULL;
                subNode->nestedList[k] = nestedSubNode;
            }
            list[j] = subNode;
        }
        nodeArray[i].list = list;
    }

    return nodeArray;
}

int main() {
    srand(time(NULL));
    int size = 5;
    Node* nodeArray = createNodeArray(size);

    // Use the nodeArray here...

