function FindElementsBySelector(root, selector, testFunc) {
    let elements = [];
    let nodes = [root];

    while (nodes.length > 0) {
        for (let node of nodes) {
            if (node.nodeType === Node.ELEMENT_NODE) {
                if (testFunc(node)) {
                    elements.push(node);
                }
                let childNodes = Array.from(node.childNodes);
                nodes = childNodes;
            } else {
                nodes = nodes.filter(node => node.nodeType !== Node.COMMENT_NODE);
            }
        }
    }

