namespace RandomService {
    class ThreadSafeGenerator {
        std::mt19937_64 mt;
        mutable std::mutex mtx;

    public:
        ThreadSafeGenerator() : mt(SeedFromThreadID()) {}

        ~ThreadSafeGenerator() {}

        double nextDouble() {
            std::lock_guard<std::mutex> lock(mtx);
            return static_cast<double>(mt()) / (1 << 63);
        }

        static unsigned long SeedFromThreadID() {
            return std::this_thread::get_id();
        }
    };
