<?php
function updateClinicStatus($clinicId, $newStatus, $lastModifiedIp, $reason) {
    // Validate clinic ID
    if (!is_int($clinicId)) {
        return json_encode(['error' => 'Invalid clinic ID']);
    }

    // Start transaction
    db_begin_transaction();

    try {
        // Update database table with new status and last modified IP and timestamp
        $query = "UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE id = ?";
        $result = db_query($query, [$newStatus, $lastModifiedIp, date('Y-m-d H:i:s'), $clinicId]);

        if ($result === false) {
            // Log error
            log_error("Error updating clinic status: " . json_encode(db_last_error()));

            // Rollback transaction
            db_rollback();
            return json_encode(['error' => 'Database update failed']);
        }

        // Commit transaction
        db_commit();

        // Record change in external logging service
        $logData = [
            'clinic_id' => $clinicId,
            'new_status' => $newStatus,
            'last_modified_ip' => $lastModifiedIp,
            'reason' => $reason,
            'user_id' => $_SESSION['user_id'], // Get user ID from session
        ];
        log_event('Clinic status updated', $logData);

        return json_encode(['success' => true]);
    } catch (Exception $e) {
        // Log error
        log_error("Error updating clinic status: " . $e->getMessage());

        // Rollback transaction
        db_rollback();

        // Return detailed error message
        return json_encode(['error' => 'Database update failed: ' . $e->getMessage()]);
    } finally {
        // Close database connection
        db_close();
    }
}

// Implement rate limiting to prevent abuse
function rate_limit($clinicId) {
    // Check if clinic has exceeded update limit within a short time frame
    if (check_rate_limit($clinicId)) {
        return json_encode(['error' => 'Update limit reached']);
    }

    // Reset rate limit timer for this clinic
    reset_rate_limit_timer($clinicId);
}

// Implement mechanism to detect and prevent bulk updates from a single source IP within a short time frame
function check_bulk_updates($lastModifiedIp) {
    // Check if last modified IP has exceeded update limit within a short time frame
    if (check_ip_rate_limit($lastModifiedIp)) {
        return json_encode(['error' => 'Bulk update detected']);
    }

    // Reset rate limit timer for this IP
    reset_ip_rate_limit_timer($lastModifiedIp);
}

// Implement support for updating multiple clinics in a single transaction
function updateMultipleClinics($clinicIds, $newStatus) {
    // Start transaction
    db_begin_transaction();

    try {
        // Update database table with new status and last modified timestamp for each clinic
        foreach ($clinicIds as $clinicId) {
            $query = "UPDATE clinics SET status = ?, last_modified_date = ? WHERE id = ?";
            $result = db_query($query, [$newStatus, date('Y-m-d H:i:s'), $clinicId]);

            if ($result === false) {
                // Log error
                log_error("Error updating clinic status: " . json_encode(db_last_error()));

                // Rollback transaction
                db_rollback();
                return json_encode(['error' => 'Database update failed']);
            }
        }

        // Commit transaction
        db_commit();

        return json_encode(['success' => true]);
    } catch (Exception $e) {
        // Log error
        log_error("Error updating clinic status: " . $e->getMessage());

        // Rollback transaction
        db_rollback();

        // Return detailed error message
        return json_encode(['error' => 'Database update failed: ' . $e->getMessage()]);
    } finally {
        // Close database connection
        db_close();
    }
}

// Implement email notification system
function send_email_notification($clinicId, $newStatus) {
    // Get clinic administrator's email address from database
    $adminEmail = get_admin_email($clinicId);

    if ($adminEmail) {
        // Send email notification with update details and user who made the change
        send_email($adminEmail, 'Clinic status updated', "The status of Clinic ID $clinicId has been updated to $newStatus by User ID $_SESSION[user_id]");
    }
}

// Implement caching mechanisms
function cache_data($key, $value) {
    // Store data in cache
    cache_set($key, $value);
}

function get_cached_data($key) {
    // Retrieve cached data
    return cache_get($key);
}

// Implement throttling mechanism to limit updates per clinic based on predefined rules
function throttle_updates($clinicId) {
    // Check if clinic has exceeded update limit within a short time frame
    if (check_update_limit($clinicId)) {
