        int retries = 0;
        while (retries < 3) {
            try {
                downloadAndProcessImage(url);
                return;
            } catch (IOException ex) {
                if (retries == 2) {
                    LOGGER.error("Failed to download image: {}", url);
                }
                // Exponential backoff
                Thread.sleep((int) Math.pow(2, retries) * 1000);
                retries++;
