```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>
#include <sys/stat.h>

#define RESOURCE_BUNDLE_FORMATS 2 // JSON and binary for now
#define MAX_FILE_PATH_LENGTH 256
#define MAX_RESOURCE_ITEMS 10000

typedef struct {
    char format;
    void* data;
    size_t size;
} ResourceBundleFormat;

ResourceBundleFormat loadResourceBundle(const char* filePath) {
    ResourceBundleFormat bundle;
    int fileDesc = open(filePath, O_RDONLY);
    if (fileDesc == -1) {
        printf("Error opening file: %s\n", filePath);
        return (ResourceBundleFormat){0};
    }

    struct stat statBuf;
    fstat(fileDesc, &statBuf);

    // Determine the format of the resource bundle
    char* extension = strrchr(filePath, '.');
    if (!extension) {
        printf("Error: file path has no extension\n");
        close(fileDesc);
        return (ResourceBundleFormat){0};
    }

    // Load JSON format
    if (strcmp(extension, ".json") == 0) {
        json_object* jsonData = json_object_from_file(filePath);
        if (!jsonData) {
            printf("Error parsing JSON file: %s\n", filePath);
            close(fileDesc);
            return (ResourceBundleFormat){0};
        }
        bundle.data = jsonData;
        bundle.size = statBuf.st_size;
        bundle.format = 'J';
    }
    // Load binary format
    else if (strcmp(extension, ".bin") == 0) {
        void* binaryData = malloc(statBuf.st_size);
        read(fileDesc, binaryData, statBuf.st_size);
        close(fileDesc);
        bundle.data = binaryData;
        bundle.size = statBuf.st_size;
        bundle.format = 'B';
    }
    else {
        printf("Error: unsupported file format: %s\n", extension);
        close(fileDesc);
        return (ResourceBundleFormat){0};
    }

    return bundle;
}
