import redis.clients.jedis.Jedis;
import redis.clients.jedis.JedisPool;
import redis.clients.jedis.JedisPoolConfig;

import java.util.HashMap;
import java.util.Map;

public class DistributedCache {
    private JedisPool jedisPool;
    private Map<String, Long> cacheExpirationTimes = new HashMap<>();

    public DistributedCache(String redisHost, int redisPort) {
        JedisPoolConfig config = new JedisPoolConfig();
        config.setMaxTotal(20);
        config.setMaxIdlePerPool(10);

        this.jedisPool = new JedisPool(config, redisHost, redisPort);
    }

    public void set(String key, String value, long expirationTime, String category) {
        Jedis jedis = jedisPool.getResource();
        try {
            jedis.setex(key, expirationTime, value);
            cacheExpirationTimes.put(category + ":" + key, expirationTime);
        } catch (Exception e) {
            // Handle errors
        } finally {
            jedis.close();
        }
    }

    public String get(String key, String category) {
        Jedis jedis = jedisPool.getResource();
        try {
            return jedis.get(key);
        } catch (Exception e) {
            // Handle errors
        } finally {
            jedis.close();
        }
    }

    public void invalidate(String key, String category) {
        Jedis jedis = jedisPool.getResource();
        try {
            jedis.del(key);
            cacheExpirationTimes.remove(category + ":" + key);
        } catch (Exception e) {
            // Handle errors
        } finally {
            jedis.close();
        }
    }

    public Map<String, Long> getCacheExpirationTimes() {
        return cacheExpirationTimes;
    }
}
