// node_modules/sequential-module-loader/index.js
const fs = require('fs');
const path = require('path');
const childProcess = require('child_process');
const crypto = require('crypto');

class SequentialModuleLoader {
  constructor(configFile) {
    this.configFile = configFile;
    this.modules = [];
    this.moduleExecutions = {};
    this.concurrentExecutions = 0;
    this.errorHandler = (err) => {
      console.error(err);
      process.exit(1);
    };
  }

  async loadModules() {
    const config = await fs.promises.readFile(this.configFile, 'utf8');
    const modulesConfig = JSON.parse(config);

    for (const moduleInfo of modulesConfig.modules) {
      this.modules.push(moduleInfo.path);
      if (moduleInfo.dependencies) {
        for (const dependency of moduleInfo.dependencies) {
          if (!this.modules.includes(dependency)) {
            this.modules.push(dependency);
          }
        }
      }
    }

    await Promise.all(this.modules.map((modulePath) => import(path.join(__dirname, '..', modulePath))));
  }

  async executeModules() {
    for (const module of this.modules) {
      try {
        const moduleExecution = childProcess.fork(path.join(__dirname, '..', module), [], { stdio: 'inherit' });
        this.moduleExecutions[module] = moduleExecution;
      } catch (err) {
        await this.errorHandler(err);
      }
    }

    return new Promise((resolve, reject) => {
      let executionsComplete = 0;

      for (const [module, execution] of Object.entries(this.moduleExecutions)) {
        execution.on('exit', () => {
          executionsComplete++;
          if (executionsComplete === this.modules.length) {
            resolve();
          }
        });
      }
    });
  }

  async generateReports() {
    // TO DO: implement report generation
  }

  async executeAndGenerateReports() {
    await this.loadModules();
    await this.executeModules();
    await this.generateReports();
  }
}

module.exports = SequentialModuleLoader;
