using System.Threading;
using System.Threading.Tasks;

public class StringHasher : IStringHasher
{
    private readonly ISettings _settings;
    private readonly ILogger _logger;

    public StringHasher(ISettings settings, ILogger logger)
    {
        _settings = settings;
        _logger = logger;
    }

    public string HashSingleString(string inputString)
    {
        if (_settings.HashAlgorithm == "MD5")
            return MD5Hash(inputString);
        else if (_settings.HashAlgorithm == "SHA256")
            return SHA256Hash(inputString);
        else
            return CustomHash(inputString);
    }

    public string[] HashStringsInParallel(string[] inputStrings)
    {
        var results = new Task<string>[inputStrings.Length];
        for (int i = 0; i < inputStrings.Length; i++)
        {
            int index = i;
            results[i] = Task.Run(() => HashSingleString(inputStrings[index])).Result;
        }
        return results;
    }

    public bool ValidateHashes(string[] hashes, string[] expectedHashes)
    {
        for (int i = 0; i < hashes.Length; i++)
        {
            if (!hashes[i].Equals(expectedHashes[i]))
                return false;
        }
        return true;
    }

    private string MD5Hash(string inputString)
    {
        using var md5 = MD5.Create();
        var inputBytes = Encoding.UTF8.GetBytes(inputString);
        var hashBytes = md5.ComputeHash(inputBytes);
        return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
    }

    private string SHA256Hash(string inputString)
    {
        using var sha256 = SHA256.Create();
        var inputBytes = Encoding.UTF8.GetBytes(inputString);
        var hashBytes = sha256.ComputeHash(inputBytes);
        return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
    }

    private string CustomHash(string inputString)
    {
        // implement your custom hashing algorithm here
        return "";
    }
}

public interface ISettings
{
    string HashAlgorithm { get; set; }
    int BatchSize { get; set; }
}

public interface ILogger
{
    void LogError(Exception ex);
}
