using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;

namespace SecureCipherService
{
    public class SecureCipherService : IDisposable
    {
        private readonly object _syncLock = new object();
        private readonly TokenCache _tokenCache;
        private readonly AuthenticationClient _authClient;

        public SecureCipherService(AuthenticationClient authClient, TokenCache tokenCache)
        {
            _authClient = authClient;
            _tokenCache = tokenCache;
        }

        public async Task<byte[]> DecryptMessageAsync(byte[] ciphertext, byte[] key, byte[] iv, long offset, CancellationToken cancellationToken)
        {
            if (ciphertext == null) throw new ArgumentNullException(nameof(ciphertext));
            if (key == null) throw new ArgumentNullException(nameof(key));
            if (iv == null) throw new ArgumentNullException(nameof(iv));

            using var aes = Aes.Create();
            aes.Key = key;
            aes.IV = iv;

            using var decryptor = aes.CreateDecryptor();

            using var ms = new MemoryStream(ciphertext);
            ms.Position = offset;

            byte[] buffer = new byte[1024 * 16]; // adjust buffer size as needed
            int bytesRead;

            try
            {
                while ((bytesRead = ms.Read(buffer, 0, buffer.Length)) > 0)
                {
                    using var stream = new MemoryStream();
                    await decryptor.TransformFinalBlockAsync(buffer, 0, bytesRead, stream, cancellationToken);
                    ciphertext = stream.ToArray();
                }
            }
            catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
            {
                // decryption canceled
                return null;
            }

            return ciphertext;
        }

        public async Task RefreshTokenAsync()
        {
            while (!_tokenCache.TryRefreshToken())
            {
                await Task.Delay(1000, CancellationToken.None);
            }
        }

        public void Dispose()
        {
            _authClient?.Dispose();
            _tokenCache?.Dispose();
        }
    }
}
