import logging
from datetime import datetime
from functools import lru_cache
from typing import Dict, List, Any

@lru_cache(maxsize=1000)
def process_user_activity_logs(file_path: str, start_time: datetime = None, end_time: datetime = None, activity_types: List[str] = None, user_roles: List[str] = None) -> Dict[str, Any]:
    cache_key = (file_path, start_time, end_time, frozenset(activity_types), frozenset(user_roles))

    if cache_key in cache:
        logging.info(f"Cache hit for {cache_key}")
        return cache[cache_key]

    try:
        with open(file_path, 'r') as f:
            logs = [line.strip().split(',') for line in f.readlines()]

        filtered_logs = []
        for log in logs:
            log_time = datetime.strptime(log[0], '%Y-%m-%d %H:%M:%S')
            activity_type = log[1]
            user_role = log[2]

            if (start_time is None or start_time <= log_time) and (end_time is None or end_time >= log_time):
                if (activity_types is None or activity_type in activity_types) and (user_roles is None or user_role in user_roles):
                    filtered_logs.append(log)

        aggregated_data = {}
        for log in filtered_logs:
            timestamp = datetime.strptime(log[0], '%Y-%m-%d %H:%M:%S')
            activity_type = log[1]

            if activity_type not in aggregated_data:
                aggregated_data[activity_type] = {'count': 0, 'total_time': datetime.min}

            aggregated_data[activity_type]['count'] += 1
            aggregated_data[activity_type]['total_time'] += (timestamp - datetime.strptime(log[3], '%Y-%m-%d %H:%M:%S'))

        cache[cache_key] = {'filtered_logs': filtered_logs, 'aggregated_data': aggregated_data}
        logging.info(f"Cache set for {cache_key}")
        return cache[cache_key]

    except FileNotFoundError:
        logging.error(f"File not found: {file_path}")
        return None

    except Exception as e:
        logging.error(f"Error processing logs: {str(e)}")
        return None

