function renderFooterScripts(apiUrl) {
  const scriptCache = {};
  let lastFetchTime = 0;
  const fetchScriptDetails = async () => {
    const currentTime = Date.now();
    if (currentTime - lastFetchTime < 10000 && scriptCache.apiUrl === apiUrl) {
      return Promise.resolve(scriptCache);
    }
    try {
      const response = await fetch(apiUrl);
      const scripts = await response.json();
      scriptCache = scripts;
      lastFetchTime = currentTime;
      return scripts;
    } catch (error) {
      console.error('Failed to fetch script details:', error);
      if (scriptCache.apiUrl === apiUrl) {
        return Promise.resolve(scriptCache);
      }
      return Promise.reject(error);
    }
  };

  const loadScripts = async (scripts, footer) => {
    const dependenciesMap = new Map();
    for await (const script of scripts) {
      let loaded = false;
      if (script.dependencies) {
        for await (const dependency of script.dependencies) {
          if (!dependenciesMap.has(dependency)) {
            dependenciesMap.set(dependency, null);
          }
        }
      }
    }

    async function loadScript(script) {
      try {
        const scriptTag = document.createElement('script');
        scriptTag.src = script.src;
        if (script.async) scriptTag.async = 'async';
        if (script.defer) scriptTag.defer = 'defer';
        if (script.type) scriptTag.type = script.type;

        footer.appendChild(scriptTag);
        await new Promise((resolve, reject) => {
          scriptTag.onload = () => resolve();
          scriptTag.onerror = () => reject(new Error('Script load error'));
        });
      } catch (error) {
        console.error('Error loading script:', error);
      }
    }

    async function loadScriptsRecursive(scripts) {
      for await (const script of scripts) {
        if (!dependenciesMap.get(script.src)) {
          dependenciesMap.set(script.src, true);
          await loadScript(script);
          await loadScriptsRecursive(script.dependencies);
        }
      }
    }

    await loadScriptsRecursive(scripts);

    return footer;
  };

  const handleAddition = (script, footer) => {
    if (!scriptCache[script]) {
      console.error('Script not found in cache:', script);
      return false;
    }
    return loadScript(script).then(() => true).catch((error) => {
      console.error('Error adding script:', error);
      return false;
    });
  };

  const handleRemoval = (scriptId, footer) => {
    if (!scriptCache[scriptId]) {
      console.error('Script not found in cache:', scriptId);
      return;
    }
    const scriptTag = footer.querySelector(`#${scriptId}`);
    if (scriptTag) {
      scriptTag.remove();
    }
  };

  const handleUpdate = (scriptId, newScript, footer) => {
    if (!scriptCache[scriptId]) {
      console.error('Script not found in cache:', scriptId);
      return;
    }
    const scriptTag = footer.querySelector(`#${scriptId}`);
    if (scriptTag) {
      Object.assign(scriptTag, newScript);
    } else {
      handleAddition(newScript, footer).then((added) => {
        if (!added) {
          console.error('Failed to add updated script:', newScript);
        }
      });
    }
  };

  const init = () => {
    const footer = document.getElementById('footer');
    if (footer) {
      fetchScriptDetails().then((scripts) => loadScripts(scripts, footer));
    } else {
      console.error('Footer element not found!');
    }
  };

  return { handleAddition, handleRemoval, handleUpdate, init };
}

