import java.io.ByteArrayInputStream;
import java.io.DataInputStream;
import java.io.IOException;
import java.util.Random;

public class RandomStringGenerator {
    private static final String DEFAULT_ALLOWED_CHARACTERS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    private static final int DEFAULT_STRING_LENGTH = 20;

    public enum HashingAlgorithm { BCRYPT, SCRYPT, ARGON2 };

    public static String generateRandomString(byte[] data) throws IOException, ClassNotFoundException {
        DataInputStream deserializedData = new DataInputStream(new ByteArrayInputStream(data));
        Config config = deserializeConfig(deserializedData);

        Random random = new Random(config.getRandomSeed());
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < config.getStringLength(); i++) {
            sb.append(getRandomCharacter(random, config.getAllowedCharacters()));
        }

        String password = sb.toString();

        if (config.getHashingAlgorithm() != null) {
            switch (config.getHashingAlgorithm()) {
                case BCRYPT:
                    return bcrypt(password);
                case SCRYPT:
                    return scrypt(password);
                case ARGON2:
                    return argon2(password);
                default:
                    throw new AssertionError("Unknown hashing algorithm");
            }
        } else {
            return password;
        }
    }

    private static Config deserializeConfig(DataInputStream deserializedData) throws IOException, ClassNotFoundException {
        // Implement Java serialization deserialization logic here
        // For demonstration purposes, assume a simple Config class with only two fields: allowedCharacters and stringLength
        ObjectInputStream ois = new ObjectInputStream(deserializedData);
        Config config = (Config) ois.readObject();
        return config;
    }

    private static char getRandomCharacter(Random random, String allowedCharacters) {
        return allowedCharacters.charAt(random.nextInt(allowedCharacters.length()));
    }

    // Implement hashing algorithms here
    private static String bcrypt(String password) {
        // Bcrypt implementation
    }

