public class LruCache<K, V> where K : IEquatable<K>
{
    private readonly Dictionary<K, V> _cache;
    private readonly int _capacity;

    public LruCache(int capacity)
    {
        _cache = new Dictionary<K, V>();
        _capacity = capacity;
    }

    public V Get(K key)
    {
        if (_cache.TryGetValue(key, out V value))
        {
            // Cache hit
            return value;
        }
        else
        {
            // Cache miss
            if (_cache.Count >= _capacity)
            {
                K evictKey = _cache.Keys.ElementAt(0);
                _cache.Remove(evictKey);
            }

            return default(V);
        }
    }
}

