// Asynchronous reducer function for array of numbers
async function reduce(numbers, initial, callback) {
  let result = initial;
  for await (num of numbers) {
    try {
      result = await callback(result, num);
    } catch (error) {
      return { error: true, value: error };
    }
  }
  return { error: false, value: result };
}

