function resolveDependency(moduleName) {
  const cachedResult = cache.get(moduleName);
  if (cachedResult) return cachedResult;

  // Resolve dependency using the external package manager
  const result = await require('package-manager').resolve(moduleName);

  cache.set(moduleName, result);
  return result;
}

