```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <pthread.h>

// External logging service API
#include "logging_service_api.h"

// Function prototypes
void* process_file(void* arg);
int read_log_line(char* line, int* last_two_fields);
double calculate_average(int* fields);

// Command-line options
char* log_dir = NULL;
char* logging_service_endpoint = NULL;
int verbosity_level = 0;
int max_concurrent_threads = 10;
int message_queue_size = 100;
int progress_report_interval = 60;

// Thread pool and concurrency management
pthread_t* thread_pool = NULL;
int num_threads = 0;
int num_files_processed = 0;
sem_t file_sem = SEM_FAILED;
sem_t report_sem = SEM_FAILED;

int main(int argc, char** argv) {
    // Parse command-line options
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-d") == 0) {
            log_dir = argv[i + 1];
            i++;
        } else if (strcmp(argv[i], "-e") == 0) {
            logging_service_endpoint = argv[i + 1];
            i++;
        } else if (strcmp(argv[i], "-v") == 0) {
            verbosity_level = atoi(argv[i + 1]);
            i++;
        }
    }

    // Initialize thread pool and concurrency management
    num_threads = max_concurrent_threads;
    thread_pool = (pthread_t*)malloc(num_threads * sizeof(pthread_t));
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&thread_pool[i], NULL, process_file, NULL);
    }

    // Process log files concurrently
    DIR* dir = opendir(log_dir);
    if (dir == NULL) {
        perror("Error opening directory");
        return -1;
    }
    struct dirent* ent;
    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) {
            continue;
        }
        char file_path[1024];
        sprintf(file_path, "%s/%s", log_dir, ent->d_name);
        pthread_mutex_lock(&file_sem);
        sem_post(&file_sem);
        pthread_mutex_unlock(&file_sem);
    }
    closedir(dir);

    // Wait for all threads to finish
    for (int i = 0; i < num_threads; i++) {
        pthread_join(thread_pool[i], NULL);
    }

    return 0;
}

void* process_file(void* arg) {
    // Read log file line by line and process each line concurrently
    FILE* file = fopen(arg, "r");
    if (file == NULL) {
        return NULL;
    }
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        pthread_mutex_lock(&report_sem);
        int last_two_fields[2];
        read_log_line(line, last_two_fields);
        double average = calculate_average(last_two_fields);
        report_average_to_logging_service(average);
        pthread_mutex_unlock(&report_sem);
    }
    fclose(file);
    return NULL;
}

int read_log_line(char* line, int* last_two_fields) {
    // Implement log file parsing logic to extract the last two numerical fields
    // ...
    return 0;
}

double calculate_average(int* fields) {
    // Calculate the average of the last two numerical fields
    double sum = (fields[0] + fields[1]) / 2.0;
    return sum;
}
