#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    IMAGE,
    TEXT,
    AUDIO
} ResourceType;

typedef struct {
    ResourceType type;
    int count;
} ResourceItem;

void loadResourceBundle(const char* filePath) {
    FILE* file = fopen(filePath, "rb");
    if (!file) return; // handle error

    size_t fileSize = file_size(file);
    unsigned char* buffer = malloc(fileSize);

    fread(buffer, 1, fileSize, file);
    fclose(file);

    // parse resource entries
    ResourceItem* resources = NULL;
    int numResources = 0;

    for (int i = 0; i < fileSize; i++) {
        unsigned char typeByte = buffer[i];
        int count = *(int*)&buffer[i + 1];

        if (typeByte == IMAGE) {
            // allocate memory for image resource
        } else if (typeByte == TEXT) {
            // allocate memory for text resource
        } else if (typeByte == AUDIO) {
            // allocate memory for audio resource
        }

        resources[numResources].type = typeByte;
        resources[numResources].count = count;
        numResources++;
    }

    free(buffer);

    return resources;
}
