using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public static class GraphQLQueryBuilder
{
    public async Task<GraphQLQueryResult> BuildAndExecuteGraphQLQuery(
        IGQLClient client, 
        string queryTemplate, 
        Dictionary<string, object> parameters)
    {
        // Validate input parameters to prevent injection attacks
        foreach (var parameter in parameters)
        {
            if (!queryTemplate.Contains($"{{{parameter.Key}}})"))
            {
                throw new ArgumentException("Invalid query template", nameof(queryTemplate));
            }
        }

        try
        {
            // Dynamically construct the GraphQL query based on the query template and input parameters
            string query = string.Format(queryTemplate, parameters);

            // Execute the GraphQL query using the provided client
            var result = await client.ExecuteQueryAsync(query);

            return new GraphQLQueryResult { Data = result };
        }
        catch (Exception ex)
        {
            // Log any errors that occur during the query execution
            Console.WriteLine($"Error executing GraphQL query: {ex.Message}");

            throw;
        }
    }

    public class GraphQLQueryResult
    {
        public object Data { get; set; }
    }
}

public interface IGQLClient
{
    Task<object> ExecuteQueryAsync(string query);
}
