        try:
            with open(file_path, 'r') as f:
                data = json.load(f)
        except json.JSONDecodeError as e:
            self.logger.error(f"Invalid JSON in {file_path}: {e}")
            return
        except Exception as e:
            self.logger.error(f"Failed to load {file_path}: {e}")
            return

        orders = []
        for order in data['orders']:
            if self.validate_order(order, criteria):
                orders.append(order)

        if not orders:
            self.logger.info(f"No matching orders found with criteria {criteria}")
            return

        if output_format == 'csv':
            with StringIO() as f:
                writer = csv.writer(f)
                header = ['Order ID', 'Customer Name', 'Total']
                writer.writerow(header)
                for order in orders:
                    row = [order['id'], order['customer']['name'], order['total']]
                    writer.writerow(row)
                return f.getvalue()

        elif output_format == 'pdf':
            with BytesIO() as f:
                pdf = pdfkit.from_string(f, 'Test PDF')
                return f.getvalue()
