    PyObject* response = validate_request(NULL, request);
    if (!response) {
        printf("Invalid request!\n");
        return 1;
    }

    int status = PyInt_AsLong(PyObject_GetAttrString(response, "status"));
    char* message = PyBytes_AsString(PyObject_GetAttrString(response, "message"));
    printf("Status: %d, Message: %s\n", status, message);

    // Clean up
    Py_DECREF(request);
    Py_XDECREF(response);
    Py_Finalize();

    return 0;
