        config_data = self.from_json(config_json)
        for key, value in config_data.items():
            if isinstance(value, dict):
                # Handle nested configurations
                pass  # TO DO: implement recursive loading

    def load_configs_concurrently(self, config_files: List[str]) -> None:
        threads = []
        for file in config_files:
            thread = threading.Thread(target=self.load_config, args=(file,))
            threads.append(thread)
            thread.start()
        for thread in threads:
            thread.join()

