import time
from datetime import datetime

class ValidationException(Exception):
    pass

class PaymentGatewayIntegration:
    def __init__(self):
        self.payment_status_db = {}

    def validateCardDetails(self, cardNumber, expirationDate, cvv):
        if not self._validate_card_number(cardNumber) or not self._validate_expiration_date(expirationDate) or not self._validate_cvv(cvv):
            raise ValidationException("Invalid card details")

    def _validate_card_number(self, cardNumber):
        # implement credit card number validation
        return True

    def _validate_expiration_date(self, expirationDate):
        try:
            datetime.strptime(expirationDate, "%m/%y")
            return True
        except ValueError:
            return False

    def _validate_cvv(self, cvv):
        if len(str(cvv)) != 3 or not str(cvv).isdigit():
            return False
        return True

    def processPayment(self, orderId, cardNumber, expirationDate, cvv):
        try:
            self.validateCardDetails(cardNumber, expirationDate, cvv)
            for attempt in range(1, 5):  # retry up to 4 times with exponential backoff
                response = self._simulate_payment_gateway_call(orderId, cardNumber, expirationDate, cvv)
                if response['status'] == 'success':
                    return f"Payment processed successfully for order {orderId}"
                elif response['status'] == 'failure' and attempt < 4:
                    time.sleep(2 ** attempt)  # exponential backoff
                else:
                    raise Exception(f"Payment failed: {response['error_message']}")
        except ValidationException as e:
            return f"Validation error: {e}"

    def _simulate_payment_gateway_call(self, orderId, cardNumber, expirationDate, cvv):
        # simulate a call to the payment gateway API
        if random.randint(0, 1):  # simulate transient errors
            return {'status': 'failure', 'error_message': "Insufficient funds"}
        else:
            return {'status': 'success'}

    def capturePayment(self, orderId):
        if self.payment_status_db.get(orderId) == 'authorized':
            for _ in range(3):  # retry up to 2 times with no delay
                try:
                    response = self._simulate_payment_gateway_call_capture(orderId)
                    if response['status'] == 'success':
                        self.payment_status_db[orderId] = 'captured'
                        return f"Payment captured successfully for order {orderId}"
                    else:
                        raise Exception(f"Payment capture failed: {response['error_message']}")
                except KeyError as e:
                    return f"Order {orderId} not found"
            else:
                return "Payment capture failed"
        else:
            return f"Payment already captured for order {orderId}"

    def _simulate_payment_gateway_call_capture(self, orderId):
        # simulate a call to the payment gateway API for capturing
        if random.randint(0, 1):  # simulate transient errors
            return {'status': 'failure', 'error_message': "Card declined"}
        else:
            return {'status': 'success'}

    def refundPayment(self, orderId):
        if self.payment_status_db.get(orderId) == 'captured':
            for _ in range(3):  # retry up to 2 times with no delay
                try:
                    response = self._simulate_payment_gateway_call_refund(orderId)
                    if response['status'] == 'success':
                        self.payment_status_db[orderId] = 'refunded'
                        return f"Payment refunded successfully for order {orderId}"
                    else:
                        raise Exception(f"Payment refund failed: {response['error_message']}")
                except KeyError as e:
                    return f"Order {orderId} not found"
            else:
                return "Payment refund failed"
        else:
            return f"Payment already refunded for order {orderId}"

    def _simulate_payment_gateway_call_refund(self, orderId):
        # simulate a call to the payment gateway API for refunding
        if random.randint(0, 1):  # simulate transient errors
            return {'status': 'failure', 'error_message': "Insufficient funds"}
        else:
            return {'status': 'success'}

    def updatePaymentStatus(self, orderId, status):
        if self.payment_status_db.get(orderId) is not None:
            for _ in range(3):  # retry up to 2 times with no delay
                try:
                    response = self._simulate_payment_gateway_call_update(orderId, status)
                    if response['status'] == 'success':
                        self.payment_status_db[orderId] = status
                        return f"Payment status updated successfully for order {orderId}"
                    else:
                        raise Exception(f"Payment status update failed: {response['error_message']}")
                except KeyError as e:
                    return f"Order {orderId} not found"
            else:
                return "Payment status update failed"
        else:
            return f"Order {orderId} not found"

    def _simulate_payment_gateway_call_update(self, orderId, status):
        # simulate a call to the payment gateway API for updating the payment status
        if random.randint(0, 1):  # simulate transient errors
            return {'status': 'failure', 'error_message': "Payment status update failed"}
        else:
            return {'status': 'success'}

    def _get_payment_status(self, orderId):
        return self.payment_status_db.get(orderId)
