            }

            try
            {
                // Process large list of integers from multiple files
                List<int> allIntegers = await ProcessFiles();
                int largestInteger = allIntegers.Max();
                double average = allIntegers.Average();

                Console.WriteLine($"Largest integer: {largestInteger}");
                Console.WriteLine($"Average: {average}");
            }
            catch (Exception ex)
            {
                // Log and handle errors
                Console.WriteLine("Error occurred while processing files:");
                Console.WriteLine(ex.Message);
            }

            // Clean up resources
        }

        static bool ValidateNetCoreVersion()
        {
            // Check the .NET Core version installed on the system
            // Implement your validation logic here

            return true;  // Replace with actual result of validation
        }

        static async Task<List<int>> ProcessFiles()
        {
            List<int> allIntegers = new List<int>();

            foreach (string file in Directory.GetFiles("path_to_your_files"))
            {
                try
                {
                    int[] integersInFile = File.ReadAllBytes(file).Select(b => BitConverter.ToInt32(BitConverter.GetBytes(b), 0)).ToArray();
                    allIntegers.AddRange(integersInFile);
                }
                catch (Exception ex)
                {
                    // Log and handle errors
                    Console.WriteLine($"Error occurred while processing file '{file}':");
                    Console.WriteLine(ex.Message);
                }
            }

            return allIntegers;
        }
    }
}
