import requests
import json
from typing import List, Dict

def fetch_user_data(api_url: str, filters: Dict) -> List:
    results = []
    page_size = 100
    offset = 0

    while True:
        params = {'offset': f"{offset}", 'page-size': f"{page_size}"}

        try:
            response = requests.get(api_url, params=params)

            if not response.status_code == 200:
                raise Exception(f"API request failed with status code {response.status_code}")

            data = json.loads(response.text)

            for user in data['users']:
                if all(filter_val in str(user[filter_key]) for filter_key, filter_val in filters.items()):
                    results.append({key: value for key, value in zip(['id', 'name', 'age'], [user[0], user[1], user[2]])})

            if len(data['users']) < page_size:
                break

        except Exception as e:
            print(f"Error fetching data: {e}")

    return results

