typedef struct {
    int *states;
    int num_states;
    int last_state;
} FSA;

int* traverse_dom(FSA* fsa, const char* selector) {
    // recursively traverse DOM tree and check states against the given selector
    // handle memory allocation/deallocation carefully
    // return list of matching states

    int *matching_states = (int*)malloc((fsa->num_states + 1) * sizeof(int));
    int next_state = 0;

    for (int i = 0; i < fsa->num_states; i++) {
        if (check_selector(fsa->states[i], selector)) {
            matching_states[next_state++] = fsa->states[i];
        }
    }

    matching_states[next_state] = -1; // mark the end of the list

    return matching_states;
}

void free_matching_states(int *matching_states) {
    free(matching_states);
}
