#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

// Define the structure for a review
typedef struct {
    int rating;
    char comment[256];
} Review;

// Define the structure for a product
typedef struct {
    char name[256];
    double price;
    List* reviews; // Linked list of reviews
} Product;

// Define the structure for a linked list node
typedef struct Node {
    Review review;
    struct Node* next;
} ListNode;

// Function to create a new review node
ListNode* createReviewNode(int rating, char* comment) {
    ListNode* node = (ListNode*)malloc(sizeof(ListNode));
    if (!node) return NULL; // Handle memory allocation failure

    node->review.rating = rating;
    strcpy(node->comment, comment);
    node->next = NULL;

    return node;
}

// Function to add a review to a product
void addReview(Product* product, int rating, char* comment) {
    ListNode* newReview = createReviewNode(rating, comment);
    if (!newReview) return; // Handle memory allocation failure

    if (product->reviews == NULL) {
        product->reviews = newReview;
    } else {
        ListNode* current = product->reviews;
        while (current->next) current = current->next;
        current->next = newReview;
    }
}

// Function to calculate the average rating for a product
double calculateAverageRating(Product* product) {
    double sum = 0.0;
    int count = 0;

    ListNode* current = product->reviews;
    while (current) {
        sum += current->review.rating;
        count++;
        current = current->next;
    }

    if (!count) return 0.0; // Handle case where no reviews exist
    return sum / count;
}

// Function to serialize a product to JSON format
json_object* productToJson(Product* product) {
    json_object* root = json_object_new_object();
    json_object_object_add(root, "name", json_string(product->name));
    json_object_object_add(root, "price", json_real(product->price));

    ListNode* current = product->reviews;
    while (current) {
        json_object* review = json_object_new_object();
        json_object_object_add(review, "rating", json_integer(current->review.rating));
        json_object_object_add(review, "comment", json_string(current->comment));
        json_object_array_add(root, "reviews", &review);
        current = current->next;
    }

    return root;
}

// Function to deserialize a product from JSON format
Product* productFromJson(json_object* json) {
    Product* product = (Product*)malloc(sizeof(Product));
    if (!product) return NULL; // Handle memory allocation failure

    json_object_object_get_ex(json, "name", &json_string);
    strcpy(product->name, json_string->val_str);

    json_object_object_get_ex(json, "price", &json_real);
    product->price = json_real->val_double;

    json_object* reviewsJson = json_object_object_get(json, "reviews");
    ListNode* current = NULL;
    while (json_object_array_next(reviewsJson, &review)) {
        ProductReview* reviewStruct = (ProductReview*)malloc(sizeof(ProductReview));
        if (!reviewStruct) return NULL; // Handle memory allocation failure

        json_object_object_get_ex(review, "rating", &json_integer);
        reviewStruct->rating = json_integer->val_int;

        json_object_object_get_ex(review, "comment", &json_string);
        strcpy(reviewStruct->comment, json_string->val_str);

        if (!current) {
            product->reviews = createReviewNode(reviewStruct->rating, reviewStruct->comment);
            current = product->reviews;
        } else {
            ListNode* temp = product->reviews;
            while (temp->next) temp = temp->next;
            temp->next = createReviewNode(reviewStruct->rating, reviewStruct->comment);
        }
    }

    return product;
}

// Example usage:
int main() {
    Product* product1 = (Product*)malloc(sizeof(Product));
    if (!product1) return 1; // Handle memory allocation failure

    strcpy(product1->name, "Product 1");
    product1->price = 19.99;

    addReview(product1, 4, "Good product");
    addReview(product1, 5, "Excellent product");

    json_object* json = productToJson(product1);
    // Save the JSON to a file...

    Product* product2 = productFromJson(json);
    // Load the JSON from the file...

    printf("Average rating of Product 1: %.2f\n", calculateAverageRating(product1));

    return 0;
}
