using System;
using UnityEngine;

public sealed class CustomRandomGenerator : IDisposable
{
    private readonly Random _random;
    private long _seed = -1;
    private readonly object _syncLock = new object();

    public CustomRandomGenerator(int seed)
    {
        _seed = seed;
        _random = new Random(_seed);
    }

    public int NextInt(int min, bool isExclusive, int? max = null)
    {
        if (!IsValidRange(min, max))
            throw new ArgumentOutOfRangeException(nameof(max), "Invalid range");

        return isExclusive ? min + _random.Next(1, (max ?? 0) - min + 1) : _random.Next(min, (max ?? 0) + 1);
    }

    public float NextFloat(float min, bool isExclusive, float? max = null)
    {
        if (!IsValidRange(min, max))
            throw new ArgumentOutOfRangeException(nameof(max), "Invalid range");

        return isExclusive ? min + (float)_random.NextDouble() * ((max ?? 0) - min) : _random.Range(min, (max ?? 0));
    }

    public string ToString()
    {
        return $"Current seed: {_seed}, Next random value: {NextInt(1, true)}";
    }

    private bool IsValidRange(int? min, int? max)
    {
        return min.HasValue && max.HasValue && min.Value <= max.Value;
    }

    public void Dispose()
    {
        _random = null;
    }
}

public sealed class CustomRandomGenerator : IDisposable
{
    public static event Action<RandomSeedGeneratedEventArgs> OnSeedGeneratedValue;

    private readonly Random _random;
    private long _seed = -1;
    private readonly object _syncLock = new object();

    public CustomRandomGenerator(int seed)
    {
        _seed = seed;
        _random = new Random(_seed);
    }

    public int NextInt(int min, bool isExclusive, int? max = null)
    {
        if (!IsValidRange(min, max))
            throw new ArgumentOutOfRangeException(nameof(max), "Invalid range");

        return isExclusive ? min + _random.Next(1, (max ?? 0) - min + 1) : _random.Next(min, (max ?? 0) + 1);
    }

    public float NextFloat(float min, bool isExclusive, float? max = null)
    {
        if (!IsValidRange(min, max))
            throw new ArgumentOutOfRangeException(nameof(max), "Invalid range");

        return isExclusive ? min + (float)_random.NextDouble() * ((max ?? 0) - min) : _random.Range(min, (max ?? 0));
    }

    public string ToString()
    {
        return $"Current seed: {_seed}, Next random value: {NextInt(1, true)}";
    }

    private bool IsValidRange(int? min, int? max)
    {
        return min.HasValue && max.HasValue && min.Value <= max.Value;
    }

    public void Dispose()
    {
        _random = null;
    }
