from flask import Flask, request, jsonify
import boto3
import os
import logging

app = Flask(__name__)

# Configure AWS S3 client
s3 = boto3.client('s3', aws_access_key_id=os.environ['AWS_ACCESS_KEY_ID'],
                                         aws_secret_access_key=os.environ['AWS_SECRET_ACCESS_KEY'])

# Set up logging
logging.basicConfig(level=logging.INFO)

# Define user roles and permissions
user_roles = {
    'admin': ['read', 'write', 'delete'],
    'reader': ['read']
}

@app.route('/upload_file', methods=['POST'])
def upload_file():
    if request.method == 'POST':
        file_name = request.form['file_name']
        file_size = int(request.form['file_size'])
        bucket_name = os.environ['S3_BUCKET_NAME']

        # Start multipart upload
        try:
            multipart_upload_id = s3.create_multipart_upload(Bucket=bucket_name, Key=file_name)['UploadId']
        except Exception as e:
            logging.error(f"Error creating multipart upload: {e}")
            return jsonify({'error': 'failed_to_create_upload'}), 500

        # Process file parts
        part_numbers = []
        for chunk in request.files['file']:
            try:
                s3.upload_part(Bucket=bucket_name, Key=file_name, PartNumber=len(part_numbers)+1,
                               UploadId=multipart_upload_id, Body=chunk.read())
                part_numbers.append(len(part_numbers))
            except Exception as e:
                logging.error(f"Error uploading file part: {e}")
                return jsonify({'error': 'failed_to_upload_file'}), 500

        # Complete multipart upload
        try:
            s3.complete_multipart_upload(Bucket=bucket_name, Key=file_name,
                                          UploadId=multipart_upload_id, MultipartUpload={'Parts': [{'PartNumber': part_num, 'ETag': chunk.etag} for part_num in part_numbers]})
        except Exception as e:
            logging.error(f"Error completing multipart upload: {e}")
            return jsonify({'error': 'failed_to_complete_upload'}), 500

        return jsonify({'file_uploaded': True})

@app.route('/download_file', methods=['GET'])
def download_file():
    file_name = request.args.get('file_name')

    # Check file existence and permissions
    if not s3.head_object(Bucket=os.environ['S3_BUCKET_NAME'], Key=file_name):
        return jsonify({'error': 'file_not_found'}), 404

    try:
        response = s3.get_object(Bucket=os.environ['S3_BUCKET_NAME'], Key=file_name)
    except Exception as e:
        logging.error(f"Error downloading file: {e}")
        return jsonify({'error': 'failed_to_download_file'}), 500

    return response['Body'].read()

@app.route('/get_file_versions', methods=['GET'])
def get_file_versions():
    file_name = request.args.get('file_name')

    # Get object versions
    try:
        versions = s3.list_object_versions(Bucket=os.environ['S3_BUCKET_NAME'], Prefix=file_name)['VersionSummaries']
    except Exception as e:
        logging.error(f"Error getting file versions: {e}")
        return jsonify({'error': 'failed_to_get_versions'}), 500

    return jsonify(versions)

@app.route('/set_file_permission', methods=['PUT'])
def set_file_permission():
    file_name = request.form['file_name']
    user_role = request.form['user_role']

    # Set file permission
    try:
        if user_role in user_roles and 'write' in user_roles[user_role]:
            s3.put_object_acl(Bucket=os.environ['S3_BUCKET_NAME'], Key=file_name, ACL={'Grants': [{'Permission': 'Write', 'Type': 'Group', 'URI': f'arn:aws:iam::123456789012:group/{user_role}'}, {'Permission': 'Read', 'Type': 'Group', 'URI': f'arn:aws:iam::123456789012:group/{user_role}'}]})
        else:
            return jsonify({'error': 'insufficient_permissions'}), 403
    except Exception as e:
        logging.error(f"Error setting file permission: {e}")
        return jsonify({'error': 'failed_to_set_permission'}), 500

    return jsonify({'permission_updated': True})

if __name__ == '__main__':
    app.run(debug=True)
