import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.Random;
import org.apache.commons.codec.binary.StringUtils;
import org.apache.commons_CODEC.DigestUtils;

public class ObjectDeserializer {

    public String deserializeAndGenerateHashedString(byte[] data, int randomStringLength, char[] characterSet) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            Object obj = ois.readObject();
            Random rand = new Random();
            StringBuilder sb = new StringBuilder();
            for(int i=0; i<randomStringLength; i++) {
                sb.append((char)(rand.nextInt(characterSet.length)));
            }
            String randomString = sb.toString();

            String passwordHash = DigestUtils.md5Hex(new String(data));
            return randomString + "#" + passwordHash;
        } catch (ClassNotFoundException e) {
            throw new RuntimeException("Class not found", e);
        }
    }
}
