#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

// Structure to represent a product review
typedef struct {
    int rating;
    char *comment;
} Review;

// Structure to represent a product with reviews
typedef struct {
    char *name;
    double price;
    Review *reviews;
    int num_reviews;
} Product;

// Function to create a new product with an empty list of reviews
Product* create_product(char *name, double price) {
    Product *product = (Product*)malloc(sizeof(Product));
    product->name = name;
    product->price = price;
    product->reviews = NULL;
    product->num_reviews = 0;
    return product;
}

// Function to add a review to a product
void add_review(Product *product, int rating, char *comment) {
    Review *new_review = (Review*)malloc(sizeof(Review));
    new_review->rating = rating;
    new_review->comment = comment;

    if (product->reviews == NULL) {
        product->reviews = new_review;
    } else {
        Review *curr = product->reviews;
        while (curr != NULL && curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = new_review;
    }
    product->num_reviews++;
}

// Function to calculate the average rating for a product
double calc_average_rating(Product *product) {
    double sum = 0.0;
    int count = 0;
    Review *curr = product->reviews;
    while (curr != NULL) {
        sum += curr->rating;
        count++;
        curr = curr->next;
    }
    return sum / count;
}

// Function to serialize the product data to a JSON file
void serialize_products(Product **products, int num_products) {
    json_object *root = json_object_new();
    for (int i = 0; i < num_products; i++) {
        Product *product = products[i];
        json_object *product_obj = json_object_new();

        // Add product name and price to JSON object
        json_object_object_add(product_obj, "name", json_string(product->name));
        json_object_object_add(product_obj, "price", json_real(product->price));

        // Add reviews to JSON object
        json_object_object_add(product_obj, "reviews", json_object_new());
        Review *curr = product->reviews;
        while (curr != NULL) {
            json_object_object_add(product_obj->reviews, curr->comment, json_string(curr->comment));
            curr = curr->next;
        }

        // Add product object to root JSON object
        json_object_object_add(root, products[i]->name, product_obj);
    }
    FILE *fp = fopen("products.json", "w");
    json_object_to_file_fp(root, fp);
    fclose(fp);
}

// Function to deserialize the product data from a JSON file
void deserialize_products(Product ***products) {
    json_object *root = json_object_from_file("products.json");
    int num_products = json_object_get_type(root) == JSON_OBJECT ? 0 : -1;
    for (int i = 0; i < num_products; i++) {
        Product **product = &(*products)[i];
        json_object *product_obj = json_object_object_get(root, (*products)[i]->name);

        // Get product name and price from JSON object
        char *name = json_string_value(json_object_object_get(product_obj, "name"));
        double price = json_real_value(json_object_object_get(product_obj, "price"));

        // Add reviews to product
        json_object *reviews_obj = json_object_object_get(product_obj, "reviews");
        Review **curr = &((*product)->reviews);
        while (json_object_object_size(reviews_obj) > 0) {
            char *comment = json_string_value(json_object_object_get(reviews_obj, (char *)malloc(strlen(name) + strlen(comment) + 1)));
            (*curr)->rating = 5; // default rating
            (*curr)->comment = comment;
            curr++;
        }
    }
}

int main() {
    Product **products = (Product**)malloc(sizeof(Product*) * 10);

    for (int i = 0; i < 10; i++) {
        products[i] = create_product(, );
    }

    // Add reviews to products
    add_review(products[0], 4, "Great product!");
    add_review(products[1], 3, "Good but not great");
    ...

    // Serialize the product data to a JSON file
    serialize_products(products, 10);

    // Deserialize the product data from the JSON file
    deserialize_products(&products);

    return 0;
}
