EVP_CIPHER_CTX* init_cipher(int mode, int key_size) {
    EVP_CIPHER_CTX* ctx;
    unsigned char* key = NULL;
    unsigned char* iv = NULL;
    unsigned char* salt = NULL;

    // Check for valid key sizes
    if (key_size != 128 && key_size != 192 && key_size != 256) {
        return NULL;  // Error: invalid key size
    }

    // Generate the key and IV securely
    int key_len = EVP_MAX_KEY_LENGTH;
    int iv_len = EVP_MAX_IV_SIZE;
    if (!EVP_PacketWrite(key, &key_len, EVP_CIPHER_key_length(EVP_aes_256_CBC()))) {
        return NULL;  // Error: failed to generate key
    }
    if (!EVP_PacketWrite(iv, &iv_len, EVP_CIPHER_iv_length(EVP_aes_256_CBC()))) {
        return NULL;  // Error: failed to generate IV
    }

    // Initialize the cipher context
    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return NULL;  // Error: unable to initialize cipher context
    }

    // Set the cipher mode and key size
    if (!EVP_CipherInit(ctx, EVP_aes_256_GCM(), key, iv)) {
        return NULL;  // Error: failed to initialize cipher context with AES-GCM
    } else if (mode == 2) { // CBC mode
        if (!EVP_CipherInit(ctx, EVP_aes_256_CBC(), key, iv)) {
            return NULL;  // Error: failed to initialize cipher context with AES-CBC
        }
    }

    // Set the custom salt value
    if (salt != NULL) {
        if (!EVP_SaltBytesSet(ctx, salt)) {
            return NULL;  // Error: failed to set custom salt value
        }
    } else { // Use a default salt value
        unsigned char* default_salt = ...; // Generate or specify the default salt value
        if (!EVP_SaltBytesSet(ctx, default_salt)) {
            return NULL;  // Error: failed to set default salt value
        }
    }

    return ctx;
}
