import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

import javax.servlet.ServletContext;
import javax.xml.bind.DatatypeConverter;

import org.apache.commons.io.IOUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.slf4j.spi.LoggingExceptionUtils;

public class Md5HashCalculator {

    private static final Logger LOG = LoggerFactory.getLogger(Md5HashCalculator.class);
    private Map<String, String> cache = new HashMap<>();
    private ServletContext servletContext;

    public void setServletContext(ServletContext servletContext) {
        this.servletContext = servletContext;
    }

    public String calculateMd5(String filePath) throws IOException {
        try (FileInputStream fileInputStream = new FileInputStream(new File(filePath))) {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = IOUtils.toByteArray(fileInputStream);
            byte[] thedigest = md.digest(hashBytes);
            return DatatypeConverter.printHexBinary(thedigest).toUpperCase();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    public boolean verifyMd5(String filePath, String expectedHash) throws IOException {
        try {
            String actualHash = calculateMd5(filePath);
            return actualHash.equals(expectedHash);
        } catch (IOException e) {
            LOG.error("Failed to read file for verification: {}", filePath, e);
            return false;
        }
    }

    public void initLogging() {
        String logPath = System.getProperty("LOG_PATH");
        if (logPath == null || logPath.isEmpty()) {
            logPath = "logs";
        }
        File logDir = new File(logPath);
        int retryCount = 0;
        while (!logDir.exists()) {
            try {
                logDir.mkdirs();
                break;
            } catch (SecurityException e) {
                if (retryCount < 3) {
                    LOG.info("Error creating log directory. Retrying in 2 seconds...");
                    IOUtils.sleep(2000);
                    retryCount++;
                } else {
                    throw new RuntimeException(e);
                }
            }
        }
        servletContext.setAttribute("log.path", logPath);
    }

    public void configureLogging() {
        String logLevel = System.getProperty("LOG_LEVEL");
        if (logLevel == null || logLevel.isEmpty()) {
            logLevel = "INFO";
        }
        String logFormat = System.getProperty("LOG_FORMAT");
        if (logFormat == null || logFormat.isEmpty()) {
            logFormat = "%d{yyyy-MM-dd'T'HH:mm:ss.SSS} [%thread] %-5level %logger{36} - %msg%n";
        }
        LOG.info("Logging configured with level {} and format {}", logLevel, logFormat);
    }

    public void rotateAndCleanLogs() {
        File logDir = new File((String) servletContext.getAttribute("log.path"));
        for (File file : logDir.listFiles()) {
            if (!file.getName().endsWith(".log")) {
                file.delete();
            } else {
                try {
                    IOUtils.copy(file, new File(logDir, "archive-" + file.getName()));
                    file.delete();
                } catch (IOException e) {
                    LOG.error("Error rotating logs: {}", e);
                }
            }
        }
    }

}
