    {
        _storageAccount = CloudStorageAccount.Parse(storageConnectionString);
        _blobClient = _storageAccount.CreateCloudBlobClient();
        _blobClient.DefaultServiceName = defaultServiceName;
    }

    public async Task<UploadResult> UploadAsync(string filePathOrByteArray, string bucketName, string containerName, CancellationToken cancellationToken)
    {
        // Authenticate with the token-based service and obtain necessary upload permissions
        await AuthenticateAndObtainPermissions(cancellationToken);

        // Create a cloud blob client instance for the specified bucket and container
        CloudBlobClient cloudBlobClient = _blobClient.GetCloudBlobClient(bucketName).GetCloudBlobContainerReference(containerName).GetCloudBlobClient();

        if (string.IsNullOrEmpty(filePathOrByteArray))
        {
            return new UploadResult { IsSuccessful = false, ErrorMessage = "Invalid file path or byte array" };
        }

        // Handle file paths and byte arrays as input
        CloudBlockBlob cloudBlockBlob;
        using (var memoryStream = new MemoryStream())
        {
            if (filePathOrByteArray is string filePath)
            {
                await File.ReadAllBytesAsync(filePath).CopyToAsync(memoryStream, cancellationToken);
            }
            else
            {
                // Assume it's a byte array
