import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

public class RealTimeChatService {

    private final BlockingQueue<Message> messageQueue = new LinkedBlockingQueue<>();
    private WebSocketProtocol webSocketProtocol;
    private HttpLongPollingProtocol httpLongPollingProtocol;
    private NotificationService notificationService;
    private ErrorHandlingMechanism errorHandlingMechanism;

    public void start() {
        // Initialize protocols and services
        webSocketProtocol = new WebSocketProtocol();
        httpLongPollingProtocol = new HttpLongPollingProtocol();
        notificationService = new NotificationService();
        errorHandlingMechanism = new ErrorHandlingMechanism();

        // Start listening for incoming messages on both protocols
        webSocketProtocol.start(messageQueue);
        httpLongPollingProtocol.start(messageQueue);

        // Start delivering queued messages to connected clients
        deliverMessages();
    }

    public void sendMessage(Message message) {
        // Add message to queue and notify protocol handlers
        messageQueue.add(message);
        webSocketProtocol.sendMessage(message);
        httpLongPollingProtocol.sendMessage(message);
    }

    private void deliverMessages() {
        while (true) {
            try {
                Message message = messageQueue.take();
                // Deliver message to connected clients using selected protocol
                if (message.isWebSocketMessage()) {
                    webSocketProtocol.deliverMessage(message);
                } else if (message.isHttpLongPollingMessage()) {
                    httpLongPollingProtocol.deliverMessage(message);
                }
            } catch (InterruptedException e) {
                errorHandlingMechanism.handleInterruptedDelivery(e);
            } catch (Exception e) {
                errorHandlingMechanism.handleErrorDuringDelivery(e);
            }
        }
    }

}

class WebSocketProtocol {

    private WebSocketServer webSocketServer;

    public void start(BlockingQueue<Message> messageQueue) {
        // Start WebSocket server
        webSocketServer = new WebSocketServer();
        webSocketServer.start(messageQueue);
    }

    public void sendMessage(Message message) {
        // Send message to connected WebSocket clients
        webSocketServer.send(message);
    }

    public void deliverMessage(Message message) {
        // Deliver message to connected WebSocket clients using selected protocol
        webSocketServer.deliverMessage(message);
    }
}

class HttpLongPollingProtocol {

    private HttpLongPollingServer httpLongPollingServer;

    public void start(BlockingQueue<Message> messageQueue) {
        // Start HTTP long-polling server
        httpLongPollingServer = new HttpLongPollingServer();
        httpLongPollingServer.start(messageQueue);
    }

    public void sendMessage(Message message) {
        // Send message to connected HTTP clients using long-polling
        httpLongPollingServer.send(message);
    }

    public void deliverMessage(Message message) {
        // Deliver message to connected HTTP clients using selected protocol
        httpLongPollingServer.deliverMessage(message);
    }
}

class NotificationService {

    public void sendNotification(Message message, User user) {
        // Send notification to user using SMS or email
        // ...
    }
}

class ErrorHandlingMechanism {

