#include <iostream>
#include <memory>
#include <mutex>
#include <condition_variable>

class OctreeNode {
public:
    virtual ~OctreeNode() {}
    virtual void insert(int x, int y, int z) = 0;
};

class LeafNode : public OctreeNode {
public:
    std::vector<int> points;

    void insert(int x, int y, int z) override {
        points.push_back(x);
        points.push_back(y);
        points.push_back(z);
    }
};

class InternalNode : public OctreeNode {
private:
    std::unique_ptr<OctreeNode> child[8];

public:
    InternalNode() {
        for (auto& c : child)
            c = nullptr;
    }

    void insert(int x, int y, int z) override {
        if (x < 0 && y < 0 && z < 0) {
            // Handle negative coordinates
        }
        int dim = std::min({abs(x), abs(y), abs(z)});
        int axis = -1;
        if (dim == abs(x))
            axis = 0; // X-axis
        else if (dim == abs(y))
            axis = 1; // Y-axis
        else
            axis = 2; // Z-axis

        if (!child[axis]->get()) {
            child[axis] = std::make_unique<OctreeNode>();
        }
        child[axis]->insert(x / dim, y / dim, z / dim);
    }

    void query(int x, int y, int z) {
        if (x < 0 && y < 0 && z < 0) {
            // Handle negative coordinates
        }
        int dim = std::min({abs(x), abs(y), abs(z)});
        int axis = -1;
        if (dim == abs(x))
            axis = 0; // X-axis
        else if (dim == abs(y))
            axis = 1; // Y-axis
        else
            axis = 2; // Z-axis

        child[axis]->query(x / dim, y / dim, z / dim);
    }
};

class Octree {
private:
    std::unique_ptr<OctreeNode> root;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void insert(int x, int y, int z) {
        if (!root.get()) {
            root = std::make_unique<InternalNode>();
        }
        root->insert(x, y, z);
    }

    void query(int x, int y, int z) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait_for(lock, std::chrono::milliseconds(100));
        root->query(x, y, z);
    }

    Octree() : root(nullptr) {}

    ~Octree() {}
};

int main() {
    Octree octree;
    // Insert and query data
    return 0;
}
