    public class HtmlContentService : IHtmlContentService
    {
        private readonly ILogger<HtmlContentService> _logger;
        private readonly IConnectionMultiplexer _redisConnection;
        private readonly IBlobStorageService _blobStorageService;

        public HtmlContentService(ILogger<HtmlContentService> logger, IConnectionMultiplexer redisConnection, IBlobStorageService blobStorageService)
        {
            _logger = logger;
            _redisConnection = redisConnection;
            _blobStorageService = blobStorageService;
        }

        [HttpPost]
        public async Task<IActionResult> UpdateHtmlContent([FromUri]int pageSectionId, [FromUri]int elementId, [FromBody]string htmlContent)
        {
            // Check for invalid input
            if (pageSectionId <= 0 || elementId <= 0 || string.IsNullOrEmpty(htmlContent))
            {
                return BadRequest("Invalid input");
            }

            try
            {
                // Fetch HTML content from Redis cache
                string cachedHtmlContent = await GetCachedHtmlContent(pageSectionId, elementId);

                // If the content is already up-to-date in the cache, return a 304 status code
                if (!string.IsNullOrEmpty(cachedHtmlContent) && IsValidUpdate(htmlContent, cachedHtmlContent))
                {
                    return new HttpStatusCodeResult(304);
                }

                // Update the HTML content in Redis and blob storage
                await UpdateHtmlContentInRedisAndBlobStorage(pageSectionId, elementId, htmlContent);

                // Log the update operation
                _logger.LogInformation("HTML content updated for page section {PageSectionId} and element {ElementId}", pageSectionId, elementId);

                return Ok();
            }
            catch (Exception ex)
            {
                // Handle exceptions and log errors
                _logger.LogError(ex, "Error updating HTML content");
                if (ex is StorageServiceUnavailableException)
                {
                    // Fallback to serving cached content when storage service is unavailable
                    return new HttpStatusCodeResult(503);
                }
                else
                {
                    return BadRequest("Failed to update HTML content");
                }
            }
        }

        private async Task<string> GetCachedHtmlContent(int pageSectionId, int elementId)
        {
            // Retrieve the cached HTML content from Redis using a distributed locking mechanism
            string cachedHtmlContent = await _redisConnection.ExecuteAsyncAsync(async (connection) => 
            {
                using (var lockResult = connection.Lock("html-content-lock", "my-unique-key"))
                {
                    if (!lockResult)
                    {
                        return null;
                    }

                    // Check for stale cache and refresh it if necessary
                    string cachedHtmlContent = await _blobStorageService.GetHtmlContent(pageSectionId, elementId);
                    if (cachedHtmlContent == null)
                    {
                        lockResult.Dispose();
                        return null;
                    }

                    return cachedHtmlContent;
                }
            });

            return cachedHtmlContent;
        }

        private async Task UpdateHtmlContentInRedisAndBlobStorage(int pageSectionId, int elementId, string htmlContent)
        {
            // Update the HTML content in Redis
            await _redisConnection.ExecuteAsyncAsync(async (connection) => 
            {
                using (var lockResult = connection.Lock("html-content-lock", "my-unique-key"))
                {
                    if (!lockResult)
                    {
                        throw new StorageServiceUnavailableException();
                    }

                    // Update the HTML content in blob storage
                    await _blobStorageService.UpdateHtmlContent(pageSectionId, elementId, htmlContent);

                    lockResult.Dispose();
                }
            });

            // Version the HTML content for auditing and rollbacks
            await _blobStorageService.VersionHtmlContent(pageSectionId, elementId);
        }

