class FileStorageManager {
    private $fileStore = [];
    private $cache = [];

    public function uploadFile($filename, $fileContent) {
        // Handle file upload logic here
    }

    public function downloadFile($filename) {
        if (!isset($this->fileStore[$filename])) {
            return null;
        }

        $content = $this->fileStore[$filename];
        if ($this->cache[$filename]) {
            unset($this->cache[$filename]);
        }
        return $content;
    }

    public function listFiles() {
        return array_keys($this->fileStore);
    }

    public function deleteFile($filename) {
        if (!isset($this->fileStore[$filename])) {
            return false;
        }

        unset($this->fileStore[$filename]);
        if (isset($this->cache[$filename])) {
            unset($this->cache[$filename]);
        }
        return true;
    }

    public function renameFile($oldFilename, $newFilename) {
        if (!isset($this->fileStore[$oldFilename])) {
            return false;
        }

        unset($this->fileStore[$oldFilename]);
        $this->fileStore[$newFilename] = $this->fileStore[$oldFilename];
        unset($this->cache[$oldFilename]);
        $this->cache[$newFilename] = true;
        return true;
    }
}
