import software.amazon.awssdk.core.sync.RequestBodying;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.PutObjectRequest;

public class FileTransferManager {
    private S3Client s3Client;
    private Map<String, String> cachedFiles = new HashMap<>();
    private int chunkSize = 1024 * 1024; // default chunk size in bytes

    public FileTransferManager(S3Client s3Client) {
        this.s3Client = s3Client;
    }

    public void startSyncTransfer(String localDirPath, String bucketName, TransferDirection direction, FileFilter filter) throws IOException {
        if (direction == TransferDirection.UPLOAD) {
            uploadFiles(localDirPath, bucketName, filter);
        } else {
            downloadFiles(localDirPath, bucketName, filter);
        }
    }

    private void uploadFiles(String localDirPath, String bucketName, FileFilter filter) throws IOException {
        Files.walkFileTree(new File(localDirPath), new SimpleFileVisitor<File>() {
            @Override
            public FileVisitResult visitFile(File file, BasicFileAttributes attrs) throws IOException {
                if (filter.accept(file)) {
                    uploadFileToS3(bucketName, file);
                }
                return FileVisitResult.CONTINUE;
            }
        });
    }

    private void downloadFiles(String localDirPath, String bucketName, FileFilter filter) throws IOException {
        S3Client.listObjectsV2Paginator(bucketName).forEach(obj -> {
            if (filter.accept(new File(localDirPath + "/" + obj.key()))) {
                downloadFileFromS3(bucketName, obj.key(), new File(localDirPath));
            }
        });
    }

    private void uploadFileToS3(String bucketName, File file) throws IOException {
        try (InputStream input = Files.newInputStream(file.toPath())) {
            s3Client.putObject(PutObjectRequest.builder()
                    .bucket(bucketName)
                    .key(file.getName())
                    .build(), RequestBodying.of(input));
        }
    }

    private void downloadFileFromS3(String bucketName, String key, File file) throws IOException {
        try (InputStream input = s3Client.getObject(getDownloadRequest(bucketName, key))) {
            Files.copy(input, file.toPath());
        }
    }

    private GetObjectRequest getDownloadRequest(String bucketName, String key) {
        // implement S3 client caching and error handling here
        return s3Client.getObject(GetObjectRequest.builder()
                .bucket(bucketName)
                .key(key)
                .build());
    }
}
