**PHP: Secure Random String Generator and Hashing Function**

```php
<?php

function generateSecureRandomString($length, $characterSet) {
  if (!$length || !$characterSet) return;
  $chars = implode('', array_map('ord', $characterSet));
  $randomString = '';
  for ($i = 0; $i < $length; $i++) {
    $randomString .= $chars[rand(0, strlen($chars) - 1)];
  }
  return $randomString;
}

function hashPassword($password, $algorithm = 'bcrypt', $saltLength = 16) {
  if (!$password || !$algorithm) return;
  $salt = generateSecureRandomString($saltLength, 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789');
  $hashedPassword = password_hash("$password$salt", $algorithm);
  return array('salt' => $salt, 'hash' => $hashedPassword);
}

