```python
import os
import csv
import json
import gzip
from oauthlib.oauth2 import WebApplicationClient

class FileProcessor:
    def __init__(self, dir_path):
        self.dir_path = dir_path
        self.stats = {"text": 0, "log": 0, "csv": 0, "json": 0}

    def process_files(self):
        for file in os.listdir(self.dir_path):
            if file.endswith(".txt") or file.endswith(".log"):
                with open(os.path.join(self.dir_path, file), 'r') as f:
                    self.stats["text"] += len(f.read().splitlines())
            elif file.endswith(".csv"):
                with open(os.path.join(self.dir_path, file), 'r') as f:
                    reader = csv.reader(f)
                    self.stats["csv"] += sum(1 for row in reader)
            elif file.endswith(".json"):
                with open(os.path.join(self.dir_path, file), 'r') as f:
                    data = json.load(f)
                    self.stats["json"] += len(data)

    def get_stats(self):
        return self.stats

class WebApp:
    def __init__(self, client_id, redirect_uri):
        self.client_id = client_id
        self.redirect_uri = redirect_uri
        self.oauth_client = WebApplicationClient(client_id)

    def start(self):
        app = Flask(__name__)
        @app.route('/stats')
        def get_stats():
            return jsonify(FileProcessor.get_stats())
        app.run()

if __name__ == "__main__":
    file_processor = FileProcessor("path/to/files")
    file_processor.process_files()
    web_app = WebApp("client_id", "redirect_uri")
    web_app.start()
