import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class FileUploadProcessor {
    public void processFileUploads(BlockingQueue<ultipartFile> uploadQueue, int maxConcurrency, StorageHandlerFactory storageHandlerFactory) {
        ThreadPoolExecutor threadPool = new ThreadPoolExecutor(maxConcurrency, maxConcurrency, 0L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<Runnable>());

        for (int i = 0; i < maxConcurrency; i++) {
            threadPool.submit(() -> {
                FileUploadHandler fileUploadHandler = null;
                try {
                    while (uploadQueue.peek() != null) {
                        FilePart filePart = uploadQueue.take();
                        if (fileUploadHandler == null || !fileUploadHandler.isAlive()) {
                            fileUploadHandler = storageHandlerFactory.createStorageHandler(filePart);
                        }
                        fileUploadHandler.uploadFilePart(filePart);
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                } finally {
                    try {
                        if (fileUploadHandler != null) {
                            fileUploadHandler.close();
                        }
                    } catch (Exception e) {
                        // Handle exceptions
                    }
                }
            });
        }

        threadPool.shutdown();
    }
}
