class TransactionCache:
    def __init__(self):
        self.cache = {}
        self.refresh_interval = 30  # seconds

    async def get_transactions(self, gateway_id: str) -> List[Dict]:
        if gateway_id in self.cache:
            return self.cache[gateway_id]
        return []

    async def put_transaction(self, gateway_id: str, transaction_data: Dict):
        if gateway_id not in self.cache:
            self.cache[gateway_id] = []
        self.cache[gateway_id].append(transaction_data)
        await asyncio.sleep(self.refresh_interval)

class PaymentGatewayManager:
    def __init__(self):
        self.gateways = {}
        self.cache = TransactionCache()

    async def get_gateway_transactions(self, gateway_id: str) -> List[Dict]:
        return await self.cache.get_transactions(gateway_id)

    async def process_transaction(self, transaction_data: Dict) -> bool:
        gateway_id = transaction_data['gateway_id']
        if gateway_id not in self.gateways:
            self.gateways[gateway_id] = PaymentGateway(gateway_id)
        gateway = self.gateways[gateway_id]
        return await gateway.process_transaction(transaction_data)

class App(FastAPI):
