class MOBAAbilityModule {
public:
    MOBAAbilityModule() : abilityDatabase_(nullptr), cache_(new std::unordered_map<std::string, Json::Value>) {}

    ~MOBAAbilityModule() { delete abilityDatabase_; }

    void initialize(std::string databaseUrl) {
        abilityDatabase_ = new RESTfulAPI(databaseUrl);
        startWebSocketListener();
    }

    void assignAbilities(Player& player) {
        auto roleLevel = getRoleAndLevel(player);
        auto teamComposition = getTeamComposition(player);

        // Fetch abilities based on role, level, and team composition
        Json::Value abilities;
        if (!fetchAbilities(abilities, roleLevel, teamComposition)) {
            return; // Unable to fetch abilities
        }

        // Assign available abilities to player's character
        assignAvailableAbilities(abilities, player);
    }

private:
    RESTfulAPI* abilityDatabase_;
    std::unordered_map<std::string, Json::Value>* cache_;

    void startWebSocketListener() {
        // Start WebSocket connection to receive real-time updates
        WebSocketConnection conn;
        conn.onMessage([this](const std::string& message) {
            updateAbilityDatabase(message);
        });
        conn.listen();
    }

    bool fetchAbilities(Json::Value& abilities, const RoleLevel& roleLevel, const TeamComposition& teamComposition) {
        // Use caching strategy to reduce latency and improve performance
        if (cache_->count(roleLevel.toString() + teamComposition.toString())) {
            Json::Value cachedAbilities = cache_->at(roleLevel.toString() + teamComposition.toString());
            abilities = cachedAbilities;
            return true;
        }

        // Fetch from ability database via RESTful API
        std::string url = "https://api.abilitydatabase.com/abilities";
        auto response = abilityDatabase_->get(url, roleLevel.toString(), teamComposition.toString());

        if (response.ok()) {
            Json::Value jsonAbilities;
            jsonAbilities.parse(response.body());
            cache_->insert({roleLevel.toString() + teamComposition.toString(), jsonAbilities});
            abilities = jsonAbilities;
            return true;
        }

        return false; // Unable to fetch abilities
    }

    void updateAbilityDatabase(const std::string& message) {
        // Handle real-time updates to ability database via WebSocket connection
        Json::Value updatedAbilities;
        try {
            updatedAbilities.parse(message);
            cache_->clear();
            for (const auto& pair : cache_) {
                if (!updatedAbilities["abilities"][pair.first].empty()) {
                    pair.second = updatedAbilities["abilities"][pair.first];
                }
            }
        } catch (...) {
            // Handle errors during updates
            std::cout << "Error updating ability database: " << message << std::endl;
        }
    }

    void assignAvailableAbilities(const Json::Value& abilities, Player& player) {
        // Assign available abilities to player's character based on current role and level
        for (const auto& pair : abilities["abilities"]) {
            if (player.getRole().canUseAbility(pair["name"])) {
                player.assignAbility(pair["name"]);
            }
        }
    }

    std::pair<std::string, Json::Value> getRoleAndLevel(const Player& player) const {
        // Implement logic to determine role and level based on player's current state
        return {"warrior", Json::Value()};
    }

    TeamComposition getTeamComposition(const Player& player) const {
        // Implement logic to determine team composition based on players in the same game session
        return TeamComposition();
    }
};

class RESTfulAPI {
public:
    RESTfulAPI(std::string databaseUrl) : url_(databaseUrl) {}

    Json::Value get(std::string method, const std::string& roleLevel, const std::string& teamComposition) {
        // Implement logic to send GET request to ability database
        return {};
    }

private:
