#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/ssl.h>

typedef struct {
    char *json_path;
    char **filter_criteria;
    int num_filter_criteria;
    char *output_format;
} FilterCriteria;

int main(void) {
    // Example usage:
    FilterCriteria filter_criteria = {"path/to/json/file.json", {"key1", "value1"}, 1, "CSV"};

    FilterOrders(filter_criteria);

    return 0;
}

void FilterOrders(FilterCriteria filter_criteria) {
    SSL_CTX *ctx;
    SSL *ssl;

    ctx = SSL_CTX_new(TLS_client_method());
    ssl = SSL_new(ctx);

    // Traverse the JSON structure
    json_t *root = json_load_file(filter_criteria.json_path, JSON_NONE);

    if (!root) {
        printf("Error: Unable to load JSON file.\n");
        return;
    }

    // Apply filtering criteria
    for (int i = 0; i < filter_criteria.num_filter_criteria; i++) {
        char *key = filter_criteria.filter_criteria[i];
        json_t *value = json_object_get(root, key);

        if (!value) {
            printf("Error: Filtering criterion '%s' not found.\n", key);
            continue;
        }

