import os
import threading
import time
import logging
from functools import lru_cache

class DirectoryManager:
    def __init__(self):
        self._lock = threading.Lock()
        self._directories = {}
        self._temp_directories = {}
        self._config = None

    @lru_cache(maxsize=None)
    def create_directory(self, directory_path):
        with self._lock:
            if not os.path.exists(directory_path):
                try:
                    os.makedirs(directory_path)
                except (OSError, PermissionError) as e:
                    time.sleep(1)
                    raise
        return True

    @lru_cache(maxsize=None)
    def get_directory(self, directory_path):
        with self._lock:
            return os.path.exists(directory_path)

    def set_config(self, config):
        self._config = config

    def start(self):
        if not self._config:
            raise ValueError("Configuration is required")

    @property
    def temp_directories(self):
        return self._temp_directories

    def cleanup_temporary_directories(self):
        for directory in list(self._temp_directories.keys()):
            if os.path.exists(directory):
                try:
                    os.rmdir(directory)
                except (OSError, PermissionError) as e:
                    pass
        self._temp_directories = {}

    @property
    def directories(self):
        return self._directories

    def get_logger(self):
        logger_name = "directory_manager"
        if not logging.getLogger(logger_name):
            logging.basicConfig(level=logging.INFO)
        return logging.getLogger(logger_name)

# Sample usage:
if __name__ == "__main__":
    dm = DirectoryManager()
    dm.set_config({"temp_directory_lifetime": 60})
    dm.start()

    directory_path = "/path/to/directory"
    if not dm.create_directory(directory_path):
        raise ValueError("Directory creation failed")

    temp_directory_path = os.path.join("/tmp", "temporary")
    dm._temp_directories[temp_directory_path] = None
