const { readdir, stat } = require('fs');
const { join, resolve } = require('path');
const { readFileSync, writeFileSync } = require('fs');
const { parse } = require('json5');
const { promisify } = require('util');
const { load, ModuleLoaderError } = require('./ModuleLoader');

class DynamicModuleLoader {
  constructor({ moduleDir, configDir, ssmParamStore }) {
    this.moduleDir = resolve(moduleDir);
    this.configDir = resolve(configDir);
    this.ssmParamStore = ssmParamStore;
    this.modules = {};
    this.cachedModules = {};
    this.moduleLoader = load();
  }

  async loadModules() {
    const modules = await this.loadModuleDependencies();

    for (const moduleName in modules) {
      try {
        const moduleFile = join(this.moduleDir, `${moduleName}.js`);
        if (!statSync(moduleFile).isFile()) {
          throw new Error(`Module file ${moduleFile} does not exist.`);
        }

        const moduleConfig = await this.loadModuleConfig(moduleName);
        const { dependencies } = parse(readFileSync(join(this.configDir, `${moduleName}.json`), 'utf8'));

        if (!this.modules[moduleName]) {
          this.modules[moduleName] = await this.moduleLoader.loadModule({
            file: moduleFile,
            config: moduleConfig,
            dependencies: dependencies.map((dep) => this.loadModule(dep)),
          });
        }

        if (Object.keys(this.modules).length === 1) {
          return this.modules[moduleName];
        }
      } catch (error) {
        console.error(`Error loading module ${moduleName}: ${error.message}`);
      }
    }
  }

  async loadModuleDependencies() {
    const modules = {};

    for await (const file of readdir(this.moduleDir)) {
      if (!file.endsWith('.js')) continue;

      try {
        const statResult = await promisify(stat)(join(this.moduleDir, file));
        if (!statResult.isFile()) continue;

        const moduleConfig = await this.loadModuleConfig(file.split('.')[0]);
        modules[moduleConfig.name] = true;
      } catch (error) {
        console.error(`Error processing module ${file}: ${error.message}`);
      }
    }

    return modules;
  }

  async loadModuleConfig(moduleName) {
    const configPath = join(this.configDir, `${moduleName}.json`);
    if (!statSync(configPath).isFile()) {
      throw new Error(`Configuration file for module ${moduleName} does not exist.`);
    }

    return parse(readFileSync(configPath, 'utf8'));
  }

  async reloadModules() {
    this.cachedModules = {};
    await this.loadModules();
  }

  async getLoadedModules() {
    return Object.keys(this.modules);
  }

  async initiateReload(modulesToReload) {
    if (!Array.isArray(modulesToReload)) throw new Error('Expected an array of module names');

    for (const moduleName of modulesToReload) {
      await this.moduleLoader.unloadModule(moduleName);
    }

    await this.reloadModules();
  }
}

module.exports = DynamicModuleLoader;
