import requests
import time
import logging
from functools import wraps
from datetime import timedelta, datetime

def fetch_weather_data(api_key, cities, api_url='http://api.openweathermap.org/data/2.5/weather', 
                       cache_duration=timedelta(hours=1), rate_limit_max_retries=5, 
                       log_level=logging.INFO):
    logging.basicConfig(level=log_level)

    def retry_on_rate_limit(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for _ in range(rate_limit_max_retries + 1):
                try:
                    return func(*args, **kwargs)
                except requests.exceptions.RetryError as e:
                    if _ < rate_limit_max_retries:
                        logging.warning(f"Rate limit exceeded. Retrying after {int(time.time() - e.wait_before_retry)} seconds...")
                        time.sleep(e.wait_before_retry + 1)
            raise requests.exceptions.RetryError("Exceeded rate limit")
        return wrapper

    @retry_on_rate_limit
    def fetch_weather(city):
        api_url += f"?q={city}&appid={api_key}&units=metric"
        response = requests.get(api_url, timeout=5)
        if response.status_code == 200:
            logging.info(f"Fetched weather data for {city} at {datetime.now()}")
            return response.json()
        elif response.status_code in (400, 404):
            logging.error(f"Invalid city name or API key: {response.text}. Please check your inputs.")
            raise ValueError(response.text)
        else:
            logging.error(f"API request failed with status code {response.status_code}.")
            raise requests.exceptions.RequestException()

    def fetch_weather_data_secondary(api_key, cities):
        # Secondary API provider implementation
        pass

    def cache_weather(weather_data, city):
        # In-memory caching using a dictionary or OrderedDict
        weather_cache = {}

        @wraps(fetch_weather)
        def wrapper(city):
            if city in weather_cache and datetime.now() - weather_cache[city] <= cache_duration:
                logging.info(f"Using cached weather data for {city} at {datetime.now()}")
                return weather_cache[city]
            else:
                try:
                    result = fetch_weather(city)
                    weather_cache[city] = datetime.now()
                    return result
                except requests.exceptions.RequestException as e:
                    if isinstance(e, requests.exceptions.RetryError):
                        logging.warning(f"Rate limit exceeded. Retrying after {int(time.time() - e.wait_before_retry)} seconds...")
                        time.sleep(e.wait_before_retry + 1)
                    else:
                        logging.error(f"Failed to fetch weather data for {city}: {e}.")
                    raise

    def validate_input(cities):
        if not all(isinstance(city, str) and len(city) > 0 for city in cities):
            raise ValueError("Invalid city names. Please enter valid city names.")
        return True

    # Handle user input and configure rate limiting
    if not api_key:
        raise ValueError("API key is required. Please obtain a valid API key from OpenWeatherMap.")

    try:
        validate_input(cities)
        for city in cities:
            cache_weather(fetch_weather(city), city)

    except requests.exceptions.RequestException as e:
        logging.error(f"Failed to fetch weather data: {e}.")
        # Implement fallback mechanism here
        if rate_limit_max_retries > 0:
            time.sleep(60 * (1 << (rate_limit_max_retries - 1)))
            raise

