  for (let i in regexs) {
    const regex = new RegExp(regexs[i].source, 'gi');

    for (let match of text.matchAll(regex)) {
      let bookName = match[0].replace(/[^\w\s]/g, '');

      if (!results[bookName]) {
        results[bookName] = 1;
      } else {
        results[bookName]++;
      }

      const translation = getTranslation(bookName, language);

      if (translation) {
        results[translation] ? results[translation]++ : (results[translation] = 1);
      } else {
        console.warn(`Warning: No translation available for book ${bookName}.`);
      }
    }
  }

  return Object.fromEntries(Object.entries(results).sort((a, b) => b[1] - a[1]));
}

