Here is the Node.js code block that dynamically loads and executes multiple JavaScript modules:

```javascript
const fs = require('fs');
const path = require('path');
const moduleLoader = require('./module-loader');

class ModuleExecutor {
  constructor(packageName, namespace) {
    this.packageName = packageName;
    this.namespace = namespace;
    this.modules = [];
  }

  async loadModules() {
    try {
      const packagePath = path.join(__dirname, `node_modules/${this.packageName}`);
      const moduleFiles = await fs.readdir(packagePath);
      for (const file of moduleFiles) {
        if (!file.endsWith('.js')) continue;
        const moduleName = file.replace('.js', '');
        this.modules.push(moduleName);
      }
    } catch (error) {
      console.error('Error loading modules:', error);
    }

    await Promise.all(this.modules.map(async (moduleName) => {
      try {
        await moduleLoader.loadModule(`${this.packageName}/${moduleName}`, this.namespace);
      } catch (error) {
        console.error(`Failed to load ${moduleName}:`, error);
      }
    }));
  }
}

module.exports = ModuleExecutor;
