FSA* generate_state_list(int** initial_states, int init_num_states, FSA* fsa, int last_state, int termination_state_id) {
    if (!initial_states || !fsa) {
        return NULL;
    }

    int i = 0;
    while (i < init_num_states && initial_states[i]) {
        i++;
    }
    if (i != init_num_states) {
        return NULL; // invalid input
    }

    FSA* new_state_list = malloc(sizeof(FSA));
    if (!new_state_list) {
        return NULL;  // insufficient memory
    }
    new_state_list->num_states = 1;

    int* states = malloc(sizeof(int));
    if (!states) {
        free(new_state_list);
        return NULL;
    }
    states[0] = initial_states[0][0];
    new_state_list->states = states;

    for (i = 0; i < init_num_states; i++) {
        int* next_states = transition(initial_states[i][0], fsa->symbols[input_id(fsa, initial_states[i][1])], fsa);
        if (!next_states) {
            free(states);
            free(new_state_list);
            return NULL;
        }
        for (int j = 0; j < i + 1; j++) {
            if (j < next_states[0] && new_state_list->states[j] == initial_states[i][0]) {
                new_state_list->num_states++;
                states = realloc(states, sizeof(int) * (new_state_list->num_states));
                for (int k = new_state_list->num_states - 1; k > i; k--) {
                    states[k] = states[k - 1];
                }
                states[i] = next_states[0];
                break;
            }
        }
        free(next_states);
    }

    int* state_list = malloc(sizeof(int) * (new_state_list->num_states));
    for (i = 0; i < new_state_list->num_states; i++) {
        state_list[i] = new_state_list->states[i];
    }
    free(new_state_list->states);
    new_state_list->states = state_list;

    return new_state_list;
}

