```csharp
using System;
using System.Threading.Tasks;
using Microsoft.Web.Administration;

public enum WebsiteOperation { Add, Start, Stop, Remove }

public class DirectoryPath
{
    public string Path { get; set; }
    public ApplicationPool Pool { get; set; }
    public Binding[] Bindings { get; set; }
    public CustomConfig Settings { get; set; }
}

public class TaskResult
{
    public bool Success { get; set; }
    public Exception Error { get; set; }
}

public static async Task<TaskResult> ManageWebsiteLifecycle(WebsiteOperation operation, DirectoryPath directory)
{
    if (!File.Exists(directory.Path + "/web.config"))
    {
        await LogError("No web.config file found in the specified directory.");
        return new TaskResult { Success = false };
    }

    using (var server = new Server())
    {
        try
        {
            switch (operation)
            {
                case WebsiteOperation.Add:
                    if (server.Sites[directory.Path] != null)
                    {
                        await LogError("Website already exists.");
                        return new TaskResult { Success = false };
                    }

                    var site = server.CreateWebsite(directory.Path);
                    site.ApplicationPoolName = directory.Pool.Name;
                    foreach (var binding in directory.Bindings)
                    {
                        site.Bindings.Add(binding);
                    }
                    site.Enable = true;

                    await server.CommitChanges();

                case WebsiteOperation.Start:
                    if (!server.Sites[directory.Path].State.ToString().Equals("Started", StringComparison.OrdinalIgnoreCase))
                    {
                        site.State = ObjectState.Start;
                        await server.CommitChanges();
                    }

                case WebsiteOperation.Stop:
                    if (server.Sites[directory.Path].State.ToString().Equals("Stopped", StringComparison.OrdinalIgnoreCase, CultureInfo.InvariantCulture))
                    {
                        site.State = ObjectState.Stop;
                        await server.CommitChanges();
                    }

                case WebsiteOperation.Remove:
                    foreach (var binding in directory.Bindings)
                    {
                        binding.Delete();
                    }
                    server.Sites[directory.Path].Delete();

                    await server.CommitChanges();
            }
        }
        catch (Exception ex)
        {
            await LogError(ex);
            return new TaskResult { Success = false, Error = ex };
        }
    }

    return new TaskResult { Success = true };
}

private static async Task LogError(Exception ex)
{
    // Implement logging mechanism here
}
