import os
import logging
from datetime import timedelta
from functools import lru_cache
from concurrent.futures import ThreadPoolExecutor
import requests

class WeatherService:
    def __init__(self):
        self.api_keys = {}
        self.oauth_tokens = {}
        self.cached_data = {}
        self.config = {
            'units': 'metric',
            'time_zone': 'UTC',
            'caching_policy': timedelta(minutes=30),
            'logging_level': logging.INFO,
            'log_destination': 'console'
        }
        self.executor = ThreadPoolExecutor()

    def configure(self, api_keys, oauth_tokens, config):
        self.api_keys = api_keys
        self.oauth_tokens = oauth_tokens
        self.config.update(config)

    @lru_cache(maxsize=None)
    def get_weather_data(self, city_name):
        for api_key in self.api_keys:
            try:
                response = requests.get(f'https://api.openweathermap.org/data/2.5/weather?q={city_name}&units={self.config["units"]}', 
                                         headers={'Authorization': f'Bearer {self.oauth_tokens[api_key]}'})
                if response.status_code == 200:
                    return response.json()
            except Exception as e:
                logging.getLogger().log(self.config['logging_level'], f'Error fetching weather data for {city_name}: {str(e)}')

        raise ValueError(f'Failed to fetch weather data for {city_name}')

    def query_weather_data(self, city_names):
        results = {}
        with self.executor:
            futures = [self.executor.submit(get_weather_data, city_name) for city_name in city_names]
            for future in futures:
                try:
                    result = future.result()
                    if result.get('weather'):
                        results[city_name] = result
                except Exception as e:
                    logging.getLogger().log(self.config['logging_level'], f'Error fetching weather data for {city_name}: {str(e)}')

        return results

if __name__ == '__main__':
    logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

    weather_service = WeatherService()
    api_keys = {'primary': 'your_api_key', 'secondary': 'another_api_key'}
    oauth_tokens = {'primary': 'your_oauth_token', 'secondary': 'another_oauth_token'}

    weather_service.configure(api_keys, oauth_tokens, 
                               config={'units': 'metric', 'time_zone': 'UTC', 'caching_policy': timedelta(minutes=30), 'logging_level': logging.INFO, 'log_destination': 'console'})

    city_names = ['New York', 'Los Angeles', 'London']
    results = weather_service.query_weather_data(city_names)
    print(results)

