    int key;
} Record;

Record* init_records(long num_records) {
    Record* records = NULL;
    long* offsets = NULL;
    int* keys = NULL;
    long i, err;

    // Allocate memory for the record structure array
    if ((records = (Record*)malloc(num_records * sizeof(Record))) == NULL) {
        return NULL;
    }

    // Initialize the record structures with default values
    for (i = 0; i < num_records; i++) {
        records[i].offset = -1;
        records[i].key = -1;
    }

    // Clean up on failure to allocate memory
    if (records == NULL) {
        free(records);
        return NULL;
    }

    return records;
