EVP_CIPHER_CTX* setup_cipher(int key_size, int mode) {
    EVP_CIPHER_CTX* ctx;

    if (key_size != 128 && key_size != 192 && key_size != 256) {
        return NULL; // invalid key size
    }

    if ((mode != EVP_aes_128_CBC) && (mode != EVP_aes_128_GCM) &&
        (mode != EVP_aes_192_CBC) && (mode != EVP_aes_192_GCM) &&
        (mode != EVP_aes_256_CBC) && (mode != EVP_aes_256_GCM)) {
        return NULL; // invalid mode
    }

    ctx = OPENSSL_CTX_new(mode);

    if (!ctx) {
        return NULL; // error in EVP_CIPHER_CTX_new
    }

    int key[16]; // temporary storage for generated key
    unsigned char iv[16];

    if (rand_key(key, sizeof(key)) != 0 && rand_iv(iv, sizeof(iv)) != 0) {
        ERR_error_string(ERR_get_error(), NULL);
        OPENSSL_CTX_free(ctx); // free allocated resources
        return NULL; // error in key or IV generation
    }

    EVP_CIPHER_CTX_set_key_length(ctx, key_size);
    EVP_CIPHER_CTX_set_iv(ctx, iv, sizeof(iv));

    return ctx;
