import asyncio
from collections import deque
from typing import Deque, List, Callable, Union

class TaskCustomizerCallback(Callable):
    pass


class AsyncTaskQueueManager:
    def __init__(self):
        self._task_queue: Deque[asyncio.Task] = deque(maxlen=0)
        self._max_size: int = 0
        self._concurrency_level: int = 1

    async def initialize_task_queue(
            self, max_size: int, concurrency_level: int,
            task_customizer_callback: TaskCustomizerCallback = None) -> None:
        if not isinstance(max_size, int) or not isinstance(concurrency_level, int):
            raise ValueError("max_size and concurrency_level must be integers")
        if max_size <= 0:
            raise ValueError("max_size must be greater than 0")
        if concurrency_level <= 0:
            raise ValueError("concurrency_level must be greater than 0")

        self._task_queue = deque(maxlen=max_size)
        self._max_size = max_size
        self._concurrency_level = concurrency_level

    async def enqueue(self, task: asyncio.Task) -> None:
        if not isinstance(task, asyncio.Task):
            raise ValueError("task must be an asyncio Task object")

        while len(self._task_queue) >= self._concurrency_level:
            await self._dequeue()

        self._task_queue.append(task)

    async def dequeue(self) -> asyncio.Task:
        task: asyncio.Task = self._task_queue.popleft()
        return task

    async def customize_tasks(
            self, tasks: List[asyncio.Task], callback: TaskCustomizerCallback) -> None:
        for task in tasks:
            if not isinstance(task, asyncio.Task):
                raise ValueError("tasks must be a list of asyncio Task objects")

        for task in tasks:
            awaitable_task = callback(task)
            if not isinstance(awaitable_task, asyncio.Future):
                raise ValueError("TaskCustomizerCallback must return an asyncio Future")
            self._task_queue.append(awaitable_task)

    async def run(self) -> None:
        while True:
            try:
                task: asyncio.Task = await self.dequeue()
                await task
            except asyncio.CancelledError:
                pass
            except Exception as e:
                # Handle exceptions and retries here
                print(f"Exception occurred: {e}")
