function renderFooterScripts(scripts) {
  const footer = document.getElementById('footer');
  const scriptCache = {};

  async function fetchScript(script) {
    try {
      const response = await fetch(`/api/scripts/${script.id}`);
      const scriptData = await response.text();
      return JSON.parse(scriptData);
    } catch (error) {
      console.error(`Error fetching script ${script.id}:`, error);
      throw error;
    }
  }

  async function renderScript(script) {
    try {
      const cachedScript = scriptCache[script.id];
      if (!cachedScript || script.version > cachedScript.version) {
        const fetchedScript = await fetchScript(script);
        scriptCache[script.id] = { ...fetchedScript, version: script.version };
      }
      footer.innerHTML += `<script id="${script.id}" type="application/${script.type}" src="${script.src}"></script>`;
    } catch (error) {
      console.error(`Error rendering script ${script.id}:`, error);
    }
  }

  async function renderScripts() {
    try {
      for await (const script of scripts) {
        await renderScript(script);
      }
    } catch (error) {
      console.error('Error rendering footer scripts:', error);
    }
  }

  function cleanUpScripts() {
    const oldScripts = Array.from(footer.querySelectorAll('script'));
    oldScripts.forEach((oldScript) => oldScript.remove());
  }

  async function renderFooter() {
    try {
      await renderScripts();
      cleanUpScripts();
    } catch (error) {
      console.error('Error rendering footer:', error);
    }
  }

  async function fetchAndRenderScripts() {
    try {
      const loader = document.getElementById('loader');
      loader.style.display = 'block';
      await renderScripts();
      loader.style.display = 'none';
    } catch (error) {
      console.error('Error fetching and rendering scripts:', error);
    }
  }

  async function run() {
    try {
      await fetchAndRenderScripts();
    } catch (error) {
      console.error('Error running script renderer:', error);
    }
  }

  run();
}

