#include "rapidjson/document.h"
#include "rapidjson/writer.h"
#include "rapidjson/filewritewriter.h"

class Node {
public:
    int key;
    std::string value;
    long creationTimestamp;
    long lastAccessTimestamp;
};

class NodeArray {
private:
    Node* nodes;
    size_t capacity;
    size_t size;

public:
    NodeArray(size_t initialCapacity = 10) : capacity(initialCapacity), size(0) {
        nodes = new Node[capacity];
    }

    ~NodeArray() {
        delete[] nodes;
    }

    void resize(size_t newSize) {
        if (newSize > capacity) {
            capacity = newSize * 2; // grow capacity by factor of 2
            Node* temp = new Node[capacity];
            for (size_t i = 0; i < size; i++) {
                temp[i] = nodes[i]; // copy existing nodes to temporary array
            }
            delete[] nodes;
            nodes = temp;
        }
    }

    void addNode(int key, const std::string& value) {
        if (size >= capacity) {
            resize(capacity * 2); // grow capacity by factor of 2
        }
        Node newNode;
        newNode.key = key;
        newNode.value = value;
        newNode.creationTimestamp = time(nullptr);
        newNode.lastAccessTimestamp = time(nullptr);
        nodes[size] = newNode;
        size++;
    }

    void serializeToJson(NodeArray& nodes, rapidjson::Document& doc) {
        rapidjson::Value jsonNodes(rapidjson::kArrayType);
        for (size_t i = 0; i < size; i++) {
            Node node = nodes[i];
            rapidjson::Value jsonNode;
            jsonNode.SetObject();
            jsonNode.AddMember("key", node.key, doc.GetAllocator());
            jsonNode.AddMember("value", node.value.c_str(), doc.GetAllocator());
            jsonNode.AddMember("creationTimestamp", node.creationTimestamp, doc.GetAllocator());
            jsonNode.AddMember("lastAccessTimestamp", node.lastAccessTimestamp, doc.GetAllocator());
            jsonNodes.Add(jsonNode, doc.GetAllocator());
        }
        doc.AddMember("nodes", jsonNodes, doc.GetAllocator());
    }

    void deserializeFromJson(const rapidjson::Value& jsonNodes) {
        size_t newSize = jsonNodes.Size();
        resize(newSize);
        for (size_t i = 0; i < newSize; i++) {
            Node node;
            rapidjson::Value& jsonObject = jsonNodes[i];
            node.key = jsonObject["key"].GetInt();
            node.value = jsonObject["value"].GetString();
            node.creationTimestamp = jsonObject["creationTimestamp"].GetLong();
            node.lastAccessTimestamp = jsonObject["lastAccessTimestamp"].GetLong();
            nodes[size] = node;
            size++;
        }
    }
};

class DistributedDatabase {
public:
    void setNode(NodeArray& nodeArray) {
        // store node array in distributed database
    }

    void getNode(NodeArray& nodeArray) {
        // retrieve node array from distributed database
    }
};

int main() {
    NodeArray nodeArray;
    DistributedDatabase db;

    // read nodes from configuration file and add them to the node array
    // handle potential errors during file reading

    while (true) {
        std::cout << "Enter command (add, remove, update, serialize, deserialize, or exit): ";
        std::string command;
        std::cin >> command;

        if (command == "exit") {
            break;
        }

        else if (command == "add") {
            int key;
            std::string value;
            // read key and value from user input
            nodeArray.addNode(key, value);
        }

        else if (command == "remove") {
            int key;
            // remove node with given key from the node array
        }

        else if (command == "update") {
            int key;
            std::string value;
            // update node with given key in the node array
        }

        else if (command == "serialize") {
            rapidjson::Document doc;
            nodeArray.serializeToJson(nodeArray, doc);
            // write serialized JSON to file or display it on console
        }

        else if (command == "deserialize") {
