use std::env;
use std::fs::{self, DirEntry};
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

use log::{error, info, warn};
use serde_json::json;

struct DirectoryManager {
    dir_path: Arc<PathBuf>,
    last_cleanup_time: Arc<Mutex<Instant>>,
}

impl DirectoryManager {
    fn new() -> Self {
        let mut dir_path = env::var("MY_DIR_PATH").ok().unwrap_or("/tmp/my_dir".to_string());
        if !dir_path.exists() {
            fs::create_dir_all(&dir_path).unwrap_or_else(|_| {
                error!("Failed to create directory: {}", dir_path.display());
                std::process::exit(1);
            });
        }
        let last_cleanup_time = Arc::new(Mutex::new(Instant::now()));
        DirectoryManager { dir_path: Arc::new(dir_path.into()), last_cleanup_time }
    }

    fn cleanup(&self) {
        let now = Instant::now();
        if *self.last_cleanup_time.lock().unwrap() + Duration::from_secs(600) < now {
            fs::remove_dir_all(&self.dir_path).unwrap_or_else(|_| {
                error!("Failed to clean up directory: {}", self.dir_path.display());
            });
            *self.last_cleanup_time.lock().unwrap() = now;
        }
    }

    fn monitor_disk_usage(&self) -> f64 {
        let disk_usage = fs::metadata(&self.dir_path).unwrap().len() as f64;
        if disk_usage > 0.8 * self.dir_path.parent().unwrap().metadata().unwrap().len() as f64 {
            info!("Disk usage exceeded threshold ({}%)", disk_usage);
            self.cleanup();
        }
        disk_usage
    }
}

fn main() {
    let dir_manager = DirectoryManager::new();

    thread::spawn(move || loop {
        thread::sleep(Duration::from_secs(60 * 10)); // Check every 10 minutes
        dir_manager.cleanup();
    });

    let mut config_file_path = env::var("MY_CONFIG_FILE").ok().unwrap_or("/etc/my_config.json".to_string());
    if !config_file_path.exists() {
        error!("Configuration file not found: {}", config_file_path.display());
    } else {
        info!("Using configuration file: {}", config_file_path.display());
    }

    loop {
        let disk_usage = dir_manager.monitor_disk_usage();
        thread::sleep(Duration::from_secs(1)); // Monitor every second
    }
}
