```python
import os
import pathlib
import logging
import multiprocessing

def get_file_stats(directory_path):
    try:
        directory = pathlib.Path(directory_path)
        if not directory.is_dir():
            raise ValueError("Invalid directory path")

        total_lines = 0
        total_words = 0
        total_chars = 0

        for file in directory.glob("**/*"):
            if file.suffix in [".md", ".pdf"]:  # exclude specific file types
                continue

            try:
                with file.open("r") as f:
                    lines = f.readlines()
                    total_lines += len(lines)
                    words = sum(len(line.split()) for line in lines)
                    total_words += words
                    chars = sum(len(line) for line in lines)
                    total_chars += chars
            except (OSError, IOError):
                logging.error(f"Error reading file {file}")

        return {"total_lines": total_lines, "total_words": total_words, "total_chars": total_chars}

    except Exception as e:
        logging.error("An error occurred: {}".format(e))
        return None

def main(directory_path=None, output_file=None):
    if directory_path is None:
        raise ValueError("Directory path is required")

    args = multiprocessing.Process()
    results = []

    for file_stats in multiprocess.Pool().map(get_file_stats, [directory_path]):
        if file_stats is not None:
            results.append(file_stats)

    if output_file:
        with open(output_file, "w") as f:
            f.write(str(results))

if __name__ == "__main__":
    import sys
    main(*sys.argv[1:])
