      const encryptedData = await service.putParameter({
        Name: `/${env}/config`,
        Value: JSON.stringify(instance),
        Type: 'SecureString',
      });
      console.log(`Config saved to SSM parameter store: ${encryptedData.Location}`);
    } catch (err) {
      console.error('Error saving config to service:', err);
    }
  }

  async getConfigFromService(env) {
    try {
      const service = new AWS.SSM(); // or GoogleCloudSecretManager
      const params = { Name: `/${env}/config` };
      const response = await service.getParameter(params).promise();
      if (response.Parameter.Value) {
        return JSON.parse(response.Parameter.Value);
      }
    } catch (err) {
      console.error('Error getting config from service:', err);
    }
  }

  async generateTokenAndHash(apiKeyOrSecret, env) {
    const randomToken = this.randomTokenGenerator;
    const hashedValue = crypto.createHmac('sha256', apiKeyOrSecret).update(randomToken).digest().toString('hex');
    return { randomToken, hashedValue };
  }
}
