// footer.js
const { fetchScripts, renderScripts } = require('./scriptLoader');
const { setLoadingSpinner } = require('./loadingIndicator');

class Footer {
  constructor(apiEndpoint) {
    this.apiEndpoint = apiEndpoint;
    this.scriptCache = {};
  }

  async loadScripts() {
    try {
      const response = await fetch(this.apiEndpoint);
      const scripts = await response.json();
      return scripts;
    } catch (error) {
      console.error('Error fetching scripts:', error);
      throw error;
    }
  }

  async renderScripts(scripts, max ScriptsToLoadAtOnce = 5) {
    const renderedScripts = [];
    let currentScriptCount = 0;

    for (const script of scripts) {
      if (currentScriptCount >= maxScriptsToLoadAtOnce) {
        await setLoadingSpinner('loading');
        currentScriptCount = 0;
      }

      try {
        const scriptResponse = await fetch(script.url);
        const scriptHTML = await scriptResponse.text();
        renderedScripts.push(scriptHTML);
        currentScriptCount++;
      } catch (error) {
        console.error(`Error loading script ${script.name}:`, error);
      }
    }

    return renderedScripts.join('');
  }

  async renderFooter(scripts, maxScriptsToLoadAtOnce = 5) {
    const renderedScripts = await this.renderScripts(scripts, maxScriptsToLoadAtOnce);

    return `
      <footer>
        ${renderedScripts}
      </footer>
    `;
  }
}

module.exports = Footer;
