from threading import Lock
from functools import wraps
from typing import Dict

class DirectoryManager:
    def __init__(self, root_dir: str, config: dict):
        self.root_dir = root_dir
        self.config = config
        self.lock = Lock()

    def _get_parent_dir(self, dir_path: str) -> str:
        return os.path.dirname(dir_path)

    def _create_dir(self, dir_path: str) -> None:
        while True:
            try:
                os.makedirs(dir_path)
                break
            except OSError as e:
                if self.config["retry_on_failure"]:
                    time.sleep(self.config["retry_delay"])
                else:
                    raise

    @wraps(_create_dir)
    def create_dir(self, dir_path: str) -> None:
        with self.lock:
            self._create_dir(dir_path)

    def _get_env_var(self, var_name: str) -> str:
        return os.environ.get(var_name, "")

    @wraps(_get_env_var)
    def get_env_var(self, var_name: str) -> str:
        return self._get_env_var(var_name)

    def _set_env_var(self, var_name: str, value: str) -> None:
        os.environ[var_name] = value

    @wraps(_set_env_var)
    def set_env_var(self, var_name: str, value: str) -> None:
        self._set_env_var(var_name, value)

