struct MyApp {
    config: Arc<RwLock<config::Config>>,
    api_clients: Vec<Arc<api::ApiClient>>,
    logging_level: logging::LogLevel,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut file = File::open("config.json")?;
    let mut config_string = String::new();
    file.read_to_string(&mut config_string)?;

    let config = serde_json::from_str::<config::Config>(&config_string)?;
    let api_clients = vec![Arc::new(api::ApiClient::new())];
    let logging_level = logging::LogLevel::INFO;

    let app = MyApp {
        config: Arc::new(RwLock::new(config)),
        api_clients,
        logging_level,
    };

    tokio::spawn(async move {
        health_check::run(&app.config, &app.api_clients).await;
    });

    loop {
        // Handle incoming requests
        if let Ok(request) = app.handle_request().await {
            match request {
                api::Request::Function1 => {
                    let client = &api_clients[0];
                    let response = client.function1().await?;
                    logging::log(&app.logging_level, "Response from function1: {:?}", response);
                }
                api::Request::Function2 => {
                    // ...
                }
            }
        }
    }
}

async fn handle_request() -> Result<api::Request, Box<dyn std::error::Error>> {
    // Read request from socket
    let mut file = File::open("requests.txt")?;
    let mut requests = String::new();
    file.read_to_string(&mut requests)?;

    let request: api::Request = serde_json::from_str(&requests)?;
    Ok(request)
}

