```c
#include <string.h>
#include <stdlib.h>

char* appendDirectoryPath(const char* filePath, const char* directoryPath, size_t maxSize) {
    size_t filePathLen = strlen(filePath);
    size_t directoryPathLen = strlen(directoryPath);
    size_t fullPathLen = filePathLen + directoryPathLen;

    // Check for null pointers and empty strings
    if (!filePath || !directoryPath) return NULL;

    // Handle the case where filePath already ends with a directory separator
    if (filePath[filePathLen - 1] == '/') {
        fullPathLen--;
    }

    // Check for exceeding size limit
    if (fullPathLen > maxSize) {
        // Truncate the path to fit within the limit
        char* truncatedPath = (char*)malloc((maxSize + 1) * sizeof(char));
        strncpy(truncatedPath, filePath, maxSize - directoryPathLen);
        strcat(truncatedPath, directoryPath);
        return truncatedPath;
    }

    // Create a new string for the full path without exceeding the size limit
    char* fullPath = (char*)malloc((fullPathLen + 1) * sizeof(char));
    strncpy(fullPath, filePath, filePathLen);
    strcat(fullPath, directoryPath);
    return fullPath;
}
