        return;
    }

    // Decompress the file if it's compressed
    int file_descriptor = fileno(file);
    struct stat sb;
    fstat(file_descriptor, &sb);

    if (S_ISREG(sb.st_mode) && strcmp(file_path + strlen(file_path) - 3, ".gz") == 0) {
        // Decompress the file using zlib
        File* file_info = malloc(sizeof(File));
        file_info->file_name = strdup(file_path);
        file_info->file_descriptor = open(file_path, O_RDONLY);
        file_info->stream.zalloc = Z_NULL;
        file_info->stream.zfree = Z_NULL;
        inflateInit(&file_info->stream);

        // Read the decompressed data
