import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.ApplicationContext;
import org.springframework.context.annotation.Bean;
import org.springframework.core.io.FileSystemResource;
import org.springframework.core.io.Resource;
import org.springframework.security.config.annotation.authentication.builders.AuthenticationManagerBuilder;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.annotation.web.configuration.WebSecurityConfigurerAdapter;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.oauth2.config.OAuth2SecurityConfiguration;
import org.springframework.security.oauth2.provider.OAuth2Authentication;
import org.springframework.security.provisioning.JdbcUserDetailsManager;
import org.springframework.security.provisioning.UserDetailsManager;
import org.yaml.snakeyaml.Yaml;

@SpringBootApplication
@EnableWebSecurity
public class YamlConfigLoaderApplication {

    @Bean
    public YamlConfigLoader yamlConfigLoader() {
        return new YamlConfigLoader();
    }

    public static void main(String[] args) throws Exception {
        SpringApplication.run(YamlConfigLoaderApplication.class, args);
    }
}

class YamlConfigLoader {
    private final Map<String, Object> configMap = new HashMap<>();
    private final List<YamlConfig> yamlConfigs;
    private final ObjectMapper mapper;
    private final Yaml yaml;

    public YamlConfigLoader() {
        this.yamlConfigs = new ArrayList<>();
        this.mapper = new ObjectMapper().enable(SerializationFeature.INDENT_OUTPUT);
        this.yaml = new Yaml();

        // load all yaml config files
        Resource[] resources = Resources.filesToMatch("config/*.yml");
        for (Resource resource : resources) {
            try {
                String yamlString = IOUtils.toString(resource.getInputStream(), StandardCharsets.UTF_8.name());
                Object obj = mapper.readValue(yamlString, Object.class);

                // register the config in the map
                if (!configMap.containsKey(obj.getClass().getSimpleName())) {
                    configMap.put(obj.getClass().getSimpleName(), obj);
                    yamlConfigs.add(new YamlConfig(obj));
                }
            } catch (IOException e) {
                logger.error("Failed to load YAML config file: " + resource.getFilename(), e);
            }
        }
    }

    public void loadConfig() {
        // iterate over all the loaded configs
        for (YamlConfig yamlConfig : yamlConfigs) {
            try {
                Object obj = mapper.readValue(yamlString, Object.class);
                configMap.put(obj.getClass().getSimpleName(), obj);
            } catch (IOException e) {
                logger.error("Failed to load YAML config file: " + resource.getFilename(), e);
            }
        }
    }

    public YamlConfig getConfiguration(String id) {
        return yamlConfigs.stream()
                .filter(config -> config.getId().equals(id))
                .findFirst()
                .orElseThrow(() -> new ConfigurationNotFoundException(id));
    }
}

class YamlConfig {
    private final String id;
    private final Object obj;

    public YamlConfig(Object obj) {
        this.id = obj.getClass().getSimpleName();
        this.obj = obj;
    }

    public String getId() {
        return id;
    }

    public Object getObj() {
        return obj;
    }
}
