import asyncio
from typing import Any, Dict, List, Optional

class TaskCustomizerCallback:
    def __call__(self, task: Any) -> Any:
        raise NotImplementedError

class AsyncTaskQueueManager:
    def __init__(self):
        self._task_queue = []
        self._max_size = None
        self._concurrency_level = None
        self._customizers: List[TaskCustomizerCallback] = []

    async def initialize_task_queue(
            self,
            max_size: int,
            concurrency_level: int,
            customizers: Optional[List[TaskCustomizerCallback]] = None,
    ) -> None:
        if max_size is not None and concurrency_level is not None:
            if max_size < 1 or concurrency_level < 1:
                raise ValueError("Max size and concurrency level must be positive integers.")
        self._max_size = max_size
        self._concurrency_level = concurrency_level
        if customizers is not None:
            self._customizers = customizers

    async def enqueue_task(self, task: Any) -> None:
        await self._apply_customizers(task)
        self._task_queue.append(task)

    async def dequeue_task(self) -> Optional[Any]:
        try:
            return self._task_queue.pop(0)
        except IndexError:
            return None

    async def _apply_customizers(self, task: Any) -> None:
        for customizer in self._customizers:
            await asyncio.create_task(customizer(task))

    def get_max_size(self) -> int:
        return self._max_size

    def set_max_size(self, max_size: int) -> None:
        if max_size is not None and max_size > 0:
            self._max_size = max_size
        else:
            raise ValueError("Max size must be a positive integer.")

    def get_concurrency_level(self) -> int:
        return self._concurrency_level

    def set_concurrency_level(self, concurrency_level: int) -> None:
        if concurrency_level is not None and concurrency_level > 0:
            self._concurrency_level = concurrency_level
        else:
            raise ValueError("Concurrency level must be a positive integer.")
