class AuthSystem {
    private $db;
    private $sessionManager;
    private $hashAlgorithm;
    private $tokenGenerator;

    public function __construct($db, $sessionManager) {
        $this->db = $db;
        $this->sessionManager = $sessionManager;
        $this->hashAlgorithm = 'bcrypt';
        $this->tokenGenerator = new TokenGenerator();
    }

    public function registerUser($username, $password, $email) {
        if (!preg_match('/^[a-zA-Z0-9_]+$/', $username)) {
            throw new Exception('Invalid username');
        }
        if (strlen($password) < 8) {
            throw new Exception('Password must be at least 8 characters long');
        }
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            throw new Exception('Invalid email');
        }

        $hashedPassword = $this->getHashedPassword($password);
        $userId = $this->db->insertUser($username, $hashedPassword, $email);

        return $userId;
    }

    public function loginUser($username, $password) {
        if (!preg_match('/^[a-zA-Z0-9_]+$/', $username)) {
            throw new Exception('Invalid username');
        }
        if (strlen($password) < 8) {
            throw new Exception('Password must be at least 8 characters long');
        }

        $user = $this->db->getUserByUsername($username);
        if (!$user || !$this->verifyPassword($user['password'], $password)) {
            throw new Exception('Invalid username or password');
        }

        return $this->loginUserSession($user);
    }

    public function getUserSessionId() {
        return session_id();
    }

    private function getHashedPassword($password) {
        switch ($this->hashAlgorithm) {
            case 'bcrypt':
                return crypt($password, '$2y$10$');
            case 'argon2id':
                // Implement Argon2id hash algorithm
                break;
            default:
                throw new Exception('Unsupported hash algorithm');
        }
    }

    private function verifyPassword($hashedPassword, $inputPassword) {
        switch ($this->hashAlgorithm) {
            case 'bcrypt':
                return crypt($inputPassword, $hashedPassword) === $hashedPassword;
            case 'argon2id':
                // Implement Argon2id verification
                break;
            default:
                throw new Exception('Unsupported hash algorithm');
        }
    }

    private function loginUserSession($user) {
        $sessionId = session_create();
        $this->sessionManager->start($sessionId);
        return $sessionId;
    }

    class TokenGenerator {
        public function generateToken($length = 64, $characters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
            if ($length < 1) {
                throw new Exception('Invalid token length');
            }
            if (strlen($characters) < 1) {
                throw new Exception('Invalid character set');
            }

            return substr(str_shuffle($characters), 0, $length);
        }
    }
}

