void loadFilesAsync(const std::vector<std::string>& files, bool& allLoaded) {
    int numThreads = std::thread::hardware_concurrency();
    std::vector<std::thread> threads;

    for (int i = 0; i < numThreads && i < files.size(); ++i) {
        threads.emplace_back([files, &allLoaded, i]() {
            bool loaded = false;
            loadFileAsync(files[i], loaded);
            allLoaded = loaded;
        });
    }

    if (numThreads < files.size()) {
        for (int i = numThreads; i < files.size(); ++i) {
            loadFileAsync(files[i], allLoaded);
        }
    }

    for (auto& thread : threads) {
        thread.join();
    }
