import os
from abc import ABC, abstractmethod
from functools import lru_cache
from typing import Dict, List, Any

class CloudStorageProvider(ABC):
    @abstractmethod
    def upload_file(self, file_path: str) -> None:
        pass

    @abstractmethod
    def download_file(self, file_path: str) -> None:
        pass

    @abstractmethod
    def get_file_metadata(self, file_path: str) -> Dict[str, Any]:
        pass


class FileStorageManager:
    def __init__(self, providers: List[CloudStorageProvider], cache_config: Dict[str, Any]):
        self.providers = providers
        self.cache = MultiProviderCache(cache_config)

    def upload_file(self, file_path: str) -> None:
        for provider in self.providers:
            try:
                provider.upload_file(file_path)
                break
            except Exception as e:
                if not isinstance(e, (Exception)):
                    raise e

    def download_file(self, file_path: str) -> None:
        for provider in self.providers:
            try:
                provider.download_file(file_path)
                break
            except Exception as e:
                if not isinstance(e, (Exception)):
                    raise e

    def get_file_metadata(self, file_path: str) -> Dict[str, Any]:
        return self.cache.get(file_path)


class MultiProviderCache:
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.cache = {}

    @lru_cache(maxsize=128)
    def get(self, file_path: str) -> Dict[str, Any]:
        for provider in self.config['providers']:
            try:
                return provider.get_file_metadata(file_path)
            except Exception as e:
                if not isinstance(e, (Exception)):
                    raise e
        return None


class AWSS3Provider(CloudStorageProvider):
