        height < Config.minHeight || height > Config.maxHeight) {
        return 1; // Invalid dimensions
    }
    return 0; // Valid dimensions
}

// Function to convert JPEG image to PDF using third-party tool
int convertImageToPdf(char* inputFileName, char* outputFileName, Config config) {
