from flask import Flask, request, jsonify
from flask_socketio import SocketIO, emit

app = Flask(__name__)
socketio = SocketIO(app)

class ConfigManager:
    def __init__(self):
        self.configs = {}
        self.lock = threading.Lock()
        self.cached_configs = {}

    def load_config(self, config_name):
        if config_name not in self.configs:
            with open(f"{config_name}.json", "r") as f:
                config_data = json.load(f)
                self.configs[config_name] = json.dumps(config_data)

    def update_config(self, config_name, updates):
        self.load_config(config_name)
        if config_name in self.cached_configs:
            self.cached_configs[config_name].update(updates)
        else:
            self.cached_configs[config_name] = updates

    def get_config(self, config_name):
        return json.loads(self.configs.get(config_name, "{}"))

    def put_config(self, config_name, data):
        self.load_config(config_name)
        with open(f"{config_name}.json", "w") as f:
            json.dump(data, f)

class ConfigHandler:
    def __init__(self, config_manager):
        self.config_manager = config_manager

    def get_config(self, config_name):
        return self.config_manager.get_config(config_name)

    def put_config(self, config_name, data):
        self.config_manager.put_config(config_name, data)

    def update_config(self, config_name, updates):
        self.config_manager.update_config(config_name, updates)

class WebSocketHandler:
    def __init__(self, config_handler):
        self.config_handler = config_handler

    @socketio.on("config_update")
    def handle_config_update(self, data):
        config_name = data["config_name"]
        updates = data["updates"]
        self.config_handler.update_config(config_name, updates)
        emit("config_updated", data)

@app.route("/get_config", methods=["GET"])
def get_config():
    config_name = request.args.get("name")
    return jsonify(self.config_manager.get_config(config_name))

@app.route("/put_config", methods=["PUT"])
def put_config():
    config_name = request.form["name"]
    config_data = json.loads(request.form["data"])
    self.config_handler.put_config(config_name, config_data)
    return "Config updated"

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    logging.info("Starting Config Manager...")
    config_manager = ConfigManager()
    config_handler = ConfigHandler(config_manager)
    socketio.init_app(app)

    try:
        app.run(debug=True)
    except Exception as e:
        logging.error(f"Error: {e}")
