import xml.etree.ElementTree as ET
from xml.dom import minidom
import requests
from xmlschema import XMLSchema

def filter_xml(xml_string, xpath_expr):
    root = ET.fromstring(xml_string)
    for elem in ET.iter(root, xpath_expr):
        yield elem

def validate_element(xml_string, element_xpath, schema_url):
    root = ET.fromstring(xml_string)
    element = next(ET.iter(root, element_xpath), None)
    if not element:
        return False
    try:
        response = requests.post(schema_url, data=minidom.parseString(minidom.StringStreamWriter(ET.tostring(element)).read()).toprettyxml())
        response.raise_for_status()
        schema = XMLSchema(response.text)
        return schema.is_valid_string(minidom.parseString(minidom.StringStreamWriter(ET.tostring(element)).read()).toprettyxml())
    except requests.exceptions.RequestException as e:
        print(f"Error validating element: {e}")
        return False
