const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

class ModuleLoader {
  constructor(configFile) {
    this.config = JSON.parse(fs.readFileSync(configFile, 'utf8'));
    this.modules = [];
    this.moduleMap = {};
  }

  async loadModules() {
    for (const module of this.config.modules) {
      try {
        const modulePath = path.join(__dirname, '..', module.path);
        this.modules.push(await require(modulePath));
      } catch (err) {
        console.error(`Error loading module ${module.path}: ${err}`);
      }
    }
  }

  async executeModules() {
    for (const [index, module] of this.config.modules.entries()) {
      try {
        await module();
      } catch (err) {
        console.error(`Error executing module ${this.config.modules[index].path}: ${err}`);
      }
    }
  }
}

