```csharp
using System;
using UnityEngine;

public class ValueGenerator : MonoBehaviour
{
    private int min, max;
    private bool isExclusive;

    public ValueGenerator(int min, int max)
    {
        if (min > max)
            throw new ArgumentOutOfRangeException("Min value cannot be greater than Max value.");
        this.min = min;
        this.max = max;
        this.isExclusive = false;
    }

    public ValueGenerator(int min, int max, bool isExclusive)
    {
        if (min > max)
            throw new ArgumentOutOfRangeException("Min value cannot be greater than Max value.");
        this.min = min;
        this.max = max;
        this.isExclusive = isExclusive;
    }

    public float GenerateFloat()
    {
        return isExclusive ? UnityEngine.Random.Range(min, max) : UnityEngine.Random.Range(min, max + 1);
    }

    public int GenerateInt()
    {
        return isExclusive ? UnityEngine.Random.Range(min, max) : UnityEngine.Random.Range(min, max + 1);
    }

    public int[] GenerateIntArray(int size)
    {
        if (size > 1000)
            throw new ArgumentException("Array size cannot exceed 1000 for performance reasons.");

        int[] array = new int[size];
        for (int i = 0; i < size; i++)
        {
            array[i] = GenerateInt();
        }
        return array;
    }

    public float[] GenerateFloatArray(int size)
    {
        if (size > 1000)
            throw new ArgumentException("Array size cannot exceed 1000 for performance reasons.");

        float[] array = new float[size];
        for (int i = 0; i < size; i++)
        {
            array[i] = GenerateFloat();
        }
        return array;
    }

    public override string ToString()
    {
        if (isExclusive)
            return $"Random values between {min} and {max}, exclusive.";
        else
            return $"Random values between {min} and {max}, inclusive.";
    }

    public int[] GeneratePermutation(int size, int rangeMin, int rangeMax)
    {
        if (size > 1000)
            throw new ArgumentException("Array size cannot exceed 1000 for performance reasons.");

        int[] array = new int[size];
        for (int i = 0; i < size; i++)
        {
            array[i] = UnityEngine.Random.Range(rangeMin, rangeMax);
        }
        Array.Sort(array);

        // Fisher-Yates shuffle
        for (int i = size - 1; i > 0; i--)
        {
            int j = UnityEngine.Random.Range(0, i + 1);
            int temp = array[j];
            array[j] = array[i];
            array[i] = temp;
        }
        return array;
    }
}
