import importlib.util
import json
import logging
from typing import Dict, List, Any

class NetworkProtocolLoader:
    def __init__(self, config_file_path: str):
        self.config_file_path = config_file_path
        self.protocol_configs = {}
        self.log = logging.getLogger(__name__)
        self.cache = {}

    def load_protocols(self) -> Dict[str, Dict]:
        if not os.path.exists(self.config_file_path):
            raise FileNotFoundError(f"Configuration file {self.config_file_path} not found")

        with open(self.config_file_path, 'r') as f:
            protocol_configs = json.load(f)

        for protocol_config in protocol_configs:
            name = protocol_config["name"]
            implementation_class_name = protocol_config["implementation_class"]

            if implementation_class_name not in self.cache:
                try:
                    spec = importlib.util.spec_from_file_location(implementation_class_name, f"{self.config_file_path}/{implementation_class_name}.py")
                    self.cache[implementation_class_name] = importlib.util.module_from_spec(spec)
                except FileNotFoundError:
                    self.log.warning(f"Protocol implementation {name} not found in directory {self.config_file_path}")
                    continue
                except Exception as e:
                    self.log.error(f"Error loading protocol implementation {name}: {e}")
                    continue

            if name not in self.protocol_configs:
                self.protocol_configs[name] = {
                    "name": name,
                    "implementation_class": getattr(self.cache[implementation_class_name], "ProtocolImplementation", None),
                    "description": protocol_config.get("description", ""),
                    "supported_features": protocol_config.get("supported_features", []),
                    "default_config": protocol_config.get("default_config", {}),
                    "feature_flags": protocol_config.get("feature_flags", {})
                }

        return self.protocol_configs
