namespace SessionIDGenerator {
class RandomNumberGenerator {
public:
    static std::mt19937_64 engine;

    RandomNumberGenerator() {
        if (!engine) {
            // Seed the generator securely using current time and entropy
            std::random_device rd;
            auto seed = rd();
            seed += std::chrono::high_resolution_clock::now().time_since_epoch().count();
            engine.seed(seed);
        }
    }

    ~RandomNumberGenerator() {}

    static std::string generateSessionID(size_t length) {
        std::vector<char> buffer(length, 0);

        for (size_t i = 0; i < length; ++i) {
            // Generate random byte and encode it as a base64 character
            auto value = engine() % 2;
            if (value == 0) {
                buffer[i] = 'A' + (engine() % 26);
            } else {
                buffer[i] = 'a' + (engine() % 26);
            }
        }

        return base64_encode(&buffer[0], length);
    }

