```csharp
using System;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using System.Security.Cryptography;
using System.Collections.Generic;

public enum FileFormat { CSV, JSON, XML }
public enum EncryptionMode { ECB, CBC, GCM }

public class DynamicFileProcessor : IDisposable
{
    private readonly object _syncLock = new object();
    private readonly ReaderWriterLockSlim _lock = new ReaderWriterLockSlim();

    public DynamicFileProcessor(FileFormat fileFormat, EncryptionMode encryptionMode)
    {
        FileFormat = fileFormat;
        EncryptionMode = encryptionMode;
    }

    public FileFormat FileFormat { get; }
    public EncryptionMode EncryptionMode { get; }

    public void ProcessFile(string filePath, int chunkSize)
    {
        using (var fs = new FileStream(filePath, FileMode.Open))
        {
            var reader = GetReader(fs, FileFormat);
            var writer = GetWriter(FileFormat);

            long fileLength = fs.Length;
            long startPosition = 0;

            while (startPosition < fileLength)
            {
                long endPosition = Math.Min(startPosition + chunkSize, fileLength);
                byte[] chunkData = new byte[endPosition - startPosition];

                lock (_syncLock)
                {
                    fs.Seek(startPosition, SeekOrigin.Begin);
                    fs.Read(chunkData, 0, chunkData.Length);

                    if (EncryptionMode != EncryptionMode.None)
                    {
                        var encryptedChunk = EncryptChunk(chunkData);
                        writer.Write(encryptedChunk);
                    }
                    else
                    {
                        writer.Write(chunkData);
                    }
                }

                startPosition = endPosition;
            }
        }
    }

    public void Dispose()
    {
        _lock.Dispose();
    }

    private Stream GetReader(Stream fs, FileFormat fileFormat)
    {
        switch (fileFormat)
        {
            case FileFormat.CSV:
                return new CsvStreamReader(fs);
            case FileFormat.JSON:
                return new JsonStreamReader(fs);
            case FileFormat.XML:
                return new XmlStreamReader(fs);
            default:
                throw new ArgumentException("Invalid file format");
        }
    }

    private Stream GetWriter(FileFormat fileFormat)
    {
        switch (fileFormat)
        {
            case FileFormat.CSV:
