import javax.mail.MessagingException;
import javax.mail.Session;
import javax.mail.Transport;
import javax.mail.internet.InternetAddress;
import javax.mail.internet.MimeMessage;

import org.apache.commons.lang3.StringUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.slf4j.Marker;

public class NotificationService {

    private static final Logger LOG = LoggerFactory.getLogger(NotificationService.class);

    private static final int MAX_RETRIES = 5;
    private static final long RETRY_INTERVAL_MS = 30000L; // 30 seconds
    private static final String SMTP_ERROR_TEMPLATE = "SMTP error: %s";
    private static final String NETWORK_ERROR_TEMPLATE = "Network error: %s";

    private final ExecutorService executor = Executors.newFixedThreadPool(5); // adjust the thread pool size based on your system's capabilities
    private final Map<String, EmailTemplate> emailTemplates;
    private final OAuth2CredentialProvider oAuth2CredentialProvider;

    public NotificationService(Map<String, EmailTemplate> emailTemplates, OAuth2CredentialProvider oAuth2CredentialProvider) {
        this.emailTemplates = emailTemplates;
        this.oAuth2CredentialProvider = oAuth2CredentialProvider;
    }

    public void sendNotificationEmails(List<Recipient> recipients, String notificationRule) {
        for (Recipient recipient : recipients) {
            if (!validateEmail(recipient.getEmail())) {
                LOG.error("Invalid email address: {}", recipient.getEmail());
                continue;
            }
            try {
                sendEmail(recipient, notificationRule);
            } catch (MessagingException e) {
                int retryCount = 0;
                while (retryCount <= MAX_RETRIES && !sendEmailWithRetry(recipient, notificationRule)) {
                    LOG.error(SMTP_ERROR_TEMPLATE, e.getMessage());
                    if (++retryCount == MAX_RETRIES) {
                        LOG.error("SMTP service failed after max retries: {}", recipient.getEmail());
                    }
                    try {
                        Thread.sleep(RETRY_INTERVAL_MS);
                    } catch (InterruptedException ie) {
                        // handle interrupted thread
                    }
                }
            } catch (NetworkException e) {
                LOG.error(NETWORK_ERROR_TEMPLATE, e.getMessage());
            }
        }
    }

    private boolean sendEmailWithRetry(Recipient recipient, String notificationRule) throws MessagingException {
        int retryCount = 0;
        while (retryCount < MAX_RETRIES && !sendEmail(recipient, notificationRule)) {
            LOG.error(SMTP_ERROR_TEMPLATE, "SMTP service failed during retry: " + recipient.getEmail());
            try {
                Thread.sleep(RETRY_INTERVAL_MS);
            } catch (InterruptedException ie) {
                // handle interrupted thread
            }
            ++retryCount;
        }
        return true;
    }

    private boolean sendEmail(Recipient recipient, String notificationRule) throws MessagingException {
        Session session = oAuth2CredentialProvider.getOAuth2Session();
        Transport transport = session.getTransport();
        MimeMessage message = createMimeMessage(recipient, notificationRule);
        if (transport.send(message)) {
            LOG.info("Email sent to: {}", recipient.getEmail());
            return true;
        } else {
            LOG.error("SMTP service failed: {}", recipient.getEmail());
            return false;
        }
    }

    private boolean validateEmail(String email) {
        // implement email validation logic here
        return StringUtils.isNotBlank(email);
    }

    private MimeMessage createMimeMessage(Recipient recipient, String notificationRule) throws MessagingException {
        // implement email content creation logic here
        return new MimeMessage(session);
    }
}

class Recipient {
    private String email;

    public Recipient(String email) {
        this.email = email;
    }

    public String getEmail() {
        return email;
    }
}
