#include <nlohjson/json.hpp>

using namespace nlohjson;

class DynamicLoader {
public:
    // Registry management
    void addFactoryFunction(const std::string& id, const json& factory) {
        registry_[id] = factory;
    }

    void removeFactoryFunction(const std::string& id) {
        registry_.erase(id);
    }

    json getFactoryFunction(const std::string& id) {
        if (registry_.find(id) == registry_.end()) {
            throw std::runtime_error("Unknown factory function ID");
        }
        return registry_[id];
    }

    // Asynchronous loading
    void loadFiles(std::vector<std::string> fileNames, const std::function<void(json&)>& callback) {
        std::vector<std::future<json>> futures;
        for (const auto& fileName : fileNames) {
            auto future = std::async(std::launch::async, [this, &fileName, callback]() {
                json fileContent;
                try {
                    std::ifstream ifs(fileName);
                    ifs >> fileContent;
                } catch (...) {
                    throw std::runtime_error("Failed to load " + fileName);
                }
                return fileContent;
            });
            futures.push_back(future);
        }

        for (const auto& future : futures) {
            json file = future.get();
            callback(file);
        }
    }

    // External integration
    void fetchConfigFromAPI(const std::string& apiUrl, const std::function<void(json&)>& callback) {
        // TO DO: implement API fetching and versioning
    }

private:
    std::map<std::string, json> registry_;
};

int main() {
    DynamicLoader loader;

    // Example usage
    try {
        loader.addFactoryFunction("myFactory", R"({
            "type": "myType",
            "create": function() { return new MyClass(); }
        })");

        std::vector<std::string> fileNames = {"file1.json", "file2.json"};
        loader.loadFiles(fileNames, [loader](json& file) {
            // Process the loaded files
        });

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
