using System;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Logging;

public class Sha256Hasher
{
    private readonly ILogger _logger;
    private readonly Dictionary<string, byte[]> _hashCache = new();
    private readonly ReaderWriterLockSlim _lock = new();

    public Sha256Hasher(ILogger<Sha256Hasher> logger)
    {
        _logger = logger;
    }

    public string GetSha256Hash(string input)
    {
        if (input == null)
            throw new ArgumentNullException(nameof(input));

        if (_hashCache.TryGetValue(input, out byte[] cachedHash))
            return BitConverter.ToString(cachedHash).Replace("-", "").ToLower();

        using var sha256 = SHA256.Create();
        try
        {
            byte[] hashBytes;
            lock (_lock)
            {
                hashBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(input));
                _hashCache[input] = hashBytes;
            }
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error computing SHA-256 hash");
            return null;
        }
    }
}
