#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <pthread.h>
#include <semaphore.h>
#include <signal.h>
#include <sys/wait.h>

#define MAX_LINE_LENGTH 1024
#define NUM_THREADS 8 // configurable threshold for the number of threads

sem_t file_sem;
sem_t log_sem;

void *thread_function(void *);
void process_line(char *);

int main(int argc, char **argv) {
    int i, num_files = argc - 1; // number of input files
    pthread_t threads[NUM_THREADS];
    FILE *files[num_files];
    pid_t child_pids[num_files];

    // Initialize the semaphore for file operations and logging
    sem_init(&file_sem, 0, 1);
    sem_init(&log_sem, 0, 1);

    for (i = 0; i < num_files; i++) {
        files[i] = fopen(argv[i + 1], "r");
        if (!files[i]) {
            printf("Error opening file %s\n", argv[i + 1]);
            return -1;
        }

        child_pids[i] = fork();
        if (child_pids[i] == 0) { // child process
            int j;

            // Process each line in the file concurrently using multiple threads
            for (j = 0; j < NUM_THREADS; j++) {
                pthread_create(&threads[j], NULL, thread_function, files[i]);
            }

            // Wait for all threads to finish
            for (j = 0; j < NUM_THREADS; j++) {
                pthread_join(threads[j], NULL);
            }

            exit(0); // child process terminates after processing the file
        }
    }

    // Wait for all child processes to finish
    for (i = 0; i < num_files; i++) {
        wait(NULL);
    }

    return 0;
}

void *thread_function(void *file) {
    FILE *f = (FILE *)file;
    char line[MAX_LINE_LENGTH];
    int j;

    while (fgets(line, MAX_LINE_LENGTH, f)) {
        // Process the line
        process_line(line);

        // Release the file semaphore to allow other threads to access the file
        sem_post(&file_sem);
    }

    fclose(f); // Close the file after processing

    return NULL;
}

void process_line(char *line) {
    char *token = strtok(line, " ");
    int num_fields = 0;
    double sum = 0.0;

    while (token) {
        if (*token == '\0') break; // End of line reached
        token += strspn(token, " "); // Skip leading whitespace

        // Check if the field is numeric
        char *endptr;
        double value = strtod(token, &endptr);

        if (*endptr != '\0') {
            printf("Warning: Non-numeric value '%s' in line '%s'\n", token, line);
            continue; // Skip non-numeric fields
        }

        sum += value;
        num_fields++;

        if (num_fields >= 3) break; // Process at least three numeric fields

        token = strtok(NULL, " ");
    }

    if (num_fields < 3) return;

    double average = sum / (double)num_fields;

    printf("%f", average);

    // Write the processed data to an output file
    // ... implement writing logic here ...
}
