        @wraps(func)
        def wrapper(*args, **kwargs):
            ip_address = get_ip_address()
            user_id = get_user_id()

            redis_key = f'rate_limit:{ip_address}:{user_id}'
            requests_made = int(redis_client.get(redis_key) or 0)

            if requests_made >= requests_per_window:
                time.sleep(1)
                return 'Rate limit exceeded. Please try again later.'

            request_result = func(*args, **kwargs)

            redis_client.incr(redis_key)
            redis_client.expire(redis_key, RATE_LIMIT_WINDOW)

            return request_result
