function executePluginTestsParallelly(label, f, plugins, numWorkers = 4) {
  const { Worker } = require('worker_threads');
  const logFile = 'test-results.log';
  const logger = require('./logger');

  async function runTest(plugin, test) {
    return new Promise((resolve, reject) => {
      try {
        f(test);
        resolve({ status: 'passed' });
      } catch (error) {
        reject({ status: 'failed', error: error.toString() });
      }
    });
  }

  async function executeTests(plugin) {
    const tests = require(`./${plugin}/tests.js`);
    return Promise.all(Object.keys(tests).map((testName) => runTest(plugin, tests[testName])));
  }

  async function main() {
    logger.info(`Executing plugin tests for ${label}...`);

    try {
      const testResults = await Promise.all(plugins.map((plugin) => executeTests(plugin)));
      const failedTests = testResults.filter(({ status }) => status === 'failed');

      if (failedTests.length > 0) {
        logger.error('Test failures:');
        failedTests.forEach(({ plugin, tests }, index) => {
          logger.error(`Plugin: ${plugin}, Test: ${Object.keys(tests)[index]}, Error: ${tests[Object.keys(tests)[index]].error}`);
        });
      } else {
        logger.info('All tests passed!');
      }

      const testReport = testResults.map((result, index) => `Plugin: ${plugins[index]}, Tests: ${Object.keys(result).length}, Status: ${result.reduce((acc, curr) => (curr.status === 'passed' ? acc + 1 : acc), 0)}/${Object.keys(result).length}`).join('\n');

      logger.info(`Test report:\n${testReport}`);

      await fs.promises.writeFile(logFile, testReport);
      return testReport;
    } catch (error) {
      logger.error('Error executing plugin tests:', error);
      process.exit(1);
    }
  }

  main().then((report) => console.log(report)).catch((error) => console.error(error));

  async function closeWorkers() {
    await Promise.all(workers.map((worker) => worker.destroy()));
  }

  // Create workers and execute tests in parallel
  const workers = [];
  for (let i = 0; i < numWorkers; i++) {
    const worker = new Worker(__filename, { workerData: label });
    workers.push(worker);
  }
  await Promise.all(workers.map((worker) => worker.on('exit', () => closeWorkers())));

  // Start and manage workers
  for (const plugin of plugins) {
    await Promise.all(workers.map((worker) => worker.postMessage({ type: 'start', plugin })));
  }

  // Listen to exit event and close workers on termination
  process.on('SIGINT', () => closeWorkers());
}

