        private readonly IPolicyConfiguration _policyConfig;

        public CustomUserValidator(IPolicyConfiguration policyConfig)
        {
            _policyConfig = policyConfig;
        }

        public override async Task<IdentityResult> ValidateAsync(UserManager<User> userManager, User user)
        {
            var result = await base.ValidateAsync(userManager, user);

            if (!result.Succeeded)
                return result;

            // Custom validation logic based on user roles and risk levels
            if (_policyConfig.GetPolicyForUser(user).RiskLevel == RiskLevel.High)
            {
                // Validate password strength according to high-risk policy
                var passwordValidator = new PasswordValidator();
                var passwordResult = await passwordValidator.ValidateAsync(user.Password);
                if (!passwordResult.Succeeded)
                    return IdentityResult.Failed("Password does not meet high-risk requirements.");
            }

            return result;
        }
    }

    public interface IPolicyConfiguration
    {
        RiskLevel GetPolicyForUser(User user);
    }

    public enum RiskLevel
    {
        Low,
        Medium,
        High
    }

