```
const ScriptLoader = (function () {
  const scriptCache = {};
  const errorLog = [];
  const orderedLibraries = [];

  function loadScript(url) {
    return new Promise((resolve, reject) => {
      const scriptTag = document.createElement('script');
      scriptTag.src = url;
      scriptTag.onload = resolve;
      scriptTag.onerror = reject;
      document.body.appendChild(scriptTag);
    });
  }

  function cacheScript(url, script) {
    scriptCache[url] = script;
  }

  function loadOrderedScripts() {
    return Promise.all(orderedLibraries.map((url) => loadScript(url)));
  }

  function logError(error) {
    errorLog.push(error);
  }

  function getScriptStatus(url) {
    if (scriptCache.hasOwnProperty(url)) {
      return 'cached';
    } else if (errorLog.includes(`Failed to load ${url}`)) {
      return 'error';
    }
    return 'loading';
  }

  function retryFailedRequests() {
    orderedLibraries.forEach((url) => {
      if (getScriptStatus(url) === 'error') {
        loadScript(url);
      }
    });
  }

  function updateLibraryOrder(newOrder) {
    orderedLibraries = newOrder;
  }

  return {
    addLibrary: (libraryUrl) => {
      orderedLibraries.push(libraryUrl);
    },
    removeLibrary: (libraryUrl) => {
      const index = orderedLibraries.indexOf(libraryUrl);
      if (index !== -1) {
        orderedLibraries.splice(index, 1);
      }
    },
    loadScripts: () => loadOrderedScripts(),
    getScriptStatus,
    logError,
    retryFailedRequests,
    updateLibraryOrder,
  };
})();

// example usage:
