  });

  it('logs errors', async () => {
    const scriptLoader = ScriptLoader();
    scriptLoader.addLibrary('https://example.com/non-existent-library.js');
    try {
      await scriptLoader.loadScripts();
    } catch (error) {
      expect(error).to.be.an('error');
      expect(logError).to.have.callCount(1);
    }
  });

  it('retries failed requests', async () => {
    const scriptLoader = ScriptLoader();
    scriptLoader.addLibrary('https://example.com/non-existent-library.js');
    await scriptLoader.loadScripts();
    scriptLoader.retryFailedRequests();
    expect(getScriptStatus('https://example.com/non-existent-library.js')).to.equal('loading');
