import json
import asyncio
from collections import OrderedDict
from hashlib import sha256

class JSONManager:
    def __init__(self):
        self.registry = {}
        self.instances = []
        self.files_loaded = False

    async def load_files(self, files):
        if self.files_loaded:
            return
        tasks = [self.load_file(file) for file in files]
        await asyncio.gather(*tasks)
        self.files_loaded = True

    async def load_file(self, file):
        try:
            with open(file, 'r') as f:
                data = json.load(f)
                if not isinstance(data, dict):
                    print(f"Error loading {file}: Not a JSON object")
                    return
                instance = JSONInstance.from_json(data['data'])
                self.instances.append(instance)
                if data.get('id'):
                    self.registry[data['id']] = instance.__class__.__name__
        except (FileNotFoundError, json.JSONDecodeError) as e:
            print(f"Error loading {file}: {e}")

    def from_json(self, data):
        return JSONInstance(data)

    def to_json(self, instance):
        return {'data': instance.to_dict()}

    class ForwardList:
        def __init__(self):
            self.list = []

        def insert(self, target, value, position=-1):
            if not isinstance(position, int) or position > len(self.list):
                position = -1
            try:
                idx = self.list.index(target)
                if position == idx:
                    self.list.insert(idx+1, value)
                else:
                    self.list.insert(position, value)
            except ValueError:
                self.list.append(value)

    class JSONInstance:
        def __init__(self, data):
            self.data = data

        @classmethod
        def from_json(cls, data):
            return cls(data)

        def to_dict(self):
            return self.data

        def hash_password(self, password):
            return sha256(f"{password}{str(self.data)}".encode()).hexdigest()

    async def deserialize_byte_array(self, byte_array):
        try:
            data = json.loads(byte_array.decode())
            instance = JSONInstance.from_json(data)
            return instance
        except (json.JSONDecodeError, Exception) as e:
            print(f"Error deserializing: {e}")
            return None

    async def generate_random_string(self, password):
        try:
            instance = await self.deserialize_byte_array(password.encode())
            if instance:
                return {'hashed_password': instance.hash_password(password), 'random_string': str(instance.data)}
            else:
                return None
        except Exception as e:
            print(f"Error generating random string: {e}")
            return None

    async def manipulate_forward_list(self, list_str, target, value, position=-1):
        try:
            fl = self.ForwardList()
            for item in list_str.split(','):
                fl.insert(item.strip(), None)
            fl.insert(target, value, position)
            return fl.list
        except Exception as e:
            print(f"Error manipulating forward list: {e}")
            return None

    async def read_string_pairs(self, file):
        try:
            with open(file, 'r') as f:
                pairs = [line.strip().split(': ') for line in f.readlines()]
                return pairs
        except FileNotFoundError as e:
            print(f"Error reading string pairs: {e}")
            return None

    async def insert_string_pairs(self, file):
        try:
            pairs = await self.read_string_pairs(file)
            if not pairs:
                return
            for pair in pairs:
                key, value = pair
                await self.manipulate_forward_list(None, key, value)
        except Exception as e:
            print(f"Error inserting string pairs: {e}")
