const fs = require('fs');
const path = require('path');
const ScriptCache = require('script-cache');

function loadScripts() {
  return Promise.all(
    scripts.map((script) => {
      const scriptPath = path.join(__dirname, '..', 'scripts', `${script}.js`);
      return fs.promises.readFile(scriptPath, 'utf8').then((content) => ({ content, script }));
    })
  );
}

function executeScripts(scripts) {
  return Promise.all(
    scripts.map((script) => {
      const cacheKey = `scriptId-${script.scriptId}`;
      const cachedScript = ScriptCache.get(cacheKey);
      if (cachedScript) {
        return cachedScript;
      }
      return fetch(script.content).then((response) => response.text()).then((content) => {
        const script = new Function(content); // execute the script
        ScriptCache.set(cacheKey, script);
        return script();
      });
    })
  );
}

function renderScripts(scripts) {
  return scripts.map((script) => {
    if (!script.actionType || !script.scriptId) {
      throw new Error(`Script ${script.scriptId} is missing essential properties`);
    }
    // render the script HTML
  }).join('');
}

