function runModuleTests(moduleLabel, testSuite, logLevel) {
  require(moduleLabel);

  const blueslip = require('blueslip');
  let moduleInstance;

  for (const { label, testFunction } of testSuite) {
    try {
      // Reset and clean up the `blueslip` mocking library
      blueslip.reset();

      // Initialize the module instance with a fresh state
      moduleInstance = require(moduleLabel);

      // Run the test function
      const result = await testFunction(label, moduleInstance);

      if (result) {
        console.log(`Test ${label} passed`);
      } else {
        console.error(`Test ${label} failed`);
      }

    } catch (error) {
      console.error(`Error running test ${label}: ${error}`);
    } finally {
      // Release all resources held by `blueslip`
      blueslip.release();

      // Reset the module's internal state
      moduleInstance = null;
    }
  }
}
