```c
#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <string.h>

#define LOG_ERROR 0
#define LOG_WARNING 1
#define LOG_INFO 2

int logLevelEnabled[] = {1, 1, 1}; // Initialize all levels enabled

void logFormattedError(int level, const char *fmt, ...) {
    static int fileDescriptors[3]; // File descriptors for each log level
    static FILE *logs[3] = {NULL, NULL, NULL}; // Pointers to log files
    static char timestampFormat[] = "%Y-%m-%d %H:%M:%S"; // Default timestamp format

    if (level >= 0 && level < 3) {
        if (!logLevelEnabled[level]) return; // Check if logging is enabled for this level

        char buffer[1024]; // Buffer to store formatted message
        va_list args;
        va_start(args, fmt);
        vsnprintf(buffer, sizeof(buffer), fmt, args);
        va_end(args);

        // Open or reuse the log file based on the log level
        if (logs[level] == NULL) {
            char filename[32];
            sprintf(filename, "log_%s.txt", (level == LOG_ERROR ? "error" : level == LOG_WARNING ? "warning" : "info"));
            logs[level] = fopen(filename, "a");
            fileDescriptors[level] = fileno(logs[level]);
        }

        // Write the log message to the file
        fprintf(logs[level], "[%s] %s\n", asctime(localtime(&now)), buffer);

        if (ferror(logs[level])) {
            printf("Error writing to log file: %s\n", strerror(errno));
        }

        fclose(logs[level]); // Close the log file

        if (fileDescriptors[level] != -1) {
            close(fileDescriptors[level]);
            fileDescriptors[level] = -1; // Mark as closed
        }
    }
}
