```javascript
function renderScripts(scripts) {
  const SCRIPT_CONTAINER = document.getElementById('script-container');
  const LOADING_SPINNER_CONTAINER = document.getElementById('loading-spinner-container');

  function fetchScript(script, callback) {
    const xhr = new XMLHttpRequest();
    xhr.open('GET', script.src, true);
    xhr.onload = () => {
      if (xhr.status === 200) {
        try {
          const scriptElement = document.createElement('script');
          scriptElement.text = xhr.responseText;
          scriptElement.async = true;
          scriptElement.type = script.type || 'text/javascript';
          scriptElement.key = `script-${Date.now()}`;
          callback(scriptElement);
        } catch (error) {
          console.error(error);
        }
      } else {
        // handle error
      }
    };
    xhr.onerror = () => {
      // handle error
    };
    xhr.onabort = () => {
      // handle error
    };
    xhr.send();
  }

  function renderScript(scriptElement, callback) {
    const scriptContainer = document.getElementById('script-container');
    scriptContainer.appendChild(scriptElement);
    if (callback) {
      callback();
    }
  }

  function fetchAndRenderScripts(scripts) {
    let cachedScripts = {};
    let scriptsToFetch = [];
    let priorityScriptsLoaded = 0;

    scripts.forEach((script, index) => {
      const priority = script.priority || 0;
      if (priority > priorityScriptsLoaded) {
        priorityScriptsLoaded = priority;
      }
      if (!cachedScripts[script.key]) {
        scriptsToFetch.push(script);
      } else {
        renderScript(cachedScripts[script.key], () => {
          // callback
        });
      }
    });

    function fetchNextScript() {
      const script = scriptsToFetch.shift();
      if (script) {
        fetchScript(script, (scriptElement) => {
          cachedScripts[scriptElement.key] = scriptElement;
          renderScript(scriptElement, () => {
            priorityScriptsLoaded++;
            if (priorityScriptsLoaded === scripts.length) {
              // all scripts loaded
            }
            setTimeout(() => {
              if (priorityScriptsLoaded < scripts.length) {
                fetchNextScript();
              } else {
                LOADING_SPINNER_CONTAINER.style.display = 'none';
              }
            }, 1000);
          });
        });
      } else {
        LOADING_SPINNER_CONTAINER.style.display = 'none';
      }
    }

    setTimeout(() => {
      if (scriptsToFetch.length > 0) {
        fetchNextScript();
      } else {
        LOADING_SPINNER_CONTAINER.style.display = 'none';
      }
    }, 100);
  }

  fetchAndRenderScripts(scripts);
}
