const cache = {};
function renderFooterScripts(scripts) {
  const footerHTML = '';
  scripts.forEach((script) => {
    const { code, type, src } = script;
    if (!code || !type) {
      // Handle missing properties
      script.code ??= '/* No code provided */';
      script.type ??= 'text/javascript';
    }
    if (src && !cache[src]) {
      // Fetch script dynamically
      fetch(src)
        .then((response) => response.text())
        .then((scriptText) => {
          cache[src] = scriptText;
          return Promise.resolve(scriptText);
        })
        .catch((error) => {
          console.error('Error fetching script:', error);
          return Promise.reject(error);
        });
    } else if (!src || cache[src]) {
      // Use cached script
      const cachedScript = cache[src];
      footerHTML += `<script type="${type}">${cachedScript}</script>`;
    }
  });
  return footerHTML;
}

function fetchScripts(scripts) {
  const promises = [];
  scripts.forEach((script) => {
    if (script.src && !cache[script.src]) {
      promises.push(
        fetch(script.src)
          .then((response) => response.text())
          .then((scriptText) => {
            cache[script.src] = scriptText;
            return Promise.resolve(scriptText);
          })
          .catch((error) => {
            console.error('Error fetching script:', error);
            return Promise.reject(error);
          }),
      );
    }
  });
  return Promise.all(promises).then(() => scripts);
}

function renderScripts(scripts, dependencies) {
  const scriptHTML = '';
  scripts.forEach((script) => {
    if (dependencies.includes(script.src)) {
      // Add dependencies first
      scriptHTML += `<script type="${script.type}">${cache[script.src]}</script>`;
    } else {
      scriptHTML += `<script type="${script.type}">${cache[script.src]}</script>`;
    }
  });
  return scriptHTML;
}

function checkDependencies(scripts) {
  const dependencies = [];
  scripts.forEach((script) => {
    if (script.dependencies && script.dependencies.length > 0) {
      dependencies.push(...script.dependencies);
    }
  });
  return dependencies;
}

function detectCircularDependencies(scripts, dependencies) {
  const circularDependencies = [];
  scripts.forEach((script) => {
    if (dependencies.includes(script.src)) {
      circularDependencies.push(script.src);
    }
  });
  return circularDependencies;
}

async function main() {
  try {
    // Fetch and cache scripts
    const fetchedScripts = await fetchScripts(scripts);
    // Render scripts
    const renderedHTML = renderFooterScripts(fetchedScripts);
    // Add loading spinner or progress indicator
    document.body.innerHTML += `
      <div class="loading-spinner">
        <svg viewBox="0 0 24 24" width="24" height="24">
          <circle cx="12" cy="12" r="10" fill="none" stroke="#666" stroke-width="2"></circle>
        </svg>
        Loading scripts...
      </div>
    `;
    // Render scripts
    document.body.innerHTML += renderedHTML;
  } catch (error) {
    console.error('Error rendering footer scripts:', error);
    // Display error message and log for debugging
    document.body.innerHTML = 'Error: Unable to load scripts.';
  }
}

// Example usage:
const scripts = [
  { code: 'script1', type: 'text/javascript', src: '/api/script1' },
  { code: 'script2', type: 'application/javascript', src: '/api/script2' },
  { code: 'script3', type: 'text/javascript', dependencies: ['/api/script1'] },
];

main();
