from flask import Flask, jsonify, request
from flask_cors import CORS
from flask_sqlalchemy import SQLAlchemy
from flask_login import LoginManager, UserMixin, login_user, logout_user
from flask_socketio import SocketIO, emit

app = Flask(__name__)
CORS(app)

app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///weather_data.db'
db = SQLAlchemy(app)
socketio = SocketIO(app)

class WeatherData(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    city_name = db.Column(db.String(80), nullable=False)
    temperature = db.Column(db.Float, nullable=False)
    humidity = db.Column(db.Float, nullable=False)
    wind_speed = db.Column(db.Float, nullable=False)
    timestamp = db.Column(db.DateTime, default=datetime.datetime.utcnow)

class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password = db.Column(db.String(120), nullable=False)
    email = db.Column(db.String(120), nullable=False)

db.create_all()

login_manager = LoginManager()
login_manager.init_app(app)
login_manager.login_view = 'login'

@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        user = User.query.filter_by(username=username).first()
        if user and user.password == password:
            login_user(user)
            return jsonify({'message': 'Login successful'})
        else:
            return jsonify({'message': 'Invalid credentials'}), 401

@app.route('/logout', methods=['GET'])
def logout():
    logout_user()
    return jsonify({'message': 'Logout successful'})

@app.route('/register', methods=['POST'])
def register():
    username = request.form['username']
    password = request.form['password']
    email = request.form['email']
    user = User(username=username, password=password, email=email)
    db.session.add(user)
    db.session.commit()
    return jsonify({'message': 'User created successfully'})

@app.route('/weather', methods=['GET'])
def get_weather():
    city_name = request.args.get('city_name')
    weather_data = WeatherData.query.filter_by(city_name=city_name).first()
    if weather_data:
        return jsonify({
            'temperature': weather_data.temperature,
            'humidity': weather_data.humidity,
            'wind_speed': weather_data.wind_speed
        })
    else:
        return jsonify({'message': 'City not found'}), 404

@app.route('/weather', methods=['POST'])
def post_weather():
    city_name = request.json.get('city_name')
    temperature = request.json.get('temperature')
    humidity = request.json.get('humidity')
    wind_speed = request.json.get('wind_speed')
    weather_data = WeatherData(city_name=city_name, temperature=temperature, humidity=humidity, wind_speed=wind_speed)
    db.session.add(weather_data)
    db.session.commit()
    return jsonify({'message': 'Weather data created successfully'})

@socketio.on('connect')
def connect():
    print('Client connected')

@socketio.on('disconnect')
def disconnect():
    print('Client disconnected')

@socketio.on('weather_update')
def update_weather(data):
    city_name = data.get('city_name')
    temperature = data.get('temperature')
    humidity = data.get('humidity')
    wind_speed = data.get('wind_speed')
    weather_data = WeatherData.query.filter_by(city_name=city_name).first()
    if weather_data:
        weather_data.temperature = temperature
        weather_data.humidity = humidity
        weather_data.wind_speed = wind_speed
        db.session.commit()
        emit('weather_update', {'temperature': temperature, 'humidity': humidity, 'wind_speed': wind_speed})

if __name__ == '__main__':
    app.run(debug=True)
