import json
from db_operations import validate, save, external_api
from flask import jsonify

def manage_inventory(request):
    try:
        request_data = json.loads(request.data)

        if 'product_id' in request_data:
            action = 'update'
        else:
            action = request_data.get('action', '')

        if action not in ['add', 'update', 'delete']:
            return jsonify({'message': 'error', 'data': None}), 400

        if action == 'delete':
            product_id = request_data['product_id']
            save.delete_product(product_id)
            external_api.delete_product(product_id)
            return jsonify({'message': 'success', 'data': None})

        product = {}
        product['id'] = request_data.get('product_id', '')
        product['quantity'] = validate.positive_integer(request_data.get('quantity', 0))
        product['price'] = validate.positive_number(request_data.get('price', 0.0))
        product['category'] = request_data.get('category', '')

        if action in ['add', 'update']:
            save.save_product(product)
            external_api.save_product(product)
            return jsonify({'message': 'success', 'data': None})

    except (KeyError, ValueError):
        return jsonify({'message': 'error', 'data': None}), 400
    except Exception as e:
        return jsonify({'message': 'error', 'data': None}), 500

