def merge_chunks(chunk_size: int, chunked_data: List[BytesIO]):
    merged_data = BytesIO()
    for chunk in chunked_data:
        merged_data.write(chunk.read(chunk_size))
    return merged_data.getvalue()

class WeatherMonitor:
    def __init__(self):
        self.api_keys = {'openweathermap': 'https://api.openweathermap.org/data/2.5/weather?q={city}&appid={api_key}',
                         'weatherapi': 'https://api.weatherapi.com/v1/current.json?key={api_key}&q={city}',
                         'accuweather': 'https://api.accuweather.com/currentconditions/v1/{city}.json?apikey={api_key}'}
        self.cached_data = {}

    def fetch_weather(self, city_names: List[str]) -> dict:
        weather_data = {}
        for city in city_names:
            if city not in self.cached_data:
                response = requests.get(self.api_keys['openweathermap'].format(city=city, api_key='your_openweathermap_api_key'))
                if response.status_code == 200:
                    data = json.loads(response.text)
                    weather_data[city] = data
                    self.cached_data[city] = data
        return weather_data

    def log_weather(self, city_names: List[str], weather_data: dict):
        db = sqlite3.connect('weather_database.db')
        cursor = db.cursor()
        for city, data in weather_data.items():
            cursor.execute("INSERT INTO weather_data (city, temperature, humidity) VALUES (?, ?, ?)", 
                            (city, data['main']['temp'], data['main']['humidity']))
        db.commit()
        db.close()

    def aggregate_weather(self, city_names: List[str], weather_data: dict):
        aggregated_data = defaultdict(dict)
        for city, data in weather_data.items():
            if 'temperature' in data and 'humidity' in data:
                aggregated_data[city]['temperature'] = (aggregated_data.get(city, {}).get('temperature', 0) + data['main']['temp']) / 2
                aggregated_data[city]['humidity'] = (aggregated_data.get(city, {}).get('humidity', 0) + data['main']['humidity']) / 2
        return dict(aggregated_data)

    def get_aggregated_weather(self, city_names: List[str]):
        weather_data = self.fetch_weather(city_names)
        aggregated_data = self.aggregate_weather(city_names, weather_data)
        self.log_weather(city_names, weather_data)
        return aggregated_data

