import logging
import os
import time
import json
import requests
from retry import retry

@retry(wait_exponential_max=60)
def create_log_dir(log_path):
    try:
        os.makedirs(log_path)
    except Exception as e:
        raise e

def configure_logging(env_vars, config_service):
    log_config = {
        "version": 1,
        "formatters": {
            "standard": {"format": "%(asctime)s [%(name)s] %(levelname)s: %(message)s"}
        },
        "handlers": {
            "file": {
                "class": "logging.FileHandler",
                "filename": os.path.join(env_vars.get("LOG_DIR", "/var/log/moba"), env_vars.get("LOG_FILE", "moba.log")),
                "formatter": "standard"
            }
        },
        "root": {"level": logging.INFO, "handlers": ["file"]}
    }

    if config_service:
        try:
            response = requests.get(config_service)
            config_data = json.loads(response.text)
            log_config["formatters"]["custom"] = {"format": config_data.get("LOG_FORMAT", "%(asctime)s [%(name)s] %(levelname)s: %(message)s")}
            log_config["handlers"]["file"]["formatter"] = "custom"
        except Exception as e:
            print(f"Error fetching configuration from {config_service}: {e}")

    logging.config.dictConfig(log_config)

def rotate_logs(env_vars):
    log_path = os.path.join(env_vars.get("LOG_DIR", "/var/log/moba"), env_vars.get("LOG_FILE", "moba.log"))
    while True:
        try:
            if os.path.isfile(log_path):
                file_size = os.path.getsize(log_path)
                if file_size > int(env_vars.get("MAX_LOG_SIZE", 1048576)):
                    os.rename(log_path, f"{log_path}.1")
                    with open(f"{log_path}.1", "w"): pass
                elif time.time() - os.path.getmtime(log_path) > float(env_vars.get("LOG_RETENTION", 604800)):
                    os.rename(log_path, f"{log_path}.1")
                    with open(f"{log_path}.1", "w"): pass
        except Exception as e:
            print(f"Error rotating logs: {e}")
        time.sleep(int(env_vars.get("LOG_ROTATION_INTERVAL", 3600)))

def main():
    env_vars = {
        "LOG_DIR": "/var/log/moba",
        "LOG_FILE": "moba.log",
        "MAX_LOG_SIZE": "1048576",
        "LOG_RETENTION": "604800",
        "LOG_ROTATION_INTERVAL": "3600"
    }
    config_service = "https://config-service.com/config"

    create_log_dir(env_vars.get("LOG_DIR", "/var/log/moba"))
    configure_logging(env_vars, config_service)
    rotate_logs(env_vars)

if __name__ == "__main__":
    main()
