public class NetworkCommunicationFramework {
    private static final int DEFAULT_CONNECTION_POOL_SIZE = 1000;
    private static final int MINIMUM_CONNECTION_POOL_SIZE = 10;
    private static final int MAXIMUM_CONNECTION_POOL_SIZE = 10000;

    private ExecutorService executor;
    private ConnectionPool connectionPool;

    public NetworkCommunicationFramework(int connectionPoolSize) {
        this.connectionPool = new ConnectionPool(connectionPoolSize);
        this.executor = new ThreadPoolExecutor(
                DEFAULT_CONNECTION_POOL_SIZE,
                MAXIMUM_CONNECTION_POOL_SIZE,
                MINIMUM_CONNECTION_POOL_SIZE,
                new LinkedBlockingQueue<Runnable>());
    }

    public void establishConnection(String host, int port) {
