<?php
class AuthModule {
    private $oauthProvider;
    private $cache;

    public function __construct($oauthProvider) {
        $this->oauthProvider = $oauthProvider;
        $this->cache = new Memcached();
    }

    public function authenticate($code) {
        $token = $this->oauthProvider->getAccessToken($code);
        if ($token) {
            $this->storeToken($token);
            return true;
        }
        return false;
    }

    public function updateResource($resourceId, $data) {
        $token = $this->getToken();
        $response = $this->oauthProvider->updateResource($resourceId, $data, $token);
        if ($response && isset($response->body)) {
            $this->cache->set('updated-resource', json_encode($response->body));
            return $response;
        }
        return null;
    }

    public function deleteResource($resourceId) {
        $token = $this->getToken();
        $response = $this->oauthProvider->deleteResource($resourceId, $token);
        if ($response && isset($response->body)) {
            $this->cache->set('new-resource', json_encode($response->body));
            return $response;
        }
        return null;
    }

    private function storeToken($token) {
        $_SESSION['access_token'] = $token;
    }

    private function getToken() {
        return $_SESSION['access_token'];
    }
}
