import boto3
import os
from PIL import Image
from io import BytesIO
import json
import hashlib
import time

s3 = boto3.client('s3')
image_processing_bucket_name = os.environ['IMAGE_PROCESSING_BUCKET']
cache_expiration_time_in_hours = int(os.environ['CACHE_EXPIRATION_TIME_IN_HOURS'])

def get_image_from_url(url):
    response = requests.get(url)
    if response.status_code != 200:
        raise Exception(f"Failed to retrieve image from {url} with status code {response.status_code}")
    return response.content

def process_image(image_bytes, width=800, height=600):
    img = Image.open(BytesIO(image_bytes))
    new_width = int(min(width, img.size[0]) * (height / img.size[1]))
    new_height = int(min(height, img.size[1]) * (width / img.size[0]))
    img.thumbnail((new_width, new_height), resample=Image.LANCZOS)
    bio = BytesIO()
    img.save(bio, 'PNG')
    return bio.getvalue()

def get_image_hash(image_bytes):
    md5_hash = hashlib.md5(image_bytes).hexdigest()
    return md5_hash

def check_image_cache(md5_hash):
    cache_expiration_time_in_seconds = cache_expiration_time_in_hours * 3600
    current_time = time.time()
    cache_key = f"image:{md5_hash}"
    cached_timestamp = s3.get_object(Bucket=image_processing_bucket_name, Key=cache_key).get('LastModified').timestamp() if s3.get_object(Bucket=image_processing_bucket_name, Key=cache_key) else None
    if cached_timestamp and current_time - cached_timestamp < cache_expiration_time_in_seconds:
        return True
    return False

def upload_image_to_s3(image_bytes):
    image_hash = get_image_hash(image_bytes)
    bucket_name = os.environ['IMAGE_UPLOAD_BUCKET']
    s3.put_object(Body=image_bytes, Bucket=bucket_name, Key=f"{image_hash}.png")
    public_url = f"https://{bucket_name}.s3.amazonaws.com/{image_hash}.png"
    return public_url

def get_image_metadata(public_url):
    bucket_name = os.environ['IMAGE_UPLOAD_BUCKET']
    response = s3.head_object(Bucket=bucket_name, Key=os.path.basename(public_url))
    image_size = int(response.get('ContentLength'))
    image_format = 'PNG'
    upload_timestamp = response.get('LastModified').timestamp()
    return {
        "publicUrl": public_url,
        "size": image_size,
        "format": image_format,
        "uploadTimestamp": upload_timestamp
    }

def lambda_handler(event, context):
    if event['httpMethod'] != 'POST':
        return {"statusCode": 405, "body": json.dumps({"error": "Invalid HTTP method"})}

    url = event.get('body', {}).get('url')
    if not url:
        return {"statusCode": 400, "body": json.dumps({"error": "Missing URL in request body"})}

    try:
        image_bytes = get_image_from_url(url)
        md5_hash = get_image_hash(image_bytes)

        if check_image_cache(md5_hash):
            return {
                "statusCode": 304,
                "body": json.dumps({
                    "publicUrl": f"https://s3.amazonaws.com/{os.environ['IMAGE_UPLOAD_BUCKET']}/{md5_hash}.png",
                    "size": int(s3.head_object(Bucket=os.environ['IMAGE_PROCESSING_BUCKET'], Key=md5_hash).get('ContentLength')),
                    "format": 'PNG',
                    "uploadTimestamp": s3.head_object(Bucket=os.environ['IMAGE_PROCESSING_BUCKET'], Key=md5_hash).get('LastModified').timestamp()
                })
            }

        processed_image_bytes = process_image(image_bytes)
        public_url = upload_image_to_s3(processed_image_bytes)

        return {
            "statusCode": 200,
            "body": json.dumps({
                **get_image_metadata(public_url),
                "message": "Image uploaded successfully"
            })
        }
    except Exception as e:
        print(f"Error: {str(e)}")
        return {"statusCode": 500, "body": json.dumps({"error": str(e)})}
