        List<Element> result = new List<Element>();
        try {
            await Task.Run(() => {
                foreach (var element in document.querySelectorAll(selector)) {
                    result.Add(element);
                }
            });
        } catch (Exception e) {
            // Handle the error here...
        }
        return result;
    }

    // Caching mechanism for frequently used selectors.
    private Dictionary<string, List<Element>> cachedSelectors = new Dictionary<string, List<Element>>();

    public async Task<List<Element>> FindElementsBySelectorAsync(string selector) {
        if (cachedSelectors.ContainsKey(selector)) {
            return cachedSelectors[selector];
        } else {
            var result = await FindElementsBySelectorAsync(selector);
            cachedSelectors.Add(selector, result);
            return result;
        }
