#include <boost/beast/core.hpp>
#include <boost/beast/http.hpp>
#include <boost/beast/version.hpp>
#include <boost/asio/io_context.hpp>
#include <boost/asio/ip/tcp.hpp>
#include <boost/asio/steady_timer.hpp>
#include <boost/flyweight.hpp>
#include <json/json.h>

using namespace boost::beast;
using namespace boost;

class SandeshClient {
public:
    void SendRequest(const std::string& method, const std::string& url,
                     const Json::Value& metadata, bool use_post) {
        // Create a new context and session
        auto context = io_context();
        auto session = std::make_shared<boost::beast::http::async_response_session>(
            context.get_executor(), boost::beast::http::version_1_1);

        // Set the request method and URL
        boost::beast::http::request<boost::beast::http::string_body> req;
        req.version = 11;
        req.method(boost::beast::http::verb(method));
        req.target(url);
        if (use_post) {
            req.set(boost::beast::http::field::content_type, "application/json");
        }

        // Set the request headers
        req.prepare_payload();
        for (auto& pair : metadata) {
            if (pair.isString()) {
                req.set(pair.name(), pair.stringValue());
            }
        }

        // Start the timer to simulate connection timeout
        auto timer = std::make_shared<steady_timer>(context.get_executor());
        timer->expires_after(std::chrono::seconds(timeout_));
        timer->async_wait([&](boost::system::error_code ec) {
            if (!ec && session->isRunning()) {
                // If the request timed out, cancel it
                session->cancel();
            }
        });

        // Send the request and handle the response
        boost::beast::http::async_write(session.get(), req,
                                          [this, &session](boost::beast::error_code ec) {
            if (!ec) {
                // Read the response
                boost::beast::http::response<boost::beast::http::string_body> res;
                session->async_read_some(boost::asio::null_buffers(), res);

                // Log the request information
                logRequestInfo(method, url, use_post, ec.value());
            } else {
                // Handle the error
                handleRequestError(ec);
            }
        });
    }

    void start() {
        // Start the I/O context
        boost::asio::io_context::work(work_).get();

        // Initialize the rate limiter
        auto rateLimiter = std::make_shared<rate_limited_sender>(this->rateLimit_);
        boost::beast::http::async_write(session_, *req_,
                                         [this, &rateLimiter](boost::beast::error_code ec) {
            if (!ec) {
                // Log the request information
                logRequestInfo(req_->method().name(), req_->target(), false, 200);
            } else {
                // Handle the error
                handleRequestError(ec);
            }
        });
    }

    void configure(const std::string& configFile) {
        // Load the configuration file
        Json::Value config;
        auto configFile = boost::filesystem::path(configFile).make_preferred();
        if (boost::filesystem::exists(configFile)) {
            try {
                config = jsonFromFile(configFile);
            } catch (const std::exception& e) {
                // Handle the error
                std::cerr << "Error loading configuration file: " << e.what() << std::endl;
                return;
            }
        }

        // Update the client configuration
        if (!config.empty()) {
            timeout_ = config["timeout"].asUInt();
            retryPolicy_ = config["retry_policy"].asString();
            rateLimit_ = config["rate_limit"].asUInt();
        }
    }

private:
    void logRequestInfo(const std::string& method, const std::string& url,
                         bool use_post, int statusCode) {
        // Log the request information
        auto logTime = boost::posix_time::microsec_clock::universal_time();
        std::cout << "Request [" << logTime << "] - Method: " << method << ", URL: "
                  << url << ", Use POST: " << (use_post ? "true" : "false") << ", Status Code: "
                  << statusCode << ", Response Body Length: 0, Error Messages: []"
                  << std::endl;
    }

    void handleRequestError(const boost::system::error_code& ec) {
        // Handle the error
        auto logTime = boost::posix_time::microsec_clock::universal_time();
        std::cerr << "Error [" << logTime << "] - Code: " << ec.value() << ", Message: "
                  << ec.message() << std::endl;
    }

    Json::Value jsonFromFile(const std::string& configFile) {
        // Load the JSON file
        Json::Value config;
        try {
            auto file = boost::filesystem::ifstream(configFile);
            if (file.is_open()) {
                Json::Value root;
                file >> root;
                return root;
            }
        } catch (const std::exception& e) {
            // Handle the error
            throw e;
        }
    }

    boost::asio::io_context ioContext_;
    boost::beast::http::async_response_session session_;
    boost::beast::http::request<boost::beast::http::string_body> req_;
    int timeout_ = 1000; // in milliseconds
    std::string retryPolicy_;
    int rateLimit_;
};

int main() {
    SandeshClient client;
    client.configure("config.json");
    client.start();
    return 0;
}
