using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class UpdateElementService
{
    private readonly ICacheService _cacheService;
    private readonly IMessageQueueService _messageQueueService;
    private readonly ILogger _logger;

    public UpdateElementService(ICacheService cacheService, IMessageQueueService messageQueueService, ILogger logger)
    {
        _cacheService = cacheService;
        _messageQueueService = messageQueueService;
        _logger = logger;
    }

    public async Task<string> UpdateElementAsync(string sectionId, string elementId, string htmlContent, string? revisionComment = null, int version = 0)
    {
        // Validate input
        if (string.IsNullOrEmpty(sectionId) || string.IsNullOrEmpty(elementId))
            return "Invalid IDs";

        try
        {
            var cacheKey = GetCacheKey(sectionId, elementId);
            var cachedVersion = _cacheService.GetVersion(cacheKey);

            if (cachedVersion != version)
                throw new InvalidOperationException("Concurrency conflict");

            // Update cache and message queue
            await _cacheService.UpdateHtmlContentAsync(cacheKey, htmlContent, revisionComment);
            await _messageQueueService.EnqueueRefreshMessageAsync(sectionId);

            return "Update successful";
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating element");
            return "Error updating element";
        }
    }

    private string GetCacheKey(string sectionId, string elementId) => $"{sectionId}:{elementId}";
}

public interface ICacheService
{
    Task<string> GetHtmlContentAsync(string cacheKey);
    Task UpdateHtmlContentAsync(string cacheKey, string htmlContent, string? revisionComment = null);
    int GetVersion(string cacheKey);
}

public interface IMessageQueueService
{
    Task EnqueueRefreshMessageAsync(string sectionId);
}
