#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <time.h>

#define LOG_FILE "secure_trim_append_log.txt"
#define DEBUG 1
#define INFO 2
#define ERROR 3

void log_message(int level, const char* message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        return;
    }
    fprintf(fp, "%s [%d]: %s\n", 
             (level == DEBUG ? "DEBUG" : (level == INFO ? "INFO" : "ERROR")),
             time(NULL), message);
    fclose(fp);
}

char* secureTrimAndAppendSlash(const char* str, size_t size_limit) {
    if (!str || size_limit < 0) {
        log_message(ERROR, "Invalid input: null pointer or negative size limit");
        return NULL;
    }

    size_t len = strlen(str);
    const char *start = str + strspn(str, " \t\r\n\f\v");
    const char *end = str + strlen(str) - strcspn(str + len - 1, " \t\r\n\f\v");

    if (len > size_limit || (start != str && end != str + len)) {
        log_message(DEBUG, "Trimmed string length: %zu", len);
        log_message(INFO, "Appended slash: %s", start == str ? "" : "/");
        return NULL;
    }

    char *trimmed = malloc(len + 1);
    if (!trimmed) {
        log_message(ERROR, "Memory allocation failed");
        return NULL;
    }

    strncpy(trimmed, start, len);
    trimmed[len] = '\0';
    log_message(INFO, "Trimmed string: %s", trimmed);

    char *result = malloc(len + 2); // Add space for slash
    if (!result) {
        free(trimmed);
        return NULL;
    }

    strncpy(result, trimmed, len);
    result[len] = '\0';
    log_message(DEBUG, "Appended slash: %s", result);

    free(trimmed);
    return (char*)strcat(result, "/"), strcat(result, "\0");
}
