namespace DynamicValueGenerator
{
    public enum RangeType { Closed, Open, HalfOpen }

    public class RangeConfig
    {
        public int Min { get; set; }
        public int Max { get; set; }
        public RangeType Type { get; set; }
    }

    public class SeedManager
    {
        private readonly object _lock = new object();
        private static long _seed;

        public void InitializeSeed()
        {
            lock (_lock)
            {
                if (_seed == 0)
                {
                    _seed = DateTime.Now.Ticks;
                }
            }
        }

        public long GetSeed()
        {
            return _seed;
        }
    }

    public class DynamicValueGenerator
    {
        private readonly SeedManager _seedManager;
        private readonly Dictionary<string, RangeConfig> _rangeCache;

        public DynamicValueGenerator(SeedManager seedManager)
        {
            _seedManager = seedManager;
            _rangeCache = new Dictionary<string, RangeConfig>();
        }

        public double GenerateValue(string rangeId, int count)
        {
            var rangeConfig = GetRangeConfiguration(rangeId);
            if (rangeConfig == null) throw new ArgumentException("Invalid range ID");

            for (int i = 0; i < count; i++)
            {
                // Implement random value generation logic using the seed and range configuration
                // For demonstration purposes, use a simple linear congruential generator
                var seed = _seedManager.GetSeed();
                var rng = new Random(seed);
                double value;

                switch (rangeConfig.Type)
                {
                    case RangeType.Closed:
                        value = rng.NextDouble() * (rangeConfig.Max - rangeConfig.Min) + rangeConfig.Min;
                        break;
                    case RangeType.Open:
                        value = rng.NextDouble() * (rangeConfig.Max - rangeConfig.Min - 1) + rangeConfig.Min + 1;
                        break;
                    case RangeType.HalfOpen:
                        if (rng.NextDouble() < 0.5)
                        {
                            value = rng.NextDouble() * (rangeConfig.Max - rangeConfig.Min) + rangeConfig.Min;
                        }
                        else
                        {
                            value = rng.NextDouble() * (rangeConfig.Max - rangeConfig.Min - 1) + rangeConfig.Min + 1;
                        }
                        break;
                    default:
                        throw new InvalidOperationException("Unsupported range type");
                }

                // Implement external data source integration, if required
                // For demonstration purposes, use a simple callback system
                foreach (var callback in _rangeCache[rangeId])
                {
                    value = callback(value);
                }

                return value;
            }
        }

        private RangeConfig GetRangeConfiguration(string rangeId)
        {
            // Implement caching and external data source integration logic here
            // For demonstration purposes, assume a simple in-memory cache
            if (_rangeCache.TryGetValue(rangeId, out var rangeConfig))
            {
                return rangeConfig;
            }

            // Simulate an external data source fetch
            // Replace with actual implementation for your data source
            rangeConfig = new RangeConfig { Min = 1, Max = 100, Type = RangeType.Closed };
            _rangeCache.Add(rangeId, rangeConfig);
            return rangeConfig;
        }
    }
