int integrateAndOptimizeFSACreator(int* states, int numStates, struct FSA* fsa, int lastState) {
    // Create a new array to store the updated state list
    int* newStates = (int*)malloc((numStates + 1) * sizeof(int));

    // Copy the existing states into the new array
    for (int i = 0; i < numStates; i++) {
        newStates[i] = states[i];
    }

    // Initialize the 'next' pointer of the last state in the list to point to the new states
    fsa->states[lastState].next = (void*)newStates + numStates;

    // Update the 'numStates' field of the FSA to reflect the new size of the state list
    fsa->numStates = numStates + 1;

    return 0;
}
