using System;
using System.Xml;
using System.Xml.XPath;

public class XmlFinder
{
    public static void FindXmlElement(string xml, string pathExpression)
    {
        try
        {
            // Validate XML document for well-formedness
            XmlDocument doc = new XmlDocument();
            doc.LoadXml(xml);
            XPathDocument xpathDoc = new XPathDocument(new XmlNodeReader(doc));

            // Parse the XML document using XPath
            XPathNavigator nav = xpathDoc.CreateNavigator();
            XPathExpression expression = nav.Compile(pathExpression);

            XPathNodeIterator iterator = nav.Select(expression);
            if (!iterator.MoveNext())
                throw new Exception("No elements found with name " + pathExpression);

            // Check for multiple matches and throw exception
            if (iterator.MoveNext())
                throw new Exception("Multiple elements found with name " + pathExpression);

            // Get the first matching element
            XPathNodeIterator current = iterator.Current;
            string nodeName = current.Name;

            Console.WriteLine("First element with name {0} is: {1}", pathExpression, nodeName);
        }
        catch (XmlException ex)
        {
            Console.WriteLine("Error parsing XML document: " + ex.Message);
        }
        catch (XPathException ex)
        {
            Console.WriteLine("Invalid XPath expression: " + ex.Message);
        }
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        if (args.Length < 2)
        {
            Console.WriteLine("Usage: XmlFinder.exe [xml] [xpath]");
            return;
        }

        string xml = args[0];
        string pathExpression = args[1];

        try
        {
            XmlFinder.FindXmlElement(xml, pathExpression);
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error: " + ex.Message);
        }
    }
}
