        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 100);

        int randomNum = dis(gen);
        std::cout << "Random Number: " << randomNum << std::endl;

        // Synchronize the random number generation across nodes
        auto startTime = std::chrono::high_resolution_clock::now();
        while (std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::high_resolution_clock::now().time_since_epoch()).count() - startTime.count() < 100) {
