use tokio::prelude::*;
use pyo3::{prelude as py, types};
use pyo3::{Python, PyModule};

#[tokio::main]
async fn main() {
    let python = Python::acquire_gil().unwrap();
    let args: Vec<String> = std::env::args().collect();

    if args.len() < 2 {
        eprintln!("Usage: {} <module_name>", &args[0]);
        return;
    }

    let module_name = &args[1];
    match RunModuleTestsAsync(python, module_name).await {
        Ok(_) => println!("All tests passed"),
        Err(err) => eprintln!("Error running tests: {}", err),
    }
}

async fn RunModuleTestsAsync(python: Python, module_name: &str) -> Result<(), PyErr> {
    let module = python.import(module_name)?;
    let mut test_count = 0;

    for func in module.iter_functions() {
        if func.is_method() || func.is_function() {
            match py::try_func(*func, None).await {
                Ok(result) => {
                    println!("Test {}: {}", test_count + 1, result);
                    test_count += 1;
                }
                Err(err) => return Err(err.into()),
            };
        }
    }

    Ok(())
}
