// Function to dynamically select an attack based on character type and cooldown period
Attack selectAttack(const Character& character) {
    // Initialize priority list of attacks based on character profile
    std::vector<Attack> priorityAttacks;

    for (const auto& attack : character.getProfile().getAttacks()) {
        if (!attack.getCoolDownPeriod().isExpired()) {
            priorityAttacks.push_back(attack);
        }
    }

    // Try to use the highest-priority attack that meets cooldown criteria
    for (auto it = priorityAttacks.rbegin(); it != priorityAttacks.rend(); ++it) {
        if (!it->getCooldownPeriod().isExpired()) {
            return *it;
        }
    }

    // If no valid attack in priority list, select from all available attacks
    Attack bestAttack = Attack::defaultAttack();
    for (const auto& attack : character.getProfile().getAttacks()) {
        if (!attack.getCoolDownPeriod().isExpired() && attack.getStrength() > bestAttack.getStrength()) {
            bestAttack = attack;
        }
    }

    return bestAttack;
}

