```
function refreshDialogFields(resourceId, url, fieldNamesToRefresh) {
  const dialogFields = document.querySelectorAll('[data-field]');

  for (const fieldName of fieldNamesToRefresh) {
    const field = dialogFields.find((field) => field.dataset.field === fieldName);

    if (!field) {
      console.error(`Field "${fieldName}" not found`);
      continue;
    }

    const externalServicePromise = fetchUpdatedData(resourceId, url, fieldName);

    externalServicePromise.then((data) => {
      field.innerHTML = data;
    }).catch((error) => {
      handleExternalServiceError(error);
    });
  }

  function fetchUpdatedData(resourceId, url, fieldName) {
    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      xhr.open('GET', `${url}/${resourceId}/${fieldName}`, true);
      xhr.onload = () => {
        if (xhr.status === 200) {
          resolve(xhr.responseText);
        } else {
          reject(new Error(`Error fetching data for field "${fieldName}"`));
        }
      };
      xhr.onerror = () => {
        reject(new Error('Network error'));
      };
      xhr.send();
    });
  }

  function handleExternalServiceError(error) {
    console.error(error);
    // Display error message to the user
  }
}
