```c
#include <stdlib.h>
#include <string.h>

char* dynamicFileNameUpdate(const char* filename, const char* file_type, int version_number) {
    size_t len = strlen(filename);
    size_t new_len = 0;
    const char* dot_pos = NULL;

    // Check if the file has an extension
    for (size_t i = len - 1; i > 0 && filename[i] != '.'; --i) {
        if (filename[i] == '.') {
            dot_pos = &filename[i];
            break;
        }
    }

    // Calculate the new length
    size_t base_len = strlen(filename);
    if (dot_pos) {
        base_len -= (dot_pos - filename);
    }
    new_len = base_len + 4; // Add '.vX.' extension

    char* result = malloc(new_len + 1);
    strcpy(result, filename);

    // Check for existing versioning
    if (dot_pos && strstr(dot_pos, "v")) {
        size_t vpos = dot_pos - filename;
        // Replace the last occurrence of ".v" with ".vX."
        memmove(result + base_len, result + vpos, new_len - base_len);
        new_len -= vpos - base_len;
    }

    // Add the versioning and file type
    sprintf(result + new_len - 4, ".v%d.%s", version_number, file_type);

    return result;
}
