import requests
from flask import Flask, request, jsonify
from flask_cors import CORS
from datetime import datetime

app = Flask(__name__)
CORS(app)

class PaymentGateway:
    def __init__(self, api_key):
        self.api_key = api_key

    def process_payment(self, amount):
        # Make API call to payment gateway
        response = requests.post(
            'https://api.payment_gateway.com/charge', 
            json={'amount': amount}, 
            headers={'Authorization': f'Bearer {self.api_key}'}
        )
        return response.json()

class StripeGateway(PaymentGateway):
    def __init__(self, api_key):
        super().__init__(api_key)

class PayPalGateway(PaymentGateway):
    def __init__(self, api_key):
        super().__init__(api_key)

class Transaction:
    def __init__(self, amount, payment_gateway):
        self.amount = amount
        self.payment_gateway = payment_gateway

class PaymentProcessor:
    def __init__(self):
        self.rate_limit = {'requests': 0, 'window': datetime.now()}

    def process_transaction(self, transaction):
        if self.is_rate_limited():
            return jsonify({'error': 'Rate limit exceeded'}), 429
        try:
            payment_gateway = transaction.payment_gateway.process_payment(transaction.amount)
            # Update transaction status in database
            # ...
            return jsonify(payment_gateway), 201
        except Exception as e:
            # Handle exceptions
            return jsonify({'error': str(e)}), 500

    def is_rate_limited(self):
        current_time = datetime.now()
        if (current_time - self.rate_limit['window']).total_seconds() < 60:  # Check if rate limit window has passed
            self.rate_limit['requests'] += 1
            return self.rate_limit['requests'] > 10  # Check if maximum requests reached within the window
        else:
            self.rate_limit = {'requests': 0, 'window': current_time}
            return False

@app.route('/transactions', methods=['POST'])
def create_transaction():
    data = request.get_json()
    amount = float(data['amount'])
    payment_gateway_name = data['payment_gateway']
    if payment_gateway_name == 'stripe':
        payment_gateway = StripeGateway('YOUR_STRIPE_API_KEY')
    elif payment_gateway_name == 'paypal':
        payment_gateway = PayPalGateway('YOUR_PAYPAL_API_KEY')
    else:
        return jsonify({'error': 'Invalid payment gateway'}), 400
    transaction = Transaction(amount, payment_gateway)
    processor = PaymentProcessor()
    response = processor.process_transaction(transaction)
    return response

if __name__ == '__main__':
    app.run(debug=True)

