import os
import logging
from bs4 import BeautifulSoup
from collections import Counter
import csv
import gzip
import zipfile
import requests

logging.basicConfig(level=logging.INFO)

class FileProcessor:
    def __init__(self, directory):
        self.directory = directory
        self.cache = {}

    def process_directory(self):
        for root, dirs, files in os.walk(self.directory):
            for file in files:
                file_path = os.path.join(root, file)
                if file.endswith('.txt'):
                    self.process_txt_file(file_path)
                elif file.endswith('.log'):
                    self.process_log_file(file_path)
                elif file.endswith('.csv'):
                    self.process_csv_file(file_path)
                elif file.endswith(('.gz', '.zip')):
                    self.decompress_and_process(file_path)

    def process_txt_file(self, file_path):
        with open(file_path, 'r') as f:
            lines = f.readlines()
            words = len(lines[0].split())
            characters = sum(len(line) for line in lines)
            logging.info(f"Processed {file_path}: {lines.count('\n')} lines, {words} words, {characters} characters")

    def process_log_file(self, file_path):
        with open(file_path, 'r') as f:
            lines = f.readlines()
            words = len(lines[0].split())
            characters = sum(len(line) for line in lines)
            logging.info(f"Processed {file_path}: {lines.count('\n')} lines, {words} words, {characters} characters")

    def process_csv_file(self, file_path):
        with open(file_path, 'r') as f:
            reader = csv.reader(f)
            headers = next(reader)
            data = list(reader)
            unique_values = [Counter({row[i]: None for row in data}).most_common(1)[0][0] for i in range(len(headers))]
            mean = sum([float(row[0]) for row in data]) / len(data)
            median = sorted([float(row[0]) for row in data])[len(data)//2]
            mode = max(set(unique_values), key=unique_values.count)
            logging.info(f"Processed {file_path}: Unique values - {unique_values}, Mean - {mean}, Median - {median}, Mode - {mode}")

    def decompress_and_process(self, file_path):
        if file_path.endswith('.gz'):
            with gzip.open(file_path, 'rt') as f:
                self.process_file_like_text(f)
        elif file_path.endswith('.zip'):
            with zipfile.ZipFile(file_path) as z:
                for name in z.namelist():
                    with z.open(name, 'r') as f:
                        self.process_file_like_text(f)

    def process_html(self, file_path):
        with open(file_path, 'r') as f:
            soup = BeautifulSoup(f, 'html.parser')
            logging.info(f"Processed {file_path}: {len(soup.find_all())} elements")

class WebInterface:
    def __init__(self, file_processor):
        self.file_processor = file_processor

    def start(self):
        app = Flask(__name__)
        @app.route('/')
        def index():
            return render_template('index.html', plugins=self.file_processor.get_plugins())

        @app.route('/plugins')
        def get_plugins():
            return jsonify({plugin: self.file_processor.get_plugin(plugin) for plugin in self.file_processor.get_plugins()})

        app.run(debug=True)
