<?php

function generateSecureToken($length, $characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
    if (!is_integer($length) || $length <= 0) {
        throw new Exception('Invalid length');
    }
    if (!is_string($characterSet)) {
        throw new Exception('Invalid character set');
    }

    $token = '';
    for ($i = 0; $i < $length; $i++) {
        $token .= $characterSet[rand(0, strlen($characterSet) - 1)];
    }
    return $token;
}

function hashPassword($password, $algorithm = 'bcrypt', $salt = '') {
    if (!is_string($password)) {
        throw new Exception('Invalid password');
    }
    if (!in_array($algorithm, ['bcrypt', 'Argon2id'])) {
        throw new Exception('Unsupported algorithm');
    }

    if (empty($salt)) {
        $salt = generateSecureToken(10);
    }

    switch ($algorithm) {
        case 'bcrypt':
            return password_hash($password . $salt, PASSWORD_BCRYPT);
        case 'Argon2id':
            return sodium_hex2bin(sodium_crypto_pwhash_argon2id($password . $salt, 4096));
        default:
            throw new Exception('Unsupported algorithm');
    }
}

