import json
import os
from abc import ABC, abstractmethod
from functools import lru_cache
from concurrent.futures import ThreadPoolExecutor

class ProductSerializable(ABC):
    @abstractmethod
    def to_json(self) -> str:
        pass

    @classmethod
    @lru_cache(maxsize=None)
    def from_json(cls, json_data: str) -> 'ProductSerializable':
        return cls(**json.loads(json_data))

def load_file(file_path: str) -> dict:
    with open(file_path, 'r') as file:
        return json.load(file)

class ProductLoader:
    def __init__(self):
        self.factories = {}
        self.config_loader = None

    def register_factory(self, product_type: str, factory_func):
        self.factories[product_type] = factory_func

    @lru_cache(maxsize=None)
    def load_product(self, file_path: str) -> ProductSerializable:
        try:
            product_data = load_file(file_path)
            product_type = product_data['type']
            factory_func = self.factories.get(product_type)
            if not factory_func:
                raise ValueError(f"Unsupported product type: {product_type}")
            return factory_func(**product_data)

        except Exception as e:
            print(f"Failed to load file '{file_path}': {str(e)}")
            return None

    def load_files(self, file_paths: list):
        with ThreadPoolExecutor() as executor:
            future_results = [executor.submit(self.load_product, file_path) for file_path in file_paths]
            results = [future.result() for future in future_results if future.result() is not None]
            return results
