struct OctreeNode {
    // Node type (internal or leaf)
    enum class NodeType { Internal, Leaf };

    // Data structure for storing feature data
    struct FeatureData {
        int feature1;
        float feature2;
        std::string feature3;
    };

    // Actual node contents
    union {
        FeatureData data;
        std::vector<OctreeNode*> children;  // for internal nodes
    } contents;

    // Node properties
    int size;
    NodeType type;

    OctreeNode(int size, NodeType type) : size(size), type(type) {}
};

class Octree {
public:
    Octree() : root(new OctreeNode(0, OctreeNode::NodeType::Internal)) {}

    ~Octree() {
        clear(root);
    }

    void insert(const int x, const int y, const int z, const OctreeNode::FeatureData& data);

    bool query(int x, int y, int z, int& result);

private:
    void clear(OctreeNode* node);

    std::unique_ptr<OctreeNode> root;
};

void Octree::clear(OctreeNode* node) {
    if (node == nullptr)
        return;

    if (node->type == OctreeNode::NodeType::Leaf) {
        // Release memory for leaf nodes
        delete node;
    } else {
        // Recursively clear child nodes and release memory
        for (auto& child : node->contents.children) {
            clear(child.get());
            delete child;
        }
    }
}

