// Define a function to handle script rendering
function renderScripts(scripts) {
  const footerHTML = scripts.map((script) => `
    <li>
      <h2>${script.title}</h2>
      <p>${script.description}</p>
    </li>
  `).join('');

  // Render the HTML in the footer
  document.getElementById('footer').innerHTML = `<ul>${footerHTML}</ul>`;
}

// Define a function to fetch scripts asynchronously
async function loadScripts() {
  try {
    const response = await fetch('/api/scripts');
    const scripts = await response.json();

    // Cache fetched scripts in local storage
    localStorage.setItem('scripts', JSON.stringify(scripts));

    renderScripts(scripts);
  } catch (error) {
    console.error(error);
  }
}

// Define a function to handle missing script properties
function fillScriptProperties(script) {
  const defaultValues = { title: '', description: '' };

  return { ...script, ...defaultValues };
}

// Load scripts on page load or when the user interacts with the footer
window.addEventListener('load', loadScripts);
document.getElementById('footer').addEventListener('click', loadScripts);

// Define a function to display a loading spinner and handle retries
function displayLoadingSpinner() {
  const spinnerHTML = '<div class="loading-spinner">Loading...</div>';

  document.getElementById('footer').innerHTML = spinnerHTML;

  // Set up a retry mechanism for failed script fetches
  let retries = 0;
  setTimeout(() => {
    if (retries < 3) {
      loadScripts();
      retries++;
      setTimeout(() => displayLoadingSpinner(), 2000);
    }
  }, 1000);
}

// Initialize the application by loading scripts and displaying a loading spinner
loadScripts();
displayLoadingSpinner();
