use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use llvm_ir::IrBuilder;
use lexer::Lexer;
use parser::Parser;

fn generate_llvm_ir(directory: &str, output_file_name: &str, file_extension: &str) -> io::Result<()> {
    let mut ir_builder = IrBuilder::new();

    for entry in fs::read_dir(directory)? {
        let entry = entry?;

        if entry.path().extension() == Some(file_extension.parse()?){
            println!("Processing {}...", entry.path().display());

            let file_path = Path::new(entry.path());
            let mut file_contents = String::new();
            fs::File::open(file_path)?.read_to_string(&mut file_contents)?;

            let lexer = Lexer::new(&file_contents);
            let parser = Parser::new(lexer);

            match parser.parse_file(){
                Ok(nodes) => {
                    println!("Parsed nodes: {:?}", nodes);

                    for node in &nodes{
                        ir_builder.add_ir_node(node.clone());
                    }

                    if let Err(err) = ir_builder.build_and_validate(){
                        return Err(io::Error::new(io::ErrorKind::Other, err));
                    } else {
                        let output_file_path = Path::new(output_file_name);
                        fs::write(output_file_path, ir_builder.get_ir_code())?;
                        println!("Wrote LLVM IR code to {}", output_file_path.display());
                    }
                },
                Err(err) => return Err(io::Error::new(io::ErrorKind::Other, err)),
            }
        }
    }

    Ok(())
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    if args.len() != 4{
        eprintln!("Usage: {} <directory> <output_file_name> <file_extension>", args[0]);
        std::process::exit(1);
    }

    match generate_llvm_ir(&args[1], &args[2], &args[3]){
        Ok(_) => println!("LLVM IR generation successful"),
        Err(err) => eprintln!("Error: {}", err),
    };
}
