#include <json-c/json.h>
#include <stdbool.h>

bool verifyOAuth2Token(const char *tokenJson) {
    json_object *tokenObj = json_object_from_string(tokenJson);
    if (!tokenObj) return false;

    // Check "access_token" property
    json_object *accessToken = json_object_object_get(tokenObj, "access_token");
    if (!accessToken || !json_object_is_type(accessToken, json_type_string)) {
        json_object_put(tokenObj);
        return false;
    }
    size_t accessTokenLen = json_object_get_string_length(accessToken);
    if (accessTokenLen < 8) {
        json_object_put(tokenObj);
        return false;
    }

    // Check "expires_in" property
    json_object *expiresIn = json_object_object_get(tokenObj, "expires_in");
    if (!expiresIn || !json_object_is_type(expiresIn, json_type_integer)) {
        json_object_put(tokenObj);
        return false;
    }
    int expiresInVal = json_object_get_int(expiresIn);
    if (expiresInVal > 3600) {
        json_object_put(tokenObj);
        return false;
    }

    // Check "token_type" property
    json_object *tokenType = json_object_object_get(tokenObj, "token_type");
    if (!tokenType || !json_object_is_type(tokenType, json_type_string)) {
        json_object_put(tokenObj);
        return false;
    }
    const char *tokenTypeStr = json_object_get_string(tokenType);
    if (strcmp(tokenTypeStr, "Bearer") != 0) {
        json_object_put(tokenObj);
        return false;
    }

    // Check "refresh_token" property (if present)
    json_object *refreshToken = json_object_object_get(tokenObj, "refresh_token");
    if (refreshToken && !json_object_is_type(refreshToken, json_type_string)) {
        json_object_put(tokenObj);
        return false;
    }
    if (refreshToken) {
        size_t refreshTokenLen = json_object_get_string_length(refreshToken);
        if (refreshTokenLen < 16) {
            json_object_put(tokenObj);
            return false;
        }
    }

    json_object_put(tokenObj);
    return true;
}
