use std::fs;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::mpsc;
use std::thread;
use std::time;

use rustc_driver::{catch_with_exit_code, CompilerDriver};

struct Logger {
    log_file: PathBuf,
}

impl Drop for Logger {
    fn drop(&mut self) {
        if let Err(e) = fs::remove_file(self.log_file.clone()) {
            eprintln!("Error removing log file: {}", e);
        }
    }
}

fn init_logger(log_file: &Path) -> Result<Logger, ()> {
    Ok(Logger { log_file: log_file.to_path_buf() })
}

fn early_error<T>(e: T)
where
    T: std::fmt::Debug,
{
    println!("Error: {:?}", e);
}

lazy_static! {
    static ref LOG_FILE: SyncLazy<PathBuf, _> = SyncLazy::new(|| {
        let mut log_file = std::env::temp_dir().to_path_buf();
        log_file.push("rustc.log");
        Ok(log_file)
    });
}

fn compile_and_insert(
    source_code: &str,
    target_string: &str,
    replacement_string: &str,
    case_insensitive: bool,
) -> Result<(), String> {
    let mut logger = init_logger(LOG_FILE.read().unwrap()).unwrap();
    let log_path = LOG_FILE.read().unwrap().clone();

    let mut driver = CompilerDriver::new();
    driver.set_log_file(&log_path);

    if let Err(e) = catch_with_exit_code(driver, |driver| {
        let source_path = PathBuf::from("src");
        let source_file = source_path.join("main.rs");
        fs::write(source_file, source_code).unwrap();

        let mut input_data = Vec::new();
        for string in ["target_string".to_string(), "another_string".to_string()].into_iter() {
            if case_insensitive {
                match string.to_lowercase().find(target_string) {
                    Some(_) => break,
                    None => continue,
                }
            } else {
                match string.find(target_string) {
                    Some(_) => break,
                    None => continue,
                }
            }
        }

        input_data.push(replacement_string);
    }) {
        early_error(e);
        return Err(format!("Error: {}", e));
    }

    Ok(())
}
