#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <rapidjson/document.h>
#include <mutex>

class Node {
public:
    int key;
    std::string value;

    Node(int k, const std::string& v) : key(k), value(v) {}
};

class NodeArray {
private:
    std::vector<Node*> nodes;
    size_t capacity = 0;
    std::mutex mutex;

public:
    void resize(size_t newSize) {
        if (newSize > capacity) {
            capacity = newSize;
            nodes.resize(capacity);
        }
    }

    void addNode(int key, const std::string& value) {
        Node* node = new Node(key, value);
        nodes.push_back(node);
        resize(nodes.size());
    }

    void updateNode(int key, const std::string& value) {
        for (auto& node : nodes) {
            if (node->key == key) {
                node->value = value;
                return;
            }
        }
    }

    void removeNode(int key) {
        for (auto it = nodes.begin(); it != nodes.end();) {
            if ((*it)->key == key) {
                delete *it;
                it = nodes.erase(it);
            } else {
                ++it;
            }
        }
        resize(nodes.size());
    }

    std::string serialize() {
        rapidjson::Document doc(rapidjson::kObjectType);
        for (const auto& node : nodes) {
            rapidjson::Value valueNode;
            valueNode.SetObject();
            valueNode.AddMember("key", node->key, doc.GetAllocator());
            valueNode.AddMember("value", node->value.c_str(), doc.GetAllocator());
            doc.AddMember("nodes", valueNode, doc.GetAllocator());
        }
        return doc.StringBuffer().c_str();
    }

    void deserialize(const std::string& json) {
        rapidjson::Document doc;
        if (doc.Parse(json.c_str()).HasParseError()) {
            // Handle parsing error
        }
        for (const auto& node : doc["nodes"].GetArray()) {
            addNode(node["key"].GetInt(), node["value"].GetString());
        }
    }

    void logOperation(const std::string& operation) {
        // Implement logging system
    }
};

int main() {
    NodeArray array;
    array.deserialize("{\"nodes\":[{\"key\":1,\"value\":\"hello\"},{\"key\":2,\"value\":\"world\"}]}");
    array.addNode(3, "foo");
    array.updateNode(2, "bar");
    array.removeNode(1);
    std::cout << array.serialize() << std::endl;
    return 0;
}

