#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>

struct OctreeNode {
    // Node data (e.g., spatial points, bounding volume)
    std::vector<double> data;
    int capacity = 8; // Default node capacity

    bool isLeaf = false; // Is this a leaf node?
};

class Octree {
public:
    Octree(int maxCapacity) : maxCapacity_(maxCapacity), root_(nullptr), queueSize_(0) {}

    void init() {
        root_ = new OctreeNode();
        root_->isLeaf = true;
    }

    void insert(std::vector<double> point) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (queueSize_ > 0) {
            // Add to insertion queue, wait for availability
            queue_.push(point);
            cv_.wait(lock);
        } else {
            // Immediate insertion
            insertRecursive(root_, point);
        }
    }

    void remove(std::vector<double> point) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (queueSize_ > 0) {
            // Add to removal queue, wait for availability
            queue_.push(point);
            cv_.wait(lock);
        } else {
            // Immediate removal
            removeRecursive(root_, point);
        }
    }

    void rebalance() {
        std::thread rebalancer([this]() {
            while (true) {
                if (!queue_.empty()) {
                    // Process queued items, rebalance as needed
                    processQueue();
                } else {
                    // No pending operations, wait for changes
                    cv_.wait(std::chrono::milliseconds(100));
                }
            }
        });
    }

private:
    void insertRecursive(OctreeNode* node, std::vector<double> point) {
        if (node->isLeaf || node->data.size() >= node->capacity) {
            // Split or replace leaf node
            OctreeNode* newChild = new OctreeNode();
            newChild->isLeaf = true;
            node->data.push_back(point);
            node->children_.push_back(newChild);
        } else if (node->children_.empty()) {
            // Insert into existing children
            for (auto& child : node->children_) {
                if (child->isLeaf) {
                    if (std::abs((point[0] - child->data[0]) / 2) < 1e-6) {
                        // Point is inside, add to leaf
                        child->data.push_back(point);
                    } else if (std::abs((point[1] - child->data[1]) / 2) < 1e-6) {
                        // Point is inside, add to leaf
                        child->data.push_back(point);
                    } else if (std::abs((point[2] - child->data[2]) / 2) < 1e-6) {
                        // Point is inside, add to leaf
                        child->data.push_back(point);
                    }
                } else {
                    // Recursively insert into child
                    insertRecursive(child, point);
                }
            }
        } else {
            // Find the correct child for insertion
            if (std::abs((point[0] - node->children_[0]->data[0]) / 2) < 1e-6) {
                // Point is inside, add to leaf
                node->children_[0]->data.push_back(point);
            } else if (std::abs((point[1] - node->children_[1]->data[1]) / 2) < 1e-6) {
                // Point is inside, add to leaf
                node->children_[1]->data.push_back(point);
            } else if (std::abs((point[2] - node->children_[2]->data[2]) / 2) < 1e-6) {
                // Point is inside, add to leaf
                node->children_[2]->data.push_back(point);
            }
        }
    }

    void removeRecursive(OctreeNode* node, std::vector<double> point) {
        if (node->isLeaf) {
            // Remove from leaf node
            auto it = std::find_if(node->data.begin(), node->data.end(),
                [&point](const auto& p) { return p == point; });
            if (it != node->data.end()) {
                node->data.erase(it);
            }
        } else {
            // Find the correct child for removal
            if (std::abs((point[0] - node->children_[0]->data[0]) / 2) < 1e-6) {
                // Point is inside, remove from leaf
                node->children_[0]->data.push_back(point);
            } else if (std::abs((point[1] - node->children_[1]->data[1]) / 2) < 1e-6) {
                // Point is inside, add to leaf
                node->children_[1]->data.push_back(point);
            } else if (std::abs((point[2] - node->children_[2]->data[2]) / 2) < 1e-6) {
                // Point is inside, add to leaf
                node->children_[2]->data.push_back(point);
            }
        }
    }

    void processQueue() {
        while (!queue_.empty()) {
            std::vector<double> point = queue_.front();
            queue_.pop();
            if (point[0] > 1.5) {
                // Add to insertion queue, wait for availability
                queue_.push(point);
                cv_.notify_one();
            } else if (point[0] < -1.5) {
                // Add to removal queue, wait for availability
                queue_.push(point);
                cv_.notify_one();
            }
        }
    }

    int maxCapacity_;
    OctreeNode* root_;
    std::mutex mutex_;
    std::condition_variable cv_;
    std::queue<std::vector<double>> queue_;
};

int main() {
    // Initialize the octree
    Octree octree(8);
    octree.init();

    return 0;
}
