        with open(file_path, 'r') as f:
            if format == 'yaml':
                config = yaml.safe_load(f)
            elif format == 'json':
                config = json.load(f)
            else:
                raise ValueError(f"Unsupported format {format}")
            self.config_files[file_path] = config

    def load_api_gateway(self, api_gateway_url):
        self.api_gateway = api_gateway_url
        if not self.api_gateway:
            raise ValueError("API Gateway URL is required")

    def get_config(self, key, default=None):
        with self.lock:
            for file_path in self.config_files:
                config = self.config_files[file_path]
                if key in config:
                    return config[key]
        if default is None:
            return None
        return default

    def set_config(self, key, value):
        with self.lock:
            for file_path in list(self.config_files.keys()):
                config = self.config_files[file_path]
                if key in config:
                    config[key] = value
                    break
            else:
                raise KeyError(f"Key {key} not found")

    def save_config(self, file_path):
        with open(file_path, 'w') as f:
            if platform.system() == 'Windows':
                f.write(yaml.dump(self.config_files[file_path], allow_unicode=True).decode('utf-8'))
            else:
                f.write(yaml.dump(self.config_files[file_path], allow_unicode=True))

    def reload_config(self):
        self.config_files = {}
        for file_path in os.listdir():
            if file_path.endswith(('.yaml', '.yml', '.json')):
                self.load_config(file_path, 'yaml' if file_path.endswith('.yaml') else 'json')

    def run(self):
        while self.running:
            self.reload_config()
            time.sleep(1)

    def stop(self):
        self.running = False

if __name__ == '__main__':
    config_manager = ConfigManager()
    config_manager.load_config('config.yaml', 'yaml')
    config_manager.load_api_gateway('https://api.example.com')
    print(config_manager.get_config('key'))
    config_manager.set_config('key', 'value')
    config_manager.save_config('new_config.yaml')

