use {
    rustc_driver::CompilationJob,
    std::fs::{self, read_dir},
    std::path::{Path, PathBuf},
};

async fn compile_project(root_dir: &Path) -> Vec<(String, i32, f64, u64)> {
    let mut results = vec![];
    let num_cores = num_cpus::get();
    let max_memory = 0.8 * physical_memory::total().unwrap_or(1024);

    // Walk through the project directory and find all submodules
    for entry in walk_dir(root_dir) {
        if let Ok(submodule_dir) = entry {
            if submodule_dir.is_dir() && submodule_dir.join("Cargo.toml").is_file() {
                // Start a new compilation job for each submodule
                let mut job = CompilationJob::new(submodule_dir.to_path_buf());
                let start_time = std::time::Instant::now();
                match job.run().await {
                    Ok(exit_code) => {
                        let duration = start_time.elapsed().as_secs_f64();
                        let peak_rss = get_peak_rss(submodule_dir).unwrap_or(0);
                        results.push((submodule_dir.file_name().unwrap_or_default(), exit_code, duration, peak_rss));
                    }
                    Err(err) => {
                        // Log the error and report it to the CI/CD pipeline
                        log::error!("Error compiling {}: {}", submodule_dir.display(), err);
                        let start_time = std::time::Instant::now();
                        results.push((submodule_dir.file_name().unwrap_or_default(), -1, 0.0, 0));
                    }
                }
            }
        }
    }

    // Report compile results to the CI/CD pipeline and handle errors
    report_results(&results);

    results
}

async fn walk_dir(dir: &Path) -> Result<Box<dyn Iterator<Item = PathBuf>>, std::io::Error> {
    let entries = read_dir(dir)?;
    Ok(Box::new(entries.filter_map(|e| e.as_ok().map(|path| path.path_buf()))))
}

fn get_peak_rss(submodule_dir: &Path) -> Result<u64, std::io::Error> {
    use std::process::Command;

    let output = Command::new("pmap")
        .arg("-x")
        .arg(submodule_dir.to_str().unwrap())
        .output()?;

    let peak_rss_line = String::from_utf8_lossy(&output.stdout);
    for line in peak_rss_line.lines() {
        if line.contains("Peak RSS") {
            let parts: Vec<&str> = line.trim_start_matches(' ').trim_end_matches('\n').split_whitespace().collect();
            return Ok(parts[3].parse::<u64>().unwrap());
        }
    }

    Err(std::io::Error::new(std::io::ErrorKind::Other, "Failed to get peak RSS"))
}

fn report_results(results: &[(_, _, f64, u64)]) {
    // Send results to the CI/CD pipeline
    let url = "https://example.com/ci-cd-pipeline";
    let client = reqwest::blocking::Client::new();

    for result in results.iter() {
        match client.post(url).json_body(&serde_json::to_value(result)?).send() {
            Ok(_) => log::info!("Compile result reported to CI/CD pipeline"),
            Err(err) => log::error!("Error reporting compile result: {}", err),
        }
    }
}
