class Task {
public:
    int id;
    int priority;
    long deadline;
    void (*function)(void);
    Task* next;

    Task(int _id, int _priority, long _deadline, void (*_function)(void), Task* _next = nullptr) :
        id(_id), priority(_priority), deadline(_deadline), function(_function), next(_next) {}
};

class DynamicTaskScheduler {
public:
    class ConnectionPool {
    public:
        ~ConnectionPool() {
            for (auto& connection : connections) {
                delete connection;
            }
        }

        void seed(int numConnections) {
            poolSize = numConnections;
            connections.resize(numConnections);
            for (auto& connection : connections) {
                // Initialize database connection
            }
        }

        bool acquireConnection() {
            if (connections.empty()) {
                return false; // Pool exhausted
            }
            auto connection = connections.back();
            connections.pop_back();
            return true;
        }

        void releaseConnection(Task* task) {
            connections.push_back(task);
        }

        size_t getPoolSize() const { return poolSize; }
        size_t getIdleConnections() const { 
            // Count idle connections
        }

    private:
        size_t poolSize;
        std::vector<Task*> connections;

        ConnectionPool(const ConnectionPool&) = delete;
        ConnectionPool& operator=(const ConnectionPool&) = delete;
    };

private:
    std::list<Task*> tasks;
    ConnectionPool connectionPool;

public:
    DynamicTaskScheduler() : connectionPool() {}

    ~DynamicTaskScheduler() {
        for (auto& task : tasks) {
            // Free allocated memory
        }
    }

    void addTask(int id, int priority, long deadline, void (*function)(void)) {
        Task* newTask = new Task(id, priority, deadline, function);
        tasks.push_back(newTask);

        if (!connectionPool.acquireConnection()) {
            // Handle pool exhaustion error
        }

        newTask->next = &tasks.back();
        tasks.back().next = newTask;
    }

    void removeTask(int id) {
        for (auto& task : tasks) {
            if (task->id == id) {
                // Remove task from the list and free memory

                connectionPool.releaseConnection(task);
                return;
            }
        }
    }

    Task* getTask(int priority, long deadline) {
        for (auto& task : tasks) {
            if (task->priority <= priority && task->deadline >= deadline) {
                return task;
            }
        }
        return nullptr;
    }
};
