namespace MersenneTwisterGenerator
{
    class Program
    {
        static async Task Main(string[] args)
        {
            // Initialize the pool of connections to remote services
            var servicePool = new ServicePool();

            // Process CSV files provided via command-line parameters
            foreach (var file in args.Select(arg => Path.Combine(Directory.GetCurrentDirectory(), arg)))
            {
                if (!File.Exists(file))
                {
                    Console.WriteLine($"Error: File '{file}' not found.");
                    continue;
                }

                try
                {
                    await ProcessCsvFileAsync(file, servicePool);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error processing file '{file}': {ex.Message}");
                }
            }

            // Add new remote services to the pool with customizable ports and configurations
            if (args.Length > 1)
            {
                foreach (var arg in args.Skip(1))
                {
                    try
                    {
                        await servicePool.AddServiceAsync(arg);
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine($"Error adding site '{arg}': {ex.Message}");
                    }
                }
            }

            // Generate random number sequence using the Mersenne Twister algorithm
            var mt = new MersenneTwister();
            for (int i = 0; i < 100000000; i++)
            {
                Console.WriteLine(mt.NextDouble());
            }
        }

        static async Task ProcessCsvFileAsync(string file, ServicePool servicePool)
        {
            // Concurrently read and parse the CSV file
            await Task.WhenAll(
                from line in File.ReadLines(file)
                let record = line.Split(',')
                where record.Length > 1
                select servicePool.ProcessRecordAsync(record));
        }
    }

    public class ServicePool
    {
        private readonly List<Service> _services;

        public ServicePool()
        {
            _services = new List<Service>();
        }

        public async Task AddServiceAsync(string serviceName)
        {
            // Dynamically add a new remote service to the pool with customizable ports and configurations
            var service = new Service(serviceName);
            try
            {
                await service.ConnectAsync();
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error adding site '{serviceName}': {ex.Message}");
                return;
            }

            _services.Add(service);
        }

        public async Task ProcessRecordAsync(string[] record)
        {
            // Concurrently process each record in the CSV file
            await Task.WhenAll(
                from service in _services
                select service.ProcessRecordAsync(record));
        }
    }

