function reduceAsync(arr, initValue, callback) {
  let currentValue = initValue;
  const queue = arr.map((num, index) => {
    const promise = new Promise((resolve, reject) => {
      setTimeout(() => {
        try {
          currentValue = callback(currentValue, num);
          resolve();
        } catch (err) {
          reject(err);
        }
      }, 0);
    });
    return promise;
  });

  return Promise.all(queue).then(() => currentValue);
}

const numbers = [1, 2, 3, 4, 5];
const initialValue = 0;

reduceAsync(numbers, initialValue, (acc, current) => acc + current)
  .then((result) => console.log(result)) // Output: 15
  .catch((err) => console.error(err));
