                        // fetch from API or database and update cache
                        return fetchWeather(location, dateRange)
                                .map(result -> {
                                    weather.setCachedTimestamp(System.currentTimeMillis());
                                    return weather;
                                });
                    } else {
                        // use cached result
                        return Mono.just(weather);
                    }
                })
                .retryOnFailure();
    }

    private Mono<WeatherData> fetchWeather(String location, String dateRange) {
        // call OpenWeatherMap API or WeatherAPI
        return Mono.error(new Exception("API not implemented"));
    }

    private boolean isFresh(long cachedTimestamp) {
        // check if the cached result is fresh based on a predefined time interval
        return System.currentTimeMillis() - cachedTimestamp < 10000; // 10 seconds
    }
