Here's a sample Java-based microservice for managing weather data from a third-party API:

```java
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.commons.pool2.impl.GenericObjectPoolConfig;
import redis.clients.jedis.JedisPool;
import redis.clients.jedis.JedisPoolConfig;

public class WeatherMicroservice {

    // Caching configuration for in-memory caching
    private static final int CACHE_TTL = 3600; // 1 hour

    // Redis connection pool configuration
    private static final JedisPoolConfig REDIS_POOL_CONFIG = new GenericObjectPoolConfig();
    private static final String REDIS_HOST = "localhost";
    private static final int REDIS_PORT = 6379;

    // Third-party API connection configuration
    private static final String API_URL = "https://api.weather.com/forecast";
    private static final String API_KEY = "your_api_key";

    // WebSocket configuration for real-time updates
    private static final int WEB_SOCKET_PORT = 8081;
    private static final ServerSocket webSocketServer;

    static {
        try {
            webSocketServer = new ServerSocket(WEB_SOCKET_PORT);
        } catch (Exception e) {
            // Handle socket creation failure
        }
    }

    public WeatherMicroservice() {}

    public void start() {
        // Initialize caching framework for in-memory and Redis-based caching
        CacheManager cacheManager = new CacheManager();
        cacheManager.init(CACHE_TTL);

        // Initialize WebSocket server for real-time updates
        WebSocketServer webSocketServer = new WebSocketServer(webSocketServer);
        webSocketServer.start();

        // Start listening for API requests and update the cache accordingly
        startApiRequestListener();
    }

    private void startApiRequestListener() {
        // Set up the API request listener to handle incoming requests
        RestTemplate restTemplate = new RestTemplate();
        ResponseEntity<String> responseEntity;
        ObjectMapper mapper = new ObjectMapper();

        while (true) {
            try {
                // Send a GET request to the third-party API for weather data
                String apiResponse = restTemplate.getForObject(API_URL, String.class);

                // Parse the JSON response and update the cache with new data
                JsonNode jsonNode = mapper.readTree(apiResponse);
                cacheManager.updateCache(jsonNode);

                // Update WebSocket subscribers with the latest data
                webSocketServer.broadcastLatestData();

            } catch (Exception e) {
                // Handle API request failure, cache update failure, or WebSocket broadcasting failure
                log.error("Error updating cache and WebSocket subscribers: " + e.getMessage());
            }
        }
    }

    public void stop() {
        // Stop the caching framework
        cacheManager.stop();

        // Close the WebSocket server
        webSocketServer.stop();
    }
}
