```c
#include <semaphore.h>
#include <stdlib.h>
#include <pthread.h>

void* create_semaphore(int value) {
    // Create a semaphore with initial value 'value'
    sem_t *sem = (sem_t*) malloc(sizeof(sem_t));
    if (semctl(sem, 0, SETVAL, value) == -1) {
        free(sem);
        return NULL;
    }

    return sem;
}

void acquire_semaphore(void* sem) {
    // Acquire the semaphore
    sem_wait((sem_t*) sem);
}

void release_semaphore(void* sem) {
    // Release the semaphore
    sem_post((sem_t*) sem);
}

void destroy_semaphore(void* sem) {
    // Destroy the semaphore
    sem_close((sem_t*) sem);
    free(sem);
}

// Thread-safe function to log semaphore operations
void log_sem_operation(int op_type, void* sem) {
    pthread_mutex_lock(&log_mutex);  // Lock for thread safety
    // Log operation type and current value of the semaphore
    printf("Semaphore %p: %s (%d)\n", sem, op_type == 0 ? "Acquired" : "Released", *sem);
    pthread_mutex_unlock(&log_mutex);  // Unlock
}

// Mechanism to prevent semaphore starvations
void* acquire_semaphore_with_timeout(void* sem, int timeout) {
    struct timespec ts;
    ts.tv_sec = timeout / 1000;  // Convert milliseconds to seconds
    ts.tv_nsec = (timeout % 1000) * 1000000;  // Calculate remaining nanoseconds

    // Acquire the semaphore with a timeout
    if (sem_timedwait((sem_t*) sem, &ts) == -1) {
        return NULL;
    }

    return sem;
}

int main() {
    // Create multiple semaphores and manage their operations
    void* sem1 = create_semaphore(5);
    void* sem2 = create_semaphore(3);

    // Acquire and release semaphores, ensuring proper cleanup and error handling
    acquire_semaphore(sem1);
    release_semaphore(sem2);

    // Log semaphore operations for auditing purposes
    log_sem_operation(0, sem1);  // Acquired semaphore 1

    // Prevent semaphore starvations using timeouts
    void* sem = acquire_semaphore_with_timeout(sem1, 2000);  // Try to acquire semaphore 1 within 2 seconds
    if (sem == NULL) {
        printf("Timeout occurred. Semaphore starve prevented.\n");
    }

    // Destroy semaphores when no longer needed
    destroy_semaphore(sem1);
    destroy_semaphore(sem2);

    return 0;
}

