    std::condition_variable cv;

    for (const auto& test : testSuite) {
        // Initialize mocking library based on configurations from database
        auto mockLibrary = initializeMockingLibrary(resourceManager);

        {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait_for(lock, std::chrono::seconds(cooldown));
        }

        // Run the test in an isolated environment
        test(moduleLabel, &mockLibrary, resourceManager.getConfiguration());

        {
            std::unique_lock<std::mutex> lock(mtx);
            cv.notify_all();
        }

        // Reset and clean up mocking library using resource manager
        resetMockingLibrary(mockLibrary, resourceManager);

        if (testTimeout > 0) {
            // Wait for test to complete or timeout
            auto start = std::chrono::high_resolution_clock::now();
