char *appendSlashIfWithinLimit(const char *input, size_t sizeLimit) {
    size_t inputLength = strlen(input);
    if (input == NULL || sizeLimit == 0) return NULL;

    if (inputLength >= sizeLimit) {
        return NULL;
    }

    size_t newSize = inputLength + 1; // +1 for the added slash
    char *output = malloc(newSize);

    if (output == NULL) {
        return NULL;
    }

    memcpy(output, input, inputLength);
    output[inputLength] = '/';

    return output;
}
