        private async Task UpdatePageSectionAsync(string pageSectionId, string elementId, string updatedHtmlContent, string revisionComment)
        {
            // Ensure versioning integrity and optimistic concurrency control
            var previousVersion = await _distributedCache.GetPreviousVersion(pageSectionId, elementId);
            if (!previousVersion.Equals(_versioningScheme.GetLatestVersion()))
            {
                throw new Exception("Concurrent update detected. Please try again.");
            }

            // Store and update HTML content in distributed cache
            await _distributedCache.StoreAndUpdateHtmlContent(pageSectionId, elementId, updatedHtmlContent);

            // Track and manage revisions of HTML content changes
            if (revisionComment != null)
            {
                await _distributedCache.TrackRevision(pageSectionId, elementId, revisedHtmlContent: updatedHtmlContent, revisionComment: revisionComment);
