void modify_filename(const char *filename, struct configuration *config, int timeout) {
    char new_filename[1024];
    sprintf(new_filename, "%s_%d.%s", filename, config->num_digits, config->file_type);
    strcat(new_filename, ".txt");

    // Call external cloud storage API
    int retry_count = 0;
    while (1) {
        if (!store_file_in_cloud(new_filename)) {
            if (retry_count < config->max_retries) {
                usleep((int)(timeout * pow(2, retry_count)) + rand() % timeout);
                retry_count++;
            } else {
                LOG_ERROR("Failed to store file in cloud after %d retries", retry_count);
                return;
            }
        } else {
            break;
        }
    }
}
