    class SecureMersenneTwister {
    public:
        static std::mt19937_64 engine;

        SecureMersenneTwister(const std::string& seed)
            : seed_seq_(seed) {
            if (!engine) {
                // Initialize the random number generator only once
                engine = std::mt19937_64(seed_seq_);
            }
        }

        ~SecureMersenneTwister() {
            // No need to destroy the engine, it's already destroyed when the program exits
        }

        static double generateUniformRandom() {
            return std::uniform_real_distribution<double>(0.0, 1.0)(engine);
        }

        static double generateNormalDistributionRandom(double mean, double standardDeviation) {
            return std::normal_distribution<double>(mean, standardDeviation)(engine);
        }

    private:
        std::seed_seq seed_seq_;
    };
}
