function renderFooterScripts(scripts) {
  const cachedScripts = {};
  const loadingSpinner = document.getElementById('loading-spinner');
  let scriptsRendered = 0;

  function fetchScript(script, callback) {
    if (cachedScripts[script.key]) {
      return callback(cachedScripts[script.key].code);
    }

    const xhr = new XMLHttpRequest();
    xhr.open('GET', script.src, true);
    xhr.onload = () => {
      if (xhr.status === 200) {
        cachedScripts[script.key] = { code: xhr.responseText };
        callback(xhr.responseText);
      } else {
        console.error(`Failed to load script ${script.key} due to network error`);
      }
    };
    xhr.onerror = () => {
      console.error(`Failed to load script ${script.key} due to network error`);
    };
    xhr.ontimeout = () => {
      console.error(`Timeout while loading script ${script.key}`);
    };
    xhr.send();
  }

  function renderScript(script, code) {
    const scriptTag = document.createElement('script');
    scriptTag.src = `#${script.key}`;
    scriptTag.innerHTML = code;
    scriptTag.onload = () => {
      scriptsRendered++;
      if (scriptsRendered === scripts.length) {
        loadingSpinner.remove();
        callback(`Scripts loaded successfully`);
      }
    };
    scriptTag.onerror = () => {
      console.error(`Failed to load script ${script.key}`);
    };
    document.body.appendChild(scriptTag);
  }

  function renderFooter() {
    const footer = document.createElement('div');
    footer.innerHTML = '';
    for (const script of scripts) {
      if (!script.code || !script.type) {
        script.code = 'Unknown';
        script.type = 'text/javascript';
      }
      fetchScript(script, (code) => renderScript(script, code));
    }
  }

  function manageScripts() {
    const oldScripts = document.querySelectorAll('script[src^="#"]');
    for (const script of oldScripts) {
      if (!script.hasAttribute('data-loaded')) {
        setTimeout(() => {
          script.remove();
        }, 1000);
      } else {
        script.removeAttribute('data-loaded');
      }
    }
  }

  function loadScripts() {
    loadingSpinner.classList.add('visible');
    renderFooter();
    setTimeout(manageScripts, 2000); // after scripts are rendered
  }

  loadScripts();

  return `<!-- Scripts loaded successfully -->`;
}

