```javascript
import { readdir, stat } from 'fs/promises';
import { join } from 'path';
import * as logger from './logger';

const CONFIG_FILE_TYPES = ['.json', '.yaml'];
const DEFAULT_CONFIG = {};

async function readConfigFiles(directory) {
  const configFiles = await readdir(directory);
  const configObjects = [];

  for (const file of configFiles) {
    if (!file.endsWith(CONFIG_FILE_TYPES.join(''))) continue;
    try {
      const filePath = join(directory, file);
      const stats = await stat(filePath);
      if (!stats.isFile()) throw new Error(`Not a file: ${filePath}`);
      const config = await readConfigFile(filePath);
      configObjects.push(config);
    } catch (error) {
      logger.error(`Error reading ${file}: ${error.message}`);
    }
  }

  return configObjects;
}

async function readConfigFile(filePath) {
  try {
    const content = await fs.readFile(filePath, 'utf8');
    if (!content) throw new Error('Invalid file contents');

    const parsedContent = JSON.parse(content);
    if (Array.isArray(parsedContent)) {
      // Handle array of objects or values
      return parsedContent;
    }
    return { ...DEFAULT_CONFIG, ...parsedContent };
  } catch (error) {
    logger.error(`Error parsing ${filePath}: ${error.message}`);
    throw error;
  }
}

async function mergeConfigFiles(configFiles) {
  const configObject = {};

  for (const configFile of configFiles) {
    for (const key in configFile) {
      if (!configObject[key]) configObject[key] = configFile[key];
    }
  }

  return configObject;
}

export async function getConfigurations(directory, options = {}) {
  const configObjects = await readConfigFiles(directory);

  if (options.merge) {
    const mergedConfig = await mergeConfigFiles(configObjects);
    return mergedConfig;
  }
  return configObjects;
}
