function updateResource(
  resourceId: string,
  requestBody: any,
  requestedVersion?: number,
  lastModifiedTimestamp?: number
) {
  const currentResource = getResource(resourceId);
  if (!currentResource) return { status: 404, message: 'Resource not found' };

  // Check version number
  if (requestedVersion && requestedVersion !== currentResource.version) {
    return { status: 412, message: 'Precondition failed: incorrect version' };
  }

  // Check last modification timestamp
  if (lastModifiedTimestamp && lastModifiedTimestamp < currentResource.lastModified) {
    return { status: 409, message: 'Conflict: resource has been modified since last fetch' };
  }

  // Update the resource
  const updatedResource = { ...currentResource, ...requestBody };
  updatedResource.lastModified = Date.now();

  // Store the updated resource
  storeResource(resourceId, updatedResource);

  return { status: 200, message: 'Resource updated successfully' };
}

function deleteResource(resourceId: string, requestedVersion?: number) {
  const currentResource = getResource(resourceId);
  if (!currentResource) return { status: 404, message: 'Resource not found' };

  // Check version number
  if (requestedVersion && requestedVersion !== currentResource.version) {
    return { status: 412, message: 'Precondition failed: incorrect version' };
  }

  // Check last modification timestamp
  if (currentResource.lastModified > Date.now() - 1000) {
    return { status: 409, message: 'Conflict: resource has been modified since last fetch' };
  }

  // Delete the resource
  deleteResourceFromStorage(resourceId);

  return { status: 204, message: 'Resource deleted successfully' };
}
