using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using StackExchange.Redis;

public class FsaRunner
{
    public static List<string> GetReachableStates(string[] states, int stateSize, Fsa fsa, int startIndex)
    {
        var reachableStates = new HashSet<string>();
        var queue = new Queue<int>();

        queue.Enqueue(startIndex);
        reachableStates.Add(states[startIndex]);

        while (queue.Count > 0)
        {
            int currentStateIndex = queue.Dequeue();

            foreach (var nextTransition in fsa.Transitions[states[currentStateIndex]])
            {
                string nextStateName = nextTransition.Target;
                if (!reachableStates.Contains(nextStateName))
                {
                    queue.Enqueue(states.ToList().IndexOf(nextStateName));
                    reachableStates.Add(nextStateName);
                }
            }
        }

        return reachableStates.OrderBy(state => state).ToList();
    }

