using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using UnityEngine;

public class AdvancedCustomRandomGenerator : IDisposable
{
    private readonly Random _random = new Random();
    private static readonly object _syncLock = new object();

    public delegate double DistributionFunction(double min, double max);

    private Dictionary<string, (int, int)> _rangeLimits = new Dictionary<string, (int, int)>();
    private Dictionary<string, DistributionFunction> _distributionFunctions = new Dictionary<string, DistributionFunction>();

    public void Initialize(string configFile)
    {
        LoadConfigFile(configFile);
    }

    public (double, double)? GetRandomValueWithinRange(string rangeName, bool inclusive = true)
    {
        lock (_syncLock)
        {
            if (!_rangeLimits.ContainsKey(rangeName))
                throw new ArgumentException($"Invalid range: {rangeName}");

            var (min, max) = _rangeLimits[rangeName];
            if (inclusive)
                return (_random.NextDouble() * (max - min) + min, inclusive);

            return (_random.NextDouble() * (max - min), !inclusive);
        }
    }

    public (double, double)? GetRandomValueWithinRangeMultiDimensional(string rangeName, int dimensionCount, bool inclusive = true)
    {
        lock (_syncLock)
        {
            if (!_rangeLimits.ContainsKey(rangeName))
                throw new ArgumentException($"Invalid range: {rangeName}");

            var ranges = _rangeLimits[rangeName].ToArray();
            if (dimensionCount != ranges.Length)
                throw new ArgumentException($"Dimension count mismatch for range: {rangeName}");

            var values = new double[dimensionCount];
            for (int i = 0; i < dimensionCount; i++)
                values[i] = GetRandomValueWithinRange($"{rangeName}_{i}", inclusive).Value;

            return values;
        }
    }

    public void SetSeed(int seed)
    {
        _random.SetSeed(seed);
    }

    public int GetSeed()
    {
        return _random.GetSeed();
    }

    private void LoadConfigFile(string configFile)
    {
        if (!File.Exists(configFile))
            throw new FileNotFoundException($"Configuration file not found: {configFile}");

        var doc = XDocument.Load(configFile);

        foreach (XElement element in doc.Root.Elements("Range"))
        {
            string rangeName = element.Attribute("name").Value;
            int min, max;
            if (!int.TryParse(element.Attribute("min").Value, out min) || !int.TryParse(element.Attribute("max").Value, out max))
                throw new XmlException($"Invalid range configuration for {rangeName}");

            _rangeLimits.Add(rangeName, (min, max));
        }

        foreach (XElement element in doc.Root.Elements("Distribution"))
        {
            string distributionName = element.Attribute("name").Value;
            DistributionFunction func;
            if (!TryLoadDistributionFunction(element, out func))
                throw new XmlException($"Invalid distribution configuration for {distributionName}");

            _distributionFunctions.Add(distributionName, func);
        }
    }

    private bool TryLoadDistributionFunction(XElement element, out DistributionFunction func)
    {
        string distributionType = element.Attribute("type").Value;
        if (string.IsNullOrEmpty(distributionType))
            throw new XmlException("Missing 'type' attribute in distribution configuration");

        switch (distributionType)
        {
            case "uniform":
                func = (min, max) => _random.NextDouble() * (max - min) + min;
                break;
            default:
                throw new XmlException($"Unsupported distribution type: {distributionType}");
        }

        return true;
    }

    public void Dispose()
    {
        // Implement resource disposal logic here
    }
}
