const { Readable, Writable } = require('stream');
const { Buffer, EventEmitter } = require('events');

class DataAggregator {
  constructor(options) {
    this.options = options;
    this.sourceStreams = [];
    this.buffer = new Buffer();
    this.logEventEmitter = new EventEmitter();
  }

  addSourceStream(stream) {
    this.sourceStreams.push(stream);
    stream.on('data', (chunk) => this.aggregateChunk(chunk));
    stream.on('error', (err) => this.handleSourceError(err));
    stream.on('end', () => this.handleSourceEnd());
  }

  aggregateChunk(chunk) {
    const bufferLength = this.buffer.length;
    if (bufferLength + chunk.length > this.options.maxBufferLength) {
      this.resizeBuffer();
    }
    this.buffer.write(chunk);
  }

  resizeBuffer() {
    // Dynamically adjust buffer size based on memory usage and performance
    this.buffer = Buffer.alloc(this.options.maxBufferLength * 2);
  }

  handleSourceError(err) {
    console.error('Error in source stream:', err);
    this.sourceStreams = [];
  }

  handleSourceEnd() {
    if (this.sourceStreams.length === 0) {
      this.logEventEmitter.emit('all-streams-ended');
    }
  }

  writeDataToSink(writableStream) {
    writableStream.on('error', (err) => console.error('Error in sink:', err));
    writableStream.write(this.buffer);
  }

  logMetadata(logEventEmitter, data) {
    const { sourceId, byteRangeCopied, timestamp } = data;
    logEventEmitter.emit('metadata', { sourceId, byteRangeCopied, timestamp });
  }
}

module.exports = DataAggregator;
