<?php

function authenticateOAuth($provider, $username, $password) {
    // Load environment variables from .env file
    $dotenv = Dotenv::createImmutable(__DIR__);
    $dotenv->load();

    // Set provider-specific configuration
    $config = json_decode(file_get_contents('config/oauth.json'), true);

    if (!isset($config[$provider])) {
        throw new Exception("Invalid OAuth provider");
    }

    // Initialize OAuth client
    $client = new \League\OAuth2\Client\Provider/{$provider}(
        $config[$provider]['client_id'],
        $config[$provider]['client_secret'],
        $config[$provider]['redirect_uri']
    );

    try {
        // Authenticate user
        $authorizationUrl = $client->getAuthorizationUrl();
        $code = $_GET['code'];

        if (isset($_SESSION['oauth_access_token'])) {
            $token = $_SESSION['oauth_access_token'];
            $user = $client->getUserInfo($token);
            return $user;
        } else {
            // Handle authorization code
            $helper = new \League\OAuth2\Client\Provider\Helpers\AuthorizationCodeHelper();
            $params = $helper->getAccessTokenParams($authorizationUrl, $code);

            // Get access token
            $accessToken = $client->getToken($params);

            // Store access token securely in session variable
            $_SESSION['oauth_access_token'] = $accessToken;

            // Retrieve user information using access token
            $user = $client->getUserInfo($accessToken);

            return $user;
        }
    } catch (Exception $e) {
        // Log authentication attempt and error message
        logError('Authentication failed: ' . $e->getMessage());

        // Return error response
        http_response_code(401);
        echo json_encode(['error' => 'Invalid credentials']);
        exit();
    }
}

// Rate limiting function
function rateLimit($burstLimit) {
    // Check if request is from same IP address within a short period
    $ip = $_SERVER['REMOTE_ADDR'];
    $time = time();

    // Load previous requests from session variable
    $requests = &$_SESSION[$ip];

    if (!isset($requests[$time])) {
        $requests[$time] = 0;
    }

    if (++$requests[$time] > $burstLimit) {
        // Block request due to rate limiting
        http_response_code(429);
        echo json_encode(['error' => 'Rate limited']);
        exit();
    }
}

