function updateClinicStatus($clinicId, $newStatus, $lastModifiedIp, $lastModifiedDate) {
    // Validate the clinic ID
    if (!isValidClinicId($clinicId)) {
        return array('error' => 'Invalid clinic ID');
    }

    // Start a transaction
    dbTransactionStart();

    try {
        // Update the clinic status
        $query = "UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE id = ?";
        $stmt = dbPrepare($query);
        $stmt->execute(array($newStatus, $lastModifiedIp, $lastModifiedDate, $clinicId));

        // Commit the transaction
        dbTransactionCommit();
    } catch (Exception $e) {
        // Rollback the transaction on error
        dbTransactionRollback();

        // Log the error
        logError('Update clinic status failed: ' . $e->getMessage());

        return array('error' => 'Update clinic status failed');
    }
}

