@lru_cache(maxsize=None)
def get_hash_functions() -> List[HashFunction]:
    # C implementation for getting the list of available hash functions and ciphers
    hash_functions = []

    if hashlib.sha256 is not None:
        hash_functions.append(HashFunction("SHA-256"))
    if hashlib.sha384 is not None:
        hash_functions.append(HashFunction("SHA-384"))
    if hashlib.sha512 is not None:
        hash_functions.append(HashFunction("SHA-512"))
    if hashlib.md5 is not None:
        hash_functions.append(HashFunction("MD5"))

    return hash_functions

def get_block_ciphers() -> List[Dict[str, Tuple]]:
    block_ciphers = []

    # C implementation for getting the list of available block ciphers
    if hmac.new is not None and hashlib.sha256 is not None:
        block_ciphers.append({"name": "AES-256-CBC", "implementation": hmac.new})
    if hmac.new is not None and hashlib.sha384 is not None:
        block_ciphers.append({"name": "AES-256-CBC", "implementation": hmac.new})
    if hmac.new is not None and hashlib.sha512 is not None:
        block_ciphers.append({"name": "AES-256-CBC", "implementation": hmac.new})

    return block_ciphers

def create_directory(directory: str, retries: int = 3) -> bool:
    # Retry mechanism for creating a directory
    for _ in range(retries):
        try:
            os.makedirs(directory)
            return True
        except (FileExistsError, PermissionError, OSError) as e:
            logging.error(f"Failed to create directory '{directory}' due to error: {e}")

    return False

def remove_directory(directory: str) -> bool:
    # Remove a directory and its contents
    try:
        os.rmdir(directory)
        return True
    except (FileNotFoundError, PermissionError, OSError) as e:
        logging.error(f"Failed to remove directory '{directory}' due to error: {e}")

    return False

