namespace DynamicXmlManager
{
    public class DynamicXmlManager : IDynamicXmlManager
    {
        private readonly ILogger _logger;
        private readonly IOptions<XmlValidationSettings> _xmlValidationSettings;
        private readonly IXmlCache _xmlCache;
        private readonly IXsdValidator _xsdValidator;

        public DynamicXmlManager(ILogger<DynamicXmlManager> logger, 
            IOptions<XmlValidationSettings> xmlValidationSettings, 
            IXmlCache xmlCache, IXsdValidator xsdValidator)
        {
            _logger = logger;
            _xmlValidationSettings = xmlValidationSettings;
            _xmlCache = xmlCache;
            _xsdValidator = xsdValidator;
        }

        public async Task<string> ParseAndValidateAsync(string xmlData)
        {
            try
            {
                var xmlDoc = new XmlDocument();
                xmlDoc.LoadXml(xmlData);

                await ValidateXmlDocumentAsync(xmlDoc);
                return xmlData;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error parsing or validating XML");
                throw;
            }
        }

        private async Task ValidateXmlDocumentAsync(XmlDocument xmlDoc)
        {
            var xsdFile = _xmlValidationSettings.Value.XsdFilePath;
            if (!string.IsNullOrEmpty(xsdFile))
            {
                try
                {
                    using (var xsdStream = File.OpenRead(xsdFile))
                    {
                        var xsdDoc = new XmlSchema();
                        xsdDoc.SetXmlns(prefix: "xsd", namespaceUri: xsdFile);
                        _xsdValidator.Validate(xmlDoc, xsdDoc);
                    }
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error validating XML against XSD");
                }
            }

            await _xmlCache.AddAsync(xmlDoc);
        }
    }
}

