```rust
use {
    log::info,
    std::{
        collections::{HashMap, HashSet},
        fs,
        path::{Path, PathBuf},
        sync::atomic::{Ordering, AtomicUsize},
    },
};
use {
    js_sys::Function,
    web_sys::{JsModule, JsValue},
};

struct Context {
    modules: HashMap<String, JsModule>,
    execution_order: Vec<String>,
}

fn load_module(context: &mut Context, module_name: &str) -> Result<(), String> {
    let module_path = PathBuf::from(module_name);
    if !module_path.exists() {
        return Err("Module not found".to_string());
    }
    let module = JsModule::new(&module_path)?;
    context.modules.insert(module_name.to_string(), module);
    Ok(())
}

fn execute_modules(context: &Context) -> Result<(), String> {
    for module_name in &context.execution_order {
        if let Some(module) = context.modules.get(module_name) {
            let start_time = std::time::Instant::now();
            let result = module.execute()?;

            info!("Module {} executed in {:.2?}", module_name, start_time.elapsed());

            Ok(())
        } else {
            Err(format!("Module {} not found", module_name))
        }
    }
}

fn main() -> Result<(), String> {
    // Initialize logging system
    let log_level = "info";
    env_logger::builder()
        .filter_level(log_level.parse().unwrap())
        .try_init()
        .map_err(|e| format!("Failed to initialize logging: {}", e))?;

    // Load configuration file
    let config_path = PathBuf::from("config.json");
    if !config_path.exists() {
        return Err("Configuration file not found".to_string());
    }
    let config = serde_json::from_reader(config_path.read_to_string())?;
    let execution_order: Vec<String> = config["execution_order"].clone().try_into()?;
    let context = Context { modules: HashMap::new(), execution_order };

    // Load and execute modules
    for module_name in &context.execution_order {
        if let Err(err) = load_module(&mut context, module_name) {
            return Err(err);
        }
    }

    if let Err(err) = execute_modules(&context) {
        return Err(err);
    }

    Ok(())
}
