      }
    }
  }

  async executeModule(moduleName) {
    try {
      const moduleInstance = this.moduleInstances.get(moduleName);
      if (!moduleInstance) throw new Error(`Module ${moduleName} is not available`);
      await moduleInstance.execute();
    } catch (error) {
