#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <pthread.h>

#define MAX_CONCURRENT_DOWNLOADS 50
#define TIMEOUT 30
#define RETRY_INTERVAL 5

typedef struct {
    CURL *easy;
    FILE *filePointer;
} downloadContext;

void* downloadThread(void* context) {
    downloadContext* ctx = (downloadContext*)context;
    CURLcode res;

    do {
        res = curl_easy_perform(ctx->easy, NULL);

        if(CURLE_OK != res) {
            fprintf(stderr, "Error downloading file: %s\n", curl_easy_strerror(res));
        }

        if(NULL != ctx->filePointer) {
            fclose(ctx->filePointer);
            ctx->filePointer = NULL;
        }
    } while(CURLC_OK != res && 0 < --ctx->retryCount);

    free(ctx);
    return NULL;
}

int main(int argc, char** argv) {
    int concurrentDownloads = MAX_CONCURRENT_DOWNLOADS;
    char* inputDir = NULL;
    char* outputDir = NULL;
    int timeout = TIMEOUT;
    int retryInterval = RETRY_INTERVAL;

    // Parse command-line arguments
    for(int i = 1; i < argc; i++) {
        if(strcmp(argv[i], "-i") == 0) {
            inputDir = argv[++i];
        } else if(strcmp(argv[i], "-o") == 0) {
            outputDir = argv[++i];
        } else if(strcmp(argv[i], "-c") == 0) {
            concurrentDownloads = atoi(argv[++i]);
        } else if(strcmp(argv[i], "-t") == 0) {
            timeout = atoi(argv[++i]);
        } else if(strcmp(argv[i], "-r") == 0) {
            retryInterval = atoi(argv[++i]);
        }
    }

    // Initialize thread pool
    pthread_t threads[MAX_CONCURRENT_DOWNLOADS];
    downloadContext* contexts[MAX_CONCURRENT_DOWNLOADS];

    for(int i = 0; i < concurrentDownloads; i++) {
        CURL *easy = curl_easy_init();
        FILE *filePointer = fopen(outputDir, "wb");

        if(NULL == easy || NULL == filePointer) {
            fprintf(stderr, "Error initializing download context.\n");
            exit(1);
        }

        contexts[i] = (downloadContext*)malloc(sizeof(downloadContext));
        contexts[i].easy = easy;
        contexts[i].filePointer = filePointer;

        pthread_create(&threads[i], NULL, downloadThread, &contexts[i]);
    }

    // Wait for all downloads to complete
    for(int i = 0; i < concurrentDownloads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Log summary report of all downloads
    fprintf(stdout, "Summary Report:\n");

    return 0;
}

