class FetchAndFilterDynamicContent {
  constructor() {
    this.apiQueue = [];
    this.cache = {};
    this.rateLimit = 5; // adjust rate limit as needed
    this.maxConcurrentRequests = 3;
    this.activeRequests = 0;
    this.elementMetadataClient = null;
  }

  async fetchAndFilter(selector, elements, numElements, fsa) {
    if (!this.elementMetadataClient) {
      this.elementMetadataClient = await this.createApiClient();
    }

    const states = [];
    let currentState = fsa;

    for (let i = 0; i < numElements; i++) {
      const element = elements[i];
      const metadataPromise = this.fetchElementMetadata(element, selector);

      if (!this.activeRequests) {
        this.activeRequests++;
      }

      await metadataPromise.then((metadata) => {
        states.push({ ...currentState, ...metadata });
        currentState = { ...currentState, next: states.length - 1 };
      });

      if (this.activeRequests > 0) {
        await new Promise((resolve) => setTimeout(resolve, 100));
      }
    }

    this.activeRequests--;
    return states;
  }

  async createApiClient() {
    // implement API client creation logic here
    throw new Error("API client not implemented");
  }

  async fetchElementMetadata(element, selector) {
    const metadata = await this.cache[selector];
    if (metadata) {
      return metadata;
    }

    if (this.apiQueue.length >= this.rateLimit) {
      await new Promise((resolve) => setTimeout(resolve, 100));
    }

    this.apiQueue.push(this.elementMetadataClient.fetch(element, selector));

    while (this.apiQueue.length > this.maxConcurrentRequests) {
      await this.apiQueue.shift();
    }

    return await this.apiQueue.shift();
  }
}
