function extractOldTestamentBooks($text) {
    $logService = new LogService();
    $transactions = new Transactions();

    // Validate input text length against rate limiting rules
    if (strlen($text) > 5000 && !is_admin()) {
        return array('error' => 'Rate limit exceeded');
    }

    // Start transaction to ensure data integrity
    try {
        $transactions->start();

        // Extract book names using regular expressions
        preg_match_all('/(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)/i', $text, $matches);

        // Validate book names before proceeding
        if (empty($matches[0])) {
            return array('error' => 'No Old Testament books found');
        }

        // Extract and log book names with their occurrences
        $bookOccurrences = array();
        foreach ($matches[0] as $book) {
            if (!isset($bookOccurrences[$book])) {
                $bookOccurrences[$book] = 1;
            } else {
                $bookOccurrences[$book]++;
            }
            $logService->recordBookOccurrences($book, $bookOccurrences[$book], get_current_user_id());
        }

        // Commit transaction to ensure data integrity
        try {
            $transactions->commit();
        } catch (Exception $e) {
            // Revert changes and log the failure
            $transactions->rollback();
            $logService->recordFailure('Book extraction failed', get_current_user_id());
            return array('error' => 'Failed to extract books');
        }

        return $bookOccurrences;
    } catch (Exception $e) {
        // Handle any unexpected exceptions and log the failure
        $transactions->rollback();
        $logService->recordFailure('Unexpected error occurred', get_current_user_id());
        return array('error' => 'An error occurred while extracting books');
    }
}

class LogService {
    public function recordBookOccurrences($book, $occurrences, $userId) {}
    public function recordFailure($message, $userId) {}
}

