#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <stdbool.h>

struct Record {
    int key;
    int value1;
    int value2;
};

long* offsets;
int* keys;
struct Record** records;

void generateRandomKeys(int min, int max, int count) {
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        while (true) {
            int randomKey = rand() % ((max - min) + 1) + min;
            bool unique = true;
            for (int j = 0; j < i; j++) {
                if (randomKey == keys[j]) {
                    unique = false;
                    break;
                }
            }
            if (unique) {
                keys[i] = randomKey;
                break;
            }
        }
    }
}

void* allocateArray(size_t size, int count) {
    void* arr = malloc(size * count);
    if (!arr) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    return arr;
}

void initArrays(int recordCount, int minKey, int maxKey) {
    offsets = allocateArray(sizeof(long), recordCount);
    keys = allocateArray(sizeof(int), recordCount);
    records = allocateArray(sizeof(struct Record*), recordCount);

    for (int i = 0; i < recordCount; i++) {
        struct Record* record = malloc(sizeof(struct Record));
        if (!record) {
            fprintf(stderr, "Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }
        record->key = keys[i];
        // Initialize other fields of the record
        record->value1 = 0;
        record->value2 = 0;
        records[i] = record;
    }
}

void freeArrays() {
    for (int i = 0; i < recordCount; i++) {
        free(records[i]);
    }
    free(keys);
    free(offsets);
}
