    // Initialize the cipher context and set its block size
    AES_CTX* aes_ctx = AES_new();
    if (!aes_ctx) {
        ERR_error_fp(stderr, "Error initializing AES context\n");
        return NULL;
    }
    AES_set_encrypt_key(password, key_length / 8, &aes_ctx->key);

    // Derive the initialization vector (IV) from the password
    unsigned char* iv = OPENSSL_malloc(16); // IV length is 128 bits (16 bytes)
    SHA256_CTX sha256_ctx;
    SHA256_Init(&sha256_ctx);
    SHA256_Update(&sha256_ctx, password, strlen(password));
    SHA256_Final(iv, &sha256_ctx);

    // Set the IV for the AES cipher
    AES_set_iv(aes_ctx, iv, 16);

    // Clean up and disable the cipher when no longer needed
    void* cipher_ptr = aes_ctx;
    AES_free(aes_ctx);

    return cipher_ptr;
}

void cleanup_cipher(void* cipher) {
    if (cipher) {
        AES_CTX* aes_ctx = cipher;
        AES_free(aes_ctx);
    }
}
