use std::fs;
use std::time::{Duration, Instant};
use std::process::Command;

fn traverse_dag(dir: &str, graph: &HashMap<String, Vec<String>>) -> Vec<(String, usize)> {
    let mut visited = HashSet::new();
    let mut stack = Vec::new();
    let mut result = Vec::new();
    let now = Instant::now();

    fn dfs(graph: &HashMap<String, Vec<String>>, node: &str, visited: &mut HashSet<String>, stack: &mut Vec<String>, max_depth: usize) -> bool {
        if !visited.insert(node.to_string()) {
            println!("Cycle detected for task {}", node);
            return false;
        }

        let mut depth = 1;
        while let Some(parent) = stack.last() {
            if parent == node {
                break;
            }
            depth += 1;
        }

        if depth > max_depth {
            println!("Max execution depth exceeded for task {}", node);
            return false;
        }

        for &child in graph.get(node).unwrap_or(&vec![]) {
            if !dfs(graph, child.as_str(), visited, stack, max_depth) {
                return false;
            }
        }

        stack.pop();
        true
    }

    let mut initial_task = "".to_string();

    // initialize the cache with empty values for repeated queries
    let cache = HashMap::new();

    fn execute_task(dir: &str, task: &str) -> Result<(), Box<dyn std::error::Error>> {
        Command::new("task-runner")
            .arg(task)
            .current_dir(dir)
            .output()
            .map_err(|e| e.to_string())?;
        Ok(())
    }

    let mut total_time = Duration::from_secs(0);
    let mut mem_usage = 0;

    for (task, _) in &graph {
        if task == initial_task.as_str() {
            stack.push(task);
            visited.clear();
            while let Some(node) = stack.pop() {
                if !visited.insert(node.to_string()) {
                    println!("Cycle detected for task {}", node);
                } else {
                    for &child in graph.get(node).unwrap_or(&vec![]) {
                        stack.push(child.as_str());
                    }
                }
            }

            // retrieve metadata and commit message
            let mut project_api = ProjectManagementAPI::new(dir);
            let task_metadata = project_api.get_task_metadata(task)?;

            // install custom logging hook using SyncLazy
            install_logging_hook();

            for (node, depth) in graph {
                if !visited.contains(&node.to_string()) {
                    continue;
                }

                if dfs(graph, &node, visited, stack.as_mut(), 3) {
                    result.push((node.clone(), depth));
                }
            }

            // measure traversal time and memory usage
            total_time += now.elapsed();
            mem_usage = get_resident_set_size() as usize;

            println!("Traversal complete! Total time: {} ms, Memory used: {} MB", total_time.as_millis(), mem_usage);
        }
    }

    Ok(())
}

fn install_logging_hook() {
    let mut log_file = fs::File::create("log.txt").unwrap();
    let log_writer = sync_laziness::SyncLazy(move || {
        |msg| {
            writeln!(log_file, "{}", msg).unwrap();
        }
    });
}
