import os
import re
import argparse
from collections import Counter
import multiprocessing
from tqdm import tqdm
import zipfile
import requests

def process_file(file_path):
    try:
        if not os.path.isfile(file_path):
            return None

        file_type = os.path.splitext(file_path)[1][1:]

        if args.exclude and file_type in args.exclude:
            return None

        total_lines = 0
        total_words = 0
        total_chars = 0

        with open(file_path, 'r') as f:
            for line in f:
                total_lines += 1
                words = re.findall(r'\b\w+\b', line)
                total_words += len(words)
                total_chars += len(line)

        return {
            'lines': total_lines,
            'words': total_words,
            'chars': total_chars,
            'file_type': file_type
        }

    except Exception as e:
        print(f"Error processing {file_path}: {e}")

def process_directory(dir_path):
    if not os.path.exists(dir_path):
        return None

    files = []
    processes = []

    for root, dirs, filenames in os.walk(dir_path):
        for filename in filenames:
            file_path = os.path.join(root, filename)
            files.append(file_path)

            if len(files) % 100 == 0 and args.num_processes > 1:
                p = multiprocessing.Process(target=process_files_in_pool, args=(files,))
                processes.append(p)
                p.start()
                files = []

    if len(files):
        process_files_in_pool(files)

    for p in processes:
        p.join()

def process_files_in_pool(files):
    with multiprocessing.Pool(processes=args.num_processes) as pool:
        results = list(tqdm(pool.map(process_file, files), total=len(files)))

    file_stats = {}
    for result in results:
        if result:
            file_stats[result['file_type']] = file_stats.get(result['file_type'], 0) + 1
            file_stats['total_lines'] += result['lines']
            file_stats['total_words'] += result['words']
            file_stats['total_chars'] += result['chars']

    return file_stats

def compress_data(file_stats):
    if len(file_stats) < args.threshold:
        return None

    zip_file_path = 'output.zip' if not args.output else args.output
    with zipfile.ZipFile(zip_file_path, 'w') as zip_file:
        for file_type, count in file_stats.items():
            data = f"{file_type}:{count}\n"
            zip_file.writestr(file_type, data)

    return zip_file_path

def upload_to_cloud(zip_file_path):
    if not zip_file_path:
        return None

    cloud_storage_url = 'https://cloud-storage.example.com/upload'
    with requests.get(cloud_storage_url) as response:
        if response.status_code == 200:
            with open(zip_file_path, 'rb') as f:
                files = {'file': f}
                response = requests.post(cloud_storage_url, files=files)
                if response.status_code == 201:
                    print(f"Zip file uploaded successfully to {cloud_storage_url}")
                else:
                    print(f"Error uploading zip file: {response.text}")
        else:
            print(f"Error connecting to cloud storage: {response.text}")

if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('dir_path', help='Path to the directory')
    parser.add_argument('-e', '--exclude', type=str, nargs='+', help='Exclude specific file types')
    parser.add_argument('-t', '--threshold', type=int, default=100, help='Threshold for compressing data')
    parser.add_argument('-o', '--output', type=str, help='Output file path for the ZIP archive')
    parser.add_argument('-n', '--num_processes', type=int, default=1, help='Number of processes to use for processing files')
    args = parser.parse_args()

    dir_path = args.dir_path
    file_stats = process_directory(dir_path)

    if file_stats:
        compressed_data = compress_data(file_stats)
        upload_to_cloud(compressed_data)

    else:
        print("No data processed. Exiting.")
