import time
from functools import wraps
from flask import request, jsonify
from redis import Redis
from aioredis import from_url

def retry(max_attempts=3):
    def decorator(func):
        @wraps(func)
        async def wrapper(*args, **kwargs):
            for attempt in range(1, max_attempts + 1):
                try:
                    return await func(*args, **kwargs)
                except Exception as e:
                    if attempt < max_attempts:
                        time.sleep(0.5)  # wait before retrying
                    else:
                        raise e
        return wrapper
    return decorator

def rate_limited(limit=10):
    def decorator(func):
        @wraps(func)
        async def wrapper(*args, **kwargs):
            redis = Redis.from_url('redis://localhost:6379/0')
            key = 'rate_limit'
            if not redis.get(key):
                redis.set(key, time.time() + 60 / limit)  # set rate limit

            current_time = time.time()
            stored_time = float(redis.get(key))

            if current_time > stored_time:
                redis.set(key, current_time + 60 / limit)
                await func(*args, **kwargs)
            else:
                time.sleep((stored_time - current_time) * (1 - (current_time % 60)) / 60)  # wait before retrying

        return wrapper
    return decorator

@retry(max_attempts=5)
@rate_limited(limit=10)
