function dynamicFooterRenderer(footerScripts) {
  const scriptElements = [];
  const cache = {};
  const loadingSpinner = document.getElementById('loading-spinner');

  async function fetchScripts() {
    try {
      const response = await fetch('/api/scripts');
      const scriptsData = await response.json();
      return scriptsData;
    } catch (error) {
      console.error('Error fetching scripts:', error);
      return [];
    }
  }

  async function manageCache(scripts) {
    for (const script of scripts) {
      const { url, version, timestamp } = script;
      if (!cache[url]) {
        cache[url] = { version, timestamp };
      } else if (timestamp > cache[url].timestamp || version > cache[url].version) {
        // Cache needs to be invalidated
        delete cache[url];
      }
    }
  }

  async function renderScripts() {
    try {
      const scriptsData = await fetchScripts();
      await manageCache(scriptsData);
      for (const script of scriptsData) {
        const scriptElement = document.createElement('script');
        scriptElement.src = script.url;
        scriptElement.innerHTML = `key-${script.id}`;
        scriptElements.push(scriptElement);
      }
      // Execute scripts in order
      for (let i = 0; i < scriptElements.length; i++) {
        await new Promise((resolve) => setTimeout(() => resolve(), 100));
        const script = scriptElements[i];
        document.body.appendChild(script);
        await script.onload;
        document.body.removeChild(script);
      }
    } catch (error) {
      console.error('Error rendering scripts:', error);
    } finally {
      loadingSpinner.remove();
    }
  }

  renderScripts();
}

// Example usage:
