#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void dynamicFileNameUpdate(char* filename, char* fileType, int version) {
    int maxLen = 255; // Maximum filename length
    int len = strlen(filename);

    if (len + strlen(fileType) + strlen(".v") + itoa(version) > maxLen) {
        printf("Error: Filename exceeds maximum length.\n");
        return;
    }

    char updatedFilename[maxLen];

    if (!strchr(filename, '.')) {
        // Add file type to filename
        sprintf(updatedFilename, "%s.%s", filename, fileType);
    } else {
        updatedFilename[len] = 0; // Null-terminate existing filename
        strcat(updatedFilename, "."); // Add dot before versioning info
        itoa(version, (char*) &updatedFilename[len + 1], 10);
    }

    printf("Updated filename: %s\n", updatedFilename);
}
