def rate_limited(max_requests_per_minute):
    def decorator(func):
        rate = 0
        last_request_time = time.time()

        @wraps(func)
        async def wrapper(*args, **kwargs):
            nonlocal rate, last_request_time

            current_time = time.time()
            if current_time - last_request_time >= 60:
                rate = 1
                last_request_time = current_time
            else:
                rate += 1
                if rate > max_requests_per_minute / 60:
                    await websocket.send(f"Rate limit exceeded. Wait for {max_requests_per_minute / 60} seconds")
                    return

            await func(*args, **kwargs)

        return wrapper

    return decorator

