#include <openssl/aes.h>
#include <openssl/err.h>
#include <openssl/hmac.h>
#include <string.h>

struct aes_ctx {
    EVP_CIPHER_CTX *ctx;
    uint8_t *key;
    size_t key_len;
    uint8_t *iv;
    size_t iv_len;
};

void aes_ctx_free(struct aes_ctx *ctx) {
    if (!ctx)
        return;
    EVP_CIPHER_CTX_free(ctx->ctx);
    OPENSSL_cleanse(ctx->key, ctx->key_len);
    OPENSSL_cleanse(ctx->iv, ctx->iv_len);
    free(ctx->key);
    free(ctx->iv);
    free(ctx);
}

int aes_init_from_password(struct aes_ctx **ctx_p, const char *password, size_t password_len) {
    if (!password || !password_len)
        return -1;

    *ctx_p = malloc(sizeof(struct aes_ctx));
    if (!(*ctx_p))
        return -1;

    (*ctx_p)->key = malloc(32);
    if (!(*ctx_p)->key)
        return -1;

    (*ctx_p)->iv = malloc(16);
    if (!(*ctx_p)->iv)
        return -1;

    EVP_PWHKey(password, password_len, (*ctx_p)->key, 32);
    (*ctx_p)->key_len = 32;

    EVP_BytesToKey(EVP_aes_256_cbc(), NULL, NULL, (*ctx_p)->key, 32, 64, (*ctx_p)->iv, 16);
    (*ctx_p)->iv_len = 16;

    (*ctx_p)->ctx = EVP_CIPHER_CTX_new();
    if (!(*ctx_p)->ctx)
        return -1;

    EVP_CIPHER_CTX_set_key_length((*ctx_p)->ctx, 32);
    EVP_CIPHER_CTX_set_iv_length((*ctx_p)->ctx, 16);

    return 0;
}

int aes_set_nonce(struct aes_ctx *ctx, const uint8_t *nonce, size_t nonce_len) {
    if (!ctx || !nonce || !nonce_len)
        return -1;
    EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_SET_IV_IN_PLACE, nonce_len, nonce);
    return 0;
}

int aes_set_tag(struct aes_ctx *ctx, const uint8_t *tag, size_t tag_len) {
    if (!ctx || !tag || !tag_len)
        return -1;
    EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_SET_TAG_IN_PLACE, tag_len, tag);
    return 0;
}

int aes_encrypt(struct aes_ctx *ctx, const uint8_t *plaintext, size_t plaintext_len, uint8_t **ciphertext_p, size_t *ciphertext_len_p) {
    if (!ctx || !plaintext || !plaintext_len)
        return -1;

    int result = EVP_CipherUpdate(ctx->ctx, (uint8_t *)*ciphertext_p, ciphertext_len_p, plaintext, plaintext_len);
    if (result <= 0)
        return -1;

    return 0;
}

int aes_decrypt(struct aes_ctx *ctx, const uint8_t *ciphertext, size_t ciphertext_len, uint8_t **plaintext_p, size_t *plaintext_len_p) {
    if (!ctx || !ciphertext || !ciphertext_len)
        return -1;

    int result = EVP_CipherUpdate(ctx->ctx, (uint8_t *)*plaintext_p, plaintext_len_p, ciphertext, ciphertext_len);
    if (result <= 0)
        return -1;

    return 0;
}

int aes_generate_tag(struct aes_ctx *ctx, const uint8_t *data, size_t data_len, uint8_t **tag_p, size_t *tag_len_p) {
    if (!ctx || !data || !data_len)
        return -1;

    int result = EVP_CipherFinal(ctx->ctx, (uint8_t *)*tag_p, tag_len_p);
    if (result <= 0)
        return -1;

    return 0;
}

int aes_verify_tag(struct aes_ctx *ctx, const uint8_t *data, size_t data_len, const uint8_t *tag, size_t tag_len) {
    if (!ctx || !data || !data_len || !tag || !tag_len)
        return -1;

    int result = EVP_CipherFinal(ctx->ctx, NULL, NULL);
    if (result <= 0)
        return -1;

    if (EVP_CIPHER_CTX_needs_flushing(ctx->ctx))
        return -1;

    return 0;
}

