import logging
import os
import time
from kubernetes import client, config
import socket
import retrying

class LogInitializer:
    def __init__(self):
        self.config = None
        self.log_dir = None
        self.log_level = None
        self.log_format = None

    @retrying.retry(wait_exponential_multiplier=1000)
    def initialize(self, config_file=None, log_level='INFO', log_format=None):
        if not config_file:
            config.load_kubeconfig()
        else:
            config.load_kubeconfig(config_file)

        v1core_client = client.V1Client()
        pods = v1core_client.list_pod_for_all_namespaces()

        self.log_dir = os.path.join('/var/log', 'app')
        if not os.path.exists(self.log_dir):
            os.makedirs(self.log_dir, exist_ok=True)

        logging.basicConfig(
            filename=os.path.join(self.log_dir, 'app.log'),
            level=getattr(logging, log_level.upper()),
            format=log_format or '%(asctime)s - %(name)s - %(levelname)s - %(message)s'
        )

        try:
            self.config = client.V1ConfigMap('logging-config')
            if not self.config.get_data():
                logging.error('Failed to retrieve configmap data')
                return
            self.log_level = self.config.get_data()['log-level']
            self.log_format = self.config.get_data().get('log-format', '%(asctime)s - %(name)s - %(levelname)s - %(message)s')

        except Exception as e:
            logging.error(f'Failed to retrieve configmap data: {str(e)}')

    def rotate_log_file(self):
        if not os.path.exists(self.log_dir):
            return

        log_files = [f for f in os.listdir(self.log_dir) if f.startswith('app.log')]

        for file in log_files:
            file_path = os.path.join(self.log_dir, file)
            if os.path.getsize(file_path) > 1048576 or time.time() - os.path.getmtime(file_path) > 604800:  # 1 week
                logging.info(f'Removing old log file: {file}')
                os.remove(file_path)

    def cleanup(self):
        for root, dirs, files in os.walk(self.log_dir):
            for f in files:
                if not all([f.startswith('app.log')]):
                    os.remove(os.path.join(root, f))
