```cpp
#include <iostream>
#include <memory>
#include <queue>
#include <vector>

class DynamicOctreeSpatialPartitioner {
public:
    DynamicOctreeSpatialPartitioner(int initialCapacity, int maxLeafNodes);
    void initialize();
    void addDataPoint(float x, float y, float z);
    std::vector<std::pair<float, float>> queryRegion(float minx, float miny, float minz, float maxx, float maxy, float maxz);

private:
    struct OctreeNode {
        bool isLeaf;
        std::unique_ptr<OctreeNode> children[8];
        int dataPointsCount;

        // Initialize octree node
        OctreeNode(int capacity) : isLeaf(true), dataPointsCount(0) {}

        ~OctreeNode() {
            for (int i = 0; i < 8; ++i) {
                if (children[i]) children[i]->~OctreeNode();
            }
        }
    };

    std::unique_ptr<OctreeNode> root;
};

// Initialize octree
void DynamicOctreeSpatialPartitioner::initialize() {
    // Create initial octree node
    root = std::make_unique<OctreeNode>(1000);
}

// Add data point to octree
void DynamicOctreeSpatialPartitioner::addDataPoint(float x, float y, float z) {
    // Traverse the octree and insert data point into the leaf node
    auto current = &root;
    while (!current->isLeaf && (x > current->children[0]->min.x || y > current->children[0]->min.y || z > current->children[0]->min.z)) {
        int idx = 0;
        if (x <= current->children[idx].get()->max.x) {
            if (y <= current->children[idx].get()->max.y) {
                if (z <= current->children[idx].get()->max.z) {
                    idx++;
                }
            } else if (z > current->children[idx].get()->min.z && z <= current->children[idx + 1].get()->max.z) {
                idx = (idx == 7 ? 0 : idx + 1);
            } else {
                // Not a valid insertion point, prune the octree
                return;
            }
        } else if (y > current->children[6]->min.y && z <= current->children[6].get()->max.z) {
            current = &current->children[7];
        } else {
            // Not a valid insertion point, prune the octree
            return;
        }
    }

    // Insert data point into the leaf node
    if (!current->isLeaf) {
        current->isLeaf = true;
    }
}

// Query region from the octree
std::vector<std::pair<float, float>> DynamicOctreeSpatialPartitioner::queryRegion(float minx, float miny, float minz, float maxx, float maxy, float maxz) {
    std::vector<std::pair<float, float>> result;
    auto current = &root;
    while (current->isLeaf || (!minx <= current->children[0]->min.x && !miny <= current->children[0]->min.y && !minz <= current->children[0]->min.z)) {
        if (minx > current->children[0].get()->max.x || miny > current->children[0].get()->max.y || minz > current->children[0].get()->max.z) {
            // Prune the octree
            return result;
        }
        int idx = 0;
        if (minx <= current->children[idx].get()->max.x) {
            if (miny <= current->children[idx].get()->max.y) {
                if (minz <= current->children[idx].get()->max.z) {
                    idx++;
                }
            } else if (minz > current->children[idx].get()->min.z && minz <= current->children[idx + 1].get()->max.z) {
                idx = (idx == 7 ? 0 : idx + 1);
            } else {
                // Prune the octree
                return result;
            }
        } else if (miny > current->children[6]->min.y && minz <= current->children[6].get()->max.z) {
            current = &current->children[7];
        } else {
            // Prune the octree
            return result;
        }

        for (int i = 0; i < 8; ++i) {
            if (!current->children[i]->isLeaf && minx <= current->children[i].get()->max.x && miny <= current->children[i].get()->max.y && minz <= current->children[i].get()->max.z) {
                // Traverse the child nodes
                result.insert(result.end(), queryRegion(current->children[i].get()->min.x, current->children[i].get()->min.y, current->children[i].get()->min.z,
                    current->children[i].get()->max.x, current->children[i].get()->max.y, current->children[i].get()->max.z));
            }
        }
    }

    // Return data points within the query region
    return result;
}

// Constructor for DynamicOctreeSpatialPartitioner
DynamicOctreeSpatialPartitioner::DynamicOctreeSpatialPartitioner(int initialCapacity, int maxLeafNodes)
    : root(std::make_unique<OctreeNode>(initialCapacity)) {}
