```javascript
function FindElementsBySelector(node, selector, callback) {
    const results = [];
    let queue = [node];

    while (queue.length > 0) {
        const current = queue.shift();
        for (let child of Array.from(current.children)) {
            queue.push(child);
        }

        if (current.classList && callback(current.classList.value, current)) {
            results.push(current);
        } else if (callback(current.id, current)) {
            results.push(current);
        }
    }

    return results;
}
