namespace CSharpAESDecryptionService
{
    public class DecryptionService
    {
        private readonly HttpClient _httpClient;
        private readonly ILogger<DecryptionService> _logger;
        private readonly IConfigProvider _configProvider;

        public DecryptionService(HttpClient httpClient, ILogger<DecryptionService> logger, IConfigProvider configProvider)
        {
            _httpClient = httpClient;
            _logger = logger;
            _configProvider = configProvider;
        }

        public async Task<string> DecryptCiphertextAsync(byte[] ciphertext, byte[] key, byte[] iv)
        {
            // Validate provided keys and IVs
            if (!ValidateKeyAndIV(key, iv))
            {
                throw new ArgumentException("Invalid key or IV");
