const fs = require('fs');
const path = require('path');
const childProcess = require('child_process');
const os = require('os');

// Module configuration file
const config = JSON.parse(fs.readFileSync('config.json'));

// Load modules dynamically
let modules = {};
Object.keys(config).forEach((module) => {
  try {
    const modulePath = path.join(__dirname, `modules/${module}.js`);
    modules[module] = require(modulePath);
  } catch (err) {
    console.error(`Error loading module ${module}:`, err);
  }
});

// Asynchronous reduction function
async function reduce(data, start, end, callback) {
  const concurrencyLevel = Math.floor(os.cpus().length / 2);
  const pool = childProcess.pool(concurrencyLevel);

  async function processChunk(chunkStart, chunkEnd) {
    const chunkSize = (chunkEnd - chunkStart) + 1;
    const chunkData = data.slice(chunkStart, chunkEnd + 1);

    try {
      // Perform reduction on the current chunk
      const result = await modules['reduction'].reduce(chunkData);
      callback(null, result);
    } catch (err) {
      callback(err);
    }
  }

  for (let i = start; i < end; i += concurrencyLevel) {
    pool.queue(processChunk.bind(this, i, Math.min(i + concurrencyLevel - 1, end)));
  }

  // Wait until all chunks are processed
  await pool.close();
}

// TIFF parsing C function
const tiffParser = childProcess.exec('tiff-parser');

function parseTIFF(tiffFile) {
  const { stdout, stderr } = await new Promise((resolve, reject) => {
    tiffParser.stdin.write(`tiff-parser "${tiffFile}"`);
    tiffParser.stdout.on('data', (chunk) => resolve(chunk.toString()));
    tiffParser.stderr.on('data', (chunk) => reject(chunk.toString()));
  });

  const bitsPerSample = parseInt(stdout.match(/Bits per sample: (\d+)/)[1]);
  const samplesPerPixel = parseInt(stdout.match(/Samples per pixel: (\d+)/)[1]);

  if (!bitsPerSample || !samplesPerPixel) {
    return Promise.reject(`Unsupported bit depth or number of samples`);
  }

  // Report extra samples
  const extraSamples = parseInt(stderr.match(/Extra samples: (\d+)/)[1]);
  if (extraSamples) {
    console.log(`TIFF file has ${extraSamples} extra samples`);
  }

  return { bitsPerSample, samplesPerPixel };
}

// Load TIFF image and perform reduction
async function processImage(tiffFile) {
  const tiffData = await fs.promises.readFile(tiffFile);
  const parsedData = parseTIFF(tiffFile);

  // Perform reduction on the TIFF data
  try {
    await reduce(tiffData, 0, tiffData.length - 1, (err, result) => {
      if (err) {
        console.error(`Error reducing image:`, err);
      } else {
        console.log(`Reduced image: ${result}`);
      }
    });
  } catch (err) {
    console.error(`Error processing image:`, err);
  }
}

// Main entry point
async function main() {
  // Load and execute modules in the specified order
  Object.keys(config).forEach((module) => {
    try {
      await modules[module].execute();
    } catch (err) {
      console.error(`Error executing module ${module}:`, err);
    }
  });

  // Process TIFF images
  const tiffFiles = fs.readdirSync('images').filter((file) => file.endsWith('.tiff'));
  tiffFiles.forEach((tiffFile) => processImage(path.join('images', tiffFile)));
}

main();
