const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');
const jest = require('@jest/globals');
const chalk = require('chalk');
const moment = require('moment');
const log4js = require('log4js');

const config = {
  // Configuration options
};

const loadModules = (directory) => {
  const modules = [];
  try {
    fs.readdirSync(directory).forEach((file) => {
      if (path.extname(file) === '.js') {
        modules.push(require(path.join(directory, file)));
      }
    });
  } catch (error) {
    console.error(`Error loading modules: ${error.message}`);
  }
  return modules;
};

const runTests = async (modules) => {
  const concurrencyLevel = config.concurrencyLevel || 5;
  const testResults = [];

  for await (const module of loadModules(config.moduleDirectory)) {
    try {
      jest.mock();
      await jest.runAsync(module);
      testResults.push({ moduleName: module.name, result: 'passed' });
    } catch (error) {
      console.error(`Error running tests for ${module.name}: ${error.message}`);
      testResults.push({ moduleName: module.name, result: 'failed' });
    }
  }

  return testResults;
};

const logTestResults = async (testResults) => {
  const logLevel = config.logLevel || 'INFO';
  const logConfig = {
    appenders: [
      {
        type: 'console',
        layout: { pattern: `${logLevel}: %p` },
      },
      {
        type: 'file',
        filename: 'test-results.log',
        category: 'test-results',
      },
    ],
  };
  log4js.configure(logConfig);

  const logger = log4js.getLogger('test-results');
  testResults.forEach((result) => {
    if (result.result === 'failed') {
      logger.error(`Test failed for ${result.moduleName}`);
    } else {
      logger.info(`Test passed for ${result.moduleName}`);
    }
  });
};

const main = async () => {
  try {
    const modules = loadModules(config.moduleDirectory);
    const testResults = await runTests(modules);
    await logTestResults(testResults);
  } catch (error) {
    console.error(`Error running tests: ${error.message}`);
  }
};

main();
