using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Linq;
using System.Threading;

public class DynamicDatabaseConnectionManager
{
    private string _connectionStringTemplate;
    private Dictionary<string, string> _tenantIdentifierMapping;
    private List<SqlConnection> _connectionPool;
    private IConfigurationService _configurationService;

    public DynamicDatabaseConnectionManager(IConfigurationService configurationService)
    {
        _configurationService = configurationService;
        _connectionStringTemplate = null;
        _tenantIdentifierMapping = new Dictionary<string, string>();
        _connectionPool = new List<SqlConnection>();
    }

    public void EstablishConnection(string tenantIdentifier)
    {
        if (!_tenantIdentifierMapping.ContainsKey(tenantIdentifier))
            throw new Exception("Tenant identifier not found");

        string connectionString = GetTenantConnectionString(tenantIdentifier);
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            connection.Open();
            _connectionPool.Add(connection);
        }
    }

    public SqlDataReader ExecuteQuery(string tenantIdentifier, string query)
    {
        EstablishConnection(tenantIdentifier);

        if (_connectionPool.Count == 0)
            throw new Exception("No available connections");

        using (SqlConnection connection = _connectionPool.First())
        {
            try
            {
                SqlCommand command = new SqlCommand(query, connection);
                return command.ExecuteReader();
            }
            catch
            {
                RollbackTransaction();
                throw;
            }
            finally
            {
                connection.Close();
            }
        }
    }

    public void BeginTransaction(string tenantIdentifier)
    {
        EstablishConnection(tenantIdentifier);

        if (_connectionPool.Count == 0)
            throw new Exception("No available connections");

        using (SqlConnection connection = _connectionPool.First())
        {
            try
            {
                connection.Open();
                connection.BeginTransaction();
            }
            catch
            {
                RollbackTransaction();
                throw;
            }
        }
    }

    public void CommitTransaction(string tenantIdentifier)
    {
        EstablishConnection(tenantIdentifier);

        if (_connectionPool.Count == 0)
            throw new Exception("No available connections");

        using (SqlConnection connection = _connectionPool.First())
        {
            try
            {
                connection.Commit();
            }
            catch
            {
                RollbackTransaction();
                throw;
            }
        }
    }

    public void RollbackTransaction(string tenantIdentifier)
    {
        EstablishConnection(tenantIdentifier);

        if (_connectionPool.Count == 0)
            throw new Exception("No available connections");

        using (SqlConnection connection = _connectionPool.First())
        {
            try
            {
                connection.Rollback();
            }
            catch
            {
                // Transaction was already rolled back, do nothing
            }
        }
    }

    public string GetTenantConnectionString(string tenantIdentifier)
    {
        if (!_tenantIdentifierMapping.ContainsKey(tenantIdentifier))
            throw new Exception("Tenant identifier not found");

        return _connectionStringTemplate.Replace("{0}", _tenantIdentifierMapping[tenantIdentifier]);
    }

    public void CloseConnection()
    {
        foreach (SqlConnection connection in _connectionPool)
        {
            try
            {
                connection.Close();
            }
            catch
            {
                // Connection was already closed, do nothing
            }
        }
        _connectionPool.Clear();
    }

    public void UpdateConfiguration(string newConnectionStringTemplate, Dictionary<string, string> newTenantIdentifierMapping)
    {
        _connectionStringTemplate = newConnectionStringTemplate;
        _tenantIdentifierMapping = newTenantIdentifierMapping;

        if (_configurationService != null)
            _configurationService.UpdateConnectionStrings(newConnectionStringTemplate, newTenantIdentifierMapping);
    }

    public override string ToString()
    {
        return $"Active connection: {_connectionPool.Count} connections active for tenants {string.Join(", ", _tenantIdentifierMapping.Keys)}";
    }
}
